const ARENA_QUESTIONS = {"10":{"1":[{"q":"Đối tượng nghiên cứu chính của Vật lí là:","opts":["Các dạng vận động của vật chất và năng lượng.","Sự biến đổi của các chất hoá học tạo thành chất mới.","Cấu tạo và hoạt động của các cơ thể sinh vật sống.","Lịch sử hình thành và phát triển của vỏ Trái Đất."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Đối tượng nghiên cứu của Vật lí gồm các dạng vận động của vật chất (cơ, nhiệt, điện, từ, quang, hạt nhân,...) và năng lượng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circle of Physics branches -->\n      <circle cx=\"250\" cy=\"120\" r=\"45\" fill=\"#1e1b4b\" stroke=\"#6366f1\" stroke-width=\"2.5\"/>\n      <text x=\"225\" y=\"125\" fill=\"#a5b4fc\" font-size=\"14\" font-weight=\"bold\">VẬT LÍ</text>\n      <!-- Branch 1: Mechanics -->\n      <circle cx=\"120\" cy=\"70\" r=\"30\" fill=\"#0c4a6e\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"100\" y=\"75\" fill=\"#7dd3fc\" font-size=\"12\" font-weight=\"bold\">Cơ học</text>\n      <line x1=\"210\" y1=\"100\" x2=\"145\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Branch 2: Thermodynamics -->\n      <circle cx=\"380\" cy=\"70\" r=\"30\" fill=\"#7f1d1d\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"355\" y=\"75\" fill=\"#fca5a5\" font-size=\"12\" font-weight=\"bold\">Nhiệt học</text>\n      <line x1=\"290\" y1=\"100\" x2=\"355\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Branch 3: Electromagnetism -->\n      <circle cx=\"120\" cy=\"170\" r=\"30\" fill=\"#78350f\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <text x=\"95\" y=\"175\" fill=\"#fde68a\" font-size=\"12\" font-weight=\"bold\">Điện - Từ</text>\n      <line x1=\"210\" y1=\"140\" x2=\"145\" y2=\"160\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Branch 4: Optics & Quantum -->\n      <circle cx=\"380\" cy=\"170\" r=\"30\" fill=\"#064e3b\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <text x=\"350\" y=\"175\" fill=\"#a7f3d0\" font-size=\"12\" font-weight=\"bold\">Quang học</text>\n      <line x1=\"290\" y1=\"140\" x2=\"355\" y2=\"160\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Các nhánh nghiên cứu cốt lõi của khoa học Vật lí</text>\n    </svg>"},{"q":"Phương pháp nghiên cứu đặc thù và phổ biến nhất của Vật lí là sự kết hợp chặt chẽ giữa:","opts":["Phương pháp thực nghiệm và phương pháp mô hình (lí thuyết).","Phương pháp phỏng vấn xã hội học và thống kê dân số.","Phương pháp suy diễn thuần tuý không cần kiểm chứng thực tế.","Phương pháp mô tả cảm tính và kinh nghiệm dân gian."],"ans":0,"exp":"• Tiến trình nghiên cứu vật lí luôn kết hợp giữa xây dựng giả thuyết lí thuyết (mô hình hoá) và tiến hành thí nghiệm thực nghiệm để kiểm chứng tính đúng đắn của giả thuyết.","svgGraph":null},{"q":"Thành tựu nào sau đây gắn liền trực tiếp với cuộc Cách mạng công nghiệp lần thứ nhất xuất phát từ các nghiên cứu về nhiệt học?","opts":["Động cơ hơi nước của James Watt.","Máy tính điện tử bán dẫn và Internet.","Trí tuệ nhân tạo (AI) và robot tự hành.","Đèn chiếu sáng sợi đốt và mạng lưới điện xoay chiều."],"ans":0,"exp":"• Các phát minh về nhiệt học và sự hoàn thiện động cơ hơi nước của James Watt đã mở đầu cuộc Cách mạng công nghiệp lần thứ nhất, thay thế lao động thủ công bằng cơ giới hoá.","svgGraph":null},{"q":"Khi tìm hiểu về mục tiêu, vai trò và tiến trình nghiên cứu khoa học của Vật lí, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi kết quả thực nghiệm mâu thuẫn với dự đoán của mô hình lí thuyết thì phải bác bỏ ngay thực nghiệm.","Mục tiêu của môn Vật lí là khám phá các quy luật chi phối sự vận động của vật chất và vũ trụ.","Mô hình vật chất và mô hình toán học là hai dạng mô hình thường được sử dụng trong nghiên cứu vật lí.","Vật lí học là cơ sở nền tảng cho sự phát triển của nhiều ngành công nghệ, kĩ thuật hiện đại."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Mục tiêu cốt lõi của vật lí là tìm ra quy luật tự nhiên.<br>• <b>Ý b [Đúng]:</b> Mô hình vật chất (chất điểm, quả cầu...) và mô hình toán (hàm số, phương trình) là công cụ chủ đạo.<br>• <b>Ý c [Sai]:</b> Thực nghiệm là tiêu chuẩn chân lí tối thượng; nếu thực nghiệm chuẩn xác mà lí thuyết sai thì phải điều chỉnh hoặc xây dựng lại mô hình lí thuyết.<br>• <b>Ý d [Đúng]:</b> Điện tử, bán dẫn, hàng không, viễn thông đều dựa trên vật lí.","svgGraph":null},{"q":"Ghép các bước trong tiến trình nghiên cứu khoa học Vật lí ở Cột A với nội dung tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Bước 1: Quan sát và đặt câu hỏi ➔ Thu thập số liệu đo đạc, kiểm chứng giả thuyết ban đầu","Bước 1: Quan sát và đặt câu hỏi ➔ Đưa ra dự đoán khoa học có cơ sở để giải thích hiện tượng","Bước 2: Đề xuất giả thuyết ➔ Thu thập số liệu đo đạc, kiểm chứng giả thuyết ban đầu","Bước 3: Thiết kế và tiến hành thí nghiệm ➔ Đưa ra dự đoán khoa học có cơ sở để giải thích hiện tượng"],"ans":0,"exp":"• <b>1 - D:</b> Quan sát hiện tượng nảy sinh câu hỏi.<br>• <b>2 - B:</b> Đề xuất giả thuyết khoa học.<br>• <b>3 - A:</b> Làm thí nghiệm thu thập dữ liệu kiểm chứng.<br>• <b>4 - C:</b> Phân tích dữ liệu và kết luận.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Vật lí là ngành khoa học tự nhiên nghiên cứu về  [ ... ]  và các quy luật vận động của nó. Những hiểu biết sâu sắc về điện từ trường đã dẫn đến cuộc cách mạng công nghiệp lần thứ hai với sự ra đời của  [ ... ] . Việc khám phá ra vật lí bán dẫn và lượng tử đã mở đường cho kĩ thuật  [ ... ] . Vật lí cũng đóng góp to lớn vào việc bảo vệ  [ ... ]  thông qua phát triển năng lượng tái tạo.\"</i>","opts":["thế giới tự nhiên — máy phát và động cơ điện","không đổi","xã hội loài người — năng lượng hoá thạch","máy phát và động cơ điện — thế giới tự nhiên"],"ans":0,"exp":"<b>Vai trò của Vật lí:</b><br>• Nghiên cứu thế giới tự nhiên.<br>• Động cơ điện mở ra CMCN lần 2.<br>• Bán dẫn mở ra kỉ nguyên vi điện tử/máy tính.<br>• Năng lượng sạch bảo vệ môi trường.","svgGraph":null},{"q":"Ứng dụng nào sau đây trong y học hiện đại dựa trên thành tựu của Vật lí hạt nhân và sóng điện từ?","opts":["Chụp cắt lớp vi tính (CT) và cộng hưởng từ (MRI).","Kĩ thuật cấy ghép mô nhân tạo từ tế bào gốc.","Kĩ thuật nuôi cấy vi khuẩn tạo kháng sinh.","Phương pháp xoa bóp bấm huyệt cổ truyền."],"ans":0,"exp":"• CT dùng tia X và MRI dùng từ trường mạnh kết hợp sóng radio (hiện tượng cộng hưởng từ hạt nhân) là ứng dụng trực tiếp của vật lí trong y học.","svgGraph":null},{"q":"Thí nghiệm nổi tiếng thả rơi các vật có khối lượng khác nhau từ tháp nghiêng Pisa của nhà bác học nào đã chứng minh mọi vật rơi tự do như nhau nếu không có sức cản không khí?","opts":["Galileo Galilei.","Isaac Newton.","Albert Einstein.","Archimedes."],"ans":0,"exp":"• Galileo Galilei là cha đẻ của phương pháp thực nghiệm trong vật lí; ông đã bác bỏ quan niệm sai lầm cổ xưa của Aristotle cho rằng vật nặng rơi nhanh hơn vật nhẹ.","svgGraph":null},{"q":"Về các mô hình thường dùng trong học tập và nghiên cứu Vật lí, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Mô hình luôn phản ánh đầy đủ 100% mọi chi tiết phức tạp của vật thể thực trong tự nhiên.","Mô hình chất điểm coi một vật có kích thước rất nhỏ so với quãng đường di chuyển của nó.","Tia sáng là một mô hình hình học quy ước biểu diễn đường truyền của ánh sáng.","Mô hình hoá giúp đơn giản hoá các đối tượng nghiên cứu để dễ dàng thiết lập định luật toán học."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Định nghĩa chất điểm: kích thước rất nhỏ so với phạm vi chuyển động.<br>• <b>Ý b [Đúng]:</b> Tia sáng là mô hình đường thẳng có mũi tên chỉ chiều truyền.<br>• <b>Ý c [Sai]:</b> Mô hình chỉ giữ lại những yếu tố bản chất cốt lõi, bỏ qua các chi tiết phụ không đáng kể.<br>• <b>Ý d [Đúng]:</b> Giúp đơn giản hoá để phân tích định lượng.","svgGraph":null},{"q":"Quy tắc nào sau đây là quan trọng nhất để trở thành người học Vật lí có tư duy khoa học?","opts":["Luôn tìm kiếm bằng chứng thực nghiệm và lập luận logic trước khi chấp nhận một kết luận.","Ghi nhớ máy móc các công thức toán học mà không cần hiểu ý nghĩa vật lí của các đại lượng.","Tin tưởng tuyệt đối vào cảm giác trực quan của bản thân mà không cần đo đạc.","Bỏ qua các kết quả thí nghiệm không trùng khớp với suy đoán chủ quan ban đầu."],"ans":0,"exp":"• Tư duy vật lí dựa trên bằng chứng đo đạc thực nghiệm khách quan, phản biện khoa học và suy luận logic có căn cứ.","svgGraph":null}],"2":[{"q":"Biển cảnh báo hình tam giác viền vàng, bên trong có hình tia sét màu đen mang ý nghĩa cảnh báo gì?","opts":["Nguy hiểm về điện giật, điện áp cao.","Khu vực có hoá chất ăn mòn da tay.","Nơi có nguồn bức xạ hạt nhân nguy hiểm.","Khu vực có nhiệt độ cao gây bỏng nhiệt."],"ans":0,"exp":"• Kí hiệu tia sét trong tam giác vàng là biển cảnh báo nguy cơ điện giật, điện áp nguy hiểm trong phòng thí nghiệm.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Warning Triangle -->\n      <polygon points=\"250,30 370,200 130,200\" fill=\"#fbbf24\" stroke=\"#d97706\" stroke-width=\"4\"/>\n      <polygon points=\"250,50 350,190 150,190\" fill=\"#fef08a\"/>\n      <!-- Lightning bolt symbol -->\n      <polygon points=\"255,65 220,125 250,125 235,180 280,115 250,115\" fill=\"#0f172a\"/>\n      <text x=\"175\" y=\"225\" fill=\"#fef08a\" font-size=\"13\" font-weight=\"bold\">NGUY CƠ ĐIỆN CAO ÁP NGUY HIỂM</text>\n    </svg>"},{"q":"Khi tiến hành thí nghiệm với các thiết bị sử dụng nguồn điện lưới xoay chiều 220 V trong phòng thực hành, hành vi nào sau đây là KHÔNG AN TOÀN?","opts":["Cắm phích điện khi tay còn ướt hoặc đứng trên sàn nhà có nước ẩm ướt.","Kiểm tra dây dẫn điện trước khi đóng cầu dao.","Sử dụng bút thử điện để kiểm tra vỏ kim loại của thiết bị.","Ngắt nguồn điện ngay lập tức khi phát hiện mùi khét lạ."],"ans":0,"exp":"• Nước là chất dẫn điện tốt (chứa các ion khoáng); khi tay ướt điện trở cơ thể giảm mạnh, nếu chạm vào nguồn điện sẽ dẫn đến dòng điện lớn chạy qua người gây giật điện tử vong.","svgGraph":null},{"q":"Khi xảy ra sự cố chập điện làm bùng phát đám cháy trong phòng thí nghiệm, thao tác đầu tiên và quan trọng nhất cần làm là:","opts":["Nhanh chóng ngắt cầu dao tổng của phòng thí nghiệm.","Dùng nước lạnh dội thật nhiều vào đám cháy nơi có thiết bị điện.","Hô hoán và chạy thật nhanh ra khỏi phòng mà không ngắt điện.","Dùng chăn len ướt đắp trực tiếp lên ổ cắm đang có điện."],"ans":0,"exp":"• Bước tiên quyết khi chữa cháy điện là phải cắt nguồn điện ngay lập tức để ngăn dòng điện tiếp tục sinh nhiệt và tránh nguy cơ bị điện giật cho người chữa cháy.","svgGraph":null},{"q":"Về các quy tắc an toàn khi sử dụng thiết bị quang học, nhiệt học và điện học trong phòng thực hành, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi đun nóng ống nghiệm bằng đèn cồn, miệng ống nghiệm phải hướng về phía có người để tiện quan sát.","Tuyệt đối không được chiếu chùm tia laser trực tiếp vào mắt người hoặc nhìn trực diện vào nguồn phát tia laser.","Sau khi hoàn thành thí nghiệm nhiệt, cần để các dụng cụ kim loại nguội hẳn rồi mới thu dọn cất vào tủ.","Chỉ được đóng khoá điện của mạch thí nghiệm sau khi giáo viên hoặc nhóm trưởng đã kiểm tra đúng sơ đồ nối dây."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Laser có mật độ năng lượng cao chiếu vào võng mạc gây bỏng mắt và mù loà.<br>• <b>Ý b [Sai]:</b> Tuyệt đối không hướng miệng ống nghiệm về phía người vì hoá chất/chất lỏng sôi có thể bắn ra gây bỏng.<br>• <b>Ý c [Đúng]:</b> Tránh bỏng tay khi thu dọn đồ nhiệt.<br>• <b>Ý d [Đúng]:</b> Kiểm tra mạch trước khi cấp nguồn tránh ngắn mạch cháy thiết bị.","svgGraph":null},{"q":"Ghép biểu tượng an toàn ở Cột A với ý nghĩa cảnh báo tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Biểu tượng ngọn lửa màu đỏ/đen ➔ Chất độc hại gây nguy hiểm chết người nếu nuốt hoặc hít phải","Biểu tượng ngọn lửa màu đỏ/đen ➔ Chất phóng xạ, nguy cơ nhiễm xạ hạt nhân","Biểu tượng bàn tay có giọt hoá chất nhỏ xuống làm rỗ ➔ Chất độc hại gây nguy hiểm chết người nếu nuốt hoặc hít phải","Biểu tượng cánh quạt ba lá màu đen trên nền vàng ➔ Chất phóng xạ, nguy cơ nhiễm xạ hạt nhân"],"ans":0,"exp":"• <b>1 - C:</b> Ngọn lửa: chất dễ cháy.<br>• <b>2 - D:</b> Giọt hoá chất ăn mòn.<br>• <b>3 - B:</b> Quạt 3 cánh: phóng xạ.<br>• <b>4 - A:</b> Đầu lâu: chất kịch độc.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trước khi bắt đầu buổi thực hành, học sinh phải đọc kĩ  [ ... ]  và nắm vững các bước tiến hành. Trong suốt buổi thực hành, học sinh cần đeo  [ ... ]  để bảo vệ mắt khỏi các mảnh vỡ hoặc hoá chất bắn ra. Khi sử dụng nguồn điện một chiều, cần lưu ý cắm đúng  [ ... ]  của thiết bị đo. Khi kết thúc thí nghiệm, phải ngắt nguồn điện, dọn dẹp bàn làm việc và rửa tay bằng  [ ... ] .\"</i>","opts":["tài liệu hướng dẫn — kính bảo hộ","không đổi","cực dương và đất — khăn khô","kính bảo hộ — tài liệu hướng dẫn"],"ans":0,"exp":"<b>Quy chuẩn an toàn phòng thí nghiệm:</b><br>• Đọc kĩ hướng dẫn.<br>• Đeo kính bảo hộ.<br>• Cắm đúng cực tính nguồn DC.<br>• Rửa tay sạch sau khi thực hành.","svgGraph":null},{"q":"Bình chữa cháy khí CO₂ (cacbonic) thường được ưu tiên sử dụng để chữa các đám cháy thiết bị điện tử trong phòng thí nghiệm vì lý do nào sau đây?","opts":["Khí CO₂ không dẫn điện và không làm đọng cặn làm hỏng các linh kiện vi mạch điện tử.","Khí CO₂ có thể cung cấp thêm khí oxy giúp dập tắt lửa nhanh hơn.","Khí CO₂ có trọng lượng nhẹ hơn không khí nên bốc hơi ngay lập tức.","Khí CO₂ có tính ăn mòn kim loại cực kì cao."],"ans":0,"exp":"• Bình CO₂ dập lửa bằng cách làm lạnh đột ngột và cách ly oxy mà không để lại cặn bột hoá chất, đồng thời cách điện an toàn cho thiết bị điện tử.","svgGraph":null},{"q":"Dòng điện xoay chiều có giá trị bao nhiêu chạy qua cơ thể người bắt đầu gây co giật cơ bắp mạnh và nguy hiểm tới tính mạng?","opts":["Khoảng từ 10 mA đến 25 mA trở lên.","Khoảng từ 0,1 mA đến 0,5 mA.","Khoảng trên 100 A.","Dòng điện xoay chiều ở bất kì giá trị nào cũng không gây nguy hiểm."],"ans":0,"exp":"• Dòng điện xoay chiều tần số 50 Hz từ 10 mA bắt đầu gây co giật cơ không buông tay được, từ 25 mA gây khó thở và trên 50 mA có thể gây rung thất tim tử vong.","svgGraph":null},{"q":"Khi xử lí các sự cố hoá chất hoặc mảnh kính vỡ trong phòng thực hành Vật lí, xét tính Đúng / Sai của các phương án sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Dùng tay trần nhặt các mảnh thuỷ tinh vỡ của nhiệt kế bị rơi để dọn dẹp cho nhanh.","Nếu thuỷ ngân trong nhiệt kế bị vỡ rơi ra ngoài, cần báo ngay cho giáo viên và có thể rắc bột lưu huỳnh lên để gom thuỷ ngân.","Nếu bị axit bắn vào mắt, phải rửa ngay dưới vòi nước chảy liên tục ít nhất 15 phút rồi đến cơ sở y tế.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Sai]:</b> Tuyệt đối không dùng tay trần nhặt kính vỡ, phải dùng chổi và găng tay dày.<br>• <b>Ý b [Đúng]:</b> Thuỷ ngân kịch độc bay hơi; lưu huỳnh tác dụng với Hg ở nhiệt độ thường tạo HgS dạng rắn dễ thu gom.<br>• <b>Ý c [Đúng]:</b> Rửa nước nhiều để pha loãng và trôi axit.<br>• <b>Ý d [Sai]:</b> Phải phân loại và đổ vào bình chứa chất thải quy định.","svgGraph":null},{"q":"Vị trí đặt các thiết bị an toàn như bình cứu hoả, hộp sơ cứu y tế trong phòng thực hành Vật lí phải đảm bảo tiêu chuẩn nào?","opts":["Ở vị trí thông thoáng, dễ nhìn thấy, dễ tiếp cận và không có vật cản lối đi.","Khoá kĩ bên trong tủ bảo mật của phòng giáo viên để tránh học sinh nghịch.","Để ở góc khuất phía sau các dãy bàn thí nghiệm nặng.","Cất gọn gàng trên trần nhà hoặc gác xép."],"ans":0,"exp":"• Thiết bị ứng phó khẩn cấp phải luôn đặt ở nơi dễ quan sát và tiếp cận tức thời khi có sự cố hoả hoạn hay tai nạn.","svgGraph":null}],"3":[{"q":"Phép đo trực tiếp một đại lượng vật lí là:","opts":["Phép so sánh trực tiếp đại lượng cần đo với đại lượng cùng loại bằng dụng cụ đo.","Phép xác định đại lượng thông qua một công thức toán học từ các phép đo khác.","Phép ước lượng độ lớn của vật bằng mắt thường không dùng thang chia.","Phép tính tích phân hoặc đạo hàm trên máy tính bỏ túi."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Phép đo trực tiếp là phép so sánh trực tiếp đại lượng cần đo với đại lượng chuẩn cùng loại thông qua thang đo của dụng cụ (ví dụ: đo chiều dài bằng thước kẻ, đo thời gian bằng đồng hồ).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ruler with mm divisions -->\n      <rect x=\"50\" y=\"80\" width=\"400\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <!-- Marks on ruler -->\n      <line x1=\"100\" y1=\"80\" x2=\"100\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"96\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">0</text>\n      <line x1=\"150\" y1=\"80\" x2=\"150\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <line x1=\"200\" y1=\"80\" x2=\"200\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"196\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">1</text>\n      <line x1=\"250\" y1=\"80\" x2=\"250\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <line x1=\"300\" y1=\"80\" x2=\"300\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"296\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">2</text>\n      <line x1=\"350\" y1=\"80\" x2=\"350\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <line x1=\"400\" y1=\"80\" x2=\"400\" y2=\"110\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n      <text x=\"396\" y=\"125\" fill=\"#f8fafc\" font-size=\"12\">3</text>\n      <text x=\"415\" y=\"105\" fill=\"#38bdf8\" font-size=\"12\">cm</text>\n      <!-- Measured Object -->\n      <rect x=\"100\" y=\"45\" width=\"185\" height=\"25\" fill=\"#fbbf24\" stroke=\"#d97706\" stroke-width=\"1.5\" rx=\"3\"/>\n      <text x=\"160\" y=\"62\" fill=\"#0f172a\" font-size=\"12\" font-weight=\"bold\">Vật cần đo (L)</text>\n      <!-- Annotation on measured length -->\n      <line x1=\"285\" y1=\"35\" x2=\"285\" y2=\"78\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"260\" y=\"25\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">L ≈ 1,85 cm ± 0,05 cm</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Minh hoạ phép đo trực tiếp và giới hạn sai số dụng cụ</text>\n    </svg>"},{"q":"Biểu thức viết chuẩn mực kết quả đo của một đại lượng vật lí A là:","opts":["A = Ā ± ΔA.","A = Ā · ΔA.","A = Ā / ΔA.","A = Ā + (ΔA)²."],"ans":0,"exp":"• Kết quả đo được ghi dưới dạng khoảng tin cậy: A = Ā ± ΔA, trong đó Ā là giá trị trung bình của các lần đo, ΔA là sai số tuyệt đối của phép đo.","svgGraph":null},{"q":"Đo chiều dài của một cuốn sách bằng thước có độ chia nhỏ nhất (ĐCNN) là 1 mm. Sai số dụng cụ thông thường được quy ước lấy bằng:","opts":["Một nửa ĐCNN (0,5 mm) hoặc bằng một ĐCNN (1 mm).","Gấp 10 lần độ chia nhỏ nhất (10 mm).","Bằng không vì thước chế tạo rất chính xác.","Một phần mười độ chia nhỏ nhất (0,1 mm)."],"ans":0,"exp":"• Quy ước SGK: Sai số dụng cụ thông thường được lấy bằng một nửa độ chia nhỏ nhất hoặc bằng một độ chia nhỏ nhất trên thang đo.","svgGraph":null},{"q":"Khi tiến hành phân tích sai số trong phép đo thực nghiệm, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Sai số tỉ đối δA được tính bằng thương số giữa giá trị trung bình và sai số tuyệt đối: δA = Ā / ΔA.","Sai số ngẫu nhiên là sai số xuất hiện do các yếu tố ngẫu nhiên từ môi trường hoặc sự phản xạ không đều của mắt người đo.","Sai số hệ thống có tính quy luật lặp lại và có thể loại trừ bằng cách hiệu chỉnh điểm 0 của dụng cụ.","Thực hiện phép đo lặp lại nhiều lần trong cùng điều kiện và lấy giá trị trung bình là cách hiệu quả để giảm sai số ngẫu nhiên."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Định nghĩa sai số ngẫu nhiên.<br>• <b>Ý b [Đúng]:</b> Sai số hệ thống có quy luật (lệch điểm 0) sửa được.<br>• <b>Ý c [Sai]:</b> Sai số tỉ đối δA = (ΔA / Ā) · 100% (tỉ số giữa sai số tuyệt đối trên giá trị trung bình).<br>• <b>Ý d [Đúng]:</b> Đo nhiều lần giúp sai số ngẫu nhiên triệt tiêu dần.","svgGraph":null},{"q":"Ghép công thức tính sai số ở Cột A với loại sai số tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["ΔA = ΔA<sub>tb</sub> + ΔA<sub>đc</sub> ➔ Sai số tuyệt đối của từng lần đo thứ i","ΔA = ΔA<sub>tb</sub> + ΔA<sub>đc</sub> ➔ Giá trị trung bình của n lần đo","δA = (ΔA / Ā) · 100% ➔ Sai số tuyệt đối của từng lần đo thứ i","Ā = (A₁ + A₂ + ... + A<sub>n</sub>) / n ➔ Giá trị trung bình của n lần đo"],"ans":0,"exp":"• <b>1 - C:</b> ΔA = ΔA<sub>tb</sub> + ΔA<sub>đc</sub> là sai số toàn phần.<br>• <b>2 - D:</b> δA = (ΔA/Ā)·100% là sai số tỉ đối.<br>• <b>3 - B:</b> Ā là giá trị trung bình cộng.<br>• <b>4 - A:</b> ΔA<sub>i</sub> = |Ā - A<sub>i</sub>| là sai số tuyệt đối của lần đo thứ i.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi một đại lượng F là tổng hoặc hiệu của hai đại lượng đo trực tiếp (F = X ± Y), thì sai số tuyệt đối của F bằng  [ ... ] . Khi đại lượng F là tích hoặc thương của hai đại lượng (F = X·Y hoặc F = X/Y), thì  [ ... ]  của F bằng tổng các sai số tỉ đối:  [ ... ] . Nếu một đại lượng có số mũ (F = X^n), thì sai số tỉ đối của nó là  [ ... ] .\"</i>","opts":["tổng các sai số tuyệt đối: ΔF = ΔX + ΔY — sai số tỉ đối","không đổi","hiệu các sai số tuyệt đối — δF = δX / δY","sai số tỉ đối — tổng các sai số tuyệt đối: ΔF = ΔX + ΔY"],"ans":0,"exp":"<b>Quy tắc lan truyền sai số:</b><br>• Tổng/hiệu: ΔF = ΔX + ΔY.<br>• Tích/thương: δF = δX + δY.<br>• Luỹ thừa: δ(X^n) = n·δX.","svgGraph":null},{"q":"Đo 5 lần đường kính d của một viên bi thép thu được các giá trị lần lượt là: 6,32 mm; 6,34 mm; 6,33 mm; 6,35 mm; 6,31 mm. Giá trị trung bình d<sub>tb</sub> của đường kính viên bi là:","opts":["6,33 mm.","6,32 mm.","6,34 mm.","6,35 mm."],"ans":0,"exp":"• <b>Giá trị trung bình:</b><br>d<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">6,32 + 6,34 + 6,33 + 6,35 + 6,31</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">31,65</span><span class=\"denominator\">5</span></span> = 6,33 mm.","svgGraph":null},{"q":"Một học sinh đo khối lượng m và thể tích V của một khối đồng thu được: m = (890 ± 5) g và V = (100 ± 2) cm³. Khối lượng riêng của đồng tính được từ công thức ρ = m/V có sai số tỉ đối δρ là:","opts":["2,56%.","0,56%.","2,00%.","1,44%."],"ans":0,"exp":"• <b>Bước 1: Tính sai số tỉ đối của m:</b> δm = <span class=\"fraction\"><span class=\"numerator\">5</span><span class=\"denominator\">890</span></span> · 100% ≈ 0,56%.<br>• <b>Bước 2: Tính sai số tỉ đối của V:</b> δV = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">100</span></span> · 100% = 2,00%.<br>• <b>Bước 3: Sai số tỉ đối của thương ρ = m/V:</b><br>δρ = δm + δV = 0,56% + 2,00% = 2,56%.","svgGraph":null},{"q":"Khi viết và làm tròn chữ số có nghĩa trong kết quả đo, xét tính Đúng / Sai của các quy tắc sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Cách viết kết quả L = (25,4 ± 0,25) cm là cách viết đã chuẩn hoá hoàn hảo về hàng thập phân.","Số 0,00450 có 3 chữ số có nghĩa (các chữ số: 4, 5, 0 ở cuối).","Sai số tuyệt đối thường được làm tròn đến một hoặc tối đa hai chữ số có nghĩa.","Chữ số có nghĩa cuối cùng của giá trị trung bình phải ở cùng bậc thập phân với chữ số có nghĩa của sai số tuyệt đối."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Các số 0 đứng trước dấu phẩy không tính, số 4, 5 và số 0 tận cùng có nghĩa ⇒ 3 chữ số có nghĩa.<br>• <b>Ý b [Đúng]:</b> Quy ước làm tròn sai số tuyệt đối tới 1 hoặc 2 chữ số có nghĩa.<br>• <b>Ý c [Đúng]:</b> Phải cùng bậc thập phân tin cậy.<br>• <b>Ý d [Sai]:</b> Sai số có 2 chữ số thập phân (0,25) thì giá trị trung bình phải viết tương ứng 2 chữ số thập phân: (25,40 ± 0,25) cm.","svgGraph":null},{"q":"Thời gian rơi tự do của một vật đo được là t = (0,405 ± 0,008) s. Sai số tỉ đối của phép đo thời gian này xấp xỉ bằng:","opts":["1,98%.","0,80%.","3,96%.","0,02%."],"ans":0,"exp":"• <b>Công thức sai số tỉ đối:</b> δt = <span class=\"fraction\"><span class=\"numerator\">Δt</span><span class=\"denominator\">t<sub>tb</sub></span></span> · 100%<br>• <b>Thay số:</b> δt = <span class=\"fraction\"><span class=\"numerator\">0,008</span><span class=\"denominator\">0,405</span></span> · 100% ≈ 1,98%.","svgGraph":null}],"4":[{"q":"Độ dịch chuyển là một đại lượng vectơ nối từ:","opts":["Vị trí đầu đến vị trí cuối của chuyển động.","Gốc toạ độ đến vị trí ban đầu của vật.","Vị trí cuối cùng quay ngược trở lại gốc toạ độ.","Tâm Trái Đất đến trọng tâm của vật."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Độ dịch chuyển là một đại lượng vectơ có gốc tại vị trí ban đầu, ngọn tại vị trí kết thúc của chuyển động, đặc trưng cho độ biến thiên vị trí của vật.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr4\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Start point A and End point B -->\n      <circle cx=\"100\" cy=\"150\" r=\"7\" fill=\"#ef4444\"/>\n      <text x=\"85\" y=\"175\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">Điểm A</text>\n      <circle cx=\"400\" cy=\"80\" r=\"7\" fill=\"#34d399\"/>\n      <text x=\"405\" y=\"105\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">Điểm B</text>\n      <!-- Displacement vector d (straight arrow) -->\n      <line x1=\"100\" y1=\"150\" x2=\"395\" y2=\"82\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr4)\"/>\n      <text x=\"235\" y=\"105\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Vectơ độ dịch chuyển d</text>\n      <!-- Distance path s (curved yellow line) -->\n      <path d=\"M 100,150 Q 180,40 280,180 T 400,80\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <text x=\"210\" y=\"55\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Quãng đường s (quỹ đạo thực)</text>\n      <text x=\"145\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Phân biệt độ dịch chuyển d và quãng đường s</text>\n    </svg>"},{"q":"Khi nào độ lớn của độ dịch chuyển d bằng với quãng đường đi được s của vật?","opts":["Khi vật chuyển động thẳng và không đổi chiều chuyển động.","Khi vật chuyển động tròn đều trọn vẹn một vòng.","Khi vật chuyển động thẳng đi rồi quay lại điểm xuất phát.","Trong mọi trường hợp chuyển động bất kì."],"ans":0,"exp":"• Độ lớn của độ dịch chuyển chỉ bằng quãng đường đi được khi vật chuyển động trên đường thẳng và không đổi chiều (d = s). Nếu đổi chiều hoặc đi đường cong thì d < s.","svgGraph":null},{"q":"Một người đi bộ từ điểm A đến điểm B cách nhau 400 m về phía Đông, sau đó rẽ sang hướng Bắc đi tiếp 300 m đến điểm C. Độ lớn của độ dịch chuyển tổng hợp của người đó từ A đến C là:","opts":["500 m.","700 m.","100 m.","1200 m."],"ans":0,"exp":"• Hai hướng Đông và Bắc vuông góc với nhau (tam giác vuông ABC tại B).<br>• <b>Độ lớn độ dịch chuyển AC:</b> d = √(AB² + BC²) = √(400² + 300²) = √(160000 + 90000) = 500 m.","svgGraph":null},{"q":"Một vận động viên bơi lội xuất phát từ đầu bể bơi, bơi hết chiều dài bể 50 m rồi quay đầu bơi ngược trở lại về đúng vị trí xuất phát. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ dịch chuyển là đại lượng vô hướng luôn luôn bằng giá trị của quãng đường.","Tổng quãng đường mà vận động viên đã bơi được là s = 100 m.","Độ dịch chuyển tổng hợp của vận động viên sau cả hành trình bằng d = 0 m.","Quãng đường đi được là một đại lượng vô hướng không âm (s ≥ 0)."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> s = 50 + 50 = 100 m.<br>• <b>Ý b [Đúng]:</b> Điểm đầu trùng điểm cuối nên vectơ độ dịch chuyển d = 0.<br>• <b>Ý c [Đúng]:</b> Quãng đường là chiều dài quỹ đạo nên s ≥ 0.<br>• <b>Ý d [Sai]:</b> Độ dịch chuyển là đại lượng vectơ có hướng, có thể dương, âm hoặc bằng 0.","svgGraph":null},{"q":"Ghép tình huống chuyển động ở Cột A với mối quan hệ giữa độ dịch chuyển d và quãng đường s ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vật đi thẳng từ A đến B không đổi chiều ➔ s = 2πR; d = 0","Vật đi thẳng từ A đến B không đổi chiều ➔ s = 0; d = 0","Vật đi hết một vòng tròn bán kính R rồi về điểm xuất phát ➔ s = 2πR; d = 0","Vật đi thẳng 6 m rồi quay ngược lại 2 m ➔ s = 0; d = 0"],"ans":0,"exp":"• <b>1 - C:</b> Thẳng không đổi chiều: d = s.<br>• <b>2 - A:</b> Vòng tròn kín: s = 2πR, d = 0.<br>• <b>3 - D:</b> Đi 6 lùi 2: s = 8m, d = 4m.<br>• <b>4 - B:</b> Đứng yên: s = 0, d = 0.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Quãng đường đi được là đại lượng  [ ... ]  cho biết chiều dài thực tế mà vật vạch ra trong quá trình chuyển động. Độ dịch chuyển là một đại lượng  [ ... ]  có hướng cho biết sự thay đổi vị trí của vật trong không gian. Độ lớn độ dịch chuyển luôn  [ ... ]  quãng đường đi được: d ≤ s. Dấu bằng xảy ra khi vật chuyển động thẳng  [ ... ] .\"</i>","opts":["vô hướng — vectơ","không đổi","có hướng — lớn hơn","vectơ — vô hướng"],"ans":0,"exp":"<b>So sánh s và d:</b><br>• s: đại lượng vô hướng ≥ 0.<br>• d: đại lượng vectơ.<br>• d ≤ s luôn đúng.<br>• d = s khi chuyển động thẳng 1 chiều.","svgGraph":null},{"q":"Một ô tô chạy trên đường tròn bán kính R = 100 m. Sau khi đi được nửa vòng tròn, quãng đường s và độ lớn độ dịch chuyển d của ô tô lần lượt là (lấy π ≈ 3,14):","opts":["s = 314 m; d = 200 m.","s = 628 m; d = 0 m.","s = 200 m; d = 314 m.","s = 314 m; d = 0 m."],"ans":0,"exp":"• <b>Quãng đường nửa đường tròn:</b> s = π·R = 3,14 · 100 = 314 m.<br>• <b>Độ dịch chuyển:</b> Nối hai đầu đường kính: d = 2·R = 2 · 100 = 200 m.","svgGraph":null},{"q":"Trên trục toạ độ Ox, một chất điểm ban đầu ở vị trí x₁ = -5 m chuyển động đến vị trí x₂ = +15 m. Độ dịch chuyển Δx của chất điểm trên trục Ox là:","opts":["+20 m.","+10 m.","-20 m.","-10 m."],"ans":0,"exp":"• <b>Công thức độ dịch chuyển toạ độ:</b> Δx = x₂ - x₁ = 15 - (-5) = +20 m (hướng theo chiều dương trục toạ độ).","svgGraph":null},{"q":"Một chất điểm chuyển động dọc theo trục Ox có phương trình toạ độ x = 4t - 2 (m, s). Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Vì toạ độ ban đầu âm nên quãng đường chất điểm đi được từ 1s đến 3s bị âm.","Toạ độ ban đầu của chất điểm tại thời điểm t = 0 là x₀ = -2 m.","Tại thời điểm t = 3 s, chất điểm có toạ độ x = 10 m.","Độ dịch chuyển của chất điểm từ thời điểm t = 1 s đến t = 3 s là Δx = 8 m."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> t = 0 ⇒ x₀ = 4·0 - 2 = -2 m.<br>• <b>Ý b [Đúng]:</b> t = 3 s ⇒ x = 4·3 - 2 = 10 m.<br>• <b>Ý c [Đúng]:</b> x(1) = 2 m, x(3) = 10 m ⇒ Δx = 10 - 2 = 8 m.<br>• <b>Ý d [Sai]:</b> Quãng đường đi được s = |Δx| = 8 m luôn là số dương.","svgGraph":null},{"q":"Một flycam bay từ điểm A lên thẳng đứng 40 m, sau đó bay ngang theo phương nằm ngang 30 m đến điểm B. Khoảng cách không gian giữa điểm xuất phát A và vị trí hiện tại B là:","opts":["50 m.","70 m.","10 m.","1200 m."],"ans":0,"exp":"• Khoảng cách không gian chính là độ lớn độ dịch chuyển nối điểm đầu A và điểm cuối B: d = √(40² + 30²) = 50 m.","svgGraph":null}],"5":[{"q":"Tốc độ trung bình v<sub>tb</sub> của một vật được xác định bằng:","opts":["Thương số giữa quãng đường đi được và khoảng thời gian để đi hết quãng đường đó (v<sub>tb</sub> = s/t).","Thương số giữa độ dịch chuyển và khoảng thời gian thực hiện độ dịch chuyển đó (v = d/t).","Tích của quãng đường đi được với khoảng thời gian chuyển động.","Đạo hàm của vận tốc tức thời theo thời gian."],"ans":0,"exp":"• <b>Định nghĩa tốc độ trung bình:</b> v<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">s</span><span class=\"denominator\">t</span></span>, là đại lượng vô hướng đặc trưng cho mức độ chuyển động nhanh hay chậm của vật trên suốt quãng đường s.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr5\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Speedometer Circle -->\n      <circle cx=\"250\" cy=\"130\" r=\"85\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Dial ticks -->\n      <path d=\"M 190,130 A 60 60 0 0 1 310,130\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"4\" stroke-dasharray=\"3,6\"/>\n      <!-- Needle indicating speed -->\n      <line x1=\"250\" y1=\"130\" x2=\"285\" y2=\"80\" stroke=\"#f43f5e\" stroke-width=\"3.5\" marker-end=\"url(#arr5)\"/>\n      <circle cx=\"250\" cy=\"130\" r=\"6\" fill=\"#f8fafc\"/>\n      <!-- Speed digital value -->\n      <text x=\"235\" y=\"165\" fill=\"#38bdf8\" font-size=\"18\" font-weight=\"bold\">60</text>\n      <text x=\"232\" y=\"182\" fill=\"#94a3b8\" font-size=\"11\">km/h</text>\n      <!-- Label -->\n      <text x=\"135\" y=\"35\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">Tốc kế đo tốc độ tức thời của phương tiện</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Tốc kế hiển thị giá trị độ lớn vận tốc tại thời điểm quan sát</text>\n    </svg>"},{"q":"Vận tốc trung bình là đại lượng vectơ được tính bằng công thức:","opts":["v = d / Δt (với d là vectơ độ dịch chuyển trong khoảng thời gian Δt).","v = s / Δt (với s là quãng đường đi được).","v = a · t.","v = d · Δt."],"ans":0,"exp":"• <b>Định nghĩa vận tốc trung bình:</b> v = <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">Δt</span></span>, là đại lượng vectơ có cùng hướng với vectơ độ dịch chuyển d, đặc trưng cho cả tốc độ và hướng chuyển động của vật.","svgGraph":null},{"q":"Một xe máy đi từ A đến B dài 60 km hết thời gian 1,5 giờ, sau đó từ B quay trở về A hết thời gian 2,5 giờ. Tốc độ trung bình của xe máy trong toàn bộ chuyến đi cả đi lẫn về là:","opts":["30 km/h.","0 km/h.","40 km/h.","24 km/h."],"ans":0,"exp":"• <b>Tổng quãng đường cả đi lẫn về:</b> s = 60 + 60 = 120 km.<br>• <b>Tổng thời gian:</b> t = 1,5 + 2,5 = 4,0 h.<br>• <b>Tốc độ trung bình:</b> v<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">s</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">120</span><span class=\"denominator\">4</span></span> = 30 km/h. (Lưu ý: vận tốc trung bình bằng 0 vì d = 0).","svgGraph":null},{"q":"Về sự khác nhau giữa tốc độ và vận tốc, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tốc kế trên ô tô chỉ giá trị của vận tốc tức thời có kèm theo hướng chuyển động của xe.","Tốc độ là đại lượng vô hướng luôn không âm, trong khi vận tốc là đại lượng vectơ có thể có toạ độ dương, âm hoặc bằng 0.","Khi vật chuyển động thẳng đều theo chiều dương của trục toạ độ thì tốc độ và độ lớn của vận tốc bằng nhau.","Nếu một vật chuyển động quay trở về điểm xuất phát thì vận tốc trung bình của nó bằng không."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tốc độ vô hướng v ≥ 0; vận tốc vectơ có hướng.<br>• <b>Ý b [Sai]:</b> Tốc kế chỉ đo độ lớn của vận tốc tức thời (tốc độ tức thời), không hiển thị phương hướng.<br>• <b>Ý c [Đúng]:</b> Đi thẳng không đổi chiều thì v<sub>tb</sub> = v.<br>• <b>Ý d [Đúng]:</b> Về gốc ⇒ d = 0 ⇒ v<sub>tb</sub> = d/t = 0.","svgGraph":null},{"q":"Ghép các công thức tính tốc độ và vận tốc ở Cột A với ý nghĩa tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["v = s / t ➔ Công thức cộng vận tốc trong chuyển động tương đối","v = s / t ➔ Tốc độ trung bình (đại lượng vô hướng)","v = d / t ➔ Công thức cộng vận tốc trong chuyển động tương đối","v₁₃ = v₁₂ + v₂₃ ➔ Tốc độ trung bình (đại lượng vô hướng)"],"ans":0,"exp":"• <b>1 - B:</b> s/t là tốc độ trung bình.<br>• <b>2 - D:</b> d/t là vận tốc trung bình.<br>• <b>3 - A:</b> v₁₃ = v₁₂ + v₂₃ là công thức cộng vận tốc.<br>• <b>4 - C:</b> 1 m/s = 3,6 km/h.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi một chiếc thuyền chuyển động trên dòng sông đang chảy, vận tốc của thuyền đối với bờ sông (vận tốc tuyệt đối) bằng  [ ... ]  giữa vận tốc của thuyền đối với nước (vận tốc tương đối) và vận tốc của dòng nước đối với bờ (vận tốc kéo theo). Khi thuyền chạy xuôi dòng, độ lớn vận tốc đối với bờ bằng  [ ... ] . Khi thuyền chạy ngược dòng, độ lớn vận tốc bằng  [ ... ] . Nếu thuyền chèo vuông góc dòng nước, độ lớn vận tốc tính theo  [ ... ] .\"</i>","opts":["tổng vectơ: v₁₃ = v₁₂ + v₂₃ — v₁₂ + v₂₃","không đổi","hiệu đại số — tích đại số","v₁₂ + v₂₃ — tổng vectơ: v₁₃ = v₁₂ + v₂₃"],"ans":0,"exp":"<b>Công thức cộng vận tốc:</b><br>• v₁₃ = v₁₂ + v₂₃.<br>• Xuôi dòng (cùng chiều): v = v₁₂ + v₂₃.<br>• Ngược dòng (ngược chiều): v = v₁₂ - v₂₃.<br>• Vuông góc: v = √(v₁₂² + v₂₃²).","svgGraph":null},{"q":"Một canô đi xuôi dòng nước từ bến A đến bến B với vận tốc 24 km/h đối với bờ. Biết vận tốc của dòng nước chảy là 4 km/h. Vận tốc của canô đối với dòng nước là:","opts":["20 km/h.","28 km/h.","16 km/h.","6 km/h."],"ans":0,"exp":"• Khi xuôi dòng: v<sub>xuôi</sub>ôi = v<sub>thuyền</sub>ền/nước + v<sub>nước</sub>ước/bờ.<br>• Thay số: 24 = v<sub>thuyền</sub>ền/nước + 4 ⇒ v<sub>thuyền</sub>ền/nước = 24 - 4 = 20 km/h.","svgGraph":null},{"q":"Một chiếc ca nô chạy ngược dòng trên đoạn sông AB mất 3 giờ. Biết khoảng cách AB = 45 km và vận tốc của canô trong nước yên lặng là 18 km/h. Vận tốc chảy của dòng nước là:","opts":["3 km/h.","15 km/h.","5 km/h.","2 km/h."],"ans":0,"exp":"• <b>Vận tốc của canô đối với bờ khi ngược dòng:</b> v<sub>ngược</sub>ược = <span class=\"fraction\"><span class=\"numerator\">45</span><span class=\"denominator\">3</span></span> = 15 km/h.<br>• <b>Công thức ngược dòng:</b> v<sub>ngược</sub>ược = v<sub>thuyền</sub>ền/nước - v<sub>nước</sub>ước/bờ ⇒ 15 = 18 - v<sub>nước</sub>ước ⇒ v<sub>nước</sub>ước = 3 km/h.","svgGraph":null},{"q":"Hai xe ô tô A và B cùng chuyển động thẳng đều trên cùng một đoạn đường thẳng. Xe A chạy với tốc độ 60 km/h, xe B chạy với tốc độ 40 km/h. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Người ngồi trên xe A luôn thấy xe B chuyển động với tốc độ 40 km/h.","Nếu hai xe chuyển động cùng chiều thì vận tốc tương đối của xe A đối với xe B có độ lớn là 20 km/h.","Nếu hai xe chuyển động ngược chiều hướng vào nhau thì vận tốc tương đối giữa hai xe là 100 km/h.","Khoảng cách giữa hai xe khi chuyển động ngược chiều sẽ rút ngắn nhanh hơn so với khi chuyển động cùng chiều."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Cùng chiều: v<sub>AB</sub> = 60 - 40 = 20 km/h.<br>• <b>Ý b [Đúng]:</b> Ngược chiều: v<sub>AB</sub> = 60 + 40 = 100 km/h.<br>• <b>Ý c [Đúng]:</b> Tốc độ tương đối 100 km/h > 20 km/h nên khoảng cách rút ngắn rất nhanh.<br>• <b>Ý d [Sai]:</b> Người trên xe A chọn A làm mốc sẽ thấy B chuyển động với vận tốc tương đối v<sub>BA</sub>.","svgGraph":null},{"q":"Quy đổi vận tốc v = 72 km/h sang đơn vị m/s trong hệ SI thu được kết quả là:","opts":["20 m/s.","25 m/s.","15 m/s.","30 m/s."],"ans":0,"exp":"• <b>Quy tắc quy đổi:</b> v(m/s) = <span class=\"fraction\"><span class=\"numerator\">v(km/h)</span><span class=\"denominator\">3,6</span></span> = <span class=\"fraction\"><span class=\"numerator\">72</span><span class=\"denominator\">3,6</span></span> = 20 m/s.","svgGraph":null}],"6":[{"q":"Trong thí nghiệm đo tốc độ của xe đồ chơi chuyển động trên máng đỡ bằng đồng hồ bấm giây, tốc độ được xác định theo nguyên tắc nào?","opts":["Đo quãng đường s bằng thước đo và đo thời gian chuyển động t bằng đồng hồ bấm giây, rồi tính v = s/t.","Đọc trực tiếp giá trị vận tốc hiển thị trên màn hình của thước đo điện tử.","Dùng lực kế đo lực đẩy tác dụng lên xe rồi nhân với gia tốc trọng trường.","Đo thể tích và khối lượng của xe rồi tra bảng số liệu tiêu chuẩn."],"ans":0,"exp":"• Nguyên tắc đo gián tiếp tốc độ chuyển động: Đo trực tiếp quãng đường s bằng thước và thời gian t bằng đồng hồ, sau đó tính v qua công thức v = s/t.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr6\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Inclined track -->\n      <line x1=\"60\" y1=\"90\" x2=\"440\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"4\"/>\n      <!-- Photogate 1 at A -->\n      <rect x=\"140\" y=\"80\" width=\"16\" height=\"35\" fill=\"#f43f5e\" rx=\"2\"/>\n      <text x=\"130\" y=\"70\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Cổng quang 1</text>\n      <!-- Photogate 2 at B -->\n      <rect x=\"340\" y=\"115\" width=\"16\" height=\"35\" fill=\"#f43f5e\" rx=\"2\"/>\n      <text x=\"330\" y=\"105\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Cổng quang 2</text>\n      <!-- Toy car on track -->\n      <rect x=\"180\" y=\"90\" width=\"45\" height=\"22\" fill=\"#fbbf24\" stroke=\"#d97706\" rx=\"4\"/>\n      <circle cx=\"192\" cy=\"115\" r=\"5\" fill=\"#475569\"/>\n      <circle cx=\"213\" cy=\"120\" r=\"5\" fill=\"#475569\"/>\n      <line x1=\"225\" y1=\"100\" x2=\"260\" y2=\"106\" stroke=\"#34d399\" stroke-width=\"2\" marker-end=\"url(#arr6)\"/>\n      <!-- Digital timer connection lines -->\n      <rect x=\"200\" y=\"175\" width=\"100\" height=\"40\" fill=\"#1e293b\" stroke=\"#64748b\" rx=\"5\"/>\n      <text x=\"215\" y=\"200\" fill=\"#34d399\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">0.428 s</text>\n      <line x1=\"148\" y1=\"115\" x2=\"220\" y2=\"175\" stroke=\"#f43f5e\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n      <line x1=\"348\" y1=\"150\" x2=\"280\" y2=\"175\" stroke=\"#f43f5e\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Bộ thí nghiệm đo tốc độ bằng cổng quang điện và đồng hồ hiện số</text>\n    </svg>"},{"q":"Ưu điểm vượt trội của việc sử dụng cổng quang điện kết hợp với đồng hồ đo thời gian hiện số so với đồng hồ bấm giây thủ công bằng tay là:","opts":["Loại bỏ hoàn toàn sai số do phản xạ bấm tay của con người, đo thời gian chính xác tới phần nghìn giây.","Không cần đo quãng đường di chuyển mà đồng hồ tự tính ra vận tốc.","Thiết bị tự động khử được ma sát giữa bánh xe và mặt đường ray.","Giúp xe chuyển động nhanh hơn với gia tốc lớn hơn."],"ans":0,"exp":"• Cổng quang điện sử dụng chùm tia hồng ngoại bị ngắt mở tự động kích hoạt mạch đếm điện tử, loại bỏ thời gian trễ do phản xạ tay người (khoảng 0,1s - 0,2s).","svgGraph":null},{"q":"Khi đo tốc độ tức thời của một xe có gắn tấm chắn sáng rộng d = 2 cm đi qua một cổng quang điện duy nhất, đồng hồ hiện số đo được thời gian chắn sáng là Δt = 0,05 s. Tốc độ tức thời của xe khi qua cổng là:","opts":["0,4 m/s.","0,1 m/s.","2,5 m/s.","0,001 m/s."],"ans":0,"exp":"• <b>Đổi đơn vị:</b> d = 2 cm = 0,02 m.<br>• <b>Tốc độ tức thời:</b> v = <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">Δt</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,02</span><span class=\"denominator\">0,05</span></span> = 0,4 m/s.","svgGraph":null},{"q":"Trong bài thực hành đo tốc độ chuyển động trên máng đỡ nghiêng, xét tính Đúng / Sai của các thao tác kĩ thuật sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Đồng hồ hiện số phải được cắm vào nguồn điện xoay chiều 220 V trực tiếp mà không qua bộ đổi nguồn.","Máng trượt cần được đặt vững chắc, điều chỉnh thăng bằng ngang hoặc có độ dốc ổn định trong suốt các lần đo.","Khi đo thời gian bằng cổng quang điện, vị trí tấm chắn sáng trên xe phải đủ cao để cắt đúng chùm tia hồng ngoại.","Để giảm thiểu sai số, mỗi phép đo cần được lặp lại ít nhất 3 đến 5 lần và lấy giá trị trung bình."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Độ dốc ổn định để gia tốc không đổi.<br>• <b>Ý b [Đúng]:</b> Tấm chắn sáng phải chắn ngang qua mắt quang điện.<br>• <b>Ý c [Đúng]:</b> Đo lặp lại nhiều lần giảm sai số ngẫu nhiên.<br>• <b>Ý d [Sai]:</b> Đồng hồ hiện số và cổng quang dùng nguồn điện hạ áp một chiều (thường 6V - 12V qua adapter) an toàn.","svgGraph":null},{"q":"Ghép các thiết bị trong bộ thực hành đo tốc độ ở Cột A với chức năng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Cổng quang điện (Photogate) ➔ Đo thời gian xe đi giữa 2 cổng hoặc thời gian tấm chắn đi qua cổng","Cổng quang điện (Photogate) ➔ Phát và thu chùm tia hồng ngoại nhận biết thời điểm xe đi qua","Đồng hồ đo thời gian hiện số ➔ Đo thời gian xe đi giữa 2 cổng hoặc thời gian tấm chắn đi qua cổng","Thước thẳng chia vạch trên máng ➔ Phát và thu chùm tia hồng ngoại nhận biết thời điểm xe đi qua"],"ans":0,"exp":"• <b>1 - B:</b> Cổng quang phát/thu tia hồng ngoại.<br>• <b>2 - A:</b> Đồng hồ hiển thị thời gian chính xác.<br>• <b>3 - D:</b> Thước thẳng đo khoảng cách s.<br>• <b>4 - C:</b> Tấm chắn sáng rộng d dùng đo v tức thời.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Bố trí hai cổng quang điện tại hai vị trí A và B trên máng trượt cách nhau một khoảng s. Cài đặt đồng hồ hiện số ở chế độ đo  [ ... ]  giữa hai cổng A và B. Thả cho xe chuyển động từ đỉnh máng, khi xe đi qua cổng 1 đồng hồ  [ ... ] , khi xe đi qua cổng 2 đồng hồ  [ ... ] . Tốc độ trung bình của xe trên đoạn AB tính theo công thức  [ ... ] .\"</i>","opts":["khoảng thời gian t — bắt đầu đếm thời gian","không đổi","tốc độ tức thời — v = s · t","bắt đầu đếm thời gian — khoảng thời gian t"],"ans":0,"exp":"<b>Quy trình đo thời gian giữa 2 cổng quang:</b><br>• Cài đặt chế độ đo khoảng thời gian A - B.<br>• Qua cổng 1 bắt đầu đếm.<br>• Qua cổng 2 ngắt đếm.<br>• Tính v = s/t.","svgGraph":null},{"q":"Kết quả đo quãng đường và thời gian của một chuyển động là: s = (0,600 ± 0,002) m và t = (1,50 ± 0,03) s. Sai số tỉ đối của phép đo tốc độ v = s/t là:","opts":["2,33%.","0,33%.","2,00%.","1,67%."],"ans":0,"exp":"• <b>Sai số tỉ đối của s:</b> δs = <span class=\"fraction\"><span class=\"numerator\">0,002</span><span class=\"denominator\">0,600</span></span> · 100% ≈ 0,33%.<br>• <b>Sai số tỉ đối của t:</b> δt = <span class=\"fraction\"><span class=\"numerator\">0,03</span><span class=\"denominator\">1,50</span></span> · 100% = 2,00%.<br>• <b>Sai số tỉ đối của v = s/t:</b> δv = δs + δt = 0,33% + 2,00% = 2,33%.","svgGraph":null},{"q":"Để hạn chế ảnh hưởng của lực ma sát giữa xe và máng dẫn trong bài thực hành đo tốc độ, giải pháp kĩ thuật nào sau đây là phù hợp nhất?","opts":["Sử dụng đệm khí (Air track) nâng xe lơ lửng trên luồng không khí nén mỏng.","Tăng thêm thật nhiều tải trọng nặng đè lên xe.","Bôi keo dính vào các bánh xe của xe chuyển động.","Chế tạo máng trượt có bề mặt thật gồ ghề nhám ráp."],"ans":0,"exp":"• Máng đệm không khí (Air track) phun các tia khí nén nâng xe trôi lơ lửng không tiếp xúc trực tiếp bề mặt máng, giúp triệt tiêu ma sát gần như hoàn toàn.","svgGraph":null},{"q":"Trong quá trình ghi nhận số liệu thực nghiệm đo tốc độ của xe đồ chơi, nhóm học sinh thu được bảng thời gian qua 4 lần đo: t₁ = 0,81 s; t₂ = 0,83 s; t₃ = 0,82 s; t₄ = 0,82 s trên quãng đường s = 41 cm. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tốc độ trung bình này phản ánh chính xác tốc độ của xe tại mọi điểm trên máng nghiêng.","Thời gian trung bình của chuyển động là t<sub>tb</sub> = 0,82 s.","Sai số ngẫu nhiên trung bình của thời gian đo được là Δt<sub>ng</sub> = 0,005 s.","Tốc độ trung bình tính được của xe là v<sub>tb</sub> = 0,5 m/s."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> t<sub>tb</sub> = (0,81 + 0,83 + 0,82 + 0,82)/4 = 0,82 s.<br>• <b>Ý b [Đúng]:</b> Độ lệch: |0,82-0,81|=0,01; |0,82-0,83|=0,01; 0; 0 ⇒ Δt<sub>tb</sub> = 0,02/4 = 0,005 s.<br>• <b>Ý c [Đúng]:</b> v = 0,41 / 0,82 = 0,5 m/s.<br>• <b>Ý d [Sai]:</b> Xe xuống dốc là chuyển động nhanh dần đều, tốc độ tại mỗi điểm khác nhau, tốc độ trung bình chỉ mang tính đại diện cho cả đoạn.","svgGraph":null},{"q":"Thiết bị 'súng bắn tốc độ' dùng trong kiểm tra an toàn giao thông của cảnh sát giao thông ứng dụng hiện tượng vật lí nào để đo tốc độ phương tiện?","opts":["Hiệu ứng Doppler của sóng vô tuyến hoặc chùm tia laser phản xạ từ xe đang chạy.","Cảm biến áp suất ngầm dưới lòng đường đo tải trọng xe.","Đo nhiệt lượng toả ra từ ống xả khí của động cơ xe.","Sóng siêu âm tạo cộng hưởng làm rung kính chắn gió của xe."],"ans":0,"exp":"• Súng bắn tốc độ phát sóng điện từ tới xe chuyển động; sóng phản xạ bị thay đổi tần số do hiệu ứng Doppler (hoặc đo thời gian truyền của chùm laser Lidar) từ đó máy tính tính tức thời tốc độ của xe.","svgGraph":null}],"7":[{"q":"Hệ số góc (độ dốc) của đường biểu diễn trên đồ thị độ dịch chuyển – thời gian (d – t) của một vật chuyển động thẳng đặc trưng cho:","opts":["Vận tốc chuyển động của vật.","Gia tốc chuyển động của vật.","Lực kéo tác dụng vào vật.","Công cơ học mà vật sinh ra."],"ans":0,"exp":"• <b>Ý nghĩa hệ số góc:</b> Độ dốc = <span class=\"fraction\"><span class=\"numerator\">Δd</span><span class=\"denominator\">Δt</span></span> = v. Độ dốc của đường d - t cho biết vận tốc của chuyển động. Độ dốc dương nghĩa là vật chuyển động theo chiều dương, độ dốc âm là theo chiều âm, nằm ngang là đứng yên.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr7\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes d and t -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr7)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr7)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">t (s)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">d (m)</text>\n      <!-- Line 1: Positive slope (moving forward) -->\n      <line x1=\"80\" y1=\"200\" x2=\"220\" y2=\"80\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <text x=\"140\" y=\"125\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">v₁ > 0 (đi tới)</text>\n      <!-- Line 2: Horizontal (stationary) -->\n      <line x1=\"220\" y1=\"80\" x2=\"320\" y2=\"80\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n      <text x=\"240\" y=\"70\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">v₂ = 0 (đứng yên)</text>\n      <!-- Line 3: Negative slope (moving back) -->\n      <line x1=\"320\" y1=\"80\" x2=\"420\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n      <text x=\"360\" y=\"115\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">v₃ &lt; 0 (lùi lại)</text>\n      <!-- Points -->\n      <circle cx=\"220\" cy=\"80\" r=\"4\" fill=\"#34d399\"/>\n      <circle cx=\"320\" cy=\"80\" r=\"4\" fill=\"#34d399\"/>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Các dạng đường biểu diễn trên đồ thị d - t</text>\n    </svg>"},{"q":"Nếu đồ thị độ dịch chuyển – thời gian (d – t) là một đoạn thẳng nằm ngang song song với trục thời gian Ot thì vật đang:","opts":["Đứng yên tại một vị trí cố định.","Chuyển động thẳng đều với vận tốc rất lớn.","Chuyển động nhanh dần đều.","Chuyển động chậm dần đều rồi dừng lại."],"ans":0,"exp":"• Đường d - t nằm ngang tức là toạ độ/độ dịch chuyển không đổi theo thời gian (Δd = 0) ⇒ vận tốc v = Δd/Δt = 0 ⇒ vật đang đứng yên.","svgGraph":null},{"q":"Từ đồ thị d – t của một vật chuyển động thẳng, người ta thấy sau khoảng thời gian Δt = 4 s vật thực hiện độ dịch chuyển Δd = 20 m. Vận tốc của vật là:","opts":["5 m/s.","80 m/s.","0,2 m/s.","10 m/s."],"ans":0,"exp":"• <b>Công thức vận tốc từ đồ thị:</b> v = <span class=\"fraction\"><span class=\"numerator\">Δd</span><span class=\"denominator\">Δt</span></span> = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">4</span></span> = 5 m/s.","svgGraph":null},{"q":"Quan sát một đồ thị độ dịch chuyển – thời gian (d – t) của một hạt chuyển động thẳng, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Quãng đường đi được của vật luôn được xác định bằng diện tích hình thang dưới đồ thị d – t.","Độ dốc của đường d – t càng lớn thì vật chuyển động với tốc độ càng nhanh.","Nếu đường d – t dốc xuống dưới từ trái sang phải thì vật đang chuyển động ngược chiều dương đã chọn.","Đồ thị d – t có thể là một đường cong parabol nếu vật chuyển động thẳng biến đổi đều."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tốc độ |v| bằng trị tuyệt đối độ dốc, dốc càng đứng tốc độ càng lớn.<br>• <b>Ý b [Đúng]:</b> Dốc xuống ⇒ Δd < 0 ⇒ v < 0 (ngược chiều dương).<br>• <b>Ý c [Đúng]:</b> d = v₀t + 1/2 at² là hàm bậc hai theo t (đường cong parabol).<br>• <b>Ý d [Sai]:</b> Diện tích dưới đồ thị chỉ bằng quãng đường trong đồ thị vận tốc – thời gian (v – t), không phải đồ thị d – t.","svgGraph":null},{"q":"Ghép dạng đồ thị độ dịch chuyển – thời gian (d – t) ở Cột A với tính chất chuyển động tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Đoạn thẳng dốc lên từ gốc toạ độ ➔ Vật đứng yên (v = 0)","Đoạn thẳng dốc lên từ gốc toạ độ ➔ Chuyển động thẳng đều theo chiều dương (v = const > 0)","Đoạn thẳng nằm ngang song song trục thời gian ➔ Vật đứng yên (v = 0)","Đoạn thẳng dốc xuống ➔ Chuyển động thẳng đều theo chiều dương (v = const > 0)"],"ans":0,"exp":"• <b>1 - B:</b> Dốc lên: thẳng đều chiều dương.<br>• <b>2 - A:</b> Nằm ngang: đứng yên.<br>• <b>3 - D:</b> Dốc xuống: thẳng đều chiều âm.<br>• <b>4 - C:</b> Parabol cong lên: nhanh dần đều.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Từ đồ thị độ dịch chuyển – thời gian, ta có thể biết được vị trí của vật tại mỗi  [ ... ] . Độ dốc của đường tiếp tuyến với đồ thị d – t tại một điểm cho biết giá trị của  [ ... ]  tại thời điểm đó. Giao điểm của đồ thị d – t của hai vật cho biết thời điểm và vị trí mà hai vật  [ ... ] . Nếu đồ thị gấp khúc thì tại điểm gấp khúc vật đã  [ ... ] .\"</i>","opts":["thời điểm xác định — vận tốc tức thời","không đổi","gia tốc tức thời — va chạm nổ tung","vận tốc tức thời — thời điểm xác định"],"ans":0,"exp":"<b>Khai thác đồ thị d - t:</b><br>• Tìm vị trí tại mọi thời điểm.<br>• Tiếp tuyến cho vận tốc tức thời.<br>• Giao điểm là nơi hai vật gặp nhau.<br>• Gấp khúc là đổi vận tốc/chiều.","svgGraph":null},{"q":"Một xe ô tô chuyển động thẳng có đồ thị d – t gồm 2 giai đoạn: trong 2 giờ đầu đi được độ dịch chuyển 80 km; trong 1 giờ tiếp theo xe đứng yên nghỉ ngơi. Vận tốc trung bình của ô tô trong toàn bộ 3 giờ là:","opts":["26,7 km/h.","40 km/h.","80 km/h.","0 km/h."],"ans":0,"exp":"• <b>Tổng độ dịch chuyển:</b> d = 80 + 0 = 80 km.<br>• <b>Tổng thời gian:</b> t = 2 + 1 = 3 h.<br>• <b>Vận tốc trung bình:</b> v<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">80</span><span class=\"denominator\">3</span></span> ≈ 26,67 km/h.","svgGraph":null},{"q":"Đồ thị toạ độ – thời gian (x – t) của hai chuyển động thẳng đều (1) và (2) là hai đường thẳng cắt nhau tại điểm (t = 10 s, x = 50 m). Ý nghĩa vật lí của điểm giao nhau này là:","opts":["Tại thời điểm 10 s kể từ lúc bắt đầu chuyển động, hai vật gặp nhau ở toạ độ cách gốc 50 m.","Sau 10 s hai vật dừng lại hoàn toàn tại cùng một chỗ.","Hai vật có cùng vận tốc tức thời bằng 5 m/s.","Hai vật bắt đầu đổi chiều chuyển động ngược lại."],"ans":0,"exp":"• Giao điểm của hai đường x - t là nghiệm chung x₁ = x₂ và t₁ = t₂, biểu thị thời điểm và toạ độ gặp nhau của hai vật.","svgGraph":null},{"q":"Một người đi xe đạp xuất phát từ vị trí cách gốc toạ độ 10 km, chuyển động thẳng đều cùng chiều dương với tốc độ 15 km/h. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hệ số góc của đường biểu diễn x – t bằng 10 km.","Phương trình toạ độ của người đi xe đạp là x = 10 + 15t (với x tính bằng km, t tính bằng giờ).","Đồ thị x – t của chuyển động này là một đường thẳng dốc lên xuất phát từ điểm (t = 0; x = 10 km).","Sau 2 giờ chuyển động, toạ độ của người đó trên trục Ox là x = 40 km."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> x = x₀ + vt = 10 + 15t.<br>• <b>Ý b [Đúng]:</b> Tại t = 0 thì x = 10, v = +15 > 0 dốc lên.<br>• <b>Ý c [Đúng]:</b> x(2) = 10 + 15·2 = 40 km.<br>• <b>Ý d [Sai]:</b> Hệ số góc bằng vận tốc v = 15 km/h, không phải 10.","svgGraph":null},{"q":"Trong đồ thị d – t, đoạn thẳng đi xuống từ điểm (t = 0 s, d = 40 m) đến điểm (t = 5 s, d = 0 m). Vận tốc của vật trong khoảng thời gian này là:","opts":["-8 m/s.","+8 m/s.","-5 m/s.","+40 m/s."],"ans":0,"exp":"• <b>Công thức vận tốc:</b> v = <span class=\"fraction\"><span class=\"numerator\">d₂ - d₁</span><span class=\"denominator\">t₂ - t₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">0 - 40</span><span class=\"denominator\">5 - 0</span></span> = <span class=\"fraction\"><span class=\"numerator\">-40</span><span class=\"denominator\">5</span></span> = -8 m/s. Dấu trừ cho biết vật chuyển động ngược chiều dương.","svgGraph":null}],"8":[{"q":"Gia tốc là đại lượng vật lí đặc trưng cho:","opts":["Sự thay đổi nhanh hay chậm của vận tốc theo thời gian.","Mức độ nhanh hay chậm của toạ độ vị trí vật thể.","Độ dài quãng đường mà vật đi được trong một đơn vị thời gian.","Độ bền vững của trạng thái cân bằng lực."],"ans":0,"exp":"• <b>Định nghĩa gia tốc:</b> a = <span class=\"fraction\"><span class=\"numerator\">Δv</span><span class=\"denominator\">Δt</span></span>, là đại lượng vectơ đặc trưng cho tốc độ biến thiên của vận tốc cả về độ lớn lẫn hướng theo thời gian. Đơn vị trong hệ SI là m/s².","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr8\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Case 1: Nhanh dan deu (a and v same direction) -->\n      <g transform=\"translate(40, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"190\" height=\"120\" fill=\"#1e293b\" rx=\"8\"/>\n        <text x=\"20\" y=\"25\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Nhanh dần đều: a · v > 0</text>\n        <circle cx=\"40\" cy=\"70\" r=\"14\" fill=\"#38bdf8\"/>\n        <!-- Vector v -->\n        <line x1=\"54\" y1=\"65\" x2=\"110\" y2=\"65\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"75\" y=\"58\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\">v</text>\n        <!-- Vector a -->\n        <line x1=\"54\" y1=\"85\" x2=\"130\" y2=\"85\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"85\" y=\"102\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">a (cùng chiều v)</text>\n      </g>\n      <!-- Case 2: Cham dan deu (a and v opposite direction) -->\n      <g transform=\"translate(270, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"190\" height=\"120\" fill=\"#1e293b\" rx=\"8\"/>\n        <text x=\"20\" y=\"25\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">Chậm dần đều: a · v &lt; 0</text>\n        <circle cx=\"150\" cy=\"70\" r=\"14\" fill=\"#38bdf8\"/>\n        <!-- Vector v -->\n        <line x1=\"150\" y1=\"65\" x2=\"195\" y2=\"65\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"165\" y=\"58\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\">v</text>\n        <!-- Vector a -->\n        <line x1=\"136\" y1=\"85\" x2=\"70\" y2=\"85\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr8)\"/>\n        <text x=\"80\" y=\"102\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">a (ngược chiều v)</text>\n      </g>\n      <text x=\"140\" y=\"210\" fill=\"#94a3b8\" font-size=\"12\">Mối quan hệ hướng giữa vectơ gia tốc a và vectơ vận tốc v</text>\n    </svg>"},{"q":"Trong chuyển động thẳng nhanh dần đều, vectơ gia tốc a luôn có hướng:","opts":["Cùng hướng với vectơ vận tốc v (tích a·v > 0).","Ngược hướng với vectơ vận tốc v (tích a·v < 0).","Vuông góc với phương chuyển động.","Tuỳ ý thay đổi không phụ thuộc vào hướng chuyển động."],"ans":0,"exp":"• Khi chuyển động nhanh dần, độ lớn vận tốc tăng lên nên vectơ gia tốc a cùng chiều với vectơ vận tốc v (a·v > 0). Ngược lại, chậm dần thì a ngược chiều v (a·v < 0).","svgGraph":null},{"q":"Một ô tô đang chuyển động với vận tốc 10 m/s thì tăng tốc đều, sau 5 giây vận tốc của xe đạt 25 m/s. Gia tốc của ô tô là:","opts":["3 m/s².","5 m/s².","7 m/s².","15 m/s²."],"ans":0,"exp":"• <b>Công thức tính gia tốc:</b> a = <span class=\"fraction\"><span class=\"numerator\">v₂ - v₁</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">25 - 10</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">15</span><span class=\"denominator\">5</span></span> = 3 m/s².","svgGraph":null},{"q":"Về tính chất của vectơ gia tốc trong các dạng chuyển động thẳng, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Một vật có gia tốc mang dấu âm (a < 0) thì chắc chắn luôn là chuyển động chậm dần.","Trong chuyển động thẳng chậm dần theo chiều dương, gia tốc a mang giá trị âm.","Khi một vật chuyển động thẳng đều thì gia tốc của vật triệt tiêu bằng 0.","Đơn vị của gia tốc trong hệ đo lường SI là mét trên giây bình phương (m/s²)."],"ans":0,"exp":"• <b>Ý a [Sai]:</b> Dấu của a phụ thuộc vào chiều dương; nếu vật chạy theo chiều âm (v < 0) mà a < 0 thì a·v > 0 nên là chuyển động nhanh dần.<br>• <b>Ý b [Đúng]:</b> v > 0, chậm dần ⇒ a·v < 0 ⇒ a < 0.<br>• <b>Ý c [Đúng]:</b> Thẳng đều v = const ⇒ Δv = 0 ⇒ a = 0.<br>• <b>Ý d [Đúng]:</b> Đơn vị gia tốc là m/s².","svgGraph":null},{"q":"Ghép trạng thái chuyển động ở Cột A với điều kiện tương ứng giữa gia tốc a và vận tốc v ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Chuyển động thẳng đều ➔ a cùng chiều với v (a · v > 0)","Chuyển động thẳng đều ➔ v = 0 và a = 0","Chuyển động thẳng nhanh dần ➔ a cùng chiều với v (a · v > 0)","Chuyển động thẳng chậm dần ➔ v = 0 và a = 0"],"ans":0,"exp":"• <b>1 - C:</b> Thẳng đều: a = 0, v = const ≠ 0.<br>• <b>2 - A:</b> Nhanh dần: a·v > 0.<br>• <b>3 - D:</b> Chậm dần: a·v < 0.<br>• <b>4 - B:</b> Đứng yên: v = 0, a = 0.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Gia tốc là một đại lượng  [ ... ]  có độ lớn bằng tỉ số giữa độ biến thiên vận tốc và  [ ... ] . Trong hệ SI, đơn vị của vận tốc là m/s và của thời gian là s nên đơn vị của gia tốc là  [ ... ] . Khi một vật chuyển động trên đường cong với tốc độ không đổi, vật vẫn có gia tốc vì  [ ... ]  của vận tốc thay đổi liên tục.\"</i>","opts":["vectơ — khoảng thời gian xảy ra sự biến thiên đó","không đổi","vô hướng — m/s","khoảng thời gian xảy ra sự biến thiên đó — vectơ"],"ans":0,"exp":"<b>Đặc trưng của gia tốc:</b><br>• Đại lượng vectơ a = Δv/Δt.<br>• Đơn vị SI: m/s².<br>• Đi đường cong đổi hướng vẫn có gia tốc hướng tâm dù tốc độ không đổi.","svgGraph":null},{"q":"Một đoàn tàu hoả đang chạy với vận tốc 72 km/h (20 m/s) thì người lái tàu hãm phanh để tàu chạy chậm dần đều. Sau 20 giây thì tàu dừng hẳn. Gia tốc của đoàn tàu là:","opts":["-1 m/s².","+1 m/s².","-2 m/s².","-3,6 m/s²."],"ans":0,"exp":"• <b>Dừng hẳn:</b> v₂ = 0.<br>• <b>Gia tốc hãm phanh:</b> a = <span class=\"fraction\"><span class=\"numerator\">v₂ - v₁</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">0 - 20</span><span class=\"denominator\">20</span></span> = -1 m/s² (gia tốc ngược hướng vận tốc).","svgGraph":null},{"q":"Một vận động viên chạy nước rút bắt đầu xuất phát từ trạng thái nghỉ với gia tốc không đổi a = 4 m/s². Sau thời gian t = 2,5 giây kể từ lúc xuất phát, vận tốc của vận động viên đạt:","opts":["10 m/s.","12,5 m/s.","8 m/s.","16 m/s."],"ans":0,"exp":"• <b>Công thức vận tốc:</b> v = v₀ + at = 0 + 4 · 2,5 = 10 m/s (tương đương 36 km/h).","svgGraph":null},{"q":"Một xe ô tô thử nghiệm tăng tốc từ 0 đến 100 km/h trong thời gian 5,0 s. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Gia tốc này lớn hơn gia tốc trọng trường rơi tự do g ≈ 9,8 m/s².","Vận tốc 100 km/h quy đổi ra hệ SI xấp xỉ bằng 27,78 m/s.","Gia tốc trung bình của xe trong quá trình tăng tốc này xấp xỉ bằng 5,56 m/s².","Nếu giữ nguyên gia tốc này thêm 5 giây nữa thì vận tốc của xe sẽ đạt 200 km/h."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> 100 / 3,6 ≈ 27,78 m/s.<br>• <b>Ý b [Đúng]:</b> a = 27,78 / 5,0 ≈ 5,56 m/s².<br>• <b>Ý c [Sai]:</b> 5,56 m/s² nhỏ hơn g ≈ 9,8 m/s².<br>• <b>Ý d [Đúng]:</b> Sau 10 s vận tốc đạt v = 5,56 · 10 = 55,56 m/s = 200 km/h.","svgGraph":null},{"q":"Đồ thị vận tốc – thời gian (v – t) của một vật chuyển động có dạng một đường thẳng song song với trục hoành Ot. Gia tốc của vật bằng:","opts":["0 m/s².","1 m/s².","Một hằng số dương khác 0.","Vô cùng lớn."],"ans":0,"exp":"• Đường v - t song song với trục hoành tức vận tốc không thay đổi theo thời gian (v = const) ⇒ chuyển động thẳng đều ⇒ gia tốc a = 0.","svgGraph":null}],"9":[{"q":"Chuyển động thẳng biến đổi đều là chuyển động thẳng trong đó:","opts":["Gia tốc có phương, chiều và độ lớn không đổi theo thời gian (a = const).","Vận tốc tức thời có giá trị không đổi theo thời gian.","Quãng đường đi được tỉ lệ bậc nhất với thời gian chuyển động.","Độ dốc của đồ thị vận tốc – thời gian thay đổi liên tục."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Chuyển động thẳng biến đổi đều là chuyển động có quỹ đạo là đường thẳng và có gia tốc không đổi theo thời gian (a = const).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr9\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes v and t -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">t (s)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">v (m/s)</text>\n      <!-- Line: v = v0 + at -->\n      <line x1=\"80\" y1=\"150\" x2=\"380\" y2=\"60\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Intercept v0 -->\n      <circle cx=\"80\" cy=\"150\" r=\"4\" fill=\"#ef4444\"/>\n      <text x=\"55\" y=\"155\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">v₀</text>\n      <!-- Shaded area for displacement d -->\n      <polygon points=\"80,150 340,72 340,200 80,200\" fill=\"#38bdf8\" opacity=\"0.15\"/>\n      <text x=\"180\" y=\"175\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Diện tích hình thang = Độ dịch chuyển d</text>\n      <line x1=\"340\" y1=\"72\" x2=\"340\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"335\" y=\"215\" fill=\"#fbbf24\" font-size=\"12\">t</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị v - t của chuyển động thẳng biến đổi đều</text>\n    </svg>"},{"q":"Hệ thức độc lập thời gian liên hệ giữa vận tốc v, vận tốc ban đầu v₀, gia tốc a và độ dịch chuyển d trong chuyển động thẳng biến đổi đều là:","opts":["v² - v₀² = 2·a·d.","v² + v₀² = 2·a·d.","v - v₀ = 2·a·d.","v² - v₀² = a·d."],"ans":0,"exp":"• <b>Hệ thức liên hệ không phụ thuộc thời gian:</b> v² - v₀² = 2ad. Nếu vật chuyển động thẳng không đổi chiều thì d = s ⇒ v² - v₀² = 2as.","svgGraph":null},{"q":"Một đoàn tàu bắt đầu rời ga (v₀ = 0) chuyển động thẳng nhanh dần đều với gia tốc a = 0,2 m/s². Quãng đường tàu đi được sau thời gian 30 giây là:","opts":["90 m.","180 m.","6 m.","45 m."],"ans":0,"exp":"• <b>Công thức tính độ dịch chuyển:</b> d = v₀t + <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>at²<br>• <b>Thay số:</b> d = 0 + <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,2 · (30)² = 0,1 · 900 = 90 m.","svgGraph":null},{"q":"Một chiếc xe đang chạy với vận tốc 54 km/h (15 m/s) thì hãm phanh chuyển động thẳng chậm dần đều với độ lớn gia tốc |a| = 1,5 m/s². Chọn chiều dương là chiều chuyển động ban đầu. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Sau 12 giây kể từ lúc hãm phanh, xe sẽ tự động chạy lùi lại phía sau.","Giá trị đại số của gia tốc là a = -1,5 m/s².","Thời gian từ lúc bắt đầu hãm phanh đến khi xe dừng hẳn là 10 giây.","Quãng đường xe chạy thêm được từ lúc hãm phanh đến khi dừng hẳn là 75 m."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Chậm dần cùng chiều dương ⇒ a < 0 ⇒ a = -1,5 m/s².<br>• <b>Ý b [Đúng]:</b> t = (0 - 15)/(-1,5) = 10 s.<br>• <b>Ý c [Đúng]:</b> s = (0² - 15²) / (2 · (-1,5)) = -225 / (-3) = 75 m.<br>• <b>Ý d [Sai]:</b> Phanh xe dừng lại thì đứng yên v = 0, lực ma sát nghỉ giữ xe lại chứ không đẩy xe chạy lùi.","svgGraph":null},{"q":"Ghép công thức chuyển động thẳng biến đổi đều ở Cột A với tên gọi tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["v = v₀ + a·t ➔ Công thức tính độ dịch chuyển theo thời gian","v = v₀ + a·t ➔ Phương trình vận tốc theo thời gian","d = v₀·t + 1/2 · a·t² ➔ Công thức tính độ dịch chuyển theo thời gian","v² - v₀² = 2·a·d ➔ Phương trình vận tốc theo thời gian"],"ans":0,"exp":"• <b>1 - B:</b> v = v₀ + at.<br>• <b>2 - A:</b> d = v₀t + 1/2 at².<br>• <b>3 - D:</b> v² - v₀² = 2ad.<br>• <b>4 - C:</b> d = (v₀ + v)/2 · t.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong chuyển động thẳng biến đổi đều, gia tốc a là một  [ ... ] . Đồ thị vận tốc – thời gian (v – t) là một  [ ... ]  có độ dốc bằng gia tốc a. Diện tích hình phẳng giới hạn bởi đường v – t và trục thời gian Ot biểu diễn  [ ... ]  của vật. Nếu đồ thị toạ độ – thời gian (x – t) được vẽ thì nó có dạng một  [ ... ] .\"</i>","opts":["hằng số không đổi — đường thẳng dốc","không đổi","biến thiên tuần hoàn — đoạn thẳng nằm ngang","đường thẳng dốc — hằng số không đổi"],"ans":0,"exp":"<b>Đặc trưng chuyển động thẳng biến đổi đều:</b><br>• a = const.<br>• Đồ thị v - t là đường thẳng có hệ số góc a.<br>• Diện tích dưới v - t là độ dịch chuyển d.<br>• Đồ thị x - t là parabol bậc hai.","svgGraph":null},{"q":"Một xe máy đang chạy với vận tốc 36 km/h (10 m/s) thì tăng ga chuyển động nhanh dần đều với gia tốc a = 2 m/s² trên quãng đường dài 24 m. Vận tốc của xe ở cuối quãng đường này là:","opts":["14 m/s.","12 m/s.","16 m/s.","20 m/s."],"ans":0,"exp":"• <b>Sử dụng hệ thức độc lập thời gian:</b> v² - v₀² = 2as<br>• Thay số: v² - 10² = 2 · 2 · 24 = 96 ⇒ v² = 100 + 96 = 196 ⇒ v = √196 = 14 m/s.","svgGraph":null},{"q":"Một ô tô chuyển động nhanh dần đều không vận tốc ban đầu (v₀ = 0). Trong giây thứ nhất xe đi được quãng đường s₁ = 2 m. Quãng đường xe đi được trong giây thứ hai là:","opts":["6 m.","4 m.","8 m.","2 m."],"ans":0,"exp":"• <b>Bước 1: Tìm gia tốc a:</b> s₁ = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>a·(1)² = 2 m ⇒ a = 4 m/s².<br>• <b>Bước 2: Quãng đường sau 2 giây:</b> s(2) = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 4 · 2² = 8 m.<br>• <b>Quãng đường trong giây thứ hai:</b> Δs₂ = s(2) - s(1) = 8 - 2 = 6 m.","svgGraph":null},{"q":"Một viên bi bắt đầu lăn xuống một máng nghiêng dài 100 cm từ trạng thái nghỉ với gia tốc không đổi a = 0,5 m/s². Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tại điểm chính giữa của máng nghiêng (quãng đường 50 cm), vận tốc của viên bi bằng một nửa vận tốc tại chân máng.","Thời gian để viên bi lăn hết chiều dài máng nghiêng là 2 giây.","Vận tốc của viên bi tại chân máng nghiêng là 1 m/s.","Vận tốc trung bình của viên bi trên toàn bộ máng nghiêng là 0,5 m/s."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> s = 1m = 1/2 · 0,5 · t² ⇒ t² = 4 ⇒ t = 2 s.<br>• <b>Ý b [Đúng]:</b> v = at = 0,5 · 2 = 1 m/s.<br>• <b>Ý c [Đúng]:</b> v<sub>tb</sub> = s/t = 1/2 = 0,5 m/s.<br>• <b>Ý d [Sai]:</b> v<sub>gi</sub>ữa = √(2·a·s/2) = √(v²/2) = v / √2 ≈ 0,707 m/s (không phải bằng v/2 = 0,5 m/s).","svgGraph":null},{"q":"Khoảng cách an toàn tối thiểu giữa hai ô tô đang lưu thông trên đường cao tốc với tốc độ cao dựa chủ yếu vào yếu tố vật lí nào?","opts":["Quãng đường phản xạ của tài xế cộng với quãng đường hãm phanh dừng xe.","Khối lượng xe càng nhẹ thì khoảng cách an toàn cần giữ càng xa.","Màu sơn phản quang của đuôi xe phía trước.","Công suất cực đại của hệ thống điều hoà trên xe."],"ans":0,"exp":"• Khoảng cách an toàn = Quãng đường đi trong thời gian tài xế phản xạ (khoảng 0,7s - 1s: s₁ = v·t<sub>px</sub>) + Quãng đường phanh chậm dần đều (s₂ = v² / 2a<sub>hãm</sub>).","svgGraph":null}],"10":[{"q":"Sự rơi tự do là sự rơi của một vật:","opts":["Chỉ dưới tác dụng của trọng lực trong điều kiện không có lực cản không khí.","Từ trên cao xuống dưới với vận tốc ban đầu rất lớn.","Trong đó lực cản không khí cân bằng hoàn toàn với trọng lực.","Chuyển động thẳng đều từ trên xuống dưới với vận tốc không đổi."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Sự rơi tự do là sự rơi của các vật chỉ chịu tác dụng của trọng lực. Trong thực tế, nếu sức cản của không khí rất nhỏ so với trọng lực thì có thể coi chuyển động rơi của vật là rơi tự do.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr10\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Height scale vertical line -->\n      <line x1=\"120\" y1=\"30\" x2=\"120\" y2=\"210\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Falling ball at different times -->\n      <!-- t = 0 -->\n      <circle cx=\"120\" cy=\"40\" r=\"10\" fill=\"#ef4444\"/>\n      <text x=\"145\" y=\"45\" fill=\"#fca5a5\" font-size=\"12\">t = 0 (v₀ = 0)</text>\n      <!-- t = 1s (h = 5m) -->\n      <circle cx=\"120\" cy=\"75\" r=\"10\" fill=\"#f59e0b\"/>\n      <text x=\"145\" y=\"80\" fill=\"#fde68a\" font-size=\"12\">t = 1s (h₁ = 1/2 g)</text>\n      <!-- t = 2s (h = 20m) -->\n      <circle cx=\"120\" cy=\"130\" r=\"10\" fill=\"#38bdf8\"/>\n      <text x=\"145\" y=\"135\" fill=\"#7dd3fc\" font-size=\"12\">t = 2s (h₂ = 4h₁)</text>\n      <!-- t = 3s (h = 45m) -->\n      <circle cx=\"120\" cy=\"195\" r=\"10\" fill=\"#34d399\"/>\n      <text x=\"145\" y=\"200\" fill=\"#a7f3d0\" font-size=\"12\">t = 3s (h₃ = 9h₁)</text>\n      <!-- Gravity arrow g -->\n      <line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"150\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr10)\"/>\n      <text x=\"335\" y=\"115\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">g (thẳng đứng hướng xuống)</text>\n      <text x=\"120\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Ảnh chụp hoạt nghiệm chuyển động rơi tự do (khoảng cách tăng theo t²)</text>\n    </svg>"},{"q":"Chuyển động rơi tự do của một vật có tính chất là chuyển động:","opts":["Thẳng nhanh dần đều theo phương thẳng đứng từ trên xuống dưới.","Thẳng chậm dần đều theo phương nằm ngang.","Thẳng đều với vận tốc không đổi bằng 9,8 m/s.","Biến đổi phức tạp phụ thuộc vào hình dạng và khối lượng của vật."],"ans":0,"exp":"• Rơi tự do có phương thẳng đứng, chiều từ trên xuống dưới và là chuyển động thẳng nhanh dần đều với gia tốc rơi tự do g.","svgGraph":null},{"q":"Một vật được thả rơi tự do từ độ cao h = 45 m xuống đất. Lấy gia tốc trọng trường g = 10 m/s². Thời gian rơi của vật đến khi chạm đất là:","opts":["3 s.","4,5 s.","9 s.","2 s."],"ans":0,"exp":"• <b>Công thức thời gian rơi tự do:</b> t = √(<span class=\"fraction\"><span class=\"numerator\">2h</span><span class=\"denominator\">g</span></span>)<br>• <b>Thay số:</b> t = √(<span class=\"fraction\"><span class=\"numerator\">2 · 45</span><span class=\"denominator\">10</span></span>) = √9 = 3 s.","svgGraph":null},{"q":"Khi thả rơi tự do hai vật có khối lượng m₁ và m₂ (với m₁ = 10·m₂) ở cùng một độ cao tại cùng một nơi trên Trái Đất trong chân không, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Vật m₁ nặng hơn sẽ rơi nhanh hơn và chạm đất trước vật m₂.","Hai vật có cùng gia tốc rơi tự do g như nhau tại vị trí đó.","Cả hai vật chạm đất cùng một thời điểm và có cùng vận tốc chạm đất.","Gia tốc rơi tự do g thay đổi theo vĩ độ địa lí và độ cao so với mực nước biển."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Gia tốc rơi tự do g không phụ thuộc khối lượng vật.<br>• <b>Ý b [Đúng]:</b> t = √(2h/g) và v = √(2gh) bằng nhau.<br>• <b>Ý c [Sai]:</b> Trong chân không hai vật rơi như nhau (thí nghiệm ống Newton).<br>• <b>Ý d [Đúng]:</b> g lớn nhất ở 2 cực (≈ 9,83 m/s²) và nhỏ nhất ở xích đạo (≈ 9,78 m/s²), giảm dần khi lên cao.","svgGraph":null},{"q":"Ghép các công thức của chuyển động rơi tự do (v₀ = 0) ở Cột A với ý nghĩa tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["v = g · t ➔ Thời gian rơi của vật từ độ cao h","v = g · t ➔ Vận tốc tức thời sau thời gian rơi t","h = 1/2 · g · t² ➔ Thời gian rơi của vật từ độ cao h","v² = 2 · g · h ➔ Vận tốc tức thời sau thời gian rơi t"],"ans":0,"exp":"• <b>1 - B:</b> v = gt.<br>• <b>2 - C:</b> h = ½ g·t².<br>• <b>3 - D:</b> v² = 2gh.<br>• <b>4 - A:</b> t = √(2h/g).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Tại một nơi xác định trên bề mặt Trái Đất, mọi vật đều rơi tự do với cùng một  [ ... ] . Giá trị của g thường được lấy xấp xỉ bằng  [ ... ] . Càng lên cao so với mặt đất, giá trị của gia tốc trọng trường g sẽ  [ ... ] . Thí nghiệm của Newton với ống hút chân không chứa một chiếc lông chim và hòn bi chì đã chứng minh khi không có sức cản không khí thì các vật rơi  [ ... ] .\"</i>","opts":["gia tốc rơi tự do g — 9,8 m/s² (hoặc 10 m/s²)","không đổi","tăng dần — lông chim rơi chậm hơn","9,8 m/s² (hoặc 10 m/s²) — gia tốc rơi tự do g"],"ans":0,"exp":"<b>Gia tốc rơi tự do:</b><br>• Cùng một nơi g như nhau.<br>• g ≈ 9,8 m/s².<br>• Lên cao g giảm: g = GM/(R+h)².<br>• Không có không khí mọi vật rơi như nhau.","svgGraph":null},{"q":"Thả một hòn đá rơi tự do từ miệng một giếng sâu. Sau 2 giây kể từ khi thả thì nghe thấy tiếng hòn đá chạm đáy giếng. Bỏ qua thời gian truyền âm trong không khí, lấy g = 10 m/s². Độ sâu của giếng là:","opts":["20 m.","40 m.","10 m.","30 m."],"ans":0,"exp":"• <b>Công thức độ sâu rơi tự do:</b> h = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>g·t² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 10 · 2² = 5 · 4 = 20 m.","svgGraph":null},{"q":"Một vật rơi tự do chạm đất với vận tốc v = 30 m/s. Lấy g = 10 m/s². Độ cao ban đầu khi thả vật là:","opts":["45 m.","90 m.","30 m.","15 m."],"ans":0,"exp":"• <b>Công thức liên hệ:</b> v² = 2gh ⇒ h = <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">2g</span></span> = <span class=\"fraction\"><span class=\"numerator\">30²</span><span class=\"denominator\">2 · 10</span></span> = <span class=\"fraction\"><span class=\"numerator\">900</span><span class=\"denominator\">20</span></span> = 45 m.","svgGraph":null},{"q":"Một vật rơi tự do từ độ cao h xuống đất với g = 10 m/s² trong tổng thời gian rơi là 4 giây. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trong giây đầu tiên, vật rơi được một nửa độ cao h.","Độ cao ban đầu thả vật là h = 80 m.","Vận tốc của vật ngay trước khi chạm đất là v = 40 m/s.","Quãng đường vật rơi được trong giây cuối cùng trước khi chạm đất là 35 m."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> h = 1/2 · 10 · 4² = 80 m.<br>• <b>Ý b [Đúng]:</b> v = gt = 10 · 4 = 40 m/s.<br>• <b>Ý c [Đúng]:</b> Sau 3s: h(3) = 1/2 · 10 · 3² = 45 m ⇒ giây thứ tư: Δh = 80 - 45 = 35 m.<br>• <b>Ý d [Sai]:</b> Giây đầu rơi h(1) = 1/2 · 10 · 1² = 5 m (chỉ bằng 5/80 = 1/16 độ cao ban đầu).","svgGraph":null},{"q":"Tại sao khi một chiếc lá cây và một hòn sỏi rơi trong không khí ngoài trời, hòn sỏi rơi xuống đất nhanh hơn chiếc lá?","opts":["Vì lực cản của không khí tác dụng lên chiếc lá là đáng kể so với trọng lượng rất nhỏ của nó.","Vì Trái Đất hút hòn sỏi mạnh hơn chiếc lá với gia tốc trọng trường lớn hơn.","Vì chiếc lá có khối lượng âm trong không khí quyển.","Vì lực hấp dẫn chỉ tác dụng lên các vật có dạng hình khối đặc."],"ans":0,"exp":"• Chiếc lá có diện tích bề mặt lớn và trọng lượng nhỏ nên tỉ số lực cản/trọng lực rất lớn làm giảm mạnh gia tốc rơi so với hòn sỏi đặc có lực cản không đáng kể.","svgGraph":null}],"11":[{"q":"Trong bài thực hành đo gia tốc rơi tự do bằng cổng quang điện và đồng hồ hiện số, gia tốc g được tính từ công thức:","opts":["g = 2·s / t².","g = s / (2t²).","g = 2·s · t².","g = s / t."],"ans":0,"exp":"• Từ công thức rơi tự do không vận tốc đầu: s = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>gt² ⇒ g = <span class=\"fraction\"><span class=\"numerator\">2s</span><span class=\"denominator\">t²</span></span>.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Vertical stand -->\n      <line x1=\"120\" y1=\"20\" x2=\"120\" y2=\"210\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <!-- Electromagnet at top -->\n      <rect x=\"105\" y=\"25\" width=\"30\" height=\"20\" fill=\"#dc2626\" rx=\"3\"/>\n      <text x=\"145\" y=\"40\" fill=\"#fca5a5\" font-size=\"11\">Nam châm điện</text>\n      <!-- Steel ball dropped -->\n      <circle cx=\"120\" cy=\"55\" r=\"7\" fill=\"#f8fafc\"/>\n      <!-- Photogate A -->\n      <rect x=\"100\" y=\"80\" width=\"40\" height=\"15\" fill=\"#0284c7\" rx=\"2\"/>\n      <text x=\"145\" y=\"92\" fill=\"#7dd3fc\" font-size=\"11\">Cổng quang A</text>\n      <!-- Photogate B -->\n      <rect x=\"100\" y=\"170\" width=\"40\" height=\"15\" fill=\"#0284c7\" rx=\"2\"/>\n      <text x=\"145\" y=\"182\" fill=\"#7dd3fc\" font-size=\"11\">Cổng quang B</text>\n      <!-- Height distance s -->\n      <line x1=\"85\" y1=\"80\" x2=\"85\" y2=\"170\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"85\" cy=\"80\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"85\" cy=\"170\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"60\" y=\"130\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">s</text>\n      <!-- Digital Timer Screen -->\n      <rect x=\"250\" y=\"80\" width=\"160\" height=\"70\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"8\"/>\n      <text x=\"270\" y=\"110\" fill=\"#94a3b8\" font-size=\"11\">ĐỒNG HỒ HIỆN SỐ</text>\n      <text x=\"275\" y=\"135\" fill=\"#34d399\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">0.285 s</text>\n      <text x=\"140\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Mô hình bố trí thí nghiệm đo gia tốc rơi tự do</text>\n    </svg>"},{"q":"Vai trò của nam châm điện đặt ở đỉnh giá đỡ trong thí nghiệm đo gia tốc rơi tự do là:","opts":["Giữ viên bi đứng yên và thả rơi viên bi với vận tốc ban đầu triệt tiêu hoàn toàn (v₀ = 0).","Khuếch đại gia tốc rơi của viên bi lên mức lớn hơn bình thường.","Đẩy viên bi rơi xuống với lực điện từ cực mạnh.","Đo trực tiếp khối lượng của viên bi kim loại."],"ans":0,"exp":"• Nam châm điện giữ viên bi cố định; khi ngắt công tắc điện, từ trường mất tức thì viên bi bắt đầu rơi tự do với vận tốc đầu v₀ = 0 hoàn toàn không có lực đẩy cơ học bằng tay.","svgGraph":null},{"q":"Trong một lần thí nghiệm, đo được quãng đường rơi tự do s = (0,784 ± 0,002) m và thời gian rơi t = (0,400 ± 0,004) s. Giá trị trung bình của gia tốc rơi tự do g<sub>tb</sub> là:","opts":["9,80 m/s².","9,75 m/s².","9,85 m/s².","10,0 m/s²."],"ans":0,"exp":"• <b>Giá trị trung bình của g:</b><br>g<sub>tb</sub> = <span class=\"fraction\"><span class=\"numerator\">2·s<sub>tb</sub></span><span class=\"denominator\">t<sub>tb</sub>²</span></span> = <span class=\"fraction\"><span class=\"numerator\">2 · 0,784</span><span class=\"denominator\">(0,400)²</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,568</span><span class=\"denominator\">0,16</span></span> = 9,80 m/s².","svgGraph":null},{"q":"Về các nguồn sai số và cách xử lí số liệu trong bài thực hành đo g, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nên chọn viên bi có đường kính quá lớn và khối lượng thật nhẹ như quả bóng bàn để làm thí nghiệm.","Công thức tính sai số tỉ đối của gia tốc rơi tự do là δg = δs + 2·δt.","Nếu giá treo bị nghiêng lệch khỏi phương dây dọi thẳng đứng thì kết quả tính g sẽ bị sai lệch hệ thống.","Phương pháp vẽ đồ thị mối quan hệ s theo t² là một đường thẳng đi qua gốc toạ độ có hệ số góc bằng g/2."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> g = 2s/t² ⇒ δg = δs + 2·δt.<br>• <b>Ý b [Đúng]:</b> Máng hoặc giá đỡ lệch phương thẳng đứng làm bi va quẹt vào cổng quang hoặc rơi theo phương xiên.<br>• <b>Ý c [Sai]:</b> Bóng bàn lực cản không khí lớn không còn là rơi tự do; phải dùng bi thép đặc, nhỏ và nặng.<br>• <b>Ý d [Đúng]:</b> s = (g/2)·t², đồ thị s theo t² là đường thẳng độ dốc k = g/2.","svgGraph":null},{"q":"Ghép các bộ phận thí nghiệm đo g ở Cột A với chức năng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Dây dọi thẳng đứng ➔ Xác định thời điểm viên bi đi qua vị trí xác định","Dây dọi thẳng đứng ➔ Căn chỉnh giá đỡ chuẩn xác theo phương thẳng đứng","Viên bi thép nhỏ ➔ Xác định thời điểm viên bi đi qua vị trí xác định","Thước thẳng chia vạch trên giá đỡ ➔ Căn chỉnh giá đỡ chuẩn xác theo phương thẳng đứng"],"ans":0,"exp":"• <b>1 - B:</b> Dây dọi căn chỉnh phương thẳng đứng.<br>• <b>2 - C:</b> Bi thép nhỏ làm vật rơi tự do.<br>• <b>3 - D:</b> Thước đo khoảng cách rơi s.<br>• <b>4 - A:</b> Cổng quang bấm giờ.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Căn chỉnh chân đế giá đỡ sao cho dây dọi trùng với  [ ... ] . Đặt viên bi thép dính vào nam châm điện. Cài đặt đồng hồ đo thời gian ở chế độ  [ ... ] . Nhấn nút ngắt điện nam châm để viên bi  [ ... ]  rơi qua cổng quang. Lặp lại phép đo ít nhất 5 lần, tính giá trị trung bình g<sub>tb</sub> và  [ ... ]  của phép đo.\"</i>","opts":["phương thẳng đứng — thang đo thời gian rơi","không đổi","phương nằm ngang — tốc độ tức thời","thang đo thời gian rơi — phương thẳng đứng"],"ans":0,"exp":"<b>Quy trình đo g:</b><br>• Căn chỉnh phương thẳng đứng.<br>• Cài đặt chế độ đếm thời gian.<br>• Thả rơi tự do viên bi.<br>• Tính g<sub>tb</sub> và sai số toàn phần Δg.","svgGraph":null},{"q":"Biết sai số tỉ đối của phép đo quãng đường là δs = 0,4% và sai số tỉ đối của phép đo thời gian là δt = 0,8%. Sai số tỉ đối của phép đo gia tốc rơi tự do g là:","opts":["2,0%.","1,2%.","1,6%.","0,4%."],"ans":0,"exp":"• <b>Công thức sai số tỉ đối của g = 2s/t²:</b><br>δg = δs + 2·δt = 0,4% + 2 · 0,8% = 0,4% + 1,6% = 2,0%.","svgGraph":null},{"q":"Kết quả đo gia tốc rơi tự do tại phòng thí nghiệm của trường thu được là g = (9,78 ± 0,12) m/s². Khoảng giá trị tin cậy của gia tốc rơi tự do đo được là:","opts":["Từ 9,66 m/s² đến 9,90 m/s².","Từ 9,78 m/s² đến 9,90 m/s².","Từ 9,66 m/s² đến 9,78 m/s².","Từ 9,80 m/s² đến 10,0 m/s²."],"ans":0,"exp":"• Khoảng tin cậy: [g<sub>tb</sub> - Δg ; g<sub>tb</sub> + Δg] = [9,78 - 0,12 ; 9,78 + 0,12] = [9,66 ; 9,90] m/s².","svgGraph":null},{"q":"Một nhóm học sinh đo thời gian rơi tự do trên quãng đường s = 0,8 m thu được 3 lần đo: t₁ = 0,402 s; t₂ = 0,405 s; t₃ = 0,408 s. Lấy g<sub>tb</sub> tính từ thời gian trung bình. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Kết quả đo này cho thấy Trái Đất hoàn toàn không có lực hấp dẫn tại phòng thí nghiệm.","Thời gian trung bình của 3 lần đo là t<sub>tb</sub> = 0,405 s.","Sai số ngẫu nhiên tuyệt đối trung bình của thời gian rơi là Δt<sub>ng</sub> = 0,002 s.","Giá trị trung bình gia tốc trọng trường tính được là g<sub>tb</sub> ≈ 9,75 m/s²."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> t<sub>tb</sub> = (0,402 + 0,405 + 0,408)/3 = 0,405 s.<br>• <b>Ý b [Đúng]:</b> Độ lệch: |0,405-0,402|=0,003; 0; 0,003 ⇒ Δt = 0,006/3 = 0,002 s.<br>• <b>Ý c [Đúng]:</b> g = 2·0,8 / (0,405)² = 1,6 / 0,164025 ≈ 9,75 m/s².<br>• <b>Ý d [Sai]:</b> Giá trị 9,75 m/s² xấp xỉ chuẩn gia tốc trọng trường của Trái Đất (≈ 9,8 m/s²).","svgGraph":null},{"q":"Nếu không có đồng hồ hiện số và cổng quang điện, có thể đo sơ bộ gia tốc rơi tự do bằng phương pháp truyền thống nào sau đây?","opts":["Sử dụng đồng hồ bấm giây thủ công đo chu kì dao động của con lắc đơn chiều dài L rồi tính g = 4π²L / T².","Dùng nhiệt kế đo nhiệt độ nóng chảy của nước đá.","Dùng lực kế đo thể tích của một khối chì nhúng trong nước.","Dùng kính hiển vi quan sát tế bào thực vật."],"ans":0,"exp":"• Con lắc đơn T = 2π√(L/g) ⇒ g = 4π²L/T² là phương pháp đo gia tốc trọng trường kinh điển rất chính xác với dụng cụ đơn giản.","svgGraph":null}],"12":[{"q":"Chuyển động ném ngang là chuyển động có thể phân tích thành hai chuyển động thành phần độc lập:","opts":["Chuyển động thẳng đều theo phương ngang (Ox) và chuyển động rơi tự do theo phương thẳng đứng (Oy).","Chuyển động thẳng biến đổi đều theo phương ngang và đứng yên theo phương thẳng đứng.","Hai chuyển động thẳng đều theo cả phương ngang và phương thẳng đứng.","Hai chuyển động rơi tự do theo cả hai phương vuông góc nhau."],"ans":0,"exp":"• <b>Nguyên tắc độc lập chuyển động:</b> Theo phương ngang Ox không có lực tác dụng (F<sub>x</sub> = 0) nên chuyển động thẳng đều với v<sub>x</sub> = v₀. Theo phương thẳng đứng Oy chỉ chịu trọng lực P nên rơi tự do với gia tốc a<sub>y</sub> = g.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr12\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Height cliff at Left -->\n      <rect x=\"50\" y=\"40\" width=\"40\" height=\"160\" fill=\"#1e293b\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <line x1=\"50\" y1=\"200\" x2=\"450\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Launch point O -->\n      <circle cx=\"90\" cy=\"40\" r=\"6\" fill=\"#ef4444\"/>\n      <text x=\"75\" y=\"32\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">O</text>\n      <!-- Initial horizontal velocity v0 -->\n      <line x1=\"90\" y1=\"40\" x2=\"160\" y2=\"40\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr12)\"/>\n      <text x=\"120\" y=\"30\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">v₀</text>\n      <!-- Parabolic trajectory -->\n      <path d=\"M 90,40 Q 230,40 370,200\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n      <!-- Impact point on ground -->\n      <circle cx=\"370\" cy=\"200\" r=\"5\" fill=\"#34d399\"/>\n      <!-- Height h and Range L -->\n      <line x1=\"35\" y1=\"40\" x2=\"35\" y2=\"200\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"15\" y=\"125\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">h</text>\n      <line x1=\"90\" y1=\"215\" x2=\"370\" y2=\"215\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <text x=\"210\" y=\"230\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Tầm xa L = v₀·√(2h/g)</text>\n    </svg>"},{"q":"Quỹ đạo chuyển động của một vật ném ngang có dạng là:","opts":["Một nhánh của đường parabol có đỉnh tại vị trí ném.","Một đường thẳng dốc nghiêng nối từ điểm ném xuống đất.","Một cung tròn bán kính bằng độ cao thả vật.","Một đường xoắn ốc quanh trục thẳng đứng."],"ans":0,"exp":"• <b>Phương trình quỹ đạo:</b> Khử thời gian t từ x = v₀t và y = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>gt² ta được: y = (<span class=\"fraction\"><span class=\"numerator\">g</span><span class=\"denominator\">2v₀²</span></span>)·x². Đây là phương trình của một nhánh parabol đỉnh O.","svgGraph":null},{"q":"Một vật được ném ngang từ độ cao h = 20 m với vận tốc ban đầu v₀ = 15 m/s. Lấy g = 10 m/s². Tầm ném xa L của vật khi chạm đất là:","opts":["30 m.","15 m.","45 m.","60 m."],"ans":0,"exp":"• <b>Bước 1: Tính thời gian bay t:</b> t = √(<span class=\"fraction\"><span class=\"numerator\">2h</span><span class=\"denominator\">g</span></span>) = √(<span class=\"fraction\"><span class=\"numerator\">2 · 20</span><span class=\"denominator\">10</span></span>) = √4 = 2 s.<br>• <b>Bước 2: Tính tầm ném xa L:</b> L = v₀ · t = 15 · 2 = 30 m.","svgGraph":null},{"q":"Tại cùng một độ cao h so với mặt đất, hai viên bi sắt A và B được thả cùng một lúc: viên bi A thả rơi tự do thẳng đứng, viên bi B được ném ngang với vận tốc v₀. Bỏ qua sức cản không khí. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu tăng vận tốc ném v₀ lên gấp đôi thì thời gian chạm đất của viên bi B cũng tăng lên gấp đôi.","Cả hai viên bi A và B chạm đất tại cùng một thời điểm.","Thời gian chuyển động của vật ném ngang hoàn toàn không phụ thuộc vào vận tốc ném ban đầu v₀.","Khi chạm đất, vận tốc của viên bi B có độ lớn lớn hơn vận tốc của viên bi A."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Theo phương thẳng đứng cả 2 đều rơi tự do cùng độ cao h nên t = √(2h/g) như nhau.<br>• <b>Ý b [Đúng]:</b> t = √(2h/g) chỉ phụ thuộc độ cao h và g.<br>• <b>Ý c [Đúng]:</b> v<sub>A</sub> = v<sub>y</sub> = √(2gh); v<sub>B</sub> = √(v₀² + v<sub>y</sub>²) > v<sub>A</sub>.<br>• <b>Ý d [Sai]:</b> v₀ tăng chỉ làm tăng tầm xa L = v₀t, thời gian chạm đất t không đổi.","svgGraph":null},{"q":"Ghép các công thức của chuyển động ném ngang ở Cột A với ý nghĩa tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["t = √(2h / g) ➔ Vận tốc toàn phần tại thời điểm t","t = √(2h / g) ➔ Thời gian bay cho đến khi chạm đất","L = v₀ · √(2h / g) ➔ Vận tốc toàn phần tại thời điểm t","v = √(v₀² + g²t²) ➔ Thời gian bay cho đến khi chạm đất"],"ans":0,"exp":"• <b>1 - B:</b> t = √(2h/g).<br>• <b>2 - D:</b> L = v₀·t = v₀√(2h/g).<br>• <b>3 - A:</b> v = √(v<sub>x</sub>² + v<sub>y</sub>²) = √(v₀² + g²t²).<br>• <b>4 - C:</b> y = [g/(2v₀²)]·x².","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi ném một vật với vận tốc v₀ hợp với phương ngang một góc nhọn α, chuyển động của vật là chuyển động ném xiên. Quỹ đạo của vật có hình dạng một  [ ... ]  đối xứng. Tại điểm cao nhất của quỹ đạo (đỉnh), vận tốc của vật  [ ... ]  và có giá trị bằng  [ ... ] . Góc ném để đạt tầm xa cực đại trong không khí (bỏ qua lực cản) là  [ ... ] .\"</i>","opts":["đường parabol — chỉ còn thành phần nằm ngang","không đổi","triệt tiêu bằng 0 — α = 60°","chỉ còn thành phần nằm ngang — đường parabol"],"ans":0,"exp":"<b>Chuyển động ném xiên:</b><br>• Quỹ đạo parabol.<br>• Tại đỉnh: v<sub>y</sub> = 0 ⇒ v = v<sub>x</sub> = v₀·cos(α).<br>• Tầm xa L = (v₀²·sin(2α))/g cực đại khi sin(2α) = 1 ⇒ α = 45°.","svgGraph":null},{"q":"Một máy bay cứu trợ đang bay theo phương ngang ở độ cao h = 500 m với tốc độ 180 km/h (50 m/s) muốn thả một gói hàng rơi trúng vị trí người gặp nạn trên mặt đất. Lấy g = 10 m/s². Máy bay phải thả gói hàng khi còn cách vị trí người gặp nạn theo phương ngang một khoảng cách là:","opts":["500 m.","1000 m.","250 m.","750 m."],"ans":0,"exp":"• <b>Bước 1: Tính thời gian rơi của gói hàng:</b><br>t = √(<span class=\"fraction\"><span class=\"numerator\">2h</span><span class=\"denominator\">g</span></span>) = √(<span class=\"fraction\"><span class=\"numerator\">2 · 500</span><span class=\"denominator\">10</span></span>) = √100 = 10 s.<br>• <b>Bước 2: Tầm bay ngang của gói hàng:</b><br>L = v₀ · t = 50 · 10 = 500 m. Vậy phải thả trước 500 m.","svgGraph":null},{"q":"Một vật được ném ngang từ độ cao h với vận tốc v₀ = 10 m/s. Lấy g = 10 m/s². Sau 1 giây kể từ lúc ném, góc hợp bởi vectơ vận tốc tức thời của vật với phương ngang là:","opts":["45°.","30°.","60°.","90°."],"ans":0,"exp":"• <b>Thành phần vận tốc:</b> v<sub>x</sub> = v₀ = 10 m/s; v<sub>y</sub> = g·t = 10 · 1 = 10 m/s.<br>• <b>Góc hợp với phương ngang:</b> tan(β) = <span class=\"fraction\"><span class=\"numerator\">v<sub>y</sub></span><span class=\"denominator\">v<sub>x</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">10</span></span> = 1 ⇒ β = 45°.","svgGraph":null},{"q":"Một cầu thủ sút một quả bóng với vận tốc ban đầu v₀ = 20 m/s hợp với phương ngang một góc α = 30°. Lấy g = 10 m/s². Bỏ qua sức cản không khí. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tầm ném xa L của quả bóng khi chạm đất là 20 m.","Vận tốc ban đầu theo phương thẳng đứng là v<sub>0y</sub> = 10 m/s.","Thời gian quả bóng bay đến điểm cao nhất là 1,0 giây.","Độ cao cực đại H<sub>max</sub> mà quả bóng đạt được là 5 m."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> v<sub>0y</sub> = v₀·sin(30°) = 20 · 0,5 = 10 m/s.<br>• <b>Ý b [Đúng]:</b> t<sub>l</sub>ên = v<sub>0y</sub> / g = 10 / 10 = 1,0 s.<br>• <b>Ý c [Đúng]:</b> H = v<sub>0y</sub>² / (2g) = 10² / 20 = 5 m.<br>• <b>Ý d [Sai]:</b> L = (v₀²·sin(60°))/g = (400 · √3/2) / 10 = 20√3 ≈ 34,64 m (không phải 20 m).","svgGraph":null},{"q":"Trong các môn thể thao như ném lao, đẩy tạ, ném đĩa, yếu tố nào sau đây đóng vai trò quyết định nhiều nhất đến thành tích tầm xa của vận động viên?","opts":["Tốc độ giải phóng vật ném (v₀) và góc ném tối ưu (khoảng 38° - 44° tuỳ độ cao người ném).","Màu sắc của dụng cụ thi đấu phản xạ ánh sáng mặt trời.","Thời gian vận động viên khởi động trước trận đấu.","Nhiệt độ môi trường phòng thay đồ."],"ans":0,"exp":"• Tầm xa L tỉ lệ với bình phương vận tốc đầu v₀² (yếu tố quan trọng hàng đầu) kết hợp với việc lựa chọn góc ném tối ưu phù hợp với độ cao tay người ném.","svgGraph":null}],"13":[{"q":"Tổng hợp lực là phép thay thế hai hay nhiều lực tác dụng đồng thời vào một vật bằng một lực duy nhất có tác dụng:","opts":["Giống hệt như tác dụng của tất cả các lực thành phần đó.","Gấp đôi tác dụng của các lực thành phần ban đầu.","Làm triệt tiêu hoàn toàn chuyển động của vật.","Làm vật đổi hướng chuyển động sang phương vuông góc."],"ans":0,"exp":"• <b>Định nghĩa tổng hợp lực:</b> Tổng hợp lực là thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt như các lực ấy. Lực thay thế gọi là hợp lực: F = F₁ + F₂.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr13\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Origin point O -->\n      <circle cx=\"120\" cy=\"170\" r=\"6\" fill=\"#f8fafc\"/>\n      <text x=\"100\" y=\"180\" fill=\"#f8fafc\" font-size=\"13\" font-weight=\"bold\">O</text>\n      <!-- Force F1 (horizontal) -->\n      <line x1=\"120\" y1=\"170\" x2=\"280\" y2=\"170\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr13)\"/>\n      <text x=\"210\" y=\"190\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">F₁</text>\n      <!-- Force F2 (angled 45 deg) -->\n      <line x1=\"120\" y1=\"170\" x2=\"220\" y2=\"70\" stroke=\"#fbbf24\" stroke-width=\"3\" marker-end=\"url(#arr13)\"/>\n      <text x=\"155\" y=\"105\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">F₂</text>\n      <!-- Parallelogram dotted lines -->\n      <line x1=\"280\" y1=\"170\" x2=\"380\" y2=\"70\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n      <line x1=\"220\" y1=\"70\" x2=\"380\" y2=\"70\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n      <!-- Resultant Force F (diagonal) -->\n      <line x1=\"120\" y1=\"170\" x2=\"375\" y2=\"73\" stroke=\"#34d399\" stroke-width=\"3.5\" marker-end=\"url(#arr13)\"/>\n      <text x=\"260\" y=\"105\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">F (Hợp lực)</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Quy tắc hình bình hành tổng hợp hai lực đồng quy</text>\n    </svg>"},{"q":"Hai lực đồng quy F₁ và F₂ có độ lớn lần lượt là 6 N và 8 N, hợp với nhau một góc 90° (vuông góc nhau). Độ lớn hợp lực F của hai lực này là:","opts":["10 N.","14 N.","2 N.","48 N."],"ans":0,"exp":"• <b>Công thức góc vuông:</b> F = √(F₁² + F₂²)<br>• <b>Thay số:</b> F = √(6² + 8²) = √(36 + 64) = √100 = 10 N.","svgGraph":null},{"q":"Điều kiện cân bằng của một chất điểm chịu tác dụng của nhiều lực là:","opts":["Hợp lực của tất cả các lực tác dụng lên vật phải triệt tiêu bằng 0 (F = ∑F<sub>i</sub> = 0).","Tổng độ lớn của các lực tác dụng phải là một số dương cực đại.","Các lực tác dụng phải có cùng phương và cùng chiều.","Vật phải chuyển động với gia tốc lớn nhất có thể."],"ans":0,"exp":"• <b>Điều kiện cân bằng:</b> Một chất điểm ở trạng thái cân bằng khi và chỉ khi hợp lực của tất cả các lực tác dụng lên nó bằng 0: F = F₁ + F₂ + ... = 0.","svgGraph":null},{"q":"Cho hai lực đồng quy có độ lớn F₁ = 12 N và F₂ = 5 N. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ lớn hợp lực F có thể nhận giá trị bằng 20 N nếu góc hợp giữa hai lực thay đổi phù hợp.","Độ lớn hợp lực cực đại của hai lực này là F<sub>max</sub> = 17 N khi hai lực cùng hướng (α = 0°).","Độ lớn hợp lực cực tiểu của hai lực này là F<sub>min</sub> = 7 N khi hai lực ngược hướng (α = 180°).","Độ lớn của hợp lực luôn thoả mãn bất đẳng thức: |F₁ - F₂| ≤ F ≤ F₁ + F₂."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F<sub>max</sub> = F₁ + F₂ = 12 + 5 = 17 N.<br>• <b>Ý b [Đúng]:</b> F<sub>min</sub> = |F₁ - F₂| = 12 - 5 = 7 N.<br>• <b>Ý c [Sai]:</b> Hợp lực F chỉ nằm trong đoạn [7 N ; 17 N], không thể bằng 20 N.<br>• <b>Ý d [Đúng]:</b> |F₁ - F₂| ≤ F ≤ F₁ + F₂ là bất đẳng thức tam giác cho độ dài vectơ.","svgGraph":null},{"q":"Ghép góc hợp bởi hai lực đồng quy F₁ và F₂ ở Cột A với biểu thức độ lớn hợp lực F tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Góc α = 0° (hai lực cùng hướng) ➔ F = √(F₁² + F₂²)","Góc α = 0° (hai lực cùng hướng) ➔ F = F₁ + F₂","Góc α = 180° (hai lực ngược hướng) ➔ F = √(F₁² + F₂²)","Góc α = 90° (hai lực vuông góc) ➔ F = F₁ + F₂"],"ans":0,"exp":"• <b>1 - B:</b> Cùng hướng: F = F₁ + F₂.<br>• <b>2 - D:</b> Ngược hướng: F = |F₁ - F₂|.<br>• <b>3 - A:</b> Vuông góc: F = √(F₁² + F₂²).<br>• <b>4 - C:</b> Góc α bất kì: F = √(F₁² + F₂² + 2F₁F₂cosα).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Quy tắc hình bình hành phát biểu rằng: nếu hai lực đồng quy được biểu diễn bằng hai cạnh của một hình bình hành thì  [ ... ]  xuất phát từ gốc chung biểu diễn hợp lực. Phân tích lực là phép toán  [ ... ]  của tổng hợp lực. Khi phân tích một lực F thành hai thành phần vuông góc F<sub>x</sub> và F<sub>y</sub> trên hệ trục toạ độ Oxy, ta có  [ ... ]  và  [ ... ] .\"</i>","opts":["đường chéo — ngược lại","không đổi","cạnh đáy — song song","ngược lại — đường chéo"],"ans":0,"exp":"<b>Quy tắc hình bình hành và phân tích lực:</b><br>• Đường chéo là hợp lực.<br>• Phân tích lực là bài toán ngược.<br>• Chiếu lên trục toạ độ: F<sub>x</sub> = F·cosα, F<sub>y</sub> = F·sinα.","svgGraph":null},{"q":"Một vật có trọng lượng P = 20 N được giữ yên trên một mặt phẳng nghiêng góc α = 30° so với phương ngang bởi một sợi dây song song với mặt nghiêng. Bỏ qua ma sát. Lực căng T của sợi dây có độ lớn là:","opts":["10 N.","17,3 N.","20 N.","5 N."],"ans":0,"exp":"• <b>Phân tích trọng lực:</b> Thành phần trọng lực kéo vật trượt dọc theo mặt phẳng nghiêng là: P₁ = P·sin(α).<br>• Vì vật cân bằng nên lực căng dây: T = P₁ = P·sin(30°) = 20 · 0,5 = 10 N.","svgGraph":null},{"q":"Hai người cùng kéo một chiếc thuyền nhỏ bằng hai sợi dây tạo với phương chuyển động của thuyền các góc bằng nhau α = 30°. Lực kéo của mỗi người có độ lớn bằng nhau F₁ = F₂ = 100 N. Hợp lực kéo tác dụng lên thuyền theo phương chuyển động xấp xỉ bằng:","opts":["173 N.","200 N.","100 N.","141 N."],"ans":0,"exp":"• <b>Góc giữa hai lực:</b> θ = 2α = 60°.<br>• <b>Công thức hợp lực khi F₁ = F₂:</b> F = 2·F₁·cos(<span class=\"fraction\"><span class=\"numerator\">θ</span><span class=\"denominator\">2</span></span>) = 2 · 100 · cos(30°) = 200 · <span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 100√3 ≈ 173,2 N.","svgGraph":null},{"q":"Một bóng đèn khối lượng m = 1 kg được treo cân bằng vào trần nhà bằng hai sợi dây mảnh không dãn tạo với trần nhà các góc bằng nhau 45°. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu hạ thấp trần nhà để góc treo dẹp hơn (góc với trần giảm xuống gần 0°) thì lực căng dây sẽ giảm dần về 0.","Trọng lực tác dụng lên bóng đèn có độ lớn là P = 10 N hướng thẳng đứng xuống dưới.","Hợp lực của hai lực căng dây phải cân bằng trực đối với trọng lực P.","Độ lớn lực căng của mỗi sợi dây treo là T ≈ 7,07 N."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> P = mg = 1 · 10 = 10 N.<br>• <b>Ý b [Đúng]:</b> T₁ + T₂ + P = 0 ⇒ T₁ + T₂ = -P.<br>• <b>Ý c [Đúng]:</b> 2·T·sin(45°) = P ⇒ T = 10 / (2 · √2/2) = 10/√2 = 5√2 ≈ 7,07 N.<br>• <b>Ý d [Sai]:</b> sin(α) giảm về 0 thì T = P / (2·sinα) sẽ tiến tới vô cùng rất dễ làm đứt dây.","svgGraph":null},{"q":"Một chất điểm cân bằng dưới tác dụng của ba lực đồng quy F₁, F₂, F₃. Nếu giữ nguyên độ lớn và phương chiều của F₁ và F₂ nhưng bỏ đi lực F₃ thì hợp lực của hai lực còn lại là:","opts":["Một lực có cùng phương, cùng độ lớn nhưng ngược chiều với lực F₃.","Một lực có độ lớn bằng 0.","Một lực có cùng chiều hoàn toàn với lực F₃.","Một lực có độ lớn bằng tổng độ lớn (F₁ + F₂ + F₃)."],"ans":0,"exp":"• Vì F₁ + F₂ + F₃ = 0 ⇒ F₁₂ = F₁ + F₂ = -F₃. Hợp lực F₁₂ là vectơ trực đối với F₃.","svgGraph":null}],"14":[{"q":"Nội dung định luật 1 Newton phát biểu rằng:","opts":["Nếu một vật không chịu tác dụng của lực nào hoặc chịu tác dụng của các lực có hợp lực bằng không, thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều.","Gia tốc của một vật luôn tỉ lệ thuận với lực tác dụng và tỉ lệ nghịch với khối lượng của vật.","Trong mọi trường hợp tương tác, lực tác dụng luôn bằng phản lực nhưng ngược chiều.","Mọi vật trong tự nhiên đều có xu hướng dừng lại nếu không có lực duy trì chuyển động."],"ans":0,"exp":"• <b>Định luật 1 Newton:</b> Nếu hợp lực tác dụng lên vật bằng 0 (F = 0) thì gia tốc của vật a = 0; vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều ban đầu.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr14\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Bus outline braking -->\n      <rect x=\"100\" y=\"70\" width=\"280\" height=\"100\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\" rx=\"10\"/>\n      <!-- Bus wheels -->\n      <circle cx=\"160\" cy=\"170\" r=\"18\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <circle cx=\"320\" cy=\"170\" r=\"18\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <!-- Passenger leaning forward due to inertia -->\n      <circle cx=\"250\" cy=\"95\" r=\"9\" fill=\"#ef4444\"/>\n      <line x1=\"250\" y1=\"104\" x2=\"265\" y2=\"135\" stroke=\"#ef4444\" stroke-width=\"4\"/>\n      <line x1=\"265\" y1=\"135\" x2=\"260\" y2=\"160\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n      <!-- Motion and Braking Arrow -->\n      <line x1=\"200\" y1=\"45\" x2=\"280\" y2=\"45\" stroke=\"#38bdf8\" stroke-width=\"3\" marker-end=\"url(#arr14)\"/>\n      <text x=\"210\" y=\"38\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">v (xe chạy tới)</text>\n      <text x=\"280\" y=\"105\" fill=\"#fca5a5\" font-size=\"11\" font-weight=\"bold\">Hành khách chúi về phía trước</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Hiện tượng quán tính: hành khách chúi người khi xe phanh gấp</text>\n    </svg>"},{"q":"Quán tính là tính chất của mọi vật có xu hướng:","opts":["Bảo toàn vận tốc của nó cả về hướng và độ lớn.","Tự động tăng vận tốc khi không có ngoại lực tác dụng.","Biến đổi hình dạng liên tục trong không gian.","Dừng lại ngay lập tức khi thôi tác dụng lực."],"ans":0,"exp":"• <b>Định nghĩa quán tính:</b> Quán tính là tính chất bảo toàn trạng thái đứng yên hoặc chuyển động thẳng đều (bảo toàn vectơ vận tốc) của vật.","svgGraph":null},{"q":"Đại lượng vật lí nào sau đây là thước đo mức quán tính của một vật?","opts":["Khối lượng của vật.","Trọng lượng của vật.","Vận tốc chuyển động của vật.","Thể tích của vật."],"ans":0,"exp":"• Khối lượng là đại lượng đặc trưng cho mức quán tính của vật: vật có khối lượng càng lớn thì mức quán tính càng lớn (càng khó làm thay đổi vận tốc của nó).","svgGraph":null},{"q":"Về hiện tượng quán tính và định luật 1 Newton trong đời sống thực tế, xét tính Đúng / Sai của các hiện tượng sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực là nguyên nhân bắt buộc phải có để duy trì vận tốc chuyển động của một vật.","Khi ô tô đang chạy nhanh đột ngột phanh gấp, hành khách trên xe bị chúi người về phía trước theo quán tính.","Khi xe ô tô đột ngột rẽ nhanh sang bên trái, hành khách trên xe bị nghiêng người sang bên phải.","Đeo dây an toàn khi ngồi trên xe ô tô giúp giữ cơ thể không bị văng về phía trước khi có va chạm mạnh."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Thân người có quán tính bảo toàn vận tốc về phía trước.<br>• <b>Ý b [Đúng]:</b> Xe rẽ trái, thân người theo quán tính tiếp tục đi thẳng nên bị nghiêng sang phải so với xe.<br>• <b>Ý c [Sai]:</b> Lực không duy trì chuyển động; lực chỉ là nguyên nhân làm thay đổi vận tốc (gây ra gia tốc).<br>• <b>Ý d [Đúng]:</b> Dây an toàn giữ người gắn liền với ghế chống lại quán tính lao tới.","svgGraph":null},{"q":"Ghép hiện tượng ở Cột A với lời giải thích vật lí dựa vào quán tính ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Giũ mạnh quần áo ướt trước khi phơi ➔ Đầu búa theo quán tính tiếp tục dịch chuyển lún sâu vào cán","Giũ mạnh quần áo ướt trước khi phơi ➔ Giảm lực ma sát để duy trì trạng thái quán tính tốt hơn","Gõ mạnh đuôi cán búa xuống nền đất cứng ➔ Đầu búa theo quán tính tiếp tục dịch chuyển lún sâu vào cán","Vận động viên nhảy xa phải chạy đà thật nhanh ➔ Giảm lực ma sát để duy trì trạng thái quán tính tốt hơn"],"ans":0,"exp":"• <b>1 - D:</b> Giũ áo giọt nước văng theo quán tính.<br>• <b>2 - A:</b> Gõ cán búa đầu búa lún chặt vào cán.<br>• <b>3 - C:</b> Chạy đà tích luỹ vận tốc theo quán tính.<br>• <b>4 - B:</b> Tra dầu giảm ma sát bảo toàn vận tốc.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Hệ quy chiếu trong đó định luật 1 Newton nghiệm đúng được gọi là  [ ... ] . Hệ quy chiếu gắn với Trái Đất trong nhiều bài toán kĩ thuật thông thường được coi gần đúng là  [ ... ] . Một hệ quy chiếu chuyển động thẳng đều đối với hệ quy chiếu quán tính thì cũng là một  [ ... ] . Trong hệ quy chiếu có gia tốc (phi quán tính), xuất hiện thêm  [ ... ]  tác dụng lên các vật.\"</i>","opts":["hệ quy chiếu quán tính — hệ quy chiếu quán tính","không đổi","hệ quy chiếu phi quán tính — lực ma sát","không xác định"],"ans":0,"exp":"<b>Hệ quy chiếu quán tính:</b><br>• Định luật 1 đúng trong hệ quy chiếu quán tính.<br>• Hệ gắn Trái Đất coi gần đúng là quán tính.<br>• Hệ chuyển động thẳng đều đối với hệ quán tính cũng là quán tính.<br>• Hệ phi quán tính có lực quán tính F<sub>qt</sub> = -ma.","svgGraph":null},{"q":"Một tàu vũ trụ đang bay trong không gian sâu thẳm giữa các vì sao, rất xa mọi thiên thể lớn nên lực hấp dẫn coi như triệt tiêu hoàn toàn. Nếu động cơ tên lửa tắt hẳn thì con tàu sẽ:","opts":["Tiếp tục chuyển động thẳng đều mãi mãi với vận tốc không đổi.","Dừng lại ngay lập tức tại vị trí động cơ tắt.","Chuyển động chậm dần đều rồi dừng lại sau vài ngày.","Quay tròn tại chỗ vô hạn định."],"ans":0,"exp":"• Theo định luật 1 Newton: Trong không gian chân không không có lực cản và không có lực hấp dẫn (∑F = 0), con tàu bảo toàn vận tốc và bay thẳng đều vĩnh viễn.","svgGraph":null},{"q":"Một cuốn sách nằm yên trên mặt bàn nằm ngang. Cặp lực nào sau đây là hai lực cân bằng tác dụng lên cuốn sách?","opts":["Trọng lực của Trái Đất hút cuốn sách và phản lực của mặt bàn nâng cuốn sách.","Trọng lực của Trái Đất hút cuốn sách và lực hút của cuốn sách tác dụng lên Trái Đất.","Áp lực của cuốn sách đè lên bàn và phản lực của bàn nâng cuốn sách.","Trọng lực của cuốn sách và lực ma sát nghỉ giữa sách với bàn."],"ans":0,"exp":"• Cuốn sách cân bằng nên hai lực tác dụng trực tiếp lên cuốn sách là trọng lực P (hướng xuống) và phản lực N của mặt bàn (hướng lên) là hai lực cân bằng: P + N = 0.","svgGraph":null},{"q":"Một chiếc bút đặt trên một tờ giấy trên bàn. Khi giật thật nhanh tờ giấy theo phương ngang, chiếc bút hầu như vẫn đứng yên tại chỗ. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Thí nghiệm này chứng minh khối lượng của chiếc bút tự động biến mất khi giật nhanh.","Thời gian tác dụng của lực ma sát giữa giấy và bút trong thí nghiệm này là cực kì ngắn.","Do có quán tính, chiếc bút có xu hướng duy trì trạng thái đứng yên ban đầu của nó.","Nếu kéo tờ giấy thật từ từ chậm chạp thì chiếc bút sẽ chuyển động theo tờ giấy."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Thời gian tương tác Δt rất nhỏ nên xung lượng lực ma sát F·Δt không đủ tạo độ biến thiên vận tốc lớn.<br>• <b>Ý b [Đúng]:</b> Quán tính bảo toàn trạng thái đứng yên.<br>• <b>Ý c [Đúng]:</b> Kéo từ từ ma sát nghỉ đủ lớn kéo bút đi cùng giấy.<br>• <b>Ý d [Sai]:</b> Khối lượng là bất biến, không biến mất.","svgGraph":null},{"q":"Tại sao các xe tải chở hàng siêu trường, siêu trọng lại bị hạn chế tốc độ tối đa thấp hơn so với xe ô tô con du lịch trên các tuyến đường?","opts":["Vì xe tải có khối lượng rất lớn dẫn đến mức quán tính cực kì lớn, quãng đường phanh dừng xe sẽ rất dài nếu chạy nhanh.","Vì xe tải tiêu thụ nhiều nhiên liệu hơn khi chạy ở tốc độ cao.","Vì kích thước xe tải quá lớn làm cản trở tầm nhìn của camera phạt nguội.","Vì động cơ xe tải không thể đạt được tốc độ của xe con."],"ans":0,"exp":"• Khối lượng m lớn dẫn tới mức quán tính lớn, làm việc hãm dừng xe rất khó khăn; gia tốc hãm nhỏ khiến quãng đường phanh dài gây nguy cơ tai nạn nghiêm trọng.","svgGraph":null}],"15":[{"q":"Định luật 2 Newton phát biểu rằng gia tốc a của một vật có cùng hướng với lực tác dụng F và:","opts":["Tỉ lệ thuận với độ lớn của lực tác dụng và tỉ lệ nghịch với khối lượng của vật (a = F / m).","Tỉ lệ thuận với khối lượng của vật và tỉ lệ nghịch với độ lớn của lực.","Tỉ lệ thuận với bình phương của lực tác dụng lên vật.","Không phụ thuộc vào khối lượng mà chỉ phụ thuộc vào vận tốc ban đầu."],"ans":0,"exp":"• <b>Định luật 2 Newton:</b> a = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">m</span></span> hay F = m·a. Vectơ gia tốc luôn cùng hướng với vectơ hợp lực tác dụng lên vật.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr15\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Block on horizontal ground -->\n      <line x1=\"60\" y1=\"170\" x2=\"440\" y2=\"170\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <rect x=\"180\" y=\"110\" width=\"90\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\" rx=\"5\"/>\n      <text x=\"215\" y=\"145\" fill=\"#f8fafc\" font-size=\"16\" font-weight=\"bold\">m</text>\n      <!-- Force vector F -->\n      <line x1=\"270\" y1=\"140\" x2=\"380\" y2=\"140\" stroke=\"#fbbf24\" stroke-width=\"3.5\" marker-end=\"url(#arr15)\"/>\n      <text x=\"315\" y=\"130\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Lực F</text>\n      <!-- Acceleration vector a -->\n      <line x1=\"225\" y1=\"85\" x2=\"310\" y2=\"85\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr15)\"/>\n      <text x=\"245\" y=\"75\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Gia tốc a = F/m</text>\n      <!-- Vertical forces P and N -->\n      <line x1=\"225\" y1=\"140\" x2=\"225\" y2=\"205\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr15)\"/>\n      <text x=\"235\" y=\"200\" fill=\"#94a3b8\" font-size=\"11\">P</text>\n      <line x1=\"225\" y1=\"140\" x2=\"225\" y2=\"40\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr15)\"/>\n      <text x=\"235\" y=\"50\" fill=\"#94a3b8\" font-size=\"11\">N</text>\n      <text x=\"145\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Mô hình định luật 2 Newton: F = m·a</text>\n    </svg>"},{"q":"Một lực không đổi F = 20 N tác dụng lên một vật có khối lượng m = 4 kg đang đứng yên trên mặt sàn trơn nhẵn nằm ngang. Gia tốc mà vật thu được là:","opts":["5 m/s².","80 m/s².","0,2 m/s².","10 m/s²."],"ans":0,"exp":"• <b>Công thức định luật 2 Newton:</b> a = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">m</span></span><br>• <b>Thay số:</b> a = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">4</span></span> = 5 m/s².","svgGraph":null},{"q":"Trong hệ đơn vị SI, đơn vị lực Newton (N) được định nghĩa theo các đơn vị cơ bản là:","opts":["1 N = 1 kg·m/s².","1 N = 1 kg·m²/s².","1 N = 1 kg·m/s.","1 N = 1 g·cm/s²."],"ans":0,"exp":"• Từ F = m·a: đơn vị khối lượng là kg, gia tốc là m/s² ⇒ 1 N = 1 kg · 1 m/s² = 1 kg·m/s².","svgGraph":null},{"q":"Về định luật 2 Newton và mối quan hệ giữa lực và chuyển động, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu cùng tác dụng một lực F như nhau vào hai vật có khối lượng m₁ và m₂ (m₁ > m₂) thì vật m₁ sẽ thu được gia tốc lớn hơn.","Khi hợp lực tác dụng lên vật không đổi (F = const) thì vật chuyển động thẳng biến đổi đều.","Hướng của vectơ gia tốc luôn luôn trùng với hướng của vectơ hợp lực tác dụng lên vật.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F = const ⇒ a = F/m = const (chuyển động thẳng biến đổi đều).<br>• <b>Ý b [Sai]:</b> a = F/m tỉ lệ nghịch với m, nên m₁ > m₂ thì a₁ < a₂.<br>• <b>Ý c [Đúng]:</b> F = ma nên vectơ a và vectơ F luôn cùng hướng.<br>• <b>Ý d [Sai]:</b> Hợp lực bằng 0 thì a = 0, vật chuyển động thẳng đều tiếp tục theo quán tính chứ không dừng ngay.","svgGraph":null},{"q":"Ghép sự thay đổi của lực F và khối lượng m ở Cột A với sự thay đổi của gia tốc a ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Lực F tăng lên gấp đôi, khối lượng m giữ nguyên ➔ Gia tốc a giảm đi 2 lần","Lực F tăng lên gấp đôi, khối lượng m giữ nguyên ➔ Gia tốc a tăng lên 4 lần","Lực F giữ nguyên, khối lượng m tăng lên gấp đôi ➔ Gia tốc a giảm đi 2 lần","Cả lực F và khối lượng m đều tăng lên gấp đôi ➔ Gia tốc a tăng lên 4 lần"],"ans":0,"exp":"• <b>1 - D:</b> F' = 2F ⇒ a' = 2a.<br>• <b>2 - A:</b> m' = 2m ⇒ a' = a/2.<br>• <b>3 - C:</b> 2F / 2m = a (không đổi).<br>• <b>4 - B:</b> 2F / (m/2) = 4a (tăng 4 lần).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Định luật 2 Newton còn có thể diễn đạt dưới dạng: độ biến thiên  [ ... ]  của một vật trong một khoảng thời gian tỉ lệ thuận với xung lượng của  [ ... ] . Biểu thức toán học là  [ ... ] . Nếu tổng các lực tác dụng lên một vật bằng không thì  [ ... ]  của vật được bảo toàn.\"</i>","opts":["động lượng Δp — hợp lực: F · Δt","không đổi","thế năng — nhiệt năng","hợp lực: F · Δt — động lượng Δp"],"ans":0,"exp":"<b>Dạng tổng quát định luật 2:</b><br>• F = Δp/Δt hay Δp = F·Δt.<br>• F = 0 ⇒ Δp = 0 ⇒ p = const (bảo toàn động lượng).","svgGraph":null},{"q":"Một quả bóng khối lượng m = 500 g đang bay với vận tốc 10 m/s thì bị một cầu thủ sút trả ngược lại theo đúng phương cũ với vận tốc 15 m/s. Thời gian bóng tiếp xúc với chân cầu thủ là 0,05 s. Lực trung bình của cú sút tác dụng lên bóng là:","opts":["250 N.","50 N.","100 N.","150 N."],"ans":0,"exp":"• Chọn chiều dương là chiều bật lại của bóng: v₁ = -10 m/s; v₂ = +15 m/s.<br>• <b>Độ biến thiên vận tốc:</b> Δv = v₂ - v₁ = 15 - (-10) = 25 m/s.<br>• <b>Lực tác dụng:</b> F = m·<span class=\"fraction\"><span class=\"numerator\">Δv</span><span class=\"denominator\">Δt</span></span> = 0,5 · <span class=\"fraction\"><span class=\"numerator\">25</span><span class=\"denominator\">0,05</span></span> = 0,5 · 500 = 250 N.","svgGraph":null},{"q":"Một ô tô có khối lượng 1,2 tấn đang chạy với tốc độ 72 km/h (20 m/s) thì hãm phanh chuyển động chậm dần đều và dừng lại sau khi đi thêm được 50 m. Lực hãm phanh tác dụng lên xe là:","opts":["4800 N.","2400 N.","9600 N.","1200 N."],"ans":0,"exp":"• <b>Bước 1: Tính gia tốc hãm:</b><br>v² - v₀² = 2as ⇒ 0² - 20² = 2 · a · 50 ⇒ 100a = -400 ⇒ a = -4 m/s².<br>• <b>Bước 2: Tính độ lớn lực hãm phanh:</b><br>F<sub>h</sub>ãm = m·|a| = 1200 · 4 = 4800 N.","svgGraph":null},{"q":"Một vật có khối lượng m = 2 kg trượt trên sàn nằm ngang dưới tác dụng của lực kéo nằm ngang F<sub>k</sub> = 10 N. Lực ma sát cản trở chuyển động là F<sub>ms</sub> = 4 N. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu thôi tác dụng lực kéo F<sub>k</sub> (F<sub>k</sub> = 0) thì vật sẽ dừng lại ngay lập tức tại thời điểm đó.","Hợp lực tác dụng lên vật theo phương ngang là F<sub>hl</sub> = 6 N.","Gia tốc chuyển động của vật là a = 3 m/s².","Sau 4 giây kể từ lúc bắt đầu chuyển động từ trạng thái nghỉ, vận tốc của vật là 12 m/s."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F<sub>hl</sub> = F<sub>k</sub> - F<sub>ms</sub> = 10 - 4 = 6 N.<br>• <b>Ý b [Đúng]:</b> a = F<sub>hl</sub> / m = 6 / 2 = 3 m/s².<br>• <b>Ý c [Đúng]:</b> v = at = 3 · 4 = 12 m/s.<br>• <b>Ý d [Sai]:</b> Thôi lực kéo thì chỉ còn ma sát F<sub>ms</sub> = 4N gây gia tốc hãm a' = -2 m/s², vật sẽ chuyển động chậm dần đều thêm một đoạn rồi mới dừng.","svgGraph":null},{"q":"Hệ túi khí (Airbag) trên ô tô bung ra trong các vụ va chạm giao thông nhằm mục đích vật lí cơ bản nào?","opts":["Kéo dài thời gian va chạm Δt của người với vô lăng, từ đó làm giảm lực va đập F = Δp / Δt tác dụng lên cơ thể.","Làm tăng khối lượng của người lái xe để tăng mức quán tính.","Triệt tiêu hoàn toàn động lượng của xe ô tô trong 0,001 giây.","Làm mát nhiệt độ cabin xe sau khi va chạm."],"ans":0,"exp":"• Theo định luật 2 Newton: F = Δp / Δt. Với cùng một độ biến thiên động lượng Δp, túi khí làm tăng thời gian hãm dừng Δt lên hàng chục lần giúp lực cản tác dụng lên đầu và ngực người giảm đi rất nhiều, hạn chế chấn thương tử vong.","svgGraph":null}],"16":[{"q":"Theo định luật 3 Newton, trong mọi trường hợp khi vật A tác dụng lên vật B một lực, thì vật B cũng tác dụng lại vật A một lực. Hai lực này là hai lực:","opts":["Trực đối: cùng phương, cùng độ lớn nhưng ngược chiều và đặt vào hai vật khác nhau.","Cân bằng: cùng đặt vào một vật và triệt tiêu lẫn nhau.","Cùng phương, cùng chiều và cùng độ lớn.","Có độ lớn tỉ lệ nghịch với khối lượng của hai vật tương tác."],"ans":0,"exp":"• <b>Định luật 3 Newton:</b> F<sub>AB</sub> = -F<sub>BA</sub>. Lực và phản lực luôn xuất hiện và mất đi đồng thời thành từng cặp; chúng có cùng bản chất, cùng giá, ngược chiều, cùng độ lớn nhưng đặt vào hai vật khác nhau nên không bao giờ triệt tiêu lẫn nhau.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr16\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Body A -->\n      <circle cx=\"160\" cy=\"120\" r=\"35\" fill=\"#1e293b\" stroke=\"#ef4444\" stroke-width=\"2.5\"/>\n      <text x=\"140\" y=\"125\" fill=\"#fca5a5\" font-size=\"16\" font-weight=\"bold\">Vật A</text>\n      <!-- Body B -->\n      <circle cx=\"340\" cy=\"120\" r=\"35\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2.5\"/>\n      <text x=\"320\" y=\"125\" fill=\"#93c5fd\" font-size=\"16\" font-weight=\"bold\">Vật B</text>\n      <!-- Force F₂₁ (B acts on A, points to left) -->\n      <line x1=\"160\" y1=\"120\" x2=\"60\" y2=\"120\" stroke=\"#ef4444\" stroke-width=\"3.5\" marker-end=\"url(#arr16)\"/>\n      <text x=\"70\" y=\"105\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">F₂₁</text>\n      <!-- Force F₁₂ (A acts on B, points to right) -->\n      <line x1=\"340\" y1=\"120\" x2=\"440\" y2=\"120\" stroke=\"#3b82f6\" stroke-width=\"3.5\" marker-end=\"url(#arr16)\"/>\n      <text x=\"380\" y=\"105\" fill=\"#3b82f6\" font-size=\"13\" font-weight=\"bold\">F₁₂</text>\n      <text x=\"180\" y=\"80\" fill=\"#fbbf24\" font-size=\"15\" font-weight=\"bold\">F₁₂ = -F₂₁</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Cặp lực và phản lực tương tác trực đối theo Định luật 3 Newton</text>\n    </svg>"},{"q":"Tại sao lực và phản lực trong định luật 3 Newton KHÔNG THỂ cân bằng và triệt tiêu lẫn nhau?","opts":["Vì chúng tác dụng lên hai vật hoàn toàn khác nhau.","Vì độ lớn của chúng luôn khác nhau.","Vì phương tác dụng của chúng vuông góc với nhau.","Vì chúng không xuất hiện cùng một thời điểm."],"ans":0,"exp":"• Hai lực cân bằng phải cùng đặt lên một vật thể duy nhất. Cặp lực và phản lực đặt lên hai vật tương tác riêng biệt nên chúng không thể tự triệt tiêu nhau.","svgGraph":null},{"q":"Một con ngựa kéo một cỗ xe chuyển động về phía trước trên đường. Theo định luật 3 Newton, lực mà cỗ xe tác dụng lên con ngựa có độ lớn:","opts":["Luôn luôn bằng độ lớn lực mà con ngựa tác dụng lên cỗ xe.","Nhỏ hơn lực mà con ngựa tác dụng lên cỗ xe nên xe mới chạy tới được.","Lớn hơn lực con ngựa tác dụng lên cỗ xe.","Bằng không vì xe bị kéo đi một cách thụ động."],"ans":0,"exp":"• Theo định luật 3 Newton, trong mọi trạng thái (đứng yên, tăng tốc, chuyển động đều), lực ngựa kéo xe luôn có độ lớn bằng lực xe kéo lại ngựa. Xe chạy tới được là nhờ hợp lực tác dụng lên xe dương (lực kéo > ma sát) và hợp lực lên ngựa dương (lực ma sát đất đẩy chân ngựa > lực xe kéo lại).","svgGraph":null},{"q":"Về các đặc điểm của cặp lực và phản lực trong định luật 3 Newton, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trái Đất có khối lượng khổng lồ nên gia tốc mà nó thu được khi hút quả táo là bằng với gia tốc của quả táo.","Lực và phản lực luôn xuất hiện đồng thời và mất đi đồng thời.","Lực và phản lực luôn cùng bản chất vật lí (ví dụ: cùng là lực hấp dẫn, hoặc cùng là lực đàn hồi tĩnh điện).","Khi Trái Đất hút một quả táo rơi xuống thì quả táo cũng hút Trái Đất một lực có cùng độ lớn."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Xuất hiện và mất đi đồng thời.<br>• <b>Ý b [Đúng]:</b> Luôn cùng bản chất vật lí.<br>• <b>Ý c [Đúng]:</b> F<sub>T</sub>Đ/táo = F<sub>t</sub>áo/TĐ theo định luật 3.<br>• <b>Ý d [Sai]:</b> a<sub>T</sub>Đ = F / M<sub>T</sub>Đ ≈ 0 do khối lượng Trái Đất M<sub>T</sub>Đ ≈ 6·10²⁴ kg cực lớn.","svgGraph":null},{"q":"Ghép hành động ở Cột A với phản lực tạo ra chuyển động tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Người bơi lội dùng tay gạt nước về phía sau ➔ Lực đẩy của dòng khí phụt đẩy tên lửa bay vọt về phía trước","Người bơi lội dùng tay gạt nước về phía sau ➔ Lực đẩy của nước đẩy mái chèo và thuyền tiến về phía trước","Vận động viên bật nhảy đạp mạnh chân xuống mặt đất ➔ Lực đẩy của dòng khí phụt đẩy tên lửa bay vọt về phía trước","Tên lửa phụt khí đốt cháy phụt mạnh về phía sau ➔ Lực đẩy của nước đẩy mái chèo và thuyền tiến về phía trước"],"ans":0,"exp":"• <b>1 - C:</b> Gạt nước sau, nước đẩy người tới.<br>• <b>2 - D:</b> Đạp đất, đất đẩy người bật lên.<br>• <b>3 - A:</b> Khí phụt sau, phản lực đẩy tên lửa tới.<br>• <b>4 - B:</b> Đẩy nước sau, nước đẩy thuyền tới.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Chuyển động bằng phản lực là chuyển động của một vật tự tách ra thành  [ ... ]  phần chuyển động ngược chiều nhau. Khi tên lửa hoạt động, buồng đốt sinh khí áp suất cực cao phụt mạnh qua ống xả về phía sau, theo định luật 3 Newton, dòng khí tác dụng  [ ... ]  đẩy thân tên lửa bay vọt về phía trước. Chuyển động phản lực có thể hoạt động hoàn hảo trong môi trường  [ ... ]  vì không cần điểm tựa vào không khí. Đây là cơ sở cho các động cơ  [ ... ]  vũ trụ.\"</i>","opts":["hai — phản lực","không đổi","ba — trọng lực","phản lực — hai"],"ans":0,"exp":"<b>Chuyển động phản lực:</b><br>• Tách 2 phần ngược chiều.<br>• Khí phụt sau sinh phản lực đẩy thân tới.<br>• Hoạt động tốt trong chân không.<br>• Động cơ tên lửa không gian.","svgGraph":null},{"q":"Một người có khối lượng m = 60 kg đứng trên một tấm ván trượt trên mặt băng trơn trượt ném một quả tạ khối lượng M = 3 kg về phía trước với vận tốc v = 8 m/s. Bỏ qua ma sát với mặt băng. Vận tốc giật lùi của người và ván trượt ngay sau khi ném là:","opts":["-0,4 m/s.","-0,8 m/s.","-1,2 m/s.","-2,4 m/s."],"ans":0,"exp":"• <b>Bảo toàn động lượng:</b> m·V + M·v = 0<br>• <b>Vận tốc giật lùi:</b> V = -<span class=\"fraction\"><span class=\"numerator\">M·v</span><span class=\"denominator\">m</span></span> = -<span class=\"fraction\"><span class=\"numerator\">3 · 8</span><span class=\"denominator\">60</span></span> = -<span class=\"fraction\"><span class=\"numerator\">24</span><span class=\"denominator\">60</span></span> = -0,4 m/s.","svgGraph":null},{"q":"Một quả bóng tennis va đập vào bức tường bê tông với lực tác dụng lên tường là F = 400 N trong thời gian 0,02 s. Lực mà bức tường tác dụng ngược lại quả bóng có độ lớn là:","opts":["400 N.","200 N.","800 N.","0 N."],"ans":0,"exp":"• Theo định luật 3 Newton, lực tường tác dụng lên bóng luôn có độ lớn bằng đúng lực bóng tác dụng lên tường: |F<sub>tb</sub>| = |F<sub>bt</sub>| = 400 N.","svgGraph":null},{"q":"Một khẩu súng trường có khối lượng M = 4 kg bắn một viên đạn khối lượng m = 10 g với vận tốc ban đầu v = 600 m/s. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực mà thuốc súng đẩy viên đạn lớn hơn lực mà viên đạn đẩy súng lùi lại.","Động lượng của viên đạn ngay khi rời nòng súng là p = 6 kg·m/s.","Vận tốc giật lùi của báng súng khi bắn là V = -1,5 m/s.","Người bắn súng cần tì chặt báng súng vào vai để tăng khối lượng tiếp nhận độ giật, giảm vận tốc giật lùi tránh chấn thương."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> p = m·v = 0,01 · 600 = 6 kg·m/s.<br>• <b>Ý b [Đúng]:</b> V = -p / M = -6 / 4 = -1,5 m/s.<br>• <b>Ý c [Sai]:</b> Lực tác dụng và phản lực giữa khí súng, đạn và thân súng luôn có cùng độ lớn theo định luật 3.<br>• <b>Ý d [Đúng]:</b> Tì vai làm khối lượng hệ tăng lên (M<sub>s</sub>úng + M<sub>ng</sub>ười) khiến vận tốc giật giảm mạnh.","svgGraph":null},{"q":"Khi bước từ một chiếc thuyền nhỏ không cột dây lên cầu cảng, người ta thấy chiếc thuyền bị đẩy lùi ra xa bờ. Hiện tượng này là do:","opts":["Chân người khi đạp về phía sau để tiến lên đã tác dụng một lực đẩy ngược lại lên thuyền theo định luật 3 Newton.","Gió thổi từ trên bờ đẩy chiếc thuyền trôi ra xa.","Dòng nước dưới đáy thuyền tự động sinh ra lực xoáy hút thuyền.","Chiếc thuyền có khối lượng âm so với cơ thể người."],"ans":0,"exp":"• Muốn tiến về trước, chân người tác dụng lực đẩy ra phía sau lên sàn thuyền. Phản lực của thuyền đẩy người tới bờ, đồng thời lực của chân đẩy thuyền dạt lùi ra xa.","svgGraph":null}],"17":[{"q":"Trọng lực tác dụng lên một vật là lực hấp dẫn giữa Trái Đất và vật đó, có đặc điểm:","opts":["Phương thẳng đứng, chiều từ trên xuống dưới và đặt tại trọng tâm của vật.","Phương nằm ngang, chiều theo chiều chuyển động của vật.","Phương tiếp tuyến với quỹ đạo và đặt tại điểm tiếp xúc.","Phương xiên 45° hướng về phía tâm của xích đạo."],"ans":0,"exp":"• <b>Đặc điểm của trọng lực:</b> Trọng lực P là lực hút của Trái Đất tác dụng lên vật; có phương thẳng đứng, chiều từ trên xuống dưới, điểm đặt tại trọng tâm của vật và độ lớn gọi là trọng lượng: P = m·g.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr17\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ceiling horizontal line -->\n      <line x1=\"160\" y1=\"30\" x2=\"340\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <!-- Rope vertical line -->\n      <line x1=\"250\" y1=\"30\" x2=\"250\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n      <!-- Suspended Block -->\n      <rect x=\"220\" y=\"120\" width=\"60\" height=\"50\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <!-- Center of gravity dot G -->\n      <circle cx=\"250\" cy=\"145\" r=\"4\" fill=\"#f8fafc\"/>\n      <text x=\"260\" y=\"148\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">G</text>\n      <!-- Tension vector T (upward) -->\n      <line x1=\"250\" y1=\"120\" x2=\"250\" y2=\"60\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr17)\"/>\n      <text x=\"260\" y=\"80\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Lực căng T</text>\n      <!-- Gravity vector P (downward) -->\n      <line x1=\"250\" y1=\"145\" x2=\"250\" y2=\"215\" stroke=\"#ef4444\" stroke-width=\"3\" marker-end=\"url(#arr17)\"/>\n      <text x=\"260\" y=\"200\" fill=\"#ef4444\" font-size=\"13\" font-weight=\"bold\">Trọng lực P</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Vật treo cân bằng dưới tác dụng của Trọng lực P và Lực căng T</text>\n    </svg>"},{"q":"Khối lượng m và trọng lượng P của một vật liên hệ với nhau qua công thức:","opts":["P = m · g.","P = m / g.","m = P · g.","P = m · g²."],"ans":0,"exp":"• Trọng lượng P là độ lớn của trọng lực tác dụng lên vật: P = m·g, trong đó m đo bằng kg, g đo bằng m/s² và P đo bằng Newton (N).","svgGraph":null},{"q":"Lực căng dây xuất hiện tại các điểm trên sợi dây mềm đàn hồi khi bị kéo căng có đặc điểm:","opts":["Có phương trùng với phương của sợi dây, chiều hướng từ hai đầu dây vào phần giữa của sợi dây.","Có phương vuông góc với sợi dây hướng ra ngoài không gian.","Luôn có chiều hướng thẳng đứng lên trên bất kể dây đặt theo phương nào.","Có độ lớn thay đổi liên tục dọc theo chiều dài của một sợi dây nhẹ lý tưởng."],"ans":0,"exp":"• Lực căng dây xuất hiện chống lại sự dãn; phương trùng với sợi dây, chiều hướng từ điểm liên kết vào trong lòng sợi dây để kéo giữ các vật nối.","svgGraph":null},{"q":"Về trọng lực, trọng tâm và trạng thái không trọng lượng, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi một phi hành gia ở trên trạm vũ trụ ISS quay quanh Trái Đất, lực hấp dẫn của Trái Đất tác dụng lên phi hành gia hoàn toàn biến mất bằng 0.","Trọng tâm của các vật phẳng đồng chất, có dạng hình học đối xứng thường trùng với tâm đối xứng hình học của vật.","Hiện tượng không trọng lượng xảy ra khi con tàu và phi hành gia rơi tự do liên tục quanh Trái Đất nên không còn lực ép lên sàn trạm.","Khối lượng của một vật thể không đổi khi đưa từ Trái Đất lên Mặt Trăng, nhưng trọng lượng của nó giảm đi khoảng 6 lần."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tâm đối xứng của hình tròn, hình vuông, quả cầu đồng chất chính là trọng tâm.<br>• <b>Ý b [Sai]:</b> Lực hấp dẫn vẫn rất lớn (khoảng 90% ở mặt đất), chính lực hấp dẫn này đóng vai trò lực hướng tâm duy trì quỹ đạo.<br>• <b>Ý c [Đúng]:</b> Rơi tự do cùng gia tốc g nên áp lực lên sàn bằng 0 tạo cảm giác không trọng lượng.<br>• <b>Ý d [Đúng]:</b> m = const, g<sub>MT</sub> ≈ g<sub>T</sub>Đ / 6 ⇒ P<sub>MT</sub> ≈ P<sub>T</sub>Đ / 6.","svgGraph":null},{"q":"Ghép tình huống cân bằng hoặc chuyển động ở Cột A với độ lớn lực căng dây T ở Cột B (vật khối lượng m treo vào sợi dây):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vật đứng yên cân bằng hoặc chuyển động thẳng đều ➔ T = m·(g - a)","Vật đứng yên cân bằng hoặc chuyển động thẳng đều ➔ T = m·(g + a)","Dây kéo vật chuyển động thẳng nhanh dần đều đi lên với gia tốc a ➔ T = m·(g - a)","Dây giữ vật chuyển động chậm dần đều đi lên với gia tốc a ➔ T = m·(g + a)"],"ans":0,"exp":"• <b>1 - D:</b> Đứng yên: T = P = mg.<br>• <b>2 - B:</b> Đi lên nhanh dần: T - P = ma ⇒ T = m(g+a).<br>• <b>3 - A:</b> Đi lên chậm dần: P - T = ma ⇒ T = m(g-a).<br>• <b>4 - C:</b> Rơi tự do: a = g ⇒ T = m(g-g) = 0.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Để xác định trọng tâm của một vật phẳng mỏng có hình dạng bất kì, ta có thể dùng phương pháp  [ ... ] . Treo vật tại một điểm A bất kì trên mép, khi vật đứng yên cân bằng thì trọng tâm G phải nằm trên  [ ... ]  đi qua A. Tiếp tục treo vật tại một điểm B khác, kẻ đường thẳng đứng thứ hai đi qua B. Trọng tâm G chính là  [ ... ]  của hai đường thẳng này. Trọng tâm có thể nằm  [ ... ]  phần vật chất của vật (ví dụ như tâm của một chiếc nhẫn tròn).\"</i>","opts":["buộc dây treo — đường thẳng đứng kéo dài","không đổi","bên trong — đo thể tích","đường thẳng đứng kéo dài — buộc dây treo"],"ans":0,"exp":"<b>Phương pháp dây dọi tìm trọng tâm:</b><br>• Treo vật bằng dây mềm.<br>• Trọng tâm nằm trên đường thẳng đứng qua điểm treo.<br>• Giao điểm 2 lần treo là trọng tâm G.<br>• Trọng tâm có thể ở ngoài phần vật chất (chiếc nhẫn, vành xe).","svgGraph":null},{"q":"Một vật có khối lượng m = 5 kg được treo bằng một sợi dây chịu được lực căng tối đa T<sub>max</sub> = 70 N. Lấy g = 10 m/s². Gia tốc kéo lên lớn nhất mà sợi dây có thể chịu được mà không bị đứt là:","opts":["4 m/s².","14 m/s².","2 m/s².","10 m/s²."],"ans":0,"exp":"• <b>Phương trình định luật 2 khi kéo lên:</b> T - mg = ma ⇒ a = <span class=\"fraction\"><span class=\"numerator\">T - mg</span><span class=\"denominator\">m</span></span><br>• <b>Thay giá trị cực đại:</b> a<sub>max</sub> = <span class=\"fraction\"><span class=\"numerator\">70 - 5 · 10</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">70 - 50</span><span class=\"denominator\">5</span></span> = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">5</span></span> = 4 m/s².","svgGraph":null},{"q":"Một người có khối lượng m = 60 kg đứng trên một bàn cân lò xo đặt trong buồng thang máy. Lấy g = 10 m/s². Khi thang máy chuyển động nhanh dần đều đi xuống với gia tốc a = 2 m/s², số chỉ của bàn cân là:","opts":["480 N (tương đương 48 kg).","720 N (tương đương 72 kg).","600 N (tương đương 60 kg).","120 N."],"ans":0,"exp":"• <b>Đi xuống nhanh dần đều:</b> Trọng lực thắng phản lực sàn: P - N = ma ⇒ N = m(g - a).<br>• <b>Thay số:</b> N = 60 · (10 - 2) = 60 · 8 = 480 N (số chỉ cân giảm).","svgGraph":null},{"q":"Hai vật có khối lượng m₁ = 2 kg và m₂ = 3 kg được nối với nhau bằng một sợi dây nhẹ không dãn vắt qua một ròng rọc cố định lí tưởng (máy Atwood). Thả cho hệ tự do chuyển động từ trạng thái nghỉ. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực căng dây T luôn luôn bằng đúng trọng lượng P₂ của vật nặng m₂.","Vật m₂ có khối lượng lớn hơn sẽ chuyển động đi xuống nhanh dần đều, vật m₁ đi lên nhanh dần đều với cùng độ lớn gia tốc.","Gia tốc chuyển động của hệ là a = 2 m/s².","Lực căng của sợi dây trong quá trình hệ chuyển động là T = 24 N."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Dây không dãn nối 2 vật qua ròng rọc nên a₁ = a₂ = a.<br>• <b>Ý b [Đúng]:</b> a = (m₂ - m₁)g / (m₁ + m₂) = (3 - 2)·10 / (2 + 3) = 10/5 = 2 m/s².<br>• <b>Ý c [Đúng]:</b> T = m₁(g + a) = 2 · (10 + 2) = 24 N (hoặc T = m₂(g - a) = 3 · 8 = 24 N).<br>• <b>Ý d [Sai]:</b> T = 24 N < P₂ = 30 N (vì vật m₂ tăng tốc đi xuống nên P₂ phải lớn hơn T).","svgGraph":null},{"q":"Một sợi dây dù có độ bền giới hạn chịu được lực căng cực đại là 1500 N. Một người leo núi có khối lượng cả người và ba lô là 75 kg. Lấy g = 10 m/s². Hệ số an toàn n (tỉ số giữa lực căng cực đại chịu được và trọng lượng của người) là:","opts":["2,0 lần.","1,5 lần.","3,0 lần.","0,5 lần."],"ans":0,"exp":"• <b>Trọng lượng người và đồ:</b> P = mg = 75 · 10 = 750 N.<br>• <b>Hệ số an toàn:</b> n = <span class=\"fraction\"><span class=\"numerator\">T<sub>max</sub></span><span class=\"denominator\">P</span></span> = <span class=\"fraction\"><span class=\"numerator\">1500</span><span class=\"denominator\">750</span></span> = 2,0 lần.","svgGraph":null}],"18":[{"q":"Lực ma sát trượt xuất hiện ở mặt tiếp xúc giữa hai vật khi:","opts":["Vật này trượt trên bề mặt của vật kia, có hướng ngược hướng vận tốc tương đối.","Vật này lăn trên bề mặt của vật kia không có trượt.","Một vật có xu hướng chuyển động nhưng chưa chuyển động được.","Hai vật đặt cách xa nhau trong không gian chân không."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Lực ma sát trượt xuất hiện ở bề mặt tiếp xúc khi một vật trượt trên bề mặt của một vật khác; nó có phương tiếp tuyến với mặt tiếp xúc và có chiều ngược chiều chuyển động tương đối của vật.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr18\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ground line with hatch -->\n      <line x1=\"60\" y1=\"160\" x2=\"440\" y2=\"160\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Block sliding right -->\n      <rect x=\"180\" y=\"100\" width=\"100\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"220\" y=\"135\" fill=\"#f8fafc\" font-size=\"14\" font-weight=\"bold\">Vật m</text>\n      <!-- Pulling Force F<tspan baseline-shift=\"sub\" font-size=\"70%\">k</tspan> -->\n      <line x1=\"280\" y1=\"130\" x2=\"380\" y2=\"130\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr18)\"/>\n      <text x=\"320\" y=\"120\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Lực kéo F</text>\n      <!-- Friction Force F_mst (at contact surface) -->\n      <line x1=\"180\" y1=\"160\" x2=\"80\" y2=\"160\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr18)\"/>\n      <text x=\"90\" y=\"150\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">F<tspan baseline-shift=\"sub\" font-size=\"70%\">ms</tspan> = μ · N</text>\n      <!-- Normal force N and Gravity P -->\n      <line x1=\"230\" y1=\"100\" x2=\"230\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr18)\"/>\n      <text x=\"240\" y=\"55\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Áp lực N</text>\n      <line x1=\"230\" y1=\"130\" x2=\"230\" y2=\"210\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr18)\"/>\n      <text x=\"240\" y=\"200\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Trọng lực P</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Lực ma sát trượt ngược chiều chuyển động tương đối</text>\n    </svg>"},{"q":"Độ lớn của lực ma sát trượt F<sub>mst</sub> phụ thuộc vào những yếu tố nào?","opts":["Bản chất, tình trạng bề mặt tiếp xúc và áp lực N ép lên bề mặt tiếp xúc.","Diện tích tiếp xúc bề mặt và tốc độ trượt của vật.","Vận tốc trượt càng nhanh thì lực ma sát trượt càng tăng vọt.","Chỉ phụ thuộc vào hình dạng kích thước khối học của vật."],"ans":0,"exp":"• <b>Công thức ma sát trượt:</b> F<sub>mst</sub> = μ_t·N. Độ lớn của lực ma sát trượt tỉ lệ với độ lớn của áp lực N, phụ thuộc vào vật liệu và tình trạng bề mặt tiếp xúc (thể hiện qua hệ số μ_t); không phụ thuộc vào diện tích tiếp xúc và vận tốc của vật.","svgGraph":null},{"q":"Một vật có khối lượng m = 10 kg đang trượt trên mặt sàn nằm ngang. Hệ số ma sát trượt giữa vật và sàn là μ_t = 0,25. Lấy g = 10 m/s². Độ lớn của lực ma sát trượt tác dụng lên vật là:","opts":["25 N.","2,5 N.","250 N.","40 N."],"ans":0,"exp":"• <b>Áp lực mặt sàn nằm ngang:</b> N = P = m·g = 10 · 10 = 100 N.<br>• <b>Lực ma sát trượt:</b> F<sub>mst</sub> = μ_t·N = 0,25 · 100 = 25 N.","svgGraph":null},{"q":"Về lực ma sát nghỉ và lực ma sát lăn, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ lớn của lực ma sát nghỉ luôn luôn là một hằng số không bao giờ thay đổi.","Lực ma sát nghỉ xuất hiện khi có ngoại lực tác dụng có xu hướng làm vật chuyển động nhưng vật vẫn đứng yên.","Lực ma sát nghỉ đóng vai trò là lực phát động giúp người và xe cộ có thể bước đi và chuyển động trên mặt đường.","Hệ số ma sát lăn thường nhỏ hơn hệ số ma sát trượt hàng chục lần nên người ta dùng con lăn hoặc ổ bi để giảm ma sát."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Định nghĩa ma sát nghỉ.<br>• <b>Ý b [Sai]:</b> Lực ma sát nghỉ biến thiên: 0 ≤ F<sub>msn</sub> ≤ F<sub>msn</sub>_max = μ_n·N.<br>• <b>Ý c [Đúng]:</b> Chân đạp đất về sau, ma sát nghỉ của đất đẩy chân tới trước.<br>• <b>Ý d [Đúng]:</b> Ma sát lăn rất nhỏ so với ma sát trượt, thay trượt bằng lăn trong ổ bi.","svgGraph":null},{"q":"Ghép loại lực ma sát ở Cột A với đặc điểm hoặc ứng dụng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Lực ma sát nghỉ cực đại ➔ Xuất hiện khi vật này lăn trên mặt vật khác, cản trở chuyển động lăn","Lực ma sát nghỉ cực đại ➔ Làm mòn chi tiết máy và tiêu hao công cơ học, cần bôi trơn dầu mỡ","Lực ma sát trượt ➔ Xuất hiện khi vật này lăn trên mặt vật khác, cản trở chuyển động lăn","Lực ma sát lăn ➔ Làm mòn chi tiết máy và tiêu hao công cơ học, cần bôi trơn dầu mỡ"],"ans":0,"exp":"• <b>1 - C:</b> F<sub>msn</sub>_max là ngưỡng bắt đầu trượt.<br>• <b>2 - D:</b> F<sub>mst</sub> = μ_t·N.<br>• <b>3 - A:</b> Ma sát lăn cản trở lăn.<br>• <b>4 - B:</b> Ma sát làm mòn chi tiết máy cần bôi trơn.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Nếu không có ma sát nghỉ, chúng ta sẽ không thể  [ ... ]  trên mặt đất và đinh không thể  [ ... ]  trong tường. Tuy nhiên, ma sát trượt trong các ổ trục làm máy móc  [ ... ]  và nóng lên, làm giảm  [ ... ]  của máy móc.\"</i>","opts":["đi lại được — giữ chặt","không đổi","bay lên — trơn trượt","giữ chặt — đi lại được"],"ans":0,"exp":"<b>Vai trò của ma sát:</b><br>• Có ích: giúp người đi lại, giữ đinh ốc vít, phanh xe.<br>• Có hại: mài mòn chi tiết, sinh nhiệt làm giảm hiệu suất.","svgGraph":null},{"q":"Một thùng hàng nặng 40 kg đặt trên sàn nhà có hệ số ma sát nghỉ cực đại μ_n = 0,4. Lấy g = 10 m/s². Một người dùng lực F<sub>k</sub> = 120 N theo phương ngang để đẩy thùng hàng. Lực ma sát tác dụng lên thùng hàng khi đó là:","opts":["120 N (ma sát nghỉ).","160 N.","40 N.","0 N."],"ans":0,"exp":"• <b>Lực ma sát nghỉ cực đại:</b> F<sub>msn</sub>_max = μ_n·mg = 0,4 · 40 · 10 = 160 N.<br>• Vì lực kéo F<sub>k</sub> = 120 N < 160 N nên thùng hàng chưa chuyển động (đứng yên).<br>• Theo điều kiện cân bằng: F<sub>msn</sub> = F<sub>k</sub> = 120 N.","svgGraph":null},{"q":"Tác dụng của các rãnh khía trên bề mặt lốp xe máy, ô tô là gì?","opts":["Tăng độ bám đường và thoát nước nhanh khi trời mưa để duy trì lực ma sát an toàn.","Giảm khối lượng của bánh xe giúp xe chạy nhẹ hơn.","Tạo tiếng rít vui tai khi xe vào cua ở tốc độ cao.","Làm giảm áp lực của xe lên mặt đường nhựa."],"ans":0,"exp":"• Hoa lốp và các rãnh thoát nước giúp tống khứ màng nước mỏng giữa lốp và mặt đường, chống hiện tượng trượt nước (aquaplaning) và đảm bảo độ bám ma sát tốt.","svgGraph":null},{"q":"Một khối gỗ có khối lượng m = 2 kg trượt đều xuống dưới trên một mặt phẳng nghiêng góc α = 30° so với phương ngang. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Vì khối gỗ trượt đều nên gia tốc của nó triệt tiêu bằng 0.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Trượt đều ⇒ a = 0.<br>• <b>Ý b [Đúng]:</b> P₁ = mg·sin(30°) = 2 · 10 · 0,5 = 10 N.<br>• <b>Ý c [Đúng]:</b> a = 0 ⇒ F<sub>mst</sub> = P₁ = 10 N.<br>• <b>Ý d [Đúng]:</b> F<sub>mst</sub> = μ·N = μ·mg·cos(30°) = mg·sin(30°) ⇒ μ = tan(30°) = 1/√3 ≈ 0,577.","svgGraph":null},{"q":"Để di chuyển một cỗ máy nặng hàng tấn vào xưởng cơ khí, các công nhân thường đặt các ống thép tròn lót dưới đáy máy rồi đẩy. Biện pháp này nhằm:","opts":["Thay thế lực ma sát trượt rất lớn bằng lực ma sát lăn nhỏ hơn nhiều lần.","Làm giảm trọng lượng của cỗ máy xuống một nửa.","Tăng diện tích tiếp xúc giữa máy và sàn nhà.","Làm cho mặt sàn nhà trơn nhẵn hơn."],"ans":0,"exp":"• Lực ma sát lăn có độ lớn nhỏ hơn rất nhiều lần so với lực ma sát trượt, giúp việc dịch chuyển các vật nặng trở nên nhẹ nhàng hơn.","svgGraph":null}],"19":[{"q":"Khi một vật chuyển động trong môi trường chất lưu (chất lỏng hoặc chất khí), vật luôn chịu tác dụng của:","opts":["Lực cản của chất lưu có xu hướng cản trở chuyển động của vật.","Lực đẩy luôn làm vật tăng tốc độ liên tục.","Một lực có phương vuông góc với vectơ vận tốc.","Lực hấp dẫn kéo vật bay lên trên khí quyển."],"ans":0,"exp":"• Mọi vật chuyển động trong chất lưu đều chịu lực cản do va chạm với các phân tử chất lưu và lực ma sát nhớt giữa bề mặt vật với các lớp chất lưu bao quanh.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr19\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Streamlined Airplane Wing Cross-section -->\n      <path d=\"M 120,120 C 180,70 300,90 380,125 C 300,140 180,135 120,120 Z\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <!-- Airflow lines top (faster, lower pressure) -->\n      <path d=\"M 60,80 Q 180,45 320,60 T 440,90\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n      <text x=\"210\" y=\"55\" fill=\"#38bdf8\" font-size=\"11\">Dòng khí trên chạy nhanh (Áp suất P₁ thấp)</text>\n      <!-- Airflow lines bottom (slower, higher pressure) -->\n      <path d=\"M 60,150 Q 200,160 320,155 T 440,145\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.8\"/>\n      <text x=\"210\" y=\"180\" fill=\"#94a3b8\" font-size=\"11\">Dòng khí dưới chạy chậm (Áp suất P₂ cao)</text>\n      <!-- Aerodynamic Lift Force F<tspan baseline-shift=\"sub\" font-size=\"70%\">n</tspan> (upward) -->\n      <line x1=\"250\" y1=\"110\" x2=\"250\" y2=\"30\" stroke=\"#34d399\" stroke-width=\"3.5\" marker-end=\"url(#arr19)\"/>\n      <text x=\"260\" y=\"40\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">Lực nâng khí động học F<tspan baseline-shift=\"sub\" font-size=\"70%\">n</tspan></text>\n      <!-- Drag Force F_c (backward) -->\n      <line x1=\"120\" y1=\"120\" x2=\"60\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr19)\"/>\n      <text x=\"35\" y=\"115\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Lực cản F<tspan baseline-shift=\"sub\" font-size=\"70%\">c</tspan></text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Lực nâng khí động học của cánh máy bay dạng khí động học</text>\n    </svg>"},{"q":"Độ lớn của lực cản không khí tác dụng lên một vật chuyển động phụ thuộc chủ yếu vào:","opts":["Vận tốc chuyển động, diện tích cản gió và hình dạng khí động học của vật.","Khối lượng riêng của vật liệu làm nên vật thể đó.","Vĩ độ địa lí và độ cao của mặt phẳng quỹ đạo.","Màu sắc phản xạ ánh sáng của bề mặt vật thể."],"ans":0,"exp":"• Lực cản không khí F<sub>c</sub> tỉ lệ với bình phương vận tốc (v² ở tốc độ cao), diện tích bề mặt vuông góc với dòng khí (S) và hình dạng hình học (hệ số cản C<sub>x</sub>).","svgGraph":null},{"q":"Hình dạng nào sau đây của vật thể giúp làm giảm lực cản của chất lưu xuống mức nhỏ nhất?","opts":["Hình dạng thuôn nhọn khí động học (giọt nước hoặc thân cá heo).","Hình hộp vuông chữ nhật góc cạnh gồ ghề.","Hình bán cầu rỗng quay mặt lõm về phía trước.","Hình đĩa phẳng tròn đặt vuông góc với hướng gió."],"ans":0,"exp":"• Dạng khí động học thuôn dài như giọt nước hoặc thân cá giúp dòng chất lưu chảy êm dịu bao quanh thân mà không tạo các vùng xoáy cuộn phía sau, triệt tiêu đáng kể lực cản.","svgGraph":null},{"q":"Khi một vận động viên nhảy dù rơi trong không khí từ máy bay xuống đất, xét tính Đúng / Sai của các giai đoạn chuyển động sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi mở dù, lực cản không khí đột ngột giảm xuống làm người rơi nhanh hơn để chạm đất an toàn.","Ngay sau khi nhảy ra (vận tốc v còn nhỏ), trọng lực lớn hơn lực cản không khí nên vận động viên chuyển động nhanh dần.","Khi vận tốc rơi tăng lên thì lực cản của không khí tác dụng lên người cũng tăng dần theo.","Khi lực cản không khí cân bằng với trọng lực (F<sub>c</sub> = P), vận động viên sẽ rơi thẳng đều với một tốc độ giới hạn (tốc độ cuối)."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> P > F<sub>c</sub> ⇒ gia tốc a > 0 nhanh dần.<br>• <b>Ý b [Đúng]:</b> v tăng kéo theo F<sub>c</sub> tăng.<br>• <b>Ý c [Đúng]:</b> F<sub>c</sub> = P ⇒ a = 0 rơi thẳng đều với vận tốc giới hạn v<sub>t</sub> (terminal velocity).<br>• <b>Ý d [Sai]:</b> Mở dù diện tích S tăng vọt làm F<sub>c</sub> tăng rất lớn làm giảm tốc độ rơi về mức an toàn (khoảng 5 m/s) khi chạm đất.","svgGraph":null},{"q":"Ghép hiện tượng ở Cột A với loại lực của chất lưu đóng vai trò chủ đạo ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Khí cầu bay lơ lửng trên bầu trời ➔ Lực cản không khí lớn của vòm dù","Khí cầu bay lơ lửng trên bầu trời ➔ Lực đẩy tĩnh học Archimedes của không khí","Máy bay bay lượn trên không trung ➔ Lực cản không khí lớn của vòm dù","Cá heo bơi nhanh trong đại dương ➔ Lực đẩy tĩnh học Archimedes của không khí"],"ans":0,"exp":"• <b>1 - B:</b> Khí cầu: Lực đẩy Archimedes.<br>• <b>2 - D:</b> Máy bay: Lực nâng khí động học.<br>• <b>3 - C:</b> Thân cá heo: giảm lực cản nước.<br>• <b>4 - A:</b> Chiếc dù: Lực cản không khí hãm tốc.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Cánh máy bay được thiết kế theo biên dạng khí động học có mặt trên cong nhiều hơn mặt dưới phẳng. Khi máy bay chuyển động, luồng không khí ở mặt trên cánh chảy  [ ... ]  luồng không khí ở mặt dưới. Theo định luật Bernoulli, nơi nào chất lưu chảy nhanh hơn thì áp suất tĩnh ở đó sẽ  [ ... ] . Do đó, áp suất không khí ở mặt dưới lớn hơn mặt trên tạo ra một  [ ... ]  hướng thẳng đứng lên trên. Lực này giúp máy bay có thể  [ ... ]  trên bầu trời.\"</i>","opts":["nhanh hơn — nhỏ hơn","không đổi","chậm hơn — lớn hơn","nhỏ hơn — nhanh hơn"],"ans":0,"exp":"<b>Nguyên lí tạo lực nâng (Bernoulli):</b><br>• Dòng khí trên cong chảy nhanh hơn.<br>• Áp suất mặt trên nhỏ hơn mặt dưới.<br>• Hiệu áp suất tạo lực nâng F<sub>n</sub> hướng lên.<br>• F<sub>n</sub> cân bằng trọng lực P giúp máy bay bay ổn định.","svgGraph":null},{"q":"Một quả cầu kim loại nhỏ rơi trong một ống nghiệm đựng đầy dầu nhớt đặc. Sau một đoạn đường ngắn, quả cầu chuyển động thẳng đều với vận tốc không đổi v = 0,2 m/s. Trọng lượng quả cầu là P = 0,15 N và lực đẩy Archimedes của dầu là F<sub>A</sub> = 0,05 N. Độ lớn của lực cản nhớt tác dụng lên quả cầu khi rơi đều là:","opts":["0,10 N.","0,20 N.","0,15 N.","0,05 N."],"ans":0,"exp":"• <b>Khi quả cầu rơi thẳng đều:</b> Hợp lực triệt tiêu: P = F<sub>A</sub> + F<sub>c</sub>ản.<br>• <b>Lực cản nhớt:</b> F<sub>c</sub>ản = P - F<sub>A</sub> = 0,15 - 0,05 = 0,10 N.","svgGraph":null},{"q":"Lực đẩy Archimedes tác dụng lên một vật nhúng chìm trong chất lỏng có độ lớn bằng:","opts":["Trọng lượng của phần chất lỏng bị vật chiếm chỗ: F<sub>A</sub> = ρ_lỏng · g · V.","Khối lượng toàn phần của vật nhúng chìm.","Áp suất ở đáy bình chứa chất lỏng.","Trọng lượng của chính vật đó trong chân không."],"ans":0,"exp":"• Định luật Archimedes: F<sub>A</sub> = d·V = ρ·g·V, trong đó ρ là khối lượng riêng của chất lỏng, V là thể tích phần chất lỏng bị vật chiếm chỗ.","svgGraph":null},{"q":"Một vật có khối lượng m = 800 g và thể tích V = 1000 cm³ = 10⁻³ m³ được thả vào một chậu nước lớn có khối lượng riêng ρ<sub>n</sub>ước = 1000 kg/m³. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Thể tích phần vật chìm dưới nước bằng trọn vẹn 1000 cm³.","Khối lượng riêng của vật là ρ_vật = 800 kg/m³ nhỏ hơn khối lượng riêng của nước.","Khi thả vào nước, vật sẽ nổi một phần trên mặt nước.","Lực đẩy Archimedes tác dụng lên vật khi vật nổi cân bằng có độ lớn bằng 8 N."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> ρ_vật = 0,8 / 10⁻³ = 800 kg/m³ < 1000 kg/m³.<br>• <b>Ý b [Đúng]:</b> ρ_vật < ρ<sub>n</sub>ước nên vật nổi.<br>• <b>Ý c [Đúng]:</b> Nổi cân bằng thì F<sub>A</sub> = P = mg = 0,8 · 10 = 8 N.<br>• <b>Ý d [Sai]:</b> V<sub>ch</sub>ìm = F<sub>A</sub> / (ρ<sub>n</sub>ước · g) = 8 / (1000 · 10) = 8·10⁻⁴ m³ = 800 cm³ (chỉ chìm 80% thể tích).","svgGraph":null},{"q":"Tại sao các vận động viên đua xe đạp chuyên nghiệp thường mặc trang phục bó sát, đội mũ bảo hiểm hình giọt nước và cúi gập lưng sát ghi-đông khi thi đấu?","opts":["Để giảm tối đa diện tích cản gió và cải thiện hệ số khí động học giúp xe chạy nhanh hơn.","Để làm cho xe đạp có trọng lượng nặng hơn bám đường tốt hơn.","Để cản trở gió không cho các đối thủ phía sau vượt lên.","Để hạ nhiệt độ cơ thể khi thi đấu dưới trời nắng."],"ans":0,"exp":"• Giảm diện tích cản gió S và tạo hình dáng khí động học thuôn mượt giúp giảm đáng kể lực cản không khí, tiết kiệm tối đa sức lực cho vận động viên ở tốc độ cao.","svgGraph":null}],"20":[{"q":"Bước đầu tiên và mang tính quyết định trong quy trình giải bài toán động lực học bằng định luật Newton là:","opts":["Chọn vật khảo sát, vẽ sơ đồ phân tích tất cả các lực tác dụng lên vật và chọn hệ quy chiếu thích hợp.","Bấm máy tính tính ngay vận tốc và gia tốc mà không cần vẽ hình.","Đo trực tiếp độ dài của các vectơ trên trang giấy kẻ ô.","Thay số đại số vào các công thức chuyển động học."],"ans":0,"exp":"• Quy trình chuẩn: (1) Xác định vật khảo sát; (2) Phân tích các lực tác dụng (P, N, F<sub>k</sub>, F<sub>ms</sub>,...); (3) Chọn hệ trục toạ độ Oxy; (4) Viết phương trình vectơ F = ma; (5) Chiếu phương trình lên các trục toạ độ.","svgGraph":null},{"q":"Một vật trượt không vận tốc đầu từ đỉnh một mặt phẳng nghiêng góc α so với phương ngang. Bỏ qua ma sát. Gia tốc chuyển động của vật dọc theo mặt phẳng nghiêng là:","opts":["a = g · sin(α).","a = g · cos(α).","a = g · tan(α).","a = g."],"ans":0,"exp":"• <b>Chiếu phương trình định luật 2 lên phương song song mặt nghiêng:</b><br>P<sub>x</sub> = P·sin(α) = m·a ⇒ m·g·sin(α) = m·a ⇒ a = g·sin(α). Gia tốc không phụ thuộc vào khối lượng vật.","svgGraph":null},{"q":"Một vật trượt xuống một mặt phẳng nghiêng góc α = 30° có hệ số ma sát trượt μ = 0,2. Lấy g = 10 m/s² và √3 ≈ 1,73. Gia tốc trượt của vật xấp xỉ bằng:","opts":["3,27 m/s².","5,00 m/s².","1,73 m/s².","4,50 m/s²."],"ans":0,"exp":"• <b>Công thức gia tốc trên mặt phẳng nghiêng có ma sát:</b><br>a = g·(sin α - μ·cos α)<br>• <b>Thay số:</b> a = 10 · [sin(30°) - 0,2 · cos(30°)] = 10 · [0,5 - 0,2 · 0,866] = 10 · [0,5 - 0,173] = 10 · 0,327 = 3,27 m/s².","svgGraph":null},{"q":"Hai vật có khối lượng m₁ = 1 kg và m₂ = 3 kg đặt trên mặt sàn trơn nhẵn nằm ngang nối với nhau bằng một sợi dây nhẹ. Tác dụng một lực kéo F = 16 N theo phương ngang vào vật m₂. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực căng dây T đúng bằng lực kéo F = 16 N.","Gia tốc chuyển động của hệ hai vật là a = 4 m/s².","Lực căng của sợi dây nối giữa hai vật là T = 4 N.","Nếu đổi ngược lại, tác dụng lực kéo F = 16 N vào vật m₁ thì lực căng của sợi dây sẽ là T' = 12 N."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> a = F / (m₁ + m₂) = 16 / (1 + 3) = 4 m/s².<br>• <b>Ý b [Đúng]:</b> Dây kéo m₁ ⇒ T = m₁·a = 1 · 4 = 4 N.<br>• <b>Ý c [Sai]:</b> T = 4 N < F = 16 N.<br>• <b>Ý d [Đúng]:</b> Nếu kéo m₁ thì dây kéo m₂ ⇒ T' = m₂·a = 3 · 4 = 12 N.","svgGraph":null},{"q":"Ghép phương trình động lực học ở Cột A với bài toán tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["F<sub>k</sub> - F<sub>ms</sub> = m·a ➔ Vật trượt xuống mặt phẳng nghiêng có ma sát","F<sub>k</sub> - F<sub>ms</sub> = m·a ➔ Vật đứng yên cân bằng trên mặt phẳng nghiêng","P·sin(α) - F<sub>ms</sub> = m·a ➔ Vật trượt xuống mặt phẳng nghiêng có ma sát","P·sin(α) = F<sub>ms</sub> ➔ Vật đứng yên cân bằng trên mặt phẳng nghiêng"],"ans":0,"exp":"• <b>1 - C:</b> Kéo ngang có ma sát: F<sub>k</sub> - F<sub>ms</sub> = ma.<br>• <b>2 - A:</b> Trượt xuống mặt nghiêng: P·sinα - F<sub>ms</sub> = ma.<br>• <b>3 - B:</b> Cân bằng trên mặt nghiêng: P·sinα = F<sub>ms</sub>.<br>• <b>4 - D:</b> Kéo thẳng đứng: T - P = ma.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Để giải phương trình vectơ ∑F = m·a, ta chọn hệ trục toạ độ vuông góc Oxy. Thông thường chọn trục Ox  [ ... ]  và trục Oy  [ ... ] . Chiếu phương trình lên trục Oy (vuông góc chuyển động) để xác định  [ ... ] . Sau đó thay N vào công thức lực ma sát F<sub>ms</sub> = μ·N để chiếu lên trục Ox tìm  [ ... ] .\"</i>","opts":["trùng với phương chuyển động — vuông góc với phương chuyển động","không đổi","song song trọng lực — vận tốc v","vuông góc với phương chuyển động — trùng với phương chuyển động"],"ans":0,"exp":"<b>Phương pháp toạ độ:</b><br>• Ox dọc theo chuyển động.<br>• Oy vuông góc chuyển động.<br>• Chiếu Oy: N = P<sub>y</sub> tìm N.<br>• Chiếu Ox: tìm gia tốc a.","svgGraph":null},{"q":"Một người kéo một vali nặng 20 kg trên sàn nằm ngang bằng một lực F = 50 N hợp với phương ngang một góc α = 60°. Lấy g = 10 m/s². Áp lực N mà vali đè lên mặt sàn là:","opts":["156,7 N.","200 N.","243,3 N.","175 N."],"ans":0,"exp":"• <b>Chiếu lực lên trục thẳng đứng Oy:</b> N + F·sin(α) - P = 0<br>• <b>Áp lực:</b> N = P - F·sin(α) = m·g - F·sin(60°) = 20 · 10 - 50 · <span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 200 - 43,3 = 156,7 N. (Lực kéo chếch lên làm giảm áp lực).","svgGraph":null},{"q":"Một khối gỗ đặt trên một tấm ván nằm ngang. Nâng từ từ một đầu tấm ván lên cao. Khi góc nghiêng của tấm ván đạt α = 30° thì khối gỗ bắt đầu trượt. Hệ số ma sát nghỉ cực đại giữa khối gỗ và ván là:","opts":["0,577 (tan 30°).","0,500 (sin 30°).","0,866 (cos 30°).","1,000."],"ans":0,"exp":"• Tại góc tới hạn bắt đầu trượt: Thành phần kéo P·sin(α) cân bằng với ma sát nghỉ cực đại μ_n·P·cos(α) ⇒ μ_n = tan(α) = tan(30°) = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">√3</span></span> ≈ 0,577.","svgGraph":null},{"q":"Một vật có khối lượng m = 4 kg chịu tác dụng của lực kéo F = 20 N hợp với phương ngang một góc α = 30°. Vật chuyển động trên sàn nhẵn không ma sát. Lấy g = 10 m/s² và cos(30°) ≈ 0,866. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu góc kéo tăng lên α = 90° thì vật sẽ di chuyển trên sàn với gia tốc lớn nhất.","Lực kéo theo phương chuyển động ngang là F<sub>x</sub> = F·cos(30°) ≈ 17,32 N.","Gia tốc chuyển động của vật là a ≈ 4,33 m/s².","Thành phần lực kéo F<sub>y</sub> hướng thẳng đứng lên trên làm giảm áp lực của vật lên sàn."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F<sub>x</sub> = 20 · cos(30°) = 17,32 N.<br>• <b>Ý b [Đúng]:</b> a = F<sub>x</sub> / m = 17,32 / 4 = 4,33 m/s².<br>• <b>Ý c [Đúng]:</b> N = P - F·sin(30°) < P.<br>• <b>Ý d [Sai]:</b> α = 90° thì F<sub>x</sub> = 0, vật không có gia tốc theo phương ngang.","svgGraph":null},{"q":"Trong các vụ va chạm ô tô được tái hiện để điều tra tai nạn giao thông, các kĩ sư hiện trường thường dựa vào vết trượt phanh lốp trên mặt đường để xác định yếu tố nào của xe trước khi phanh?","opts":["Vận tốc tức thời của xe ngay trước khi tài xế đạp phanh khẩn cấp: v = √(2·μ·g·s).","Dung tích bình xăng của xe ô tô.","Công suất định mức của ắc quy xe điện.","Số lượng hành khách ngồi trên xe."],"ans":0,"exp":"• Áp dụng định lí động năng hoặc hệ thức độc lập: v² - 0 = 2·a·s = 2·(μ·g)·s ⇒ v = √(2μgs). Đo vết phanh s và đo hệ số ma sát μ của mặt đường sẽ tìm được tốc độ v ban đầu của xe.","svgGraph":null}],"21":[{"q":"Moment của một lực đối với một trục quay là đại lượng đặc trưng cho:","opts":["Tác dụng làm quay của lực và được đo bằng tích của lực với cánh tay đòn của nó (M = F · d).","Khả năng làm biến dạng cơ học của vật thể.","Tốc độ chuyển động tịnh tiến của trọng tâm vật rắn.","Công suất toả nhiệt của lực ma sát quay."],"ans":0,"exp":"• <b>Định nghĩa moment lực:</b> M = F·d. Moment lực đặc trưng cho tác dụng làm quay của lực quanh trục. Trong đó F là độ lớn của lực (N), d là cánh tay đòn (khoảng cách vuông góc từ trục quay đến giá của lực, đo bằng mét). Đơn vị là N·m.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr21\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Rotation axis O -->\n      <circle cx=\"120\" cy=\"120\" r=\"10\" fill=\"#f43f5e\" stroke=\"#fca5a5\" stroke-width=\"2\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"3\" fill=\"#ffffff\"/>\n      <text x=\"100\" y=\"150\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">Trục quay O</text>\n      <!-- Wrench bar -->\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#475569\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n      <!-- Force F applied at end -->\n      <circle cx=\"380\" cy=\"120\" r=\"5\" fill=\"#fbbf24\"/>\n      <line x1=\"380\" y1=\"120\" x2=\"380\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"3.5\" marker-end=\"url(#arr21)\"/>\n      <text x=\"390\" y=\"55\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Lực F</text>\n      <!-- Lever arm d bracket -->\n      <line x1=\"120\" y1=\"170\" x2=\"380\" y2=\"170\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <circle cx=\"120\" cy=\"170\" r=\"3\" fill=\"#34d399\"/>\n      <circle cx=\"380\" cy=\"170\" r=\"3\" fill=\"#34d399\"/>\n      <text x=\"220\" y=\"195\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Cánh tay đòn d</text>\n      <text x=\"145\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Moment lực làm quay M = F · d</text>\n    </svg>"},{"q":"Cánh tay đòn d của một lực là:","opts":["Khoảng cách vuông góc từ trục quay đến giá của lực.","Khoảng cách từ trục quay đến điểm đặt của lực trên vật.","Chiều dài của toàn bộ thanh đòn quay.","Độ dài của mũi tên vectơ biểu diễn lực tác dụng."],"ans":0,"exp":"• Cánh tay đòn d luôn luôn là khoảng cách vuông góc (đoạn hạ vuông góc) từ trục quay tới đường thẳng chứa vectơ lực (giá của lực).","svgGraph":null},{"q":"Quy tắc moment lực (điều kiện cân bằng của một vật có trục quay cố định) phát biểu rằng:","opts":["Tổng các moment lực làm vật quay theo chiều kim đồng hồ bằng tổng các moment lực làm vật quay ngược chiều kim đồng hồ.","Hợp lực của các lực tác dụng phải có phương vuông góc với cánh tay đòn.","Tổng độ lớn của các lực làm quay theo chiều kim đồng hồ phải bằng tổng độ lớn các lực ngược chiều kim đồng hồ.","Trọng tâm của vật phải luôn nằm trùng với trục quay cố định."],"ans":0,"exp":"• <b>Quy tắc moment:</b> Một vật có trục quay cố định ở trạng thái cân bằng khi: ∑M<sub>thu</sub>ận = ∑M<sub>ngh</sub>ịch.","svgGraph":null},{"q":"Xét một chiếc cờ lê dài 25 cm đang được dùng để vặn chặt một đai ốc bu lông. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Moment lực là một đại lượng vô hướng luôn luôn mang giá trị âm.","Tác dụng một lực F = 40 N vuông góc vào đầu mút cờ lê tạo ra moment lực M = 10 N·m.","Nếu đẩy lực F theo phương đi thẳng qua tâm đai ốc thì moment lực bằng 0 và đai ốc không quay được.","Nếu dùng ống tuýp nối dài cán cờ lê thêm thì moment lực làm quay sẽ tăng lên giúp vặn ốc nhẹ nhàng hơn."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> M = F·d = 40 · 0,25 = 10 N·m.<br>• <b>Ý b [Đúng]:</b> Giá lực qua trục quay thì cánh tay đòn d = 0 ⇒ M = 0 không quay.<br>• <b>Ý c [Đúng]:</b> Nối dài cán làm tăng d ⇒ M tăng với cùng lực F.<br>• <b>Ý d [Sai]:</b> Moment lực đại số có thể mang dấu (+) hoặc (-) tuỳ quy ước chiều quay.","svgGraph":null},{"q":"Ghép loại ngẫu lực hoặc đòn bẩy ở Cột A với đặc điểm tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Ngẫu lực ➔ M = F · d (với d là khoảng cách giữa hai giá của hai lực song song ngược chiều)","Ngẫu lực ➔ Hệ hai lực song song, ngược chiều, cùng độ lớn và cùng tác dụng vào một vật","Đòn bẩy loại 1 (điểm tựa ở giữa) ➔ M = F · d (với d là khoảng cách giữa hai giá của hai lực song song ngược chiều)","Đòn bẩy loại 2 (vật ở giữa) ➔ Hệ hai lực song song, ngược chiều, cùng độ lớn và cùng tác dụng vào một vật"],"ans":0,"exp":"• <b>1 - B:</b> Ngẫu lực: 2 lực song song ngược chiều cùng độ lớn.<br>• <b>2 - D:</b> Đòn bẩy loại 1: điểm tựa ở giữa.<br>• <b>3 - C:</b> Đòn bẩy loại 2: vật ở giữa lợi về lực.<br>• <b>4 - A:</b> M<sub>ng</sub>ẫu = F·d.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Ngẫu lực là hệ hai lực  [ ... ] , ngược chiều, có cùng độ lớn cùng tác dụng vào một vật. Ngẫu lực chỉ có tác dụng làm cho vật  [ ... ]  chứ không làm tịnh tiến vật. Điều kiện cân bằng tổng quát của một vật rắn bất kì gồm hai điều kiện: tổng các lực tác dụng lên vật bằng 0 (chống tịnh tiến) và  [ ... ]  đối với trục quay bất kì bằng 0 (chống quay). Moment của ngẫu lực  [ ... ]  vị trí chọn trục quay vuông góc.\"</i>","opts":["song song — quay","không đổi","vuông góc — phụ thuộc chặt chẽ vào","quay — song song"],"ans":0,"exp":"<b>Ngẫu lực và cân bằng tổng quát:</b><br>• 2 lực song song, ngược chiều, bằng độ lớn.<br>• Chỉ làm quay, không làm tịnh tiến.<br>• Điều kiện cân bằng: ∑F = 0 và ∑M = 0.<br>• Moment ngẫu lực M = F·d độc lập vị trí trục quay.","svgGraph":null},{"q":"Một thanh chắn đường dài L = 6 m có trục quay O cách đầu bên trái 1 m. Để thanh nằm ngang cân bằng, người ta treo vào đầu bên trái một đối trọng khối lượng m₁ = 50 kg. Trọng lượng của thanh phân bố đều có trọng tâm nằm ở chính giữa thanh (cách O một đoạn 2 m). Khối lượng m₂ của thanh chắn là:","opts":["25 kg.","50 kg.","100 kg.","12,5 kg."],"ans":0,"exp":"• <b>Cánh tay đòn đối trọng m₁:</b> d₁ = 1 m.<br>• <b>Trọng tâm thanh G ở chính giữa:</b> cách đầu trái 3 m ⇒ cách O một đoạn: d₂ = 3 - 1 = 2 m.<br>• <b>Quy tắc moment quanh O:</b> m₁·g·d₁ = m₂·g·d₂ ⇒ 50 · 1 = m₂ · 2 ⇒ m₂ = <span class=\"fraction\"><span class=\"numerator\">50</span><span class=\"denominator\">2</span></span> = 25 kg.","svgGraph":null},{"q":"Hai tay của một tài xế tác dụng vào vô lăng ô tô một ngẫu lực gồm hai lực ngược chiều có cùng độ lớn F = 20 N. Bán kính vô lăng là R = 20 cm. Moment của ngẫu lực này là:","opts":["8,0 N·m.","4,0 N·m.","2,0 N·m.","16,0 N·m."],"ans":0,"exp":"• Khoảng cách giữa giá hai lực ngẫu lực bằng đường kính vô lăng: d = 2·R = 2 · 0,2 = 0,4 m.<br>• <b>Moment ngẫu lực:</b> M = F·d = 20 · 0,4 = 8,0 N·m.","svgGraph":null},{"q":"Hai đứa trẻ chơi bập bênh gồm một thanh gỗ đồng chất quay quanh điểm tựa ở chính giữa. Đứa trẻ A nặng m<sub>A</sub> = 30 kg ngồi cách điểm tựa d<sub>A</sub> = 2,0 m. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu đứa trẻ B tiến lại gần điểm tựa hơn (d<sub>B</sub> < 1,5 m) thì đầu bập bênh phía đứa trẻ A sẽ bị bổng lên cao.","Moment lực do đứa trẻ A tạo ra quanh điểm tựa là M<sub>A</sub> = 600 N·m (lấy g = 10 m/s²).","Đứa trẻ B nặng m<sub>B</sub> = 40 kg muốn bập bênh thăng bằng nằm ngang thì phải ngồi cách điểm tựa một đoạn d<sub>B</sub> = 1,5 m.","Trọng lực tác dụng lên chính thanh gỗ không làm thanh bị quay vì điểm đặt của nó đi qua điểm tựa (cánh tay đòn bằng 0)."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> M<sub>A</sub> = P<sub>A</sub>·d<sub>A</sub> = (30 · 10) · 2 = 600 N·m.<br>• <b>Ý b [Đúng]:</b> M<sub>B</sub> = M<sub>A</sub> ⇒ (40 · 10) · d<sub>B</sub> = 600 ⇒ d<sub>B</sub> = 600 / 400 = 1,5 m.<br>• <b>Ý c [Sai]:</b> d<sub>B</sub> < 1,5 m thì M<sub>B</sub> < M<sub>A</sub> ⇒ phía A chìm xuống, phía B bổng lên.<br>• <b>Ý d [Đúng]:</b> Trọng tâm thanh trùng điểm tựa ⇒ d = 0 ⇒ M<sub>thanh</sub> = 0.","svgGraph":null},{"q":"Nguyên nhân chính giúp những người đi thăng bằng trên dây xiếc thường cầm một chiếc sào rất dài và uốn cong chúc xuống dưới là:","opts":["Hạ thấp trọng tâm của toàn bộ hệ người - sào xuống dưới dây và tăng moment quán tính chống lại sự nghiêng ngã.","Tăng khối lượng để dây căng hơn.","Tạo luồng gió nâng người bay lơ lửng.","Che chắn mắt khỏi ánh đèn sân khấu."],"ans":0,"exp":"• Chiếc sào dài uốn cong làm trọng tâm của cả hệ hạ xuống sát hoặc thấp hơn dây xiếc (trạng thái cân bằng bền vững hơn), đồng thời cánh tay đòn dài tạo moment quán tính quay lớn chống lại chuyển động lắc nghiêng mất thăng bằng.","svgGraph":null}],"22":[{"q":"Trong bài thực hành kiểm chứng quy tắc hình bình hành tổng hợp hai lực đồng quy, người ta sử dụng dụng cụ nào để đo trực tiếp độ lớn của các lực?","opts":["Lực kế lò xo chia vạch Newton.","Cân đồng hồ đo khối lượng gam.","Thước kẹp đo chiều dài milimét.","Vôn kế điện tử đo hiệu điện thế."],"ans":0,"exp":"• Lực kế lò xo là dụng cụ đo trực tiếp độ lớn của lực dựa trên định luật Hooke về độ biến dạng của lò xo tỉ lệ thuận với lực tác dụng: F = k·Δl.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr22\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circular Board with angle scale -->\n      <circle cx=\"250\" cy=\"120\" r=\"95\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <circle cx=\"250\" cy=\"120\" r=\"6\" fill=\"#f8fafc\"/>\n      <text x=\"245\" y=\"140\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">O</text>\n      <!-- Rubber band stretched to O -->\n      <line x1=\"250\" y1=\"215\" x2=\"250\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n      <text x=\"255\" y=\"180\" fill=\"#f43f5e\" font-size=\"11\">Dây cao su</text>\n      <!-- Spring Balance 1 -->\n      <line x1=\"250\" y1=\"120\" x2=\"160\" y2=\"55\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <rect x=\"130\" y=\"35\" width=\"40\" height=\"25\" fill=\"#0284c7\" rx=\"3\"/>\n      <text x=\"135\" y=\"52\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">F₁</text>\n      <!-- Spring Balance 2 -->\n      <line x1=\"250\" y1=\"120\" x2=\"340\" y2=\"55\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <rect x=\"330\" y=\"35\" width=\"40\" height=\"25\" fill=\"#d97706\" rx=\"3\"/>\n      <text x=\"335\" y=\"52\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">F₂</text>\n      <text x=\"140\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Bố trí thí nghiệm kiểm chứng quy tắc hình bình hành lực</text>\n    </svg>"},{"q":"Để kiểm chứng quy tắc tổng hợp hai lực đồng quy F₁ và F₂, bước đối chứng quan trọng nhất là:","opts":["Dùng một lực kế thứ ba kéo dây cao su sao cho nút chỉ O dãn đúng đến vị trí O cân bằng ban đầu.","Tăng gấp đôi độ dãn của dây cao su rồi đo lại.","Tháo rời các lực kế ra và cân từng lực kế trên đĩa cân.","Đo chu kì dao động của dây cao su khi buông tay."],"ans":0,"exp":"• Nút chỉ O về đúng vị trí cũ chứng tỏ lực kéo duy nhất F của lực kế thứ ba gây ra tác dụng hoàn toàn giống hệt như tác dụng đồng thời của hai lực F₁ và F₂.","svgGraph":null},{"q":"Khi đọc số chỉ trên bảng chia độ của lực kế lò xo, thao tác nào sau đây là chuẩn mực?","opts":["Đặt hướng nhìn vuông góc với thang đo chỉ thị của lực kế.","Nhìn nghiêng từ dưới lên để số đo được phóng đại to hơn.","Nhìn nghiêng một góc 45° từ trên xuống.","Cầm lực kế lắc qua lắc lại liên tục trong khi đọc số đo."],"ans":0,"exp":"• Hướng nhìn vuông góc với mặt thang đo giúp loại trừ hoàn toàn sai số thị sai (sai số góc nhìn).","svgGraph":null},{"q":"Trong quá trình tiến hành thí nghiệm tổng hợp lực trên bảng từ, xét tính Đúng / Sai của các thao tác sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ dài của hình bình hành lực vẽ trên giấy phải lấy tỉ lệ xích ngẫu nhiên khác nhau cho từng lực.","Trước khi đo, cần hiệu chỉnh kim chỉ thị của tất cả các lực kế về đúng vạch số 0.","Dây nối từ nút O đến các lực kế phải luôn áp sát mặt phẳng bảng và không bị vướng chốt cản.","Đánh dấu phương của các lực bằng cách chấm hai điểm trên đường đi của mỗi sợi dây chỉ."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Chỉnh điểm 0 khử sai số hệ thống dụng cụ.<br>• <b>Ý b [Đúng]:</b> Tránh ma sát và lực kẹt làm sai lệch hướng lực.<br>• <b>Ý c [Đúng]:</b> Đánh dấu 2 điểm để kẻ đường thẳng phương lực.<br>• <b>Ý d [Sai]:</b> Phải chọn cùng một tỉ lệ xích (ví dụ 1 cm ứng với 1 N) cho tất cả các vectơ lực F₁, F₂ và hợp lực F để dựng hình so sánh.","svgGraph":null},{"q":"Ghép các bước thực hành ở Cột A với mục đích thao tác ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Hiệu chỉnh điểm 0 của lực kế ➔ Xác định độ lớn và hướng của hợp lực lí thuyết F<sub>lt</sub>","Hiệu chỉnh điểm 0 của lực kế ➔ Quy đổi độ lớn các lực (N) thành độ dài các đoạn thẳng (cm)","Ghi nhận vị trí điểm O cân bằng ➔ Xác định độ lớn và hướng của hợp lực lí thuyết F<sub>lt</sub>","Chọn tỉ lệ xích biểu diễn lực ➔ Quy đổi độ lớn các lực (N) thành độ dài các đoạn thẳng (cm)"],"ans":0,"exp":"• <b>1 - C:</b> Hiệu chỉnh điểm 0 trừ sai số dụng cụ.<br>• <b>2 - D:</b> Ghi nhận O làm mốc đối chứng.<br>• <b>3 - B:</b> Tỉ lệ xích đổi N sang cm.<br>• <b>4 - A:</b> Đường chéo cho hợp lực lí thuyết.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Từ kết quả thực nghiệm, ta so sánh độ lớn và hướng của hợp lực thực nghiệm F<sub>tn</sub> (đo bằng 1 lực kế) với đường chéo F<sub>lt</sub> dựng bằng  [ ... ] . Nếu độ lệch giữa F<sub>tn</sub> và F<sub>lt</sub> nằm trong giới hạn  [ ... ]  cho phép, ta kết luận quy tắc hình bình hành lực được  [ ... ] . Thí nghiệm này khẳng định lực là một  [ ... ] .\"</i>","opts":["quy tắc hình bình hành — sai số thực nghiệm","không đổi","quy tắc tam giác vuông — đại lượng vô hướng","sai số thực nghiệm — quy tắc hình bình hành"],"ans":0,"exp":"<b>Kết luận thực hành tổng hợp lực:</b><br>• Dựng hợp lực bằng quy tắc hình bình hành.<br>• So sánh trong giới hạn sai số.<br>• Kiểm chứng thành công định luật.<br>• Lực tuân theo quy tắc cộng vectơ.","svgGraph":null},{"q":"Trong một lần thí nghiệm, hai lực kế chỉ F₁ = 3,0 N và F₂ = 4,0 N vuông góc nhau (α = 90°). Độ lớn hợp lực lí thuyết vẽ bằng quy tắc hình bình hành là:","opts":["5,0 N.","7,0 N.","1,0 N.","12,0 N."],"ans":0,"exp":"• <b>Hợp lực góc vuông:</b> F = √(3,0² + 4,0²) = √(9 + 16) = √25 = 5,0 N.","svgGraph":null},{"q":"Lực kế đo hợp lực thực nghiệm chỉ F<sub>tn</sub> = 4,9 N, trong khi hợp lực tính từ hình bình hành là F<sub>lt</sub> = 5,0 N. Sai số tỉ đối của phép đo hợp lực là:","opts":["2,0%.","0,1%.","1,0%.","5,0%."],"ans":0,"exp":"• <b>Độ lệch tuyệt đối:</b> ΔF = |F<sub>lt</sub> - F<sub>tn</sub>| = |5,0 - 4,9| = 0,1 N.<br>• <b>Sai số tỉ đối:</b> δF = <span class=\"fraction\"><span class=\"numerator\">0,1</span><span class=\"denominator\">5,0</span></span> · 100% = 2,0%.","svgGraph":null},{"q":"Khi tiến hành thí nghiệm tổng hợp hai lực song song cùng chiều tác dụng lên một thước dẹt nhẹ có trục quay tự do, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Điểm đặt của hợp lực luôn nằm gần phía lực có độ lớn nhỏ hơn.","Hợp lực F của hai lực song song cùng chiều có độ lớn bằng tổng độ lớn hai lực: F = F₁ + F₂.","Hợp lực F có phương song song và cùng chiều với hai lực thành phần.","Điểm đặt của hợp lực chia trong khoảng cách giữa hai lực theo tỉ lệ nghịch: F₁·d₁ = F₂·d₂."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F = F₁ + F₂.<br>• <b>Ý b [Đúng]:</b> Cùng phương cùng chiều.<br>• <b>Ý c [Đúng]:</b> F₁·d₁ = F₂·d₂ (quy tắc đòn bẩy chia trong).<br>• <b>Ý d [Sai]:</b> Lực nào lớn hơn thì điểm đặt phải nằm gần lực đó hơn (cánh tay đòn ngắn hơn).","svgGraph":null},{"q":"Một tấm ván đồng chất dài L = 2 m được hai công nhân khiêng ở hai đầu. Người A khiêng ở đầu mút, người B khiêng ở đầu mút kia. Một vật nặng được đặt tại vị trí cách người A 0,5 m. So sánh lực nâng của hai người:","opts":["Người A chịu lực nặng gấp 3 lần người B.","Người B chịu lực nặng gấp 3 lần người A.","Hai người chịu lực nặng hoàn toàn bằng nhau.","Người A chịu toàn bộ trọng lượng, người B không chịu lực nào."],"ans":0,"exp":"• Khoảng cách từ vật đến A là d<sub>A</sub> = 0,5 m; đến B là d<sub>B</sub> = 2 - 0,5 = 1,5 m.<br>• Theo quy tắc tổng hợp hai lực song song: <span class=\"fraction\"><span class=\"numerator\">F<sub>A</sub></span><span class=\"denominator\">F<sub>B</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">d<sub>B</sub></span><span class=\"denominator\">d<sub>A</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">1,5</span><span class=\"denominator\">0,5</span></span> = 3. Vậy người A chịu lực nặng gấp 3 lần người B.","svgGraph":null}],"23":[{"q":"Biểu thức tính công của một lực không đổi F làm vật dịch chuyển một quãng đường s theo phương hợp với hướng của lực một góc α là:","opts":["A = F · s · cos(α).","A = F · s · sin(α).","A = F · s / cos(α).","A = F · s · tan(α)."],"ans":0,"exp":"• <b>Công thức tính công:</b> A = F·s·cos(α). Trong hệ SI, lực F đo bằng Newton (N), quãng đường s đo bằng mét (m), công A đo bằng Jun (Joule - J): 1 J = 1 N·m.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr23\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Ground line -->\n      <line x1=\"60\" y1=\"180\" x2=\"440\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <!-- Block -->\n      <rect x=\"120\" y=\"120\" width=\"80\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2.5\" rx=\"4\"/>\n      <!-- Displacement direction s -->\n      <line x1=\"200\" y1=\"180\" x2=\"380\" y2=\"180\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr23)\"/>\n      <text x=\"270\" y=\"200\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Quãng đường s</text>\n      <!-- Pulling Force F angled at alpha -->\n      <line x1=\"200\" y1=\"150\" x2=\"330\" y2=\"75\" stroke=\"#fbbf24\" stroke-width=\"3.5\" marker-end=\"url(#arr23)\"/>\n      <text x=\"340\" y=\"70\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Lực F</text>\n      <!-- Angle alpha arc -->\n      <line x1=\"200\" y1=\"150\" x2=\"310\" y2=\"150\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <path d=\"M 245,150 A 45 45 0 0 0 240,127\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <text x=\"255\" y=\"140\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">α</text>\n      <text x=\"145\" y=\"45\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">A = F · s · cos(α)</text>\n      <text x=\"130\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Mô hình tính công cơ học của lực F làm vật dịch chuyển s</text>\n    </svg>"},{"q":"Trong trường hợp nào sau đây lực tác dụng KHÔNG SINH CÔNG cơ học (A = 0)?","opts":["Lực tác dụng có phương vuông góc với phương dịch chuyển của vật (α = 90°).","Lực tác dụng cùng chiều với chiều chuyển động của vật (α = 0°).","Lực tác dụng ngược chiều với chiều chuyển động của vật (α = 180°).","Lực tác dụng hợp với hướng chuyển động một góc nhọn 45°."],"ans":0,"exp":"• Khi α = 90° thì cos(90°) = 0 ⇒ A = F·s·cos(90°) = 0. Ví dụ: Trọng lực không sinh công khi vật chuyển động trên mặt sàn nằm ngang phẳng.","svgGraph":null},{"q":"Một người kéo một thùng gỗ trượt trên sàn nằm ngang bằng một lực kéo F = 150 N hợp với phương ngang góc α = 60°. Thùng gỗ dịch chuyển được quãng đường s = 10 m. Công của lực kéo đã thực hiện là:","opts":["750 J.","1500 J.","1299 J.","0 J."],"ans":0,"exp":"• <b>Công của lực kéo:</b> A = F·s·cos(α) = 150 · 10 · cos(60°) = 1500 · 0,5 = 750 J.","svgGraph":null},{"q":"Về dấu của công cơ học và ý nghĩa vật lí, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực ma sát trượt tác dụng lên vật chuyển động luôn sinh công phát động làm vật tăng tốc độ.","Khi góc hợp α là góc nhọn (0° ≤ α < 90°), công A > 0 được gọi là công phát động (sinh công dương thúc đẩy chuyển động).","Khi góc hợp α là góc tù (90° < α ≤ 180°), công A < 0 được gọi là công cản (cản trở chuyển động).","Đơn vị đo công trong hệ SI là Joule (J), 1 J tương đương với công do lực 1 N thực hiện trên quãng đường 1 m theo hướng của lực."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> cosα > 0 ⇒ A > 0 (công phát động).<br>• <b>Ý b [Đúng]:</b> cosα < 0 ⇒ A < 0 (công cản).<br>• <b>Ý c [Sai]:</b> Lực ma sát trượt ngược chiều chuyển động (α = 180°, cos 180° = -1) nên luôn sinh công cản âm (A<sub>ms</sub> < 0) biến cơ năng thành nhiệt.<br>• <b>Ý d [Đúng]:</b> 1 J = 1 N·m.","svgGraph":null},{"q":"Ghép góc hợp α ở Cột A với tính chất của công cơ học ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["α = 0° (lực cùng chiều dịch chuyển) ➔ A = 0 (lực không sinh công)","α = 0° (lực cùng chiều dịch chuyển) ➔ A = F · s (công phát động cực đại)","α = 180° (lực ngược chiều dịch chuyển) ➔ A = 0 (lực không sinh công)","α = 90° (lực vuông góc hướng chuyển động) ➔ A = F · s (công phát động cực đại)"],"ans":0,"exp":"• <b>1 - B:</b> α = 0°: A = F·s.<br>• <b>2 - C:</b> α = 180°: A = -F·s.<br>• <b>3 - A:</b> α = 90°: A = 0.<br>• <b>4 - D:</b> Góc nhọn: A > 0.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Năng lượng không tự nhiên sinh ra và cũng không tự nhiên  [ ... ] , nó chỉ truyền từ vật này sang vật khác hoặc chuyển hoá từ  [ ... ]  này sang dạng khác. Trong các quá trình cơ học có ma sát, một phần cơ năng luôn bị chuyển hoá thành  [ ... ]  làm nóng môi trường. Tổng năng lượng của một hệ cô lập luôn là một đại lượng  [ ... ] .\"</i>","opts":["mất đi — dạng năng lượng","không đổi","phát sinh thêm — điện năng","dạng năng lượng — mất đi"],"ans":0,"exp":"<b>Định luật bảo toàn năng lượng:</b><br>• Không tự sinh ra hay mất đi.<br>• Chuyển hoá giữa các dạng năng lượng.<br>• Ma sát sinh nhiệt năng.<br>• Hệ cô lập bảo toàn tổng năng lượng.","svgGraph":null},{"q":"Một vật có khối lượng m = 2 kg rơi tự do từ độ cao h = 10 m xuống mặt đất. Lấy g = 10 m/s². Công của trọng lực thực hiện trong suốt quá trình rơi này là:","opts":["200 J.","-200 J.","100 J.","0 J."],"ans":0,"exp":"• <b>Công của trọng lực:</b> A<sub>P</sub> = m·g·h (vì trọng lực cùng chiều chuyển động rơi thẳng đứng nên α = 0°).<br>• Thay số: A<sub>P</sub> = 2 · 10 · 10 = 200 J.","svgGraph":null},{"q":"Một ô tô hãm phanh chuyển động thẳng chậm dần đều trên quãng đường 20 m. Lực hãm của phanh có độ lớn không đổi F<sub>h</sub> = 3000 N. Công của lực hãm phanh là:","opts":["-60000 J (-60 kJ).","+60000 J (+60 kJ).","-30000 J.","+150000 J."],"ans":0,"exp":"• Lực hãm ngược chiều chuyển động nên α = 180° ⇒ cos(180°) = -1.<br>• <b>Công của lực hãm:</b> A = F<sub>h</sub> · s · cos(180°) = 3000 · 20 · (-1) = -60000 J = -60 kJ.","svgGraph":null},{"q":"Một lực kế kéo một vật nặng 5 kg trượt đều trên mặt bàn nằm ngang một đoạn 2 m với lực kéo nằm ngang F = 15 N. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tổng công của tất cả các lực tác dụng lên vật bằng 60 J.","Công của lực kéo thực hiện là A<sub>k</sub> = 30 J.","Vì vật trượt đều nên độ lớn lực ma sát trượt bằng đúng lực kéo: F<sub>mst</sub> = 15 N.","Công của lực ma sát trượt thực hiện là A<sub>ms</sub> = -30 J."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> A<sub>k</sub> = F<sub>k</sub> · s = 15 · 2 = 30 J.<br>• <b>Ý b [Đúng]:</b> Chuyển động thẳng đều nên hợp lực bằng 0 ⇒ F<sub>ms</sub> = F<sub>k</sub> = 15 N.<br>• <b>Ý c [Đúng]:</b> A<sub>ms</sub> = -F<sub>ms</sub> · s = -15 · 2 = -30 J.<br>• <b>Ý d [Sai]:</b> Tổng công: A<sub>tong</sub> = A<sub>k</sub> + A<sub>ms</sub> + A<sub>P</sub> + A<sub>N</sub> = 30 + (-30) + 0 + 0 = 0 J.","svgGraph":null},{"q":"Trong nhà máy thuỷ điện, dạng năng lượng nào của dòng nước ở trên hồ chứa đập cao được chuyển hoá thành điện năng?","opts":["Thế năng trọng trường của nước biến đổi thành động năng làm quay tuabin, sau đó máy phát biến cơ năng thành điện năng.","Nhiệt năng của nước đun sôi tạo hơi nước làm quay quạt gió.","Năng lượng hoá học của các phân tử nước giải phóng electron.","Năng lượng hạt nhân của các đồng vị hydro trong nước."],"ans":0,"exp":"• Chuỗi chuyển hoá năng lượng trong thuỷ điện: Thế năng nước chảy từ trên cao -> Động năng dòng chảy qua tuabin -> Cơ năng quay máy phát điện -> Điện năng.","svgGraph":null}],"24":[{"q":"Công suất là đại lượng đặc trưng cho:","opts":["Tốc độ thực hiện công của lực và được xác định bằng công thực hiện trong một đơn vị thời gian (P = A / t).","Tổng lượng công mà một cỗ máy có thể thực hiện được trong suốt vòng đời.","Mức độ tiêu hao nhiên liệu của động cơ đốt trong.","Khối lượng tối đa mà thiết bị nâng có thể cẩu lên cao."],"ans":0,"exp":"• <b>Định nghĩa công suất:</b> P = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">t</span></span>. Công suất là đại lượng đặc trưng cho tốc độ sinh công. Đơn vị trong hệ SI là Oát (Watt - W): 1 W = 1 J/s.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr24\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Crane Tower -->\n      <line x1=\"120\" y1=\"210\" x2=\"120\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"6\"/>\n      <line x1=\"80\" y1=\"210\" x2=\"160\" y2=\"210\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <line x1=\"100\" y1=\"40\" x2=\"380\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"5\"/>\n      <!-- Pulley Cable lifting container -->\n      <line x1=\"320\" y1=\"40\" x2=\"320\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <rect x=\"290\" y=\"120\" width=\"60\" height=\"40\" fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"3\"/>\n      <text x=\"305\" y=\"145\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">m</text>\n      <!-- Lifting speed vector v -->\n      <line x1=\"365\" y1=\"140\" x2=\"365\" y2=\"90\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr24)\"/>\n      <text x=\"375\" y=\"115\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">v</text>\n      <!-- Power formula text -->\n      <text x=\"180\" y=\"90\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">P = F · v</text>\n      <text x=\"180\" y=\"115\" fill=\"#94a3b8\" font-size=\"12\">(Lực kéo F nâng vật tốc độ v)</text>\n      <text x=\"140\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Cần cẩu thực hiện công nâng vật với công suất P = F · v</text>\n    </svg>"},{"q":"Mối liên hệ giữa công suất tức thời P, lực tác dụng F và vận tốc tức thời v khi lực cùng hướng với vận tốc là:","opts":["P = F · v.","P = F / v.","P = F · v².","P = F² · v."],"ans":0,"exp":"• Khi lực F cùng hướng với vận tốc v: P = A/t = (F·s)/t = F·(s/t) = F·v.","svgGraph":null},{"q":"Một cần cẩu nâng một khối bê tông nặng 1 tấn (1000 kg) lên cao 12 m trong thời gian 30 giây với tốc độ không đổi. Lấy g = 10 m/s². Công suất của cần cẩu là:","opts":["4000 W (4 kW).","2000 W (2 kW).","12000 W (12 kW).","400 W."],"ans":0,"exp":"• <b>Lực nâng cần cẩu:</b> F = P = mg = 1000 · 10 = 10000 N.<br>• <b>Công thực hiện:</b> A = F·h = 10000 · 12 = 120000 J.<br>• <b>Công suất:</b> P = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">t</span></span> = <span class=\"fraction\"><span class=\"numerator\">120000</span><span class=\"denominator\">30</span></span> = 4000 W = 4 kW.","svgGraph":null},{"q":"Về công suất của các phương tiện giao thông và máy móc cơ khí, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Một cỗ máy thực hiện công càng lớn thì chắc chắn luôn có công suất lớn hơn cỗ máy khác.","Đơn vị mã lực (Horse Power - HP) thường dùng cho động cơ ô tô xấp xỉ bằng 746 Watt.","Khi một ô tô đang chạy với công suất động cơ tối đa không đổi, nếu muốn tăng lực kéo F để vượt dốc thì tài xế cần chuyển về số thấp để giảm vận tốc v (vì P = F·v).","Công suất trung bình bằng thương số giữa toàn bộ công thực hiện và khoảng thời gian thực hiện công đó."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> 1 HP ≈ 746 W (chuẩn Anh/Mỹ).<br>• <b>Ý b [Đúng]:</b> P = F·v = const, v giảm thì lực kéo F tăng lên giúp xe leo dốc khoẻ.<br>• <b>Ý c [Sai]:</b> Máy thực hiện công A lớn nhưng tốn rất nhiều thời gian t thì công suất P = A/t có thể rất nhỏ.<br>• <b>Ý d [Đúng]:</b> P<sub>tb</sub> = A / Δt.","svgGraph":null},{"q":"Ghép đơn vị đo công suất ở Cột A với giá trị tương đương ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["1 Kilowatt (1 kW) ➔ 1 000 000 Watt (10⁶ W)","1 Kilowatt (1 kW) ➔ 1 000 Watt (10³ W)","1 Megawatt (1 MW) ➔ 1 000 000 Watt (10⁶ W)","1 Mã lực (1 HP) ➔ 1 000 Watt (10³ W)"],"ans":0,"exp":"• <b>1 - B:</b> 1 kW = 10³ W.<br>• <b>2 - A:</b> 1 MW = 10⁶ W.<br>• <b>3 - C:</b> 1 HP ≈ 746 W.<br>• <b>4 - D:</b> 1 GW = 10⁹ W.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Hộp số của xe máy và ô tô hoạt động dựa trên nguyên lí công suất của động cơ  [ ... ] . Khi động cơ hoạt động ở một mức công suất nhất định, mối liên hệ giữa lực kéo F và vận tốc v là  [ ... ] . Khi xe khởi hành hoặc leo dốc cần lực kéo F rất lớn nên tài xế chọn số thấp ( [ ... ] ). Khi xe chạy trên đường trường bằng phẳng cần tốc độ cao thì tài xế gài số cao ( [ ... ] ).\"</i>","opts":["P = F · v = const — tỉ lệ nghịch với nhau","không đổi","tỉ lệ thuận với nhau — vận tốc cực đại","tỉ lệ nghịch với nhau — P = F · v = const"],"ans":0,"exp":"<b>Nguyên tắc số xe:</b><br>• P = F·v = const.<br>• F tỉ lệ nghịch với v.<br>• Leo dốc: số thấp (1, 2) cho F lớn.<br>• Đường trường: số cao (4, 5) cho v lớn.","svgGraph":null},{"q":"Một ô tô có động cơ công suất P = 60 kW đang chuyển động thẳng đều trên đường nằm ngang với tốc độ v = 20 m/s (72 km/h). Lực kéo của động cơ ô tô khi đó là:","opts":["3000 N.","1200 N.","300 N.","6000 N."],"ans":0,"exp":"• <b>Công thức:</b> P = F·v ⇒ F = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">v</span></span><br>• <b>Thay số:</b> F = <span class=\"fraction\"><span class=\"numerator\">60000</span><span class=\"denominator\">20</span></span> = 3000 N.","svgGraph":null},{"q":"Một máy bơm nước có công suất định mức P = 1,5 kW hoạt động liên tục trong 2 giờ. Công cơ học mà máy bơm đã thực hiện là:","opts":["1,08·10⁷ J (10,8 MJ).","3,0·10⁶ J.","1,5·10³ J.","5,4·10⁵ J."],"ans":0,"exp":"• <b>Đổi thời gian:</b> t = 2 h = 2 · 3600 = 7200 s.<br>• <b>Công thực hiện:</b> A = P·t = 1500 · 7200 = 10800000 J = 10,8 MJ.","svgGraph":null},{"q":"Một vận động viên leo núi nặng m = 70 kg leo lên đỉnh núi có độ cao thẳng đứng h = 600 m trong thời gian 50 phút. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu người đó leo lên đỉnh trong thời gian 25 phút (nhanh gấp đôi) thì công thực hiện cũng tăng lên gấp đôi.","Trọng lượng của vận động viên là P = 700 N.","Công tối thiểu mà vận động viên phải thực hiện chống lại trọng lực là A = 420000 J.","Công suất trung bình của vận động viên này trong suốt chặng leo là 140 W."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> P = mg = 70 · 10 = 700 N.<br>• <b>Ý b [Đúng]:</b> A = mgh = 700 · 600 = 420000 J = 420 kJ.<br>• <b>Ý c [Đúng]:</b> t = 50 · 60 = 3000 s ⇒ P<sub>tb</sub> = 420000 / 3000 = 140 W.<br>• <b>Ý d [Sai]:</b> Công A = mgh không đổi (chỉ phụ thuộc độ cao), thời gian giảm một nửa thì công suất P tăng gấp đôi chứ công không đổi.","svgGraph":null},{"q":"Trên nhãn mác của một máy hút bụi gia đình có ghi thông số: '220 V - 1800 W'. Ý nghĩa của con số 1800 W là:","opts":["Công suất tiêu thụ điện định mức của máy khi cắm vào nguồn điện chuẩn 220 V.","Công suất hút bụi cơ học có ích thực tế của đầu chổi hút.","Tổng lượng điện năng tiêu thụ trong một tháng sử dụng.","Lực hút cực đại của máy đo bằng Newton."],"ans":0,"exp":"• Số Oát (W) ghi trên thiết bị điện gia dụng là công suất tiêu thụ định mức của thiết bị khi hoạt động ở hiệu điện thế danh định ghi trên nhãn.","svgGraph":null}],"25":[{"q":"Động năng của một vật khối lượng m đang chuyển động với vận tốc v được tính theo công thức:","opts":["W<sub>đ</sub> = 1/2 · m · v².","W<sub>đ</sub> = m · v².","W<sub>đ</sub> = 1/2 · m · v.","W<sub>đ</sub> = 2 · m · v²."],"ans":0,"exp":"• <b>Công thức động năng:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v². Động năng là dạng năng lượng mà vật có được do nó đang chuyển động, tỉ lệ thuận với khối lượng m và bình phương vận tốc v². Đơn vị là Joule (J).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr25\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Height reference ground -->\n      <line x1=\"50\" y1=\"200\" x2=\"450\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <text x=\"350\" y=\"218\" fill=\"#64748b\" font-size=\"12\">Mốc thế năng (z = 0, W<tspan baseline-shift=\"sub\" font-size=\"70%\">t</tspan> = 0)</text>\n      <!-- Object at height z -->\n      <rect x=\"180\" y=\"60\" width=\"70\" height=\"50\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"205\" y=\"90\" fill=\"#f8fafc\" font-size=\"14\" font-weight=\"bold\">m</text>\n      <!-- Velocity vector v -->\n      <line x1=\"250\" y1=\"85\" x2=\"350\" y2=\"85\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr25)\"/>\n      <text x=\"300\" y=\"75\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">v</text>\n      <!-- Height z bracket -->\n      <line x1=\"150\" y1=\"85\" x2=\"150\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"150\" cy=\"85\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"150\" cy=\"200\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"125\" y=\"145\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">z</text>\n      <!-- Formula texts -->\n      <text x=\"280\" y=\"140\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">W<tspan baseline-shift=\"sub\" font-size=\"70%\">đ</tspan> = ½·m·v²</text>\n      <text x=\"280\" y=\"170\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">W<tspan baseline-shift=\"sub\" font-size=\"70%\">t</tspan> = m·g·z</text>\n      <text x=\"135\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Hai dạng năng lượng cơ học: Động năng và Thế năng trọng trường</text>\n    </svg>"},{"q":"Thế năng trọng trường của một vật khối lượng m ở độ cao z so với mốc thế năng đã chọn được xác định bằng công thức:","opts":["W<sub>t</sub> = m · g · z.","W<sub>t</sub> = 1/2 · m · g · z.","W<sub>t</sub> = m · g / z.","W<sub>t</sub> = m · g · z²."],"ans":0,"exp":"• <b>Thế năng trọng trường:</b> W<sub>t</sub> = m·g·z, là năng lượng tương tác giữa Trái Đất và vật, phụ thuộc vào vị trí của vật trong trọng trường so với mốc thế năng quy ước.","svgGraph":null},{"q":"Một ô tô có khối lượng m = 1,5 tấn (1500 kg) đang chuyển động với tốc độ v = 72 km/h (20 m/s). Động năng của ô tô là:","opts":["300000 J (300 kJ).","150000 J (150 kJ).","600000 J.","30000 J."],"ans":0,"exp":"• <b>Công thức động năng:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v²<br>• <b>Thay số:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 1500 · (20)² = 750 · 400 = 300000 J = 300 kJ.","svgGraph":null},{"q":"Về tính chất của động năng và thế năng trọng trường, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ biến thiên thế năng giữa hai điểm luôn phụ thuộc vào cách chọn mốc tính thế năng.","Động năng là đại lượng vô hướng luôn không âm (W<sub>đ</sub> ≥ 0).","Nếu vận tốc của một vật tăng lên gấp đôi thì động năng của nó tăng lên gấp 4 lần.","Giá trị của thế năng trọng trường W<sub>t</sub> có thể mang giá trị dương, bằng không hoặc âm tuỳ thuộc vào việc chọn mốc thế năng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> m > 0 và v² ≥ 0 nên W<sub>đ</sub> ≥ 0.<br>• <b>Ý b [Đúng]:</b> v tăng 2 lần ⇒ v² tăng 4 lần ⇒ W<sub>đ</sub> tăng 4 lần.<br>• <b>Ý c [Đúng]:</b> Ở trên mốc z > 0 (W<sub>t</sub> > 0), tại mốc z = 0 (W<sub>t</sub> = 0), ở dưới mốc z < 0 (W<sub>t</sub> < 0).<br>• <b>Ý d [Sai]:</b> Hiệu thế năng W<sub>t1</sub> - W<sub>t2</sub> = mg(z₁ - z₂) = A<sub>P</sub> luôn bất biến, hoàn toàn không phụ thuộc vào vị trí chọn mốc.","svgGraph":null},{"q":"Ghép định lí năng lượng ở Cột A với biểu thức tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Định lí động năng ➔ W<sub>t</sub> = m · g · z","Định lí động năng ➔ W<sub>đ</sub>2 - W<sub>đ</sub>1 = A<sub>ngo</sub>ạilực","Thế năng trọng trường ➔ W<sub>t</sub> = m · g · z","Mối liên hệ công trọng lực và độ giảm thế năng ➔ W<sub>đ</sub>2 - W<sub>đ</sub>1 = A<sub>ngo</sub>ạilực"],"ans":0,"exp":"• <b>1 - B:</b> ΔW<sub>đ</sub> = A.<br>• <b>2 - A:</b> W<sub>t</sub> = mgz.<br>• <b>3 - D:</b> A<sub>P</sub> = W<sub>t1</sub> - W<sub>t2</sub>.<br>• <b>4 - C:</b> Thế năng lò xo: 1/2 k(Δl)².","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Định lí động năng phát biểu rằng: độ biến thiên động năng của một vật bằng  [ ... ]  của các ngoại lực tác dụng lên vật. Biểu thức là  [ ... ] . Nếu ngoại lực sinh công phát động (A > 0) thì động năng của vật  [ ... ] . Nếu ngoại lực sinh công cản (A < 0) thì động năng của vật  [ ... ] .\"</i>","opts":["tổng công — W<sub>đ</sub>2 - W<sub>đ</sub>1 = A","không đổi","hiệu công — không đổi","W<sub>đ</sub>2 - W<sub>đ</sub>1 = A — tổng công"],"ans":0,"exp":"<b>Định lí động năng:</b><br>• ΔW<sub>đ</sub> = A.<br>• A > 0: W<sub>đ</sub> tăng.<br>• A < 0: W<sub>đ</sub> giảm.","svgGraph":null},{"q":"Một lò xo có độ cứng k = 100 N/m bị nén một đoạn Δl = 4 cm = 0,04 m so với chiều dài tự nhiên. Thế năng đàn hồi dự trữ trong lò xo là:","opts":["0,08 J.","0,16 J.","8,0 J.","0,04 J."],"ans":0,"exp":"• <b>Công thức thế năng đàn hồi:</b> W<sub>t</sub>đh = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>k·(Δl)²<br>• <b>Thay số:</b> W<sub>t</sub>đh = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 100 · (0,04)² = 50 · 0,0016 = 0,08 J (80 mJ).","svgGraph":null},{"q":"Một hòn đá khối lượng m = 400 g (0,4 kg) được ném thẳng đứng lên cao từ mặt đất với vận tốc ban đầu v₀ = 15 m/s. Lấy g = 10 m/s², chọn mốc thế năng tại mặt đất. Động năng ban đầu của hòn đá là:","opts":["45 J.","90 J.","22,5 J.","60 J."],"ans":0,"exp":"• <b>Động năng ban đầu:</b> W<sub>đ</sub>0 = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,4 · (15)² = 0,2 · 225 = 45 J.","svgGraph":null},{"q":"Một cuốn sách có khối lượng m = 500 g đặt trên mặt bàn cao 0,8 m so với sàn nhà. Trần nhà cao 3,0 m so với sàn nhà. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Nếu chọn mốc thế năng tại mặt sàn nhà thì thế năng của cuốn sách là W<sub>t</sub> = 4 J.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> z = 0,8 m ⇒ W<sub>t</sub> = 0,5 · 10 · 0,8 = 4 J.<br>• <b>Ý b [Đúng]:</b> Tại bàn z = 0 ⇒ W<sub>t</sub> = 0.<br>• <b>Ý c [Đúng]:</b> So với trần: z = 0,8 - 3,0 = -2,2 m ⇒ W<sub>t</sub> = 0,5 · 10 · (-2,2) = -11 J.<br>• <b>Ý d [Đúng]:</b> ΔW<sub>t</sub> = mg·Δz = 0,5 · 10 · 0,8 = 4 J là bất biến.","svgGraph":null},{"q":"Một viên đạn khối lượng 10 g đang bay với vận tốc 400 m/s thì xuyên vào một tấm gỗ dày và dừng lại. Lực cản trung bình của tấm gỗ tác dụng lên viên đạn biết bề dày xuyên sâu là 8 cm (0,08 m) có độ lớn là:","opts":["10000 N (10 kN).","5000 N.","20000 N.","800 N."],"ans":0,"exp":"• <b>Định lí động năng:</b> 0 - <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀² = -F<sub>c</sub> · d<br>• Thay số: <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,01 · 400² = F<sub>c</sub> · 0,08 ⇒ 800 = 0,08·F<sub>c</sub> ⇒ F<sub>c</sub> = <span class=\"fraction\"><span class=\"numerator\">800</span><span class=\"denominator\">0,08</span></span> = 10000 N = 10 kN.","svgGraph":null}],"26":[{"q":"Cơ năng của một vật chuyển động dưới tác dụng của trọng lực là đại lượng bằng:","opts":["Tổng động năng và thế năng trọng trường của vật: W = W<sub>đ</sub> + W<sub>t</sub>.","Hiệu số giữa động năng và thế năng trọng trường.","Tích của động năng với thế năng của vật.","Bình phương của động năng cộng với bình phương thế năng."],"ans":0,"exp":"• <b>Định nghĩa cơ năng:</b> Cơ năng W bằng tổng động năng và thế năng của vật: W = W<sub>đ</sub> + W<sub>t</sub> = ½ m·v² + mgz. Đơn vị là Joule (J).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Simple Pendulum Track -->\n      <line x1=\"250\" y1=\"30\" x2=\"250\" y2=\"180\" stroke=\"#475569\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Ceiling -->\n      <line x1=\"180\" y1=\"30\" x2=\"320\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"4\"/>\n      <!-- Extreme Position Left A -->\n      <line x1=\"250\" y1=\"30\" x2=\"150\" y2=\"130\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"150\" cy=\"130\" r=\"14\" fill=\"#ef4444\"/>\n      <text x=\"175\" y=\"215\" fill=\"#a7f3d0\" font-size=\"11\" font-weight=\"bold\">Vị trí cân bằng O: Động năng cực đại, thế năng cực tiểu</text>\n      <!-- Extreme Position Right B -->\n      <line x1=\"250\" y1=\"30\" x2=\"350\" y2=\"130\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"350\" cy=\"130\" r=\"14\" fill=\"#ef4444\"/>\n      <text x=\"370\" y=\"130\" fill=\"#fca5a5\" font-size=\"11\" font-weight=\"bold\">Vị trí biên B:</text>\n      <text x=\"70\" y=\"145\" fill=\"#fca5a5\" font-size=\"11\">Thế năng cực đại (v = 0)</text>\n      <!-- Swing arc -->\n      <path d=\"M 150,130 Q 250,200 350,130\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"135\" y=\"55\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Mô hình con lắc đơn dao động trong trọng trường</text>\n    </svg>"},{"q":"Định luật bảo toàn cơ năng phát biểu rằng: Khi một vật chỉ chịu tác dụng của lực thế (như trọng lực hoặc lực đàn hồi), cơ năng của vật là một đại lượng:","opts":["Bảo toàn (không đổi theo thời gian): W = const.","Tăng dần đều theo thời gian.","Giảm dần về không do định luật vạn vật hấp dẫn.","Biến thiên điều hoà quanh giá trị 0."],"ans":0,"exp":"• <b>Định luật bảo toàn cơ năng:</b> Khi vật chuyển động chỉ chịu tác dụng của trọng lực (hoặc lực đàn hồi), động năng có thể chuyển hoá thành thế năng và ngược lại nhưng tổng cơ năng luôn được bảo toàn: W = W<sub>đ</sub> + W<sub>t</sub> = const.","svgGraph":null},{"q":"Thả rơi tự do một vật m = 1 kg từ độ cao h = 20 m so với mặt đất. Lấy g = 10 m/s², chọn mốc thế năng tại mặt đất. Vận tốc của vật khi chạm đất là:","opts":["20 m/s.","10 m/s.","14,1 m/s.","40 m/s."],"ans":0,"exp":"• <b>Bảo toàn cơ năng giữa đỉnh và mặt đất:</b><br>m·g·h = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v² ⇒ v = √(2·g·h) = √(2 · 10 · 20) = √400 = 20 m/s.","svgGraph":null},{"q":"Một con lắc đơn gồm quả cầu nhỏ treo vào sợi dây mảnh nhẹ không dãn được kéo lệch góc α₀ rồi thả nhẹ không vận tốc đầu. Bỏ qua mọi ma sát và sức cản không khí. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu có lực cản không khí thì cơ năng của con lắc vẫn được bảo toàn nguyên vẹn.","Cơ năng của con lắc được bảo toàn trong suốt quá trình dao động.","Tại vị trí biên (góc lệch cực đại α₀), động năng bằng không và thế năng đạt cực đại.","Tại vị trí cân bằng (phương thẳng đứng), thế năng nhỏ nhất và tốc độ quả cầu đạt giá trị cực đại."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Chỉ chịu trọng lực P và lực căng T vuông góc vận tốc (không sinh công) nên cơ năng bảo toàn.<br>• <b>Ý b [Đúng]:</b> Tại biên v = 0 ⇒ W<sub>đ</sub> = 0, z max ⇒ W<sub>t</sub> max.<br>• <b>Ý c [Đúng]:</b> Tại VCB z min ⇒ v max.<br>• <b>Ý d [Sai]:</b> Lực cản không khí sinh công âm làm cơ năng tiêu hao thành nhiệt (dao động tắt dần).","svgGraph":null},{"q":"Ghép trạng thái tại các vị trí đặc biệt trong chuyển động con lắc đơn ở Cột A với tính chất cơ năng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vị trí biên (v = 0) ➔ Thế năng bằng một nửa cơ năng (z = h<sub>max</sub> / 2)","Vị trí biên (v = 0) ➔ Cơ năng không bảo toàn, độ giảm cơ năng bằng công của lực ma sát","Vị trí cân bằng (z = 0) ➔ Thế năng bằng một nửa cơ năng (z = h<sub>max</sub> / 2)","Vị trí có W<sub>đ</sub> = W<sub>t</sub> ➔ Cơ năng không bảo toàn, độ giảm cơ năng bằng công của lực ma sát"],"ans":0,"exp":"• <b>1 - C:</b> Biên: W<sub>t</sub> max, W<sub>đ</sub> = 0.<br>• <b>2 - D:</b> VCB: W<sub>đ</sub> max, W<sub>t</sub> = 0.<br>• <b>3 - A:</b> W<sub>đ</sub> = W<sub>t</sub>: W<sub>t</sub> = W/2 ⇒ z = h<sub>max</sub>/2.<br>• <b>4 - B:</b> Có ma sát: W₂ - W₁ = A<sub>ms</sub>.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi một vật chuyển động chịu tác dụng của các lực không phải là lực thế (như lực ma sát, lực cản), thì cơ năng của vật  [ ... ] . Độ biến thiên cơ năng của vật bằng  [ ... ]  của các lực không thế đó:  [ ... ] . Phần cơ năng bị giảm đi đã chuyển hoá hoàn toàn thành  [ ... ]  làm nóng các bề mặt cọ xát.\"</i>","opts":["không được bảo toàn — công","không đổi","bảo toàn tuyệt đối — thế năng","công — không được bảo toàn"],"ans":0,"exp":"<b>Biến thiên cơ năng:</b><br>• Ma sát làm cơ năng không bảo toàn.<br>• ΔW = W₂ - W₁ = A<sub>c</sub>ản.<br>• Cơ năng giảm biến thành nhiệt năng.","svgGraph":null},{"q":"Một vật được ném thẳng đứng lên cao từ mặt đất với vận tốc ban đầu v₀ = 20 m/s. Lấy g = 10 m/s², bỏ qua sức cản không khí. Ở độ cao nào thì thế năng của vật bằng 3 lần động năng (W<sub>t</sub> = 3·W<sub>đ</sub>)?","opts":["15 m.","10 m.","5 m.","20 m."],"ans":0,"exp":"• <b>Cơ năng tại mặt đất:</b> W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀².<br>• <b>Tại vị trí W<sub>t</sub> = 3·W<sub>đ</sub>:</b> W = W<sub>đ</sub> + W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">W<sub>t</sub></span><span class=\"denominator\">3</span></span> + W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>m·g·z.<br>• <b>Bảo toàn cơ năng:</b> <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m·v₀² = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>m·g·z ⇒ z = <span class=\"fraction\"><span class=\"numerator\">3·v₀²</span><span class=\"denominator\">8g</span></span> = <span class=\"fraction\"><span class=\"numerator\">3 · 400</span><span class=\"denominator\">8 · 10</span></span> = 15 m.","svgGraph":null},{"q":"Một vật trượt từ đỉnh một mặt dốc nghiêng cao h = 5 m xuống chân dốc. Do có ma sát, vận tốc của vật tại chân dốc đo được là v = 8 m/s. Lấy g = 10 m/s². Tỉ lệ phần trăm cơ năng bị mất đi do ma sát là:","opts":["36%.","64%.","50%.","20%."],"ans":0,"exp":"• <b>Cơ năng ban đầu ở đỉnh:</b> W₁ = mgh = m · 10 · 5 = 50m (J).<br>• <b>Cơ năng ở chân dốc:</b> W₂ = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mv² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m · 8² = 32m (J).<br>• <b>Phần cơ năng bị mất:</b> ΔW = W₁ - W₂ = 50m - 32m = 18m (J).<br>• <b>Tỉ lệ phần trăm mất đi:</b> <span class=\"fraction\"><span class=\"numerator\">18m</span><span class=\"denominator\">50m</span></span> · 100% = 36%.","svgGraph":null},{"q":"Một viên sỏi rơi từ trên cao xuống cắm sâu vào lớp cát mềm dưới mặt đất rồi dừng lại. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trong suốt cả quá trình từ lúc rơi đến khi nằm yên trong cát, cơ năng luôn được bảo toàn tuyệt đối.","Trong giai đoạn rơi tự do trong không khí (bỏ qua sức cản), cơ năng của viên sỏi được bảo toàn.","Khi xuyên vào cát, lực cản rất lớn của cát sinh công âm làm cơ năng của viên sỏi giảm về không.","Toàn bộ cơ năng ban đầu của viên sỏi đã chuyển hoá thành nhiệt năng làm nóng viên sỏi và cát xung quanh."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Rơi tự do cơ năng bảo toàn.<br>• <b>Ý b [Đúng]:</b> Lực cản cát sinh công cản triệt tiêu cơ năng.<br>• <b>Ý c [Đúng]:</b> Cơ năng biến thành nhiệt năng.<br>• <b>Ý d [Sai]:</b> Cơ năng không bảo toàn khi va chạm cát (năng lượng toàn phần thì bảo toàn, nhưng cơ năng bị tiêu tán).","svgGraph":null},{"q":"Ứng dụng nào sau đây dựa trên nguyên tắc chuyển hoá thế năng đàn hồi thành động năng để phóng vật thể đi xa?","opts":["Cung tên và súng cao su.","Động cơ phản lực của máy bay siêu âm.","Tua-bin gió phát điện ven biển.","Lò phản ứng nhiệt hạch."],"ans":0,"exp":"• Kéo căng dây cung hoặc dây cao su tích luỹ thế năng đàn hồi; khi buông tay thế năng giải phóng biến đổi thành động năng đẩy mũi tên hoặc viên đạn bay vọt đi xa.","svgGraph":null}],"27":[{"q":"Hiệu suất H của một động cơ hoặc thiết bị chuyển hoá năng lượng được xác định bằng tỉ số giữa:","opts":["Năng lượng có ích và năng lượng toàn phần cung cấp cho thiết bị: H = (A<sub>ích</sub> / A<sub>to</sub>ànphần) · 100%.","Năng lượng hao phí và năng lượng toàn phần cung cấp.","Năng lượng toàn phần và năng lượng có ích.","Nhiệt lượng toả ra môi trường và công có ích."],"ans":0,"exp":"• <b>Công thức hiệu suất:</b> H = <span class=\"fraction\"><span class=\"numerator\">A<sub>ích</sub></span><span class=\"denominator\">A<sub>to</sub>ànphần</span></span> · 100% = <span class=\"fraction\"><span class=\"numerator\">P<sub>ích</sub></span><span class=\"denominator\">P<sub>to</sub>ànphần</span></span> · 100%. Hiệu suất luôn nhỏ hơn hoặc bằng 100% (H ≤ 1).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr27\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Sankey-like energy flow diagram -->\n      <!-- Input Energy -->\n      <rect x=\"50\" y=\"90\" width=\"120\" height=\"60\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"65\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">NĂNG LƯỢNG</text>\n      <text x=\"65\" y=\"135\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">TOÀN PHẦN</text>\n      <!-- Useful Output Arrow -->\n      <line x1=\"170\" y1=\"110\" x2=\"330\" y2=\"70\" stroke=\"#34d399\" stroke-width=\"4\" marker-end=\"url(#arr27)\"/>\n      <rect x=\"330\" y=\"50\" width=\"130\" height=\"40\" fill=\"#064e3b\" stroke=\"#34d399\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"345\" y=\"75\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">CÓ ÍCH (W<tspan baseline-shift=\"sub\" font-size=\"70%\">ích</tspan>)</text>\n      <!-- Waste/Loss Output Arrow -->\n      <line x1=\"170\" y1=\"130\" x2=\"330\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arr27)\"/>\n      <rect x=\"330\" y=\"150\" width=\"130\" height=\"40\" fill=\"#7f1d1d\" stroke=\"#f43f5e\" stroke-width=\"2\" rx=\"4\"/>\n      <text x=\"345\" y=\"175\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">HAO PHÍ (W<tspan baseline-shift=\"sub\" font-size=\"70%\">hp</tspan>)</text>\n      <text x=\"120\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Sơ đồ dòng năng lượng: W<tspan baseline-shift=\"sub\" font-size=\"70%\">tp</tspan> = W<tspan baseline-shift=\"sub\" font-size=\"70%\">ích</tspan> + W<tspan baseline-shift=\"sub\" font-size=\"70%\">hp</tspan></text>\n    </svg>"},{"q":"Một bóng đèn LED tiêu thụ công suất điện toàn phần P<sub>tp</sub> = 20 W, trong đó công suất phát sáng có ích là P<sub>ích</sub> = 6 W. Hiệu suất chiếu sáng của bóng đèn LED là:","opts":["30%.","33,3%.","70%.","12%."],"ans":0,"exp":"• <b>Công thức hiệu suất:</b> H = <span class=\"fraction\"><span class=\"numerator\">P<sub>ích</sub></span><span class=\"denominator\">P<sub>tp</sub></span></span> · 100% = <span class=\"fraction\"><span class=\"numerator\">6</span><span class=\"denominator\">20</span></span> · 100% = 30%. (70% năng lượng còn lại biến thành nhiệt hao phí).","svgGraph":null},{"q":"Tại sao hiệu suất của các cỗ máy thực tế trong kĩ thuật và đời sống không bao giờ đạt được mức 100%?","opts":["Vì luôn tồn tại ma sát, sức cản hoặc điện trở biến một phần năng lượng thành nhiệt năng hao phí toả ra môi trường.","Vì các kĩ sư chế tạo máy chưa đủ trình độ công nghệ cao.","Vì lực hấp dẫn của Trái Đất triệt tiêu một phần công cơ học.","Vì các định luật Newton chỉ áp dụng cho chất điểm lí tưởng."],"ans":0,"exp":"• Theo nguyên lí nhiệt động lực học, trong bất kì quá trình chuyển hoá năng lượng cơ, điện, nhiệt thực tế nào cũng có sự tiêu tán năng lượng do ma sát hoặc toả nhiệt Joules nên A<sub>ích</sub> luôn nhỏ hơn A<sub>to</sub>ànphần ⇒ H < 100%.","svgGraph":null},{"q":"Một động cơ điện kéo một thang tời nâng một thùng hàng có trọng lượng P = 1200 N lên cao h = 10 m trong thời gian 15 giây. Công suất tiêu thụ điện toàn phần của động cơ là P<sub>tp</sub> = 1000 W. Xét tính Đúng / Sai của các nhận định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Công có ích mà động cơ thực hiện để nâng thùng hàng là A<sub>ích</sub> = 12000 J.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> A<sub>ích</sub> = P·h = 1200 · 10 = 12000 J.<br>• <b>Ý b [Đúng]:</b> A<sub>tp</sub> = P<sub>tp</sub> · t = 1000 · 15 = 15000 J.<br>• <b>Ý c [Đúng]:</b> H = 12000 / 15000 · 100% = 80%.<br>• <b>Ý d [Đúng]:</b> A<sub>hp</sub> = 15000 - 12000 = 3000 J.","svgGraph":null},{"q":"Ghép loại thiết bị ở Cột A với hiệu suất chuyển hoá năng lượng điển hình ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Động cơ xe điện (Electric Motor) ➔ Hiệu suất rất cao, khoảng 85% đến 95%","Động cơ xe điện (Electric Motor) ➔ Hiệu suất rất thấp, chỉ khoảng 2% đến 5% phát sáng, 95% toả nhiệt","Động cơ xăng ô tô (Internal Combustion) ➔ Hiệu suất rất cao, khoảng 85% đến 95%","Bóng đèn sợi đốt cổ điển ➔ Hiệu suất rất thấp, chỉ khoảng 2% đến 5% phát sáng, 95% toả nhiệt"],"ans":0,"exp":"• <b>1 - A:</b> Động cơ điện: 85-95%.<br>• <b>2 - C:</b> Động cơ nhiệt xăng: 25-35%.<br>• <b>3 - B:</b> Đèn sợi đốt: chỉ 2-5% quang năng.<br>• <b>4 - D:</b> Pin mặt trời: 18-23%.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Để nâng cao hiệu suất của các máy móc và bảo vệ môi trường, trong kĩ thuật người ta thường  [ ... ]  định kì các chi tiết quay để giảm lực ma sát. Thiết kế phương tiện giao thông theo biên dạng  [ ... ]  để giảm lực cản không khí. Thay thế các bóng đèn sợi đốt tiêu tốn điện bằng đèn  [ ... ] . Sử dụng các thiết bị dán nhãn năng lượng  [ ... ]  để tiết kiệm điện.\"</i>","opts":["tra dầu mỡ bôi trơn — khí động học thuôn mượt","không đổi","lực ma sát trượt — đèn huỳnh quang","khí động học thuôn mượt — tra dầu mỡ bôi trơn"],"ans":0,"exp":"<b>Nâng cao hiệu suất:</b><br>• Bôi trơn giảm ma sát.<br>• Khí động học giảm cản gió.<br>• Dùng đèn LED.<br>• Thiết bị nhãn năng lượng 5 sao tiết kiệm điện.","svgGraph":null},{"q":"Một bếp điện có hiệu suất H = 75% được dùng để đun sôi 2 kg nước từ 25°C. Nhiệt lượng có ích làm nước sôi là Q<sub>ích</sub> = 630000 J. Tổng điện năng mà bếp đã tiêu thụ từ lưới điện là:","opts":["840000 J (840 kJ).","472500 J.","630000 J.","1050000 J."],"ans":0,"exp":"• <b>Công thức hiệu suất:</b> H = <span class=\"fraction\"><span class=\"numerator\">Q<sub>ích</sub></span><span class=\"denominator\">A<sub>tp</sub></span></span> ⇒ A<sub>tp</sub> = <span class=\"fraction\"><span class=\"numerator\">Q<sub>ích</sub></span><span class=\"denominator\">H</span></span><br>• <b>Thay số:</b> A<sub>tp</sub> = <span class=\"fraction\"><span class=\"numerator\">630000</span><span class=\"denominator\">0,75</span></span> = 840000 J = 840 kJ.","svgGraph":null},{"q":"Nhãn năng lượng hình tam giác hoặc chữ nhật có từ 1 đến 5 ngôi sao dán trên các thiết bị gia dụng (tủ lạnh, máy giặt, điều hoà) có ý nghĩa gì đối với người tiêu dùng?","opts":["Càng nhiều sao thì thiết bị càng có hiệu suất sử dụng năng lượng cao và càng tiết kiệm điện.","Số sao biểu thị độ bền cơ học của vỏ máy.","Số sao cho biết số năm bảo hành chính hãng của nhà sản xuất.","Càng nhiều sao thì giá bán của sản phẩm càng rẻ."],"ans":0,"exp":"• Cấp sao trên nhãn năng lượng của Bộ Công Thương phản ánh hiệu suất năng lượng: 5 sao là mức tối ưu tiết kiệm điện nhất.","svgGraph":null},{"q":"Một nhà máy thuỷ điện có lưu lượng nước đổ vào tuabin là Q = 50 m³/s từ độ cao h = 40 m. Khối lượng riêng của nước là 1000 kg/m³. Lấy g = 10 m/s². Hiệu suất toàn phần của nhà máy là H = 85%. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Phần năng lượng hao phí trong quá trình vận hành là 10 MW.","Khối lượng nước đổ qua tuabin trong mỗi giây là 50000 kg.","Công suất trọng trường tiềm năng (công suất toàn phần) của dòng nước là P<sub>tp</sub> = 20 MW.","Công suất phát điện hữu ích của nhà máy thuỷ điện là P<sub>ích</sub> = 17 MW."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> m = ρ·V = 1000 · 50 = 50000 kg/s.<br>• <b>Ý b [Đúng]:</b> P<sub>tp</sub> = m·g·h = 50000 · 10 · 40 = 20000000 W = 20 MW.<br>• <b>Ý c [Đúng]:</b> P<sub>ích</sub> = H · P<sub>tp</sub> = 0,85 · 20 MW = 17 MW.<br>• <b>Ý d [Sai]:</b> Hao phí P<sub>hp</sub> = 20 - 17 = 3 MW (không phải 10 MW).","svgGraph":null},{"q":"Hệ số suy giảm hiệu suất trong động cơ đốt trong truyền thống xuất phát chủ yếu từ giai đoạn nào?","opts":["Khí thải nóng xả ra môi trường mang theo một lượng nhiệt lượng khổng lồ không chuyển thành công cơ học.","Điện trở của các bóng đèn xi-nhan trên xe.","Khối lượng của dầu bôi trơn quá nặng.","Áp suất không khí bên trong lốp xe quá căng."],"ans":0,"exp":"• Khoảng 60% năng lượng nhiệt giải phóng từ nhiên liệu xăng/dầu bị mất qua ống xả khí nóng và hệ thống tản nhiệt làm mát động cơ.","svgGraph":null}],"28":[{"q":"Động lượng p của một vật có khối lượng m đang chuyển động với vận tốc v là đại lượng vectơ được định nghĩa bằng:","opts":["Tích của khối lượng m và vectơ vận tốc v của vật: p = m · v.","Tích của khối lượng m và gia tốc a của vật: p = m · a.","Thương số giữa khối lượng và vận tốc của vật: p = m / v.","Một nửa tích khối lượng và bình phương vận tốc: p = ½ m·v²."],"ans":0,"exp":"• <b>Định nghĩa động lượng:</b> p = m·v. Động lượng là đại lượng vectơ có cùng hướng với vectơ vận tốc của vật. Trong hệ SI, đơn vị của động lượng là kg·m/s (hoặc N·s).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr28\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Moving Sphere with mass m -->\n      <circle cx=\"160\" cy=\"120\" r=\"30\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <text x=\"155\" y=\"125\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">m</text>\n      <!-- Velocity Vector v -->\n      <line x1=\"190\" y1=\"110\" x2=\"310\" y2=\"110\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr28)\"/>\n      <text x=\"235\" y=\"100\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Vận tốc v</text>\n      <!-- Momentum Vector p -->\n      <line x1=\"190\" y1=\"135\" x2=\"350\" y2=\"135\" stroke=\"#fbbf24\" stroke-width=\"4\" marker-end=\"url(#arr28)\"/>\n      <text x=\"230\" y=\"155\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Động lượng p = m · v</text>\n      <text x=\"120\" y=\"45\" fill=\"#f8fafc\" font-size=\"15\" font-weight=\"bold\">Động lượng đặc trưng cho khả năng truyền tương tác</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Vectơ động lượng p luôn cùng hướng với vectơ vận tốc v</text>\n    </svg>"},{"q":"Xung lượng của lực F tác dụng lên vật trong một khoảng thời gian ngắn Δt là F·Δt. Biểu thức liên hệ giữa xung lượng của lực và độ biến thiên động lượng của vật là:","opts":["Δp = p₂ - p₁ = F · Δt.","Δp = F / Δt.","Δp = F · (Δt)².","p = F · Δt² / 2."],"ans":0,"exp":"• <b>Xung lượng của lực:</b> F·Δt = Δp. Độ biến thiên động lượng của một vật trong khoảng thời gian Δt bằng xung lượng của hợp lực tác dụng lên vật trong khoảng thời gian đó.","svgGraph":null},{"q":"Một quả bóng đá khối lượng m = 400 g (0,4 kg) bay với tốc độ v = 20 m/s. Độ lớn động lượng của quả bóng là:","opts":["8,0 kg·m/s.","8000 kg·m/s.","80 kg·m/s.","4,0 kg·m/s."],"ans":0,"exp":"• <b>Công thức tính động lượng:</b> p = m·v = 0,4 · 20 = 8,0 kg·m/s.","svgGraph":null},{"q":"Về các đặc tính của vectơ động lượng p, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu một vật chuyển động tròn đều với tốc độ không đổi thì vectơ động lượng của vật là một hằng số không đổi.","Động lượng là đại lượng vectơ có phương và chiều luôn trùng với phương và chiều của vectơ vận tốc.","Một chiếc xe tải nặng và một chiếc xe đạp chuyển động với cùng vận tốc thì xe tải có động lượng lớn hơn rất nhiều.","Đơn vị của động lượng kg·m/s hoàn toàn tương đương với đơn vị Newton nhân giây (N·s)."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> p = mv với m > 0 nên p cùng hướng v.<br>• <b>Ý b [Đúng]:</b> Khối lượng xe tải m<sub>t</sub>ải >> m<sub>đạp</sub> nên p<sub>t</sub>ải >> p<sub>đạp</sub>.<br>• <b>Ý c [Đúng]:</b> N·s = (kg·m/s²)·s = kg·m/s.<br>• <b>Ý d [Sai]:</b> Chuyển động tròn đều thì hướng của v thay đổi liên tục ⇒ hướng của p thay đổi liên tục nên vectơ động lượng biến thiên (chỉ có độ lớn là không đổi).","svgGraph":null},{"q":"Ghép sự biến đổi động lượng ở Cột A với lực và thời gian tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vận động viên uốn cong đầu gối khi tiếp đất sau cú nhảy cao ➔ Kéo dài thời gian tiếp xúc bóng Δt để truyền xung lượng lớn nhất","Vận động viên uốn cong đầu gối khi tiếp đất sau cú nhảy cao ➔ Kéo dài thời gian hãm dừng Δt để giảm lực cản F tác dụng lên cơ thể","Túi khí ô tô bung ra khi có va chạm mạnh ➔ Kéo dài thời gian tiếp xúc bóng Δt để truyền xung lượng lớn nhất","Thủ môn kéo lùi tay về sau khi bắt quả bóng sút mạnh ➔ Kéo dài thời gian hãm dừng Δt để giảm lực cản F tác dụng lên cơ thể"],"ans":0,"exp":"• <b>1 - D:</b> Gập gối tăng Δt giảm lực phản đất.<br>• <b>2 - B:</b> Túi khí tăng Δt giảm lực cản va đập.<br>• <b>3 - C:</b> Kéo lùi tay tăng Δt đỡ rát tay.<br>• <b>4 - A:</b> Vung hết đà tăng thời gian đẩy bóng đi xa.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Động lượng đặc trưng cho  [ ... ]  của một vật trong tương tác va chạm. Khi hai vật có cùng động lượng va chạm vào một vật cản thì chúng có khả năng truyền  [ ... ]  như nhau. Một viên đạn nhỏ có khối lượng vài gam nhưng bay với vận tốc  [ ... ]  nên có động lượng rất lớn và sức công phá nguy hiểm. Để dừng một vật có động lượng lớn, cần phải tác dụng một  [ ... ]  lớn hoặc tác dụng trong thời gian dài.\"</i>","opts":["mức độ truyền chuyển động — xung lượng","không đổi","khối lượng — thời gian ngắn","xung lượng — mức độ truyền chuyển động"],"ans":0,"exp":"<b>Ý nghĩa động lượng:</b><br>• Đặc trưng khả năng truyền chuyển động.<br>• Cùng p truyền cùng xung lượng.<br>• Đạn nhẹ nhưng v cực cao nên p lớn.<br>• Cần lực cản lớn để dừng vật có p lớn.","svgGraph":null},{"q":"Một quả bóng khối lượng m = 200 g bay theo phương ngang với vận tốc 15 m/s đập vuông góc vào bức tường rồi bật ngược trở lại theo phương cũ với cùng tốc độ 15 m/s. Chọn chiều dương là chiều bật ra. Độ biến thiên động lượng của quả bóng là:","opts":["+6 kg·m/s.","0 kg·m/s.","-6 kg·m/s.","+3 kg·m/s."],"ans":0,"exp":"• <b>Vận tốc ban đầu:</b> v₁ = -15 m/s; vận tốc sau bật: v₂ = +15 m/s.<br>• <b>Độ biến thiên động lượng:</b> Δp = m·(v₂ - v₁) = 0,2 · [15 - (-15)] = 0,2 · 30 = +6 kg·m/s. (Không phải bằng 0 vì hướng vận tốc đã đảo ngược).","svgGraph":null},{"q":"Một lực F = 50 N tác dụng vào một vật đứng yên trong khoảng thời gian Δt = 0,4 s. Động lượng mà vật thu được sau khoảng thời gian này là:","opts":["20 kg·m/s.","125 kg·m/s.","12,5 kg·m/s.","200 kg·m/s."],"ans":0,"exp":"• <b>Theo định lí xung lượng:</b> p₂ - 0 = F·Δt = 50 · 0,4 = 20 N·s = 20 kg·m/s.","svgGraph":null},{"q":"Một xe ô tô khối lượng m₁ = 1000 kg chạy với vận tốc v₁ = 54 km/h (15 m/s) và một xe tải khối lượng m₂ = 3000 kg chạy với vận tốc v₂ = 36 km/h (10 m/s). Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Xe tải có động năng lớn gấp đôi động năng của xe ô tô con.","Động lượng của xe ô tô con là p₁ = 15000 kg·m/s.","Động lượng của xe tải là p₂ = 30000 kg·m/s lớn gấp đôi động lượng của xe ô tô con.","Động năng của xe ô tô con là W<sub>đ</sub>1 = 112500 J."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> p₁ = 1000 · 15 = 15000 kg·m/s.<br>• <b>Ý b [Đúng]:</b> p₂ = 3000 · 10 = 30000 kg·m/s = 2·p₁.<br>• <b>Ý c [Đúng]:</b> W<sub>đ</sub>1 = 1/2 · 1000 · 15² = 112500 J.<br>• <b>Ý d [Sai]:</b> W<sub>đ</sub>2 = 1/2 · 3000 · 10² = 150000 J (tỉ số 150000 / 112500 = 1,33 lần, không phải gấp đôi).","svgGraph":null},{"q":"Hệ thức liên hệ giữa động năng W<sub>đ</sub> và độ lớn động lượng p của một vật khối lượng m là:","opts":["W<sub>đ</sub> = p² / (2m).","W<sub>đ</sub> = 2m / p².","W<sub>đ</sub> = 2m · p².","W<sub>đ</sub> = p / (2m)."],"ans":0,"exp":"• <b>Biến đổi:</b> W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mv² = <span class=\"fraction\"><span class=\"numerator\">(mv)²</span><span class=\"denominator\">2m</span></span> = <span class=\"fraction\"><span class=\"numerator\">p²</span><span class=\"denominator\">2m</span></span>.","svgGraph":null}],"29":[{"q":"Một hệ được gọi là hệ kín (hệ cô lập) về phương diện cơ học khi:","opts":["Không có ngoại lực tác dụng lên các vật trong hệ, hoặc các ngoại lực triệt tiêu lẫn nhau.","Các vật trong hệ đứng yên hoàn toàn không có tương tác nội lực.","Khối lượng của tất cả các vật trong hệ bằng nhau.","Hệ chỉ gồm duy nhất một vật thể đơn lẻ trong vũ trụ."],"ans":0,"exp":"• <b>Định nghĩa hệ kín:</b> Hệ kín là hệ mà các vật trong hệ chỉ tương tác với nhau (nội lực) mà không chịu tác dụng của các lực bên ngoài (ngoại lực), hoặc nếu có ngoại lực thì tổng các ngoại lực phải triệt tiêu: ∑F<sub>ngo</sub>ài = 0.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr29\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Before Collision -->\n      <g transform=\"translate(30, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" fill=\"#1e293b\" rx=\"6\"/>\n        <text x=\"35\" y=\"25\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Trước va chạm</text>\n        <circle cx=\"50\" cy=\"70\" r=\"18\" fill=\"#ef4444\"/>\n        <text x=\"44\" y=\"75\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">m₁</text>\n        <line x1=\"68\" y1=\"70\" x2=\"110\" y2=\"70\" stroke=\"#ef4444\" stroke-width=\"2.5\" marker-end=\"url(#arr29)\"/>\n        <text x=\"80\" y=\"62\" fill=\"#fca5a5\" font-size=\"10\">v₁</text>\n        <circle cx=\"150\" cy=\"70\" r=\"18\" fill=\"#3b82f6\"/>\n        <text x=\"144\" y=\"75\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">m₂</text>\n        <line x1=\"168\" y1=\"70\" x2=\"195\" y2=\"70\" stroke=\"#3b82f6\" stroke-width=\"2\" marker-end=\"url(#arr29)\"/>\n        <text x=\"175\" y=\"62\" fill=\"#93c5fd\" font-size=\"10\">v₂</text>\n      </g>\n      <!-- After Collision (Stick together: va chạm mềm) -->\n      <g transform=\"translate(260, 40)\">\n        <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" fill=\"#1e293b\" rx=\"6\"/>\n        <text x=\"35\" y=\"25\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Sau va chạm mềm (dính liền)</text>\n        <circle cx=\"85\" cy=\"70\" r=\"18\" fill=\"#ef4444\"/>\n        <circle cx=\"115\" cy=\"70\" r=\"18\" fill=\"#3b82f6\"/>\n        <text x=\"75\" y=\"105\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">m₁ + m₂</text>\n        <line x1=\"133\" y1=\"70\" x2=\"185\" y2=\"70\" stroke=\"#34d399\" stroke-width=\"3\" marker-end=\"url(#arr29)\"/>\n        <text x=\"150\" y=\"62\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">V</text>\n      </g>\n      <text x=\"140\" y=\"210\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">p<tspan baseline-shift=\"sub\" font-size=\"70%\">trước</tspan> = p<tspan baseline-shift=\"sub\" font-size=\"70%\">sau</tspan>  ⇔  m₁v₁ + m₂v₂ = (m₁ + m₂)V</text>\n    </svg>"},{"q":"Định luật bảo toàn động lượng phát biểu rằng:","opts":["Tổng vectơ động lượng của một hệ kín là một đại lượng không đổi (bảo toàn) theo thời gian.","Động lượng của từng vật riêng rẽ trong hệ không bao giờ được phép thay đổi.","Tổng động năng của hệ kín luôn luôn bằng tổng động lượng của hệ đó.","Động lượng của hệ chỉ bảo toàn khi mọi va chạm là hoàn toàn đàn hồi."],"ans":0,"exp":"• <b>Định luật bảo toàn động lượng:</b> Trong một hệ kín, tổng vectơ động lượng của hệ bảo toàn: p = p₁ + p₂ + ... = const.","svgGraph":null},{"q":"Một xe goòng khối lượng m₁ = 200 kg đang chạy với vận tốc v₁ = 3 m/s trên đường ray nằm ngang trơn nhẵn thì va chạm mềm với một xe thứ hai có khối lượng m₂ = 100 kg đang đứng yên trên ray. Sau va chạm hai xe dính liền vào nhau. Vận tốc của hai xe ngay sau va chạm là:","opts":["2 m/s.","1,5 m/s.","1 m/s.","3 m/s."],"ans":0,"exp":"• <b>Bảo toàn động lượng cho va chạm mềm:</b><br>m₁·v₁ + 0 = (m₁ + m₂)·V ⇒ V = <span class=\"fraction\"><span class=\"numerator\">m₁·v₁</span><span class=\"denominator\">m₁ + m₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">200 · 3</span><span class=\"denominator\">200 + 100</span></span> = <span class=\"fraction\"><span class=\"numerator\">600</span><span class=\"denominator\">300</span></span> = 2 m/s.","svgGraph":null},{"q":"Về các loại va chạm và nguyên lí bảo toàn trong va chạm cơ học, xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi bắn một viên đạn bằng súng, định luật bảo toàn động lượng không nghiệm đúng vì có lực nổ của thuốc súng rất lớn.","Định luật bảo toàn động lượng nghiệm đúng cho cả va chạm đàn hồi và va chạm mềm.","Trong va chạm mềm (hai vật dính vào nhau sau va chạm), cơ năng của hệ không được bảo toàn mà một phần biến thành nhiệt năng biến dạng.","Trong va chạm đàn hồi hoàn toàn, cả động lượng và động năng của hệ đều được bảo toàn nguyên vẹn."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Va chạm rất nhanh coi là hệ kín nên động lượng luôn bảo toàn.<br>• <b>Ý b [Đúng]:</b> Va chạm mềm mất cơ năng thành nhiệt biến dạng.<br>• <b>Ý c [Đúng]:</b> Va chạm đàn hồi bảo toàn cả p và W<sub>đ</sub>.<br>• <b>Ý d [Sai]:</b> Lực thuốc súng là nội lực giữa đạn và súng, trong thời gian nổ cực ngắn ngoại lực (trọng lực, ma sát) không đáng kể nên hệ súng - đạn là hệ kín, động lượng bảo toàn.","svgGraph":null},{"q":"Ghép loại tương tác ở Cột A với biểu thức bảo toàn động lượng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Va chạm mềm hai vật dính liền nhau ➔ M·V + m·v = 0 ⇒ V = -(m/M)·v","Va chạm mềm hai vật dính liền nhau ➔ m₁v₁ + m₂v₂ = (m₁ + m₂)·V","Hiện tượng súng giật lùi khi bắn đạn ➔ M·V + m·v = 0 ⇒ V = -(m/M)·v","Tên lửa phụt khí phản lực ➔ m₁v₁ + m₂v₂ = (m₁ + m₂)·V"],"ans":0,"exp":"• <b>1 - B:</b> Va chạm mềm: m₁v₁ + m₂v₂ = (m₁+m₂)V.<br>• <b>2 - A:</b> Súng giật: MV + mv = 0.<br>• <b>3 - D:</b> Phản lực tên lửa: M·ΔV = -m<sub>kh</sub>í·v<sub>kh</sub>í.<br>• <b>4 - C:</b> 2 bi bằng nhau va chạm đàn hồi hoán đổi vận tốc.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Tên lửa vũ trụ hoạt động theo nguyên tắc chuyển động bằng  [ ... ] . Để tăng tốc độ của tàu vũ trụ lên đến vận tốc vũ trụ cấp 1 (khoảng  [ ... ] ), người ta sử dụng tên lửa  [ ... ] . Sau khi mỗi tầng đốt hết nhiên liệu, tầng đó sẽ tự động  [ ... ]  để giảm khối lượng cho các tầng tiếp theo tăng tốc hiệu quả hơn.\"</i>","opts":["phản lực — 7,9 km/s","không đổi","quán tính — 11,2 km/s","7,9 km/s — phản lực"],"ans":0,"exp":"<b>Tên lửa nhiều tầng:</b><br>• Chuyển động bằng phản lực.<br>• Vận tốc vũ trụ cấp 1: v₁ ≈ 7,9 km/s.<br>• Cấu tạo nhiều tầng ghép nối tiếp.<br>• Tách bỏ vỏ tầng rỗng để giảm m tăng tốc.","svgGraph":null},{"q":"Một phi hành gia có khối lượng cả người và đồ bảo hộ là m₁ = 80 kg đang lơ lửng đứng yên ngoài không gian thì ném một bình oxy rỗng khối lượng m₂ = 2 kg ra xa với vận tốc v₂ = 10 m/s. Vận tốc giật lùi của phi hành gia theo hướng ngược lại là:","opts":["-0,25 m/s.","-0,50 m/s.","-1,00 m/s.","-2,50 m/s."],"ans":0,"exp":"• <b>Bảo toàn động lượng:</b> m₁·V + m₂·v₂ = 0 ⇒ V = -<span class=\"fraction\"><span class=\"numerator\">m₂·v₂</span><span class=\"denominator\">m₁</span></span> = -<span class=\"fraction\"><span class=\"numerator\">2 · 10</span><span class=\"denominator\">80</span></span> = -<span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">80</span></span> = -0,25 m/s.","svgGraph":null},{"q":"Hai viên bi cùng khối lượng m chuyển động ngược chiều nhau với cùng tốc độ v trên một rãnh thẳng nhẵn không ma sát. Khi va chạm mềm dính vào nhau, vận tốc của hai viên bi sau va chạm là:","opts":["0 m/s (hai viên bi đứng yên hoàn toàn).","v.","2v.","v/2."],"ans":0,"exp":"• Chọn chiều dương: v₁ = +v; v₂ = -v.<br>• Tổng động lượng trước va chạm: p = m·(+v) + m·(-v) = 0.<br>• Sau va chạm dính liền: (m + m)·V = 0 ⇒ V = 0.","svgGraph":null},{"q":"Một quả lựu đạn đang bay theo phương ngang với vận tốc v₀ = 10 m/s ở độ cao h thì nổ thành hai mảnh có khối lượng bằng nhau m₁ = m₂. Ngay sau khi nổ, mảnh 1 bay thẳng đứng xuống dưới với vận tốc v₁ = 10√3 m/s. Xét tính Đúng / Sai của các khẳng định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Trong quá trình lựu đạn nổ, nội lực nổ của thuốc nổ lớn hơn rất nhiều so với ngoại lực (trọng lực) nên động lượng của hệ được bảo toàn.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Nổ là tương tác cực nhanh, nội lực áp đảo, bảo toàn p.<br>• <b>Ý b [Đúng]:</b> p₀ = M·v₀ = 2m₁·v₀ nằm ngang.<br>• <b>Ý c, d [Đúng]:</b> p₀ nằm ngang, p₁ thẳng đứng xuống dưới ⇒ tam giác vuông động lượng: p₂² = p₀² + p₁² ⇒ (m₁v₂)² = (2m₁v₀)² + (m₁v₁)² ⇒ v₂ = √[(2·10)² + (10√3)²] = √(400 + 300) = √700 = 10√7... Khoan, p₀ = Mv₀ = 2m₁·10 = 20m₁; p₁ = m₁·10√3 ⇒ p₂ = m₁·√(20² + 300) = m₁√700; góc tanα = p₁/p₀ = 10√3 / 20 = √3/2.","svgGraph":null},{"q":"Định luật bảo toàn động lượng gắn liền với tính chất đối xứng cơ bản nào của không gian trong vật lí hiện đại (Định lí Noether)?","opts":["Tính đồng nhất của không gian (không gian là đồng tính tại mọi vị trí).","Tính đẳng hướng của không gian (mọi hướng đều như nhau).","Tính đồng nhất của dòng thời gian.","Sự cong vênh của không thời gian bốn chiều."],"ans":0,"exp":"• Theo định lí Noether trong vật lí lí thuyết: Định luật bảo toàn động lượng là hệ quả trực tiếp từ tính đồng tính (đối xứng tịnh tiến) của không gian.","svgGraph":null}],"30":[{"q":"Trong bài thực hành đo động lượng của hai xe trước và sau va chạm, thiết bị đệm khí (Air track) được sử dụng nhằm mục đích chính là:","opts":["Triệt tiêu tối đa lực ma sát giữa xe và đường ray để hệ hai xe được coi là hệ kín lý tưởng.","Làm tăng khối lượng của xe khi chuyển động.","Làm cho hai xe tự động dính vào nhau sau va chạm.","Đo trực tiếp vận tốc của xe mà không cần cổng quang điện."],"ans":0,"exp":"• Đệm khí tạo lớp màng không khí nâng xe nổi lơ lửng, triệt tiêu ma sát để điều kiện hệ kín (∑F<sub>ngo</sub>ài = 0) của định luật bảo toàn động lượng được nghiệm đúng chính xác.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Air Track Rail -->\n      <rect x=\"50\" y=\"140\" width=\"400\" height=\"25\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"4\"/>\n      <!-- Air holes on track -->\n      <circle cx=\"100\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"150\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"200\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"250\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"300\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"350\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <circle cx=\"400\" cy=\"148\" r=\"2\" fill=\"#38bdf8\"/>\n      <!-- Glider A -->\n      <rect x=\"110\" y=\"105\" width=\"55\" height=\"30\" fill=\"#ef4444\" rx=\"3\"/>\n      <rect x=\"133\" y=\"80\" width=\"8\" height=\"25\" fill=\"#f8fafc\"/>\n      <text x=\"125\" y=\"125\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">Xe A</text>\n      <!-- Glider B -->\n      <rect x=\"260\" y=\"105\" width=\"55\" height=\"30\" fill=\"#3b82f6\" rx=\"3\"/>\n      <rect x=\"283\" y=\"80\" width=\"8\" height=\"25\" fill=\"#f8fafc\"/>\n      <text x=\"275\" y=\"125\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"bold\">Xe B</text>\n      <!-- Photogates -->\n      <rect x=\"80\" y=\"70\" width=\"15\" height=\"50\" fill=\"#0284c7\" opacity=\"0.6\"/>\n      <rect x=\"350\" y=\"70\" width=\"15\" height=\"50\" fill=\"#0284c7\" opacity=\"0.6\"/>\n      <text x=\"65\" y=\"60\" fill=\"#38bdf8\" font-size=\"11\">Cổng quang 1</text>\n      <text x=\"335\" y=\"60\" fill=\"#38bdf8\" font-size=\"11\">Cổng quang 2</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Máng đệm khí đo động lượng trước và sau va chạm</text>\n    </svg>"},{"q":"Vận tốc v của mỗi xe khi đi qua cổng quang điện trong thí nghiệm được tính từ công thức nào (với d là bề rộng của tấm chắn sáng và Δt là thời gian chắn sáng)?","opts":["v = d / Δt.","v = d · Δt.","v = Δt / d.","v = 1/2 · d / Δt."],"ans":0,"exp":"• <b>Công thức vận tốc tức thời:</b> v = <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">Δt</span></span>. Do bề rộng tấm chắn sáng d rất nhỏ nên vận tốc của xe khi đi qua cổng quang điện được coi xấp xỉ bằng vận tốc tức thời tại vị trí cổng.","svgGraph":null},{"q":"Để tạo ra va chạm mềm (dính liền vào nhau sau va chạm) giữa hai xe trong bài thực hành, người ta gắn vào đầu tiếp xúc của hai xe chi tiết nào?","opts":["Miếng dán dính nhám (hoặc đầu kim ghim cắm vào miếng xốp mềm).","Vòng đệm lò xo thép có độ đàn hồi cực cao.","Hai nam châm vĩnh cửu quay hai cực cùng dấu vào nhau.","Một lưỡi dao sắc và một khối gỗ cứng."],"ans":0,"exp":"• Miếng dán nhám (Velcro) hoặc kim cắm xốp giữ hai xe dính chặt vào nhau ngay sau khi chạm để tạo thành va chạm mềm hoàn toàn.","svgGraph":null},{"q":"Trong quá trình chuẩn bị và tiến hành thí nghiệm đo động lượng trên máng đệm khí, xét tính Đúng / Sai của các thao tác sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Chỉ cần đo 1 lần duy nhất là có thể kết luận chắc chắn định luật bảo toàn động lượng hoàn toàn chính xác.","Cần căn chỉnh máng đệm khí thật thăng bằng nằm ngang bằng bọt thuỷ hoặc quan sát xe đứng yên khi mở máy bơm khí.","Khối lượng của các xe (kể cả tấm chắn sáng và phụ kiện gắn thêm) phải được cân chính xác bằng cân điện tử trước khi làm thí nghiệm.","Bề rộng tấm chắn sáng d cần được đo chính xác bằng thước kẹp milimét."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Máng phải thăng bằng ngang để trọng lực không tạo gia tốc dọc ray.<br>• <b>Ý b [Đúng]:</b> Cân khối lượng cả xe và phụ kiện.<br>• <b>Ý c [Sai]:</b> Cần lặp lại nhiều lần đo để lấy giá trị trung bình và phân tích sai số.<br>• <b>Ý d [Đúng]:</b> Bề rộng d đo bằng thước kẹp có độ chính xác 0,1 mm.","svgGraph":null},{"q":"Ghép loại va chạm trong bài thực hành ở Cột A với cách bố trí đầu tiếp xúc ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Va chạm đàn hồi ➔ Đầu xe gắn miếng dán nhám gai (Velcro)","Va chạm đàn hồi ➔ Đầu xe gắn vòng cung lò xo đàn hồi hoặc nam châm đẩy nhau","Va chạm mềm ➔ Đầu xe gắn miếng dán nhám gai (Velcro)","Đo khối lượng xe ➔ Đầu xe gắn vòng cung lò xo đàn hồi hoặc nam châm đẩy nhau"],"ans":0,"exp":"• <b>1 - B:</b> Đàn hồi: lò xo/nam châm đẩy.<br>• <b>2 - A:</b> Va chạm mềm: miếng dán nhám.<br>• <b>3 - D:</b> Cân điện tử đo m.<br>• <b>4 - C:</b> Cổng quang đo thời gian Δt.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Từ số liệu khối lượng và vận tốc đo được, ta tính tổng động lượng của hệ trước va chạm: p =  [ ... ] . Sau đó tính tổng động lượng của hệ sau va chạm: p' =  [ ... ] . So sánh hai giá trị p và p', sai số tỉ đối được tính theo công thức  [ ... ] . Nếu sai số này nhỏ (dưới 5%), ta có thể khẳng định định luật bảo toàn động lượng được  [ ... ]  trong thực nghiệm.\"</i>","opts":["m₁v₁ + m₂v₂ — m₁v₁' + m₂v₂'","không đổi","m₁v₁ - m₂v₂ — bác bỏ hoàn toàn","m₁v₁' + m₂v₂' — m₁v₁ + m₂v₂"],"ans":0,"exp":"<b>Xử lí số liệu thực hành động lượng:</b><br>• p = m₁v₁ + m₂v₂.<br>• p' = m₁v₁' + m₂v₂'.<br>• δp = |p - p'|/p · 100%.<br>• Sai số nhỏ kết luận định luật nghiệm đúng.","svgGraph":null},{"q":"Trong một lần thí nghiệm va chạm mềm, đo được: tổng động lượng trước va chạm là p = 0,425 kg·m/s và tổng động lượng sau va chạm là p' = 0,412 kg·m/s. Sai số tỉ đối của phép đo động lượng này xấp xỉ bằng:","opts":["3,06%.","1,30%.","0,013%.","6,12%."],"ans":0,"exp":"• <b>Độ lệch tuyệt đối:</b> Δp = |0,425 - 0,412| = 0,013 kg·m/s.<br>• <b>Sai số tỉ đối:</b> δp = <span class=\"fraction\"><span class=\"numerator\">0,013</span><span class=\"denominator\">0,425</span></span> · 100% ≈ 3,06%.","svgGraph":null},{"q":"Nguyên nhân chủ yếu khiến tổng động lượng sau va chạm thực tế thường hơi nhỏ hơn một chút so với tổng động lượng trước va chạm trong phòng thí nghiệm là:","opts":["Vẫn còn một lực ma sát nhỏ còn sót lại giữa xe và ray cùng với sức cản không khí trong quá trình di chuyển.","Khối lượng của hai xe bị bào mòn sau cú va chạm.","Đồng hồ hiện số bị giảm tần số quét điện tử.","Lực hút của Mặt Trăng làm giảm động lượng của hệ."],"ans":0,"exp":"• Dù dùng đệm khí, ma sát nhớt của không khí và ma sát nhỏ của luồng khí xả vẫn tác dụng công cản làm tốc độ xe sau va chạm suy giảm nhẹ, dẫn đến p' hơi nhỏ hơn p.","svgGraph":null},{"q":"Trong một thí nghiệm va chạm đàn hồi giữa xe A (m<sub>A</sub> = 0,2 kg) chuyển động với vận tốc v<sub>A</sub> = 0,5 m/s đập vào xe B (m<sub>B</sub> = 0,2 kg) đang đứng yên. Sau va chạm, xe A dừng lại hoàn toàn (v<sub>A</sub>' = 0) và xe B chuyển động tới trước. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tổng động năng của hệ sau va chạm bị giảm đi một nửa so với trước va chạm.","Động lượng của xe A trước va chạm là p<sub>A</sub> = 0,1 kg·m/s.","Theo định luật bảo toàn động lượng lí thuyết, vận tốc của xe B sau va chạm là v<sub>B</sub>' = 0,5 m/s.","Hiện tượng xe A dừng lại truyền toàn bộ vận tốc cho xe B chứng tỏ đây là va chạm đàn hồi hoàn toàn của hai vật cùng khối lượng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> p<sub>A</sub> = 0,2 · 0,5 = 0,1 kg·m/s.<br>• <b>Ý b [Đúng]:</b> p<sub>B</sub>' = p<sub>A</sub> ⇒ 0,2 · v<sub>B</sub>' = 0,1 ⇒ v<sub>B</sub>' = 0,5 m/s.<br>• <b>Ý c [Đúng]:</b> Hai vật cùng m va chạm đàn hồi hoán đổi vận tốc hoàn toàn.<br>• <b>Ý d [Sai]:</b> Va chạm đàn hồi động năng bảo toàn nguyên vẹn: W<sub>đ</sub>' = 1/2 · 0,2 · 0,5² = 0,025 J = W<sub>đ</sub> ban đầu.","svgGraph":null},{"q":"Đồ chơi con lắc Newton (gồm 5 viên bi thép treo sát nhau) minh hoạ trực quan định luật vật lí nào khi ta kéo một viên bi ở đầu ra rồi buông tay?","opts":["Đồng thời cả định luật bảo toàn động lượng và định luật bảo toàn động năng trong va chạm đàn hồi.","Chỉ minh hoạ định luật phản xạ ánh sáng.","Hiện tượng giao thoa sóng cơ học trên dây treo.","Định luật cảm ứng điện từ Faraday."],"ans":0,"exp":"• Con lắc Newton là mô hình va chạm đàn hồi liên tiếp giữa các viên bi thép cùng khối lượng, bảo toàn đồng thời cả động lượng và cơ năng (kéo 1 viên bi thì chỉ có đúng 1 viên bi ở đầu kia bật ra với cùng vận tốc).","svgGraph":null}],"31":[{"q":"Chuyển động tròn đều là chuyển động có quỹ đạo tròn và có:","opts":["Tốc độ không đổi theo thời gian.","Vectơ vận tốc không đổi cả về độ lớn lẫn hướng.","Gia tốc luôn bằng 0.","Vectơ vận tốc luôn hướng về tâm quỹ đạo."],"ans":0,"exp":"• <b>Chuyển động tròn đều:</b> Quỹ đạo là đường tròn và tốc độ (độ lớn vận tốc) không đổi theo thời gian.<br>• <i>Lưu ý:</i> Vectơ vận tốc có hướng luôn tiếp tuyến với quỹ đạo nên phương chiều liên tục thay đổi, do đó chuyển động tròn đều luôn có gia tốc (gia tốc hướng tâm), vectơ vận tốc không hề không đổi.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr31\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circle trajectory -->\n      <circle cx=\"250\" cy=\"120\" r=\"80\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n      <!-- Center O -->\n      <circle cx=\"250\" cy=\"120\" r=\"4\" fill=\"#f8fafc\"/>\n      <text x=\"245\" y=\"110\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">O</text>\n      <!-- Radius R -->\n      <line x1=\"250\" y1=\"120\" x2=\"330\" y2=\"120\" stroke=\"#f8fafc\" stroke-width=\"1.5\"/>\n      <text x=\"285\" y=\"115\" fill=\"#f8fafc\" font-size=\"13\" font-family=\"sans-serif\">r</text>\n      <!-- Point M -->\n      <circle cx=\"330\" cy=\"120\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"340\" y=\"125\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"14\" font-family=\"sans-serif\">M</text>\n      <!-- Tangent velocity v -->\n      <line x1=\"330\" y1=\"120\" x2=\"330\" y2=\"40\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr31)\"/>\n      <text x=\"338\" y=\"55\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"14\" font-family=\"sans-serif\">v (tiếp tuyến)</text>\n    </svg>"},{"q":"Đơn vị đo của tốc độ góc (kí hiệu ω) trong hệ đơn vị đo lường quốc tế SI là:","opts":["Radian trên giây (rad/s).","Vòng trên phút (rpm).","Mét trên giây (m/s).","Độ trên giây (°/s)."],"ans":0,"exp":"• <b>Tốc độ góc:</b> ω = <span class=\"fraction\"><span class=\"numerator\">Δθ</span><span class=\"denominator\">Δt</span></span>. Trong hệ SI, góc quay Δθ đo bằng radian (rad), thời gian Δt đo bằng giây (s), do đó đơn vị của ω là rad/s.","svgGraph":null},{"q":"Mối liên hệ giữa tốc độ dài v, tốc độ góc ω và bán kính quỹ đạo r của chuyển động tròn đều là:","opts":["v = ω · r.","v = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">r</span></span>.","v = <span class=\"fraction\"><span class=\"numerator\">r</span><span class=\"denominator\">ω</span></span>.","v = ω² · r."],"ans":0,"exp":"• <b>Mối liên hệ:</b> Quãng đường s = r · θ ⇒ Vận tốc dài v = <span class=\"fraction\"><span class=\"numerator\">Δs</span><span class=\"denominator\">Δt</span></span> = r · <span class=\"fraction\"><span class=\"numerator\">Δθ</span><span class=\"denominator\">Δt</span></span> = ω · r.","svgGraph":null},{"q":"Kim phút của một chiếc đồng hồ treo tường có chiều dài 10 cm. Tốc độ góc của kim phút bằng:","opts":["≈ 1,75 · 10⁻³ rad/s (chính xác là <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">1800</span></span> rad/s).","≈ 1,45 · 10⁻⁴ rad/s (chính xác là <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">21600</span></span> rad/s).","≈ 0,105 rad/s (chính xác là <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">30</span></span> rad/s).","1 rad/s."],"ans":0,"exp":"• <b>Chu kì quay của kim phút:</b> T = 1 giờ = 3600 s.<br>• <b>Tốc độ góc:</b> ω = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">3600</span></span> = <span class=\"fraction\"><span class=\"numerator\">π</span><span class=\"denominator\">1800</span></span> ≈ 1,75 · 10⁻³ rad/s.","svgGraph":null},{"q":"Chu kì T và tần số f của chuyển động tròn đều liên hệ với tốc độ góc ω theo công thức nào sau đây?","opts":["T = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span> và f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span>.","T = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> và f = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span>.","T = 2π · ω và f = 2π / ω.","T = 1 / f = 2π · ω."],"ans":0,"exp":"• Chu kì T là thời gian vật quay hết 1 vòng (góc 2π rad): T = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span>.<br>• Tần số f là số vòng quay trong 1 giây: f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> (đơn vị Hertz - Hz hoặc vòng/s).","svgGraph":null},{"q":"Một chất điểm chuyển động tròn đều trên đường tròn bán kính r = 0,5 m với tần số f = 2 Hz. Tốc độ dài của chất điểm là:","opts":["2π m/s (≈ 6,28 m/s).","π m/s (≈ 3,14 m/s).","4π m/s (≈ 12,57 m/s).","1 m/s."],"ans":0,"exp":"• Tốc độ góc: ω = 2π · f = 2π · 2 = 4π rad/s.<br>• Tốc độ dài: v = ω · r = 4π · 0,5 = 2π m/s ≈ 6,28 m/s.","svgGraph":null},{"q":"Hãy ghép mỗi đại lượng đặc trưng của chuyển động tròn đều ở Cột A với biểu thức hoặc ý nghĩa vật lí tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Tốc độ góc ω ➔ Đặc trưng cho tốc độ quay, tính bằng góc quét chia thời gian: ω = Δθ / Δt","Tốc độ góc ω ➔ Thời gian chất điểm quay hết một vòng tròn: T = 2π / ω","Chu kì T ➔ Đặc trưng cho tốc độ quay, tính bằng góc quét chia thời gian: ω = Δθ / Δt","Tần số f ➔ Thời gian chất điểm quay hết một vòng tròn: T = 2π / ω"],"ans":0,"exp":"• Các công thức nền tảng của động học chuyển động tròn đều: ω = Δθ/Δt; T = 2π/ω; f = 1/T = ω/(2π); v = ω·r.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong chuyển động tròn đều, vectơ vận tốc luôn có phương  [ ... ]  với đường tròn quỹ đạo và có độ lớn không đổi. Tốc độ góc ω là đại lượng đo bằng  [ ... ]  mà bán kính quét được trong một đơn vị thời gian. Chu kì T là thời gian vật chuyển động được  [ ... ] . Mối liên hệ giữa tốc độ dài và tốc độ góc là  [ ... ] .\"</i>","opts":["tiếp tuyến — góc","không đổi","hai vòng — v = ω / r","góc — tiếp tuyến"],"ans":0,"exp":"• Vectơ vận tốc tiếp tuyến quỹ đạo tròn, độ lớn không đổi. Tốc độ góc đo bằng góc quét mỗi giây, chu kì là thời gian đi hết 1 vòng, v = ω·r.","svgGraph":null},{"q":"Một đĩa tròn quay đều quanh trục thẳng đứng đi qua tâm với tốc độ góc không đổi ω = 10 rad/s. Điểm A nằm trên vành đĩa cách tâm r<sub>A</sub> = 20 cm, điểm B nằm trên bán kính cách tâm r<sub>B</sub> = 10 cm. Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Chu kì quay của điểm A nhỏ hơn chu kì quay của điểm B vì điểm A đi quãng đường dài hơn.","Điểm A và điểm B có cùng tốc độ góc ω = 10 rad/s.","Tốc độ dài của điểm A lớn gấp hai lần tốc độ dài của điểm B.","Tần số quay của toàn bộ đĩa tròn xấp xỉ 1,59 Hz."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Mọi điểm trên vật rắn quay đều quanh một trục cố định đều có cùng tốc độ góc ω = 10 rad/s.<br>• <b>Ý b [Đúng]:</b> v = ω·r ⇒ v<sub>A</sub> / v<sub>B</sub> = r<sub>A</sub> / r<sub>B</sub> = 20/10 = 2.<br>• <b>Ý c [Sai]:</b> T = 2π/ω giống nhau với mọi điểm trên đĩa.<br>• <b>Ý d [Đúng]:</b> f = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">2π</span></span> ≈ 1,59 Hz.","svgGraph":null},{"q":"Xét chuyển động quay của kim giờ và kim phút trên mặt một chiếc đồng hồ treo tường hình tròn tiêu chuẩn. Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Kim giờ và kim phút có cùng gia tốc hướng tâm ở đầu kim.","Chu kì quay của kim phút bằng 1 giờ (3600 s), chu kì quay của kim giờ bằng 12 giờ (43200 s).","Tốc độ góc của kim phút lớn gấp 12 lần tốc độ góc của kim giờ.","Nếu chiều dài kim phút gấp 1,5 lần chiều dài kim giờ thì tốc độ dài ở đầu kim phút lớn gấp 18 lần tốc độ dài ở đầu kim giờ."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> T<sub>ph</sub>út = 1 h = 3600 s; T<sub>gi</sub>ờ = 12 h = 43200 s.<br>• <b>Ý b [Đúng]:</b> ω = 2π/T ⇒ ω_phút / ω_giờ = T<sub>gi</sub>ờ / T<sub>ph</sub>út = 12.<br>• <b>Ý c [Đúng]:</b> v = ω·r ⇒ v<sub>ph</sub>út / v<sub>gi</sub>ờ = (ω_phút / ω_giờ) · (r<sub>ph</sub>út / r<sub>gi</sub>ờ) = 12 · 1,5 = 18.<br>• <b>Ý d [Sai]:</b> a<sub>ht</sub> = ω²·r ⇒ a<sub>ht</sub>(phút) / a<sub>ht</sub>(giờ) = 12² · 1,5 = 216 lần (khác nhau hoàn toàn).","svgGraph":null}],"32":[{"q":"Trong chuyển động tròn đều, vectơ gia tốc hướng tâm luôn có đặc điểm nào sau đây?","opts":["Luôn hướng về tâm đường tròn quỹ đạo và có độ lớn a<sub>ht</sub> = v² / r = ω² · r.","Luôn cùng hướng với vectơ vận tốc tiếp tuyến.","Có hướng không đổi trong suốt quá trình chuyển động.","Có độ lớn tỉ lệ nghịch với bình phương tốc độ góc."],"ans":0,"exp":"• Trong chuyển động tròn đều, vận tốc thay đổi về hướng liên tục, gia tốc sinh ra luôn vuông góc với vận tốc và hướng vào tâm quỹ đạo gọi là gia tốc hướng tâm: a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">r</span></span> = ω² · r.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs>\n        <marker id=\"arrV32\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker>\n        <marker id=\"arrA32\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#f43f5e\"/></marker>\n      </defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Circle trajectory -->\n      <circle cx=\"250\" cy=\"120\" r=\"75\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n      <!-- Center O -->\n      <circle cx=\"250\" cy=\"120\" r=\"4\" fill=\"#f8fafc\"/>\n      <text x=\"235\" y=\"125\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">O</text>\n      <!-- Point M -->\n      <circle cx=\"250\" cy=\"45\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"258\" y=\"42\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">M</text>\n      <!-- Tangent velocity v -->\n      <line x1=\"250\" y1=\"45\" x2=\"170\" y2=\"45\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arrV32)\"/>\n      <text x=\"175\" y=\"36\" fill=\"#38bdf8\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">v</text>\n      <!-- Centripetal acceleration a<tspan baseline-shift=\"sub\" font-size=\"70%\">ht</tspan> -->\n      <line x1=\"250\" y1=\"45\" x2=\"250\" y2=\"105\" stroke=\"#f43f5e\" stroke-width=\"2.5\" marker-end=\"url(#arrA32)\"/>\n      <text x=\"256\" y=\"90\" fill=\"#f43f5e\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">a<tspan baseline-shift=\"sub\" font-size=\"70%\">ht</tspan> (hướng tâm)</text>\n    </svg>"},{"q":"Hợp lực của các lực tác dụng lên một vật chuyển động tròn đều giữ vai trò là lực hướng tâm. Biểu thức của lực hướng tâm là:","opts":["F<sub>ht</sub> = m · a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v²</span><span class=\"denominator\">r</span></span> = m · ω² · r.","F<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v</span><span class=\"denominator\">r</span></span>.","F<sub>ht</sub> = m · v² · r.","F<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · ω</span><span class=\"denominator\">r</span></span>."],"ans":0,"exp":"• Theo định luật II Newton: F<sub>ht</sub> = m · a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v²</span><span class=\"denominator\">r</span></span> = m · ω² · r. Lực hướng tâm không phải là một loại lực cơ học mới, mà là tên gọi của hợp lực gây ra gia tốc hướng tâm.","svgGraph":null},{"q":"Khi một chiếc ô tô chuyển động qua một khúc cua tròn trên mặt đường nằm ngang, lực nào đóng vai trò chính cung cấp lực hướng tâm giữ cho xe không bị trượt văng ra ngoài?","opts":["Lực ma sát nghỉ giữa lốp xe và mặt đường.","Trọng lực của xe ô tô.","Phản lực pháp tuyến của mặt đường.","Lực đẩy của động cơ xe."],"ans":0,"exp":"• Trên mặt đường nằm ngang, trọng lực P và phản lực N triệt tiêu nhau theo phương thẳng đứng. Thành phần lực ma sát nghỉ hướng vào tâm đường cong đóng vai trò lực hướng tâm giúp xe vào cua an toàn. Khi đường trơn trượt (ma sát nghỉ cực đại không đủ lớn), xe sẽ bị trượt li tâm ra ngoài khúc cua.","svgGraph":null},{"q":"Một vệ tinh nhân tạo có khối lượng m đang bay trên quỹ đạo tròn quanh Trái Đất. Lực nào đóng vai trò là lực hướng tâm giữ cho vệ tinh chuyển động trên quỹ đạo?","opts":["Lực hấp dẫn giữa Trái Đất và vệ tinh.","Lực đẩy của động cơ phản lực gắn trên vệ tinh.","Lực ma sát của bầu khí quyển loãng.","Lực từ trường của Trái Đất."],"ans":0,"exp":"• Trong không gian vũ trụ, lực hấp dẫn do Trái Đất tác dụng lên vệ tinh đóng vai trò là lực hướng tâm: F<sub>hd</sub> = G · (M·m)/r² = m·v²/r, giữ cho vệ tinh bay đều quanh Trái Đất mà không rơi xuống hay bay mất vào không gian.","svgGraph":null},{"q":"Một hòn đá khối lượng m = 0,2 kg được buộc vào đầu một sợi dây nhẹ không giãn dài r = 0,8 m và quay đều trong mặt phẳng nằm ngang với tốc độ v = 4 m/s. Lực căng của sợi dây (bỏ qua trọng lực tác dụng lên đá) có độ lớn là:","opts":["4,0 N.","2,0 N.","8,0 N.","1,6 N."],"ans":0,"exp":"• Lực căng dây T hướng vào tâm quỹ đạo đóng vai trò là lực hướng tâm:<br>T = F<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">m · v²</span><span class=\"denominator\">r</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,2 · 4²</span><span class=\"denominator\">0,8</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,2 · 16</span><span class=\"denominator\">0,8</span></span> = 4,0 N.","svgGraph":null},{"q":"Tại các đoạn đường cua gấp trên quốc lộ hay đường đua xe tốc độ cao, người ta thường thiết kế mặt đường nghiêng vào phía trong tâm đường cong nhằm mục đích gì?","opts":["Hợp lực của trọng lực và phản lực mặt đường có thành phần hướng vào tâm cung cấp lực hướng tâm, giảm tải sự phụ thuộc vào lực ma sát lốp xe.","Để nước mưa thoát nhanh hơn về phía lề đường.","Tăng lực ma sát trượt giữa lốp xe và mặt đường.","Giúp ô tô tăng tốc độ cực đại khi lên dốc."],"ans":0,"exp":"• Khi mặt đường nghiêng góc α vào trong, phản lực N của mặt đường nghiêng so với phương thẳng đứng. Hợp lực F = P + N có thành phần nằm ngang F<sub>x</sub> = m·g·tan(α) hướng về tâm khúc cua, đóng vai trò lực hướng tâm giúp xe ôm cua tốc độ cao an toàn mà không bị văng li tâm dù đường trơn ướt.","svgGraph":null},{"q":"Hãy ghép mỗi tình huống chuyển động tròn ở Cột A với bản chất của lực đóng vai trò lực hướng tâm ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Xe ô tô ôm cua trên đường bằng ➔ Lực ma sát nghỉ giữa bánh xe và mặt đường","Xe ô tô ôm cua trên đường bằng ➔ Lực hấp dẫn giữa Mặt Trời và Trái Đất","Trái Đất chuyển động quanh Mặt Trời ➔ Lực ma sát nghỉ giữa bánh xe và mặt đường","Hòn đá quay tròn buộc vào đầu sợi dây ➔ Lực hấp dẫn giữa Mặt Trời và Trái Đất"],"ans":0,"exp":"• Lực hướng tâm không phải lực mới mà là hợp lực cơ học trong từng trường hợp cụ thể: ma sát nghỉ, hấp dẫn, lực căng dây, hoặc hợp lực của P và N.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Lực tác dụng vào vật chuyển động tròn đều gây ra  [ ... ]  được gọi là lực hướng tâm. Lực hướng tâm luôn có hướng  [ ... ]  và có độ lớn tỉ lệ thuận với  [ ... ]  của tốc độ dài. Lực hướng tâm không phải là một lực mới trong tự nhiên mà do  [ ... ]  của các lực thực tế tác dụng lên vật đóng vai trò.\"</i>","opts":["gia tốc hướng tâm — về tâm quỹ đạo","không đổi","căn bậc hai — phản lực","về tâm quỹ đạo — gia tốc hướng tâm"],"ans":0,"exp":"• Lực hướng tâm gây ra gia tốc hướng tâm, luôn hướng về tâm, F<sub>ht</sub> = m·v²/r (tỉ lệ với v²), bản chất là hợp lực của các lực cơ học có sẵn.","svgGraph":null},{"q":"Một chiếc ô tô khối lượng m = 1200 kg chuyển động với tốc độ v = 54 km/h (15 m/s) qua một khúc cua có bán kính cong r = 50 m trên mặt đường phẳng nằm ngang. Cho g = 10 m/s². Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực hướng tâm trong trường hợp này do lực ma sát trượt cung cấp.","Gia tốc hướng tâm của ô tô tại khúc cua có độ lớn là 4,5 m/s².","Độ lớn lực hướng tâm cần thiết tác dụng lên ô tô bằng 5400 N.","Hệ số ma sát nghỉ giữa lốp xe và mặt đường tối thiểu phải bằng μ_n = 0,45 để xe không bị trượt li tâm."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">r</span></span> = <span class=\"fraction\"><span class=\"numerator\">15²</span><span class=\"denominator\">50</span></span> = <span class=\"fraction\"><span class=\"numerator\">225</span><span class=\"denominator\">50</span></span> = 4,5 m/s².<br>• <b>Ý b [Đúng]:</b> F<sub>ht</sub> = m·a<sub>ht</sub> = 1200 · 4,5 = 5400 N.<br>• <b>Ý c [Sai]:</b> Lực hướng tâm do lực ma sát <b>nghỉ</b> (không phải ma sát trượt) giữ bánh xe bám đường.<br>• <b>Ý d [Đúng]:</b> F<sub>msn</sub>(max) = μ_n·N = μ_n·m·g ≥ F<sub>ht</sub> ⇒ μ_n ≥ <span class=\"fraction\"><span class=\"numerator\">a<sub>ht</sub></span><span class=\"denominator\">g</span></span> = <span class=\"fraction\"><span class=\"numerator\">4,5</span><span class=\"denominator\">10</span></span> = 0,45.","svgGraph":null},{"q":"Một ô tô có khối lượng m = 1000 kg chuyển động với tốc độ không đổi v = 10 m/s đi qua một cây cầu vồng lên có bán kính cong R = 40 m. Lấy g = 10 m/s². Hãy đánh giá tính Đúng / Sai của các nhận định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Tại điểm cao nhất trên đỉnh cầu, gia tốc hướng tâm của xe có độ lớn bằng 2,5 m/s².\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> a<sub>ht</sub> = <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">R</span></span> = <span class=\"fraction\"><span class=\"numerator\">10²</span><span class=\"denominator\">40</span></span> = 2,5 m/s².<br>• <b>Ý b [Đúng]:</b> P = m · g = 1000 · 10 = 10 000 N.<br>• <b>Ý c [Đúng]:</b> Hợp lực P - N = m · a<sub>ht</sub> ⇒ N = P - m · a<sub>ht</sub> = 10 000 - 1000 · 2,5 = 7500 N.<br>• <b>Ý d [Đúng]:</b> Xe rời cầu khi N = 0 ⇒ v<sub>bay</sub> = √(g · R) = √(10 · 40) = 20 m/s.","svgGraph":null}],"33":[{"q":"Biến dạng nào sau đây của vật rắn được gọi là biến dạng đàn hồi?","opts":["Biến dạng mà vật lấy lại hoàn toàn hình dạng và kích thước ban đầu khi lực tác dụng thôi tác dụng.","Biến dạng mà vật bị gãy vụn ngay khi chịu lực lớn.","Biến dạng mà hình dạng của vật bị thay đổi vĩnh viễn không thể hồi phục lại.","Biến dạng chỉ xảy ra khi nung nóng vật rắn đến nhiệt độ nóng chảy."],"ans":0,"exp":"• <b>Biến dạng đàn hồi:</b> Biến dạng mà vật rắn có thể tự khôi phục lại hoàn toàn hình dạng và kích thước ban đầu khi thôi tác dụng ngoại lực (trong giới hạn đàn hồi). Nếu vượt quá giới hạn đàn hồi, vật sẽ bị biến dạng dư (dẻo) hoặc đứt gãy.","svgGraph":null},{"q":"Nội dung của định luật Hooke (Húc) đối với lò xo biến dạng kéo hoặc nén trong giới hạn đàn hồi là:","opts":["Trong giới hạn đàn hồi, độ lớn của lực đàn hồi tỉ lệ thuận với độ biến dạng của lò xo: F<sub>đh</sub> = k · |Δl|.","Lực đàn hồi tỉ lệ nghịch với độ biến dạng của lò xo.","Lực đàn hồi luôn tỉ lệ thuận với bình phương độ dãn của lò xo.","Độ cứng của lò xo tỉ lệ nghịch với chiều dài tự nhiên của nó và không phụ thuộc vật liệu."],"ans":0,"exp":"• <b>Định luật Hooke:</b> F<sub>đh</sub> = k · |Δl|, trong đó k là độ cứng (hay hệ số đàn hồi) của lò xo (đo bằng N/m), |Δl| = |l - l₀| là độ biến dạng (đo bằng mét - m).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr33\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes -->\n      <line x1=\"80\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr33)\"/>\n      <line x1=\"80\" y1=\"200\" x2=\"80\" y2=\"30\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr33)\"/>\n      <text x=\"425\" y=\"225\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">Δl (m)</text>\n      <text x=\"50\" y=\"45\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">F<tspan baseline-shift=\"sub\" font-size=\"70%\">đh</tspan> (N)</text>\n      <!-- Linear Hooke law region -->\n      <line x1=\"80\" y1=\"200\" x2=\"320\" y2=\"70\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <circle cx=\"320\" cy=\"70\" r=\"4\" fill=\"#34d399\"/>\n      <text x=\"325\" y=\"65\" fill=\"#34d399\" font-size=\"12\" font-family=\"sans-serif\">Giới hạn đàn hồi</text>\n      <!-- Beyond elastic limit (plastic) -->\n      <path d=\"M320,70 Q370,60 410,110\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2\" stroke-dasharray=\"3 3\"/>\n      <text x=\"375\" y=\"130\" fill=\"#f43f5e\" font-size=\"11\" font-family=\"sans-serif\">Biến dạng dẻo</text>\n    </svg>"},{"q":"Một lò xo nhẹ có chiều dài tự nhiên l₀ = 20 cm và độ cứng k = 100 N/m. Khi treo vào đầu dưới lò xo một quả cân có khối lượng m = 200 g (lấy g = 10 m/s²) thì chiều dài của lò xo khi cân bằng là:","opts":["22 cm (l = 0,22 m).","25 cm.","18 cm.","20,2 cm."],"ans":0,"exp":"• Khi vật cân bằng: P = F<sub>đh</sub> ⇒ m · g = k · Δl.<br>• Độ dãn của lò xo: Δl = <span class=\"fraction\"><span class=\"numerator\">m · g</span><span class=\"denominator\">k</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,2 · 10</span><span class=\"denominator\">100</span></span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">100</span></span> = 0,02 m = 2 cm.<br>• Chiều dài lò xo: l = l₀ + Δl = 20 + 2 = 22 cm.","svgGraph":null},{"q":"Độ cứng (hệ số đàn hồi) k của một thanh kim loại hình trụ đồng chất tỉ lệ thuận với đại lượng nào và tỉ lệ nghịch với đại lượng nào?","opts":["Tỉ lệ thuận với tiết diện ngang S và tỉ lệ nghịch với chiều dài tự nhiên l₀ của thanh.","Tỉ lệ thuận với chiều dài tự nhiên l₀ và tỉ lệ nghịch với tiết diện S.","Tỉ lệ thuận với khối lượng của thanh và độc lập với kích thước hình học.","Không phụ thuộc vào hình dạng kích thước mà chỉ phụ thuộc vào nhiệt độ môi trường."],"ans":0,"exp":"• <b>Công thức độ cứng thanh vật rắn:</b> k = E · <span class=\"fraction\"><span class=\"numerator\">S</span><span class=\"denominator\">l₀</span></span>, trong đó E là suất đàn hồi (suất Young) phụ thuộc bản chất vật liệu, S là tiết diện ngang, l₀ là chiều dài ban đầu. Thanh càng to (S lớn) và càng ngắn (l₀ nhỏ) thì càng cứng.","svgGraph":null},{"q":"Khi ta dùng tay uốn cong một chiếc thước nhựa dẻo, lớp vật liệu ở phía mặt lồi của thước chịu loại biến dạng nào, và lớp vật liệu ở phía mặt lõm chịu loại biến dạng nào?","opts":["Mặt lồi chịu biến dạng kéo, mặt lõm chịu biến dạng nén.","Mặt lồi chịu biến dạng nén, mặt lõm chịu biến dạng kéo.","Cả hai mặt đều chỉ chịu biến dạng xoắn.","Cả hai mặt đều chỉ chịu biến dạng cắt."],"ans":0,"exp":"• Biến dạng uốn là sự kết hợp của biến dạng kéo và biến dạng nén: Khi thước bị uốn cong, các thớ vật liệu ở phía ngoài (mặt lồi) bị kéo dài ra, còn các thớ vật liệu ở phía trong (mặt lõm) bị ép ngắn lại.","svgGraph":null},{"q":"Hai lò xo nhẹ giống hệt nhau có cùng độ cứng k được mắc nối tiếp thành một hệ lò xo. Độ cứng tương đương k<sub>nt</sub> của hệ hai lò xo nối tiếp bằng:","opts":["k<sub>nt</sub> = <span class=\"fraction\"><span class=\"numerator\">k</span><span class=\"denominator\">2</span></span>.","k<sub>nt</sub> = 2 · k.","k<sub>nt</sub> = k.","k<sub>nt</sub> = 4 · k."],"ans":0,"exp":"• Khi mắc nối tiếp, cùng chịu một lực kéo F: Δl = Δl₁ + Δl₂ ⇒ <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">k<sub>nt</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">k</span></span> + <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">k</span></span> = <span class=\"fraction\"><span class=\"numerator\">2F</span><span class=\"denominator\">k</span></span> ⇒ k<sub>nt</sub> = <span class=\"fraction\"><span class=\"numerator\">k</span><span class=\"denominator\">2</span></span>. Hệ lò xo trở nên mềm hơn (dễ dãn hơn).","svgGraph":null},{"q":"Hãy ghép mỗi loại biến dạng cơ học của vật rắn ở Cột A với ví dụ thực tế tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Biến dạng kéo ➔ Dây cáp cẩu hàng nâng kiện bê tông lên cao","Biến dạng kéo ➔ Các trụ bê tông cốt thép đỡ nhịp cầu vượt","Biến dạng nén ➔ Dây cáp cẩu hàng nâng kiện bê tông lên cao","Biến dạng uốn ➔ Các trụ bê tông cốt thép đỡ nhịp cầu vượt"],"ans":0,"exp":"• Các dạng biến dạng cơ học thực tế: Dây cáp chịu kéo; cột trụ cầu chịu nén; thanh xà đu chịu uốn; trục máy quay truyền động lực chịu xoắn.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong  [ ... ] , độ lớn của lực đàn hồi của lò xo tỉ lệ thuận với  [ ... ]  của lò xo. Đại lượng k được gọi là  [ ... ]  có đơn vị trong hệ SI là  [ ... ] . Khi lực tác dụng vượt quá giới hạn đàn hồi, lò xo sẽ không thể trở về chiều dài ban đầu.\"</i>","opts":["giới hạn đàn hồi — độ biến dạng","không đổi","hệ số ma sát — N·m","độ biến dạng — giới hạn đàn hồi"],"ans":0,"exp":"• Định luật Hooke: Trong giới hạn đàn hồi, F<sub>đh</sub> = k·|Δl|; k là độ cứng (hệ số đàn hồi) tính bằng N/m.","svgGraph":null},{"q":"Một học sinh tiến hành thí nghiệm khảo sát mối liên hệ giữa độ dãn Δl của một lò xo xoắn và lực tác dụng F kéo dãn. Bảng số liệu ghi nhận được như sau: F = 1 N thì Δl = 2 cm; F = 2 N thì Δl = 4 cm; F = 3 N thì Δl = 6 cm; F = 4 N thì Δl = 8 cm. Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu tác dụng một lực kéo F = 1000 N, độ dãn của lò xo chắc chắn sẽ bằng 20 m theo đúng công thức F = k · Δl.","Trong dải lực từ 1 N đến 4 N, độ dãn của lò xo tỉ lệ thuận với lực kéo.","Độ cứng của lò xo dùng trong thí nghiệm bằng k = 50 N/m.","Khi treo vật nặng có trọng lượng P = 2,5 N, độ dãn của lò xo sẽ bằng 5 cm."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F/Δl = 1/0,02 = 2/0,04 = 3/0,06 = 4/0,08 = 50 N/m (hằng số).<br>• <b>Ý b [Đúng]:</b> k = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">Δl</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">0,02</span></span> = 50 N/m.<br>• <b>Ý c [Đúng]:</b> Δl = <span class=\"fraction\"><span class=\"numerator\">2,5</span><span class=\"denominator\">50</span></span> = 0,05 m = 5 cm.<br>• <b>Ý d [Sai]:</b> Lực 1000 N vượt quá xa giới hạn đàn hồi khiến lò xo bị hỏng hoàn toàn, đứt gãy, định luật Hooke không còn áp dụng.","svgGraph":null},{"q":"Hai lò xo nhẹ k₁ = 60 N/m và k₂ = 40 N/m có cùng chiều dài tự nhiên l₀ = 20 cm. Treo vật nặng m = 200 g (lấy g = 10 m/s², trọng lượng P = 2 N). Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi mắc song song, hệ lò xo dãn nhiều hơn so với khi mắc nối tiếp cùng chịu một tải trọng.","Nếu mắc nối tiếp hai lò xo, độ cứng tương đương của hệ bằng k<sub>nt</sub> = 24 N/m.","Độ dãn của hệ nối tiếp khi treo vật m là Δl<sub>nt</sub> ≈ 8,33 cm.","Nếu mắc song song hai lò xo, độ cứng tương đương của hệ bằng k<sub>ss</sub> = 100 N/m."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">k<sub>nt</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">k₁</span></span> + <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">k₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">60</span></span> + <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">40</span></span> = <span class=\"fraction\"><span class=\"numerator\">5</span><span class=\"denominator\">120</span></span> ⇒ k<sub>nt</sub> = 24 N/m.<br>• <b>Ý b [Đúng]:</b> Δl<sub>nt</sub> = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">k<sub>nt</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">24</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">12</span></span> m ≈ 0,0833 m = 8,33 cm.<br>• <b>Ý c [Đúng]:</b> k<sub>ss</sub> = k₁ + k₂ = 60 + 40 = 100 N/m.<br>• <b>Ý d [Sai]:</b> Mắc song song cứng hơn nên dãn ít hơn: Δl<sub>ss</sub> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">100</span></span> = 2 cm < 8,33 cm.","svgGraph":null}],"34":[{"q":"Khối lượng riêng ρ (hoặc D) của một chất được xác định bằng biểu thức nào sau đây?","opts":["ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> (khối lượng của một đơn vị thể tích chất đó).","ρ = m · V.","ρ = <span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">m</span></span>.","ρ = P / V."],"ans":0,"exp":"• <b>Định nghĩa khối lượng riêng:</b> ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span>. Trong hệ SI, khối lượng m đo bằng kg, thể tích V đo bằng m³, khối lượng riêng ρ đo bằng kg/m³.","svgGraph":null},{"q":"Áp suất p tại một điểm ở độ sâu h trong lòng chất lỏng đứng yên có khối lượng riêng ρ được tính theo công thức nào (p₀ là áp suất khí quyển trên mặt thoáng)?","opts":["p = p₀ + ρ · g · h.","p = p₀ + <span class=\"fraction\"><span class=\"numerator\">ρ · g</span><span class=\"denominator\">h</span></span>.","p = ρ · g · h (không phụ thuộc vào áp suất khí quyển p₀).","p = p₀ + ρ · h / g."],"ans":0,"exp":"• <b>Công thức áp suất thủy tĩnh:</b> p = p₀ + ρ·g·h. Áp suất tại độ sâu h bằng tổng áp suất khí quyển p₀ trên mặt thoáng cộng với áp suất do cột chất lỏng có độ cao h gây ra (p<sub>cl</sub> = ρ·g·h).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr34\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Water beaker -->\n      <rect x=\"140\" y=\"50\" width=\"220\" height=\"150\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2.5\" rx=\"4\"/>\n      <!-- Water body -->\n      <rect x=\"142\" y=\"90\" width=\"216\" height=\"108\" fill=\"#0284c7\" fill-opacity=\"0.3\"/>\n      <!-- Water surface -->\n      <line x1=\"142\" y1=\"90\" x2=\"358\" y2=\"90\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"220\" y=\"80\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">Mặt thoáng (p₀)</text>\n      <!-- Depth h dimension -->\n      <line x1=\"180\" y1=\"90\" x2=\"180\" y2=\"160\" stroke=\"#fbbf24\" stroke-width=\"1.5\" marker-end=\"url(#arr34)\"/>\n      <text x=\"165\" y=\"130\" fill=\"#fbbf24\" font-size=\"13\" font-family=\"sans-serif\">h</text>\n      <!-- Point M at depth h -->\n      <circle cx=\"250\" cy=\"160\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"262\" y=\"165\" fill=\"#f43f5e\" font-weight=\"bold\" font-size=\"13\" font-family=\"sans-serif\">Điểm M: p = p₀ + ρ·g·h</text>\n    </svg>"},{"q":"Đơn vị đo áp suất trong hệ đơn vị đo lường quốc tế SI là Paxcan (Pascal, kí hiệu Pa). 1 Pa tương đương với:","opts":["1 Newton trên mét vuông (1 N/m²).","1 Newton trên centimét vuông (1 N/cm²).","1 Jun trên mét khối (1 J/m³).","1 Kilôgam trên mét khối (1 kg/m³)."],"ans":0,"exp":"• <b>Áp suất:</b> p = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">S</span></span>. Lực ép F đo bằng Newton (N), diện tích ép S đo bằng mét vuông (m²), do đó 1 Pa = 1 N/m².","svgGraph":null},{"q":"Nguyên lí Pascal phát biểu rằng độ tăng áp suất tác dụng lên một chất lỏng chứa trong bình kín sẽ:","opts":["Được truyền nguyên vẹn tới mọi điểm trong lòng chất lỏng và tới thành bình.","Giảm dần theo hàm bậc nhất theo khoảng cách tính từ điểm tác dụng.","Chỉ truyền theo phương thẳng đứng từ trên xuống đáy bình.","Bị triệt tiêu hoàn toàn sau khi lan truyền qua khoảng cách 1 mét."],"ans":0,"exp":"• <b>Nguyên lí Pascal:</b> Độ tăng áp suất tác dụng lên một chất lỏng không nén được chứa trong bình kín được truyền nguyên vẹn đến mọi phần của chất lỏng và thành bình chứa. Đây là nguyên lí hoạt động của máy nâng thủy lực, phanh dầu ô tô.","svgGraph":null},{"q":"Một thợ lặn đang lặn ở độ sâu h = 20 m dưới mặt nước biển. Biết khối lượng riêng của nước biển là ρ = 1030 kg/m³, áp suất khí quyển p₀ = 1,01 · 10⁵ Pa và gia tốc trọng trường g = 9,8 m/s². Áp suất tác dụng lên người thợ lặn ở độ sâu này xấp xỉ bằng:","opts":["3,03 · 10⁵ Pa (gấp khoảng 3 lần áp suất khí quyển).","2,02 · 10⁵ Pa.","1,01 · 10⁵ Pa.","4,05 · 10⁵ Pa."],"ans":0,"exp":"• Áp suất do cột nước biển: p<sub>cl</sub> = ρ · g · h = 1030 · 9,8 · 20 = 201880 Pa ≈ 2,02 · 10⁵ Pa.<br>• Áp suất toàn phần: p = p₀ + p<sub>cl</sub> = 1,01 · 10⁵ + 2,02 · 10⁵ = 3,03 · 10⁵ Pa.","svgGraph":null},{"q":"Trong một máy nén thủy lực dùng để nâng ô tô, pít-tông nhỏ có diện tích S₁ = 10 cm², pít-tông lớn có diện tích S₂ = 500 cm². Muốn nâng một chiếc ô tô có trọng lượng P = 20 000 N đặt trên pít-tông lớn, ta phải tác dụng một lực F₁ vào pít-tông nhỏ có độ lớn tối thiểu là:","opts":["400 N.","200 N.","1000 N.","50 N."],"ans":0,"exp":"• Ứng dụng nguyên lí Pascal cho máy ép thuỷ lực:<br><span class=\"fraction\"><span class=\"numerator\">F₁</span><span class=\"denominator\">S₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">F₂</span><span class=\"denominator\">S₂</span></span> ⇒ F₁ = F₂ · <span class=\"fraction\"><span class=\"numerator\">S₁</span><span class=\"denominator\">S₂</span></span> = 20 000 · <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">500</span></span> = 20 000 · <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">50</span></span> = 400 N.","svgGraph":null},{"q":"Hãy ghép mỗi thiết bị hoặc hiện tượng ứng dụng ở Cột A với nguyên lí hoặc định luật vật lí chất lỏng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Kích thuỷ lực nâng gầm ô tô ➔ Nguyên lí Pascal truyền nguyên vẹn độ tăng áp suất trong bình kín","Kích thuỷ lực nâng gầm ô tô ➔ Mặt thoáng ở các nhánh luôn ở cùng một độ cao khi cân bằng","Bình thông nhau chứa cùng chất lỏng ➔ Nguyên lí Pascal truyền nguyên vẹn độ tăng áp suất trong bình kín","Tàu ngầm lặn xuống hoặc nổi lên ➔ Mặt thoáng ở các nhánh luôn ở cùng một độ cao khi cân bằng"],"ans":0,"exp":"• Các ứng dụng thực tế: Máy nâng dùng nguyên lí Pascal; bình thông nhau cân bằng mặt thoáng; tàu ngầm đổi tải nổi/chìm theo lực đẩy Archimedes; chân đập thuỷ điện làm dày để chịu áp suất thuỷ tĩnh cực lớn ở đáy.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Áp suất chất lỏng tại một điểm tác dụng  [ ... ]  lên mọi phương của vật nhúng trong nó. Áp suất tại các điểm có cùng độ sâu trong cùng một chất lỏng đứng yên là  [ ... ] . Trong máy ép thuỷ lực, lực tác dụng lên pít-tông lớn gấp bao nhiêu lần lực tác dụng lên pít-tông nhỏ thì diện tích pít-tông lớn cũng  [ ... ]  bấy nhiêu lần so với diện tích pít-tông nhỏ, nhưng  [ ... ]  thực hiện là không đổi.\"</i>","opts":["theo mọi phương — như nhau","không đổi","nhỏ hơn — áp suất","như nhau — theo mọi phương"],"ans":0,"exp":"• Áp suất chất lỏng tác dụng theo mọi phương, cùng độ sâu cùng áp suất, máy nén thủy lực lợi bao nhiêu lần về lực thì thiệt bấy nhiêu lần về đường đi, công thực hiện không đổi.","svgGraph":null},{"q":"Một ống hình chữ U có hai nhánh hở thẳng đứng đựng nước (khối lượng riêng ρ<sub>n</sub> = 1000 kg/m³). Đổ thêm một lượng dầu (khối lượng riêng ρ<sub>d</sub> = 800 kg/m³) không hòa tan vào nhánh bên trái tạo thành cột dầu có chiều cao h<sub>d</sub> = 10 cm. Lấy g = 10 m/s². Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ chênh lệch mặt thoáng giữa nhánh trái và nhánh phải bằng đúng 10 cm.","Áp suất tác dụng tại đáy của hai nhánh ống U khi chất lỏng đã cân bằng là bằng nhau.","Mặt thoáng của cột dầu ở nhánh trái sẽ cao hơn mặt thoáng của cột nước ở nhánh phải.","Chiều cao cột nước dâng lên ở nhánh phải tính từ mặt phân cách hai chất lỏng bằng 8 cm."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Các điểm ở cùng độ sâu trong cùng chất lỏng (nước ở đáy) có áp suất bằng nhau.<br>• <b>Ý b [Đúng]:</b> Dầu nhẹ hơn nước (ρ<sub>d</sub> < ρ<sub>n</sub>) nên cột dầu phải cao hơn cột nước để tạo ra áp suất bằng nhau.<br>• <b>Ý d [Đúng]:</b> Tại mặt phân cách: p₀ + ρ<sub>d</sub> · g · h<sub>d</sub> = p₀ + ρ<sub>n</sub> · g · h<sub>n</sub> ⇒ h<sub>n</sub> = h<sub>d</sub> · <span class=\"fraction\"><span class=\"numerator\">ρ<sub>d</sub></span><span class=\"denominator\">ρ<sub>n</sub></span></span> = 10 · <span class=\"fraction\"><span class=\"numerator\">800</span><span class=\"denominator\">1000</span></span> = 8 cm.<br>• <b>Ý c [Sai]:</b> Độ chênh lệch mặt thoáng hai nhánh: Δh = h<sub>d</sub> - h<sub>n</sub> = 10 - 8 = 2 cm (không phải 10 cm).","svgGraph":null},{"q":"Xét một đập thuỷ điện ngăn nước có độ sâu nước sau thân đập là h = 50 m. Khối lượng riêng của nước là ρ = 1000 kg/m³, áp suất khí quyển trên mặt hồ là p₀ = 1,0 · 10⁵ Pa, lấy g = 9,8 m/s². Hãy đánh giá tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu nhiệt độ nước ở đáy hồ giảm xuống gần 0 °C thì áp suất thuỷ tĩnh tại đáy đập sẽ giảm về 0.","Áp suất thuỷ tĩnh do riêng cột nước gây ra tại đáy đập bằng 4,9 · 10⁵ Pa.","Áp suất toàn phần tác dụng lên mặt trong của chân đập bằng 5,9 · 10⁵ Pa (gấp gần 6 lần áp suất khí quyển).","Áp lực của nước ép vào chân đập lớn hơn rất nhiều so với đỉnh đập, do đó chân đập luôn được thiết kế xây dày hơn nhiều so với đỉnh đập."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> p<sub>cl</sub> = ρ · g · h = 1000 · 9,8 · 50 = 4,9 · 10⁵ Pa.<br>• <b>Ý b [Đúng]:</b> p = p₀ + p<sub>cl</sub> = 1,0 · 10⁵ + 4,9 · 10⁵ = 5,9 · 10⁵ Pa.<br>• <b>Ý c [Đúng]:</b> p tỉ lệ thuận với độ sâu h, nên chân đập phải làm rất dày để chịu áp lực lớn nhất.<br>• <b>Ý d [Sai]:</b> Khối lượng riêng của nước ở 0 °C xấp xỉ 1000 kg/m³, áp suất thủy tĩnh vẫn xấp xỉ 4,9 · 10⁵ Pa, không thể giảm về 0.","svgGraph":null}]},"11":{"1":[{"q":"Dao động điều hoà là một dạng dao động cơ học đặc biệt mà trong đó li độ của vật là:","opts":["Một hàm bậc nhất theo thời gian.","Một hàm cosin (hoặc sin) của thời gian.","Một hàm bậc hai theo thời gian biến thiên liên tục.","Một đại lượng không đổi theo thời gian."],"ans":"B","exp":"• <b>Định nghĩa SGK:</b> Dao động điều hoà là dao động trong đó li độ của vật là một hàm cosin (hoặc sin) của thời gian: x = A·cos(ωt + φ).<br>• Đại lượng A là biên độ, ω là tần số góc, (ωt + φ) là pha dao động.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <circle cx=\"130\" cy=\"120\" r=\"70\" stroke=\"#334155\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" fill=\"none\"/>\n      <line x1=\"40\" y1=\"120\" x2=\"220\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <line x1=\"130\" y1=\"200\" x2=\"130\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <line x1=\"130\" y1=\"120\" x2=\"180\" y2=\"70\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <circle cx=\"180\" cy=\"70\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"185\" y=\"65\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">M(t)</text>\n      <line x1=\"180\" y1=\"70\" x2=\"180\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <circle cx=\"180\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"175\" y=\"140\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">P(x)</text>\n      <line x1=\"250\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <line x1=\"270\" y1=\"200\" x2=\"270\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr1)\"/>\n      <path d=\"M 270,70 Q 320,30 370,120 T 470,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">t</text><text x=\"275\" y=\"45\" fill=\"#94a3b8\" font-size=\"12\">x</text>\n      <text x=\"250\" y=\"70\" fill=\"#34d399\" font-size=\"12\">+A</text><text x=\"250\" y=\"175\" fill=\"#34d399\" font-size=\"12\">-A</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Mô hình hình chiếu của chuyển động tròn đều</text>\n    </svg>"},{"q":"Trong phương trình dao động điều hoà x = A·cos(ωt + φ), đại lượng ω được gọi là:","opts":["Chu kì của dao động, đơn vị là giây (s).","Pha ban đầu của dao động, đơn vị là radian (rad).","Tần số góc của dao động, đơn vị là radian trên giây (rad/s).","Tần số của dao động, đơn vị là héc (Hz)."],"ans":"C","exp":"• A: Biên độ dao động (m, cm).<br>• ω: Tần số góc (rad/s).<br>• (ωt + φ): Pha dao động tại thời điểm t (rad).<br>• φ: Pha ban đầu tại thời điểm t = 0 (rad).","svgGraph":null},{"q":"Một chất điểm dao động điều hoà thực hiện được 60 dao động toàn phần trong thời gian 30 giây. Chu kì dao động của chất điểm là:","opts":["0,5 s.","2,0 s.","120 s.","1800 s."],"ans":"A","exp":"• <b>Hiện tượng:</b> Chu kì T là thời gian thực hiện 1 dao động toàn phần.<br>• <b>Công thức:</b> T = <span class=\"fraction\"><span class=\"numerator\">Δt</span><span class=\"denominator\">N</span></span><br>• <b>Thay số:</b> T = <span class=\"fraction\"><span class=\"numerator\">30</span><span class=\"denominator\">60</span></span> = 0,5 s.","svgGraph":null},{"q":"Một con lắc lò xo dao động điều hoà dọc theo trục Ox nằm ngang xung quanh vị trí cân bằng O. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Pha dao động (ωt + φ) là đại lượng không đổi theo thời gian và chỉ phụ thuộc vào điều kiện kích thích ban đầu.","Biên độ dao động A là độ dịch chuyển cực đại của vật tính từ vị trí cân bằng và luôn có giá trị dương.","Sau mỗi chu kì T, trạng thái dao động (gồm vị trí và chiều chuyển động) của vật được lặp lại như cũ.","Tần số f của dao động là số dao động toàn phần mà vật thực hiện được trong thời gian 1 giây."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Biên độ A > 0 là khoảng cách cực đại từ vật đến VCB.<br>• <b>Ý b [Đúng]:</b> Chu kì là khoảng thời gian ngắn nhất sau đó trạng thái dao động lặp lại như cũ.<br>• <b>Ý c [Sai]:</b> Pha dao động tăng tuyến tính theo thời gian t; chỉ có pha ban đầu φ mới là hằng số.<br>• <b>Ý d [Đúng]:</b> Tần số f = 1/T là số dao động toàn phần trong 1 giây (Hz).","svgGraph":null},{"q":"Ghép các đại lượng đặc trưng của dao động điều hoà ở Cột A với ý nghĩa vật lí hoặc công thức chuẩn ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Chu kì dao động T ➔ Xác định trạng thái dao động của vật tại thời điểm ban đầu t = 0","Chu kì dao động T ➔ Tốc độ biến thiên của pha dao động, liên hệ: ω = 2π·f","Tần số dao động f ➔ Xác định trạng thái dao động của vật tại thời điểm ban đầu t = 0","Tần số góc ω ➔ Tốc độ biến thiên của pha dao động, liên hệ: ω = 2π·f"],"ans":0,"exp":"• <b>1 - C:</b> Chu kì T = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">ω</span></span> là thời gian 1 dao động toàn phần.<br>• <b>2 - D:</b> Tần số f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> là số dao động trong 1 giây.<br>• <b>3 - B:</b> Tần số góc ω = 2π·f đo tốc độ biến thiên pha.<br>• <b>4 - A:</b> Pha ban đầu φ cho biết trạng thái tại t = 0.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Dao động là chuyển động  [ ... ]  quanh một vị trí cân bằng xác định. Dao động điều hoà là dao động trong đó li độ là hàm  [ ... ]  của thời gian. Khoảng thời gian để vật thực hiện một dao động toàn phần gọi là  [ ... ] . Đại lượng xác định trạng thái dao động tại thời điểm t gọi là  [ ... ] .\"</i>","opts":["lặp đi lặp lại — cosin hoặc sin","không đổi","ngẫu nhiên — biên độ","cosin hoặc sin — lặp đi lặp lại"],"ans":0,"exp":"<b>Định nghĩa chuẩn SGK Vật lí 11:</b><br>• Dao động cơ là chuyển động lặp đi lặp lại quanh VCB.<br>• Dao động điều hoà có li độ là hàm cosin/sin theo thời gian.<br>• Chu kì là thời gian 1 dao động toàn phần.<br>• Pha dao động (ωt + φ) xác định trạng thái tại thời điểm t.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với phương trình x = 8·cos(2πt - π/6) (cm). Biên độ và pha ban đầu của dao động lần lượt là:","opts":["A = 8 cm; φ = -π/6 rad.","A = 8 cm; φ = π/6 rad.","A = 16 cm; φ = 2π rad.","A = 4 cm; φ = -π/6 rad."],"ans":"A","exp":"• Đối chiếu với x = A·cos(ωt + φ):<br>- Biên độ A = 8 cm.<br>- Pha ban đầu φ = -π/6 rad.","svgGraph":null},{"q":"Một con lắc dao động với tần số góc ω = 10 rad/s. Tần số dao động f của con lắc xấp xỉ bằng:","opts":["1,59 Hz.","6,28 Hz.","3,14 Hz.","62,8 Hz."],"ans":"A","exp":"• <b>Công thức:</b> f = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span><br>• <b>Thay số:</b> f = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">2π</span></span> ≈ 1,59 Hz.","svgGraph":null},{"q":"Một vật nhỏ gắn vào đầu một lò xo nhẹ có độ cứng k, dao động điều hoà theo phương ngang trên mặt phẳng không ma sát. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu kích thích cho vật dao động với biên độ lớn gấp đôi thì chu kì dao động của vật cũng tăng gấp đôi.","Quỹ đạo chuyển động của vật dao động điều hoà là một đoạn thẳng có độ dài bằng 2A.","Tại hai vị trí biên x = ±A, độ lớn li độ của vật đạt cực đại.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Sai]:</b> Chu kì của con lắc lò xo T = 2π√(m/k) không phụ thuộc vào biên độ dao động A.<br>• <b>Ý b [Đúng]:</b> Vật chuyển động từ -A đến +A nên chiều dài quỹ đạo là L = 2A.<br>• <b>Ý c [Sai]:</b> Gốc thời gian t = 0 có thể chọn tùy ý tại bất kì vị trí và thời điểm nào.<br>• <b>Ý d [Đúng]:</b> Tại hai biên, |x| = A là giá trị cực đại.","svgGraph":null},{"q":"Pha ban đầu φ của dao động điều hoà cho phép ta xác định:","opts":["Tốc độ cực đại của vật trong quá trình dao động.","Vị trí và chiều chuyển động của vật ở thời điểm ban đầu t = 0.","Năng lượng toàn phần mà vật dao động tích luỹ.","Khoảng thời gian ngắn nhất vật đổi chiều chuyển động."],"ans":"B","exp":"• Tại thời điểm ban đầu t = 0: x₀ = A·cos(φ) và v₀ = -ωA·sin(φ).<br>• Do đó pha ban đầu φ xác định chính xác vị trí và chiều chuyển động của vật lúc bắt đầu quan sát.","svgGraph":null}],"2":[{"q":"Hình bên dưới là đồ thị li độ - thời gian của một vật dao động điều hoà. Biên độ dao động A và chu kì T của vật là:","opts":["A = 4 cm; T = 2 s.","A = 8 cm; T = 2 s.","A = 4 cm; T = 4 s.","A = 2 cm; T = 1 s."],"ans":"A","exp":"• <b>Từ đồ thị:</b><br>- Giá trị đỉnh cao nhất của đồ thị là x = 4 cm, do đó biên độ A = 4 cm.<br>- Khoảng thời gian giữa hai đỉnh sóng liên tiếp (hoặc từ vị trí x = 0 qua một chu trình đầy đủ) là từ t = 0 s đến t = 2 s, do đó chu kì T = 2 s.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"60\" y1=\"60\" x2=\"460\" y2=\"60\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"60\" y1=\"180\" x2=\"460\" y2=\"180\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"40\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr2)\"/>\n      <line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr2)\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"13\">t (s)</text><text x=\"65\" y=\"35\" fill=\"#94a3b8\" font-size=\"13\">x (cm)</text>\n      <text x=\"48\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">0</text><text x=\"42\" y=\"65\" fill=\"#38bdf8\" font-size=\"12\">4</text><text x=\"35\" y=\"185\" fill=\"#38bdf8\" font-size=\"12\">-4</text>\n      <text x=\"155\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">1</text><text x=\"255\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">2</text><text x=\"355\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">3</text><text x=\"455\" y=\"138\" fill=\"#fbbf24\" font-size=\"12\">4</text>\n      <path d=\"M 60,60 C 110,60 110,180 160,180 C 210,180 210,60 260,60 C 310,60 310,180 360,180 C 410,180 410,60 460,60\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    </svg>"},{"q":"Đồ thị li độ - thời gian của một dao động điều hoà là một đường cong hình sin. Dựa vào đồ thị, đại lượng nào sau đây KHÔNG THỂ xác định trực tiếp được ngay mà phải qua tính toán?","opts":["Biên độ dao động A.","Chu kì dao động T.","Li độ x tại một thời điểm t cho trước.","Khối lượng m của vật dao động."],"ans":"D","exp":"• Đồ thị x-t cho biết trực tiếp: Biên độ A, chu kì T, tần số f = 1/T, pha ban đầu φ và li độ x tại mọi thời điểm.<br>• Khối lượng m là đại lượng quán tính động lực học, không biểu hiện trực tiếp trên đồ thị hình học x-t.","svgGraph":null},{"q":"Tại thời điểm ban đầu t = 0, một vật dao động điều hoà đang ở vị trí biên dương (x = +A). Pha ban đầu φ của dao động này là:","opts":["φ = 0 rad.","φ = π rad.","φ = π/2 rad.","φ = -π/2 rad."],"ans":"A","exp":"• Tại t = 0: x₀ = A·cos(φ) = +A ⇔ cos(φ) = 1 ⇔ φ = 0 rad.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có đồ thị li độ - thời gian cắt trục hoành tại các thời điểm t₁ = 0,2 s và t₂ = 0,6 s liên tiếp. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tần số dao động của chất điểm là f = 2,5 Hz.","Khoảng thời gian giữa hai lần liên tiếp vật đi qua vị trí cân bằng bằng một nửa chu kì (T/2).","Chu kì dao động của chất điểm là T = 0,8 s.","Thời gian để chất điểm đi từ biên âm sang biên dương là 0,4 s."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Vật qua VCB liên tiếp sau mỗi khoảng thời gian Δt = T/2.<br>• <b>Ý b [Đúng]:</b> T/2 = t₂ - t₁ = 0,6 - 0,2 = 0,4 s ⇒ T = 0,8 s.<br>• <b>Ý c [Sai]:</b> Tần số f = 1/T = 1/0,8 = 1,25 Hz (không phải 2,5 Hz).<br>• <b>Ý d [Đúng]:</b> Thời gian từ biên âm sang biên dương là nửa chu kì: T/2 = 0,4 s.","svgGraph":null},{"q":"Ghép vị trí của chất điểm dao động điều hoà tại thời điểm ban đầu t = 0 ở Cột A với giá trị pha ban đầu φ tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vật qua vị trí cân bằng theo chiều dương (x = 0, v > 0) ➔ Pha ban đầu φ = π rad (hoặc -π rad)","Vật qua vị trí cân bằng theo chiều dương (x = 0, v > 0) ➔ Pha ban đầu φ = 0 rad","Vật qua vị trí cân bằng theo chiều âm (x = 0, v < 0) ➔ Pha ban đầu φ = π rad (hoặc -π rad)","Vật ở vị trí biên dương (x = +A) ➔ Pha ban đầu φ = 0 rad"],"ans":0,"exp":"• <b>1 - C:</b> x = 0, v > 0 ⇒ cos(φ) = 0 và sin(φ) < 0 ⇒ φ = -π/2 rad.<br>• <b>2 - D:</b> x = 0, v < 0 ⇒ cos(φ) = 0 và sin(φ) > 0 ⇒ φ = +π/2 rad.<br>• <b>3 - B:</b> x = +A ⇒ cos(φ) = 1 ⇒ φ = 0 rad.<br>• <b>4 - A:</b> x = -A ⇒ cos(φ) = -1 ⇒ φ = π rad.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khoảng cách từ trục thời gian đến điểm cao nhất của đường cong là  [ ... ] . Khoảng thời gian giữa hai điểm liên tiếp có cùng trạng thái dao động là  [ ... ] . Nếu tại t = 0 đồ thị xuất phát từ đỉnh cao nhất thì pha ban đầu bằng  [ ... ] . Nếu đồ thị đi qua gốc toạ độ và đi lên thì pha ban đầu bằng  [ ... ] .\"</i>","opts":["biên độ dao động — chu kì dao động","không đổi","tần số dao động — vận tốc cực đại","chu kì dao động — biên độ dao động"],"ans":0,"exp":"<b>Quy tắc đọc đồ thị x-t:</b><br>• Đỉnh cao nhất là biên độ A.<br>• Chu kì T là khoảng thời gian lặp lại trạng thái.<br>• Điểm cực đại tại t = 0 ứng với φ = 0.<br>• Đi qua gốc O theo chiều dương ứng với φ = -π/2.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà trên trục Ox. Trong thời gian 1 phút, vật thực hiện được 120 dao động toàn phần. Tần số góc ω của dao động là:","opts":["4π rad/s.","2π rad/s.","2 rad/s.","120π rad/s."],"ans":"A","exp":"• Tần số: f = N/Δt = 120/60 = 2 Hz.<br>• Tần số góc: ω = 2π·f = 2π · 2 = 4π rad/s.","svgGraph":null},{"q":"Một vật dao động điều hoà theo phương trình x = 5·cos(10t + π/4) (cm). Độ dịch chuyển (li độ) của vật tại thời điểm t = 0 là:","opts":["2,5√2 cm.","5 cm.","2,5 cm.","0 cm."],"ans":"A","exp":"• Tại t = 0: x = 5·cos(π/4) = 5 · <span class=\"fraction\"><span class=\"numerator\">√2</span><span class=\"denominator\">2</span></span> = 2,5√2 cm (≈ 3,54 cm).","svgGraph":null},{"q":"Một vật dao động điều hoà có phương trình x = 10·cos(2πt - π/3) (cm). Xét tính Đúng / Sai của các nhận định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Tại thời điểm t = 0, vật đang chuyển động theo chiều dương của trục Ox.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> φ = -π/3 < 0 ⇒ v₀ = -ωA·sin(φ) > 0 (chuyển động theo chiều dương).<br>• <b>Ý b [Đúng]:</b> Tại t = 0,5 s: pha là 2π(0,5) - π/3 = 2π/3 ⇒ x = 10·cos(2π/3) = -5 cm.<br>• <b>Ý c [Đúng]:</b> Qua VCB khi pha = π/2 ⇒ 2πt - π/3 = π/2 ⇒ 2πt = 5π/6 ⇒ t = 5/12 s.<br>• <b>Ý d [Đúng]:</b> Quãng đường trong 1 chu kì luôn là S = 4A = 4 · 10 = 40 cm.","svgGraph":null},{"q":"Quỹ đạo chuyển động của một vật dao động điều hoà là một đoạn thẳng dài 14 cm. Biên độ dao động của vật là:","opts":["7 cm.","14 cm.","28 cm.","3,5 cm."],"ans":"A","exp":"• Chiều dài quỹ đạo: L = 2A ⇒ A = L/2 = 14/2 = 7 cm.","svgGraph":null}],"3":[{"q":"Một chất điểm dao động điều hoà theo phương trình x = A·cos(ωt + φ). Biểu thức vận tốc v của chất điểm là:","opts":["v = -ωA·sin(ωt + φ).","v = ωA·cos(ωt + φ).","v = -ω²A·sin(ωt + φ).","v = ω²A·cos(ωt + φ)."],"ans":"A","exp":"• Vận tốc là đạo hàm bậc nhất của li độ theo thời gian: v = x' = -ωA·sin(ωt + φ) = ωA·cos(ωt + φ + π/2).<br>• Vận tốc biến thiên điều hoà cùng tần số góc ω và sớm pha π/2 so với li độ.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"30\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr3)\"/>\n      <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr3)\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">t</text>\n      <path d=\"M 50,60 Q 100,60 150,120 T 250,180 T 350,120 T 450,60\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <path d=\"M 50,120 Q 100,180 150,180 T 250,60 T 350,120 T 450,180\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/>\n      <path d=\"M 50,180 Q 100,180 150,120 T 250,60 T 350,120 T 450,180\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <rect x=\"260\" y=\"25\" width=\"200\" height=\"40\" fill=\"#1e293b\" rx=\"5\"/>\n      <line x1=\"270\" y1=\"38\" x2=\"295\" y2=\"38\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <text x=\"305\" y=\"42\" fill=\"#38bdf8\" font-size=\"11\">Li độ x(t)</text>\n      <line x1=\"270\" y1=\"53\" x2=\"295\" y2=\"53\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"4,2\"/>\n      <text x=\"305\" y=\"57\" fill=\"#34d399\" font-size=\"11\">Vận tốc v(t)</text>\n      <line x1=\"370\" y1=\"38\" x2=\"395\" y2=\"38\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n      <text x=\"405\" y=\"42\" fill=\"#f43f5e\" font-size=\"11\">Gia tốc a(t)</text>\n    </svg>"},{"q":"Trong dao động điều hoà, gia tốc của vật biến thiên điều hoà và có mối quan hệ về pha so với li độ là:","opts":["Ngược pha với li độ.","Cùng pha với li độ.","Sớm pha π/2 so với li độ.","Trễ pha π/2 so với li độ."],"ans":"A","exp":"• Biểu thức gia tốc: a = -ω²x = ω²A·cos(ωt + φ + π).<br>• Dấu âm chứng tỏ véctơ gia tốc a luôn ngược chiều với li độ x, nghĩa là ngược pha với li độ.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với biên độ A = 5 cm và tần số góc ω = 10 rad/s. Tốc độ cực đại v<sub>max</sub> của chất điểm là:","opts":["50 cm/s.","2 cm/s.","0,5 cm/s.","500 cm/s."],"ans":"A","exp":"• <b>Công thức:</b> v<sub>max</sub> = ω·A<br>• <b>Thay số:</b> v<sub>max</sub> = 10 · 5 = 50 cm/s (khi vật đi qua vị trí cân bằng).","svgGraph":null},{"q":"Khi một vật dao động điều hoà quanh vị trí cân bằng O trên đoạn thẳng -A đến +A, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tại vị trí biên, vận tốc của vật đạt giá trị lớn nhất và gia tốc bằng 0.","Khi vật đi từ vị trí cân bằng ra vị trí biên thì chuyển động của vật là chuyển động chậm dần.","Véctơ gia tốc của vật luôn luôn hướng về vị trí cân bằng và có độ lớn tỉ lệ với khoảng cách tới vị trí cân bằng.","Ở vị trí cân bằng, hợp lực tác dụng lên vật bằng 0 nên gia tốc của vật triệt tiêu."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Từ VCB ra biên tốc độ giảm từ cực đại về 0 nên là chậm dần.<br>• <b>Ý b [Đúng]:</b> a = -ω²x nên véctơ gia tốc luôn hướng về O và có độ lớn |a| = ω²|x|.<br>• <b>Ý c [Sai]:</b> Tại biên v = 0 còn độ lớn gia tốc cực đại a<sub>max</sub> = ω²A.<br>• <b>Ý d [Đúng]:</b> Tại VCB x = 0 ⇒ F<sub>hl</sub> = ma = 0 ⇒ a = 0.","svgGraph":null},{"q":"Ghép các vị trí đặc biệt của chất điểm dao động điều hoà ở Cột A với độ lớn vận tốc và gia tốc tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vị trí cân bằng (x = 0) ➔ Độ lớn vận tốc v = v<sub>max</sub>·√3/2 và gia tốc |a| = a<sub>max</sub>/2","Vị trí cân bằng (x = 0) ➔ Tốc độ triệt tiêu (v = 0) và độ lớn gia tốc cực đại (|a| = ω²A)","Vị trí biên dương hoặc biên âm (x = ±A) ➔ Độ lớn vận tốc v = v<sub>max</sub>·√3/2 và gia tốc |a| = a<sub>max</sub>/2","Vị trí có li độ x = ±A/2 ➔ Tốc độ triệt tiêu (v = 0) và độ lớn gia tốc cực đại (|a| = ω²A)"],"ans":0,"exp":"• <b>1 - C:</b> Tại VCB: v đạt cực đại v<sub>max</sub> = ωA, gia tốc a = 0.<br>• <b>2 - B:</b> Tại biên: v = 0, |a| đạt cực đại |a<sub>max</sub>| = ω²A.<br>• <b>3 - A:</b> Tại x = ±A/2: |a| = a<sub>max</sub>/2, v = v<sub>max</sub>·√3/2.<br>• <b>4 - D:</b> Tại x = ±A/√2: v = v<sub>max</sub>/√2, |a| = a<sub>max</sub>/√2.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Vận tốc trong dao động điều hoà  [ ... ]  pha một góc π/2 so với li độ. Gia tốc dao động  [ ... ]  pha so với li độ và sớm pha  [ ... ]  so với vận tốc. Công thức độc lập thời gian giữa li độ x và vận tốc v là  [ ... ] .\"</i>","opts":["sớm — ngược","không đổi","cùng — x² - v²/ω² = A²","ngược — sớm"],"ans":0,"exp":"<b>Mối quan hệ pha và hệ thức độc lập:</b><br>• v sớm pha π/2 so với x.<br>• a ngược pha với x và sớm pha π/2 so với v.<br>• Hệ thức độc lập: x² + (v/ω)² = A².","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có biên độ A = 4 cm và chu kì T = 2 s. Gia tốc cực đại a<sub>max</sub> của chất điểm là:","opts":["4π² cm/s².","2π² cm/s².","8π cm/s².","16π² cm/s²."],"ans":"A","exp":"• Tần số góc: ω = 2π/T = 2π/2 = π rad/s.<br>• Gia tốc cực đại: a<sub>max</sub> = ω²A = π² · 4 = 4π² cm/s² (≈ 39,5 cm/s²).","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với phương trình x = 6·cos(5t) (cm). Khi vật có li độ x = 3 cm thì độ lớn gia tốc của vật là:","opts":["75 cm/s².","15 cm/s².","150 cm/s².","30 cm/s²."],"ans":"A","exp":"• Độ lớn gia tốc: |a| = ω²|x| = 5² · 3 = 25 · 3 = 75 cm/s².","svgGraph":null},{"q":"Một vật dao động điều hoà có tần số góc ω = 10 rad/s và biên độ A = 10 cm. Tại một thời điểm, vật có li độ x = 6 cm và đang chuyển động theo chiều dương. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Vật đang chuyển động nhanh dần vì vận tốc v > 0.","Vận tốc của vật tại thời điểm này có giá trị v = +80 cm/s.","Gia tốc của vật tại thời điểm này có giá trị a = -600 cm/s².","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Áp dụng x² + v²/ω² = A² ⇒ v = +ω√(A² - x²) = 10√(100 - 36) = +80 cm/s.<br>• <b>Ý b [Đúng]:</b> a = -ω²x = -10² · 6 = -600 cm/s².<br>• <b>Ý c [Sai]:</b> Vật ở x = 6 > 0 đang đi ra biên dương (v > 0) nên là chuyển động chậm dần (a và v trái dấu).<br>• <b>Ý d [Sai]:</b> Lực kéo về hướng về O ngược chiều chuyển động nên cản trở, làm giảm tốc độ.","svgGraph":null},{"q":"Hệ thức độc lập thời gian giữa vận tốc v và gia tốc a của vật dao động điều hoà là:","opts":["<span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">ω²</span></span> + <span class=\"fraction\"><span class=\"numerator\">a²</span><span class=\"denominator\">ω⁴</span></span> = A².","<span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">ω⁴</span></span> + <span class=\"fraction\"><span class=\"numerator\">a²</span><span class=\"denominator\">ω²</span></span> = A².","v² + a² = ω²A².","v²·ω² + a² = A²."],"ans":"A","exp":"• Vì a = -ω²x ⇒ x² = a²/ω⁴.<br>• Thay vào hệ thức x² + v²/ω² = A² ta được: <span class=\"fraction\"><span class=\"numerator\">v²</span><span class=\"denominator\">ω²</span></span> + <span class=\"fraction\"><span class=\"numerator\">a²</span><span class=\"denominator\">ω⁴</span></span> = A².","svgGraph":null}],"4":[{"q":"Một chất điểm dao động điều hoà với phương trình x = 10·cos(4πt + π/3) (cm). Tốc độ của chất điểm khi đi qua vị trí cân bằng là:","opts":["40π cm/s.","10π cm/s.","4π cm/s.","160π² cm/s."],"ans":"A","exp":"• Tốc độ qua VCB đạt giá trị cực đại: v<sub>max</sub> = ωA.<br>• Thay số: v<sub>max</sub> = 4π · 10 = 40π cm/s (≈ 125,7 cm/s).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr4\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <circle cx=\"250\" cy=\"120\" r=\"80\" stroke=\"#334155\" stroke-width=\"2\" fill=\"none\"/>\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr4)\"/>\n      <line x1=\"250\" y1=\"210\" x2=\"250\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr4)\"/>\n      <line x1=\"250\" y1=\"120\" x2=\"290\" y2=\"50.7\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <circle cx=\"290\" cy=\"50.7\" r=\"5\" fill=\"#38bdf8\"/>\n      <text x=\"295\" y=\"45\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">M₀ (t=0)</text>\n      <text x=\"260\" y=\"100\" fill=\"#fbbf24\" font-size=\"12\">π/3</text>\n      <line x1=\"290\" y1=\"50.7\" x2=\"290\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <circle cx=\"290\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"285\" y=\"140\" fill=\"#f43f5e\" font-size=\"12\">x₀ = 5 cm</text>\n      <text x=\"330\" y=\"135\" fill=\"#34d399\" font-size=\"12\">+10 cm</text>\n      <text x=\"145\" y=\"135\" fill=\"#34d399\" font-size=\"12\">-10 cm</text>\n      <text x=\"180\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Vòng tròn lượng giác biểu diễn pha dao động</text>\n    </svg>"},{"q":"Một con lắc lò xo dao động điều hoà với biên độ A = 8 cm và chu kì T = 1,2 s. Khoảng thời gian ngắn nhất để vật đi từ vị trí cân bằng x = 0 đến vị trí x = 4 cm là:","opts":["0,1 s.","0,2 s.","0,3 s.","0,6 s."],"ans":"A","exp":"• Vị trí x = 4 cm = A/2.<br>• Thời gian ngắn nhất đi từ VCB (x = 0) đến x = A/2 là: Δt = T/12.<br>• Thay số: Δt = 1,2 / 12 = 0,1 s.","svgGraph":null},{"q":"Một vật dao động điều hoà với biên độ A = 10 cm. Quãng đường vật đi được trong khoảng thời gian bằng 2,5 chu kì (2,5T) là:","opts":["100 cm.","50 cm.","25 cm.","200 cm."],"ans":"A","exp":"• Trong 1 chu kì vật luôn đi được quãng đường S₁ = 4A.<br>• Trong 0,5 chu kì vật luôn đi được quãng đường S₀.5 = 2A.<br>• Tổng quãng đường: S = 2 · (4A) + 2A = 10A = 10 · 10 = 100 cm.","svgGraph":null},{"q":"Một vật dao động điều hoà dọc theo trục Ox có phương trình x = 6·cos(2πt - π/2) (cm). Xét tính Đúng / Sai của các mệnh đề sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Tại thời điểm ban đầu t = 0, vật đang ở vị trí cân bằng và chuyển động theo chiều dương.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> φ = -π/2 ⇒ x₀ = 0 và v₀ = +ωA > 0.<br>• <b>Ý b [Đúng]:</b> v<sub>max</sub> = ωA = 2π · 6 = 12π cm/s.<br>• <b>Ý c [Đúng]:</b> Tại t = 0 vật qua VCB theo chiều dương nên đạt vận tốc cực đại ngay lúc ban đầu.<br>• <b>Ý d [Đúng]:</b> Chu kì T = 2π/ω = 1 s. Quãng đường 1T là S = 4A = 24 cm ⇒ v<sub>tb</sub> = S/T = 24 cm/s.","svgGraph":null},{"q":"Ghép khoảng thời gian ngắn nhất chuyển động của vật dao động điều hoà ở Cột A với phân số chu kì tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Từ VCB (x = 0) đến vị trí x = A/2 ➔ Thời gian Δt = T/8","Từ VCB (x = 0) đến vị trí x = A/2 ➔ Thời gian Δt = T/6","Từ VCB (x = 0) đến vị trí x = A/√2 ➔ Thời gian Δt = T/8","Từ VCB (x = 0) đến vị trí x = A·√3/2 ➔ Thời gian Δt = T/6"],"ans":0,"exp":"• <b>1 - D:</b> Từ 0 đến A/2: góc quét π/6 ⇒ Δt = T/12.<br>• <b>2 - A:</b> Từ 0 đến A/√2: góc quét π/4 ⇒ Δt = T/8.<br>• <b>3 - B:</b> Từ 0 đến A√3/2: góc quét π/3 ⇒ Δt = T/6.<br>• <b>4 - C:</b> Từ 0 đến A: góc quét π/2 ⇒ Δt = T/4.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Quãng đường vật đi được trong một chu kì luôn bằng  [ ... ] . Thời gian ngắn nhất để vật đi từ biên này sang biên kia là  [ ... ] . Tốc độ trung bình trong một chu kì tính theo công thức  [ ... ] . Khi vật đi từ vị trí cân bằng ra vị trí biên thì lực kéo về sinh công  [ ... ] .\"</i>","opts":["4A — T/2","không đổi","T/4 — dương","T/2 — 4A"],"ans":0,"exp":"• Trong 1T: S = 4A.<br>• Từ -A đến +A: Δt = T/2.<br>• Tốc độ trung bình: v<sub>tb</sub> = S/T = 4A/T.<br>• Từ VCB ra biên: lực kéo về hướng ngược chiều chuyển động nên công A < 0.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với tần số góc ω = 5 rad/s. Khi li độ x = 4 cm thì vận tốc v = 15 cm/s. Biên độ dao động của chất điểm là:","opts":["5 cm.","7 cm.","3 cm.","25 cm."],"ans":"A","exp":"• Áp dụng hệ thức độc lập: A = √(x² + v²/ω²).<br>• Thay số: A = √(4² + (15/5)²) = √(16 + 9) = √25 = 5 cm.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà quanh vị trí cân bằng. Trong khoảng thời gian ngắn nhất giữa hai lần liên tiếp vật đi qua li độ x = 5 cm, vật đi được quãng đường dài 10 cm. Biên độ dao động A là:","opts":["10 cm.","5 cm.","5√2 cm.","15 cm."],"ans":"A","exp":"• Vật đi từ x = 5 cm ra biên A rồi quay lại x = 5 cm: Quãng đường S = 2(A - 5).<br>• Theo đề bài: 2(A - 5) = 10 ⇒ A - 5 = 5 ⇒ A = 10 cm.","svgGraph":null},{"q":"Một con lắc lò xo dao động điều hoà theo phương ngang với biên độ 10 cm và chu kì 1 s. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tốc độ của vật khi đi qua vị trí x = 5√2 cm bằng một nửa tốc độ cực đại.","Quãng đường lớn nhất vật đi được trong khoảng thời gian 0,25 s (T/4) là 10√2 cm.","Quãng đường nhỏ nhất vật đi được trong khoảng thời gian 0,25 s (T/4) là 20 - 10√2 cm.","Thời gian vật chuyển động nhanh dần trong mỗi chu kì là 0,5 s."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> S<sub>max</sub> trong T/4 = 2A·sin(Δφ/2) = 2 · 10 · sin(π/4) = 10√2 cm.<br>• <b>Ý b [Đúng]:</b> S<sub>min</sub> trong T/4 = 2A(1 - cos(Δφ/2)) = 20(1 - cos(π/4)) = 20 - 10√2 cm.<br>• <b>Ý c [Sai]:</b> x = A/√2 ⇒ v = v<sub>max</sub>/√2 ≈ 0,707 v<sub>max</sub> (không phải một nửa).<br>• <b>Ý d [Đúng]:</b> Nhanh dần khi đi từ biên về VCB (2 lần mỗi chu kì, mỗi lần T/4), tổng thời gian là T/2 = 0,5 s.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có gia tốc a và li độ x liên hệ với nhau qua hệ thức a = -100x (cm/s²), trong đó x tính bằng cm. Chu kì dao động của chất điểm là:","opts":["0,2π s.","0,1π s.","10 s.","2 s."],"ans":"A","exp":"• Từ a = -ω²x và a = -100x ⇒ ω² = 100 ⇒ ω = 10 rad/s.<br>• Chu kì: T = 2π/ω = 2π/10 = 0,2π s (≈ 0,628 s).","svgGraph":null}],"5":[{"q":"Cơ năng của một vật dao động điều hoà có khối lượng m, tần số góc ω và biên độ A được xác định bởi công thức:","opts":["W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A².","W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mωA².","W = mω²A².","W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A."],"ans":"A","exp":"• Cơ năng của vật dao động điều hoà bằng tổng động năng và thế năng, luôn được bảo toàn và tỉ lệ với bình phương biên độ dao động: W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>kA².","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr5\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"50\" y1=\"190\" x2=\"450\" y2=\"190\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr5)\"/>\n      <line x1=\"250\" y1=\"210\" x2=\"250\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr5)\"/>\n      <text x=\"455\" y=\"195\" fill=\"#94a3b8\" font-size=\"12\">x</text>\n      <text x=\"255\" y=\"40\" fill=\"#94a3b8\" font-size=\"12\">W</text>\n      <line x1=\"90\" y1=\"60\" x2=\"410\" y2=\"60\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n      <text x=\"415\" y=\"65\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">W = const</text>\n      <path d=\"M 90,60 Q 250,220 410,60\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <path d=\"M 90,190 Q 250,-70 410,190\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n      <text x=\"80\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">-A</text>\n      <text x=\"400\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">+A</text>\n      <text x=\"240\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">0</text>\n      <circle cx=\"179.3\" cy=\"125\" r=\"4\" fill=\"#f43f5e\"/>\n      <circle cx=\"320.7\" cy=\"125\" r=\"4\" fill=\"#f43f5e\"/>\n      <text x=\"280\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">W<tspan baseline-shift=\"sub\" font-size=\"70%\">đ</tspan> = W<tspan baseline-shift=\"sub\" font-size=\"70%\">t</tspan></text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị động năng và thế năng theo li độ x</text>\n    </svg>"},{"q":"Trong quá trình dao động điều hoà, thế năng của vật đạt giá trị cực đại khi vật ở vị trí:","opts":["Biên dương hoặc biên âm (x = ±A).","Vị trí cân bằng (x = 0).","Vị trí có li độ x = ±A/2.","Vị trí có vận tốc đạt cực đại."],"ans":"A","exp":"• Thế năng: W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²x².<br>• Khi x = ±A, độ lớn li độ cực đại nên thế năng đạt cực đại: W<sub>t</sub>,max = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = W.","svgGraph":null},{"q":"Một vật dao động điều hoà với chu kì T. Động năng và thế năng của vật biến thiên tuần hoàn theo thời gian với chu kì bằng:","opts":["T/2.","T.","2T.","4T."],"ans":"A","exp":"• Biểu thức thế năng và động năng chứa cos²(ωt + φ) và sin²(ωt + φ).<br>• Khi hạ bậc: cos²(α) = <span class=\"fraction\"><span class=\"numerator\">1 + cos(2α)</span><span class=\"denominator\">2</span></span> ⇒ tần số góc tăng gấp đôi (2ω), do đó chu kì giảm một nửa: T' = T/2.","svgGraph":null},{"q":"Khi khảo sát sự chuyển hoá năng lượng của con lắc lò xo dao động điều hoà trên mặt phẳng ngang, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu tăng biên độ dao động lên gấp đôi thì cơ năng của hệ dao động cũng tăng lên gấp đôi.","Khi vật chuyển động từ vị trí cân bằng ra vị trí biên thì động năng giảm dần và chuyển hoá thành thế năng.","Tại vị trí cân bằng, thế năng triệt tiêu và động năng của vật đạt giá trị cực đại bằng cơ năng.","Tại vị trí li độ x = ±A/√2 thì động năng của vật bằng thế năng của vật."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Từ VCB ra biên tốc độ giảm dần nên W<sub>đ</sub> giảm, W<sub>t</sub> tăng.<br>• <b>Ý b [Đúng]:</b> Tại x = 0, W<sub>t</sub> = 0 và W<sub>đ</sub> = W<sub>đ</sub>,max = W.<br>• <b>Ý c [Sai]:</b> Cơ năng tỉ lệ thuận với bình phương biên độ (W ∝ A²), nên khi A tăng gấp đôi thì W tăng gấp 4 lần.<br>• <b>Ý d [Đúng]:</b> W<sub>t</sub> = 0,5mω²(A/√2)² = 0,25mω²A² = W/2 ⇒ W<sub>đ</sub> = W - W<sub>t</sub> = W/2 (động năng bằng thế năng).","svgGraph":null},{"q":"Ghép các vị trí li độ x ở Cột A với mối quan hệ giữa động năng (W<sub>đ</sub>) và thế năng (W<sub>t</sub>) ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Vị trí li độ x = ±A/√2 ➔ Động năng bằng 3 lần thế năng (W<sub>đ</sub> = 3W<sub>t</sub>)","Vị trí li độ x = ±A/√2 ➔ Thế năng bằng 3 lần động năng (W<sub>t</sub> = 3W<sub>đ</sub>)","Vị trí li độ x = ±A/2 ➔ Động năng bằng 3 lần thế năng (W<sub>đ</sub> = 3W<sub>t</sub>)","Vị trí li độ x = ±A·√3/2 ➔ Thế năng bằng 3 lần động năng (W<sub>t</sub> = 3W<sub>đ</sub>)"],"ans":0,"exp":"• <b>1 - D:</b> x = ±A/√2 ⇒ W<sub>t</sub> = W/2 ⇒ W<sub>đ</sub> = W<sub>t</sub>.<br>• <b>2 - A:</b> x = ±A/2 ⇒ W<sub>t</sub> = W/4 ⇒ W<sub>đ</sub> = 3W/4 = 3W<sub>t</sub>.<br>• <b>3 - B:</b> x = ±A√3/2 ⇒ W<sub>t</sub> = 3W/4 ⇒ W<sub>đ</sub> = W/4 ⇒ W<sub>t</sub> = 3W<sub>đ</sub>.<br>• <b>4 - C:</b> x = 0 ⇒ W<sub>t</sub> = 0, W<sub>đ</sub> = W.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong quá trình dao động điều hoà, có sự chuyển hoá qua lại liên tục giữa  [ ... ]  và  [ ... ]  nhưng tổng của chúng là  [ ... ]  luôn được bảo toàn. Động năng và thế năng biến thiên tuần hoàn với tần số bằng  [ ... ]  tần số của li độ.\"</i>","opts":["động năng — thế năng","không đổi","nội năng — gia tốc","thế năng — động năng"],"ans":0,"exp":"<b>Định luật bảo toàn năng lượng dao động:</b><br>• Động năng và thế năng chuyển hoá lẫn nhau.<br>• Cơ năng W = W<sub>đ</sub> + W<sub>t</sub> không đổi.<br>• Tần số năng lượng: f' = 2f (gấp hai lần tần số dao động).","svgGraph":null},{"q":"Một con lắc lò xo có độ cứng k = 100 N/m dao động điều hoà với biên độ A = 5 cm. Cơ năng của con lắc là:","opts":["0,125 J.","1,25 J.","0,25 J.","125 J."],"ans":"A","exp":"• Đổi đơn vị: A = 5 cm = 0,05 m.<br>• Công thức: W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>kA² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 100 · (0,05)² = 0,125 J.","svgGraph":null},{"q":"Một vật có khối lượng m = 200 g dao động điều hoà với tần số f = 5 Hz và biên độ A = 4 cm. Cơ năng của vật (lấy π² ≈ 10) là:","opts":["0,16 J.","0,08 J.","0,32 J.","1,6 J."],"ans":"A","exp":"• ω = 2π·f = 10π rad/s.<br>• Đổi m = 0,2 kg; A = 0,04 m.<br>• W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 0,2 · (10π)² · (0,04)² = 0,1 · 1000 · 0,0016 = 0,16 J.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với cơ năng W = 40 mJ. Tại vị trí có li độ x = A/2, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tốc độ của chất điểm tại vị trí này bằng một nửa tốc độ cực đại.","Thế năng của chất điểm tại vị trí này có giá trị W<sub>t</sub> = 10 mJ.","Động năng của chất điểm tại vị trí này có giá trị W<sub>đ</sub> = 30 mJ.","Nếu vật đi tiếp đến vị trí cân bằng thì động năng tăng thêm 10 mJ."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tại x = A/2 ⇒ W<sub>t</sub> = (1/4)W = 40/4 = 10 mJ.<br>• <b>Ý b [Đúng]:</b> W<sub>đ</sub> = W - W<sub>t</sub> = 40 - 10 = 30 mJ.<br>• <b>Ý c [Sai]:</b> x = A/2 ⇒ v = v<sub>max</sub>·√3/2 ≈ 0,866 v<sub>max</sub> (không phải 0,5 v<sub>max</sub>).<br>• <b>Ý d [Đúng]:</b> Tại VCB W<sub>đ</sub> = 40 mJ, nên tăng thêm 40 - 30 = 10 mJ.","svgGraph":null},{"q":"Khi vật dao động điều hoà đi qua vị trí có động năng bằng thế năng (W<sub>đ</sub> = W<sub>t</sub>) thì độ lớn li độ của vật là:","opts":["|x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">√2</span></span>.","|x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">2</span></span>.","|x| = <span class=\"fraction\"><span class=\"numerator\">A√3</span><span class=\"denominator\">2</span></span>.","|x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">4</span></span>."],"ans":"A","exp":"• Khi W<sub>đ</sub> = W<sub>t</sub> ⇒ W = W<sub>đ</sub> + W<sub>t</sub> = 2W<sub>t</sub>.<br>• <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²A² = 2 · (<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²x²) ⇒ x² = <span class=\"fraction\"><span class=\"numerator\">A²</span><span class=\"denominator\">2</span></span> ⇒ |x| = <span class=\"fraction\"><span class=\"numerator\">A</span><span class=\"denominator\">√2</span></span>.","svgGraph":null}],"6":[{"q":"Hiện tượng biên độ và cơ năng của dao động giảm dần theo thời gian được gọi là:","opts":["Dao động tắt dần.","Dao động cưỡng bức.","Dao động duy trì.","Hiện tượng cộng hưởng."],"ans":"A","exp":"• Dao động tắt dần là dao động có biên độ và cơ năng giảm dần theo thời gian do ma sát và lực cản của môi trường chuyển hoá cơ năng thành nhiệt năng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr6\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"30\" y1=\"120\" x2=\"230\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <line x1=\"40\" y1=\"200\" x2=\"40\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <path d=\"M 40,60 Q 60,60 80,120 T 120,160 T 155,100 T 185,130 T 215,120\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n      <text x=\"235\" y=\"125\" fill=\"#94a3b8\" font-size=\"11\">t</text>\n      <text x=\"45\" y=\"45\" fill=\"#94a3b8\" font-size=\"11\">x</text>\n      <text x=\"55\" y=\"220\" fill=\"#f43f5e\" font-size=\"12\">Dao động tắt dần</text>\n      <line x1=\"270\" y1=\"190\" x2=\"470\" y2=\"190\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <line x1=\"280\" y1=\"200\" x2=\"280\" y2=\"40\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr6)\"/>\n      <path d=\"M 290,180 Q 340,170 370,60 Q 400,170 450,180\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <line x1=\"370\" y1=\"60\" x2=\"370\" y2=\"190\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <circle cx=\"370\" cy=\"60\" r=\"4\" fill=\"#fbbf24\"/>\n      <text x=\"355\" y=\"205\" fill=\"#fbbf24\" font-size=\"11\">f = f₀</text>\n      <text x=\"475\" y=\"195\" fill=\"#94a3b8\" font-size=\"11\">f<tspan baseline-shift=\"sub\" font-size=\"70%\">cb</tspan></text>\n      <text x=\"285\" y=\"45\" fill=\"#94a3b8\" font-size=\"11\">A<tspan baseline-shift=\"sub\" font-size=\"70%\">cb</tspan></text>\n      <text x=\"315\" y=\"220\" fill=\"#38bdf8\" font-size=\"12\">Đường cong cộng hưởng</text>\n    </svg>"},{"q":"Một thiết bị đóng cửa tự động sử dụng lò xo kéo và piston giảm xóc hoạt động dựa trên ứng dụng của:","opts":["Dao động tắt dần.","Dao động cưỡng bức.","Hiện tượng cộng hưởng cơ.","Chuyển động rơi tự do."],"ans":"A","exp":"• Piston chứa dầu tạo lực cản lớn làm cho dao động của cánh cửa bị tắt dần nhanh chóng, giúp cửa đóng êm ái mà không bị va đập lắc qua lắc lại.","svgGraph":null},{"q":"Hiện tượng cộng hưởng xảy ra trong dao động cưỡng bức khi:","opts":["Tần số của lực cưỡng bức bằng tần số riêng của hệ dao động.","Biên độ của lực cưỡng bức đạt giá trị cực đại.","Lực ma sát của môi trường triệt tiêu hoàn toàn.","Chu kì của lực cưỡng bức lớn gấp đôi chu kì riêng của hệ."],"ans":"A","exp":"• Khi tần số của ngoại lực tuần hoàn f bằng tần số riêng f₀ của hệ, biên độ dao động cưỡng bức đạt giá trị cực đại. Hiện tượng này gọi là hiện tượng cộng hưởng cơ.","svgGraph":null},{"q":"Xét các hiện tượng dao động trong đời sống và kĩ thuật, hãy xác định tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Biên độ của dao động cưỡng bức chỉ phụ thuộc vào biên độ của ngoại lực chứ không phụ thuộc vào tần số của ngoại lực.","Dao động của con lắc đồng hồ quả lắc là dao động duy trì vì sau mỗi chu kì được tiếp thêm năng lượng từ dây cót hoặc pin.","Khi xảy ra hiện tượng cộng hưởng, lực cản của môi trường càng nhỏ thì biên độ dao động cực đại càng lớn.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Đồng hồ quả lắc có cơ cấu tiếp năng lượng bổ sung đúng bằng lượng tiêu hao sau mỗi chu kì ⇒ dao động duy trì.<br>• <b>Ý b [Sai]:</b> Biên độ dao động cưỡng bức phụ thuộc cả vào biên độ ngoại lực, lực cản và độ chênh lệch giữa tần số ngoại lực và tần số riêng.<br>• <b>Ý c [Đúng]:</b> Lực cản càng nhỏ thì đỉnh cộng hưởng càng cao và nhọn.<br>• <b>Ý d [Sai]:</b> Cộng hưởng có nhiều ứng dụng có ích: hộp đàn ghi-ta làm âm thanh to vang, lò vi sóng, mạch thu sóng radio...","svgGraph":null},{"q":"Ghép các loại dao động cơ học ở Cột A với đặc điểm bản chất vật lí tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Dao động tự do ➔ Chịu tác dụng của ngoại lực biến thiên tuần hoàn, tần số dao động bằng tần số ngoại lực","Dao động tự do ➔ Biên độ và cơ năng giảm dần theo thời gian do ma sát và lực cản","Dao động tắt dần ➔ Chịu tác dụng của ngoại lực biến thiên tuần hoàn, tần số dao động bằng tần số ngoại lực","Dao động duy trì ➔ Biên độ và cơ năng giảm dần theo thời gian do ma sát và lực cản"],"ans":0,"exp":"• <b>1 - D:</b> Dao động tự do có chu kì/tần số chỉ do đặc tính của hệ quyết định.<br>• <b>2 - B:</b> Dao động tắt dần có A và W giảm dần.<br>• <b>3 - C:</b> Dao động duy trì bổ sung năng lượng sau mỗi chu kì, giữ tần số f₀.<br>• <b>4 - A:</b> Dao động cưỡng bức dao động theo tần số của ngoại lực tuần hoàn.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Dao động cưỡng bức là dao động dưới tác dụng của  [ ... ]  tuần hoàn. Khi tần số của ngoại lực bằng  [ ... ]  của hệ thì xảy ra hiện tượng  [ ... ] . Khi đó  [ ... ]  của dao động cưỡng bức đạt giá trị cực đại.\"</i>","opts":["ngoại lực — tần số riêng","không đổi","trọng lực — năng lượng","tần số riêng — ngoại lực"],"ans":0,"exp":"• Dao động cưỡng bức do ngoại lực tuần hoàn duy trì.<br>• Khi f = f₀ xảy ra hiện tượng cộng hưởng.<br>• Biên độ đạt cực đại khi cộng hưởng.","svgGraph":null},{"q":"Một con lắc lò xo có tần số dao động riêng f₀ = 10 Hz. Tác dụng vào con lắc một ngoại lực tuần hoàn có tần số f. Hiện tượng cộng hưởng xảy ra khi tần số f có giá trị bằng:","opts":["10 Hz.","5 Hz.","20 Hz.","15 Hz."],"ans":"A","exp":"• Điều kiện xảy ra cộng hưởng là tần số ngoại lực bằng tần số riêng: f = f₀ = 10 Hz.","svgGraph":null},{"q":"Bộ phận giảm xóc (phuộc nhún) ở bánh xe máy và ô tô hoạt động dựa trên nguyên tắc của loại dao động nào?","opts":["Dao động tắt dần.","Dao động cưỡng bức.","Dao động điều hoà tự do.","Hiện tượng cộng hưởng."],"ans":"A","exp":"• Khi xe đi qua đoạn đường gồ ghề, lò xo bị nén và có xu hướng dao động liên tục. Bộ giảm xóc tạo lực cản nhớt làm dao động tắt dần nhanh chóng, giúp xe nhanh ổn định thăng bằng.","svgGraph":null},{"q":"Một thanh niên ngồi trên xích đu. Người này đưa chân đẩy nhịp nhàng xuống đất theo từng chu kì để xích đu tiếp tục lắc. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu người này đẩy chân với tần số gấp 10 lần tần số riêng của xích đu thì biên độ xích đu sẽ tăng cực lớn.","Chuyển động của xích đu lúc này là một ví dụ thực tế về dao động duy trì.","Nếu không tiếp tục đẩy chân, dao động của xích đu sẽ tắt dần do ma sát ở trục quay và lực cản không khí.","Tần số dao động của xích đu khi đẩy chân đúng nhịp bằng tần số riêng của hệ xích đu."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tự cung cấp năng lượng sau mỗi chu kì là dao động duy trì.<br>• <b>Ý b [Đúng]:</b> Ma sát và lực cản không khí làm tiêu hao cơ năng khiến dao động tắt dần.<br>• <b>Ý c [Đúng]:</b> Dao động duy trì có tần số bằng tần số riêng f₀.<br>• <b>Ý d [Sai]:</b> Tần số ngoại lực lệch rất xa f₀ nên biên độ sẽ rất nhỏ, không xảy ra cộng hưởng.","svgGraph":null},{"q":"Đoàn quân đi đều bước qua một cây cầu treo có thể làm cầu rung lắc dữ dội và có nguy cơ bị sập là do:","opts":["Tần số bước chân trùng với tần số dao động riêng của cầu gây ra hiện tượng cộng hưởng.","Trọng lượng của đoàn quân quá nặng vượt tải trọng tĩnh của cầu.","Gió thổi mạnh làm thay đổi biên độ dao động riêng của cầu.","Chất lượng vật liệu làm cầu bị giảm dần theo thời gian."],"ans":"A","exp":"• Tần số bước chân đều đặn của đoàn quân đóng vai trò là ngoại lực tuần hoàn. Khi tần số này trùng với tần số riêng của cầu, hiện tượng cộng hưởng xảy ra làm biên độ rung lắc tăng vọt dẫn tới nguy cơ sập cầu.","svgGraph":null}],"7":[{"q":"Một con lắc lò xo dao động điều hoà với cơ năng W = 0,2 J. Tại vị trí có động năng bằng 3 lần thế năng (W<sub>đ</sub> = 3W<sub>t</sub>), thế năng của con lắc có giá trị bằng:","opts":["0,05 J.","0,15 J.","0,067 J.","0,1 J."],"ans":"A","exp":"• Ta có: W = W<sub>đ</sub> + W<sub>t</sub> = 3W<sub>t</sub> + W<sub>t</sub> = 4W<sub>t</sub>.<br>• Suy ra thế năng: W<sub>t</sub> = W / 4 = 0,2 / 4 = 0,05 J.<br>• Động năng lúc này: W<sub>đ</sub> = 3 · 0,05 = 0,15 J.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà với biên độ A = 10 cm. Vị trí có thế năng bằng 3 lần động năng (W<sub>t</sub> = 3W<sub>đ</sub>) cách vị trí cân bằng một khoảng là:","opts":["5√3 cm.","5 cm.","5√2 cm.","2,5 cm."],"ans":"A","exp":"• Ta có: W<sub>t</sub> = 3W<sub>đ</sub> ⇒ W<sub>đ</sub> = W<sub>t</sub> / 3.<br>• Cơ năng: W = W<sub>đ</sub> + W<sub>t</sub> = W<sub>t</sub>/3 + W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span>W<sub>t</sub> ⇒ W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>W.<br>• Do W<sub>t</sub> ∝ x² và W ∝ A² nên: x² = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>A² ⇒ |x| = A·<span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 10 · <span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span> = 5√3 cm.","svgGraph":null},{"q":"Một vật có khối lượng m = 400 g dao động điều hoà có đồ thị thế năng theo thời gian là một đường cong hình sin biến thiên từ 0 đến 0,5 J với chu kì biến thiên là 0,25 s. Chu kì dao động của vật là:","opts":["0,5 s.","0,25 s.","0,125 s.","1,0 s."],"ans":"A","exp":"• Chu kì biến thiên của thế năng là T' = T/2.<br>• Suy ra chu kì dao động của vật: T = 2·T' = 2 · 0,25 = 0,5 s.","svgGraph":null},{"q":"Một con lắc lò xo gồm lò xo có độ cứng k = 50 N/m và vật nhỏ khối lượng m = 200 g dao động điều hoà trên trục Ox nằm ngang với biên độ A = 6 cm. Xét tính Đúng / Sai của các mệnh đề sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Cơ năng toàn phần của con lắc là W = 0,09 J.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> W = 0,5·k·A² = 0,5 · 50 · (0,06)² = 0,09 J (90 mJ).<br>• <b>Ý b [Đúng]:</b> ω = √(k/m) = √(50/0,2) = √250 = 5√10 rad/s ⇒ v<sub>max</sub> = ωA = 5√10 · 6 = 30√10 cm/s.<br>• <b>Ý c [Đúng]:</b> x = 3 cm = A/2 ⇒ W<sub>t</sub> = W/4 ⇒ W<sub>đ</sub> = 3W/4 > W<sub>t</sub>.<br>• <b>Ý d [Đúng]:</b> Tại biên W<sub>t</sub> = W và W<sub>đ</sub> = 0; tại VCB W<sub>t</sub> = 0 và W<sub>đ</sub> = W.","svgGraph":null},{"q":"Ghép mối quan hệ giữa động năng và thế năng ở Cột A với toạ độ li độ x tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Động năng bằng thế năng (W<sub>đ</sub> = W<sub>t</sub>) ➔ Li độ |x| = A/3","Động năng bằng thế năng (W<sub>đ</sub> = W<sub>t</sub>) ➔ Li độ |x| = A/2","Động năng bằng 3 lần thế năng (W<sub>đ</sub> = 3W<sub>t</sub>) ➔ Li độ |x| = A/3","Thế năng bằng 3 lần động năng (W<sub>t</sub> = 3W<sub>đ</sub>) ➔ Li độ |x| = A/2"],"ans":0,"exp":"• <b>Công thức tổng quát:</b> W<sub>đ</sub> = n·W<sub>t</sub> ⇒ |x| = A / √(n+1).<br>• <b>1 - D:</b> n = 1 ⇒ |x| = A/√2.<br>• <b>2 - B:</b> n = 3 ⇒ |x| = A/√4 = A/2.<br>• <b>3 - C:</b> W<sub>t</sub> = 3W<sub>đ</sub> ⇒ n = 1/3 ⇒ |x| = A / √(4/3) = A√3/2.<br>• <b>4 - A:</b> n = 8 ⇒ |x| = A/√9 = A/3.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi vật dao động điều hoà có li độ x = A/2 thì thế năng chiếm  [ ... ]  cơ năng và động năng chiếm  [ ... ]  cơ năng. Tại vị trí này, tốc độ của vật bằng  [ ... ]  tốc độ cực đại. Tần số góc của dao động năng lượng bằng  [ ... ]  tần số góc của li độ.\"</i>","opts":["25% — 75%","không đổi","1/2 — 4 lần","75% — 25%"],"ans":0,"exp":"• x = A/2 ⇒ W<sub>t</sub> = (1/4)W = 25% cơ năng.<br>• Động năng W<sub>đ</sub> = 75% cơ năng.<br>• v = v<sub>max</sub> · √3/2.<br>• ω' = 2ω (gấp 2 lần).","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có cơ năng W = 36 mJ. Khi chất điểm có thế năng W<sub>t</sub> = 9 mJ thì tỉ số giữa động năng và thế năng là:","opts":["3.","4.","1/3.","1/4."],"ans":"A","exp":"• Động năng: W<sub>đ</sub> = W - W<sub>t</sub> = 36 - 9 = 27 mJ.<br>• Tỉ số: W<sub>đ</sub> / W<sub>t</sub> = 27 / 9 = 3.","svgGraph":null},{"q":"Một con lắc lò xo dao động điều hoà với biên độ A. Khi vật đi từ vị trí cân bằng x = 0 đến vị trí có li độ x = A/√2 thì tỉ lệ thế năng tăng thêm so với cơ năng là:","opts":["50%.","25%.","70,7%.","100%."],"ans":"A","exp":"• Tại x = 0 thì W<sub>t</sub> = 0.<br>• Tại x = A/√2 thì W<sub>t</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mω²(A/√2)² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>mω²A² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>W = 50%W.<br>• Như vậy thế năng đã tăng thêm 50% cơ năng.","svgGraph":null},{"q":"Một chất điểm dao động điều hoà có cơ năng W = 0,18 J và biên độ A = 6 cm. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Thế năng của vật đạt cực đại khi vật có gia tốc bằng 0.","Độ cứng tương đương của hệ dao động là k = 100 N/m.","Khi vật đi qua vị trí có li độ x = 3√2 cm thì động năng của vật là 0,09 J.","Trong một chu kì dao động, có 4 thời điểm động năng bằng thế năng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> W = 0,5 k A² ⇒ k = 2W / A² = 2 · 0,18 / (0,06)² = 0,36 / 0,0036 = 100 N/m.<br>• <b>Ý b [Đúng]:</b> x = 3√2 cm = A/√2 ⇒ W<sub>đ</sub> = W<sub>t</sub> = W/2 = 0,18/2 = 0,09 J.<br>• <b>Ý c [Sai]:</b> Gia tốc bằng 0 tại VCB x = 0, lúc đó thế năng bằng 0 (triệt tiêu), không phải cực đại.<br>• <b>Ý d [Đúng]:</b> Vị trí x = ±A/√2 có 4 lần qua trong 1 chu kì, tại đó W<sub>đ</sub> = W<sub>t</sub>.","svgGraph":null},{"q":"Một con lắc lò xo dao động điều hoà với cơ năng W. Khi tốc độ của vật bằng một nửa tốc độ cực đại (v = v<sub>max</sub>/2) thì thế năng của con lắc bằng:","opts":["<span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>W.","<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>W.","<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>W.","<span class=\"fraction\"><span class=\"numerator\">√3</span><span class=\"denominator\">2</span></span>W."],"ans":"A","exp":"• Khi v = v<sub>max</sub>/2 ⇒ W<sub>đ</sub> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>mv² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>m(v<sub>max</sub>/2)² = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>W.<br>• Suy ra thế năng: W<sub>t</sub> = W - W<sub>đ</sub> = W - <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>W = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">4</span></span>W.","svgGraph":null}],"8":[{"q":"Sóng cơ học là:","opts":["Quá trình lan truyền dao động cơ học và năng lượng trong một môi trường vật chất theo thời gian.","Sự chuyển động tịnh tiến của các phần tử môi trường từ nguồn sóng ra xa.","Quá trình lan truyền của các hạt vật chất chuyển động với vận tốc không đổi.","Sự biến dạng vĩnh viễn của môi trường đàn hồi khi có ngoại lực tác dụng."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Sóng cơ là dao động cơ lan truyền trong môi trường vật chất.<br>• Khi sóng truyền qua, các phần tử môi trường chỉ dao động tại chỗ quanh vị trí cân bằng của chúng, không chuyển dời theo sóng; chỉ có pha dao động và năng lượng sóng được truyền đi xa.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr8\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <line x1=\"40\" y1=\"120\" x2=\"470\" y2=\"120\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr8)\"/>\n      <line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr8)\"/>\n      <text x=\"475\" y=\"125\" fill=\"#94a3b8\" font-size=\"12\">x (m)</text><text x=\"65\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">u (mm)</text>\n      <!-- Sinusoidal wave profile -->\n      <path d=\"M 60,120 Q 110,40 160,120 T 260,120 T 360,120 T 460,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Wavelength lambda line -->\n      <line x1=\"110\" y1=\"50\" x2=\"310\" y2=\"50\" stroke=\"#fbbf24\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/>\n      <circle cx=\"110\" cy=\"50\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"310\" cy=\"50\" r=\"4\" fill=\"#fbbf24\"/>\n      <text x=\"195\" y=\"42\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">Bước sóng λ</text>\n      <!-- Particles vibrating vertically -->\n      <circle cx=\"210\" cy=\"190\" r=\"5\" fill=\"#f43f5e\"/>\n      <line x1=\"210\" y1=\"160\" x2=\"210\" y2=\"210\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arr8)\"/>\n      <text x=\"220\" y=\"200\" fill=\"#f43f5e\" font-size=\"11\">Phần tử dao động tại chỗ</text>\n      <!-- Wave propagation direction -->\n      <line x1=\"330\" y1=\"90\" x2=\"400\" y2=\"90\" stroke=\"#34d399\" stroke-width=\"2.5\" marker-end=\"url(#arr8)\"/>\n      <text x=\"340\" y=\"80\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">v (truyền sóng)</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Hình ảnh sóng hình sin lan truyền trong không gian</text>\n    </svg>"},{"q":"Bước sóng λ là:","opts":["Quãng đường mà sóng truyền được trong một chu kì dao động.","Khoảng cách giữa hai điểm bất kì trên cùng một phương truyền sóng.","Quãng đường sóng truyền được trong thời gian một giây.","Khoảng cách giữa một đỉnh sóng và một hõm sóng gần nhau nhất."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Bước sóng λ là quãng đường sóng truyền đi trong 1 chu kì: λ = v·T = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span>.<br>• Bước sóng cũng chính là khoảng cách ngắn nhất giữa hai điểm trên cùng một phương truyền sóng dao động cùng pha.","svgGraph":null},{"q":"Một sóng cơ hình sin truyền trong một môi trường với tốc độ v = 20 m/s và tần số f = 50 Hz. Bước sóng của sóng này là:","opts":["0,4 m.","2,5 m.","1000 m.","0,02 m."],"ans":"A","exp":"• <b>Công thức:</b> λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span><br>• <b>Thay số:</b> λ = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">50</span></span> = 0,4 m (40 cm).","svgGraph":null},{"q":"Khi khảo sát quá trình lan truyền của một sóng cơ trên mặt nước, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Các phần tử nước trên bề mặt chuyển động tịnh tiến cùng hướng với hướng truyền của sóng.","Tốc độ truyền sóng chỉ phụ thuộc vào bản chất và nhiệt độ của môi trường truyền sóng, không phụ thuộc vào tần số sóng.","Khoảng cách giữa hai đỉnh sóng liên tiếp trên phương truyền sóng đúng bằng một bước sóng λ.","Tần số dao động của các phần tử môi trường khi sóng truyền qua đúng bằng tần số của nguồn phát sóng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tốc độ truyền sóng v do môi trường quyết định.<br>• <b>Ý b [Sai]:</b> Các phần tử chỉ dao động tại chỗ quanh VCB, không trôi đi theo sóng.<br>• <b>Ý c [Đúng]:</b> Hai đỉnh sóng liên tiếp cùng pha nên cách nhau đúng 1 bước sóng λ.<br>• <b>Ý d [Đúng]:</b> Sóng truyền dao động cưỡng bức nên tần số của các phần tử bằng tần số nguồn f.","svgGraph":null},{"q":"Ghép các đại lượng đặc trưng của sóng cơ ở Cột A với biểu thức hoặc định nghĩa tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Bước sóng λ ➔ Độ dịch chuyển lớn nhất của phần tử môi trường khỏi vị trí cân bằng","Bước sóng λ ➔ Tốc độ lan truyền dao động trong môi trường: v = λ/T = λ·f","Tốc độ truyền sóng v ➔ Độ dịch chuyển lớn nhất của phần tử môi trường khỏi vị trí cân bằng","Chu kì sóng T ➔ Tốc độ lan truyền dao động trong môi trường: v = λ/T = λ·f"],"ans":0,"exp":"• <b>1 - C:</b> Bước sóng λ = v·T.<br>• <b>2 - B:</b> Tốc độ truyền sóng v = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">T</span></span> = λ·f.<br>• <b>3 - D:</b> Chu kì sóng T bằng chu kì dao động của nguồn.<br>• <b>4 - A:</b> Biên độ sóng A là biên độ dao động tại chỗ.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Sóng cơ là sự lan truyền  [ ... ]  trong môi trường vật chất. Bước sóng là quãng đường sóng truyền trong một  [ ... ] . Hai điểm trên cùng phương truyền sóng cách nhau một số nguyên lần bước sóng thì dao động  [ ... ] . Hai điểm cách nhau một số bán nguyên lần bước sóng thì dao động  [ ... ] .\"</i>","opts":["dao động — chu kì","không đổi","tần số — vuông pha","chu kì — dao động"],"ans":0,"exp":"• Sóng truyền dao động và năng lượng.<br>• λ là quãng đường trong 1 chu kì T.<br>• d = kλ: cùng pha.<br>• d = (k + 0,5)λ: ngược pha.","svgGraph":null},{"q":"Một người quan sát thấy một chiếc phao trên mặt biển nhấp nhô lên xuống tại chỗ 10 lần trong khoảng thời gian 18 giây. Khoảng cách giữa hai đỉnh sóng lân cận là 3 m. Tốc độ truyền sóng trên mặt biển là:","opts":["1,5 m/s.","3,0 m/s.","1,67 m/s.","0,6 m/s."],"ans":"A","exp":"• Phao nhô lên 10 lần ứng với 9 chu kì dao động: 9T = 18 s ⇒ T = 2 s.<br>• Khoảng cách giữa 2 đỉnh lân cận là bước sóng: λ = 3 m.<br>• Tốc độ truyền sóng: v = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> = 1,5 m/s.","svgGraph":null},{"q":"Một sóng cơ truyền dọc theo trục Ox có phương trình u = 5·cos(20πt - 4πx) (mm), trong đó x tính bằng mét, t tính bằng giây. Tốc độ truyền sóng là:","opts":["5 m/s.","20 m/s.","4 m/s.","80 m/s."],"ans":"A","exp":"• Phương trình sóng chuẩn: u = A·cos(ωt - <span class=\"fraction\"><span class=\"numerator\">2πx</span><span class=\"denominator\">λ</span></span>).<br>• Đồng nhất hệ số: ω = 20π rad/s và <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">λ</span></span> = 4π ⇒ λ = 0,5 m.<br>• Tần số: f = ω/(2π) = 10 Hz.<br>• Tốc độ truyền sóng: v = λ·f = 0,5 · 10 = 5 m/s.","svgGraph":null},{"q":"Một nguồn phát sóng cơ dao động với tần số f = 100 Hz truyền vào hai môi trường khác nhau: không khí (v₁ = 340 m/s) và nước (v₂ = 1500 m/s). Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Bước sóng trong nước là λ₂ = 0,15 m.","Khi truyền từ không khí vào nước, tần số của sóng vẫn giữ nguyên không đổi f = 100 Hz.","Bước sóng của sóng âm trong nước lớn hơn bước sóng của sóng âm trong không khí.","Bước sóng trong không khí là λ₁ = 3,4 m."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tần số sóng không đổi khi truyền qua các môi trường khác nhau.<br>• <b>Ý b [Đúng]:</b> Vì v₂ > v₁ nên λ₂ = v₂/f > λ₁ = v₁/f.<br>• <b>Ý c [Đúng]:</b> λ₁ = 340 / 100 = 3,4 m.<br>• <b>Ý d [Sai]:</b> λ₂ = 1500 / 100 = 15 m (không phải 0,15 m).","svgGraph":null},{"q":"Độ lệch pha giữa hai điểm M và N nằm trên cùng một phương truyền sóng cách nhau một khoảng d được tính bởi công thức:","opts":["Δφ = <span class=\"fraction\"><span class=\"numerator\">2πd</span><span class=\"denominator\">λ</span></span>.","Δφ = <span class=\"fraction\"><span class=\"numerator\">πd</span><span class=\"denominator\">λ</span></span>.","Δφ = <span class=\"fraction\"><span class=\"numerator\">2πλ</span><span class=\"denominator\">d</span></span>.","Δφ = <span class=\"fraction\"><span class=\"numerator\">v·d</span><span class=\"denominator\">λ</span></span>."],"ans":"A","exp":"• Thời gian sóng truyền từ M đến N là Δt = d/v.<br>• Độ lệch pha tương ứng: Δφ = ω·Δt = <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">T</span></span> · <span class=\"fraction\"><span class=\"numerator\">d</span><span class=\"denominator\">v</span></span> = <span class=\"fraction\"><span class=\"numerator\">2πd</span><span class=\"denominator\">λ</span></span>.","svgGraph":null}],"9":[{"q":"Sóng ngang là sóng trong đó các phần tử môi trường có phương dao động:","opts":["Vuông góc với phương truyền sóng.","Trùng với phương truyền sóng.","Song song với phương truyền sóng.","Hợp với phương truyền sóng một góc 45°."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b><br>- Sóng ngang: Phương dao động vuông góc với phương truyền sóng (ví dụ sóng trên mặt nước, sóng trên dây đàn).<br>- Sóng dọc: Phương dao động trùng với phương truyền sóng (ví dụ sóng âm trong không khí, sóng nén dãn của lò xo).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr9\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Sóng ngang -->\n      <text x=\"50\" y=\"35\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">SÓNG NGANG (Transverse wave)</text>\n      <line x1=\"40\" y1=\"80\" x2=\"220\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <text x=\"225\" y=\"85\" fill=\"#64748b\" font-size=\"11\">Phương truyền</text>\n      <!-- Vertical vibration -->\n      <line x1=\"120\" y1=\"50\" x2=\"120\" y2=\"110\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n      <circle cx=\"120\" cy=\"80\" r=\"5\" fill=\"#f43f5e\"/>\n      <text x=\"130\" y=\"65\" fill=\"#f43f5e\" font-size=\"11\">Dao động ⊥</text>\n      <!-- Sóng dọc -->\n      <text x=\"280\" y=\"35\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">SÓNG DỌC (Longitudinal wave)</text>\n      <line x1=\"270\" y1=\"80\" x2=\"450\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr9)\"/>\n      <text x=\"455\" y=\"85\" fill=\"#64748b\" font-size=\"11\">Phương truyền</text>\n      <!-- Horizontal vibration -->\n      <line x1=\"330\" y1=\"80\" x2=\"390\" y2=\"80\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n      <circle cx=\"360\" cy=\"80\" r=\"5\" fill=\"#fbbf24\"/>\n      <text x=\"330\" y=\"105\" fill=\"#fbbf24\" font-size=\"11\">Dao động // (nén - giãn)</text>\n      <!-- Bottom summary -->\n      <rect x=\"50\" y=\"140\" width=\"400\" height=\"70\" fill=\"#1e293b\" rx=\"6\"/>\n      <text x=\"70\" y=\"165\" fill=\"#38bdf8\" font-size=\"12\">• Sóng ngang truyền trong chất rắn và bề mặt chất lỏng.</text>\n      <text x=\"70\" y=\"195\" fill=\"#34d399\" font-size=\"12\">• Sóng dọc truyền được trong cả chất rắn, chất lỏng và chất khí.</text>\n    </svg>"},{"q":"Sóng dọc là loại sóng có thể truyền được trong các môi trường nào sau đây?","opts":["Chất rắn, chất lỏng và chất khí.","Chỉ truyền trong chất rắn.","Chỉ truyền trong chất khí và chân không.","Chỉ truyền trên bề mặt chất lỏng."],"ans":"A","exp":"• Sóng dọc xuất hiện khi có lực đàn hồi chống lại sự nén - giãn thể tích, do đó sóng dọc truyền được trong cả 3 trạng thái của vật chất: Rắn, Lỏng và Khí (sóng cơ không truyền được trong chân không).","svgGraph":null},{"q":"Cường độ sóng I tại một điểm là năng lượng sóng truyền qua một đơn vị diện tích đặt vuông góc với phương truyền sóng trong một đơn vị thời gian. Đơn vị của cường độ sóng trong hệ SI là:","opts":["W/m².","J/s.","N/m.","W·m²."],"ans":"A","exp":"• <b>Công thức:</b> I = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">S</span></span> = <span class=\"fraction\"><span class=\"numerator\">E</span><span class=\"denominator\">S·t</span></span>.<br>• Trong đó công suất P tính bằng Oát (W), diện tích S tính bằng m², do đó cường độ sóng I có đơn vị là W/m² (Oát trên mét vuông).","svgGraph":null},{"q":"Xét các đặc tính truyền sóng và sự truyền năng lượng của sóng cơ, hãy xác định tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Sóng ngang có thể truyền được trong lòng chất khí và trong chân không.","Sóng âm truyền trong không khí là sóng dọc.","Khi sóng truyền từ nguồn điểm ra không gian 3 chiều đồng tính, cường độ sóng tỉ lệ nghịch với bình phương khoảng cách tới nguồn.","Năng lượng của sóng tỉ lệ thuận với bình phương biên độ và bình phương tần số của sóng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Sóng âm trong không khí lan truyền nhờ các lớp không khí nén - giãn liên tiếp theo phương truyền ⇒ sóng dọc.<br>• <b>Ý b [Đúng]:</b> Diện tích mặt cầu S = 4πr² nên I = P/(4πr²) ∝ 1/r².<br>• <b>Ý c [Sai]:</b> Sóng cơ không truyền được trong chân không; sóng ngang không truyền được trong lòng chất khí.<br>• <b>Ý d [Đúng]:</b> Năng lượng sóng tỉ lệ với A² và f² (E ∝ f²A²).","svgGraph":null},{"q":"Ghép loại sóng ở Cột A với môi trường truyền sóng đặc trưng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Sóng ngang cơ học ➔ Truyền được trong chân không và các môi trường điện môi trong suốt","Sóng ngang cơ học ➔ Truyền được trong cả chất rắn, chất lỏng và chất khí","Sóng dọc cơ học ➔ Truyền được trong chân không và các môi trường điện môi trong suốt","Sóng điện từ ➔ Truyền được trong cả chất rắn, chất lỏng và chất khí"],"ans":0,"exp":"• <b>1 - C:</b> Sóng ngang cơ học truyền trong chất rắn và mặt thoáng chất lỏng.<br>• <b>2 - B:</b> Sóng dọc truyền trong rắn, lỏng, khí.<br>• <b>3 - A:</b> Sóng điện từ truyền được trong chân không.<br>• <b>4 - D:</b> Sóng mặt nước là sóng ngang kết hợp quỹ đạo elip.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Quá trình truyền sóng là quá trình truyền  [ ... ]  từ phần tử này sang phần tử khác của môi trường. Càng ra xa nguồn, biên độ sóng thường giảm dần do sự  [ ... ]  không gian và sự  [ ... ]  năng lượng của môi trường. Cường độ sóng đo bằng công suất sóng truyền qua một đơn vị  [ ... ]  vuông góc với hướng truyền.\"</i>","opts":["năng lượng — phân tán","không đổi","gia tốc — vận tốc","phân tán — năng lượng"],"ans":0,"exp":"• Truyền sóng là truyền năng lượng và pha.<br>• Biên độ giảm do năng lượng phân tán trên diện tích lớn hơn và bị môi trường hấp thụ toả nhiệt.<br>• I = P/S (công suất trên đơn vị diện tích).","svgGraph":null},{"q":"Một nguồn âm đẳng hướng phát sóng âm trong không gian. Tại điểm M cách nguồn 2 m, cường độ âm là I. Tại điểm N cách nguồn 4 m, cường độ âm là:","opts":["I/4.","I/2.","2I.","4I."],"ans":"A","exp":"• Cường độ âm của nguồn đẳng hướng: I = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">4πr²</span></span> ∝ <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">r²</span></span>.<br>• Khi r tăng từ 2 m lên 4 m (gấp đôi) thì r² tăng 4 lần ⇒ cường độ âm giảm 4 lần: I<sub>N</sub> = I / 4.","svgGraph":null},{"q":"Hiện tượng nào sau đây chứng tỏ sóng cơ học mang năng lượng?","opts":["Sóng biển đánh làm vỡ bờ kè đá và cuốn trôi tàu thuyền.","Nước biển có vị mặn do hoà tan nhiều muối khoáng.","Mặt hồ phẳng lặng không có gợn sóng khi trời lặng gió.","Ánh sáng mặt trời chiếu sáng bầu khí quyển."],"ans":"A","exp":"• Sóng biển làm vỡ kè đá và di chuyển tàu thuyền chứng tỏ sóng cơ mang năng lượng và sinh công cơ học tác dụng lên các vật cản.","svgGraph":null},{"q":"Khi so sánh sóng ngang và sóng dọc cơ học, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Sóng ngang luôn luôn truyền nhanh hơn sóng dọc trong cùng một môi trường vật chất.","Cả sóng ngang và sóng dọc đều không truyền được trong môi trường chân không.","Vận tốc truyền sóng âm trong chất rắn nói chung lớn hơn trong chất lỏng và trong chất khí.","Sóng âm có thể truyền qua bức tường gạch kín vì nó truyền được trong chất rắn."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Sóng cơ cần môi trường vật chất đàn hồi, không truyền trong chân không.<br>• <b>Ý b [Đúng]:</b> Mật độ và lực liên kết phân tử: v<sub>r</sub>ắn > v<sub>l</sub>ỏng > v<sub>kh</sub>í.<br>• <b>Ý c [Đúng]:</b> Âm thanh truyền qua tường gạch (chất rắn) làm rung tường và phát ra phòng bên cạnh.<br>• <b>Ý d [Sai]:</b> Trong cùng một môi trường rắn, sóng dọc (sóng P) thường truyền nhanh hơn sóng ngang (sóng S).","svgGraph":null},{"q":"Một nguồn phát sóng cơ có công suất P = 12,56 W phát đều ra mọi hướng trong môi trường không hấp thụ sóng. Lấy π ≈ 3,14. Cường độ sóng tại điểm cách nguồn 1 m là:","opts":["1,0 W/m².","3,14 W/m².","0,5 W/m².","2,0 W/m²."],"ans":"A","exp":"• <b>Công thức:</b> I = <span class=\"fraction\"><span class=\"numerator\">P</span><span class=\"denominator\">4πr²</span></span><br>• <b>Thay số:</b> I = <span class=\"fraction\"><span class=\"numerator\">12,56</span><span class=\"denominator\">4 · 3,14 · 1²</span></span> = <span class=\"fraction\"><span class=\"numerator\">12,56</span><span class=\"denominator\">12,56</span></span> = 1,0 W/m².","svgGraph":null}],"10":[{"q":"Trong thí nghiệm đo tần số của sóng âm bằng dao động kí điện tử, tín hiệu âm thanh thu từ micrô được hiển thị trên màn hình dưới dạng:","opts":["Đường cong hình sin biểu diễn hiệu điện thế biến thiên theo thời gian.","Một đoạn thẳng nằm ngang song song với trục thời gian.","Một đường thẳng dốc đứng có độ dốc không đổi.","Các vạch sáng phân kì không có chu kì xác định."],"ans":"A","exp":"• Micrô chuyển đổi dao động âm (áp suất không khí) thành tín hiệu điện dao động cùng tần số.<br>• Dao động kí điện tử vẽ đồ thị hiệu điện thế u theo thời gian t dưới dạng đường cong hình sin.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr10\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Oscilloscope screen frame -->\n      <rect x=\"70\" y=\"25\" width=\"360\" height=\"190\" fill=\"#031a14\" stroke=\"#059669\" stroke-width=\"3\" rx=\"10\"/>\n      <!-- Oscilloscope grid lines -->\n      <line x1=\"70\" y1=\"120\" x2=\"430\" y2=\"120\" stroke=\"#047857\" stroke-width=\"1.5\"/>\n      <line x1=\"250\" y1=\"25\" x2=\"250\" y2=\"215\" stroke=\"#047857\" stroke-width=\"1.5\"/>\n      <line x1=\"130\" y1=\"25\" x2=\"130\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <line x1=\"190\" y1=\"25\" x2=\"190\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <line x1=\"370\" y1=\"25\" x2=\"370\" y2=\"215\" stroke=\"#065f46\" stroke-width=\"0.8\" stroke-dasharray=\"2,2\"/>\n      <!-- Sine wave trace in neon green -->\n      <path d=\"M 70,120 Q 100,50 130,120 T 190,120 T 250,120 T 310,120 T 370,120 T 430,120\" fill=\"none\" stroke=\"#10b981\" stroke-width=\"3\"/>\n      <!-- Measure 1 period T -->\n      <line x1=\"100\" y1=\"45\" x2=\"220\" y2=\"45\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"100\" cy=\"45\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"220\" cy=\"45\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"140\" y=\"40\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Chu kì T (n ô x TIME/DIV)</text>\n      <text x=\"85\" y=\"205\" fill=\"#34d399\" font-size=\"11\">Màn hình hiển thị dao động kí điện tử (Oscilloscope)</text>\n    </svg>"},{"q":"Trên màn hình dao động kí, núm xoay TIME/DIV đang đặt ở mức 0,5 ms/div (0,5 mili giây trên một ô chia). Một chu kì dao động của sóng âm chiếm đúng 4 ô chia ngang. Tần số của sóng âm là:","opts":["500 Hz.","250 Hz.","2000 Hz.","1000 Hz."],"ans":"A","exp":"• <b>Bước 1: Tính chu kì T:</b><br>T = (số ô) · (giá trị mỗi ô) = 4 · 0,5 ms = 2 ms = 2·10⁻³ s.<br>• <b>Bước 2: Tính tần số f:</b><br>f = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">T</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2·10⁻³</span></span> = 500 Hz.","svgGraph":null},{"q":"Dụng cụ nào sau đây có chức năng biến đổi dao động cơ học của sóng âm thành dao động điện từ có cùng tần số?","opts":["Micrô (Microphone).","Loa điện động (Speaker).","Máy phát tần số âm.","Bộ khuếch đại tín hiệu điện."],"ans":"A","exp":"• Micrô là cảm biến âm thanh biến đổi dao động áp suất cơ học của không khí thành tín hiệu hiệu điện thế xoay chiều cùng quy luật tần số để đưa vào dao động kí.","svgGraph":null},{"q":"Trong bài thực hành đo tần số sóng âm, nhóm học sinh sử dụng âm thoa chuẩn ghi nhãn 440 Hz để kiểm chứng dao động kí. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu điều chỉnh núm xoay TIME/DIV sang mức nhỏ hơn thì số lượng chu kì sóng hiển thị trên màn hình sẽ tăng lên.","Chu kì dao động lí thuyết của âm thoa này là T ≈ 2,27 ms.","Tần số âm 440 Hz thuộc dải tần số sóng âm mà tai người bình thường có thể nghe được.","Sai số của phép đo tần số sóng âm bằng dao động kí phụ thuộc vào độ chính xác khi đọc số vạch trên màn hình."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> T = 1/440 ≈ 0,00227 s = 2,27 ms.<br>• <b>Ý b [Sai]:</b> TIME/DIV nhỏ hơn nghĩa là mỗi ô tương ứng thời gian ngắn hơn ⇒ toàn bộ màn hình quét thời gian ngắn hơn ⇒ số chu kì hiển thị sẽ ít đi.<br>• <b>Ý c [Đúng]:</b> Âm nghe được nằm trong dải 16 Hz - 20000 Hz, 440 Hz là nốt La chuẩn.<br>• <b>Ý d [Đúng]:</b> Sai số đọc số ô (độ chia nhỏ nhất) là nguồn sai số dụng cụ chính.","svgGraph":null},{"q":"Ghép các thiết bị trong bộ thí nghiệm đo tần số sóng âm ở Cột A với chức năng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Dao động kí điện tử (Oscilloscope) ➔ Điều chỉnh thang đo thời gian cho mỗi ô chia ngang trên màn hình","Dao động kí điện tử (Oscilloscope) ➔ Hiển thị đồ thị dạng sóng điện áp theo thời gian","Nguồn phát âm (loa / âm thoa) ➔ Điều chỉnh thang đo thời gian cho mỗi ô chia ngang trên màn hình","Micrô cảm biến ➔ Hiển thị đồ thị dạng sóng điện áp theo thời gian"],"ans":0,"exp":"• <b>1 - B:</b> Dao động kí hiển thị đồ thị u(t).<br>• <b>2 - D:</b> Nguồn âm phát sóng âm vào môi trường.<br>• <b>3 - C:</b> Micrô thu âm đổi thành điện áp.<br>• <b>4 - A:</b> TIME/DIV điều chỉnh tỉ lệ thời gian mỗi ô ngang.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Để đo tần số sóng âm, ta nối micrô vào kênh đầu vào của  [ ... ] . Đặt nguồn âm trước micrô rồi chỉnh núm  [ ... ]  để đồ thị sóng đứng yên và quan sát rõ. Đếm số ô ngang mà một  [ ... ]  chiếm dụng rồi nhân với giá trị của một ô để tính chu kì T. Tần số được xác định qua công thức  [ ... ] .\"</i>","opts":["dao động kí — TIME/DIV","không đổi","bước sóng — f = v/λ","TIME/DIV — dao động kí"],"ans":0,"exp":"• Dùng dao động kí để hiện sóng.<br>• Chỉnh TIME/DIV để sóng đứng yên và vừa vặn.<br>• Đếm số ô cho 1 chu kì T.<br>• Tính f = 1/T.","svgGraph":null},{"q":"Khi đo tần số một nốt nhạc phát ra từ cây đàn ghi-ta, dao động kí hiển thị một chu kì dài 4 ô với thang đo 0,25 ms/div. Tần số của nốt nhạc này là:","opts":["1000 Hz.","500 Hz.","250 Hz.","2000 Hz."],"ans":"A","exp":"• T = 4 · 0,25 ms = 1,0 ms = 10⁻³ s.<br>• f = 1/T = 1/10⁻³ = 1000 Hz.","svgGraph":null},{"q":"Đơn vị đo tần số Héc (Hz) tương đương với đơn vị cơ bản nào sau đây?","opts":["s⁻¹ (1/giây).","s (giây).","m/s.","rad/s."],"ans":"A","exp":"• f = 1/T nên 1 Hz = 1 s⁻¹ (số lần dao động trong một giây).","svgGraph":null},{"q":"Khi thực hiện phép đo tần số sóng âm 5 lần liên tiếp bằng dao động kí, ta thu được các giá trị đo chu kì: T₁ = 2,01 ms; T₂ = 1,99 ms; T₃ = 2,00 ms; T₄ = 2,02 ms; T₅ = 1,98 ms. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Kết quả đo cho thấy nguồn âm phát ra âm thanh thuộc vùng siêu âm.","Giá trị trung bình của chu kì đo được là T<sub>tb</sub> = 2,00 ms.","Tần số trung bình của nguồn âm là f<sub>tb</sub> = 500 Hz.","Sai số tuyệt đối trung bình của chu kì trong phép đo này là ΔT = 0,012 ms."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> T<sub>tb</sub> = (2,01+1,99+2,00+2,02+1,98)/5 = 2,00 ms.<br>• <b>Ý b [Đúng]:</b> f<sub>tb</sub> = 1/(2,00·10⁻³) = 500 Hz.<br>• <b>Ý c [Đúng]:</b> ΔT = (0,01+0,01+0,00+0,02+0,02)/5 = 0,06/5 = 0,012 ms.<br>• <b>Ý d [Sai]:</b> 500 Hz nằm trong vùng âm thanh nghe được (16 Hz - 20000 Hz), siêu âm là trên 20000 Hz.","svgGraph":null},{"q":"Để quan sát được trọn vẹn 2 chu kì của một tín hiệu âm thanh có tần số f = 250 Hz trên màn hình dao động kí có bề rộng 8 ô, ta nên chọn thang đo TIME/DIV phù hợp nhất là:","opts":["1,0 ms/div.","0,1 ms/div.","10 ms/div.","0,01 ms/div."],"ans":"A","exp":"• Chu kì: T = 1/250 = 4 ms.<br>• Thời gian cho 2 chu kì: Δt = 2T = 8 ms.<br>• Màn hình có 8 ô ngang nên mỗi ô cần hiển thị: TIME/DIV = 8 ms / 8 div = 1,0 ms/div.","svgGraph":null}],"11":[{"q":"Sóng điện từ là:","opts":["Điện từ trường lan truyền trong không gian theo thời gian.","Sóng cơ học lan truyền trong môi trường chân không.","Dòng chuyển dời có hướng của các electron tự do trong dây dẫn.","Quá trình lan truyền dao động đàn hồi của môi trường chất rắn."],"ans":"A","exp":"• Theo thuyết điện từ của Maxwell, điện trường biến thiên sinh ra từ trường xoáy, từ trường biến thiên sinh ra điện trường xoáy. Quá trình tương tác này tạo thành điện từ trường lan truyền trong không gian gọi là sóng điện từ.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr11\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- EM Spectrum Bar -->\n      <rect x=\"30\" y=\"50\" width=\"440\" height=\"45\" fill=\"#1e293b\" rx=\"6\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n      <!-- Colors in spectrum -->\n      <rect x=\"30\" y=\"50\" width=\"80\" height=\"45\" fill=\"#3b82f6\" opacity=\"0.3\"/>\n      <rect x=\"110\" y=\"50\" width=\"70\" height=\"45\" fill=\"#ef4444\" opacity=\"0.3\"/>\n      <rect x=\"180\" y=\"50\" width=\"60\" height=\"45\" fill=\"#eab308\" opacity=\"0.5\"/>\n      <rect x=\"240\" y=\"50\" width=\"70\" height=\"45\" fill=\"#8b5cf6\" opacity=\"0.3\"/>\n      <rect x=\"310\" y=\"50\" width=\"80\" height=\"45\" fill=\"#06b6d4\" opacity=\"0.3\"/>\n      <rect x=\"390\" y=\"50\" width=\"80\" height=\"45\" fill=\"#10b981\" opacity=\"0.3\"/>\n      <!-- Labels -->\n      <text x=\"40\" y=\"77\" fill=\"#93c5fd\" font-size=\"11\" font-weight=\"bold\">Vô tuyến</text>\n      <text x=\"120\" y=\"77\" fill=\"#fca5a5\" font-size=\"11\" font-weight=\"bold\">Hồng ngoại</text>\n      <text x=\"188\" y=\"77\" fill=\"#fef08a\" font-size=\"11\" font-weight=\"bold\">Ánh sáng</text>\n      <text x=\"250\" y=\"77\" fill=\"#c4b5fd\" font-size=\"11\" font-weight=\"bold\">Tử ngoại</text>\n      <text x=\"335\" y=\"77\" fill=\"#67e8f9\" font-size=\"11\" font-weight=\"bold\">Tia X</text>\n      <text x=\"405\" y=\"77\" fill=\"#6ee7b7\" font-size=\"11\" font-weight=\"bold\">Tia Gamma</text>\n      <!-- Arrow: Lambda decreasing, frequency increasing -->\n      <line x1=\"40\" y1=\"130\" x2=\"460\" y2=\"130\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arr11)\"/>\n      <text x=\"150\" y=\"123\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Tần số f và năng lượng photon tăng dần →</text>\n      <line x1=\"460\" y1=\"165\" x2=\"40\" y2=\"165\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr11)\"/>\n      <text x=\"160\" y=\"183\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">← Bước sóng λ tăng dần</text>\n      <text x=\"150\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Sơ đồ thang sóng điện từ (Electromagnetic Spectrum)</text>\n    </svg>"},{"q":"Trong chân không, mọi sóng điện từ đều lan truyền với cùng một tốc độ xấp xỉ bằng:","opts":["3·10⁸ m/s.","340 m/s.","3·10⁵ m/s.","1500 m/s."],"ans":"A","exp":"• Tốc độ truyền sóng điện từ trong chân không là hằng số phổ quát: c ≈ 3·10⁸ m/s (300.000 km/s).","svgGraph":null},{"q":"Đặc điểm nào sau đây là ĐÚNG đối với sóng điện từ?","opts":["Sóng điện từ là sóng ngang, trong đó vectơ điện trường E và vectơ cảm ứng từ B luôn vuông góc với nhau và vuông góc với phương truyền sóng.","Sóng điện từ là sóng dọc và không thể lan truyền trong môi trường chân không.","Vectơ điện trường E và vectơ cảm ứng từ B luôn dao động ngược pha với nhau.","Tốc độ truyền của sóng điện từ trong các môi trường điện môi luôn lớn hơn tốc độ truyền trong chân không."],"ans":"A","exp":"• Sóng điện từ là sóng ngang: véctơ E ⊥ véctơ B ⊥ phương truyền sóng v.<br>• Tại mỗi điểm, E và B luôn biến thiên cùng pha, cùng tần số.<br>• Trong môi trường có chiết suất n > 1, tốc độ truyền sóng v = c/n < c.","svgGraph":null},{"q":"Xét các loại sóng trong thang sóng điện từ, hãy xác định tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tia hồng ngoại có bước sóng nhỏ hơn bước sóng của ánh sáng nhìn thấy.","Sóng điện từ lan truyền được cả trong môi trường vật chất và trong chân không.","Tia tử ngoại có khả năng ion hoá chất khí và gây ra hiện tượng quang điện.","Tia X (tia Rơn-ghen) có tần số lớn hơn tần số của tia hồng ngoại nên có khả năng đâm xuyên rất mạnh."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Sóng điện từ không cần môi trường vật chất đàn hồi.<br>• <b>Ý b [Sai]:</b> Tia hồng ngoại có bước sóng lớn hơn ánh sáng đỏ (> 0,76 μm).<br>• <b>Ý c [Đúng]:</b> Tia tử ngoại mang năng lượng photon lớn nên ion hoá được không khí và kích thích quang điện.<br>• <b>Ý d [Đúng]:</b> Tia X có bước sóng rất ngắn (tần số rất lớn) nên đâm xuyên mạnh qua các mô mềm.","svgGraph":null},{"q":"Ghép từng dải sóng điện từ ở Cột A với ứng dụng thực tế tiêu biểu tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Sóng vô tuyến (Radio/Microwave) ➔ Chụp ảnh X-quang chẩn đoán gãy xương trong y học và kiểm tra hành lí sân bay","Sóng vô tuyến (Radio/Microwave) ➔ Tiệt trùng dụng cụ y tế, khử khuẩn nước và kiểm tra vết nứt bề mặt kim loại","Tia hồng ngoại (Infrared) ➔ Chụp ảnh X-quang chẩn đoán gãy xương trong y học và kiểm tra hành lí sân bay","Tia tử ngoại (Ultraviolet) ➔ Tiệt trùng dụng cụ y tế, khử khuẩn nước và kiểm tra vết nứt bề mặt kim loại"],"ans":0,"exp":"• <b>1 - D:</b> Sóng vô tuyến dùng trong viễn thông (Wi-Fi, 4G/5G).<br>• <b>2 - C:</b> Hồng ngoại dùng cho điều khiển, sấy khô, camera nhiệt.<br>• <b>3 - B:</b> Tử ngoại diệt khuẩn, tiệt trùng.<br>• <b>4 - A:</b> Tia X chụp chiếu y tế, soi an ninh.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Sóng điện từ là sóng  [ ... ] . Trong quá trình lan truyền, vectơ cường độ điện trường và vectơ cảm ứng từ luôn dao động  [ ... ]  pha và có phương  [ ... ]  với nhau. Trong chân không, sóng điện từ truyền với tốc độ lớn nhất bằng  [ ... ] .\"</i>","opts":["ngang — cùng","không đổi","ngược — 340 m/s","cùng — ngang"],"ans":0,"exp":"• Sóng điện từ là sóng ngang.<br>• E và B dao động cùng pha và vuông góc nhau.<br>• Tốc độ chân không c = 3·10⁸ m/s.","svgGraph":null},{"q":"Một đài phát thanh phát sóng vô tuyến có tần số f = 100 MHz. Bước sóng của sóng phát thanh này trong không khí là:","opts":["3,0 m.","30 m.","0,3 m.","300 m."],"ans":"A","exp":"• f = 100 MHz = 100·10⁶ Hz = 10⁸ Hz.<br>• Bước sóng: λ = <span class=\"fraction\"><span class=\"numerator\">c</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">3·10⁸</span><span class=\"denominator\">10⁸</span></span> = 3,0 m.","svgGraph":null},{"q":"Quang phổ ánh sáng nhìn thấy mà mắt người cảm nhận được có bước sóng trong khoảng xấp xỉ từ:","opts":["380 nm đến 760 nm.","10 nm đến 380 nm.","760 nm đến 1 mm.","1 mm đến 1 m."],"ans":"A","exp":"• Ánh sáng nhìn thấy trải dài từ màu tím (khoảng 380 nm = 0,38 μm) đến màu đỏ (khoảng 760 nm = 0,76 μm).","svgGraph":null},{"q":"Một sóng điện từ có bước sóng λ = 600 nm trong chân không truyền vào một môi trường trong suốt có chiết suất n = 1,5. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Màu sắc của ánh sáng bị thay đổi từ màu vàng cam sang màu tím do bước sóng giảm.","Khi truyền vào môi trường trong suốt, tần số của sóng điện từ không thay đổi.","Tốc độ truyền của sóng trong môi trường này là 2·10⁸ m/s.","Bước sóng của sóng điện từ trong môi trường này bị giảm đi còn 400 nm."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tần số f = c/λ = const.<br>• <b>Ý b [Đúng]:</b> v = c/n = 3·10⁸ / 1,5 = 2·10⁸ m/s.<br>• <b>Ý c [Đúng]:</b> λ' = v/f = c/(n·f) = λ/n = 600 / 1,5 = 400 nm.<br>• <b>Ý d [Sai]:</b> Màu sắc của ánh sáng do tần số quyết định chứ không phải bước sóng, nên màu ánh sáng không đổi.","svgGraph":null},{"q":"Tia hồng ngoại và tia tử ngoại đều có bản chất chung là:","opts":["Sóng điện từ nhưng có bước sóng và năng lượng photon khác nhau.","Dòng các hạt mang điện chuyển động với vận tốc cao.","Sóng cơ học lan truyền trong không khí ở tần số cao.","Bức xạ nhiệt chỉ phát ra từ các vật có nhiệt độ trên 1000°C."],"ans":"A","exp":"• Cả hai đều là sóng điện từ, tuân theo các quy luật truyền thẳng, phản xạ, khúc xạ và giao thoa; điểm khác biệt là bước sóng (hồng ngoại có λ > 760 nm, tử ngoại có λ < 380 nm).","svgGraph":null}],"12":[{"q":"Hiện tượng giao thoa sóng là hiện tượng hai sóng kết hợp khi gặp nhau thì:","opts":["Có những vị trí tăng cường lẫn nhau và có những vị trí triệt tiêu lẫn nhau.","Luôn luôn tăng cường lẫn nhau tại mọi điểm trong vùng không gian gặp nhau.","Luôn luôn làm biến mất hoàn toàn dao động sóng trong toàn bộ môi trường.","Làm thay đổi tần số dao động của các phần tử môi trường nơi gặp nhau."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Hiện tượng giao thoa là hiện tượng hai hay nhiều sóng kết hợp gặp nhau, tạo nên các gợn sóng ổn định với những điểm dao động cực đại (tăng cường) và những điểm đứng yên (triệt tiêu).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Source S1 and S2 -->\n      <circle cx=\"120\" cy=\"120\" r=\"7\" fill=\"#38bdf8\"/>\n      <circle cx=\"380\" cy=\"120\" r=\"7\" fill=\"#38bdf8\"/>\n      <text x=\"110\" y=\"145\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">S₁</text>\n      <text x=\"370\" y=\"145\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">S₂</text>\n      <!-- Central maximum line (k=0) -->\n      <line x1=\"250\" y1=\"20\" x2=\"250\" y2=\"220\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n      <text x=\"255\" y=\"35\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Cực đại k = 0</text>\n      <!-- Hyperbolas k = 1 and k = -1 (Maxima) -->\n      <path d=\"M 280,20 Q 295,120 280,220\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"290\" y=\"45\" fill=\"#38bdf8\" font-size=\"11\">k = +1</text>\n      <path d=\"M 220,20 Q 205,120 220,220\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"180\" y=\"45\" fill=\"#38bdf8\" font-size=\"11\">k = -1</text>\n      <!-- Hyperbolas Minima (Dotted) -->\n      <path d=\"M 315,20 Q 340,120 315,220\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\"/>\n      <path d=\"M 185,20 Q 160,120 185,220\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\"/>\n      <text x=\"325\" y=\"65\" fill=\"#f43f5e\" font-size=\"10\">Cực tiểu k = 0</text>\n      <text x=\"115\" y=\"65\" fill=\"#f43f5e\" font-size=\"10\">Cực tiểu k = -1</text>\n      <text x=\"140\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Giao thoa hai nguồn kết hợp cùng pha</text>\n    </svg>"},{"q":"Hai nguồn sóng được gọi là hai nguồn kết hợp khi chúng phát ra hai sóng có:","opts":["Cùng tần số và có hiệu số pha không đổi theo thời gian.","Cùng biên độ nhưng có tần số và tốc độ dao động hoàn toàn khác nhau.","Cùng phương dao động nhưng bước sóng thay đổi liên tục theo không gian.","Cùng chu kì nhưng hiệu số pha biến thiên tuần hoàn theo thời gian."],"ans":"A","exp":"• <b>Điều kiện giao thoa sóng:</b> Hai nguồn kết hợp là hai nguồn dao động cùng phương, cùng tần số (hoặc chu kì) và có hiệu số pha không đổi theo thời gian.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa sóng trên mặt nước với hai nguồn kết hợp S₁ và S₂ dao động cùng pha, bước sóng là λ. Vị trí các điểm dao động với biên độ cực đại thoả mãn hiệu đường đi d₂ - d₁ bằng:","opts":["k·λ (với k = 0, ±1, ±2, ...).","(k + 0,5)·λ (với k = 0, ±1, ±2, ...).","(2k + 1)·λ (với k = 0, ±1, ±2, ...).","k·λ/2 (với k = 0, ±1, ±2, ...)."],"ans":"A","exp":"• <b>Điều kiện cực đại giao thoa:</b> Điểm dao động với biên độ cực đại khi hiệu đường đi từ hai nguồn tới điểm đó bằng một số nguyên lần bước sóng: d₂ - d₁ = k·λ (k ∈ ℤ).","svgGraph":null},{"q":"Trong thí nghiệm tạo sóng giao thoa trên mặt nước bởi hai cần rung gắn vào cùng một máy phát (hai nguồn cùng pha), xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu thay đổi tần số của máy phát thì hệ vân giao thoa trên mặt nước vẫn giữ nguyên không đổi.","Đường trung trực của đoạn nối hai nguồn là vân giao thoa cực đại bậc k = 0.","Khoảng cách giữa hai điểm cực đại liên tiếp trên đoạn thẳng nối hai nguồn bằng một nửa bước sóng (λ/2).","Tại các điểm cực tiểu giao thoa, hai sóng thành phần gửi tới luôn dao động ngược pha nhau."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tại trung trực, d₁ = d₂ ⇒ d₂ - d₁ = 0 = 0·λ nên là cực đại chính giữa k = 0.<br>• <b>Ý b [Đúng]:</b> Trên đoạn S₁S₂, khoảng cách giữa 2 cực đại (hoặc 2 cực tiểu) kế tiếp là λ/2.<br>• <b>Ý c [Sai]:</b> Đổi f ⇒ λ = v/f thay đổi ⇒ khoảng vân và mật độ vân hyperbole thay đổi.<br>• <b>Ý d [Đúng]:</b> Điểm cực tiểu có hiệu đường đi d₂ - d₁ = (k + 0,5)λ nên độ lệch pha Δφ = (2k + 1)π (ngược pha) triệt tiêu nhau.","svgGraph":null},{"q":"Ghép tính chất hiệu đường truyền sóng d₂ - d₁ ở Cột A với trạng thái dao động tương ứng ở Cột B (hai nguồn cùng pha, bước sóng λ):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Hiệu đường truyền d₂ - d₁ = 2λ ➔ Vân cực đại trung tâm (k = 0), dao động với biên độ lớn nhất","Hiệu đường truyền d₂ - d₁ = 2λ ➔ Vân cực đại bậc 2 (k = 2)","Hiệu đường truyền d₂ - d₁ = 1,5λ ➔ Vân cực đại trung tâm (k = 0), dao động với biên độ lớn nhất","Hiệu đường truyền d₂ - d₁ = 0 ➔ Vân cực đại bậc 2 (k = 2)"],"ans":0,"exp":"• <b>1 - B:</b> d₂ - d₁ = 2λ là cực đại bậc 2.<br>• <b>2 - D:</b> d₂ - d₁ = 1,5λ = (1 + 0,5)λ là cực tiểu thứ 2.<br>• <b>3 - A:</b> d₂ - d₁ = 0 là cực đại trung tâm k = 0.<br>• <b>4 - C:</b> d₂ - d₁ = 0,5λ = (0 + 0,5)λ là cực tiểu thứ nhất.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong thí nghiệm giao thoa ánh sáng Young với khoảng cách hai khe là a, khoảng cách từ hai khe tới màn là D và bước sóng ánh sáng là λ. Khoảng vân i là khoảng cách giữa hai  [ ... ]  liên tiếp. Công thức tính khoảng vân là  [ ... ] . Vị trí vân sáng bậc k trên màn xác định bởi  [ ... ] . Hiện tượng giao thoa ánh sáng là bằng chứng thực nghiệm vững chắc chứng tỏ ánh sáng có  [ ... ] .\"</i>","opts":["vân sáng (hoặc hai vân tối) — i = λD/a","không đổi","i = aD/λ — tính chất hạt","i = λD/a — vân sáng (hoặc hai vân tối)"],"ans":0,"exp":"<b>Lí thuyết giao thoa ánh sáng qua khe Young:</b><br>• Khoảng vân: i = λD/a.<br>• Tọa độ vân sáng: x<sub>s</sub> = k·i.<br>• Giao thoa chứng minh ánh sáng có tính chất sóng.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa sóng nước với hai nguồn cùng pha dao động với tần số f = 25 Hz. Tốc độ truyền sóng trên mặt nước là v = 50 cm/s. Khoảng cách giữa hai điểm dao động với biên độ cực đại liên tiếp trên đoạn nối hai nguồn là:","opts":["1,0 cm.","2,0 cm.","0,5 cm.","4,0 cm."],"ans":"A","exp":"• <b>Bước 1: Tính bước sóng λ:</b><br>λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">50</span><span class=\"denominator\">25</span></span> = 2,0 cm.<br>• <b>Bước 2: Khoảng cách giữa 2 cực đại liên tiếp trên S₁S₂:</b><br>d = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">2,0</span><span class=\"denominator\">2</span></span> = 1,0 cm.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa khe Young, khoảng cách hai khe a = 0,5 mm, khoảng cách từ hai khe tới màn D = 1 m. Chiếu bằng ánh sáng đơn sắc có bước sóng λ = 0,6 μm. Khoảng vân i đo được trên màn là:","opts":["1,2 mm.","0,6 mm.","2,4 mm.","1,5 mm."],"ans":"A","exp":"• <b>Công thức tính khoảng vân:</b> i = <span class=\"fraction\"><span class=\"numerator\">λD</span><span class=\"denominator\">a</span></span><br>• <b>Thay số:</b> i = <span class=\"fraction\"><span class=\"numerator\">0,6·10⁻⁶ · 1</span><span class=\"denominator\">0,5·10⁻³</span></span> = 1,2·10⁻³ m = 1,2 mm.","svgGraph":null},{"q":"Thực hiện giao thoa ánh sáng đơn sắc qua hai khe Young. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu đưa toàn bộ hệ thí nghiệm từ không khí vào trong nước thì khoảng vân i sẽ tăng lên.","Tại chính giữa màn quan sát (vị trí vân trung tâm) luôn luôn là một vân sáng.","Nếu tăng khoảng cách giữa hai khe a lên gấp đôi và giữ nguyên các thông số khác thì khoảng vân i giảm đi 2 lần.","Vị trí vân tối thứ 3 tính từ vân trung tâm cách vân trung tâm một đoạn bằng 2,5·i."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tại gốc toạ độ x = 0 (trung tâm), hiệu quang trình Δd = 0 nên luôn là vân sáng trung tâm bậc 0.<br>• <b>Ý b [Sai]:</b> Trong nước, bước sóng giảm λ' = λ/n ⇒ khoảng vân i' = i/n sẽ giảm đi.<br>• <b>Ý c [Đúng]:</b> i = λD/a tỉ lệ nghịch với a nên a tăng 2 lần thì i giảm 2 lần.<br>• <b>Ý d [Đúng]:</b> Vân tối thứ 3 ứng với k = 2 có x<sub>t</sub> = (2 + 0,5)i = 2,5·i.","svgGraph":null},{"q":"Trong thí nghiệm Young, trên màn quan sát người ta đo được khoảng cách giữa 5 vân sáng liên tiếp là 4,8 mm. Khoảng vân i bằng:","opts":["1,2 mm.","0,96 mm.","1,6 mm.","2,4 mm."],"ans":"A","exp":"• <b>Quy tắc đếm khoảng vân:</b> Khoảng cách giữa n vân sáng liên tiếp chứa (n - 1) khoảng vân:<br>L = (n - 1)·i ⇒ 4·i = 4,8 mm ⇒ i = <span class=\"fraction\"><span class=\"numerator\">4,8</span><span class=\"denominator\">4</span></span> = 1,2 mm.","svgGraph":null}],"13":[{"q":"Sóng dừng là hình ảnh sóng tạo thành bởi:","opts":["Sự giao thoa của sóng tới và sóng phản xạ truyền ngược chiều trên cùng một phương.","Sự tắt dần nhanh chóng của một dao động sóng khi truyền vào môi trường có ma sát lớn.","Sự lan truyền của hai sóng cơ học vuông pha có cùng bước sóng.","Một dao động không truyền đi mà đứng yên tại nguồn phát."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Sóng dừng là hiện tượng giao thoa giữa sóng tới và sóng phản xạ trên cùng một phương truyền sóng, tạo ra hệ thống các điểm luôn đứng yên gọi là nút sóng và các điểm luôn dao động với biên độ cực đại gọi là bụng sóng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Nodes and Antinodes on horizontal string -->\n      <line x1=\"50\" y1=\"120\" x2=\"450\" y2=\"120\" stroke=\"#475569\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <!-- Loop 1 -->\n      <path d=\"M 50,120 Q 116,50 183,120 Q 250,50 316,120 Q 383,50 450,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <path d=\"M 50,120 Q 116,190 183,120 Q 250,190 316,120 Q 383,190 450,120\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n      <!-- Node circles -->\n      <circle cx=\"50\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <circle cx=\"183\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <circle cx=\"316\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <circle cx=\"450\" cy=\"120\" r=\"5\" fill=\"#f43f5e\"/>\n      <!-- Antinode circles -->\n      <circle cx=\"116\" cy=\"50\" r=\"4\" fill=\"#34d399\"/>\n      <circle cx=\"250\" cy=\"50\" r=\"4\" fill=\"#34d399\"/>\n      <circle cx=\"383\" cy=\"50\" r=\"4\" fill=\"#34d399\"/>\n      <!-- Labels -->\n      <text x=\"45\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"178\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"311\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"440\" y=\"145\" fill=\"#f43f5e\" font-size=\"11\">Nút</text>\n      <text x=\"100\" y=\"38\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Bụng</text>\n      <text x=\"235\" y=\"38\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Bụng</text>\n      <!-- Lambda / 2 bracket -->\n      <line x1=\"50\" y1=\"195\" x2=\"183\" y2=\"195\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"50\" cy=\"195\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"183\" cy=\"195\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"100\" y=\"215\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">λ/2 (1 bó sóng)</text>\n      <text x=\"180\" y=\"235\" fill=\"#94a3b8\" font-size=\"12\">Sóng dừng với 3 bó sóng (k = 3)</text>\n    </svg>"},{"q":"Khi xảy ra hiện tượng phản xạ sóng cơ trên vật cản cố định, tại điểm phản xạ sóng phản xạ luôn dao động:","opts":["Ngược pha với sóng tới.","Cùng pha với sóng tới.","Vuông pha với sóng tới.","Lệch pha π/4 so với sóng tới."],"ans":"A","exp":"• <b>Quy tắc phản xạ sóng:</b> Khi phản xạ trên vật cản cố định, sóng phản xạ ngược pha với sóng tới tại điểm phản xạ. Nếu là vật cản tự do thì cùng pha.","svgGraph":null},{"q":"Điều kiện để có sóng dừng trên sợi dây đàn hồi chiều dài L có hai đầu cố định là:","opts":["L = k·λ/2 (với k = 1, 2, 3, ... là số bó sóng).","L = (2k + 1)·λ/4 (với k = 0, 1, 2, ...).","L = k·λ (với k = 1, 2, 3, ...).","L = (2k + 1)·λ/2 (với k = 0, 1, 2, ...)."],"ans":"A","exp":"• <b>Điều kiện 2 đầu cố định:</b> Chiều dài dây phải bằng một số nguyên lần nửa bước sóng: L = k·<span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span>, trong đó k là số bó sóng, số bụng sóng = k và số nút sóng = k + 1.","svgGraph":null},{"q":"Khi quan sát hiện tượng sóng dừng ổn định trên một sợi dây cao su căng ngang, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Năng lượng dao động của sóng dừng được truyền liên tục từ đầu này sang đầu kia của dây.","Khoảng cách giữa hai nút sóng liên tiếp (hoặc hai bụng sóng liên tiếp) luôn bằng nửa bước sóng (λ/2).","Khoảng cách giữa một nút sóng và một bụng sóng gần nhau nhất bằng một phần tư bước sóng (λ/4).","Tất cả các phần tử nằm trong cùng một bó sóng luôn luôn dao động cùng pha với nhau."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Khoảng cách nút - nút hoặc bụng - bụng kế tiếp bằng λ/2.<br>• <b>Ý b [Đúng]:</b> Nút đến bụng gần nhất bằng λ/4.<br>• <b>Ý c [Đúng]:</b> Các phần tử trong cùng 1 bó sóng cùng pha nhau; hai bó sóng liền kề dao động ngược pha.<br>• <b>Ý d [Sai]:</b> Sóng dừng không truyền tải năng lượng dọc theo dây mà năng lượng bị giam giữ cố định giữa các nút.","svgGraph":null},{"q":"Ghép loại sóng dừng hoặc vị trí ở Cột A với đặc điểm tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Dây có 2 đầu cố định ➔ L = (2k + 1)·λ/4, số nút bằng số bụng = k + 1","Dây có 2 đầu cố định ➔ L = k·λ/2, số bụng = k, số nút = k + 1","Dây có 1 đầu cố định, 1 đầu tự do ➔ L = (2k + 1)·λ/4, số nút bằng số bụng = k + 1","Điểm nút sóng ➔ L = k·λ/2, số bụng = k, số nút = k + 1"],"ans":0,"exp":"• <b>1 - B:</b> 2 đầu cố định: L = k·λ/2.<br>• <b>2 - A:</b> 1 cố định 1 tự do: L = (2k + 1)·λ/4.<br>• <b>3 - D:</b> Nút là điểm đứng yên triệt tiêu.<br>• <b>4 - C:</b> Bụng dao động cực đại với A<sub>b</sub> = 2A.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Hiện tượng sóng dừng của sóng âm trong một ống khí hở một đầu và kín một đầu có điều kiện chiều dài cột khí là  [ ... ] . Đầu kín của ống luôn đóng vai trò là một  [ ... ]  sóng âm, còn miệng hở của ống đóng vai trò là một  [ ... ]  sóng âm. Tần số nhỏ nhất tạo sóng dừng trong ống này gọi là  [ ... ] .\"</i>","opts":["L = (2k + 1)·λ/4 — nút","không đổi","L = k·λ/2 — hoạ âm bậc hai","nút — L = (2k + 1)·λ/4"],"ans":0,"exp":"<b>Ống khí 1 đầu kín 1 đầu hở:</b><br>• Chiều dài: L = (2k + 1)·λ/4.<br>• Đầu kín là nút, miệng hở là bụng.<br>• Ứng với k = 0 cho tần số nhỏ nhất f₁ gọi là âm cơ bản.","svgGraph":null},{"q":"Một sợi dây đàn hồi dài L = 1,2 m hai đầu cố định đang có sóng dừng với 3 bó sóng. Bước sóng λ của sóng trên dây là:","opts":["0,8 m.","0,4 m.","1,2 m.","2,4 m."],"ans":"A","exp":"• <b>Công thức sóng dừng 2 đầu cố định:</b> L = k·<span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span><br>• <b>Thay số với k = 3 bó sóng:</b> 1,2 = 3 · <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span> ⇒ λ = <span class=\"fraction\"><span class=\"numerator\">1,2 · 2</span><span class=\"denominator\">3</span></span> = 0,8 m (80 cm).","svgGraph":null},{"q":"Một sợi dây dài 90 cm có một đầu gắn vào âm thoa dao động với tần số f = 100 Hz, đầu còn lại tự do. Tốc độ truyền sóng trên dây là v = 40 m/s. Số nút sóng quan sát được trên dây là:","opts":["5 nút sóng.","4 nút sóng.","6 nút sóng.","9 nút sóng."],"ans":"A","exp":"• <b>Bước 1: Tính bước sóng λ:</b><br>λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">40</span><span class=\"denominator\">100</span></span> = 0,4 m = 40 cm.<br>• <b>Bước 2: Tìm k từ điều kiện 1 đầu cố định 1 đầu tự do:</b><br>L = (2k + 1)·<span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">4</span></span> ⇒ 90 = (2k + 1) · <span class=\"fraction\"><span class=\"numerator\">40</span><span class=\"denominator\">4</span></span> = (2k + 1)·10 ⇒ 2k + 1 = 9 ⇒ k = 4.<br>• <b>Bước 3:</b> Số nút sóng = k + 1 = 4 + 1 = 5 nút.","svgGraph":null},{"q":"Một dây đàn ghita có chiều dài L = 65 cm hai đầu cố định, tốc độ truyền sóng trên dây là v = 416 m/s. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Muốn phát ra âm có tần số cao hơn, người chơi đàn cần bấm phím để kéo dài chiều dài tự do của dây đàn.","Tần số của âm cơ bản do dây đàn phát ra là f₁ = 320 Hz.","Khi dây dao động phát ra hoạ âm bậc hai thì trên dây xuất hiện 2 bụng sóng.","Tần số của các hoạ âm mà dây đàn có thể phát ra là các số nguyên lần tần số âm cơ bản: f<sub>k</sub> = k·f₁."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Âm cơ bản (k = 1): L = λ/2 ⇒ λ = 2L = 1,3 m ⇒ f₁ = v/λ = 416 / 1,3 = 320 Hz.<br>• <b>Ý b [Đúng]:</b> Hoạ âm bậc 2 ứng với k = 2 nên có 2 bó sóng = 2 bụng.<br>• <b>Ý c [Đúng]:</b> Dây 2 đầu cố định phát ra dãy hoạ âm f<sub>k</sub> = k·f₁ (k = 1, 2, 3, ...).<br>• <b>Ý d [Sai]:</b> f = v/(2L) tỉ lệ nghịch với L, muốn âm cao hơn (tần số f lớn hơn) thì phải bấm phím làm ngắn chiều dài dây lại.","svgGraph":null},{"q":"Trên một sợi dây đang có sóng dừng ổn định với bước sóng λ = 24 cm. Hai điểm M và N trên dây cùng nằm trong một bó sóng, cách nhau 4 cm. Độ lệch pha dao động giữa M và N bằng:","opts":["0 rad (cùng pha).","π rad (ngược pha).","π/2 rad (vuông pha).","π/3 rad."],"ans":"A","exp":"• Trong hiện tượng sóng dừng, mọi điểm nằm giữa hai nút liên tiếp (tức trong cùng một bó sóng) đều dao động đồng pha với nhau (độ lệch pha bằng 0).","svgGraph":null}],"14":[{"q":"Một sóng cơ truyền dọc theo trục Ox có phương trình u = 5·cos(4πt - 0,02πx) (mm), trong đó x tính bằng cm và t tính bằng giây. Tốc độ truyền sóng là:","opts":["200 cm/s.","100 cm/s.","50 cm/s.","400 cm/s."],"ans":"A","exp":"• <b>Dạng tổng quát phương trình sóng:</b> u = A·cos(ωt - <span class=\"fraction\"><span class=\"numerator\">2πx</span><span class=\"denominator\">λ</span></span>)<br>• Đồng nhất hệ số: <span class=\"fraction\"><span class=\"numerator\">2π</span><span class=\"denominator\">λ</span></span> = 0,02π ⇒ λ = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">0,02</span></span> = 100 cm.<br>• Tần số: f = <span class=\"fraction\"><span class=\"numerator\">ω</span><span class=\"denominator\">2π</span></span> = <span class=\"fraction\"><span class=\"numerator\">4π</span><span class=\"denominator\">2π</span></span> = 2 Hz.<br>• Tốc độ truyền sóng: v = λ·f = 100 · 2 = 200 cm/s.","svgGraph":null},{"q":"Trong thí nghiệm giao thoa sóng nước với hai nguồn đồng bộ S₁ và S₂ cách nhau 18 cm, bước sóng λ = 3 cm. Số điểm cực đại giao thoa trên đoạn nối hai nguồn S₁S₂ là:","opts":["11 điểm.","12 điểm.","13 điểm.","9 điểm."],"ans":"A","exp":"• <b>Công thức xác định số cực đại trên đoạn S₁S₂:</b><br>-<span class=\"fraction\"><span class=\"numerator\">S₁S₂</span><span class=\"denominator\">λ</span></span> < k < +<span class=\"fraction\"><span class=\"numerator\">S₁S₂</span><span class=\"denominator\">λ</span></span><br>• Thay số: -<span class=\"fraction\"><span class=\"numerator\">18</span><span class=\"denominator\">3</span></span> < k < +<span class=\"fraction\"><span class=\"numerator\">18</span><span class=\"denominator\">3</span></span> ⇒ -6 < k < +6.<br>• Vì k nguyên nên k ∈ {-5, -4, ..., 0, ..., 4, 5} ⇒ có 2 · 5 + 1 = 11 giá trị cực đại.","svgGraph":null},{"q":"Một sóng âm truyền từ không khí vào nước. Biết tốc độ truyền âm trong không khí là 340 m/s và trong nước là 1480 m/s. Khi đi vào nước thì:","opts":["Tần số không đổi, bước sóng tăng xấp xỉ 4,35 lần.","Tần số tăng 4,35 lần, bước sóng không đổi.","Cả tần số và bước sóng đều tăng 4,35 lần.","Tần số không đổi, bước sóng giảm 4,35 lần."],"ans":"A","exp":"• <b>Bản chất:</b> Tần số f của sóng do nguồn quyết định nên không đổi khi truyền qua các môi trường.<br>• <b>Bước sóng:</b> λ = <span class=\"fraction\"><span class=\"numerator\">v</span><span class=\"denominator\">f</span></span>, vì v tăng từ 340 m/s lên 1480 m/s nên bước sóng tăng: <span class=\"fraction\"><span class=\"numerator\">1480</span><span class=\"denominator\">340</span></span> ≈ 4,35 lần.","svgGraph":null},{"q":"Một sợi dây đàn hồi AB căng ngang dài L = 100 cm, đầu A gắn vào nguồn dao động với tần số f = 50 Hz, đầu B cố định. Tốc độ truyền sóng trên dây là v = 20 m/s. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu tăng tần số dao động lên f' = 75 Hz thì trên dây sẽ quan sát được 7 bụng sóng.","Bước sóng của sóng truyền trên dây là λ = 40 cm.","Trên dây quan sát được sóng dừng ổn định với 5 bó sóng.","Số điểm nút sóng trên dây (kể cả hai đầu A và B) là 6 nút."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> λ = v/f = 20 / 50 = 0,4 m = 40 cm.<br>• <b>Ý b [Đúng]:</b> L = k·λ/2 ⇒ 100 = k·(40/2) = 20k ⇒ k = 5 bó sóng.<br>• <b>Ý c [Đúng]:</b> Số nút = k + 1 = 5 + 1 = 6 nút.<br>• <b>Ý d [Sai]:</b> Với f' = 75 Hz ⇒ λ' = 20/75 = 0,2667 m ⇒ k' = 2L/λ' = 2·1 / 0,2667 = 7,5 (không nguyên) nên không thể tạo thành sóng dừng hoàn chỉnh.","svgGraph":null},{"q":"Ghép hiện tượng sóng ở Cột A với ứng dụng kĩ thuật hoặc thực tiễn đời sống ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Giao thoa ánh sáng ➔ Định lượng tần số và tạo âm thanh vang đặc trưng của nhạc cụ","Giao thoa ánh sáng ➔ Đo bề dày lớp màng mỏng, kiểm tra độ phẳng quang học","Sóng siêu âm phản xạ ➔ Định lượng tần số và tạo âm thanh vang đặc trưng của nhạc cụ","Sóng dừng trong hộp đàn ➔ Đo bề dày lớp màng mỏng, kiểm tra độ phẳng quang học"],"ans":0,"exp":"• <b>1 - B:</b> Giao thoa đo bước sóng, màng mỏng.<br>• <b>2 - D:</b> Siêu âm chuẩn đoán y khoa, sonar.<br>• <b>3 - A:</b> Sóng dừng khuếch đại âm sắc nhạc cụ.<br>• <b>4 - C:</b> Lò vi ba dùng sóng viba 2,45 GHz.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi một sóng cơ truyền qua hai điểm M và N trên cùng một phương truyền sóng cách nhau khoảng cách d, độ lệch pha giữa hai điểm được xác định bởi biểu thức  [ ... ] . Nếu d bằng một số nguyên lần bước sóng thì hai điểm dao động  [ ... ] . Nếu d bằng một số bán nguyên lần bước sóng thì hai điểm dao động  [ ... ] . Nếu hai điểm dao động vuông pha thì độ lệch pha thoả mãn  [ ... ] .\"</i>","opts":["Δφ = 2πd/λ — cùng pha","không đổi","Δφ = πd/λ — lệch pha π/4","cùng pha — Δφ = 2πd/λ"],"ans":0,"exp":"<b>Độ lệch pha hai điểm trên phương truyền sóng:</b><br>• Δφ = 2πd/λ.<br>• d = kλ: cùng pha.<br>• d = (k + 0,5)λ: ngược pha.<br>• d = (2k + 1)λ/4: vuông pha (Δφ = (2k + 1)π/2).","svgGraph":null},{"q":"Trong thí nghiệm Young về giao thoa ánh sáng, nguồn phát ánh sáng có bước sóng λ = 500 nm. Khoảng cách giữa hai khe là 1 mm, khoảng cách từ mặt phẳng chứa hai khe đến màn là 2 m. Vị trí của vân sáng bậc 4 cách vân sáng trung tâm một khoảng:","opts":["4,0 mm.","2,0 mm.","5,0 mm.","1,0 mm."],"ans":"A","exp":"• <b>Khoảng vân i:</b> i = <span class=\"fraction\"><span class=\"numerator\">λD</span><span class=\"denominator\">a</span></span> = <span class=\"fraction\"><span class=\"numerator\">500·10⁻⁶ · 2</span><span class=\"denominator\">1</span></span> = 1,0 mm.<br>• <b>Vị trí vân sáng bậc 4:</b> x₄ = 4·i = 4 · 1,0 = 4,0 mm.","svgGraph":null},{"q":"Trên mặt một chất lỏng có hai nguồn kết hợp dao động cùng pha tại A và B cách nhau 10 cm, bước sóng λ = 1,6 cm. Điểm M trên mặt nước cách A 12 cm và cách B 8,8 cm. Điểm M nằm trên vân:","opts":["Cực đại giao thoa bậc 2.","Cực tiểu giao thoa thứ 2.","Cực đại giao thoa bậc 3.","Cực tiểu giao thoa thứ 3."],"ans":"A","exp":"• <b>Xét hiệu đường đi tại M:</b> d₁ - d₂ = 12 - 8,8 = 3,2 cm.<br>• <b>Tỉ số:</b> <span class=\"fraction\"><span class=\"numerator\">d₁ - d₂</span><span class=\"denominator\">λ</span></span> = <span class=\"fraction\"><span class=\"numerator\">3,2</span><span class=\"denominator\">1,6</span></span> = 2.<br>• Vì tỉ số bằng số nguyên 2 nên điểm M nằm trên vân cực đại giao thoa bậc 2.","svgGraph":null},{"q":"Một nguồn âm đẳng hướng phát sóng âm có công suất không đổi trong không gian. Bỏ qua sự hấp thụ và phản xạ âm của môi trường. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi mức cường độ âm tăng thêm 20 dB thì cường độ âm thực tế đã tăng gấp 20 lần.","Cường độ âm I tại một điểm tỉ lệ nghịch với bình phương khoảng cách r từ điểm đó tới nguồn âm.","Nếu khoảng cách từ điểm đo tới nguồn âm tăng lên 2 lần thì mức cường độ âm L giảm đi xấp xỉ 6 dB.","Cường độ âm chuẩn là I₀ = 10⁻¹² W/m² tương ứng với ngưỡng nghe của tai người ở tần số 1000 Hz."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> I = P / (4πr²) tỉ lệ nghịch với r².<br>• <b>Ý b [Đúng]:</b> r tăng 2 lần ⇒ I giảm 4 lần ⇒ ΔL = 10·lg(1/4) ≈ -6,02 dB.<br>• <b>Ý c [Đúng]:</b> I₀ = 10⁻¹² W/m² là ngưỡng nghe chuẩn.<br>• <b>Ý d [Sai]:</b> L₂ - L₁ = 20 dB = 2 B ⇒ I₂/I₁ = 10² = 100 lần (chứ không phải 20 lần).","svgGraph":null},{"q":"Một âm có mức cường độ âm L = 80 dB. Biết cường độ âm chuẩn I₀ = 10⁻¹² W/m². Cường độ âm của âm đó là:","opts":["10⁻⁴ W/m².","10⁻⁸ W/m².","10⁻⁶ W/m².","10⁻² W/m²."],"ans":"A","exp":"• <b>Công thức mức cường độ âm:</b> L(dB) = 10·lg(<span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">I₀</span></span>)<br>• Thay số: 80 = 10·lg(<span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">10⁻¹²</span></span>) ⇒ lg(<span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">10⁻¹²</span></span>) = 8 ⇒ <span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">10⁻¹²</span></span> = 10⁸ ⇒ I = 10⁻⁴ W/m².","svgGraph":null}],"15":[{"q":"Trong thí nghiệm đo tốc độ truyền âm trong không khí bằng ống cộng hưởng hình trụ có pittông di động, hiện tượng cộng hưởng âm xảy ra khi:","opts":["Âm nghe được qua miệng ống đột ngột to nhất tại các vị trí xác định của pittông.","Mọi âm thanh bị dập tắt hoàn toàn bên trong ống nghiệm.","Tần số của máy phát tự động nhảy lên gấp đôi giá trị ban đầu.","Pittông bị đẩy bật ra khỏi ống do áp suất không khí tăng đột biến."],"ans":"A","exp":"• Khi sóng âm phát từ loa tạo sóng dừng trong cột không khí bên trong ống, tại miệng ống là một bụng sóng làm cho âm thanh cộng hưởng phát ra ngoài có âm lượng lớn nhất.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr15\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Glass tube outline -->\n      <rect x=\"100\" y=\"70\" width=\"320\" height=\"70\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <!-- Speaker at open end -->\n      <polygon points=\"60,85 85,75 85,135 60,125\" fill=\"#f59e0b\"/>\n      <rect x=\"45\" y=\"95\" width=\"15\" height=\"20\" fill=\"#64748b\"/>\n      <text x=\"50\" y=\"155\" fill=\"#f59e0b\" font-size=\"11\">Nguồn âm</text>\n      <!-- Water level / Piston at L1 -->\n      <rect x=\"250\" y=\"72\" width=\"168\" height=\"66\" fill=\"#0284c7\" opacity=\"0.4\"/>\n      <line x1=\"250\" y1=\"70\" x2=\"250\" y2=\"140\" stroke=\"#f43f5e\" stroke-width=\"4\"/>\n      <text x=\"240\" y=\"60\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Mặt nước (Nút)</text>\n      <!-- Standing sound wave inside air column -->\n      <path d=\"M 85,75 Q 165,105 250,105\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <path d=\"M 85,135 Q 165,105 250,105\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <text x=\"88\" y=\"65\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">Miệng ống (Bụng)</text>\n      <!-- Column length L1 = lambda / 4 -->\n      <line x1=\"85\" y1=\"170\" x2=\"250\" y2=\"170\" stroke=\"#fbbf24\" stroke-width=\"2\" marker-end=\"url(#arr15)\"/>\n      <text x=\"145\" y=\"190\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">L₁ ≈ λ/4</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Thí nghiệm cột khí cộng hưởng đo tốc độ truyền âm</text>\n    </svg>"},{"q":"Trong thí nghiệm đo tốc độ truyền âm bằng ống cộng hưởng hình trụ, người ta ghi nhận hai vị trí liên tiếp của mực nước cho âm nghe to nhất là L₁ và L₂ (L₂ > L₁). Bước sóng λ của âm được tính theo công thức:","opts":["λ = 2·(L₂ - L₁).","λ = L₂ - L₁.","λ = 4·(L₂ - L₁).","λ = (L₂ - L₁)/2."],"ans":"A","exp":"• <b>Nguyên lí:</b> Khoảng cách giữa hai vị trí cộng hưởng liên tiếp của cột không khí (hai mực nước liên tiếp cho âm to nhất) bằng nửa bước sóng:<br>L₂ - L₁ = <span class=\"fraction\"><span class=\"numerator\">λ</span><span class=\"denominator\">2</span></span> ⇒ λ = 2·(L₂ - L₁).","svgGraph":null},{"q":"Công thức liên hệ dùng để tính tốc độ truyền âm v từ tần số đã biết f và bước sóng xác định được λ là:","opts":["v = λ·f.","v = f/λ.","v = λ/f.","v = 2·λ·f."],"ans":"A","exp":"• Tốc độ truyền sóng bằng tích của bước sóng và tần số: v = λ·f.","svgGraph":null},{"q":"Khi tiến hành thí nghiệm đo tốc độ truyền âm trong không khí ở nhiệt độ phòng 25°C với nguồn âm có tần số f = 500 Hz, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hiệu số khoảng cách giữa hai lần cộng hưởng liên tiếp (L₂ - L₁) không phụ thuộc vào tần số của nguồn âm phát ra.","Tốc độ truyền âm đo được trong không khí ở điều kiện phòng thực nghiệm thường rơi vào khoảng từ 330 m/s đến 350 m/s.","Nếu tăng nhiệt độ của phòng thí nghiệm lên thì tốc độ truyền âm trong không khí sẽ tăng lên.","Tại mặt thoáng của mực nước trong ống luôn hình thành một nút sóng của sóng dừng áp suất."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Vận tốc âm trong không khí ở 25°C là v ≈ 331 + 0,6·25 ≈ 346 m/s.<br>• <b>Ý b [Đúng]:</b> Tốc độ âm tỉ lệ thuận với căn bậc hai nhiệt độ tuyệt đối T (nhiệt độ tăng thì tốc độ phân tử khí tăng ⇒ v tăng).<br>• <b>Ý c [Sai]:</b> L₂ - L₁ = λ/2 = v/(2f) phụ thuộc chặt chẽ vào tần số f.<br>• <b>Ý d [Đúng]:</b> Mặt nước là vật cản cố định nên tạo thành nút sóng li độ dao động.","svgGraph":null},{"q":"Ghép các bộ phận trong thí nghiệm đo tốc độ truyền âm ở Cột A với chức năng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Máy phát âm tần số xác định ➔ Đo nhiệt độ môi trường để đối chiếu với tốc độ âm lí thuyết","Máy phát âm tần số xác định ➔ Thay đổi chiều cao của cột không khí bên trong ống nghiệm","Ống cộng hưởng chia vạch mm ➔ Đo nhiệt độ môi trường để đối chiếu với tốc độ âm lí thuyết","Bình nước thông nhau có thể nâng hạ ➔ Thay đổi chiều cao của cột không khí bên trong ống nghiệm"],"ans":0,"exp":"• <b>1 - C:</b> Máy phát cung cấp f chuẩn.<br>• <b>2 - D:</b> Ống chia độ đọc chiều dài cột khí.<br>• <b>3 - B:</b> Bình thông nhau thay đổi mực nước.<br>• <b>4 - A:</b> Nhiệt kế đo nhiệt độ để tính v<sub>l</sub>í_thuyết.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Sau khi xác định được hai vị trí mực nước cho âm to nhất liên tiếp là L₁ và L₂, ta tính được bước sóng là  [ ... ] . Tốc độ truyền âm được tính bằng công thức  [ ... ] . Để giảm thiểu sai số ngẫu nhiên, ta cần thực hiện phép đo  [ ... ]  và lấy giá trị trung bình. Sai số tỉ đối của phép đo được xác định bởi công thức  [ ... ] .\"</i>","opts":["λ = 2·(L₂ - L₁) — v = λ·f","không đổi","λ = L₂ - L₁ — một lần duy nhất","v = λ·f — λ = 2·(L₂ - L₁)"],"ans":0,"exp":"<b>Quy trình xử lí số liệu thực hành:</b><br>• λ = 2(L₂ - L₁).<br>• v = λ·f.<br>• Thực hiện nhiều lần tính giá trị trung bình.<br>• Sai số tỉ đối: Δv/v = Δλ/λ + Δf/f.","svgGraph":null},{"q":"Trong thí nghiệm đo tốc độ truyền âm với nguồn âm tần số f = 680 Hz, người ta ghi nhận hai vị trí cộng hưởng liên tiếp tại L₁ = 12 cm và L₂ = 37 cm. Tốc độ truyền âm đo được là:","opts":["340 m/s.","170 m/s.","680 m/s.","320 m/s."],"ans":"A","exp":"• <b>Bước 1: Tính bước sóng λ:</b><br>λ = 2·(L₂ - L₁) = 2 · (37 - 12) = 2 · 25 = 50 cm = 0,5 m.<br>• <b>Bước 2: Tính tốc độ truyền âm v:</b><br>v = λ·f = 0,5 · 680 = 340 m/s.","svgGraph":null},{"q":"Tại sao trong thí nghiệm ống cộng hưởng, người ta không lấy ngay chiều dài cộng hưởng đầu tiên L₁ để tính λ = 4·L₁ mà phải tìm hiệu số (L₂ - L₁)?","opts":["Vì miệng ống hở có hiệu ứng mép ngoài khiến bụng sóng nhô ra ngoài miệng ống một đoạn nhỏ.","Vì đáy ống có ma sát làm sóng âm bị phản xạ chậm hơn so với lí thuyết.","Vì nước bị bay hơi làm thay đổi thể tích cột khí một cách liên tục.","Vì tần số của âm thoa bị giảm dần theo thời gian dao động."],"ans":"A","exp":"• Tại miệng hở của ống, bụng sóng không nằm chính xác ngay tại mép ống mà nhô ra ngoài một khoảng hiệu chỉnh c ≈ 0,6·r (với r là bán kính trong của ống). Phép đo hiệu số (L₂ - L₁) sẽ triệt tiêu hoàn toàn sai số điểm mép này.","svgGraph":null},{"q":"Trong quá trình làm thực hành đo tốc độ truyền âm, xét tính Đúng / Sai của các thao tác thí nghiệm sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nên chọn âm phát có tần số rất nhỏ (dưới 50 Hz) để khoảng cách giữa hai lần cộng hưởng ngắn lại dễ đo.","Cần giữ micrô hoặc tai người quan sát gần sát miệng ống và lắng nghe thời điểm âm lượng đạt cực đại rõ rệt.","Nâng hạ mực nước thật chậm và lặp lại việc xác định vị trí ít nhất 3 lần để lấy giá trị trung bình.","Trước khi đo cần ghi nhận nhiệt độ phòng thí nghiệm để tra bảng giá trị chuẩn đối chiếu."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Lắng nghe kĩ điểm âm to nhất để ghi nhận chính xác L.<br>• <b>Ý b [Đúng]:</b> Đo lặp lại nhiều lần để giảm sai số ngẫu nhiên.<br>• <b>Ý c [Sai]:</b> f nhỏ thì λ = v/f rất lớn ⇒ khoảng cách L₂ - L₁ = λ/2 sẽ vượt quá chiều dài của ống nghiệm (không đo được).<br>• <b>Ý d [Đúng]:</b> Cần ghi nhận nhiệt độ để so sánh với công thức lí thuyết v = 331 + 0,6·t.","svgGraph":null},{"q":"Kết quả đo tốc độ truyền âm trong không khí thu được là v = (342 ± 4) m/s. Sai số tỉ đối của phép đo là:","opts":["1,17%.","0,58%.","2,34%.","1,50%."],"ans":"A","exp":"• <b>Công thức sai số tỉ đối:</b> δ = <span class=\"fraction\"><span class=\"numerator\">Δv</span><span class=\"denominator\">v<sub>tb</sub></span></span> · 100%<br>• <b>Thay số:</b> δ = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">342</span></span> · 100% ≈ 1,17%.","svgGraph":null}],"16":[{"q":"Theo định luật Coulomb, độ lớn của lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không tỉ lệ thuận với:","opts":["Tích độ lớn của hai điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.","Bình phương khoảng cách giữa chúng và tỉ lệ nghịch với tích độ lớn hai điện tích.","Tổng độ lớn của hai điện tích và tỉ lệ nghịch với khoảng cách giữa chúng.","Tích độ lớn của hai điện tích và tỉ lệ nghịch với khoảng cách giữa chúng."],"ans":"A","exp":"• <b>Định luật Coulomb:</b> F = k·<span class=\"fraction\"><span class=\"numerator\">|q₁q₂|</span><span class=\"denominator\">r²</span></span> với hằng số tĩnh điện k = 9·10⁹ N·m²/C².<br>• Lực tương tác tỉ lệ thuận với tích độ lớn hai điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr16\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Distance axis -->\n      <line x1=\"80\" y1=\"120\" x2=\"420\" y2=\"120\" stroke=\"#334155\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n      <!-- Positive charge q1 -->\n      <circle cx=\"160\" cy=\"120\" r=\"18\" fill=\"#ef4444\" stroke=\"#fca5a5\" stroke-width=\"2\"/>\n      <text x=\"153\" y=\"126\" fill=\"#ffffff\" font-size=\"18\" font-weight=\"bold\">+</text>\n      <text x=\"145\" y=\"160\" fill=\"#f87171\" font-size=\"13\" font-weight=\"bold\">q₁ > 0</text>\n      <!-- Negative charge q2 -->\n      <circle cx=\"340\" cy=\"120\" r=\"18\" fill=\"#3b82f6\" stroke=\"#93c5fd\" stroke-width=\"2\"/>\n      <text x=\"335\" y=\"126\" fill=\"#ffffff\" font-size=\"20\" font-weight=\"bold\">-</text>\n      <text x=\"325\" y=\"160\" fill=\"#60a5fa\" font-size=\"13\" font-weight=\"bold\">q₂ &lt; 0</text>\n      <!-- Attractive forces F12 and F21 -->\n      <line x1=\"160\" y1=\"120\" x2=\"230\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"3\" marker-end=\"url(#arr16)\"/>\n      <text x=\"175\" y=\"105\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">F₂₁ (hút)</text>\n      <line x1=\"340\" y1=\"120\" x2=\"270\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"3\" marker-end=\"url(#arr16)\"/>\n      <text x=\"275\" y=\"105\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">F₁₂ (hút)</text>\n      <!-- Distance r -->\n      <line x1=\"160\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <circle cx=\"160\" cy=\"180\" r=\"3\" fill=\"#34d399\"/>\n      <circle cx=\"340\" cy=\"180\" r=\"3\" fill=\"#34d399\"/>\n      <text x=\"245\" y=\"173\" fill=\"#34d399\" font-size=\"13\" font-weight=\"bold\">Khoảng cách r</text>\n      <text x=\"135\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Tương tác hút tĩnh điện giữa hai điện tích trái dấu</text>\n    </svg>"},{"q":"Nếu khoảng cách giữa hai điện tích điểm tăng lên gấp 3 lần thì lực tương tác Coulomb giữa chúng sẽ:","opts":["Giảm đi 9 lần.","Tăng lên 9 lần.","Giảm đi 3 lần.","Tăng lên 3 lần."],"ans":"A","exp":"• <b>Công thức Coulomb:</b> F = k·<span class=\"fraction\"><span class=\"numerator\">|q₁q₂|</span><span class=\"denominator\">r²</span></span><br>• Vì lực F tỉ lệ nghịch với r² nên khi r tăng lên 3 lần thì lực F giảm đi 3² = 9 lần.","svgGraph":null},{"q":"Hai điện tích điểm q₁ = +2·10⁻⁸ C và q₂ = -4·10⁻⁸ C đặt cách nhau 6 cm trong không khí (lấy ε = 1, hằng số k = 9·10⁹ N·m²/C²). Lực tương tác giữa chúng là lực:","opts":["Hút, có độ lớn bằng 2·10⁻³ N.","Đẩy, có độ lớn bằng 2·10⁻³ N.","Hút, có độ lớn bằng 1,2·10⁻³ N.","Đẩy, có độ lớn bằng 4·10⁻³ N."],"ans":"A","exp":"• Hai điện tích trái dấu (q₁ > 0, q₂ < 0) nên tương tác <b>hút nhau</b>.<br>• <b>Độ lớn:</b> F = 9·10⁹ · <span class=\"fraction\"><span class=\"numerator\">|2·10⁻⁸ · (-4·10⁻⁸)|</span><span class=\"denominator\">(0,06)²</span></span> = 9·10⁹ · <span class=\"fraction\"><span class=\"numerator\">8·10⁻¹⁶</span><span class=\"denominator\">3,6·10⁻³</span></span> = 2·10⁻³ N.","svgGraph":null},{"q":"Về tương tác tĩnh điện và định luật Coulomb, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi đặt hai điện tích vào trong môi trường chất điện môi đồng tính có hằng số điện môi ε > 1 thì lực tương tác Coulomb sẽ tăng lên ε lần.","Hai quả cầu nhỏ mang điện cùng dấu sẽ đẩy nhau, trái dấu sẽ hút nhau.","Lực tương tác Coulomb tuân theo định luật III Newton: hai lực trực đối có cùng độ lớn nhưng ngược chiều.","Điện tích nguyên tố có độ lớn nhỏ nhất là e ≈ 1,6·10⁻¹⁹ C."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Cùng dấu đẩy nhau, khác dấu hút nhau.<br>• <b>Ý b [Sai]:</b> Trong điện môi F' = F/ε nên lực tương tác giảm đi ε lần.<br>• <b>Ý c [Đúng]:</b> F₁₂ = -F₂₁ và |F₁₂| = |F₂₁| theo định luật III Newton.<br>• <b>Ý d [Đúng]:</b> Điện tích của proton (+e) và electron (-e) có độ lớn nguyên tố e ≈ 1,6·10⁻¹⁹ C.","svgGraph":null},{"q":"Ghép các đại lượng trong biểu thức định luật Coulomb ở Cột A với ý nghĩa hoặc đơn vị chuẩn ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Hằng số điện môi ε ➔ Đại lượng không có thứ nguyên (đơn vị), đặc trưng cho tính cách điện của môi trường","Hằng số điện môi ε ➔ Đo bằng đơn vị Newton (N)","Hằng số k = 9·10⁹ ➔ Đại lượng không có thứ nguyên (đơn vị), đặc trưng cho tính cách điện của môi trường","Độ lớn điện tích q ➔ Đo bằng đơn vị Newton (N)"],"ans":0,"exp":"• <b>1 - A:</b> ε là đại lượng không thứ nguyên, chân không có ε = 1.<br>• <b>2 - D:</b> k = 9·10⁹ N·m²/C².<br>• <b>3 - C:</b> q đo bằng Coulomb (C).<br>• <b>4 - B:</b> Lực F đo bằng Newton (N).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong một hệ cô lập về điện, tổng đại số các điện tích luôn là một  [ ... ] . Khi cho hai quả cầu kim loại tích điện q₁ và q₂ tiếp xúc nhau rồi tách ra, điện tích trên mỗi quả cầu sau khi tiếp xúc là  [ ... ] . Nếu trước khi tiếp xúc một quả cầu tích điện âm và một quả cầu trung hoà thì sau khi tách ra cả hai quả cầu đều tích điện  [ ... ] . Hiện tượng này được gọi là sự nhiễm điện do  [ ... ] .\"</i>","opts":["hằng số không đổi — q' = (q₁ + q₂)/2","không đổi","biến thiên tuần hoàn — hưởng ứng","q' = (q₁ + q₂)/2 — hằng số không đổi"],"ans":0,"exp":"<b>Nhiễm điện do tiếp xúc và bảo toàn điện tích:</b><br>• Tổng điện tích bảo toàn: ∑q = const.<br>• Quả cầu giống nhau chia đều: q' = (q₁ + q₂)/2.<br>• Dấu điện tích sau tiếp xúc cùng dấu với tổng điện tích ban đầu.","svgGraph":null},{"q":"Hai quả cầu kim loại nhỏ giống hệt nhau mang điện tích q₁ = +6 μC và q₂ = -2 μC cho tiếp xúc nhau rồi tách ra. Điện tích trên mỗi quả cầu sau khi tách ra là:","opts":["+2 μC.","+4 μC.","-4 μC.","+8 μC."],"ans":"A","exp":"• <b>Công thức chia đều điện tích khi tiếp xúc:</b><br>q' = <span class=\"fraction\"><span class=\"numerator\">q₁ + q₂</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">+6 + (-2)</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">+4</span><span class=\"denominator\">2</span></span> = +2 μC.","svgGraph":null},{"q":"Đưa một thanh thuỷ tinh nhiễm điện dương lại gần (không chạm vào) một quả cầu kim loại trung hoà điện đang đặt trên giá cách điện. Phần mặt quả cầu gần thanh thuỷ tinh nhất sẽ:","opts":["Nhiễm điện âm do hiện tượng nhiễm điện hưởng ứng.","Nhiễm điện dương do nhận các ion dương từ thanh thuỷ tinh.","Không nhiễm điện vì không có sự tiếp xúc trực tiếp.","Nhiễm điện dương trên toàn bộ bề mặt quả cầu."],"ans":"A","exp":"• Thanh thuỷ tinh dương hút các electron tự do trong kim loại dồn về phía gần nó, làm đầu gần nhiễm điện âm còn đầu xa thiếu electron nên nhiễm điện dương. Đây là hiện tượng nhiễm điện do hưởng ứng.","svgGraph":null},{"q":"Hai điện tích điểm q₁ = +3 μC và q₂ = +12 μC đặt cố định tại hai điểm A và B cách nhau 30 cm trong không khí. Xét vị trí điểm M để lực tĩnh điện tổng hợp tác dụng lên điện tích thử q₀ đặt tại M bằng không: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Dấu và độ lớn của điện tích thử q₀ quyết định vị trí cân bằng của điểm M.","Điểm M phải nằm trên đoạn thẳng nối hai điện tích AB.","Khoảng cách từ điểm M đến điện tích q₁ là 10 cm.","Tại điểm M, hai vectơ lực tĩnh điện do q₁ và q₂ tác dụng lên q₀ là hai vectơ trực đối."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Vì q₁ và q₂ cùng dấu nên điểm M nằm giữa A và B.<br>• <b>Ý b [Đúng]:</b> E₁ = E₂ ⇒ q₁/r₁² = q₂/r₂² ⇒ r₂/r₁ = √(q₂/q₁) = √(12/3) = 2 ⇒ r₂ = 2r₁. Mà r₁ + r₂ = 30 cm ⇒ 3r₁ = 30 ⇒ r₁ = 10 cm.<br>• <b>Ý c [Sai]:</b> Vị trí cân bằng chỉ phụ thuộc vào q₁, q₂ và khoảng cách AB, hoàn toàn độc lập với q₀.<br>• <b>Ý d [Đúng]:</b> F<sub>hl</sub> = F₁ + F₂ = 0 ⇒ F₁ = -F₂ (hai lực trực đối).","svgGraph":null},{"q":"Hai điện tích điểm đặt cách nhau một khoảng r trong chân không thì hút nhau một lực F = 16·10⁻⁵ N. Nếu đặt chúng trong dầu hoả có hằng số điện môi ε = 2 và giữ nguyên khoảng cách r thì lực hút giữa chúng là:","opts":["8·10⁻⁵ N.","32·10⁻⁵ N.","4·10⁻⁵ N.","16·10⁻⁵ N."],"ans":"A","exp":"• <b>Quan hệ lực trong điện môi:</b> F' = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">ε</span></span><br>• <b>Thay số:</b> F' = <span class=\"fraction\"><span class=\"numerator\">16·10⁻⁵</span><span class=\"denominator\">2</span></span> = 8·10⁻⁵ N.","svgGraph":null}],"17":[{"q":"Điện trường là:","opts":["Dạng vật chất bao quanh điện tích và truyền tương tác điện lên các điện tích khác đặt trong nó.","Môi trường chỉ xuất hiện xung quanh các dây dẫn có dòng điện chạy qua.","Không gian chân không hoàn toàn không có bất kì hạt vật chất nào tồn tại.","Trường hấp dẫn do khối lượng của các hạt mang điện sinh ra xung quanh nó."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Điện trường là một dạng vật chất đặc biệt bao quanh các điện tích, gắn liền với điện tích và truyền tương tác giữa các điện tích thông qua lực điện trường tác dụng lên điện tích đặt trong nó.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr17\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Central positive charge -->\n      <circle cx=\"250\" cy=\"120\" r=\"22\" fill=\"#ef4444\" stroke=\"#fca5a5\" stroke-width=\"2.5\"/>\n      <text x=\"242\" y=\"128\" fill=\"#ffffff\" font-size=\"24\" font-weight=\"bold\">+</text>\n      <text x=\"240\" y=\"160\" fill=\"#f87171\" font-size=\"13\" font-weight=\"bold\">Q > 0</text>\n      <!-- Electric field lines radiating outward -->\n      <line x1=\"250\" y1=\"95\" x2=\"250\" y2=\"25\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"250\" y1=\"145\" x2=\"250\" y2=\"215\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"225\" y1=\"120\" x2=\"155\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"275\" y1=\"120\" x2=\"345\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"233\" y1=\"103\" x2=\"183\" y2=\"53\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"267\" y1=\"103\" x2=\"317\" y2=\"53\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"233\" y1=\"137\" x2=\"183\" y2=\"187\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <line x1=\"267\" y1=\"137\" x2=\"317\" y2=\"187\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr17)\"/>\n      <!-- Label test point M -->\n      <circle cx=\"345\" cy=\"120\" r=\"4\" fill=\"#34d399\"/>\n      <text x=\"355\" y=\"125\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Điểm M</text>\n      <text x=\"355\" y=\"140\" fill=\"#fbbf24\" font-size=\"11\">Véctơ E hướng xa Q dương</text>\n      <text x=\"135\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Đường sức điện trường của một điện tích điểm dương</text>\n    </svg>"},{"q":"Cường độ điện trường tại một điểm là đại lượng đặc trưng cho điện trường về:","opts":["Phương diện tác dụng lực và được xác định bằng thương số F/q.","Khả năng dự trữ thế năng điện của không gian.","Tốc độ truyền dao động điện từ trong chân không.","Số lượng hạt mang điện có trong một đơn vị thể tích."],"ans":"A","exp":"• <b>Định nghĩa vectơ cường độ điện trường:</b> E = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">q</span></span>.<br>• Cường độ điện trường đặc trưng cho tác dụng lực của điện trường tại điểm khảo sát, có đơn vị là V/m hoặc N/C.","svgGraph":null},{"q":"Một điện tích thử q = +2·10⁻⁸ C đặt tại một điểm trong điện trường chịu tác dụng của lực điện có độ lớn F = 6·10⁻⁴ N. Cường độ điện trường tại điểm đó có độ lớn là:","opts":["30000 V/m.","12000 V/m.","300 V/m.","60000 V/m."],"ans":"A","exp":"• <b>Công thức cường độ điện trường:</b> E = <span class=\"fraction\"><span class=\"numerator\">F</span><span class=\"denominator\">q</span></span><br>• <b>Thay số:</b> E = <span class=\"fraction\"><span class=\"numerator\">6·10⁻⁴</span><span class=\"denominator\">2·10⁻⁸</span></span> = 3·10⁴ V/m = 30000 V/m.","svgGraph":null},{"q":"Về vectơ cường độ điện trường và đường sức điện, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Các đường sức điện trường là những đường cong khép kín xuất phát từ vô cực và kết thúc tại vô cực.","Vectơ cường độ điện trường tại một điểm luôn cùng hướng với lực điện tác dụng lên điện tích thử dương đặt tại điểm đó.","Nơi nào điện trường mạnh thì các đường sức điện vẽ mau (dày), nơi nào điện trường yếu thì vẽ thưa.","Đường sức điện xuất phát từ điện tích dương (hoặc ở vô cực) và kết thúc ở điện tích âm (hoặc ở vô cực)."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F = qE, nếu q > 0 thì F và E cùng hướng.<br>• <b>Ý b [Sai]:</b> Đường sức điện trường tĩnh là đường không khép kín (bắt đầu từ (+) kết thúc ở (-)).<br>• <b>Ý c [Đúng]:</b> Quy ước độ mau thưa biểu thị độ lớn cường độ điện trường E.<br>• <b>Ý d [Đúng]:</b> Chiều đường sức từ điện tích dương ra xa, hướng vào điện tích âm.","svgGraph":null},{"q":"Ghép dạng điện tích ở Cột A với hình dạng của các đường sức điện tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Một điện tích điểm dương cô lập ➔ Các đường thẳng song song, cách đều nhau (điện trường đều)","Một điện tích điểm dương cô lập ➔ Các đường cong đi ra từ điện tích dương và đi vào điện tích âm","Một điện tích điểm âm cô lập ➔ Các đường thẳng song song, cách đều nhau (điện trường đều)","Hệ hai điện tích điểm trái dấu bằng nhau ➔ Các đường cong đi ra từ điện tích dương và đi vào điện tích âm"],"ans":0,"exp":"• <b>1 - C:</b> Q(+) tia thẳng phân kì hướng ra xa.<br>• <b>2 - D:</b> Q(-) tia thẳng hội tụ hướng vào.<br>• <b>3 - B:</b> Hai điện tích trái dấu đường cong nối từ (+) sang (-).<br>• <b>4 - A:</b> Giữa 2 bản phẳng song song là đường thẳng song song cách đều.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Nếu tại một điểm có nhiều điện trường do các điện tích điểm q₁, q₂, ... độc lập gây ra, thì vectơ cường độ điện trường tổng hợp bằng  [ ... ]  các vectơ cường độ điện trường thành phần. Nếu hai vectơ điện trường thành phần cùng hướng thì độ lớn điện trường tổng hợp bằng  [ ... ] . Nếu hai vectơ ngược hướng thì độ lớn bằng  [ ... ] . Nếu hai vectơ vuông góc nhau thì độ lớn tính theo  [ ... ] .\"</i>","opts":["tổng vectơ — E₁ + E₂","không đổi","hiệu vectơ — tích đại số","E₁ + E₂ — tổng vectơ"],"ans":0,"exp":"<b>Nguyên lí chồng chất điện trường:</b><br>• E = E₁ + E₂ + ...<br>• Cùng chiều: E = E₁ + E₂.<br>• Ngược chiều: E = |E₁ - E₂|.<br>• Vuông góc: E = √(E₁² + E₂²).","svgGraph":null},{"q":"Cường độ điện trường do một điện tích điểm Q = +4·10⁻⁹ C gây ra tại một điểm cách nó r = 10 cm trong không khí (hằng số k = 9·10⁹ N·m²/C²) là:","opts":["3600 V/m.","360 V/m.","1800 V/m.","7200 V/m."],"ans":"A","exp":"• <b>Công thức điện trường của điện tích điểm:</b> E = k·<span class=\"fraction\"><span class=\"numerator\">|Q|</span><span class=\"denominator\">r²</span></span><br>• <b>Thay số:</b> E = 9·10⁹ · <span class=\"fraction\"><span class=\"numerator\">4·10⁻⁹</span><span class=\"denominator\">(0,1)²</span></span> = <span class=\"fraction\"><span class=\"numerator\">36</span><span class=\"denominator\">0,01</span></span> = 3600 V/m.","svgGraph":null},{"q":"Khi một electron chuyển động tự do không vận tốc ban đầu trong một điện trường đều, dưới tác dụng duy nhất của lực điện, electron sẽ chuyển động:","opts":["Nhanh dần đều ngược hướng với các đường sức điện trường.","Nhanh dần đều cùng hướng với các đường sức điện trường.","Chậm dần đều ngược hướng với các đường sức điện trường.","Thẳng đều theo hướng bất kì."],"ans":"A","exp":"• Electron mang điện tích âm (q = -e < 0) nên lực điện tác dụng lên nó F = qE ngược hướng với vectơ điện trường E.<br>• Do đó electron chuyển động nhanh dần đều ngược chiều đường sức điện.","svgGraph":null},{"q":"Tại hai điểm A và B cách nhau 20 cm trong chân không, đặt hai điện tích điểm cùng dấu q₁ = q₂ = +2·10⁻⁸ C. Xét cường độ điện trường tại trung điểm O của đoạn AB: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu thay điện tích q₂ bằng một điện tích âm có cùng độ lớn (-2·10⁻⁸ C) thì điện trường tại O vẫn triệt tiêu.","Cường độ điện trường do q₁ gây ra tại O có độ lớn bằng 18000 V/m.","Hai vectơ cường độ điện trường do q₁ và q₂ gây ra tại O có chiều đối nghịch nhau.","Cường độ điện trường tổng hợp tại trung điểm O triệt tiêu bằng không."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> r = 0,1 m ⇒ E₁ = 9·10⁹ · 2·10⁻⁸ / 0,1² = 18000 V/m.<br>• <b>Ý b [Đúng]:</b> Cả hai đều dương nên cùng hướng ra xa hai điện tích ⇒ tại O hai vectơ ngược chiều.<br>• <b>Ý c [Đúng]:</b> E<sub>O</sub> = E₁ - E₂ = 18000 - 18000 = 0.<br>• <b>Ý d [Sai]:</b> Nếu q₂ âm thì E₂ cùng hướng với E₁ ⇒ E<sub>O</sub> = E₁ + E₂ = 36000 V/m (không triệt tiêu).","svgGraph":null},{"q":"Cường độ điện trường do điện tích điểm Q gây ra tại điểm M cách nó một khoảng r là E. Nếu khoảng cách từ điện tích đến điểm khảo sát giảm đi 2 lần thì cường độ điện trường tại đó sẽ:","opts":["Tăng lên 4 lần.","Giảm đi 4 lần.","Tăng lên 2 lần.","Giảm đi 2 lần."],"ans":"A","exp":"• <b>Công thức:</b> E = k·<span class=\"fraction\"><span class=\"numerator\">|Q|</span><span class=\"denominator\">r²</span></span><br>• E tỉ lệ nghịch với bình phương khoảng cách r². Khi r giảm 2 lần thì r² giảm 4 lần ⇒ E tăng lên 4 lần.","svgGraph":null}],"18":[{"q":"Điện trường đều là điện trường có vectơ cường độ điện trường tại mọi điểm đều:","opts":["Cùng phương, cùng chiều và có độ lớn bằng nhau.","Có độ lớn bằng nhau nhưng phương chiều biến thiên liên tục theo không gian.","Đồng quy về một điểm cố định trong không gian.","Thay đổi độ lớn theo thời gian theo quy luật hàm sin."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Điện trường đều là điện trường mà vectơ cường độ điện trường tại mọi điểm đều có cùng phương, cùng chiều và cùng độ lớn; các đường sức điện là những đường thẳng song song cách đều nhau.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr18\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Positive top plate -->\n      <rect x=\"70\" y=\"40\" width=\"360\" height=\"15\" fill=\"#ef4444\" rx=\"3\"/>\n      <text x=\"50\" y=\"52\" fill=\"#ef4444\" font-size=\"16\" font-weight=\"bold\">+</text>\n      <text x=\"440\" y=\"52\" fill=\"#f87171\" font-size=\"12\">Bản dương (+)</text>\n      <!-- Negative bottom plate -->\n      <rect x=\"70\" y=\"185\" width=\"360\" height=\"15\" fill=\"#3b82f6\" rx=\"3\"/>\n      <text x=\"50\" y=\"197\" fill=\"#3b82f6\" font-size=\"20\" font-weight=\"bold\">-</text>\n      <text x=\"440\" y=\"197\" fill=\"#60a5fa\" font-size=\"12\">Bản âm (-)</text>\n      <!-- Uniform electric field lines going downward -->\n      <line x1=\"120\" y1=\"58\" x2=\"120\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"180\" y1=\"58\" x2=\"180\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"240\" y1=\"58\" x2=\"240\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"300\" y1=\"58\" x2=\"300\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <line x1=\"360\" y1=\"58\" x2=\"360\" y2=\"182\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arr18)\"/>\n      <!-- Trajectory of electron moving into field -->\n      <path d=\"M 80,140 Q 180,140 260,70\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <circle cx=\"260\" cy=\"70\" r=\"5\" fill=\"#fbbf24\"/>\n      <text x=\"270\" y=\"70\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">Quỹ đạo hạt (Parabol)</text>\n      <text x=\"245\" y=\"115\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">E</text>\n      <text x=\"140\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Điện trường đều giữa hai bản tụ điện phẳng song song</text>\n    </svg>"},{"q":"Hệ thức liên hệ giữa hiệu điện thế U và cường độ điện trường E trong điện trường đều là:","opts":["U = E·d (với d là hình chiếu của độ dịch chuyển lên phương đường sức).","U = E / d.","E = U·d.","U = E·d²."],"ans":"A","exp":"• <b>Mối liên hệ giữa U và E:</b> E = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">d</span></span> hay U = E·d, trong đó d là khoảng cách giữa hai mặt đẳng thế đo dọc theo đường sức.","svgGraph":null},{"q":"Hai bản kim loại phẳng rộng đặt song song cách nhau d = 2 cm, được nối với nguồn điện có hiệu điện thế U = 100 V. Cường độ điện trường đều giữa hai bản có độ lớn là:","opts":["5000 V/m.","200 V/m.","50 V/m.","2500 V/m."],"ans":"A","exp":"• <b>Công thức:</b> E = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">d</span></span><br>• <b>Thay số với d = 2 cm = 0,02 m:</b> E = <span class=\"fraction\"><span class=\"numerator\">100</span><span class=\"denominator\">0,02</span></span> = 5000 V/m.","svgGraph":null},{"q":"Một hạt mang điện tích q bay vào vùng không gian có điện trường đều giữa hai bản kim loại phẳng đặt nằm ngang với vận tốc ban đầu v₀ theo phương song song với hai bản. Bỏ qua trọng lực. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu đảo ngược dấu của điện tích q thì độ lệch của hạt về phía bản nhiễm điện trái dấu sẽ bị triệt tiêu hoàn toàn.","Theo phương ngang (trục Ox song song với các bản), hạt chuyển động thẳng đều với vận tốc không đổi v<sub>x</sub> = v₀.","Theo phương thẳng đứng (trục Oy vuông góc với các bản), lực điện F = qE gây ra cho hạt một gia tốc không đổi a = |q|E / m.","Quỹ đạo chuyển động của hạt điện tích trong điện trường đều có dạng một nhánh của đường parabol."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> F<sub>x</sub> = 0 ⇒ a<sub>x</sub> = 0 ⇒ v<sub>x</sub> = v₀ (thẳng đều).<br>• <b>Ý b [Đúng]:</b> F<sub>y</sub> = qE ⇒ a<sub>y</sub> = |q|E/m = const (biến đổi đều).<br>• <b>Ý c [Đúng]:</b> y = (a<sub>y</sub> / 2v₀²)·x² là phương trình parabol.<br>• <b>Ý d [Sai]:</b> Đổi dấu q thì chiều lệch đảo ngược (hạt lệch về phía bản đối diện), chứ không hề bị triệt tiêu quỹ đạo lệch.","svgGraph":null},{"q":"Ghép đại lượng hoặc đặc điểm ở Cột A với biểu thức tương ứng trong chuyển động của hạt tích điện bay ngang vào điện trường đều ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Gia tốc chuyển động theo phương thẳng đứng a<sub>y</sub> ➔ y = (a<sub>y</sub> / 2) · (L / v₀)²","Gia tốc chuyển động theo phương thẳng đứng a<sub>y</sub> ➔ v<sub>x</sub> = v₀ (không đổi)","Vận tốc theo phương ngang v<sub>x</sub> ➔ y = (a<sub>y</sub> / 2) · (L / v₀)²","Phương trình quỹ đạo y(x) ➔ v<sub>x</sub> = v₀ (không đổi)"],"ans":0,"exp":"• <b>1 - C:</b> a<sub>y</sub> = |q|E/m.<br>• <b>2 - B:</b> Phương ngang v<sub>x</sub> = v₀.<br>• <b>3 - D:</b> y = [|q|E / (2mv₀²)]·x².<br>• <b>4 - A:</b> Thay x = L ta được y = 1/2·a<sub>y</sub>·(L/v₀)².","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong máy lọc bụi tĩnh điện, bụi bẩn đi qua vùng điện trường mạnh bị  [ ... ]  hoá và tích điện. Dưới tác dụng của  [ ... ] , các hạt bụi bị hút về các điện cực gom bụi trái dấu. Trong ống phóng tia điện tử của máy hiện sóng, điện trường đều giữa các bản lái tia dùng để  [ ... ]  chùm electron quét trên màn huỳnh quang. Nguyên tắc chuyển động của hạt mang điện trong điện trường đều tương tự như chuyển động ném ngang trong  [ ... ] .\"</i>","opts":["ion — lực điện trường","không đổi","từ trường — trung hoà","lực điện trường — ion"],"ans":0,"exp":"<b>Ứng dụng điện trường đều:</b><br>• Lọc bụi tĩnh điện ion hoá bụi, lực điện hút bụi.<br>• Ống tia âm cực (CRT) bẻ lái chùm tia e.<br>• Tương tự chuyển động ném ngang trong trường trọng lực.","svgGraph":null},{"q":"Một quả cầu nhỏ tích điện q = +10⁻⁶ C có khối lượng m = 1 g được treo bởi một sợi dây mảnh cách điện trong điện trường đều có phương nằm ngang. Khi quả cầu cân bằng, dây treo lệch góc α = 45° so với phương thẳng đứng. Lấy g = 10 m/s². Độ lớn cường độ điện trường E là:","opts":["10⁴ V/m.","10⁵ V/m.","10³ V/m.","2·10⁴ V/m."],"ans":"A","exp":"• <b>Điều kiện cân bằng:</b> tan(α) = <span class=\"fraction\"><span class=\"numerator\">F<sub>d</sub></span><span class=\"denominator\">P</span></span> = <span class=\"fraction\"><span class=\"numerator\">qE</span><span class=\"denominator\">mg</span></span><br>• Với α = 45° ⇒ tan(45°) = 1 ⇒ qE = mg.<br>• Thay số: E = <span class=\"fraction\"><span class=\"numerator\">mg</span><span class=\"denominator\">q</span></span> = <span class=\"fraction\"><span class=\"numerator\">10⁻³ · 10</span><span class=\"denominator\">10⁻⁶</span></span> = 10⁴ V/m.","svgGraph":null},{"q":"Một điện tích q = -2 μC dịch chuyển dọc theo một đường sức của điện trường đều từ điểm M đến điểm N cách nhau 10 cm theo chiều đường sức. Biết E = 1000 V/m. Công của lực điện trường thực hiện là:","opts":["-2·10⁻⁴ J.","+2·10⁻⁴ J.","-2·10⁻² J.","+2·10⁻² J."],"ans":"A","exp":"• <b>Công thức tính công của lực điện:</b> A = q·E·d<br>• Vì đi cùng chiều đường sức nên d = +10 cm = +0,1 m.<br>• <b>Thay số:</b> A = (-2·10⁻⁶) · 1000 · 0,1 = -2·10⁻⁴ J (công cản).","svgGraph":null},{"q":"Trong điện trường đều giữa hai bản kim loại nằm ngang nhiễm điện trái dấu có cường độ E = 20000 V/m, một hạt bụi mang điện tích q = -1,6·10⁻¹⁵ C nằm lơ lửng cân bằng. Lấy g = 10 m/s². Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu ngắt nguồn điện và giữ nguyên điện tích trên bản thì hạt bụi sẽ rơi tự do xuống dưới.","Lực điện tác dụng lên hạt bụi có hướng thẳng đứng lên trên để cân bằng với trọng lực.","Bản kim loại phía trên phải là bản tích điện dương và bản phía dưới tích điện âm.","Khối lượng của hạt bụi là m = 3,2·10⁻¹² kg."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Hạt bụi lơ lửng cân bằng thì F<sub>d</sub> = P hướng thẳng đứng lên trên.<br>• <b>Ý b [Đúng]:</b> Vì q < 0 nên lực điện F ngược hướng với E ⇒ E phải hướng xuống dưới ⇒ bản trên dương, bản dưới âm.<br>• <b>Ý c [Đúng]:</b> P = mg = |q|E ⇒ m = |q|E/g = (1,6·10⁻¹⁵ · 20000) / 10 = 3,2·10⁻¹² kg.<br>• <b>Ý d [Sai]:</b> Giữ nguyên điện tích trên bản thì điện trường E giữa hai bản không đổi, hạt bụi vẫn lơ lửng cân bằng.","svgGraph":null},{"q":"Hai điểm M và N nằm trên cùng một đường sức của điện trường đều có cường độ E = 400 V/m. Đoạn MN dài 5 cm và vectơ MN cùng chiều với đường sức điện. Hiệu điện thế U<sub>MN</sub> bằng:","opts":["20 V.","-20 V.","80 V.","2000 V."],"ans":"A","exp":"• <b>Công thức:</b> U<sub>MN</sub> = E·d<sub>MN</sub><br>• Vì cùng chiều đường sức nên d<sub>MN</sub> = +5 cm = +0,05 m.<br>• Thay số: U<sub>MN</sub> = 400 · 0,05 = 20 V.","svgGraph":null}],"19":[{"q":"Công của lực điện trường khi dịch chuyển một điện tích q từ điểm M đến điểm N trong điện trường tĩnh:","opts":["Chỉ phụ thuộc vào vị trí điểm đầu M và điểm cuối N, không phụ thuộc vào hình dạng đường đi.","Tỉ lệ thuận với chiều dài thực tế của quỹ đạo dịch chuyển giữa hai điểm.","Luôn luôn bằng không đối với mọi quỹ đạo cong bất kì trong điện trường.","Phụ thuộc chặt chẽ vào thời gian và vận tốc dịch chuyển của điện tích."],"ans":"A","exp":"• <b>Tính chất trường thế:</b> Lực điện trường là lực thế (trường tĩnh điện là trường thế). Công của lực điện trường khi làm điện tích di chuyển giữa hai điểm không phụ thuộc hình dạng đường đi mà chỉ phụ thuộc vị trí điểm đầu và điểm cuối.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Uniform electric field background lines -->\n      <line x1=\"60\" y1=\"50\" x2=\"440\" y2=\"50\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n      <line x1=\"60\" y1=\"120\" x2=\"440\" y2=\"120\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n      <line x1=\"60\" y1=\"190\" x2=\"440\" y2=\"190\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n      <!-- Start point M and End point N -->\n      <circle cx=\"120\" cy=\"120\" r=\"7\" fill=\"#ef4444\"/>\n      <text x=\"110\" y=\"145\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">M</text>\n      <circle cx=\"380\" cy=\"120\" r=\"7\" fill=\"#3b82f6\"/>\n      <text x=\"385\" y=\"145\" fill=\"#3b82f6\" font-size=\"14\" font-weight=\"bold\">N</text>\n      <!-- Path 1: Straight line -->\n      <line x1=\"120\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n      <text x=\"230\" y=\"110\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Đường đi (1) thẳng</text>\n      <!-- Path 2: Curved line -->\n      <path d=\"M 120,120 Q 250,30 380,120\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <text x=\"210\" y=\"45\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Đường đi (2) cong</text>\n      <!-- Path 3: Zigzag -->\n      <path d=\"M 120,120 L 200,190 L 300,170 L 380,120\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"220\" y=\"205\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Đường đi (3) gấp khúc</text>\n      <!-- Conclusion -->\n      <text x=\"145\" y=\"228\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">A₍₁₎ = A₍₂₎ = A₍₃₎ = q·E·d</text>\n    </svg>"},{"q":"Thế năng điện W<sub>M</sub> của một điện tích q tại điểm M trong điện trường đặc trưng cho:","opts":["Khả năng sinh công của điện trường khi đặt điện tích q tại điểm M.","Tốc độ chuyển động của điện tích khi đi qua điểm M.","Nhiệt lượng toả ra khi điện tích phóng tia lửa điện.","Điện dung của vật dẫn chứa điện tích q."],"ans":"A","exp":"• <b>Định nghĩa thế năng điện:</b> Thế năng của một điện tích q tại điểm M trong điện trường đặc trưng cho khả năng sinh công của điện trường khi dịch chuyển điện tích q từ điểm M ra vô cực (hoặc về mốc thế năng quy ước): W<sub>M</sub> = A<sub>M</sub>∞.","svgGraph":null},{"q":"Mối liên hệ giữa công của lực điện trường A<sub>MN</sub> và độ giảm thế năng điện (W<sub>M</sub> - W<sub>N</sub>) là:","opts":["A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub>.","A<sub>MN</sub> = W<sub>N</sub> - W<sub>M</sub>.","A<sub>MN</sub> = W<sub>M</sub> + W<sub>N</sub>.","A<sub>MN</sub> = (W<sub>M</sub> - W<sub>N</sub>)/2."],"ans":"A","exp":"• <b>Định lí thế năng:</b> Công của lực điện trường khi điện tích dịch chuyển từ M đến N bằng độ giảm thế năng điện của điện tích giữa hai điểm đó: A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub>.","svgGraph":null},{"q":"Một electron dịch chuyển từ điểm M có thế năng W<sub>M</sub> = -3,2·10⁻¹⁸ J đến điểm N có thế năng W<sub>N</sub> = -6,4·10⁻¹⁸ J trong điện trường. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu electron chuyển động theo một đường cong kín quay trở lại điểm M thì tổng công của lực điện trường là khác không.","Độ giảm thế năng điện giữa hai điểm là ΔW = +3,2·10⁻¹⁸ J.","Công của lực điện trường thực hiện trong quá trình dịch chuyển này là A<sub>MN</sub> = +3,2·10⁻¹⁸ J.","Lực điện trường sinh công phát động làm động năng của electron tăng lên."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> W<sub>M</sub> - W<sub>N</sub> = (-3,2·10⁻¹⁸) - (-6,4·10⁻¹⁸) = +3,2·10⁻¹⁸ J.<br>• <b>Ý b [Đúng]:</b> A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub> = +3,2·10⁻¹⁸ J.<br>• <b>Ý c [Đúng]:</b> A > 0 là công phát động, theo định lí động năng: ΔW<sub>đ</sub> = A > 0 nên động năng tăng.<br>• <b>Ý d [Sai]:</b> Lực thế có công trên quỹ đạo kín luôn bằng không (A<sub>v</sub>òng = 0).","svgGraph":null},{"q":"Ghép khái niệm ở Cột A với biểu thức hoặc tính chất tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Thế năng điện tại điểm M (mốc ở vô cực) ➔ A<sub>MN</sub> = q·E·d","Thế năng điện tại điểm M (mốc ở vô cực) ➔ W<sub>M</sub> = A<sub>M</sub>∞ = q·V<sub>M</sub>","Công của lực điện trên đường kín ➔ A<sub>MN</sub> = q·E·d","Định lí thế năng điện ➔ W<sub>M</sub> = A<sub>M</sub>∞ = q·V<sub>M</sub>"],"ans":0,"exp":"• <b>1 - B:</b> W<sub>M</sub> = A<sub>M</sub>∞ = q·V<sub>M</sub>.<br>• <b>2 - C:</b> Trường thế trên đường cong kín công bằng 0.<br>• <b>3 - D:</b> Công bằng độ giảm thế năng: A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub>.<br>• <b>4 - A:</b> Trong điện trường đều: A = qEd.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi một hạt mang điện chuyển động trong điện trường chỉ chịu tác dụng của lực điện thì cơ năng của hạt gồm tổng  [ ... ]  và  [ ... ]  là một đại lượng bảo toàn. Khi điện thế tại một điểm tăng lên thì thế năng của điện tích âm sẽ  [ ... ] . Khi động năng của hạt giảm đi bao nhiêu thì thế năng của hạt sẽ  [ ... ]  bấy nhiêu.\"</i>","opts":["động năng — thế năng điện","không đổi","nội năng — không đổi","thế năng điện — động năng"],"ans":0,"exp":"<b>Bảo toàn cơ năng điện:</b><br>• Cơ năng: W = W<sub>đ</sub> + W<sub>t</sub> = const.<br>• W<sub>t</sub> = qV, với q < 0 thì V tăng làm W<sub>t</sub> giảm.<br>• W<sub>đ</sub> giảm thì W<sub>t</sub> tăng tương ứng.","svgGraph":null},{"q":"Một điện tích q = +5 μC dịch chuyển từ điểm M đến điểm N trong một điện trường, lực điện thực hiện một công A<sub>MN</sub> = 2·10⁻³ J. Nếu chọn mốc thế năng tại điểm N (W<sub>N</sub> = 0) thì thế năng điện tại M là:","opts":["2·10⁻³ J.","-2·10⁻³ J.","4·10⁻³ J.","10⁻³ J."],"ans":"A","exp":"• <b>Công thức độ giảm thế năng:</b> A<sub>MN</sub> = W<sub>M</sub> - W<sub>N</sub><br>• Với W<sub>N</sub> = 0 ⇒ W<sub>M</sub> = A<sub>MN</sub> = 2·10⁻³ J.","svgGraph":null},{"q":"Một proton (điện tích q = +1,6·10⁻¹⁹ C, khối lượng m = 1,67·10⁻²⁷ kg) được tăng tốc từ trạng thái nghỉ bởi hiệu điện thế U = 1000 V. Động năng mà proton thu được sau khi tăng tốc là:","opts":["1,6·10⁻¹⁶ J.","3,2·10⁻¹⁶ J.","1,6·10⁻¹⁹ J.","8,0·10⁻¹⁷ J."],"ans":"A","exp":"• <b>Định lí động năng:</b> W<sub>đ</sub> - 0 = A = q·U<br>• <b>Thay số:</b> W<sub>đ</sub> = 1,6·10⁻¹⁹ · 1000 = 1,6·10⁻¹⁶ J (tương đương 1 keV).","svgGraph":null},{"q":"Thả nhẹ một ion âm từ trạng thái nghỉ tại một điểm trong điện trường bất kì. Bỏ qua trọng lực và mọi lực ma sát. Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tốc độ của ion âm tại mọi thời điểm tỉ lệ nghịch với khối lượng của nó.","Ion âm sẽ tự động chuyển động từ nơi có điện thế thấp sang nơi có điện thế cao.","Trong quá trình chuyển động tự do, thế năng điện của ion âm sẽ giảm dần.","Động năng của ion âm tăng dần do lực điện trường sinh công dương."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Lực tác dụng F = qE ngược chiều E (hướng từ nơi thế cao về nơi thế thấp) ⇒ ion âm bay về phía nơi điện thế cao.<br>• <b>Ý b [Đúng]:</b> Dưới tác dụng lực thế tự do, thế năng luôn giảm (W<sub>t</sub> giảm).<br>• <b>Ý c [Đúng]:</b> Lực điện sinh công dương làm động năng tăng (W<sub>đ</sub> tăng).<br>• <b>Ý d [Sai]:</b> v = √(2qU/m) tỉ lệ nghịch với căn bậc hai của khối lượng (√m) chứ không phải tỉ lệ nghịch với m.","svgGraph":null},{"q":"Đơn vị đo thế năng điện trong hệ SI là:","opts":["Joule (J).","Volt (V).","Coulomb (C).","Newton (N)."],"ans":"A","exp":"• Thế năng là một dạng năng lượng, do đó đơn vị chuẩn của nó trong hệ SI là Joule (J).","svgGraph":null}],"20":[{"q":"Điện thế tại một điểm M trong điện trường là đại lượng đặc trưng cho điện trường về:","opts":["Khả năng tạo ra thế năng khi đặt tại đó một điện tích q và được xác định bằng V<sub>M</sub> = W<sub>M</sub> / q.","Tác dụng lực tác dụng lên một đơn vị điện tích thử đặt tại điểm đó.","Khả năng tích luỹ điện tích của một tụ điện phẳng.","Tốc độ truyền dòng điện chạy trong dây dẫn kim loại."],"ans":"A","exp":"• <b>Định nghĩa điện thế SGK:</b> Điện thế tại điểm M đặc trưng cho điện trường về phương diện tạo ra thế năng: V<sub>M</sub> = <span class=\"fraction\"><span class=\"numerator\">W<sub>M</sub></span><span class=\"denominator\">q</span></span> = <span class=\"fraction\"><span class=\"numerator\">A<sub>M</sub>∞</span><span class=\"denominator\">q</span></span>. Đơn vị là Volt (V).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr20\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Equipotential surfaces (circles around Q+) -->\n      <circle cx=\"150\" cy=\"120\" r=\"18\" fill=\"#ef4444\"/>\n      <text x=\"143\" y=\"127\" fill=\"#ffffff\" font-size=\"20\" font-weight=\"bold\">+</text>\n      <text x=\"140\" y=\"155\" fill=\"#f87171\" font-size=\"12\">Q > 0</text>\n      <!-- Equipotential lines -->\n      <circle cx=\"150\" cy=\"120\" r=\"45\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"180\" y=\"70\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">V₁ = 30 V</text>\n      <circle cx=\"150\" cy=\"120\" r=\"75\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"215\" y=\"55\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">V₂ = 20 V</text>\n      <circle cx=\"150\" cy=\"120\" r=\"105\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"245\" y=\"40\" fill=\"#60a5fa\" font-size=\"11\" font-weight=\"bold\">V₃ = 10 V</text>\n      <!-- Electric field arrow perpendicular to equipotential -->\n      <line x1=\"150\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr20)\"/>\n      <text x=\"320\" y=\"110\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Vectơ E</text>\n      <text x=\"290\" y=\"145\" fill=\"#94a3b8\" font-size=\"11\">E hướng từ nơi thế cao (30V) sang nơi thế thấp (10V)</text>\n      <text x=\"130\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\">Mặt đẳng thế và hướng giảm của điện thế theo vectơ E</text>\n    </svg>"},{"q":"Hiệu điện thế giữa hai điểm M và N trong điện trường là:","opts":["U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub>.","U<sub>MN</sub> = V<sub>M</sub> + V<sub>N</sub>.","U<sub>MN</sub> = V<sub>N</sub> - V<sub>M</sub>.","U<sub>MN</sub> = V<sub>M</sub> / V<sub>N</sub>."],"ans":"A","exp":"• <b>Định nghĩa hiệu điện thế:</b> Hiệu điện thế giữa hai điểm M và N là hiệu số điện thế giữa M và N: U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub> = A<sub>MN</sub> / q.","svgGraph":null},{"q":"Khi dịch chuyển một điện tích q = +4·10⁻⁶ C từ điểm M đến điểm N trong điện trường, lực điện thực hiện một công A<sub>MN</sub> = 8·10⁻⁴ J. Hiệu điện thế U<sub>MN</sub> giữa hai điểm đó là:","opts":["200 V.","3200 V.","50 V.","400 V."],"ans":"A","exp":"• <b>Công thức hiệu điện thế:</b> U<sub>MN</sub> = <span class=\"fraction\"><span class=\"numerator\">A<sub>MN</sub></span><span class=\"denominator\">q</span></span><br>• <b>Thay số:</b> U<sub>MN</sub> = <span class=\"fraction\"><span class=\"numerator\">8·10⁻⁴</span><span class=\"denominator\">4·10⁻⁶</span></span> = 200 V.","svgGraph":null},{"q":"Về mặt đẳng thế và mối liên hệ giữa điện thế với cường độ điện trường, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu điện thế tại mọi điểm trong một vùng không gian đều bằng nhau thì cường độ điện trường trong vùng đó có giá trị rất lớn.","Mặt đẳng thế là mặt tập hợp tất cả các điểm có cùng một giá trị điện thế.","Vectơ cường độ điện trường luôn luôn có phương vuông góc với mặt đẳng thế và hướng về phía điện thế giảm.","Công của lực điện trường khi dịch chuyển một điện tích trên cùng một mặt đẳng thế luôn bằng không."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Mặt đẳng thế là mặt có V = const.<br>• <b>Ý b [Đúng]:</b> E ⊥ mặt đẳng thế và E hướng từ nơi V cao sang nơi V thấp.<br>• <b>Ý c [Đúng]:</b> A = q·(V₁ - V₂) = q·0 = 0.<br>• <b>Ý d [Sai]:</b> V bằng nhau ⇒ hiệu điện thế giữa 2 điểm bất kì U = 0 ⇒ E = U/d = 0 (điện trường triệt tiêu chứ không phải rất lớn).","svgGraph":null},{"q":"Ghép các đại lượng ở Cột A với mối quan hệ công thức tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Hiệu điện thế U<sub>MN</sub> ➔ A<sub>MN</sub> = q·U<sub>MN</sub>","Hiệu điện thế U<sub>MN</sub> ➔ U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub>","Điện thế tại điểm M ➔ A<sub>MN</sub> = q·U<sub>MN</sub>","Mối liên hệ E và U trong điện trường đều ➔ U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub>"],"ans":0,"exp":"• <b>1 - B:</b> U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub>.<br>• <b>2 - C:</b> V<sub>M</sub> = A<sub>M</sub>∞ / q.<br>• <b>3 - D:</b> E = U/d.<br>• <b>4 - A:</b> A<sub>MN</sub> = q·U<sub>MN</sub>.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong kĩ thuật và đời sống thực tế, người ta thường chọn  [ ... ]  làm mốc điện thế chuẩn (có điện thế bằng 0 V). Thiết bị dùng để đo trực tiếp hiệu điện thế giữa hai điểm là  [ ... ] . Khi đo, thiết bị này được mắc  [ ... ]  với hai điểm cần đo. Đơn vị đo hiệu điện thế và điện thế là  [ ... ] .\"</i>","opts":["mặt đất (Trái Đất) — vôn kế (Voltmeter)","không đổi","nối tiếp — ampe kế","vôn kế (Voltmeter) — mặt đất (Trái Đất)"],"ans":0,"exp":"<b>Mốc điện thế và phép đo:</b><br>• Mốc đất: V<sub>đất</sub> = 0 V.<br>• Vôn kế đo hiệu điện thế.<br>• Vôn kế mắc song song với đoạn mạch cần đo.<br>• Đơn vị là Volt (V).","svgGraph":null},{"q":"Điện thế tại điểm M là V<sub>M</sub> = 15 V, điện thế tại điểm N là V<sub>N</sub> = 5 V. Một điện tích q = -1,5 C dịch chuyển từ M đến N. Công của lực điện trường thực hiện là:","opts":["-15 J.","+15 J.","-30 J.","+30 J."],"ans":"A","exp":"• <b>Bước 1: Tính hiệu điện thế U<sub>MN</sub>:</b><br>U<sub>MN</sub> = V<sub>M</sub> - V<sub>N</sub> = 15 - 5 = 10 V.<br>• <b>Bước 2: Tính công của lực điện A<sub>MN</sub>:</b><br>A<sub>MN</sub> = q·U<sub>MN</sub> = (-1,5) · 10 = -15 J.","svgGraph":null},{"q":"Một đám mây dông tích điện ở độ cao 1200 m so với mặt đất có điện thế V = -6·10⁷ V. Lấy mốc điện thế mặt đất bằng 0 V. Cường độ điện trường trung bình giữa đám mây và mặt đất xấp xỉ bằng:","opts":["5·10⁴ V/m.","5·10² V/m.","7,2·10¹⁰ V/m.","2·10⁴ V/m."],"ans":"A","exp":"• <b>Hiệu điện thế:</b> U = |V<sub>đất</sub> - V<sub>m</sub>ây| = 6·10⁷ V.<br>• <b>Cường độ điện trường:</b> E = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">d</span></span> = <span class=\"fraction\"><span class=\"numerator\">6·10⁷</span><span class=\"denominator\">1200</span></span> = 50000 V/m = 5·10⁴ V/m.","svgGraph":null},{"q":"Trong một vùng không gian có điện trường, ba điểm A, B, C tạo thành một tam giác vuông tại B với AB = 3 cm, BC = 4 cm. Đường sức điện trường song song với cạnh AB và hướng từ A đến B, E = 5000 V/m. Xét tính Đúng / Sai của các mệnh đề sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Hiệu điện thế giữa hai điểm A và B là U<sub>AB</sub> = 150 V.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> U<sub>AB</sub> = E·d<sub>AB</sub> = 5000 · 0,03 = 150 V.<br>• <b>Ý b [Đúng]:</b> BC ⊥ E ⇒ d<sub>BC</sub> = 0 ⇒ U<sub>BC</sub> = E·0 = 0 V.<br>• <b>Ý c [Đúng]:</b> U<sub>AC</sub> = U<sub>AB</sub> + U<sub>BC</sub> = 150 + 0 = 150 V.<br>• <b>Ý d [Đúng]:</b> Mọi điểm trên đoạn BC vuông góc với E đều có cùng điện thế nên thuộc mặt đẳng thế.","svgGraph":null},{"q":"Cho hai điểm M và N trong điện trường có điện thế lần lượt là V<sub>M</sub> = 40 V và V<sub>N</sub> = -10 V. Hiệu điện thế U<sub>NM</sub> giữa hai điểm đó bằng:","opts":["-50 V.","+50 V.","+30 V.","-30 V."],"ans":"A","exp":"• <b>Công thức:</b> U<sub>NM</sub> = V<sub>N</sub> - V<sub>M</sub> = -10 - 40 = -50 V. (Chú ý thứ tự chỉ số: U<sub>NM</sub> = -U<sub>MN</sub>).","svgGraph":null}],"21":[{"q":"Tụ điện là một hệ gồm:","opts":["Hai vật dẫn đặt gần nhau và ngăn cách nhau bằng một lớp chất điện môi.","Hai vật dẫn tiếp xúc trực tiếp với nhau để truyền dẫn dòng điện liên tục.","Một vật dẫn duy nhất được bao bọc trong một khối kim loại dày.","Hai chất bán dẫn ghép nối tiếp nhau tạo nên một điốt chỉnh lưu."],"ans":"A","exp":"• <b>Định nghĩa SGK:</b> Tụ điện là một hệ hai vật dẫn đặt gần nhau và ngăn cách nhau bởi một lớp cách điện (chất điện môi). Tụ điện dùng để tích và phóng điện tích.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Parallel plate capacitor -->\n      <!-- Plate 1 Left -->\n      <rect x=\"180\" y=\"40\" width=\"16\" height=\"150\" fill=\"#ef4444\" rx=\"3\"/>\n      <text x=\"183\" y=\"120\" fill=\"#ffffff\" font-size=\"14\" font-weight=\"bold\">+</text>\n      <text x=\"135\" y=\"120\" fill=\"#f87171\" font-size=\"12\" font-weight=\"bold\">+Q</text>\n      <!-- Plate 2 Right -->\n      <rect x=\"290\" y=\"40\" width=\"16\" height=\"150\" fill=\"#3b82f6\" rx=\"3\"/>\n      <text x=\"294\" y=\"120\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"bold\">-</text>\n      <text x=\"315\" y=\"120\" fill=\"#60a5fa\" font-size=\"12\" font-weight=\"bold\">-Q</text>\n      <!-- Dielectric layer in between -->\n      <rect x=\"196\" y=\"42\" width=\"94\" height=\"146\" fill=\"#10b981\" opacity=\"0.25\"/>\n      <text x=\"212\" y=\"120\" fill=\"#34d399\" font-size=\"12\">Điện môi ε</text>\n      <!-- Connecting leads -->\n      <line x1=\"80\" y1=\"115\" x2=\"180\" y2=\"115\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n      <line x1=\"306\" y1=\"115\" x2=\"400\" y2=\"115\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n      <!-- Distance d bracket -->\n      <line x1=\"196\" y1=\"200\" x2=\"290\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n      <circle cx=\"196\" cy=\"200\" r=\"3\" fill=\"#fbbf24\"/>\n      <circle cx=\"290\" cy=\"200\" r=\"3\" fill=\"#fbbf24\"/>\n      <text x=\"238\" y=\"218\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">d</text>\n      <text x=\"130\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Cấu tạo tụ điện phẳng: hai bản cực song song cách nhau bởi điện môi</text>\n    </svg>"},{"q":"Điện dung C của tụ điện là đại lượng đặc trưng cho:","opts":["Khả năng tích điện của tụ điện ở một hiệu điện thế nhất định, tính bằng C = Q/U.","Mức độ cản trở dòng điện một chiều của tụ điện.","Nhiệt lượng toả ra khi tụ điện phóng điện qua bóng đèn.","Độ bền cơ học của các bản cực kim loại."],"ans":"A","exp":"• <b>Định nghĩa điện dung:</b> Điện dung C của tụ điện là đại lượng đặc trưng cho khả năng tích điện của tụ ở một hiệu điện thế U: C = <span class=\"fraction\"><span class=\"numerator\">Q</span><span class=\"denominator\">U</span></span>. Đơn vị đo là Fara (F).","svgGraph":null},{"q":"Một tụ điện có điện dung C = 20 μF được nối vào hai cực của nguồn điện có hiệu điện thế U = 12 V. Điện tích tích được trên các bản tụ là:","opts":["2,4·10⁻⁴ C.","1,2·10⁻⁴ C.","4,8·10⁻⁴ C.","6,0·10⁻⁵ C."],"ans":"A","exp":"• <b>Công thức:</b> Q = C·U<br>• <b>Thay số:</b> Q = 20·10⁻⁶ · 12 = 2,4·10⁻⁴ C (240 μC).","svgGraph":null},{"q":"Xét một tụ điện phẳng không khí đã được tích điện bằng nguồn có hiệu điện thế U rồi ngắt tụ khỏi nguồn điện (điện tích Q trên tụ không đổi). Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Năng lượng điện trường dự trữ trong tụ điện sẽ giảm đi khi tăng khoảng cách d.","Nếu kéo hai bản cực ra xa nhau (tăng khoảng cách d) thì điện dung C của tụ điện sẽ giảm.","Khi khoảng cách d tăng, hiệu điện thế U giữa hai bản tụ sẽ tăng lên.","Cường độ điện trường E giữa hai bản tụ không bị thay đổi khi thay đổi khoảng cách d."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> C = εS / (4πkd) tỉ lệ nghịch với d nên d tăng thì C giảm.<br>• <b>Ý b [Đúng]:</b> Q = const ⇒ U = Q/C, C giảm nên U tăng.<br>• <b>Ý c [Đúng]:</b> E = U/d = (Q/C)/d = Q / (εS/4πk) không phụ thuộc vào d nên E không đổi.<br>• <b>Ý d [Sai]:</b> W = Q² / (2C), C giảm nên năng lượng W tăng (công cơ học thực hiện khi kéo tách 2 bản biến thành năng lượng điện trường).","svgGraph":null},{"q":"Ghép công thức tính năng lượng điện trường dự trữ trong tụ điện ở Cột A với các đại lượng liên quan ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["W = 1/2 · C·U² ➔ Tính năng lượng khi biết điện tích Q và điện dung C","W = 1/2 · C·U² ➔ Tính năng lượng khi biết điện dung C và hiệu điện thế U","W = 1/2 · Q·U ➔ Tính năng lượng khi biết điện tích Q và điện dung C","W = Q² / (2C) ➔ Tính năng lượng khi biết điện dung C và hiệu điện thế U"],"ans":0,"exp":"• <b>1 - B:</b> W = 1/2·CU².<br>• <b>2 - D:</b> W = 1/2·QU.<br>• <b>3 - A:</b> W = Q²/(2C).<br>• <b>4 - C:</b> Mắc song song: C<sub>td</sub> = C₁ + C₂.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi ghép nối tiếp các tụ điện, điện tích trên mỗi tụ  [ ... ]  và điện dung tương đương được tính theo công thức  [ ... ] . Khi ghép song song các tụ điện, hiệu điện thế giữa hai đầu mỗi tụ  [ ... ]  và điện tích của bộ tụ bằng  [ ... ] .\"</i>","opts":["bằng nhau: Q₁ = Q₂ = Q<sub>bình</sub> — 1/C<sub>td</sub> = 1/C₁ + 1/C₂","không đổi","tỉ lệ nghịch — C<sub>td</sub> = C₁ + C₂","1/C<sub>td</sub> = 1/C₁ + 1/C₂ — bằng nhau: Q₁ = Q₂ = Q<sub>bình</sub>"],"ans":0,"exp":"<b>Quy tắc ghép tụ:</b><br>• Ghép nối tiếp: Q bằng nhau, 1/C<sub>td</sub> = 1/C₁ + 1/C₂.<br>• Ghép song song: U bằng nhau, Q = Q₁ + Q₂.","svgGraph":null},{"q":"Trên vỏ một tụ điện có ghi nhãn: '100 μF - 50 V'. Con số 50 V cho biết:","opts":["Hiệu điện thế giới hạn (cực đại) mà tụ chịu được; nếu vượt quá tụ sẽ bị đánh thủng.","Hiệu điện thế bắt buộc phải đặt vào để tụ có thể tích điện được.","Hiệu điện thế tối thiểu để duy trì lớp cách điện bên trong tụ.","Suất điện động mà tụ điện tự phát ra khi phóng điện."],"ans":"A","exp":"• Giá trị điện áp ghi trên tụ là hiệu điện thế định mức (hoặc hiệu điện thế đánh thủng giới hạn). Đặt hiệu điện thế vượt quá giá trị này sẽ làm lớp điện môi bị đánh thủng dẫn điện gây hỏng tụ.","svgGraph":null},{"q":"Năng lượng điện trường dự trữ trong tụ điện có điện dung C = 50 μF khi được nạp điện đến hiệu điện thế U = 20 V là:","opts":["0,01 J.","0,02 J.","0,05 J.","0,1 J."],"ans":"A","exp":"• <b>Công thức năng lượng:</b> W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>·C·U²<br>• <b>Thay số:</b> W = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · 50·10⁻⁶ · (20)² = 25·10⁻⁶ · 400 = 0,01 J (10 mJ).","svgGraph":null},{"q":"Có hai tụ điện C₁ = 3 μF và C₂ = 6 μF. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi ghép nối tiếp và nối vào nguồn điện, tụ C₁ sẽ tích lượng điện tích lớn hơn tụ C₂.","Khi ghép song song hai tụ này thì điện dung tương đương của bộ tụ là C<sub>ss</sub> = 9 μF.","Khi ghép nối tiếp hai tụ này thì điện dung tương đương của bộ tụ là C<sub>nt</sub> = 2 μF.","Khi ghép song song và nối vào nguồn điện, tụ C₂ sẽ tích lượng điện tích lớn gấp đôi tụ C₁."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> C<sub>ss</sub> = C₁ + C₂ = 3 + 6 = 9 μF.<br>• <b>Ý b [Đúng]:</b> C<sub>nt</sub> = (C₁·C₂)/(C₁ + C₂) = (3·6)/(3 + 6) = 18/9 = 2 μF.<br>• <b>Ý c [Sai]:</b> Ghép nối tiếp thì điện tích trên các tụ luôn bằng nhau Q₁ = Q₂ = Q<sub>bình</sub>.<br>• <b>Ý d [Đúng]:</b> Ghép song song thì U₁ = U₂ = U ⇒ Q₂/Q₁ = C₂/C₁ = 6/3 = 2.","svgGraph":null},{"q":"Trong các thiết bị điện tử, tụ điện có vai trò cơ bản là:","opts":["Tích lũy năng lượng điện trường và phóng điện nhanh, lọc phẳng tín hiệu điện xoay chiều.","Biến đổi năng lượng điện thành cơ năng quay liên tục như động cơ điện.","Phát ra dòng điện một chiều vĩnh cửu như một nguồn pin hoá học.","Đo trực tiếp cường độ dòng điện chạy qua mạch nối tiếp."],"ans":"A","exp":"• Tụ điện tích trữ và phóng điện năng, lọc phẳng gợn sóng điện áp trong mạch nguồn một chiều, truyền tín hiệu xoay chiều và chặn dòng một chiều.","svgGraph":null}],"22":[{"q":"Dòng điện trong kim loại là dòng chuyển dời có hướng của các:","opts":["Electron tự do ngược chiều điện trường.","Ion dương cùng chiều điện trường.","Ion âm ngược chiều điện trường.","Hạt mang điện tích dương và hạt mang điện tích âm ngược chiều nhau."],"ans":"A","exp":"• <b>Bản chất dòng điện trong kim loại:</b> Trong kim loại, các electron hoá trị bứt ra khỏi nguyên tử thành các electron tự do. Dưới tác dụng của điện trường, các electron tự do dịch chuyển có hướng ngược chiều điện trường tạo nên dòng điện.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr22\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Cylindrical wire section -->\n      <rect x=\"80\" y=\"60\" width=\"340\" height=\"110\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"2\" rx=\"10\"/>\n      <!-- Electric field direction E (left to right) -->\n      <line x1=\"120\" y1=\"35\" x2=\"380\" y2=\"35\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <text x=\"235\" y=\"28\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">Điện trường E</text>\n      <!-- Conventional current direction I (left to right) -->\n      <line x1=\"120\" y1=\"195\" x2=\"380\" y2=\"195\" stroke=\"#fbbf24\" stroke-width=\"2.5\" marker-end=\"url(#arr22)\"/>\n      <text x=\"210\" y=\"215\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">Chiều dòng điện quy ước (I)</text>\n      <!-- Positive lattice ions (fixed) -->\n      <circle cx=\"150\" cy=\"90\" r=\"10\" fill=\"#ef4444\"/><text x=\"146\" y=\"94\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"250\" cy=\"90\" r=\"10\" fill=\"#ef4444\"/><text x=\"246\" y=\"94\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"350\" cy=\"90\" r=\"10\" fill=\"#ef4444\"/><text x=\"346\" y=\"94\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"200\" cy=\"140\" r=\"10\" fill=\"#ef4444\"/><text x=\"196\" y=\"144\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <circle cx=\"300\" cy=\"140\" r=\"10\" fill=\"#ef4444\"/><text x=\"296\" y=\"144\" fill=\"#ffffff\" font-size=\"11\">+</text>\n      <!-- Free electrons drifting right to left -->\n      <circle cx=\"280\" cy=\"110\" r=\"6\" fill=\"#60a5fa\"/><text x=\"277\" y=\"113\" fill=\"#ffffff\" font-size=\"9\">-</text>\n      <line x1=\"280\" y1=\"110\" x2=\"220\" y2=\"110\" stroke=\"#60a5fa\" stroke-width=\"2\" marker-end=\"url(#arr22)\"/>\n      <text x=\"175\" y=\"114\" fill=\"#60a5fa\" font-size=\"11\">Tốc độ trôi v</text>\n      <text x=\"120\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Chuyển động trôi của electron ngược chiều điện trường</text>\n    </svg>"},{"q":"Cường độ dòng điện không đổi I chạy qua tiết diện thẳng của dây dẫn được xác định bằng công thức:","opts":["I = q / t.","I = q · t.","I = t / q.","I = q² / t."],"ans":"A","exp":"• <b>Định nghĩa cường độ dòng điện:</b> I = <span class=\"fraction\"><span class=\"numerator\">q</span><span class=\"denominator\">t</span></span>, là đại lượng đặc trưng cho tác dụng mạnh hay yếu của dòng điện, đo bằng lượng điện tích chuyển qua tiết diện thẳng của dây dẫn trong một đơn vị thời gian. Đơn vị là Ampe (A).","svgGraph":null},{"q":"Một dòng điện không đổi có cường độ I = 2 A chạy qua dây dẫn kim loại. Điện lượng chuyển qua tiết diện thẳng của dây trong thời gian 5 phút là:","opts":["600 C.","10 C.","300 C.","1200 C."],"ans":"A","exp":"• <b>Đổi đơn vị thời gian:</b> t = 5 phút = 5 · 60 = 300 s.<br>• <b>Công thức:</b> q = I·t = 2 · 300 = 600 C.","svgGraph":null},{"q":"Xét mô hình dẫn điện của hạt tải điện trong dây dẫn kim loại hình trụ có tiết diện S, mật độ electron tự do n, tốc độ trôi trung bình v và độ lớn điện tích mỗi hạt e. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi bật công tắc bóng đèn sáng gần như tức thì là vì tốc độ trôi của electron bằng tốc độ ánh sáng trong chân không.","Cường độ dòng điện chạy qua dây dẫn liên hệ với tốc độ trôi bởi hệ thức I = S·n·e·v.","Tốc độ trôi của electron trong dây dẫn kim loại thực tế rất nhỏ (thường chỉ cỡ vài mm/s hoặc cm/s).","Mật độ dòng điện j = I/S có đơn vị là A/m²."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Công thức liên hệ vi mô: I = Snev.<br>• <b>Ý b [Đúng]:</b> Tốc độ trôi định hướng rất chậm (cỡ 10⁻⁴ đến 10⁻³ m/s) do va chạm liên tục với các ion mạng.<br>• <b>Ý c [Sai]:</b> Bóng đèn sáng tức thì vì điện trường lan truyền dọc dây với tốc độ ánh sáng (c ≈ 3·10⁸ m/s), chứ không phải do electron chạy với tốc độ ánh sáng.<br>• <b>Ý d [Đúng]:</b> Mật độ dòng điện j = I/S đo bằng Ampe trên mét vuông (A/m²).","svgGraph":null},{"q":"Ghép các đại lượng trong biểu thức vi mô của dòng điện I = S·n·e·v ở Cột A với ý nghĩa tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["n (mật độ electron tự do) ➔ Tốc độ dịch chuyển có hướng trung bình của các electron dưới tác dụng của điện trường","n (mật độ electron tự do) ➔ Số electron tự do có trong một đơn vị thể tích (m⁻³)","v (tốc độ trôi) ➔ Tốc độ dịch chuyển có hướng trung bình của các electron dưới tác dụng của điện trường","S (tiết diện thẳng của dây) ➔ Số electron tự do có trong một đơn vị thể tích (m⁻³)"],"ans":0,"exp":"• <b>1 - B:</b> n là mật độ hạt tải điện (m⁻³).<br>• <b>2 - A:</b> v là tốc độ trôi (m/s).<br>• <b>3 - D:</b> S là tiết diện dây (m²).<br>• <b>4 - C:</b> e là điện tích nguyên tố.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Quy ước chiều của dòng điện là chiều chuyển động của các  [ ... ] . Trong kim loại, chiều dòng điện  [ ... ]  với chiều dịch chuyển của các electron tự do. Tác dụng đặc trưng nhất mà mọi dòng điện đều gây ra là  [ ... ] . Dụng cụ dùng để đo cường độ dòng điện là  [ ... ] .\"</i>","opts":["điện tích dương — ngược chiều","không đổi","điện tích âm — cùng chiều","ngược chiều — điện tích dương"],"ans":0,"exp":"<b>Quy ước và tác dụng dòng điện:</b><br>• Chiều dòng điện theo chiều điện tích dương.<br>• Ngược chiều electron tự do trong kim loại.<br>• Tác dụng từ là tác dụng đặc trưng nhất.<br>• Đo bằng ampe kế mắc nối tiếp.","svgGraph":null},{"q":"Số electron tự do dịch chuyển qua tiết diện thẳng của dây dẫn kim loại trong 1 giây khi có dòng điện I = 1,6 A chạy qua là:","opts":["1,0·10¹⁹ hạt.","1,6·10¹⁹ hạt.","6,25·10¹⁸ hạt.","2,5·10¹⁹ hạt."],"ans":"A","exp":"• <b>Điện lượng qua dây trong 1 s:</b> q = I·t = 1,6 · 1 = 1,6 C.<br>• <b>Số hạt electron:</b> N = <span class=\"fraction\"><span class=\"numerator\">q</span><span class=\"denominator\">e</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,6</span><span class=\"denominator\">1,6·10⁻¹⁹</span></span> = 1,0·10¹⁹ hạt.","svgGraph":null},{"q":"Một dây đồng tiết diện S = 1 mm² mang dòng điện I = 3,2 A. Biết mật độ electron tự do của đồng là n = 8,5·10²⁸ m⁻³. Lấy e = 1,6·10⁻¹⁹ C. Tốc độ trôi trung bình của electron trong dây đồng xấp xỉ bằng:","opts":["0,235 mm/s.","2,35 mm/s.","0,0235 mm/s.","1,25 mm/s."],"ans":"A","exp":"• <b>Công thức tốc độ trôi:</b> v = <span class=\"fraction\"><span class=\"numerator\">I</span><span class=\"denominator\">n·e·S</span></span><br>• <b>Thay số với S = 10⁻⁶ m²:</b><br>v = <span class=\"fraction\"><span class=\"numerator\">3,2</span><span class=\"denominator\">8,5·10²⁸ · 1,6·10⁻¹⁹ · 10⁻⁶</span></span> = <span class=\"fraction\"><span class=\"numerator\">3,2</span><span class=\"denominator\">13,6·10³</span></span> ≈ 2,35·10⁻⁴ m/s = 0,235 mm/s.","svgGraph":null},{"q":"Một acquy ô tô đang phóng điện cung cấp dòng điện không đổi I = 5 A chạy qua hệ thống đèn chiếu sáng trong thời gian 2 giờ. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Đơn vị Ampe - giờ (A·h) là đơn vị đo năng lượng điện.","Điện lượng chuyển qua acquy trong thời gian này là 36000 C.","Dung lượng của acquy đã tiêu hao là 10 A·h (Ampe - giờ).","Cường độ dòng điện chạy trong mạch luôn không đổi nếu điện trở tải không đổi và suất điện động của nguồn lý tưởng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> q = I·t = 5 · (2 · 3600) = 36000 C.<br>• <b>Ý b [Đúng]:</b> Dung lượng = I·t = 5 A · 2 h = 10 A·h.<br>• <b>Ý c [Sai]:</b> A·h = (C/s) · 3600s = 3600 C là đơn vị đo điện lượng (điện tích), không phải đo năng lượng điện.<br>• <b>Ý d [Đúng]:</b> Định luật Ohm cho mạch kín: I = E / (R + r) = const.","svgGraph":null},{"q":"Dòng điện chạy qua một dây dẫn có cường độ thay đổi theo thời gian theo phương trình q(t) = 3t² + 2t (C). Cường độ dòng điện tức thời tại thời điểm t = 2 s là:","opts":["14 A.","16 A.","12 A.","8 A."],"ans":"A","exp":"• <b>Công thức đạo hàm cường độ tức thời:</b> i(t) = q'(t) = 6t + 2.<br>• <b>Tại t = 2 s:</b> i(2) = 6 · 2 + 2 = 14 A.","svgGraph":null}],"23":[{"q":"Theo định luật Ohm đối với đoạn mạch chỉ chứa điện trở thuần R, cường độ dòng điện I chạy qua đoạn mạch:","opts":["Tỉ lệ thuận với hiệu điện thế U giữa hai đầu đoạn mạch và tỉ lệ nghịch với điện trở R.","Tỉ lệ thuận với điện trở R và tỉ lệ nghịch với hiệu điện thế U giữa hai đầu.","Tỉ lệ thuận với bình phương hiệu điện thế U giữa hai đầu đoạn mạch.","Không phụ thuộc vào hiệu điện thế U mà chỉ do bản chất vật dẫn quyết định."],"ans":"A","exp":"• <b>Định luật Ohm cho đoạn mạch:</b> I = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">R</span></span>. Cường độ dòng điện tỉ lệ thuận với hiệu điện thế giữa hai đầu điện trở và tỉ lệ nghịch với giá trị điện trở đó.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr23\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- U-I characteristic axes -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr23)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr23)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">U (V)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">I (A)</text>\n      <!-- Resistor 1 line (straight through origin) -->\n      <line x1=\"80\" y1=\"200\" x2=\"380\" y2=\"60\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <text x=\"390\" y=\"65\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Vật dẫn kim loại (R = const)</text>\n      <!-- Resistor 2 curve (Non-ohmic / light bulb) -->\n      <path d=\"M 80,200 Q 200,160 380,120\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n      <text x=\"390\" y=\"125\" fill=\"#f43f5e\" font-size=\"12\">Dây tóc bóng đèn (R tăng khi nóng)</text>\n      <!-- Slope label -->\n      <text x=\"210\" y=\"115\" fill=\"#fbbf24\" font-size=\"12\">Độ dốc = 1/R</text>\n      <text x=\"130\" y=\"228\" fill=\"#94a3b8\" font-size=\"12\">Đặc tuyến Vôn - Ampe (U - I) của vật dẫn tuân theo định luật Ohm</text>\n    </svg>"},{"q":"Điện trở của một đoạn dây kim loại hình trụ đồng chất có chiều dài L, tiết diện S và điện trở suất ρ được tính theo công thức:","opts":["R = ρ · L / S.","R = ρ · S / L.","R = L · S / ρ.","R = ρ · L · S."],"ans":"A","exp":"• <b>Công thức điện trở dây dẫn:</b> R = ρ·<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">S</span></span>. Điện trở tỉ lệ thuận với chiều dài L, điện trở suất ρ và tỉ lệ nghịch với tiết diện S.","svgGraph":null},{"q":"Đặt hiệu điện thế U = 24 V vào hai đầu một điện trở R = 12 Ω. Cường độ dòng điện chạy qua điện trở là:","opts":["2 A.","0,5 A.","288 A.","12 A."],"ans":"A","exp":"• <b>Định luật Ohm:</b> I = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">R</span></span><br>• <b>Thay số:</b> I = <span class=\"fraction\"><span class=\"numerator\">24</span><span class=\"denominator\">12</span></span> = 2 A.","svgGraph":null},{"q":"Về sự phụ thuộc của điện trở vào nhiệt độ và các loại linh kiện điện trở, xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hệ số nhiệt điện trở của kim loại α thường mang giá trị âm.","Khi nhiệt độ của dây kim loại tăng lên, các ion mạng dao động nhiệt mạnh hơn làm tăng sự va chạm với electron nên điện trở suất của kim loại tăng.","Hiện tượng siêu dẫn là hiện tượng điện trở của vật liệu đột ngột giảm xuống bằng không khi nhiệt độ hạ xuống dưới nhiệt độ tới hạn T<sub>c</sub>.","Điện trở nhiệt (thermistor) có điện trở biến thiên rất nhạy theo nhiệt độ và được ứng dụng làm cảm biến nhiệt độ."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Tăng T ⇒ ion dao động cản trở e ⇒ ρ = ρ₀(1 + αΔt) tăng.<br>• <b>Ý b [Sai]:</b> Kim loại có α > 0 (nhiệt độ tăng thì điện trở tăng). Bán dẫn mới có α < 0.<br>• <b>Ý c [Đúng]:</b> Định nghĩa hiện tượng siêu dẫn: R = 0 khi T < T<sub>c</sub>.<br>• <b>Ý d [Đúng]:</b> Nhiệt điện trở NTC/PTC dùng làm cảm biến nhiệt độ.","svgGraph":null},{"q":"Ghép đoạn mạch điện trở ở Cột A với công thức điện trở tương đương tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Hai điện trở mắc nối tiếp (R₁ nt R₂) ➔ R<sub>tđ</sub> = R / n","Hai điện trở mắc nối tiếp (R₁ nt R₂) ➔ R<sub>tđ</sub> = R₁ + R₂","Hai điện trở mắc song song (R₁ // R₂) ➔ R<sub>tđ</sub> = R / n","Đoạn mạch gồm n điện trở R giống nhau mắc song song ➔ R<sub>tđ</sub> = R₁ + R₂"],"ans":0,"exp":"• <b>1 - B:</b> Nối tiếp: R<sub>tđ</sub> = R₁ + R₂.<br>• <b>2 - D:</b> Song song: R<sub>tđ</sub> = (R₁·R₂)/(R₁ + R₂).<br>• <b>3 - A:</b> n điện trở song song: R<sub>tđ</sub> = R/n.<br>• <b>4 - C:</b> n điện trở nối tiếp: R<sub>tđ</sub> = n·R.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong đoạn mạch gồm hai điện trở R₁ và R₂ mắc song song, hiệu điện thế hai đầu mỗi điện trở  [ ... ] . Cường độ dòng điện trong mạch chính bằng  [ ... ]  cường độ dòng điện qua các mạch nhánh. Cường độ dòng điện qua mỗi nhánh  [ ... ]  với điện trở của nhánh đó. Điện trở tương đương của đoạn mạch luôn  [ ... ]  điện trở của từng nhánh thành phần.\"</i>","opts":["bằng nhau: U₁ = U₂ = U — tổng các dòng điện nhánh: I = I₁ + I₂","không đổi","tỉ lệ thuận — lớn hơn","tổng các dòng điện nhánh: I = I₁ + I₂ — bằng nhau: U₁ = U₂ = U"],"ans":0,"exp":"<b>Tính chất mạch song song:</b><br>• U bằng nhau.<br>• I chính = I₁ + I₂.<br>• I₁/I₂ = R₂/R₁ (tỉ lệ nghịch với R).<br>• R<sub>tđ</sub> nhỏ hơn từng R thành phần.","svgGraph":null},{"q":"Một sợi dây mayso có điện trở R = 20 Ω được cắt đều thành hai đoạn bằng nhau rồi mắc song song hai đoạn đó với nhau. Điện trở tương đương của bộ dây mới là:","opts":["5 Ω.","10 Ω.","20 Ω.","2,5 Ω."],"ans":"A","exp":"• <b>Mỗi đoạn có điện trở:</b> R' = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">20</span><span class=\"denominator\">2</span></span> = 10 Ω.<br>• <b>Ghép song song hai đoạn:</b> R<sub>tđ</sub> = <span class=\"fraction\"><span class=\"numerator\">R'</span><span class=\"denominator\">2</span></span> = <span class=\"fraction\"><span class=\"numerator\">10</span><span class=\"denominator\">2</span></span> = 5 Ω.","svgGraph":null},{"q":"Một dây dẫn bằng đồng có chiều dài L = 100 m và tiết diện S = 0,5 mm² = 0,5·10⁻⁶ m². Biết điện trở suất của đồng là ρ = 1,7·10⁻⁸ Ω·m. Điện trở của đoạn dây đồng này là:","opts":["3,4 Ω.","0,85 Ω.","1,7 Ω.","6,8 Ω."],"ans":"A","exp":"• <b>Công thức điện trở:</b> R = ρ·<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">S</span></span><br>• <b>Thay số:</b> R = 1,7·10⁻⁸ · <span class=\"fraction\"><span class=\"numerator\">100</span><span class=\"denominator\">0,5·10⁻⁶</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,7·10⁻⁶</span><span class=\"denominator\">0,5·10⁻⁶</span></span> = 3,4 Ω.","svgGraph":null},{"q":"Cho đoạn mạch điện gồm điện trở R₁ = 6 Ω mắc song song với điện trở R₂ = 12 Ω rồi nối tiếp với điện trở R₃ = 4 Ω vào nguồn hiệu điện thế U = 16 V. Xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Cường độ dòng điện chạy qua điện trở R₁ nhỏ hơn cường độ dòng điện chạy qua điện trở R₂.","Điện trở tương đương của cụm (R₁ // R₂) bằng 4 Ω.","Điện trở tương đương toàn mạch là R<sub>tđ</sub> = 8 Ω.","Cường độ dòng điện chạy qua điện trở R₃ là I₃ = 2 A."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> R₁₂ = (6·12)/(6 + 12) = 72/18 = 4 Ω.<br>• <b>Ý b [Đúng]:</b> R<sub>tđ</sub> = R₁₂ + R₃ = 4 + 4 = 8 Ω.<br>• <b>Ý c [Đúng]:</b> I<sub>toanmach</sub> = U/R<sub>tđ</sub> = 16/8 = 2 A ⇒ I₃ = 2 A.<br>• <b>Ý d [Sai]:</b> U₁ = U₂ ⇒ I₁·R₁ = I₂·R₂. Vì R₁ = 6 Ω < R₂ = 12 Ω nên I₁ = 2·I₂ (dòng qua R₁ lớn gấp đôi dòng qua R₂).","svgGraph":null},{"q":"Quang điện trở (LDR) là linh kiện điện tử có điện trở:","opts":["Giảm mạnh khi được chiếu sáng thích hợp.","Tăng vọt khi được chiếu ánh sáng nhìn thấy.","Hoàn toàn không thay đổi khi cường độ ánh sáng thay đổi.","Biến đổi tỉ lệ nghịch với hiệu điện thế đặt vào nó."],"ans":"A","exp":"• Quang điện trở làm bằng chất bán dẫn; khi được chiếu sáng thích hợp xảy ra hiện tượng quang điện trong tạo thêm các hạt dẫn điện (electron và lỗ trống) làm độ dẫn điện tăng lên, dẫn tới điện trở của nó giảm mạnh.","svgGraph":null}],"24":[{"q":"Suất điện động E của nguồn điện là đại lượng đặc trưng cho:","opts":["Khả năng thực hiện công của các lực lạ bên trong nguồn điện để tách và dịch chuyển điện tích.","Tác dụng cản trở dòng điện của vật liệu chế tạo nguồn điện.","Nhiệt lượng toả ra khi nguồn điện bị đoản mạch.","Khả năng tích điện tĩnh trên hai cực khi nối mạch kín."],"ans":"A","exp":"• <b>Định nghĩa suất điện động:</b> E = <span class=\"fraction\"><span class=\"numerator\">A<sub>la</sub></span><span class=\"denominator\">q</span></span>, đo bằng thương số giữa công của lực lạ khi dịch chuyển một điện tích dương ngược chiều điện trường từ cực âm sang cực dương bên trong nguồn và độ lớn điện tích đó. Đơn vị là Volt (V).","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr24\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#38bdf8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Source symbol box -->\n      <rect x=\"80\" y=\"50\" width=\"340\" height=\"80\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\" rx=\"10\"/>\n      <!-- EMF source symbol -->\n      <line x1=\"160\" y1=\"70\" x2=\"160\" y2=\"110\" stroke=\"#ef4444\" stroke-width=\"3\"/>\n      <line x1=\"175\" y1=\"80\" x2=\"175\" y2=\"100\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n      <text x=\"150\" y=\"65\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">+</text>\n      <text x=\"175\" y=\"65\" fill=\"#3b82f6\" font-size=\"16\" font-weight=\"bold\">-</text>\n      <text x=\"135\" y=\"125\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">E</text>\n      <!-- Internal resistance r -->\n      <rect x=\"230\" y=\"80\" width=\"50\" height=\"20\" fill=\"#334155\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n      <text x=\"250\" y=\"95\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">r</text>\n      <text x=\"215\" y=\"125\" fill=\"#fbbf24\" font-size=\"11\">Điện trở trong r</text>\n      <!-- External load resistor R -->\n      <rect x=\"200\" y=\"180\" width=\"100\" height=\"30\" fill=\"#0f766e\" stroke=\"#2dd4bf\" stroke-width=\"2\" rx=\"5\"/>\n      <text x=\"235\" y=\"200\" fill=\"#ffffff\" font-size=\"13\" font-weight=\"bold\">R (ngoài)</text>\n      <!-- Circuit wires -->\n      <line x1=\"80\" y1=\"90\" x2=\"40\" y2=\"90\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"40\" y1=\"90\" x2=\"40\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"40\" y1=\"195\" x2=\"200\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"420\" y1=\"90\" x2=\"460\" y2=\"90\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"460\" y1=\"90\" x2=\"460\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <line x1=\"460\" y1=\"195\" x2=\"300\" y2=\"195\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n      <!-- Current arrow -->\n      <line x1=\"330\" y1=\"195\" x2=\"380\" y2=\"195\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arr24)\"/>\n      <text x=\"350\" y=\"185\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">I</text>\n      <text x=\"145\" y=\"232\" fill=\"#94a3b8\" font-size=\"12\">Mạch điện kín gồm nguồn (E, r) và điện trở ngoài R</text>\n    </svg>"},{"q":"Theo định luật Ohm cho toàn mạch kín gồm nguồn (E, r) nối với điện trở ngoài R, cường độ dòng điện trong mạch xác định bởi:","opts":["I = E / (R + r).","I = E / (R - r).","I = (E + U) / R.","I = E · (R + r)."],"ans":"A","exp":"• <b>Định luật Ohm cho toàn mạch:</b> I = <span class=\"fraction\"><span class=\"numerator\">E</span><span class=\"denominator\">R + r</span></span>. Cường độ dòng điện tỉ lệ thuận với suất điện động của nguồn và tỉ lệ nghịch với tổng trở toàn phần của mạch.","svgGraph":null},{"q":"Một nguồn điện có suất điện động E = 12 V và điện trở trong r = 1 Ω được mắc vào điện trở ngoài R = 5 Ω thành mạch kín. Cường độ dòng điện trong mạch và hiệu điện thế hai đầu nguồn điện lần lượt là:","opts":["I = 2 A; U<sub>ngoài</sub> = 10 V.","I = 2,4 A; U<sub>ngoài</sub> = 12 V.","I = 2 A; U<sub>ngoài</sub> = 12 V.","I = 2,4 A; U<sub>ngoài</sub> = 10 V."],"ans":"A","exp":"• <b>Cường độ dòng điện:</b> I = <span class=\"fraction\"><span class=\"numerator\">E</span><span class=\"denominator\">R + r</span></span> = <span class=\"fraction\"><span class=\"numerator\">12</span><span class=\"denominator\">5 + 1</span></span> = <span class=\"fraction\"><span class=\"numerator\">12</span><span class=\"denominator\">6</span></span> = 2 A.<br>• <b>Hiệu điện thế mạch ngoài:</b> U<sub>ngoài</sub> = I·R = 2 · 5 = 10 V (hoặc U = E - I·r = 12 - 2·1 = 10 V).","svgGraph":null},{"q":"Về hoạt động của nguồn điện và hiện tượng đoản mạch, xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hiện tượng đoản mạch là an toàn và có lợi cho các thiết bị điện trong gia đình.","Khi mạch ngoài để hở (không nối tải R), hiệu điện thế giữa hai cực của nguồn điện bằng đúng suất điện động E.","Hiện tượng đoản mạch xảy ra khi điện trở mạch ngoài rất nhỏ (R ≈ 0), lúc này cường độ dòng điện đạt giá trị cực đại I<sub>đm</sub> = E/r.","Hiệu suất của nguồn điện được tính bằng tỉ số giữa công suất có ích tiêu thụ ở mạch ngoài và công suất toàn phần của nguồn: H = U/E."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Mạch hở I = 0 ⇒ U = E - I·r = E.<br>• <b>Ý b [Đúng]:</b> R ≈ 0 ⇒ I<sub>đm</sub> = E/r rất lớn.<br>• <b>Ý c [Sai]:</b> Đoản mạch làm dòng tăng vọt gây cháy nổ, hoả hoạn cực kì nguy hiểm.<br>• <b>Ý d [Đúng]:</b> H = P<sub>ích</sub> / P<sub>to</sub>ànphần = (U·I) / (E·I) = U/E = R / (R + r).","svgGraph":null},{"q":"Ghép công thức liên quan đến nguồn điện ở Cột A với ý nghĩa tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Công của nguồn điện: A<sub>ng</sub> = E·I·t ➔ Cường độ dòng điện khi hai cực nguồn bị nối tắt bằng dây dẫn điện trở không đáng kể","Công của nguồn điện: A<sub>ng</sub> = E·I·t ➔ Hiệu điện thế mạch ngoài cung cấp cho tải tiêu thụ","Độ giảm thế trong nguồn điện: U<sub>trong</sub> = I·r ➔ Cường độ dòng điện khi hai cực nguồn bị nối tắt bằng dây dẫn điện trở không đáng kể","Hiệu điện thế hai cực nguồn: U = E - I·r ➔ Hiệu điện thế mạch ngoài cung cấp cho tải tiêu thụ"],"ans":0,"exp":"• <b>1 - D:</b> A<sub>ng</sub> = E·I·t là toàn bộ năng lượng nguồn sản sinh.<br>• <b>2 - C:</b> I·r là độ giảm thế trong nguồn.<br>• <b>3 - B:</b> U = E - Ir là điện áp cực cấp ra ngoài.<br>• <b>4 - A:</b> I<sub>đm</sub> = E/r là dòng đoản mạch.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi ghép nối tiếp n nguồn giống nhau mỗi nguồn (E, r), suất điện động của bộ nguồn là  [ ... ]  và điện trở trong của bộ là  [ ... ] . Khi ghép song song m nguồn giống nhau thành một bộ, suất điện động của bộ nguồn  [ ... ]  và điện trở trong của bộ là  [ ... ] .\"</i>","opts":["E<sub>b</sub> = n·E — r<sub>b</sub> = n·r","không đổi","E<sub>b</sub> = E / n — r<sub>b</sub> = r · m","r<sub>b</sub> = n·r — E<sub>b</sub> = n·E"],"ans":0,"exp":"<b>Quy tắc ghép bộ nguồn:</b><br>• Nối tiếp: E<sub>b</sub> = nE, r<sub>b</sub> = nr.<br>• Song song (m nhánh giống nhau): E<sub>b</sub> = E, r<sub>b</sub> = r/m.","svgGraph":null},{"q":"Một bộ pin gồm 4 pin giống nhau mắc nối tiếp, mỗi pin có suất điện động e = 1,5 V và điện trở trong r₀ = 0,5 Ω. Suất điện động và điện trở trong của bộ nguồn lần lượt là:","opts":["E<sub>b</sub> = 6,0 V; r<sub>b</sub> = 2,0 Ω.","E<sub>b</sub> = 6,0 V; r<sub>b</sub> = 0,5 Ω.","E<sub>b</sub> = 1,5 V; r<sub>b</sub> = 2,0 Ω.","E<sub>b</sub> = 3,0 V; r<sub>b</sub> = 1,0 Ω."],"ans":"A","exp":"• <b>Ghép nối tiếp 4 pin:</b><br>E<sub>b</sub> = 4 · e = 4 · 1,5 = 6,0 V.<br>r<sub>b</sub> = 4 · r₀ = 4 · 0,5 = 2,0 Ω.","svgGraph":null},{"q":"Một nguồn điện có suất điện động E = 6 V, điện trở trong r = 2 Ω được nối với mạch ngoài có điện trở R để tạo thành mạch kín. Biết hiệu điện thế giữa hai cực của nguồn là U = 4 V. Giá trị điện trở R là:","opts":["4 Ω.","2 Ω.","6 Ω.","8 Ω."],"ans":"A","exp":"• <b>Bước 1: Tính cường độ dòng điện trong mạch:</b><br>U = E - I·r ⇒ 4 = 6 - I · 2 ⇒ 2I = 2 ⇒ I = 1 A.<br>• <b>Bước 2: Tính điện trở ngoài R:</b><br>R = <span class=\"fraction\"><span class=\"numerator\">U</span><span class=\"denominator\">I</span></span> = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">1</span></span> = 4 Ω.","svgGraph":null},{"q":"Một pin sạc dự phòng điện thoại có suất điện động E = 3,7 V và dung lượng 10000 mA·h. Xét tính Đúng / Sai của các khẳng định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi sạc pin, dòng điện đi vào cực âm và đi ra từ cực dương của pin dự phòng.","Tổng điện lượng dự trữ tối đa trong pin là q = 36000 C.","Năng lượng điện tối đa mà pin có thể cung cấp là W = 37 W·h (khoảng 133,2 kJ).","Hiệu suất của pin càng cao khi điện trở trong r của pin càng nhỏ."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> q = 10 A · 3600 s = 36000 C.<br>• <b>Ý b [Đúng]:</b> W = E·q = 3,7 V · 10 A·h = 37 W·h = 37 · 3600 J = 133200 J = 133,2 kJ.<br>• <b>Ý c [Sai]:</b> Khi nạp điện (sạc pin), nguồn sạc đẩy dòng điện đi vào cực dương và đi ra từ cực âm của acquy.<br>• <b>Ý d [Đúng]:</b> H = R/(R + r), r càng nhỏ thì tổn hao nhiệt trong pin càng ít, hiệu suất càng cao.","svgGraph":null},{"q":"Khi một nguồn điện được nối với một biến trở R, hiệu suất của nguồn điện đạt H = 80%. Tỉ số giữa điện trở mạch ngoài R và điện trở trong r của nguồn là:","opts":["4.","0,8.","5.","1,25."],"ans":"A","exp":"• <b>Công thức hiệu suất nguồn:</b> H = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">R + r</span></span> = 0,8<br>• R = 0,8·(R + r) = 0,8R + 0,8r ⇒ 0,2R = 0,8r ⇒ <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">r</span></span> = <span class=\"fraction\"><span class=\"numerator\">0,8</span><span class=\"denominator\">0,2</span></span> = 4.","svgGraph":null}],"25":[{"q":"Theo định luật Joule – Lenz, nhiệt lượng toả ra trên một dây dẫn thuần điện trở tỉ lệ thuận với:","opts":["Bình phương cường độ dòng điện, điện trở của dây và thời gian dòng điện chạy qua.","Cường độ dòng điện, điện trở của dây và bình phương thời gian.","Bình phương điện trở của dây và cường độ dòng điện.","Hiệu điện thế giữa hai đầu và nghịch đảo của thời gian."],"ans":"A","exp":"• <b>Định luật Joule – Lenz:</b> Q = I²·R·t. Nhiệt lượng toả ra trên một vật dẫn tỉ lệ thuận với bình phương cường độ dòng điện, với điện trở của vật dẫn và thời gian dòng điện chạy qua.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr25\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Power vs Resistance R curve -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr25)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr25)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">R (Ω)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">P<tspan baseline-shift=\"sub\" font-size=\"70%\">ngoài</tspan> (W)</text>\n      <!-- Curve of P vs R -->\n      <path d=\"M 80,200 Q 150,50 240,60 T 420,160\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Peak power at R = r -->\n      <circle cx=\"240\" cy=\"60\" r=\"5\" fill=\"#fbbf24\"/>\n      <line x1=\"240\" y1=\"60\" x2=\"240\" y2=\"200\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <line x1=\"80\" y1=\"60\" x2=\"240\" y2=\"60\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n      <text x=\"225\" y=\"215\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">R = r</text>\n      <text x=\"15\" y=\"65\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">P<tspan baseline-shift=\"sub\" font-size=\"70%\">max</tspan> = E² / (4r)</text>\n      <text x=\"250\" y=\"50\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Điểm cực đại công suất</text>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị công suất mạch ngoài cực đại khi R = r</text>\n    </svg>"},{"q":"Công suất điện tiêu thụ trên một đoạn mạch bất kì có hiệu điện thế U và cường độ dòng điện I được tính bằng công thức:","opts":["P = U·I.","P = U / I.","P = U²·I.","P = U·I²."],"ans":"A","exp":"• <b>Công thức công suất điện:</b> P = A/t = (U·I·t)/t = U·I. Đơn vị đo công suất là Oát (Watt - W).","svgGraph":null},{"q":"Một bóng đèn sợi đốt ghi nhãn: '220 V - 100 W' hoạt động bình thường ở mạng điện 220 V trong thời gian 5 giờ. Điện năng bóng đèn tiêu thụ là:","opts":["0,5 kW·h (1,8·10⁶ J).","500 kW·h.","0,2 kW·h.","1,1 kW·h."],"ans":"A","exp":"• <b>Tính theo kW·h:</b> A = P·t = 0,1 kW · 5 h = 0,5 kW·h.<br>• <b>Quy đổi ra Joule:</b> A = 0,5 · 3,6·10⁶ J = 1,8·10⁶ J.","svgGraph":null},{"q":"Một bếp điện có điện trở R = 44 Ω được cắm vào mạng điện gia đình có hiệu điện thế U = 220 V. Bếp được dùng để đun sôi 2 lít nước từ 20°C. Biết nhiệt dung riêng của nước là c = 4200 J/(kg·K). Bỏ qua mọi hao phí nhiệt ra môi trường. Xét tính Đúng / Sai của các khẳng định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Cường độ dòng điện chạy qua bếp điện là I = 5 A.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> I = U/R = 220 / 44 = 5 A.<br>• <b>Ý b [Đúng]:</b> P = U·I = 220 · 5 = 1100 W.<br>• <b>Ý c [Đúng]:</b> Q = mcΔt = 2 · 4200 · (100 - 20) = 672000 J.<br>• <b>Ý d [Đúng]:</b> t = Q/P = 672000 / 1100 ≈ 610,9 s ≈ 10 phút 11 giây.","svgGraph":null},{"q":"Ghép các công thức tính công suất điện hoặc năng lượng ở Cột A với điều kiện áp dụng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["P = U·I ➔ Bằng 3 600 000 Joule (3,6 MJ)","P = U·I ➔ Công suất phát điện toàn phần của nguồn điện","P = I²·R = U²/R ➔ Bằng 3 600 000 Joule (3,6 MJ)","P<sub>ng</sub> = E·I ➔ Công suất phát điện toàn phần của nguồn điện"],"ans":0,"exp":"• <b>1 - D:</b> P = UI áp dụng cho mọi đoạn mạch.<br>• <b>2 - C:</b> I²R = U²/R áp dụng riêng cho tải điện trở.<br>• <b>3 - B:</b> P<sub>ng</sub> = EI là công suất toàn phần của nguồn.<br>• <b>4 - A:</b> 1 kWh = 3,6·10⁶ J.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Mắc một biến trở R vào nguồn điện có suất điện động E và điện trở trong r. Công suất tiêu thụ trên biến trở R đạt giá trị cực đại khi  [ ... ] . Giá trị công suất cực đại khi đó là  [ ... ] . Khi công suất mạch ngoài cực đại, hiệu suất của nguồn điện đạt  [ ... ] . Nếu tăng điện trở R lên rất lớn thì công suất mạch ngoài sẽ  [ ... ] .\"</i>","opts":["R = r — P<sub>max</sub> = E² / (4r)","không đổi","R = 2r — 100%","P<sub>max</sub> = E² / (4r) — R = r"],"ans":0,"exp":"<b>Cực trị công suất mạch ngoài:</b><br>• P<sub>ngoài</sub> cực đại khi R = r.<br>• P<sub>max</sub> = E²/(4r).<br>• Hiệu suất khi đó H = R/(R+r) = r/(r+r) = 50%.<br>• R tăng vô cùng thì I giảm về 0 nên P giảm về 0.","svgGraph":null},{"q":"Một nguồn điện có suất điện động E = 12 V và điện trở trong r = 2 Ω được mắc với một biến trở R. Công suất tiêu thụ lớn nhất trên biến trở R có thể đạt được là:","opts":["18 W.","36 W.","72 W.","9 W."],"ans":"A","exp":"• <b>Điều kiện công suất cực đại:</b> R = r = 2 Ω.<br>• <b>Công suất cực đại:</b> P<sub>max</sub> = <span class=\"fraction\"><span class=\"numerator\">E²</span><span class=\"denominator\">4r</span></span> = <span class=\"fraction\"><span class=\"numerator\">(12)²</span><span class=\"denominator\">4 · 2</span></span> = <span class=\"fraction\"><span class=\"numerator\">144</span><span class=\"denominator\">8</span></span> = 18 W.","svgGraph":null},{"q":"Hai bóng đèn Đ₁ (110 V - 60 W) và Đ₂ (110 V - 100 W) được mắc nối tiếp vào mạng điện 220 V. Độ sáng thực tế của hai bóng đèn so với định mức là:","opts":["Đèn 60 W sáng hơn bình thường (dễ cháy hỏng), đèn 100 W sáng yếu hơn bình thường.","Cả hai đèn đều sáng bình thường đúng công suất định mức.","Đèn 100 W sáng rực rỡ hơn đèn 60 W.","Cả hai đèn đều sáng mờ mờ như nhau."],"ans":"A","exp":"• Điện trở định mức: R = U<sub>dm</sub>²/P<sub>dm</sub> ⇒ R₁ = 110²/60 ≈ 201,7 Ω, R₂ = 110²/100 = 121 Ω.<br>• Khi mắc nối tiếp, cùng dòng điện I ⇒ U₁/U₂ = R₁/R₂ > 1 ⇒ U₁ > 110 V và U₂ < 110 V.<br>• Do đó đèn 60 W bị quá áp sáng rực dễ cháy, còn đèn 100 W non áp sáng yếu.","svgGraph":null},{"q":"Một gia đình sử dụng các thiết bị điện trong một ngày (24 giờ) gồm: 1 tivi (100 W) dùng 4 giờ, 4 bóng đèn LED (20 W mỗi bóng) thắp sáng 5 giờ, 1 tủ lạnh (150 W) chạy tích luỹ 10 giờ. Giả sử giá điện sinh hoạt trung bình là 2500 đồng/(kW·h). Xét tính Đúng / Sai của các khẳng định sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Tổng điện năng tiêu thụ của tivi trong một ngày là 0,4 kW·h.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> A<sub>tivi</sub> = 0,1 kW · 4 h = 0,4 kW·h.<br>• <b>Ý b [Đúng]:</b> A<sub>led</sub> = (4 · 0,02 kW) · 5 h = 0,4 kW·h.<br>• <b>Ý c [Đúng]:</b> A<sub>tulanh</sub> = 0,15 kW · 10 h = 1,5 kW·h ⇒ A<sub>tong</sub> = 0,4 + 0,4 + 1,5 = 2,3 kW·h.<br>• <b>Ý d [Đúng]:</b> Tiền = 2,3 · 2500 = 5750 đồng.","svgGraph":null},{"q":"Số đếm của công tơ điện trong gia đình phản ánh:","opts":["Tổng điện năng (kW·h) mà gia đình đã tiêu thụ trong chu kì tính cước.","Công suất cực đại tức thời của các đồ dùng điện tại một thời điểm.","Hiệu điện thế trung bình của lưới điện trong tháng.","Cường độ dòng điện đỉnh đi vào cầu dao tổng."],"ans":"A","exp":"• Công tơ điện là thiết bị đo điện năng tiêu thụ của gia đình. Một số đếm trên công tơ tương ứng với 1 kW·h điện năng tiêu thụ (tương đương 3,6·10⁶ J).","svgGraph":null}],"26":[{"q":"Trong bài thực hành khảo sát pin điện hoá, đồ thị biểu diễn mối quan hệ giữa hiệu điện thế U hai đầu mạch ngoài và cường độ dòng điện I có dạng:","opts":["Một đoạn thẳng có độ dốc âm cắt trục tung tại giá trị suất điện động E.","Một đường thẳng đi qua gốc toạ độ hướng lên trên.","Một đường cong parabol đi qua gốc toạ độ.","Một đường thẳng nằm ngang song song với trục hoành cường độ dòng điện."],"ans":"A","exp":"• <b>Phương trình đặc tuyến ngoài của nguồn:</b> U = E - I·r.<br>• Đồ thị U theo I là một đoạn thẳng dốc xuống có hệ số góc bằng -r, cắt trục tung (khi I = 0) tại điểm U = E.","svgGraph":"<svg viewBox=\"0 0 500 240\" class=\"graph-svg\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs><marker id=\"arr26\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#94a3b8\"/></marker></defs>\n      <rect width=\"100%\" height=\"100%\" fill=\"#090d16\" rx=\"8\"/>\n      <!-- Axes -->\n      <line x1=\"60\" y1=\"200\" x2=\"440\" y2=\"200\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr26)\"/>\n      <line x1=\"80\" y1=\"220\" x2=\"80\" y2=\"30\" stroke=\"#64748b\" stroke-width=\"1.5\" marker-end=\"url(#arr26)\"/>\n      <text x=\"445\" y=\"205\" fill=\"#94a3b8\" font-size=\"12\">I (A)</text>\n      <text x=\"85\" y=\"35\" fill=\"#94a3b8\" font-size=\"12\">U (V)</text>\n      <!-- Downward line U = E - Ir -->\n      <line x1=\"80\" y1=\"60\" x2=\"380\" y2=\"180\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n      <!-- Intercept on U-axis: E -->\n      <circle cx=\"80\" cy=\"60\" r=\"5\" fill=\"#ef4444\"/>\n      <text x=\"50\" y=\"65\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">E</text>\n      <text x=\"95\" y=\"65\" fill=\"#ef4444\" font-size=\"11\">Điểm cắt U = E (khi I = 0)</text>\n      <!-- Experimental data points -->\n      <circle cx=\"140\" cy=\"84\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"200\" cy=\"108\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"260\" cy=\"132\" r=\"4\" fill=\"#fbbf24\"/>\n      <circle cx=\"320\" cy=\"156\" r=\"4\" fill=\"#fbbf24\"/>\n      <!-- Slope annotation -->\n      <text x=\"260\" y=\"105\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Độ dốc: -r = ΔU / ΔI</text>\n      <text x=\"130\" y=\"230\" fill=\"#94a3b8\" font-size=\"12\">Đồ thị thực nghiệm U = E - Ir đo suất điện động và r</text>\n    </svg>"},{"q":"Để đo suất điện động E và điện trở trong r của pin điện hoá, sơ đồ mạch thí nghiệm cần gồm:","opts":["Pin cần đo, điện trở bảo vệ, biến trở R, vôn kế mắc song song hai cực nguồn, ampe kế mắc nối tiếp trong mạch.","Pin cần đo, ampe kế mắc song song với nguồn và vôn kế mắc nối tiếp.","Pin cần đo chỉ cần nối trực tiếp với một ampe kế duy nhất có thang đo lớn.","Pin cần đo nối tiếp với một tụ điện và một bóng đèn công suất cao."],"ans":"A","exp":"• Vôn kế có điện trở rất lớn mắc song song với hai cực của nguồn để đo hiệu điện thế U.<br>• Ampe kế có điện trở rất nhỏ mắc nối tiếp để đo dòng điện I.<br>• Biến trở R dùng để thay đổi các giá trị (I, U) ghi nhận số liệu.","svgGraph":null},{"q":"Trong quá trình đo, tại sao mạch thí nghiệm luôn phải có một điện trở bảo vệ R₀ (cỡ vài ohm) mắc nối tiếp với biến trở R?","opts":["Để khi vô tình vặn biến trở R về giá trị 0 Ω thì mạch không bị đoản mạch làm hỏng pin và ampe kế.","Để khuếch đại suất điện động của pin lên mức cao hơn dễ đọc thang đo.","Để triệt tiêu hoàn toàn sai số dụng cụ đo của ampe kế và vôn kế.","Để ngăn không cho dòng điện xoay chiều xâm nhập vào hệ thống."],"ans":"A","exp":"• Khi vặn biến trở về 0, nếu không có R₀ thì điện trở mạch ngoài bằng 0 dẫn tới dòng điện tăng vọt (đoản mạch) làm cháy pin và hỏng ampe kế. R₀ đóng vai trò hạn dòng an toàn.","svgGraph":null},{"q":"Một nhóm học sinh tiến hành đo suất điện động và điện trở trong của một quả pin con thỏ cỡ AA. Từ đồ thị thực nghiệm U theo I, đường thẳng thực nghiệm cắt trục tung tại U₀ = 1,52 V và đi qua điểm (I = 0,4 A; U = 1,20 V). Xét tính Đúng / Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Dòng điện đoản mạch lí thuyết của quả pin này là 5 A.","Suất điện động của quả pin đo được là E = 1,52 V.","Độ giảm thế trong nguồn khi dòng điện I = 0,4 A là 0,32 V.","Điện trở trong của pin con thỏ tính được là r = 0,8 Ω."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Điểm cắt trục tung (I = 0) cho E = U₀ = 1,52 V.<br>• <b>Ý b [Đúng]:</b> ΔU = E - U = 1,52 - 1,20 = 0,32 V.<br>• <b>Ý c [Đúng]:</b> r = ΔU / I = 0,32 / 0,4 = 0,8 Ω.<br>• <b>Ý d [Sai]:</b> I<sub>đm</sub> = E / r = 1,52 / 0,8 = 1,9 A (không phải 5 A).","svgGraph":null},{"q":"Ghép các đại lượng hoặc thiết bị ở Cột A với vai trò tương ứng trong bài thực hành ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Biến trở con chạy R ➔ Đóng / ngắt mạch điện kịp thời để tránh pin bị nóng và tiêu hao năng lượng","Biến trở con chạy R ➔ Đo trực tiếp cường độ dòng điện chạy trong mạch kín","Vôn kế khung quay ➔ Đóng / ngắt mạch điện kịp thời để tránh pin bị nóng và tiêu hao năng lượng","Ampe kế điện tử ➔ Đo trực tiếp cường độ dòng điện chạy trong mạch kín"],"ans":0,"exp":"• <b>1 - C:</b> Biến trở thay đổi U, I.<br>• <b>2 - D:</b> Vôn kế đo U mạch ngoài.<br>• <b>3 - B:</b> Ampe kế đo dòng điện I.<br>• <b>4 - A:</b> Khoá K đóng/ngắt mạch bảo vệ pin.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trước khi đóng khoá K, cần chỉnh biến trở về giá trị  [ ... ]  để đảm bảo an toàn cho mạch. Khi đọc số đo trên ampe kế và vôn kế, cần đặt mắt nhìn  [ ... ]  với mặt kim chỉ thị. Sau mỗi lần đọc số liệu, nên  [ ... ]  để pin không bị cạn và không bị nóng làm thay đổi điện trở trong. Xử lí số liệu bằng phương pháp vẽ  [ ... ]  giúp loại bỏ sai số ngẫu nhiên tốt hơn cách tính trung bình từng cặp điểm.\"</i>","opts":["lớn nhất — vuông góc","không đổi","nhỏ nhất — để mạch đóng liên tục","vuông góc — lớn nhất"],"ans":0,"exp":"<b>Thao tác an toàn thực hành:</b><br>• Bắt đầu với R lớn nhất để I nhỏ an toàn.<br>• Mắt nhìn vuông góc tránh sai số thị sai.<br>• Ngắt khoá K sau khi ghi để tránh nóng pin.<br>• Phương pháp đồ thị giúp làm mịn và loại trừ sai số ngẫu nhiên.","svgGraph":null},{"q":"Nếu sử dụng vôn kế có điện trở R<sub>V</sub> chưa đủ lớn (R<sub>V</sub> hữu hạn) để đo hiệu điện thế hai cực của nguồn, sai số mắc phải sẽ làm cho giá trị suất điện động đo được:","opts":["Nhỏ hơn giá trị suất điện động thực tế của nguồn.","Lớn hơn giá trị suất điện động thực tế của nguồn.","Hoàn toàn không bị ảnh hưởng vì dòng qua vôn kế luôn bằng 0.","Bằng đúng hai lần suất điện động thực tế."],"ans":"A","exp":"• Khi R<sub>V</sub> hữu hạn, vôn kế nối vào nguồn vẫn có một dòng rò nhỏ I<sub>V</sub> = E / (r + R<sub>V</sub>) chạy qua nguồn, do đó số chỉ vôn kế là U<sub>V</sub> = E - I<sub>V</sub>·r < E. Vì vậy suất điện động đo được luôn nhỏ hơn giá trị thực.","svgGraph":null},{"q":"Kết quả đo suất điện động của một pin hoá học được biểu diễn dưới dạng: E = (1,50 ± 0,02) V. Sai số tỉ đối của phép đo suất điện động này là:","opts":["1,33%.","0,67%.","2,00%.","0,02%."],"ans":"A","exp":"• <b>Công thức sai số tỉ đối:</b> δ = <span class=\"fraction\"><span class=\"numerator\">ΔE</span><span class=\"denominator\">E<sub>tb</sub></span></span> · 100%<br>• <b>Thay số:</b> δ = <span class=\"fraction\"><span class=\"numerator\">0,02</span><span class=\"denominator\">1,50</span></span> · 100% ≈ 1,33%.","svgGraph":null},{"q":"Trong quá trình vẽ đường thẳng hồi quy U = E - Ir từ bảng số liệu thực nghiệm gồm 5 cặp điểm (I, U), xét tính Đúng / Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hệ số góc của đường thẳng bằng giá trị dương của điện trở trong r.","Đường thẳng hồi quy thực nghiệm cần đi qua càng nhiều điểm thực nghiệm càng tốt và phân bố đều các điểm lệch ở hai phía.","Nếu có một điểm đo bị lệch quá xa so với xu thế chung của các điểm còn lại, cần kiểm tra lại thao tác và loại bỏ điểm đo sai lệch thô này.","Giao điểm của đường kéo dài đồ thị với trục hoành (U = 0) là giá trị dòng điện đoản mạch I<sub>đm</sub>."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Phương pháp đồ thị bình phương tối thiểu phân bố đều các điểm.<br>• <b>Ý b [Đúng]:</b> Điểm dị biệt (outlier) do lỗi thao tác thô cần loại bỏ hoặc đo lại.<br>• <b>Ý c [Sai]:</b> U = E - Ir nên hệ số góc của đường thẳng mang dấu âm k = -r.<br>• <b>Ý d [Đúng]:</b> Tại U = 0 ⇒ 0 = E - I·r ⇒ I = E/r = I<sub>đm</sub>.","svgGraph":null},{"q":"Khi một pin điện hoá đã dùng lâu ngày bị 'chai pin', hiện tượng vật lí nào sau đây xảy ra bên trong pin?","opts":["Điện trở trong r của pin tăng lên đáng kể, làm hiệu điện thế cấp cho tải sụt giảm nhanh chóng.","Suất điện động của pin tăng vọt làm quá áp thiết bị tải.","Điện trở trong r của pin giảm dần về 0 khiến pin tự xả hết điện tích.","Lực lạ bên trong pin biến đổi hoàn toàn thành lực tĩnh điện Coulomb."],"ans":"A","exp":"• Khi pin bị chai do các phản ứng hoá học phụ và cạn dung dịch điện phân, điện trở trong r tăng vọt (từ dưới 1 Ω lên hàng chục hoặc hàng trăm Ω). Khi có tải tiêu thụ, sụt áp I·r bên trong pin rất lớn khiến điện áp ngoài U = E - Ir sụt mạnh không đủ cấp điện cho thiết bị.","svgGraph":null}]},"12":{"1":[{"q":"Theo mô hình động học phân tử về cấu trúc của chất, tính chất nào sau đây là đặc trưng cơ bản nhất của thể khí so với thể lỏng và thể rắn?","opts":["Các phân tử ở rất xa nhau, lực tương tác phân tử rất yếu, chuyển động hoàn toàn hỗn loạn chiếm toàn bộ thể tích bình chứa.","Các phân tử chỉ dao động nhiệt xung quanh các vị trí cân bằng cố định xác định.","Chất khí có thể tích riêng xác định nhưng hình dạng hoàn toàn phụ thuộc vào bình chứa.","Khoảng cách giữa các phân tử khí xấp xỉ bằng kích thước của chính các phân tử đó."],"ans":0,"exp":"• <b>Bản chất vật lí:</b> Ở thể khí, khoảng cách giữa các phân tử rất lớn (gấp hàng chục lần kích thước phân tử), do đó lực tương tác phân tử là rất yếu.<br>• Các phân tử khí chuyển động hỗn loạn không ngừng về mọi phía và chiếm toàn bộ dung tích của bình chứa khí.","svgGraph":"<svg viewBox=\"0 0 460 220\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"solG\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#38bdf8\"/><stop offset=\"100%\" stop-color=\"#0284c7\"/></radialGradient>\n    <radialGradient id=\"liqG\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#34d399\"/><stop offset=\"100%\" stop-color=\"#059669\"/></radialGradient>\n    <radialGradient id=\"gasG\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#f43f5e\"/><stop offset=\"100%\" stop-color=\"#be123c\"/></radialGradient>\n    <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feGaussianBlur stdDeviation=\"3\" result=\"blur\"/><feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/></filter>\n  </defs>\n  <!-- Box Solid -->\n  <rect x=\"15\" y=\"30\" width=\"130\" height=\"150\" rx=\"10\" fill=\"rgba(2,132,199,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n  <text x=\"80\" y=\"200\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">THỂ RẮN</text>\n  <text x=\"80\" y=\"214\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Trật tự, dao động tại chỗ</text>\n  <!-- 16 Solid molecules orderly -->\n  <g fill=\"url(#solG)\">\n    <circle cx=\"45\" cy=\"65\" r=\"9\"/><circle cx=\"68\" cy=\"65\" r=\"9\"/><circle cx=\"91\" cy=\"65\" r=\"9\"/><circle cx=\"114\" cy=\"65\" r=\"9\"/>\n    <circle cx=\"45\" cy=\"90\" r=\"9\"/><circle cx=\"68\" cy=\"90\" r=\"9\"/><circle cx=\"91\" cy=\"90\" r=\"9\"/><circle cx=\"114\" cy=\"90\" r=\"9\"/>\n    <circle cx=\"45\" cy=\"115\" r=\"9\"/><circle cx=\"68\" cy=\"115\" r=\"9\"/><circle cx=\"91\" cy=\"115\" r=\"9\"/><circle cx=\"114\" cy=\"115\" r=\"9\"/>\n    <circle cx=\"45\" cy=\"140\" r=\"9\"/><circle cx=\"68\" cy=\"140\" r=\"9\"/><circle cx=\"91\" cy=\"140\" r=\"9\"/><circle cx=\"114\" cy=\"140\" r=\"9\"/>\n  </g>\n  <!-- Box Liquid -->\n  <rect x=\"165\" y=\"30\" width=\"130\" height=\"150\" rx=\"10\" fill=\"rgba(5,150,105,0.12)\" stroke=\"#059669\" stroke-width=\"1.8\"/>\n  <text x=\"230\" y=\"200\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"13\" font-weight=\"700\">THỂ LỎNG</text>\n  <text x=\"230\" y=\"214\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Sát nhau, trượt tự do</text>\n  <g fill=\"url(#liqG)\">\n    <circle cx=\"190\" cy=\"100\" r=\"9\"/><circle cx=\"215\" cy=\"95\" r=\"9\"/><circle cx=\"240\" cy=\"105\" r=\"9\"/><circle cx=\"265\" cy=\"98\" r=\"9\"/>\n    <circle cx=\"195\" cy=\"125\" r=\"9\"/><circle cx=\"225\" cy=\"128\" r=\"9\"/><circle cx=\"250\" cy=\"132\" r=\"9\"/><circle cx=\"270\" cy=\"122\" r=\"9\"/>\n    <circle cx=\"185\" cy=\"155\" r=\"9\"/><circle cx=\"210\" cy=\"158\" r=\"9\"/><circle cx=\"238\" cy=\"155\" r=\"9\"/><circle cx=\"262\" cy=\"152\" r=\"9\"/>\n  </g>\n  <!-- Box Gas -->\n  <rect x=\"315\" y=\"30\" width=\"130\" height=\"150\" rx=\"10\" fill=\"rgba(190,18,60,0.12)\" stroke=\"#be123c\" stroke-width=\"1.8\"/>\n  <text x=\"380\" y=\"200\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"700\">THỂ KHÍ</text>\n  <text x=\"380\" y=\"214\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Ở rất xa nhau, hỗn loạn</text>\n  <g fill=\"url(#gasG)\">\n    <circle cx=\"340\" cy=\"55\" r=\"8\"/><line x1=\"340\" y1=\"55\" x2=\"355\" y2=\"70\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"415\" cy=\"70\" r=\"8\"/><line x1=\"415\" y1=\"70\" x2=\"395\" y2=\"85\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"360\" cy=\"115\" r=\"8\"/><line x1=\"360\" y1=\"115\" x2=\"375\" y2=\"135\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"420\" cy=\"145\" r=\"8\"/><line x1=\"420\" y1=\"145\" x2=\"400\" y2=\"135\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <circle cx=\"345\" cy=\"160\" r=\"8\"/><line x1=\"345\" y1=\"160\" x2=\"330\" y2=\"145\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  </g>\n</svg>"},{"q":"Điểm khác biệt căn bản nhất về mặt cấu trúc và tính chất vật lí giữa chất rắn kết tinh và chất rắn vô định hình là:","opts":["Chất rắn kết tinh có cấu trúc mạng tinh thể và có nhiệt độ nóng chảy xác định, còn chất rắn vô định hình không có nhiệt độ nóng chảy xác định.","Chất rắn kết tinh luôn dẫn điện tốt hơn chất rắn vô định hình trong mọi điều kiện.","Chất rắn vô định hình có hình dạng hình học xác định khi bị nung nóng.","Chất rắn kết tinh có tính đẳng hướng đối với mọi tính chất vật lí."],"ans":0,"exp":"• <b>Chất rắn kết tinh:</b> Các hạt liên kết theo một trật tự tuần hoàn hình học gọi là <i>mạng tinh thể</i>, có <b>nhiệt độ nóng chảy hoàn toàn xác định</b> (ở áp suất chuẩn).<br>• <b>Chất rắn vô định hình</b> (như thủy tinh, nhựa đường): Không có cấu trúc mạng tuần hoàn, khi bị đốt nóng sẽ mềm dần rồi chuyển sang lỏng, <b>không có nhiệt độ nóng chảy xác định</b>.","svgGraph":null},{"q":"Hiện tượng nào sau đây là minh chứng thực tế rõ nét nhất cho sự thăng hoa (chuyển trực tiếp từ thể rắn sang thể khí mà không qua thể lỏng)?","opts":["Viên băng phiến (long não) đặt trong tủ quần áo có kích thước nhỏ dần sau một thời gian.","Giọt sương đọng trên lá cây tan biến khi mặt trời lên cao.","Cục nước đá tan chảy thành nước trong cốc thủy tinh.","Nước sôi trong ấm tạo thành làn khói trắng bốc lên."],"ans":0,"exp":"• <b>Thăng hoa</b> là quá trình một chất chuyển trực tiếp từ <b>thể rắn sang thể khí</b> mà không trải qua thể lỏng.<br>• Viên băng phiến (long não) hoặc đá khô (CO₂ rắn) tự biến đổi trực tiếp thành hơi lan tỏa trong không khí chính là hiện tượng thăng hoa.","svgGraph":null},{"q":"Khi khảo sát mô hình cấu trúc phân tử và sự chuyển thể của nước, hãy xác định tính Đúng/Sai của từng nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Sự bay hơi của nước chỉ diễn ra ở nhiệt độ sôi 100°C tại mặt thoáng chất lỏng.","Ở thể lỏng, các phân tử nước ở gần nhau hơn ở thể khí và có lực tương tác phân tử lớn hơn ở thể khí.","Trong suốt quá trình nước đá tinh khiết đang nóng chảy ở áp suất 1 atm, nhiệt độ của hệ luôn duy trì ổn định ở 0°C.","Sự sôi là quá trình hoá hơi đặc biệt xảy ra đồng thời ở cả trong lòng và trên bề mặt chất lỏng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Thể lỏng có mật độ phân tử dày đặc hơn khí, lực tương tác phân tử lớn hơn nhiều so với thể khí.<br>• <b>Ý b [Sai]:</b> Sự bay hơi diễn ra ở <i>mọi nhiệt độ</i> trên bề mặt thoáng của chất lỏng, không nhất thiết phải đạt 100°C.<br>• <b>Ý c [Đúng]:</b> Nước đá là chất rắn kết tinh, trong suốt thời gian nóng chảy ở áp suất chuẩn, nhiệt độ không đổi ở 0°C.<br>• <b>Ý d [Đúng]:</b> Định nghĩa chuẩn SGK: Sự sôi là sự hoá hơi xảy ra cả ở bên trong lòng chất lỏng và trên mặt thoáng.","svgGraph":null},{"q":"Ghép từng hiện tượng thực tiễn trong đời sống (Cột A) với tên quá trình chuyển thể tương ứng của chất (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Sương mù xuất hiện vào sáng sớm mùa đông rồi tan dần khi mặt trời lên ➔ Sự thăng hoa (Rắn chuyển trực tiếp thành Khí)","Sương mù xuất hiện vào sáng sớm mùa đông rồi tan dần khi mặt trời lên ➔ Sự ngưng tụ của hơi nước trong khí quyển","Viên nước đá khô (CO₂ rắn) bốc khói mịt mù trong các hiệu ứng sân khấu ➔ Sự thăng hoa (Rắn chuyển trực tiếp thành Khí)","Nghề làm muối thủ công trên các cánh đồng muối ven biển ➔ Sự ngưng tụ của hơi nước trong khí quyển"],"ans":0,"exp":"• <b>1 ghép B:</b> Hơi nước trong không khí gặp lạnh ngưng tụ thành hạt sương li ti.<br>• <b>2 ghép A:</b> CO₂ rắn thăng hoa trực tiếp thành khí CO₂ lạnh làm ngưng tụ hơi ẩm không khí tạo khói trắng.<br>• <b>3 ghép D:</b> Nước biển dưới nắng gió bay hơi để lại muối kết tinh trên ruộng.<br>• <b>4 ghép C:</b> Nung đồng nóng chảy rót vào khuôn, sau đó nguội đông đặc thành tượng.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Các chất được cấu tạo từ các  [ ... ]  riêng biệt. Các phân tử chuyển động  [ ... ]  không ngừng. Nhiệt độ của vật càng cao thì tốc độ chuyển động nhiệt của các phân tử càng  [ ... ] . Giữa các phân tử đồng thời tồn tại lực  [ ... ]  và lực đẩy.\"</i>","opts":["phân tử — nguyên tố","không đổi","nhỏ — hút","nguyên tố — phân tử"],"ans":0,"exp":"<b>Nội dung thuyết động học phân tử:</b><br>1. Các chất cấu tạo từ các hạt riêng biệt gọi là phân tử.<br>2. Các phân tử chuyển động hỗn loạn không ngừng; nhiệt độ càng cao chuyển động càng nhanh.<br>3. Giữa các phân tử đồng thời có lực tương tác gồm cả lực hút và lực đẩy.","svgGraph":null},{"q":"Biết khối lượng mol của nước là 18 g/mol và số Avogadro N<sub>A</sub> = 6,022 × 10²³ mol⁻¹. Số lượng phân tử nước chứa trong một cốc nước có thể tích V = 180 cm³ (biết khối lượng riêng của nước là D = 1 g/cm³) là:","opts":["6,022 × 10²⁴ phân tử","6,022 × 10²³ phân tử","1,084 × 10²⁵ phân tử","3,345 × 10²³ phân tử"],"ans":0,"exp":"• Khối lượng nước trong cốc:<div class='formula-box'><span class='math-sym'>m = D · V = 1 × 180 = 180 g</span></div>• Số mol nước:<div class='formula-box'><span class='math-sym'>n = <div class='fraction'><span class='numerator'>m</span><span class='denominator'>M</span></div> = <div class='fraction'><span class='numerator'>180</span><span class='denominator'>18</span></div> = 10 mol</span></div>• Số phân tử nước:<div class='formula-box'><span class='math-sym'>N = n · N<sub>A</sub> = 10 × 6,022 × 10²³ = 6,022 × 10²⁴ phân tử</span></div>","svgGraph":null},{"q":"Hình vẽ dưới đây biểu diễn đường đặc tuyến nhiệt độ theo thời gian khi đun nóng liên tục một khối chất rắn kết tinh từ thể rắn đến khi chuyển thể hoàn toàn. Dựa vào đồ thị, chất rắn này bắt đầu nóng chảy ở nhiệt độ nào và quá trình nóng chảy diễn ra trong khoảng thời gian bao lâu?","opts":["Nóng chảy ở 80°C, diễn ra trong 4 phút (từ phút thứ 3 đến phút thứ 7)","Nóng chảy ở 60°C, diễn ra trong 3 phút (từ phút thứ 0 đến phút thứ 3)","Nóng chảy ở 100°C, diễn ra trong 5 phút (từ phút thứ 7 đến phút thứ 12)","Nóng chảy ở 80°C, diễn ra trong 7 phút (từ phút thứ 0 đến phút thứ 7)"],"ans":0,"exp":"• Trên đồ thị, đoạn nằm ngang song song trục thời gian biểu diễn quá trình chuyển thể (nóng chảy) vì nhiệt độ được giữ không đổi dù liên tục nhận nhiệt.<br>• Đoạn nằm ngang ở giá trị nhiệt độ <span class='math-sym'>T = 80°C</span> (đây chính là nhiệt độ nóng chảy của chất).<br>• Thời điểm bắt đầu nóng chảy: phút thứ 3; kết thúc nóng chảy: phút thứ 7.<br>• Thời gian diễn ra nóng chảy: <span class='math-sym'>Δt = 7 - 3 = 4 phút</span>.","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"60\" x2=\"400\" y2=\"60\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"120\" x2=\"400\" y2=\"120\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"180\" x2=\"400\" y2=\"180\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <line x1=\"140\" y1=\"210\" x2=\"140\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"260\" y1=\"210\" x2=\"260\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"410\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"415\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (phút)</text>\n            <text x=\"30\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">T (°C)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"135\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">3</text>\n            <text x=\"255\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">7</text>\n            \n            <text x=\"20\" y=\"185\" fill=\"#cbd5e1\" font-size=\"13\">25°</text>\n            <text x=\"20\" y=\"125\" fill=\"#cbd5e1\" font-size=\"13\">80°</text>\n            <text x=\"15\" y=\"65\" fill=\"#cbd5e1\" font-size=\"13\">110°</text>\n\n            <!-- Đường đặc tuyến -->\n            <line x1=\"50\" y1=\"180\" x2=\"140\" y2=\"120\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"50\" cy=\"180\" r=\"4\" fill=\"#06b6d4\" />\n            <circle cx=\"140\" cy=\"120\" r=\"5\" fill=\"#f43f5e\" />\n\n            <line x1=\"140\" y1=\"120\" x2=\"260\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"4\" />\n            <circle cx=\"260\" cy=\"120\" r=\"5\" fill=\"#f43f5e\" />\n\n            <line x1=\"260\" y1=\"120\" x2=\"360\" y2=\"60\" stroke=\"#10b981\" stroke-width=\"3.5\" />\n            <circle cx=\"360\" cy=\"60\" r=\"4\" fill=\"#10b981\" />\n\n            <!-- Nhãn vùng -->\n            <text x=\"65\" y=\"145\" fill=\"#06b6d4\" font-size=\"13\" font-weight=\"700\">Rắn</text>\n            <text x=\"175\" y=\"110\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"800\">Nóng chảy</text>\n            <text x=\"300\" y=\"85\" fill=\"#10b981\" font-size=\"13\" font-weight=\"700\">Lỏng</text>\n          </svg>"},{"q":"Trong thí nghiệm đun nóng chất rắn và quan sát sự chuyển thể sử dụng đèn cồn, nhiệt kế và ống nghiệm đựng băng phiến. Hãy xét tính Đúng/Sai của các thao tác thực hành: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi băng phiến bắt đầu nóng chảy, nhiệt kế ghi nhận nhiệt độ tăng vọt đột ngột.","Nên đun cách thủy ống nghiệm đựng băng phiến trong cốc nước thay vì hơ trực tiếp ống nghiệm trên ngọn lửa đèn cồn để nhiệt truyền đều khắp khối chất.","Phải đặt bầu nhiệt kế ngập hoàn toàn trong khối chất băng phiến và không chạm vào đáy ống nghiệm.","Trong suốt giai đoạn nóng chảy, băng phiến tồn tại đồng thời ở cả thể rắn và thể lỏng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Đun cách thủy giúp phân bố nhiệt lượng êm dịu, đều đặn, tránh cháy cục bộ đáy ống.<br>• <b>Ý b [Sai]:</b> Băng phiến là chất rắn kết tinh, khi bắt đầu nóng chảy nhiệt độ giữ cố định ở 80°C chứ không tăng vọt.<br>• <b>Ý c [Đúng]:</b> Bầu nhiệt kế đo nhiệt độ khối chất, nếu chạm đáy ống nghiệm sẽ đo sai lệch nhiệt độ ngọn lửa bên ngoài.<br>• <b>Ý d [Đúng]:</b> Trong suốt thời gian chuyển thể, hai pha rắn và lỏng cùng tồn tại cân bằng nhiệt.","svgGraph":null},{"q":"Công nghệ sấy thăng hoa (Freeze Drying) hiện đại ứng dụng trong bảo quản thực phẩm cao cấp và dược phẩm dựa trên nguyên lí vật lí nào?","opts":["Làm đông lạnh thực phẩm ở nhiệt độ rất thấp, sau đó giảm mạnh áp suất môi trường xuống dưới điểm ba thể để nước đá thăng hoa trực tiếp thành hơi.","Đun nóng nhanh thực phẩm lên nhiệt độ trên 100°C ở áp suất cực cao để nước sôi tức thì.","Dùng lực ly tâm cực đại để vắt kiệt toàn bộ các phân tử nước tự do ra khỏi tế bào sinh học.","Ngâm thực phẩm vào dung dịch muối đậm đặc để rút nước qua màng bán thấm."],"ans":0,"exp":"• <b>Sấy thăng hoa:</b> Thực phẩm trước hết được cấp đông sâu để nước đóng băng hoàn toàn. Sau đó đặt vào buồng chân không áp suất cực thấp.<br>• Ở áp suất chân không thấp hơn áp suất điểm ba trạng thái của nước (<span class='math-sym'>p < 611 Pa</span>), băng đá sẽ <b>thăng hoa trực tiếp thành hơi nước</b> mà không chảy lỏng, giữ nguyên vẹn 100% hình dạng, màu sắc và vitamin của thực phẩm.","svgGraph":null}],"2":[{"q":"Trong nhiệt động lực học, nội năng (U) của một vật thể được định nghĩa chuẩn xác là:","opts":["Tổng động năng chuyển động nhiệt hỗn loạn của các phân tử cấu tạo nên vật và thế năng tương tác giữa chúng.","Tổng động năng chuyển động có hướng của toàn bộ vật thể so với mặt đất.","Thế năng trọng trường của vật thể đặt ở một độ cao xác định so với mốc thế năng.","Năng lượng bức xạ điện từ mà vật thể liên tục phát ra ngoài môi trường xung quanh."],"ans":0,"exp":"• <b>Định nghĩa SGK Vật Lí 12:</b> Nội năng của một vật là tổng động năng của các phân tử cấu tạo nên vật (do chuyển động nhiệt) và thế năng tương tác giữa chúng.<br>• Ký hiệu là <span class='math-sym'>U</span>, đơn vị trong hệ SI là Jun (J). Nội năng phụ thuộc vào nhiệt độ <span class='math-sym'>T</span> và thể tích <span class='math-sym'>V</span> của vật: <span class='math-sym'>U = f(T, V)</span>.","svgGraph":null},{"q":"Điểm khác biệt bản chất nhất giữa hai quá trình làm biến đổi nội năng: 'Thực hiện công' và 'Truyền nhiệt' là gì?","opts":["Thực hiện công có sự chuyển hoá năng lượng từ dạng khác (cơ năng, điện năng...) thành nội năng; còn truyền nhiệt là sự truyền trực tiếp nội năng mà không có sự chuyển hoá dạng năng lượng.","Thực hiện công luôn làm nội năng tăng, còn truyền nhiệt luôn làm nội năng giảm.","Truyền nhiệt chỉ xảy ra khi có sự tiếp xúc trực tiếp giữa các vật rắn.","Thực hiện công chỉ xảy ra đối với các khối chất khí trong xilanh kín."],"ans":0,"exp":"• <b>Bản chất năng lượng:</b><br>- <i>Thực hiện công:</i> Có sự chuyển hoá giữa các dạng năng lượng khác (ví dụ cơ năng cọ xát thành nội năng làm vật nóng lên).<br>- <i>Truyền nhiệt:</i> Không có sự chuyển hoá dạng năng lượng, chỉ là sự trao đổi chuyển giao nội năng từ vật có nhiệt độ cao sang vật có nhiệt độ thấp hơn.","svgGraph":null},{"q":"Theo biểu thức định luật I của nhiệt động lực học ΔU = A + Q, hãy xác định tính Đúng/Sai của các nhận định sau về quy ước dấu đại số: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hệ nhận công từ ngoại lực bên ngoài tác dụng vào thì quy ước A < 0.","Hệ nhận nhiệt lượng từ môi trường ngoài thì quy ước Q > 0.","Khối khí dãn nở đẩy pittong di chuyển thực hiện công lên ngoại vật thì quy ước A < 0.","Một hệ biến đổi trong một chu trình kín khép kín quay về trạng thái ban đầu thì độ biến thiên nội năng ΔU = 0."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Hệ nhận nhiệt: <span class='math-sym'>Q > 0</span>; hệ tỏa nhiệt: <span class='math-sym'>Q < 0</span>.<br>• <b>Ý b [Sai]:</b> Hệ nhận công từ ngoại lực tác dụng nén vào: quy ước <span class='math-sym'>A > 0</span>.<br>• <b>Ý c [Đúng]:</b> Hệ sinh công đẩy pittong ra ngoài: quy ước <span class='math-sym'>A < 0</span>.<br>• <b>Ý d [Đúng]:</b> Nội năng là hàm trạng thái. Khi đi hết một chu trình kín quay về trạng thái ban đầu thì <span class='math-sym'>U<sub>cuối</sub>ối = U<sub>đầu</sub> ⟹ ΔU = 0</span>.","svgGraph":null},{"q":"Ghép từng quá trình biến đổi thực tế của khối khí trong xilanh (Cột A) với biểu thức tương ứng của Định luật I Nhiệt động lực học (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Khối khí bị nén nhanh trong xilanh cách nhiệt hoàn toàn (không trao đổi nhiệt) ➔ Q = 0 ⟹ ΔU = A (với A > 0, nội năng tăng)","Khối khí bị nén nhanh trong xilanh cách nhiệt hoàn toàn (không trao đổi nhiệt) ➔ ΔU = 0 ⟹ Q = -A (với A < 0, nhiệt lượng nhận chuyển thành công)","Khối khí dãn nở đẳng nhiệt ở nhiệt độ không đổi (nội năng không đổi) ➔ Q = 0 ⟹ ΔU = A (với A > 0, nội năng tăng)","Khối khí được đốt nóng trong bình kín có thể tích cố định (đẳng tích không sinh công) ➔ ΔU = 0 ⟹ Q = -A (với A < 0, nhiệt lượng nhận chuyển thành công)"],"ans":0,"exp":"• <b>1 ghép A:</b> Đoạn nhiệt (<span class='math-sym'>Q = 0</span>), nén nhận công (<span class='math-sym'>A > 0</span>) ⟹ <span class='math-sym'>ΔU = A > 0</span> (khí nóng lên).<br>• <b>2 ghép B:</b> Đẳng nhiệt (<span class='math-sym'>ΔU = 0</span>) ⟹ <span class='math-sym'>Q = -A</span>.<br>• <b>3 ghép C:</b> Đẳng tích thể tích không đổi ⟹ không sinh công (<span class='math-sym'>A = 0</span>) ⟹ <span class='math-sym'>ΔU = Q</span>.<br>• <b>4 ghép D:</b> Dãn khí đoạn nhiệt (<span class='math-sym'>Q = 0</span>, <span class='math-sym'>A < 0</span>) ⟹ <span class='math-sym'>ΔU = A < 0</span> (khí bị làm lạnh).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Độ biến thiên nội năng của một hệ bằng tổng  [ ... ]  và  [ ... ]  mà hệ nhận được. Biểu thức đại số là:  [ ... ]  = A + Q. Định luật I thực chất là sự vận dụng định luật bảo toàn và chuyển hoá  [ ... ]  vào các hiện tượng nhiệt.\"</i>","opts":["công — nhiệt lượng","không đổi","p·V — động lượng","nhiệt lượng — công"],"ans":0,"exp":"<b>Nội dung Định luật I Nhiệt động lực học:</b><br><div class='formula-box'><span class='math-sym'>ΔU = A + Q</span></div>Độ biến thiên nội năng của hệ bằng tổng công và nhiệt lượng mà hệ nhận được. Đây là trường hợp riêng của định luật bảo toàn và chuyển hoá năng lượng.","svgGraph":null},{"q":"Người ta truyền cho một khối khí trong xilanh nhiệt lượng Q = 250 J. Khối khí nở ra thực hiện công A' = 150 J đẩy pittong đi lên. Độ biến thiên nội năng ΔU của khối khí là:","opts":["ΔU = +100 J","ΔU = +400 J","ΔU = -100 J","ΔU = -400 J"],"ans":0,"exp":"• Theo quy ước dấu:<br>- Khí nhận nhiệt lượng: <span class='math-sym'>Q = +250 J</span>.<br>- Khí thực hiện công <span class='math-sym'>A' = 150 J</span> nên công hệ nhận vào mang dấu âm: <span class='math-sym'>A = -150 J</span>.<br>• Độ biến thiên nội năng:<div class='formula-box'><span class='math-sym'>ΔU = A + Q = -150 + 250 = +100 J</span></div>Nội năng của khối khí tăng thêm 100 J.","svgGraph":null},{"q":"Một khối khí bị nén trong xilanh bởi một lực ngoài thực hiện công A = 180 J lên khối khí. Biết trong quá trình nén, khối khí đã tỏa ra môi trường xung quanh một nhiệt lượng 60 J. Nội năng của khối khí biến đổi như thế nào?","opts":["Tăng thêm 120 J","Giảm đi 120 J","Tăng thêm 240 J","Giảm đi 240 J"],"ans":0,"exp":"• Theo quy ước dấu:<br>- Khí nhận công: <span class='math-sym'>A = +180 J</span>.<br>- Khí tỏa nhiệt ra môi trường: <span class='math-sym'>Q = -60 J</span>.<br>• Độ biến thiên nội năng:<div class='formula-box'><span class='math-sym'>ΔU = A + Q = 180 + (-60) = +120 J</span></div>Vì <span class='math-sym'>ΔU > 0</span> nên nội năng của khối khí <b>tăng thêm 120 J</b>.","svgGraph":null},{"q":"Hình vẽ dưới đây là đồ thị biểu diễn quá trình dãn nở đẳng áp của một khối khí lí tưởng từ trạng thái (1) có thể tích V₁ = 2 lít đến trạng thái (2) có thể tích V₂ = 6 lít ở áp suất không đổi p = 2 × 10⁵ Pa. Công do khối khí này sinh ra trong quá trình dãn nở có độ lớn bằng:","opts":["800 J","1200 J","400 J","1600 J"],"ans":0,"exp":"• Trong quá trình đẳng áp (<span class='math-sym'>p = const</span>), độ lớn của công do khối khí sinh ra bằng diện tích hình chữ nhật bên dưới đường đồ thị trong hệ tọa độ <span class='math-sym'>p - V</span>:<div class='formula-box'><span class='math-sym'>A' = p · ΔV = p · (V₂ - V₁)</span></div>• Đổi đơn vị: <span class='math-sym'>V₁ = 2 lít = 2 × 10⁻³ m³; V₂ = 6 lít = 6 × 10⁻³ m³ ⟹ ΔV = 4 × 10⁻³ m³</span>.<br>• Tính công:<div class='formula-box'><span class='math-sym'>A' = 2 × 10⁵ × 4 × 10⁻³ = 800 J</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới nền -->\n            <line x1=\"60\" y1=\"90\" x2=\"380\" y2=\"90\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"140\" y1=\"210\" x2=\"140\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"320\" y1=\"210\" x2=\"320\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Vùng diện tích công gạch sọc/màu -->\n            <rect x=\"140\" y=\"90\" width=\"180\" height=\"120\" fill=\"rgba(6, 182, 212, 0.15)\" stroke=\"rgba(6, 182, 212, 0.4)\" stroke-dasharray=\"3\"/>\n            <text x=\"205\" y=\"155\" fill=\"#38bdf8\" font-size=\"16\" font-weight=\"800\">Diện tích = A</text>\n\n            <!-- Trục tọa độ -->\n            <line x1=\"60\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"60\" y1=\"210\" x2=\"60\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">V (lít)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">p (10⁵ Pa)</text>\n            <text x=\"46\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"135\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">2</text>\n            <text x=\"315\" y=\"230\" fill=\"#cbd5e1\" font-size=\"13\">6</text>\n            <text x=\"36\" y=\"95\" fill=\"#cbd5e1\" font-size=\"13\">2</text>\n\n            <!-- Đường quá trình 1 -> 2 -->\n            <line x1=\"140\" y1=\"90\" x2=\"320\" y2=\"90\" stroke=\"#f43f5e\" stroke-width=\"4\" marker-mid=\"url(#arrow)\" />\n            <circle cx=\"140\" cy=\"90\" r=\"5\" fill=\"#06b6d4\" />\n            <circle cx=\"320\" cy=\"90\" r=\"5\" fill=\"#f43f5e\" />\n            \n            <text x=\"130\" y=\"75\" fill=\"#06b6d4\" font-size=\"15\" font-weight=\"800\">(1)</text>\n            <text x=\"325\" y=\"75\" fill=\"#f43f5e\" font-size=\"15\" font-weight=\"800\">(2)</text>\n          </svg>"},{"q":"Trong thí nghiệm nén khí bằng bơm tay để kiểm chứng Định luật I: Bơm khí liên tục vào một bình nhựa kín chứa một ít cồn và có gắn nhiệt kế kỹ thuật số, sau một lát nút chai đột ngột bật tung ra kèm theo sương mù xuất hiện trong bình. Hãy xét tính Đúng/Sai của các nhận định: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hiện tượng sương mù trắng xuất hiện trong bình là do hơi cồn bị bốc cháy dưới áp suất cao.","Khi dùng bơm nén khí vào bình, công của lực nén làm tăng nội năng và làm nhiệt độ khối khí trong bình tăng lên.","Khi nút chai bật tung ra, khối khí dãn nở rất nhanh thực hiện công lên nút chai.","Vì quá trình dãn nở diễn ra rất nhanh nên coi như đoạn nhiệt (Q ≈ 0), khí mất nội năng để sinh công làm nhiệt độ giảm đột ngột."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Nhận công <span class='math-sym'>A > 0 ⟹ ΔU > 0</span> làm khí nóng lên.<br>• <b>Ý b [Đúng]:</b> Khí bung nở đẩy nút bay đi là quá trình sinh công cơ học.<br>• <b>Ý c [Đúng]:</b> Quá trình dãn nở chớp nhoáng là đoạn nhiệt (<span class='math-sym'>Q ≈ 0</span>), từ <span class='math-sym'>ΔU = A' < 0</span> nên nhiệt độ giảm mạnh.<br>• <b>Ý d [Sai]:</b> Nhiệt độ hạ xuống đột ngột làm hơi cồn và hơi nước gặp lạnh <b>ngưng tụ</b> thành các giọt sương li ti tạo làn sương mù trắng, không phải bốc cháy.","svgGraph":null},{"q":"Một động cơ nhiệt hoạt động tuần hoàn nhận từ nguồn nóng nhiệt lượng Q₁ = 1000 J trong mỗi chu trình và truyền cho nguồn lạnh nhiệt lượng Q₂ = 650 J. Hiệu suất nhiệt của động cơ này là:","opts":["35%","65%","53,8%","70%"],"ans":0,"exp":"• Công có ích động cơ sinh ra trong một chu trình:<div class='formula-box'><span class='math-sym'>A = Q₁ - Q₂ = 1000 - 650 = 350 J</span></div>• Hiệu suất của động cơ nhiệt:<div class='formula-box'><span class='math-sym'>H = <div class='fraction'><span class='numerator'>A</span><span class='denominator'>Q₁</span></div> = <div class='fraction'><span class='numerator'>350</span><span class='denominator'>1000</span></div> = 0,35 = 35%</span></div>","svgGraph":null}],"3":[{"q":"Theo quan điểm của thuyết động học phân tử, nhiệt độ là đại lượng vật lí đặc trưng cho:","opts":["Động năng tịnh tiến trung bình của các phân tử cấu tạo nên vật thể.","Tổng thế năng tương tác giữa tất cả các phân tử trong vật.","Vận tốc chuyển động có hướng của khối tâm vật thể.","Mật độ hạt phân tử phân bố trên một đơn vị thể tích của chất."],"ans":0,"exp":"• <b>Bản chất vi mô:</b> Nhiệt độ không phản ánh vận tốc của từng phân tử riêng lẻ mà là thước đo <b>động năng tịnh tiến trung bình</b> của tập hợp vô số phân tử cấu tạo nên vật: <span class='math-sym'>E<sub>đ</sub> = (<span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span>) · k · T</span>.<br>• Vật có nhiệt độ càng cao thì các phân tử chuyển động nhiệt hỗn loạn càng nhanh.","svgGraph":null},{"q":"Khái niệm 'Độ không tuyệt đối' (0 K trong thang nhiệt độ Kelvin) có ý nghĩa vật lí cơ bản là:","opts":["Nhiệt độ thấp nhất theo lí thuyết mà tại đó động năng chuyển động nhiệt của các phân tử triệt tiêu về mức cực tiểu.","Nhiệt độ tại đó nước tinh khiết bắt đầu đóng băng ở áp suất chuẩn 1 atm.","Nhiệt độ thấp nhất từng được ghi nhận trong khí quyển bề mặt Trái Đất.","Nhiệt độ mà tại đó tất cả các chất lỏng đều bắt đầu sôi mãnh liệt."],"ans":0,"exp":"• <b>Độ không tuyệt đối (0 K hay -273,15°C):</b> Là nhiệt độ thấp nhất có thể có về mặt nhiệt động lực học.<br>• Ở nhiệt độ này, chuyển động nhiệt hỗn loạn của các phân tử giảm về mức thấp nhất (triệt tiêu theo cơ học cổ điển, dừng ở trạng thái năng lượng điểm không theo cơ học lượng tử).","svgGraph":null},{"q":"Xét các thang nhiệt độ thông dụng (Celsius, Kelvin, Fahrenheit), hãy kiểm tra tính Đúng/Sai của từng nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trong thang nhiệt độ Kelvin, giá trị nhiệt độ tuyệt đối có thể nhận giá trị âm dưới 0 K.","Trong thang Celsius, điểm đóng băng của nước tinh khiết là 0°C và điểm sôi là 100°C ở áp suất 1 atm.","Độ biến thiên nhiệt độ 1 K trong thang Kelvin có độ lớn bằng đúng độ biến thiên nhiệt độ 1°C trong thang Celsius (ΔT = Δt).","Ở áp suất tiêu chuẩn 1 atm, nước tinh khiết sôi ở nhiệt độ 212°F trên thang Fahrenheit."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Thang Celsius định chuẩn 0°C (băng tan) và 100°C (nước sôi ở 1 atm).<br>• <b>Ý b [Đúng]:</b> Vì <span class='math-sym'>T = t + 273,15 ⟹ ΔT = Δt</span> (khoảng cách 1 độ là như nhau).<br>• <b>Ý c [Sai]:</b> Thang Kelvin bắt đầu từ 0 K (độ không tuyệt đối), nhiệt độ tuyệt đối <span class='math-sym'>T ≥ 0 K</span>, không có giá trị âm.<br>• <b>Ý d [Đúng]:</b> <span class='math-sym'>t<sub>F</sub> = 1,8 × 100 + 32 = 212°F</span>.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"cGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\"><stop offset=\"0%\" stop-color=\"#3b82f6\"/><stop offset=\"50%\" stop-color=\"#10b981\"/><stop offset=\"100%\" stop-color=\"#ef4444\"/></linearGradient>\n    <linearGradient id=\"kGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\"><stop offset=\"0%\" stop-color=\"#6366f1\"/><stop offset=\"50%\" stop-color=\"#06b6d4\"/><stop offset=\"100%\" stop-color=\"#f59e0b\"/></linearGradient>\n  </defs>\n  <!-- Background Box -->\n  <rect x=\"15\" y=\"10\" width=\"430\" height=\"190\" rx=\"14\" fill=\"rgba(15,23,42,0.85)\" stroke=\"rgba(56,189,248,0.3)\" stroke-width=\"1.5\"/>\n  <!-- Thermometer C -->\n  <text x=\"120\" y=\"32\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">Thang Celsius (°C)</text>\n  <rect x=\"110\" y=\"45\" width=\"20\" height=\"120\" rx=\"10\" fill=\"url(#cGrad)\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"170\" r=\"16\" fill=\"#3b82f6\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  <!-- Thermometer K -->\n  <text x=\"340\" y=\"32\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"14\" font-weight=\"800\">Thang Kelvin (K)</text>\n  <rect x=\"330\" y=\"45\" width=\"20\" height=\"120\" rx=\"10\" fill=\"url(#kGrad)\" stroke=\"#34d399\" stroke-width=\"1.5\"/>\n  <circle cx=\"340\" cy=\"170\" r=\"16\" fill=\"#6366f1\" stroke=\"#34d399\" stroke-width=\"1.5\"/>\n  <!-- Reference lines -->\n  <!-- Boiling point -->\n  <line x1=\"130\" y1=\"55\" x2=\"330\" y2=\"55\" stroke=\"#ef4444\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <text x=\"85\" y=\"59\" fill=\"#ef4444\" font-size=\"12\" font-weight=\"700\" text-anchor=\"end\">100 °C</text>\n  <text x=\"230\" y=\"52\" fill=\"#ef4444\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Điểm sôi của nước (1 atm)</text>\n  <text x=\"375\" y=\"59\" fill=\"#ef4444\" font-size=\"12\" font-weight=\"700\" text-anchor=\"start\">373,15 K</text>\n  <!-- Freezing point -->\n  <line x1=\"130\" y1=\"105\" x2=\"330\" y2=\"105\" stroke=\"#10b981\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <text x=\"85\" y=\"109\" fill=\"#10b981\" font-size=\"12\" font-weight=\"700\" text-anchor=\"end\">0 °C</text>\n  <text x=\"230\" y=\"102\" fill=\"#10b981\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Điểm đóng băng của nước</text>\n  <text x=\"375\" y=\"109\" fill=\"#10b981\" font-size=\"12\" font-weight=\"700\" text-anchor=\"start\">273,15 K</text>\n  <!-- Absolute zero -->\n  <line x1=\"130\" y1=\"155\" x2=\"330\" y2=\"155\" stroke=\"#38bdf8\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <text x=\"85\" y=\"159\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"end\">-273,15 °C</text>\n  <text x=\"230\" y=\"152\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Độ không tuyệt đối (T = 0 K)</text>\n  <text x=\"375\" y=\"159\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"start\">0 K</text>\n</svg>"},{"q":"Ghép từng loại nhiệt kế (Cột A) với nguyên lí hoạt động vật lí tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Nhiệt kế thủy ngân hoặc rượu thông dụng ➔ Dựa vào sự phụ thuộc của điện trở bán dẫn (thermistor) vào nhiệt độ","Nhiệt kế thủy ngân hoặc rượu thông dụng ➔ Dựa vào hiện tượng giãn nở vì nhiệt của cột chất lỏng trong ống quản","Nhiệt kế điện tử kỹ thuật số dùng trong y tế ➔ Dựa vào sự phụ thuộc của điện trở bán dẫn (thermistor) vào nhiệt độ","Nhiệt kế hồng ngoại đo trán không tiếp xúc ➔ Dựa vào hiện tượng giãn nở vì nhiệt của cột chất lỏng trong ống quản"],"ans":0,"exp":"• <b>1 ghép B:</b> Nhiệt kế thủy ngân/rượu dựa vào sự dãn nở thể tích vì nhiệt của chất lỏng.<br>• <b>2 ghép A:</b> Nhiệt kế điện tử dùng cảm biến điện trở bán dẫn thay đổi điện trở theo nhiệt độ.<br>• <b>3 ghép C:</b> Nhiệt kế hồng ngoại thu nhận phổ bức xạ hồng ngoại của cơ thể phát ra.<br>• <b>4 ghép D:</b> Cặp nhiệt điện đo suất điện động Seebeck tỉ lệ với hiệu nhiệt độ 2 mối hàn.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Hai vật tiếp xúc nhau được gọi là ở trạng thái  [ ... ]  nhiệt nếu không có sự truyền năng lượng nhiệt ròng giữa chúng. Theo định luật số 0: Nếu hai vật A và B độc lập cùng ở trạng thái cân bằng nhiệt với vật thứ ba C, thì A và B cũng  [ ... ]  nhiệt với nhau. Khi đó chúng có cùng một  [ ... ] .\"</i>","opts":["cân bằng — biến thiên","không đổi","nội năng — đoạn nhiệt","biến thiên — cân bằng"],"ans":0,"exp":"<b>Nội dung Định luật số 0 Nhiệt động lực học:</b><br>Nếu vật A cân bằng nhiệt với C, và vật B cũng cân bằng nhiệt với C, thì A và B cân bằng nhiệt với nhau.<br>Đại lượng chung cho tất cả các vật ở trạng thái cân bằng nhiệt chính là <b>Nhiệt độ</b>.","svgGraph":null},{"q":"Thân nhiệt bình thường của người khỏe mạnh là 37,0°C. Giá trị nhiệt độ này tương ứng trong thang nhiệt độ Kelvin (T) và thang Fahrenheit (t<sub>F</sub>) lần lượt là:","opts":["T = 310,15 K và t<sub>F</sub> = 98,6°F","T = 300,15 K và t<sub>F</sub> = 98,6°F","T = 310,15 K và t<sub>F</sub> = 104,2°F","T = 236,15 K và t<sub>F</sub> = 66,6°F"],"ans":0,"exp":"• Đổi sang Kelvin:<div class='formula-box'><span class='math-sym'>T = t + 273,15 = 37 + 273,15 = 310,15 K</span></div>• Đổi sang Fahrenheit:<div class='formula-box'><span class='math-sym'>t<sub>F</sub> = 1,8 · t + 32 = 1,8 × 37 + 32 = 66,6 + 32 = 98,6°F</span></div>","svgGraph":null},{"q":"Tại giá trị nhiệt độ nào thì số chỉ trên thang nhiệt độ Celsius (t) và thang nhiệt độ Fahrenheit (t<sub>F</sub>) có cùng một giá trị bằng số?","opts":["-40°","0°","-20°","40°"],"ans":0,"exp":"• Ta có công thức liên hệ: <span class='math-sym'>t<sub>F</sub> = 1,8 · t + 32</span>.<br>• Đặt <span class='math-sym'>t<sub>F</sub> = t = x</span>, ta có phương trình:<div class='formula-box'><span class='math-sym'>x = 1,8 · x + 32 ⟺ 0,8 · x = -32 ⟺ x = -40</span></div>Như vậy, tại <b>-40°C = -40°F</b>, hai thang đo cho cùng một giá trị số chỉ.","svgGraph":null},{"q":"Một học sinh tự chế tạo một nhiệt kế chất lỏng chưa chia độ. Khi nhúng vào nước đá đang tan (0°C), chiều cao cột chất lỏng là h₀ = 40 mm. Khi nhúng vào hơi nước sôi (100°C), chiều cao cột chất lỏng là h₁₀₀ = 240 mm (xem đồ thị bên dưới). Khi dùng nhiệt kế này đo nhiệt độ phòng thì thấy chiều cao cột chất lỏng là h = 88 mm. Nhiệt độ phòng đo được là:","opts":["24°C","22°C","20°C","28°C"],"ans":0,"exp":"• Giả thiết chiều cao cột chất lỏng phụ thuộc bậc nhất (tuyến tính) vào nhiệt độ:<br><div class='formula-box'><span class='math-sym'>h(t) = h₀ + <div class='fraction'><span class='numerator'>h₁₀₀ - h₀</span><span class='denominator'>100</span></div> · t</span></div>• Độ tăng chiều cao cho mỗi 1°C:<div class='formula-box'><span class='math-sym'>k = <div class='fraction'><span class='numerator'>240 - 40</span><span class='denominator'>100</span></div> = <div class='fraction'><span class='numerator'>200</span><span class='denominator'>100</span></div> = 2 mm/°C</span></div>• Với <span class='math-sym'>h = 88 mm</span>:<div class='formula-box'><span class='math-sym'>t = <div class='fraction'><span class='numerator'>h - h₀</span><span class='denominator'>k</span></div> = <div class='fraction'><span class='numerator'>88 - 40</span><span class='denominator'>2</span></div> = <div class='fraction'><span class='numerator'>48</span><span class='denominator'>2</span></div> = 24°C</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"180\" x2=\"380\" y2=\"180\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"60\" x2=\"380\" y2=\"60\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"330\" y1=\"210\" x2=\"330\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (°C)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">h (mm)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"18\" y=\"185\" fill=\"#cbd5e1\" font-size=\"13\">40</text>\n            <text x=\"12\" y=\"65\" fill=\"#cbd5e1\" font-size=\"13\">240</text>\n            <text x=\"318\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">100</text>\n\n            <!-- Đường tuyến tính h theo t -->\n            <line x1=\"50\" y1=\"180\" x2=\"330\" y2=\"60\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"50\" cy=\"180\" r=\"5\" fill=\"#f43f5e\" />\n            <circle cx=\"330\" cy=\"60\" r=\"5\" fill=\"#f43f5e\" />\n\n            <!-- Điểm đo hx = 88 mm -->\n            <line x1=\"50\" y1=\"151\" x2=\"117\" y2=\"151\" stroke=\"#f59e0b\" stroke-dasharray=\"3\"/>\n            <line x1=\"117\" y1=\"151\" x2=\"117\" y2=\"210\" stroke=\"#f59e0b\" stroke-dasharray=\"3\"/>\n            <circle cx=\"117\" cy=\"151\" r=\"5\" fill=\"#f59e0b\" />\n            \n            <text x=\"22\" y=\"155\" fill=\"#f59e0b\" font-size=\"12\" font-weight=\"700\">88</text>\n            <text x=\"110\" y=\"228\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"800\">t<tspan baseline-shift=\"sub\" font-size=\"70%\">x</tspan> = ?</text>\n          </svg>"},{"q":"Trong quá trình chuẩn hóa (hiệu chuẩn) điểm mốc cho thang nhiệt độ Celsius trong phòng thí nghiệm, hãy xét tính Đúng/Sai của các quy tắc thực nghiệm: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi xác định điểm 100°C, ta cắm trực tiếp bầu nhiệt kế chạm vào đáy kim loại của nồi đun nước sôi.","Điểm 0°C được chuẩn hóa bằng cách cắm bầu nhiệt kế ngập sâu vào phễu chứa nước đá tinh khiết bào nhỏ đang tan chảy.","Phễu chứa đá bào cần có lỗ thoát nước phía dưới để nước tan chảy thoát ra ngoài liên tục, đảm bảo luôn đo đúng trạng thái hỗn hợp đá - nước cân bằng ở 0°C.","Nếu áp suất khí quyển phòng thí nghiệm giảm xuống dưới 1 atm (ví dụ ở vùng núi cao), nhiệt độ sôi của nước sẽ thấp hơn 100°C làm điểm mốc bị dịch chuyển."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Chuẩn hóa mốc 0°C bằng nước đá tinh khiết đang tan.<br>• <b>Ý b [Đúng]:</b> Nước đá tan tích tụ ở đáy có thể hấp thụ nhiệt ngoài phòng nóng lên, phễu thoát nước giúp duy trì đá bào tinh khiết tiếp xúc bầu nhiệt kế.<br>• <b>Ý c [Sai]:</b> Bầu nhiệt kế phải được treo trong <b>luồng hơi nước sôi</b> bên trên mặt thoáng, không được chạm đáy kim loại (nơi đáy nồi chịu lửa nóng hơn 100°C).<br>• <b>Ý d [Đúng]:</b> Điểm sôi phụ thuộc áp suất ngoài. Khi áp suất giảm, nhiệt độ sôi giảm.","svgGraph":null},{"q":"Một cặp nhiệt điện đồng - constantan có hệ số nhiệt điện động α_T = 40 μV/K. Nối một đầu mối hàn vào nước đá đang tan ở 0°C (273,15 K) và nhúng đầu mối hàn còn lại vào lò nung nhiệt độ cao thì đo được suất điện động nhiệt điện là E = 24 mV. Nhiệt độ của lò nung là:","opts":["600°C","573°C","873°C","480°C"],"ans":0,"exp":"• Công thức suất điện động nhiệt điện:<div class='formula-box'><span class='math-sym'>E = α_T · (T - T₀) = α_T · (t - t₀)</span></div>• Đổi đơn vị: <span class='math-sym'>E = 24 mV = 24.000 μV</span>, <span class='math-sym'>α_T = 40 μV/°C</span>, <span class='math-sym'>t₀ = 0°C</span>.<br>• Nhiệt độ của lò nung:<div class='formula-box'><span class='math-sym'>t - 0 = <div class='fraction'><span class='numerator'>E</span><span class='denominator'>α_T</span></div> = <div class='fraction'><span class='numerator'>24000</span><span class='denominator'>40</span></div> = 600°C</span></div>","svgGraph":null}],"4":[{"q":"Theo định nghĩa chuẩn trong chương trình Vật Lí 12, nhiệt dung riêng của một chất là:","opts":["Nhiệt lượng cần cung cấp để 1 kg chất đó chuyển hoàn toàn từ thể lỏng sang thể khí.","Nhiệt lượng tỏa ra khi làm đông đặc hoàn toàn một khối lượng chất lỏng xác định.","Nhiệt lượng cần thiết để làm cho 1 kg chất đó tăng nhiệt độ thêm 1 K (hoặc 1°C).","Tổng động năng nhiệt của tất cả các phân tử cấu tạo nên một vật thể xác định."],"ans":2,"exp":"Nhiệt dung riêng được xác định bằng công thức:<div class='formula-box'><span class='math-sym'>c</span> = <div class='fraction'><span class='numerator math-sym'>Q</span><span class='denominator math-sym'>m · ΔT</span></div></div>Đại lượng này biểu thị nhiệt lượng cần truyền cho <b>1 kg</b> chất để nhiệt độ tăng thêm <b>1 K (hoặc 1°C)</b>.<br>Đơn vị chuẩn trong hệ SI là: <b style='color:#38bdf8;'>J/(kg·K)</b>.","svgGraph":null},{"q":"Trong các hệ thống tản nhiệt làm mát động cơ đốt trong (xe máy tay ga, ô tô), dung dịch có thành phần chủ yếu là nước được sử dụng làm chất tải nhiệt chính. Nguyên nhân vật lí cơ bản nhất là do:","opts":["Nước có tính dẫn điện cao giúp tiêu tán nhanh điện tích tĩnh phát sinh do cọ xát trong xi-lanh.","Nước có nhiệt dung riêng rất lớn, có khả năng hấp thụ nhiệt lượng cực lớn từ buồng đốt mà nhiệt độ tăng không quá nhiều.","Nước có khối lượng riêng nhỏ nhất trong số các chất lỏng bôi trơn kỹ thuật.","Nước bay hơi rất nhanh ở nhiệt độ phòng, tạo hiệu ứng giảm nhiệt độ cục bộ liên tục."],"ans":1,"exp":"Nhiệt dung riêng của nước <span class='math-sym'>c ≈ 4180 J/(kg·K)</span> cao hơn hẳn các chất lỏng khác. Nhờ đó, một khối lượng nước tuần hoàn nhất định có thể hấp thụ và vận chuyển một nhiệt lượng cực lớn:<div class='formula-box'><span class='math-sym'>Q = m · c · Δt</span></div>Lượng nhiệt lớn được tải ra két tản nhiệt mà nhiệt độ của khối nước tăng không quá cao, giữ buồng đốt luôn ở ngưỡng an toàn.","svgGraph":null},{"q":"Một học sinh nghiên cứu các đặc tính của nhiệt dung riêng (ký hiệu là c). Hãy xác định tính Đúng/Sai của từng phát biểu sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hai vật làm bằng cùng một chất có khối lượng m₁ = 2m₂ thì vật thứ nhất có nhiệt dung riêng lớn gấp đôi vật thứ hai.","Nhiệt dung riêng là thuộc tính đặc trưng cho chất làm nên vật, không phụ thuộc vào khối lượng của vật thể.","Khi hai chất nhận cùng nhiệt lượng và có cùng khối lượng, chất có nhiệt dung riêng bé hơn sẽ tăng nhiệt độ nhanh hơn.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Nhiệt dung riêng <span class='math-sym'>c</span> là thuộc tính bản chất của chất cấu tạo.<br>• <b>Ý b [Sai]:</b> Cùng một chất thì <span class='math-sym'>c</span> như nhau. Chỉ có nhiệt dung <span class='math-sym'>C = m · c</span> mới tỉ lệ với khối lượng.<br>• <b>Ý c [Đúng]:</b> Từ <span class='math-sym'>ΔT = Q / (m · c)</span>, khi <span class='math-sym'>Q</span> và <span class='math-sym'>m</span> như nhau thì <span class='math-sym'>ΔT</span> tỉ lệ nghịch với <span class='math-sym'>c</span> (<span class='math-sym'>c</span> càng nhỏ thì nóng lên càng nhanh).<br>• <b>Ý d [Sai]:</b> Đơn vị SI chuẩn của nhiệt dung riêng là <b>J/(kg·K)</b>.","svgGraph":null},{"q":"Ghép từng hiện tượng chuyển động của không khí ở bờ biển (Cột A) với bản chất đối lưu và áp suất tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Gió biển (Ban ngày thổi từ biển vào đất liền) ➔ Cát có c nhỏ nên ban đêm tỏa nhiệt nguội nhanh, không khí co lại tạo áp cao đẩy gió ra biển","Gió biển (Ban ngày thổi từ biển vào đất liền) ➔ Cát có nhiệt dung riêng nhỏ hơn nước biển nhiều lần nên hấp thu bức xạ nóng lên nhanh hơn","Gió đất (Ban đêm thổi từ đất liền ra biển) ➔ Cát có c nhỏ nên ban đêm tỏa nhiệt nguội nhanh, không khí co lại tạo áp cao đẩy gió ra biển","Nhiệt độ cát ven bờ ban ngày tăng nhanh hơn nước biển ➔ Cát có nhiệt dung riêng nhỏ hơn nước biển nhiều lần nên hấp thu bức xạ nóng lên nhanh hơn"],"ans":0,"exp":"• <b>1 ghép C:</b> Ban ngày đất liền nóng nhanh → không khí bốc lên tạo áp thấp → gió mát thổi từ biển vào (Gió Biển).<br>• <b>2 ghép A:</b> Ban đêm cát tỏa nhiệt nhanh tạo áp cao trên bờ → gió thổi từ đất liền ra biển (Gió Đất).<br>• <b>3 ghép B:</b> <span class='math-sym'>c<sub>chì</sub>át ≈ 800 < c<sub>nước</sub> ≈ 4180 J/(kg·K)</span> nên ban ngày cát nóng lên nhanh hơn.<br>• <b>4 ghép D:</b> Ban đêm nước biển giữ nhiệt tốt hơn làm nhiệt độ nước biển cao hơn đất liền.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong một hệ cô lập nhiệt chỉ gồm các vật trao đổi nhiệt với nhau, nhiệt lượng do vật nóng tỏa ra có độ lớn  [ ... ]  nhiệt lượng do vật lạnh  [ ... ] . Nếu quy ước dấu đại số (tỏa nhiệt Q < 0, thu nhiệt Q > 0) thì tổng đại số các nhiệt lượng thỏa mãn biểu thức tổng Q =  [ ... ] .\"</i>","opts":["nhỏ hơn — luôn bằng","không đổi","0 — 100","luôn bằng — nhỏ hơn"],"ans":0,"exp":"Về độ lớn: <span class='math-sym' style='font-size:1.15rem;'>Q<sub>tỏa</sub> = Q<sub>thu</sub></span>.<br>Nếu tính theo dấu đại số quy ước (<span class='math-sym'>Q<sub>tỏa</sub> < 0</span> và <span class='math-sym'>Q<sub>thu</sub> > 0</span>) thì:<div class='formula-box'><span class='math-sym'>∑ Q = Q<sub>tỏa</sub> + Q<sub>thu</sub> = 0</span></div>","svgGraph":null},{"q":"Một ấm đun nước siêu tốc công suất định mức P = 1500 W, hiệu suất nhiệt H = 80%. Dùng ấm đun m = 1,5 kg nước từ nhiệt độ 20°C đến sôi ở 100°C. Biết nhiệt dung riêng của nước c = 4200 J/(kg·K). Thời gian đun cần thiết là:","opts":["336 giây (~ 5,6 phút)","420 giây (~ 7,0 phút)","504 giây (~ 8,4 phút)","280 giây (~ 4,7 phút)"],"ans":1,"exp":"• Nhiệt lượng có ích để làm sôi nước:<div class='formula-box'><span class='math-sym'>Q<sub>ích</sub> = m · c · (t₂ - t₁) = 1,5 × 4200 × (100 - 20) = 504.000 J</span></div>• Điện năng tiêu thụ toàn phần:<div class='formula-box'><span class='math-sym'>A = Q<sub>ích</sub> / H = 504.<span class=\"fraction\"><span class=\"numerator\">000</span><span class=\"denominator\">0</span></span>,8 = 630.000 J</span></div>• Thời gian đun:<div class='formula-box'><span class='math-sym'>t = A / P = 630.<span class=\"fraction\"><span class=\"numerator\">000</span><span class=\"denominator\">1500</span></span> = 420 giây (7 phút)</span></div>","svgGraph":null},{"q":"Thả một thỏi nhôm khối lượng 0,4 kg ở nhiệt độ 100°C vào bình nhiệt lượng kế chứa 0,8 kg nước ở 20°C. Bỏ qua hao phí nhiệt ra bình và môi trường. Cho c<sub>nhôm</sub> = 880 J/(kg·K), c<sub>nước</sub> = 4200 J/(kg·K). Nhiệt độ cân bằng t của hệ xấp xỉ bằng:","opts":["27,6°C","32,4°C","40,0°C","58,2°C"],"ans":0,"exp":"Phương trình cân bằng nhiệt:<div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub> = Q<sub>thu</sub> ⇔ m<sub>Al</sub> · c<sub>Al</sub> · (100 - t) = m<sub>n</sub>ước · c<sub>nước</sub> · (t - 20)</span></div>Thay số: <span class='math-sym'>0,4 × 880 × (100 - t) = 0,8 × 4200 × (t - 20)</span><br>⇔ <span class='math-sym'>352(100 - t) = 3360(t - 20)</span><br>⇔ <span class='math-sym'>35200 - 352t = 3360t - 67200 ⟹ 3712t = 102400 ⟹ t ≈ 27,59°C</span>.","svgGraph":null},{"q":"Trong thí nghiệm đo nhiệt dung riêng của nước sử dụng bình nhiệt lượng kế và dây nung điện trở (Vật Lí 12). Hãy xét tính Đúng/Sai của các thao tác thực hành sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu bỏ qua nhiệt lượng do vỏ bình nhiệt lượng kế và que khuấy hấp thụ, giá trị nhiệt dung riêng của nước thu được sẽ nhỏ hơn giá trị thực.","Cần khuấy nhẹ và đều nước liên tục để nhiệt độ trong toàn bộ khối chất lỏng phân bố đồng đều trước khi đọc số đo nhiệt độ.","Dùng nắp đậy xốp kín bình nhiệt lượng kế nhằm mục đích hạn chế sự thất thoát nhiệt do đối lưu và bay hơi ra ngoài không khí.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Khuấy nhẹ đều tay để nhiệt lượng phân bố đồng nhất khắp khối chất lỏng.<br>• <b>Ý b [Sai]:</b> Vì <span class='math-sym'>P · t = Q<sub>nước</sub>ước + Q<sub>bình</sub>ình</span>. Nếu bỏ qua <span class='math-sym'>Q<sub>bình</sub>ình</span> mà coi <span class='math-sym'>P · t = m · c<sub>t</sub>ính · ΔT</span> thì kết quả tính ra <span class='math-sym'>c<sub>t</sub>ính = (P · t) / (m · ΔT) > c<sub>th</sub>ật</span> (bị lớn hơn).<br>• <b>Ý c [Đúng]:</b> Nắp xốp cách nhiệt hạn chế tối đa đối lưu và bay hơi.<br>• <b>Ý d [Sai]:</b> Đun càng lâu, lượng nhiệt rò rỉ ra môi trường càng tăng, sai số càng lớn.","svgGraph":null},{"q":"Hình vẽ bên dưới là đồ thị biểu diễn sự phụ thuộc của nhiệt độ (T) theo thời gian đun (t) của hai chất lỏng (1) và (2) có cùng khối lượng m. Cả hai được cấp nhiệt từ hai nguồn hoàn toàn giống nhau có công suất không đổi P. Dựa vào đồ thị, kết luận nào sau đây đúng về tỉ số nhiệt dung riêng <span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span>?","opts":["<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span>","<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = 2","<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>","<span class=\"fraction\"><span class=\"numerator\">c₁</span><span class=\"denominator\">c₂</span></span> = 1"],"ans":0,"exp":"• Phương trình truyền nhiệt: <span class='math-sym'>Q = P · t = m · c · ΔT ⟹ ΔT = (P / (m · c)) · t</span><br>• Độ dốc (hệ số góc) của đồ thị:<div class='formula-box'><span class='math-sym'>k = tan(α) = <div class='fraction'><span class='numerator'>ΔT</span><span class='denominator'>t</span></div> = <div class='fraction'><span class='numerator'>P</span><span class='denominator'>m · c</span></div></span></div>Vì <span class='math-sym'>P</span> và <span class='math-sym'>m</span> như nhau nên hệ số góc <span class='math-sym'>k</span> tỉ lệ nghịch với nhiệt dung riêng <span class='math-sym'>c</span>.<br>• Từ đồ thị tại cùng thời điểm <span class='math-sym'>t₀</span>: đường (1) tăng <span class='math-sym'>2T₀</span> còn đường (2) tăng <span class='math-sym'>T₀</span> nên độ dốc <span class='math-sym'>k₁ = 2k₂</span>.<br>Do đó: <div class='formula-box'><span class='math-sym'><div class='fraction'><span class='numerator'>c₁</span><span class='denominator'>c₂</span></div> = <div class='fraction'><span class='numerator'>k₂</span><span class='denominator'>k₁</span></div> = <div class='fraction'><span class='numerator'>1</span><span class='denominator'>2</span></div></span></div>","svgGraph":"<svg viewBox=\"0 0 440 250\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <line x1=\"50\" y1=\"50\" x2=\"400\" y2=\"50\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"125\" x2=\"400\" y2=\"125\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"220\" y1=\"200\" x2=\"220\" y2=\"30\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <line x1=\"50\" y1=\"200\" x2=\"410\" y2=\"200\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"200\" x2=\"50\" y2=\"20\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"415\" y=\"205\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (s)</text>\n            <text x=\"32\" y=\"24\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">T (°C)</text>\n            <text x=\"38\" y=\"215\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            <text x=\"215\" y=\"222\" fill=\"#cbd5e1\" font-size=\"13\">t₀</text>\n            <text x=\"18\" y=\"130\" fill=\"#cbd5e1\" font-size=\"13\">T₀</text>\n            <text x=\"10\" y=\"55\" fill=\"#cbd5e1\" font-size=\"13\">2T₀</text>\n\n            <line x1=\"50\" y1=\"200\" x2=\"220\" y2=\"50\" stroke=\"#f43f5e\" stroke-width=\"3.5\" />\n            <circle cx=\"220\" cy=\"50\" r=\"5\" fill=\"#f43f5e\" />\n            <text x=\"228\" y=\"48\" fill=\"#f43f5e\" font-size=\"15\" font-weight=\"800\">Chất (1)</text>\n\n            <line x1=\"50\" y1=\"200\" x2=\"220\" y2=\"125\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"220\" cy=\"125\" r=\"5\" fill=\"#06b6d4\" />\n            <text x=\"228\" y=\"125\" fill=\"#06b6d4\" font-size=\"15\" font-weight=\"800\">Chất (2)</text>\n          </svg>"},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Các khu vực duyên hải ven biển thường có khí hậu ôn hòa hơn sâu trong đất liền vì đại dương đóng vai trò như một  [ ... ]  khổng lồ. Nhờ nước có nhiệt dung riêng  [ ... ] , đại dương hấp thụ bớt năng lượng vào mùa hè giúp nhiệt độ không tăng quá cao, đồng thời  [ ... ]  nhiệt lượng vào mùa đông làm giảm bớt độ giá rét.\"</i>","opts":["bộ ổn nhiệt — nguồn phát điện","không đổi","tỏa dần — hấp thụ thêm","nguồn phát điện — bộ ổn nhiệt"],"ans":0,"exp":"Nước biển có nhiệt dung riêng rất lớn (<span class='math-sym'>c ≈ 4180 J/(kg·K)</span>) giúp điều hòa khí hậu vùng bờ biển: mùa hè tích trữ nhiệt làm giảm độ nóng bức, mùa đông tỏa dần lượng nhiệt dự trữ làm ấm không khí xung quanh.","svgGraph":null}],"5":[{"q":"Theo chương trình Vật Lí 12, nhiệt nóng chảy riêng của một chất rắn kết tinh là:","opts":["Nhiệt lượng cần cung cấp cho 1 kg chất đó để chuyển hoàn toàn từ thể rắn sang thể lỏng ở nhiệt độ nóng chảy.","Nhiệt lượng cần thiết để làm tăng nhiệt độ của 1 kg chất rắn thêm 1 K.","Nhiệt lượng tỏa ra khi làm hóa hơi hoàn toàn một đơn vị khối lượng chất lỏng.","Nhiệt độ mà tại đó mạng tinh thể của chất rắn bắt đầu bị phá vỡ hoàn toàn."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Nhiệt nóng chảy riêng (ký hiệu <span class='math-sym'>λ</span>) của một chất là nhiệt lượng cần thiết để <b>1 kg</b> chất đó chuyển hoàn toàn từ thể rắn sang thể lỏng ở nhiệt độ nóng chảy.<br>• Công thức xác định:<div class='formula-box'><span class='math-sym'>λ = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>m</span></div></span></div>• Đơn vị chuẩn trong hệ SI là: <b style='color:#38bdf8;'>J/kg</b>.","svgGraph":null},{"q":"Biết nhiệt nóng chảy riêng của nước đá là λ ≈ 3,34 × 10⁵ J/kg. Ý nghĩa thực tiễn của con số này là:","opts":["Cần cung cấp nhiệt lượng 3,34 × 10⁵ J để làm nóng chảy hoàn toàn 1 kg nước đá ở 0°C thành nước ở 0°C.","Mỗi khi 1 kg nước đá hạ nhiệt độ xuống 1°C thì nó sẽ tỏa ra năng lượng 3,34 × 10⁵ J.","Nhiệt lượng tỏa ra khi đun sôi 1 kg nước đá từ 0°C đến 100°C là 3,34 × 10⁵ J.","Để nâng nhiệt độ của 1 kg nước đá từ 0°C lên 1°C cần cung cấp 3,34 × 10⁵ J."],"ans":0,"exp":"• Đại lượng <span class='math-sym'>λ = 3,34 × 10⁵ J/kg</span> biểu thị: Cần truyền một nhiệt lượng bằng <b>3,34 × 10⁵ Jun</b> cho 1 kg nước đá ở đúng 0°C để phá vỡ toàn bộ cấu trúc mạng tinh thể băng và chuyển hoàn toàn thành nước lỏng ở 0°C.","svgGraph":null},{"q":"Khi khảo sát hiện tượng nóng chảy và nhiệt nóng chảy riêng của các chất, hãy xác định tính Đúng/Sai của từng phát biểu sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Chất rắn vô định hình (nhựa, thủy tinh) cũng có giá trị nhiệt nóng chảy riêng xác định như kim loại.","Trong suốt quá trình nóng chảy ở áp suất chuẩn, nhiệt độ của khối chất rắn kết tinh không thay đổi dù liên tục nhận nhiệt.","Nhiệt lượng nhận vào trong quá trình nóng chảy chủ yếu làm tăng thế năng tương tác giữa các phân tử để phá hủy mạng tinh thể.","Khi 1 kg chất lỏng đông đặc hoàn toàn ở nhiệt độ đông đặc thì nó tỏa ra môi trường nhiệt lượng đúng bằng nhiệt nóng chảy riêng λ của nó."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Chất rắn kết tinh giữ nhiệt độ không đổi trong suốt thời gian nóng chảy.<br>• <b>Ý b [Đúng]:</b> Động năng phân tử không đổi (nhiệt độ không đổi), toàn bộ nhiệt lượng dùng để tăng thế năng phân tử phá vỡ mạng tinh thể.<br>• <b>Ý c [Sai]:</b> Chất rắn vô định hình không có nhiệt độ nóng chảy xác định nên không có khái niệm nhiệt nóng chảy riêng xác định.<br>• <b>Ý d [Đúng]:</b> Quá trình đông đặc là quá trình ngược lại của nóng chảy, tỏa nhiệt <span class='math-sym'>Q<sub>tỏa</sub> = λ · m</span>.","svgGraph":null},{"q":"Ghép từng hiện tượng thực tiễn (Cột A) với bản chất nhiệt động lực học tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Cho các viên nước đá vào cốc nước giải khát làm nước lạnh đi rất nhanh ➔ Nước đá thu một nhiệt lượng nóng chảy rất lớn (334 kJ/kg) từ nước giải khát","Cho các viên nước đá vào cốc nước giải khát làm nước lạnh đi rất nhanh ➔ Tuyết tan thu nhiệt nóng chảy cực lớn từ môi trường không khí xung quanh làm khí quyển lạnh buốt","Vào những ngày tuyết tan ở xứ lạnh, nhiệt độ không khí lại hạ thấp buốt giá hơn khi tuyết rơi ➔ Nước đá thu một nhiệt lượng nóng chảy rất lớn (334 kJ/kg) từ nước giải khát","Thợ kim hoàn nung chảy vàng rồi rót vào khuôn để chế tác trang sức ➔ Tuyết tan thu nhiệt nóng chảy cực lớn từ môi trường không khí xung quanh làm khí quyển lạnh buốt"],"ans":0,"exp":"• <b>1 ghép A:</b> Nước đá thu <span class='math-sym'>Q = λ · m</span> rất lớn làm mát nước giải khát cấp tốc.<br>• <b>2 ghép B:</b> Tuyết tan là quá trình thu nhiệt lượng khổng lồ từ không khí xung quanh.<br>• <b>3 ghép C:</b> Nung chảy vàng để chuyển thể lỏng rót khuôn.<br>• <b>4 ghép D:</b> Chì/thiếc hàn nóng chảy nhanh để liên kết mạch điện tử.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Nhiệt lượng cần cung cấp cho khối lượng m của chất rắn ở nhiệt độ nóng chảy để nó nóng chảy hoàn toàn được tính bằng công thức:  [ ... ]  = λ · m. Trong đó λ là nhiệt nóng chảy riêng phụ thuộc vào  [ ... ]  của chất. Quá trình ngược lại của sự nóng chảy là sự  [ ... ] , trong đó vật sẽ  [ ... ]  nhiệt lượng.\"</i>","opts":["Q — ΔU","không đổi","tỏa ra — thu vào","ΔU — Q"],"ans":0,"exp":"<b>Công thức tính nhiệt lượng nóng chảy:</b><br><div class='formula-box'><span class='math-sym'>Q = λ · m</span></div>Hệ số <span class='math-sym'>λ</span> đặc trưng cho bản chất của chất làm vật.<br>Quá trình đông đặc tỏa ra nhiệt lượng có độ lớn bằng <span class='math-sym'>λ · m</span>.","svgGraph":null},{"q":"Cần cung cấp một nhiệt lượng bao nhiêu để làm nóng chảy hoàn toàn 1,5 kg nước đá ở nhiệt độ 0°C? Cho biết nhiệt nóng chảy riêng của nước đá là λ = 3,34 × 10⁵ J/kg.","opts":["5,01 × 10⁵ J (501 kJ)","2,23 × 10⁵ J (223 kJ)","6,68 × 10⁵ J (668 kJ)","3,34 × 10⁵ J (334 kJ)"],"ans":0,"exp":"• Nhiệt lượng nóng chảy:<div class='formula-box'><span class='math-sym'>Q = λ · m = 3,34 × 10⁵ × 1,5 = 5,01 × 10⁵ J = 501 kJ</span></div>","svgGraph":null},{"q":"Cần cung cấp tổng nhiệt lượng bao nhiêu để làm chuyển 2,0 kg nước đá từ nhiệt độ -10°C thành nước lỏng hoàn toàn ở 0°C? Cho biết nhiệt dung riêng của nước đá c<sub>đá</sub> = 2100 J/(kg·K), nhiệt nóng chảy riêng của nước đá λ = 3,34 × 10⁵ J/kg.","opts":["710 kJ","668 kJ","42 kJ","752 kJ"],"ans":0,"exp":"• Giai đoạn 1: Nâng nhiệt độ nước đá từ -10°C lên 0°C:<div class='formula-box'><span class='math-sym'>Q₁ = m · c<sub>đá</sub> · Δt = 2,0 × 2100 × (0 - (-10)) = 42.000 J = 42 kJ</span></div>• Giai đoạn 2: Làm nóng chảy hoàn toàn nước đá ở 0°C:<div class='formula-box'><span class='math-sym'>Q₂ = m · λ = 2,0 × 3,34 × 10⁵ = 668.000 J = 668 kJ</span></div>• Tổng nhiệt lượng cần thiết:<div class='formula-box'><span class='math-sym'>Q = Q₁ + Q₂ = 42 + 668 = 710 kJ</span></div>","svgGraph":null},{"q":"Hình vẽ dưới đây là đồ thị biểu diễn sự thay đổi nhiệt độ theo thời gian khi nung nóng một mẫu chì khối lượng m = 0,5 kg bằng nguồn nhiệt có công suất không đổi P = 500 W. Giai đoạn chì nóng chảy diễn ra ở nhiệt độ 327°C và kéo dài trong khoảng thời gian Δt = 25 giây (từ giây thứ 15 đến giây thứ 40). Bỏ qua hao phí nhiệt ra môi trường. Nhiệt nóng chảy riêng của chì xác định từ đồ thị là:","opts":["2,5 × 10⁴ J/kg","5,0 × 10⁴ J/kg","1,25 × 10⁴ J/kg","2,5 × 10⁵ J/kg"],"ans":0,"exp":"• Nhiệt lượng nguồn cấp trong giai đoạn nóng chảy:<div class='formula-box'><span class='math-sym'>Q = P · Δt = 500 × 25 = 12.500 J</span></div>• Nhiệt nóng chảy riêng của chì:<div class='formula-box'><span class='math-sym'>λ = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>m</span></div> = <div class='fraction'><span class='numerator'>12500</span><span class='denominator'>0,5</span></div> = 25.000 J/kg = 2,5 × 10⁴ J/kg</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"180\" x2=\"380\" y2=\"180\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"110\" x2=\"380\" y2=\"110\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"140\" y1=\"210\" x2=\"140\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"280\" y1=\"210\" x2=\"280\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (s)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">T (°C)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"18\" y=\"185\" fill=\"#cbd5e1\" font-size=\"13\">27°</text>\n            <text x=\"12\" y=\"115\" fill=\"#cbd5e1\" font-size=\"13\">327°</text>\n            <text x=\"132\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">15</text>\n            <text x=\"272\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">40</text>\n\n            <!-- Đường đặc tuyến -->\n            <line x1=\"50\" y1=\"180\" x2=\"140\" y2=\"110\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"50\" cy=\"180\" r=\"4\" fill=\"#06b6d4\" />\n            \n            <line x1=\"140\" y1=\"110\" x2=\"280\" y2=\"110\" stroke=\"#f43f5e\" stroke-width=\"4\" />\n            <circle cx=\"140\" cy=\"110\" r=\"5\" fill=\"#f43f5e\" />\n            <circle cx=\"280\" cy=\"110\" r=\"5\" fill=\"#f43f5e\" />\n\n            <line x1=\"280\" y1=\"110\" x2=\"360\" y2=\"55\" stroke=\"#10b981\" stroke-width=\"3.5\" />\n            <circle cx=\"360\" cy=\"55\" r=\"4\" fill=\"#10b981\" />\n\n            <!-- Nhãn -->\n            <text x=\"175\" y=\"98\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"800\">Δt = 25s (Nóng chảy)</text>\n          </svg>"},{"q":"Trong thí nghiệm thực hành đo nhiệt nóng chảy riêng của nước đá bằng nhiệt lượng kế (Vật Lí 12), hãy xét tính Đúng/Sai của các thao tác thực hành sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Cần khuấy nước liên tục và mạnh tay để nước đá va đập vỡ vụn đẩy nhanh quá trình tan.","Trước khi thả các viên nước đá vào nhiệt lượng kế, cần dùng giấy thấm sạch lớp nước bám bên ngoài bề mặt từng viên đá.","Khối lượng nước đá tan được tính chính xác bằng hiệu số khối lượng của bình nhiệt lượng kế sau khi đá tan hết trừ đi khối lượng bình ban đầu.","Nhiệt lượng tỏa ra từ nước ấm và bình nhiệt lượng kế đóng vai trò cung cấp nhiệt nóng chảy cho khối nước đá."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Phải thấm khô đá để chỉ có đá ở 0°C đi vào bình, tránh sai số do nước lỏng bám ngoài.<br>• <b>Ý b [Đúng]:</b> Cân bình sau khi tan hết trừ khối lượng ban đầu suy ra chính xác <span class='math-sym'>m<sub>đá</sub></span>.<br>• <b>Ý c [Sai]:</b> Chỉ khuấy <b>nhẹ và đều tay</b>; khuấy mạnh tay làm sinh công cơ học biến thành nhiệt gây sai số lớn.<br>• <b>Ý d [Đúng]:</b> Phương trình cân bằng nhiệt: <span class='math-sym'>Q<sub>tỏa</sub> (nước ấm + bình) = Q<sub>thu</sub> (nóng chảy + nước đá tan tăng nhiệt độ)</span>.","svgGraph":null},{"q":"Thả một cục nước đá khối lượng m₁ = 0,2 kg ở 0°C vào một bình nhiệt lượng kế chứa m₂ = 0,5 kg nước ở 30°C. Bỏ qua nhiệt dung của bình và mất mát nhiệt ra ngoài. Cho c<sub>nước</sub> = 4200 J/(kg·K), λ = 3,34 × 10⁵ J/kg. Hiện tượng và trạng thái cuối cùng của hệ là:","opts":["Nước đá tan hoàn toàn và nhiệt độ cân bằng cuối cùng xấp xỉ bằng 8,7°C.","Nước đá không tan hết và nhiệt độ cân bằng dừng lại ở 0°C.","Nước đá tan hoàn toàn và nhiệt độ cân bằng đạt 15,0°C.","Nước đóng băng thêm và nhiệt độ hạ xuống dưới 0°C."],"ans":0,"exp":"• Nhiệt lượng nước tỏa ra tối đa khi hạ từ 30°C về 0°C:<div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub><sub>max</sub> = m₂ · c · (30 - 0) = 0,5 × 4200 × 30 = 63.000 J</span></div>• Nhiệt lượng cần để làm tan hoàn toàn 0,2 kg đá ở 0°C:<div class='formula-box'><span class='math-sym'>Q<sub>tan</sub> = m₁ · λ = 0,2 × 3,34 × 10⁵ = 66.800 J</span></div>• <i>Khoan đã!</i> Ta thấy <span class='math-sym'>Q<sub>tỏa</sub><sub>max</sub> (63.000 J) < Q<sub>tan</sub> (66.800 J)</span>!<br>Do đó nước hạ về 0°C mà nhiệt lượng tỏa ra vẫn chưa đủ để làm tan hết đá ⟹ <b>Đá không tan hết, hệ ở trạng thái cân bằng tại đúng 0°C</b>!<br>Khối lượng đá tan được: <span class='math-sym'>m<sub>tan</sub> = <span class=\"fraction\"><span class=\"numerator\">63000</span><span class=\"denominator\">334000</span></span> ≈ 0,1886 kg</span>. Còn dư <span class='math-sym'>~0,0114 kg</span> đá chưa tan.<br><i>Đáp án chính xác nhất là:</i> Đá không tan hết và nhiệt độ dừng lại ở 0°C.","svgGraph":null}],"6":[{"q":"Theo định nghĩa trong chương trình Vật Lí 12, nhiệt hoá hơi riêng của một chất lỏng là:","opts":["Nhiệt lượng cần thiết để làm cho 1 kg chất lỏng đó hoá hơi hoàn toàn ở nhiệt độ sôi.","Nhiệt lượng tỏa ra khi làm ngưng tụ hoàn toàn một thể tích hơi xác định.","Nhiệt lượng cần cung cấp để 1 kg chất lỏng tăng nhiệt độ thêm 1°C khi đang sôi.","Nhiệt độ mà tại đó các bọt khí bắt đầu nổi lên mãnh liệt trong lòng chất lỏng."],"ans":0,"exp":"• <b>Định nghĩa SGK:</b> Nhiệt hoá hơi riêng (ký hiệu <span class='math-sym'>L</span>) của một chất lỏng là nhiệt lượng cần cung cấp cho <b>1 kg</b> chất lỏng đó để nó hoá hơi hoàn toàn ở nhiệt độ sôi.<br>• Công thức tính:<div class='formula-box'><span class='math-sym'>L = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>m</span></div></span></div>• Đơn vị chuẩn trong hệ SI là: <b style='color:#38bdf8;'>J/kg</b>.","svgGraph":null},{"q":"Sự khác nhau căn bản nhất giữa quá trình 'Bay hơi' và quá trình 'Sôi' của chất lỏng là:","opts":["Bay hơi diễn ra ở mọi nhiệt độ và chỉ xảy ra trên bề mặt chất lỏng; còn sự sôi chỉ xảy ra ở nhiệt độ sôi xác định và diễn ra đồng thời ở cả trong lòng lẫn trên mặt thoáng.","Bay hơi cần cung cấp nhiệt lượng còn sự sôi thì tự phát tỏa nhiệt ra môi trường.","Bay hơi làm khối lượng chất lỏng tăng lên còn sự sôi làm thể tích khối chất lỏng co lại.","Bay hơi chỉ xảy ra đối với nước ngọt, còn sự sôi chỉ xảy ra với dung dịch nước muối."],"ans":0,"exp":"• <b>So sánh chuẩn SGK:</b><br>- <i>Sự bay hơi:</i> Xảy ra ở <b>mọi nhiệt độ</b>, chỉ diễn ra trên <b>bề mặt thoáng</b> của chất lỏng.<br>- <i>Sự sôi:</i> Là trường hợp hoá hơi đặc biệt, chỉ xảy ra tại <b>nhiệt độ sôi xác định</b> (ở một áp suất ngoài nhất định), diễn ra <b>ở cả trong lòng</b> (hình thành bọt khí) và <b>trên bề mặt thoáng</b>.","svgGraph":null},{"q":"Khi khảo sát các đặc tính của nhiệt hoá hơi riêng và quá trình sôi của chất lỏng, hãy xác định tính Đúng/Sai của từng phát biểu sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trên đỉnh núi Phan Xi Păng (áp suất khí quyển thấp hơn 1 atm), nước tinh khiết sôi ở nhiệt độ cao hơn 100°C.","Trong suốt thời gian chất lỏng sôi ở áp suất không đổi, nhiệt độ của chất lỏng giữ nguyên không đổi.","Nhiệt độ sôi của chất lỏng tăng lên khi áp suất trên mặt thoáng chất lỏng tăng lên.","Nước có nhiệt hoá hơi riêng rất lớn (xấp xỉ 2,26 × 10⁶ J/kg), lớn hơn nhiều so với nhiệt nóng chảy riêng của nước đá."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Trong suốt thời gian sôi, nhiệt độ chất lỏng giữ cố định.<br>• <b>Ý b [Đúng]:</b> Áp suất mặt thoáng tăng thì nhiệt độ sôi tăng (nguyên lí nồi áp suất).<br>• <b>Ý c [Sai]:</b> Lên núi cao áp suất giảm ⟹ nhiệt độ sôi của nước <b>giảm xuống dưới 100°C</b> (khoảng 88°C - 90°C).<br>• <b>Ý d [Đúng]:</b> <span class='math-sym'>L<sub>n</sub>ước ≈ 2,26 × 10⁶ J/kg</span> gấp gần 7 lần nhiệt nóng chảy riêng <span class='math-sym'>λ_đá ≈ 3,34 × 10⁵ J/kg</span>.","svgGraph":null},{"q":"Ghép từng hiện tượng thực tế (Cột A) với nguyên lí nhiệt động học tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Bị bỏng hơi nước 100°C thường gây tổn thương sâu và nguy hiểm hơn bỏng nước sôi 100°C ➔ Hơi nước ngưng tụ trên da tỏa thêm một nhiệt lượng hoá hơi khổng lồ (2,26 × 10⁶ J/kg)","Bị bỏng hơi nước 100°C thường gây tổn thương sâu và nguy hiểm hơn bỏng nước sôi 100°C ➔ Mồ hôi bay hơi thu nhiệt lượng lớn từ bề mặt da làm mát cơ thể","Cơ thể người toát mồ hôi vào mùa hè giúp duy trì thân nhiệt ổn định 37°C ➔ Hơi nước ngưng tụ trên da tỏa thêm một nhiệt lượng hoá hơi khổng lồ (2,26 × 10⁶ J/kg)","Tưới nước lên sân gạch hoặc mái tôn vào trưa hè làm mát không khí xung quanh ➔ Mồ hôi bay hơi thu nhiệt lượng lớn từ bề mặt da làm mát cơ thể"],"ans":0,"exp":"• <b>1 ghép A:</b> Hơi nước 100°C ngưng tụ tỏa nhiệt hoá hơi cực lớn <span class='math-sym'>L · m</span> làm bỏng sâu.<br>• <b>2 ghép B:</b> Mồ hôi bay hơi thu nhiệt lượng lớn từ da giúp hạ nhiệt cơ thể.<br>• <b>3 ghép C:</b> Nước tưới bay hơi thu nhiệt của sân gạch và không khí.<br>• <b>4 ghép D:</b> Nồi áp suất tăng áp suất làm nước sôi ở 120°C giúp thức ăn chín nhanh.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Nhiệt lượng cần cung cấp cho khối lượng m của chất lỏng ở nhiệt độ sôi để nó hoá hơi hoàn toàn được xác định bởi công thức:  [ ... ]  = L · m. Trong đó L là nhiệt hoá hơi riêng phụ thuộc vào  [ ... ]  của chất lỏng. Ở cấp độ vi mô, năng lượng này dùng để thắng  [ ... ]  giữa các phân tử và thực hiện  [ ... ]  dãn nở chống áp suất ngoài.\"</i>","opts":["Q — Δp","không đổi","công — động năng","Δp — Q"],"ans":0,"exp":"<b>Nội dung vật lí về nhiệt hoá hơi:</b><br><div class='formula-box'><span class='math-sym'>Q = L · m</span></div>Nhiệt hoá hơi riêng <span class='math-sym'>L</span> phụ thuộc bản chất chất lỏng.<br>Năng lượng cung cấp dùng để: (1) Thắng lực hút liên kết phân tử và (2) Thực hiện công dãn nở thể tích chống lại áp suất ngoài.","svgGraph":null},{"q":"Cần cung cấp một nhiệt lượng bao nhiêu để làm hoá hơi hoàn toàn 0,8 kg nước đang sôi ở 100°C trong ấm? Cho biết nhiệt hoá hơi riêng của nước là L = 2,26 × 10⁶ J/kg.","opts":["1,808 × 10⁶ J (1808 kJ)","2,825 × 10⁶ J (2825 kJ)","1,130 × 10⁶ J (1130 kJ)","2,260 × 10⁶ J (2260 kJ)"],"ans":0,"exp":"• Nhiệt lượng hoá hơi:<div class='formula-box'><span class='math-sym'>Q = L · m = 2,26 × 10⁶ × 0,8 = 1,808 × 10⁶ J = 1808 kJ</span></div>","svgGraph":null},{"q":"Một ấm đun nước bằng điện có công suất hữu ích P = 1130 W dùng để đun nước. Sau khi nước trong ấm đạt nhiệt độ sôi 100°C, người ta để ấm tiếp tục sôi trong thời gian t = 4 phút (240 giây). Khối lượng nước đã hoá hơi thoát ra khỏi ấm trong khoảng thời gian này là:","opts":["0,12 kg (120 g)","0,24 kg (240 g)","0,06 kg (60 g)","0,18 kg (180 g)"],"ans":0,"exp":"• Nhiệt lượng ấm cung cấp khi nước đang sôi:<div class='formula-box'><span class='math-sym'>Q = P · t = 1130 × 240 = 271.200 J</span></div>• Khối lượng nước đã hoá hơi:<div class='formula-box'><span class='math-sym'>m = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>L</span></div> = <div class='fraction'><span class='numerator'>271200</span><span class='denominator'>2,26 × 10⁶</span></div> = 0,12 kg = 120 g</span></div>","svgGraph":null},{"q":"Hình vẽ bên dưới là đồ thị ghi nhận khối lượng m (gam) của ấm và nước đang sôi theo thời gian đun t (phút) bằng cân điện tử kỹ thuật số. Biết công suất nhiệt cấp liên tục là P = 750 W không đổi. Trong khoảng thời gian từ t₁ = 2 phút đến t₂ = 6 phút, khối lượng giảm từ m₁ = 600 g xuống m₂ = 520 g. Nhiệt hoá hơi riêng của nước xác định từ số liệu đồ thị này là:","opts":["2,25 × 10⁶ J/kg","2,40 × 10⁶ J/kg","2,10 × 10⁶ J/kg","2,50 × 10⁶ J/kg"],"ans":0,"exp":"• Thời gian khảo sát: <span class='math-sym'>Δt = 6 - 2 = 4 phút = 240 giây</span>.<br>• Nhiệt lượng ấm cung cấp:<div class='formula-box'><span class='math-sym'>Q = P · Δt = 750 × 240 = 180.000 J</span></div>• Độ giảm khối lượng nước hoá hơi: <span class='math-sym'>Δm = 600 - 520 = 80 g = 0,08 kg</span>.<br>• Nhiệt hoá hơi riêng tính được:<div class='formula-box'><span class='math-sym'>L = <div class='fraction'><span class='numerator'>Q</span><span class='denominator'>Δm</span></div> = <div class='fraction'><span class='numerator'>180000</span><span class='denominator'>0,08</span></div> = 2.250.000 J/kg = 2,25 × 10⁶ J/kg</span></div>","svgGraph":"<svg viewBox=\"0 0 440 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n            <defs>\n              <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n                <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n              </marker>\n            </defs>\n            <!-- Lưới mờ -->\n            <line x1=\"50\" y1=\"80\" x2=\"380\" y2=\"80\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"50\" y1=\"140\" x2=\"380\" y2=\"140\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"130\" y1=\"210\" x2=\"130\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            <line x1=\"290\" y1=\"210\" x2=\"290\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n            \n            <!-- Trục tọa độ -->\n            <line x1=\"50\" y1=\"210\" x2=\"400\" y2=\"210\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/>\n            \n            <text x=\"405\" y=\"215\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">t (phút)</text>\n            <text x=\"25\" y=\"25\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"700\">m (gam)</text>\n            <text x=\"36\" y=\"225\" fill=\"#94a3b8\" font-size=\"14\">O</text>\n            \n            <!-- Giá trị trục -->\n            <text x=\"18\" y=\"85\" fill=\"#cbd5e1\" font-size=\"13\">600</text>\n            <text x=\"18\" y=\"145\" fill=\"#cbd5e1\" font-size=\"13\">520</text>\n            <text x=\"125\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">2</text>\n            <text x=\"285\" y=\"228\" fill=\"#cbd5e1\" font-size=\"13\">6</text>\n\n            <!-- Đường giảm khối lượng tuyến tính -->\n            <line x1=\"130\" y1=\"80\" x2=\"290\" y2=\"140\" stroke=\"#06b6d4\" stroke-width=\"3.5\" />\n            <circle cx=\"130\" cy=\"80\" r=\"5\" fill=\"#f43f5e\" />\n            <circle cx=\"290\" cy=\"140\" r=\"5\" fill=\"#f43f5e\" />\n\n            <!-- Nhãn Δm -->\n            <text x=\"175\" y=\"100\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"800\">Δm = 80g</text>\n            <text x=\"170\" y=\"195\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">Δt = 4 phút</text>\n          </svg>"},{"q":"Trong thí nghiệm đo nhiệt hoá hơi riêng của nước bằng ấm điện đun sôi đặt trên đĩa cân điện tử (Vật Lí 12), hãy xét tính Đúng/Sai của các thao tác thực hành sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu đậy kín nắp ấm có lỗ thông hơi hẹp khiến hơi nước ngưng tụ trên nắp chảy ngược trở lại ấm, giá trị L tính được sẽ nhỏ hơn giá trị thực tế.","Chỉ bắt đầu bấm giờ đo sự thay đổi khối lượng sau khi nước trong ấm đã sôi đều và ổn định ở 100°C.","Cần mở nắp ấm đun để hơi nước tự do bay thoát ra ngoài không khí phòng.","Điện năng tiêu thụ được xác định thông qua số đo của oát kế (hoặc ampe kế và vôn kế) và đồng hồ bấm giây."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Phải chờ nước sôi ổn định 100°C để toàn bộ nhiệt cấp chỉ dùng cho việc hoá hơi.<br>• <b>Ý b [Đúng]:</b> Mở nắp hoặc dùng ống dẫn hơi thoát ra ngoài không để ngưng tụ rơi lại cân.<br>• <b>Ý c [Sai]:</b> Hơi nước ngưng tụ rơi lại ấm làm độ giảm khối lượng <span class='math-sym'>Δm</span> đo được nhỏ hơn thực tế ⟹ <span class='math-sym'>L = Q / Δm</span> sẽ bị <b>lớn hơn giá trị thực</b>.<br>• <b>Ý d [Đúng]:</b> Đo công suất bằng oát kế và thời gian bằng đồng hồ bấm giây để tính <span class='math-sym'>Q = P · t</span>.","svgGraph":null},{"q":"Cần cung cấp tổng nhiệt lượng bao nhiêu để đun 1,0 kg nước từ 20°C đến sôi ở 100°C và làm hoá hơi 20% lượng nước đó? Cho c<sub>nước</sub> = 4200 J/(kg·K), L = 2,26 × 10⁶ J/kg. Bỏ qua hao phí nhiệt ra môi trường.","opts":["7,88 × 10⁵ J (788 kJ)","3,36 × 10⁵ J (336 kJ)","4,52 × 10⁵ J (452 kJ)","9,12 × 10⁵ J (912 kJ)"],"ans":0,"exp":"• Nhiệt lượng làm tăng nhiệt độ 1 kg nước từ 20°C lên 100°C:<div class='formula-box'><span class='math-sym'>Q₁ = m · c · (100 - 20) = 1,0 × 4200 × 80 = 336.000 J = 336 kJ</span></div>• Khối lượng nước hoá hơi: <span class='math-sym'>m<sub>h</sub>ơi = 20% × 1,0 = 0,2 kg</span>.<br>• Nhiệt lượng làm hoá hơi 0,2 kg nước sôi:<div class='formula-box'><span class='math-sym'>Q₂ = m<sub>h</sub>ơi · L = 0,2 × 2,26 × 10⁶ = 452.000 J = 452 kJ</span></div>• Tổng nhiệt lượng cần cung cấp:<div class='formula-box'><span class='math-sym'>Q = Q₁ + Q₂ = 336 + 452 = 788 kJ = 7,88 × 10⁵ J</span></div>","svgGraph":null}],"7":[{"q":"Trong một hệ nhiệt động lực học cô lập hoàn toàn chỉ gồm các vật trao đổi nhiệt và cơ năng với nhau, phát biểu nào sau đây thể hiện đúng định luật bảo toàn năng lượng?","opts":["Tổng đại số độ biến thiên nội năng của tất cả các vật trong hệ cô lập luôn bằng 0: ∑ ΔU<sub>i</sub> = 0.","Nhiệt lượng của các vật nóng luôn lớn hơn nhiệt lượng mà các vật lạnh thu vào.","Hệ có thể tự phát sinh công mà không tiêu hao bất kì dạng năng lượng nào.","Nội năng của mỗi vật riêng lẻ trong hệ luôn không đổi theo thời gian."],"ans":0,"exp":"• <b>Nguyên lí bảo toàn:</b> Trong một hệ cô lập (không trao đổi năng lượng với bên ngoài), năng lượng chỉ truyền từ vật này sang vật khác hoặc chuyển hóa giữa các dạng: <span class='math-sym'>∑ ΔU<sub>i</sub> = 0</span>.<br>• Khi chỉ có trao đổi nhiệt đơn thuần: <span class='math-sym'>∑ Q<sub>i</sub> = 0 ⟺ Q<sub>tỏa</sub> = Q<sub>thu</sub></span>.","svgGraph":null},{"q":"Hiệu suất nhiệt (H) của một thiết bị đun nước dùng điện được định nghĩa chuẩn xác bằng:","opts":["Tỉ số giữa nhiệt lượng có ích dùng để làm nóng và sôi nước với toàn bộ điện năng tiêu thụ: H = <span class=\"fraction\"><span class=\"numerator\">Q<sub>ích</sub></span><span class=\"denominator\">A</span></span>.","Tỉ số giữa nhiệt lượng hao phí tỏa ra ngoài môi trường với nhiệt lượng có ích.","Tỉ số giữa điện năng tiêu thụ với nhiệt dung riêng của nước.","Tỉ số giữa khối lượng nước trong ấm với thời gian đun nước sôi."],"ans":0,"exp":"• <b>Định nghĩa hiệu suất:</b><div class='formula-box'><span class='math-sym'>H = <div class='fraction'><span class='numerator'>Q<sub>ích</sub></span><span class='denominator'>A<sub>to</sub>àn phần</span></div> = <div class='fraction'><span class='numerator'>m · c · Δt</span><span class='denominator'>P · t</span></div></span></div>Luôn có <span class='math-sym'>H < 1</span> (hay <span class='math-sym'>H < 100%</span>) do luôn có mất mát nhiệt ra vỏ ấm và không khí.","svgGraph":null},{"q":"Thả một thỏi đồng khối lượng m₁ = 0,5 kg ở nhiệt độ 100°C vào nhiệt lượng kế chứa m₂ = 0,8 kg nước ở 20°C. Bỏ qua trao đổi nhiệt với bình và không khí. Cho c<sub>đồng</sub> = 380 J/(kg·K), c<sub>nước</sub> = 4200 J/(kg·K). Hãy xét tính Đúng/Sai của các nhận định: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nhiệt độ cân bằng của hệ lớn hơn 50°C.","Nhiệt lượng do thỏi đồng tỏa ra bằng đúng nhiệt lượng mà khối nước thu vào.","Nội năng của thỏi đồng giảm đi một lượng đúng bằng độ tăng nội năng của khối nước.","Nhiệt độ cân bằng của hệ đạt xấp xỉ 24,3°C."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Hệ cô lập nên <span class='math-sym'>Q<sub>tỏa</sub> = Q<sub>thu</sub></span>.<br>• <b>Ý b [Sai] & Ý d [Đúng]:</b> Phương trình cân bằng nhiệt:<div class='formula-box'><span class='math-sym'>0,5 × 380 × (100 - t) = 0,8 × 4200 × (t - 20)</span></div>⇔ <span class='math-sym'>190(100 - t) = 3360(t - 20) ⟹ 3550t = 86100 ⟹ t ≈ 24,25°C</span> (< 50°C).<br>• <b>Ý c [Đúng]:</b> Vì <span class='math-sym'>ΔU<sub>đồng</sub> = Q<sub>tỏa</sub> < 0</span> và <span class='math-sym'>ΔU<sub>n</sub>ước = Q<sub>thu</sub> > 0</span>, độ biến thiên nội năng tổng cộng <span class='math-sym'>ΔU = 0</span>.","svgGraph":null},{"q":"Một khối nước đá khối lượng m ở -10°C được cung cấp nhiệt liên tục đến khi chuyển hoàn toàn thành hơi nước ở 100°C. Ghép từng giai đoạn (Cột A) với công thức tính nhiệt lượng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Giai đoạn 1: Nâng nhiệt độ nước đá từ -10°C lên 0°C ➔ Q = m · c<sub>đá</sub> · (0 - (-10))","Giai đoạn 1: Nâng nhiệt độ nước đá từ -10°C lên 0°C ➔ Q = m · λ","Giai đoạn 2: Nước đá nóng chảy hoàn toàn ở 0°C ➔ Q = m · c<sub>đá</sub> · (0 - (-10))","Giai đoạn 3: Nâng nhiệt độ nước từ 0°C lên 100°C ➔ Q = m · λ"],"ans":0,"exp":"• <b>1 ghép A:</b> Tăng nhiệt độ chất rắn: <span class='math-sym'>Q₁ = m · c<sub>đá</sub> · Δt</span>.<br>• <b>2 ghép B:</b> Chuyển thể rắn ➔ lỏng ở 0°C: <span class='math-sym'>Q₂ = m · λ</span>.<br>• <b>3 ghép C:</b> Tăng nhiệt độ chất lỏng: <span class='math-sym'>Q₃ = m · c<sub>nước</sub> · Δt</span>.<br>• <b>4 ghép D:</b> Chuyển thể lỏng ➔ hơi ở 100°C: <span class='math-sym'>Q₄ = m · L</span>.","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi có nhiều vật trao đổi nhiệt trong một hệ cô lập, tổng nhiệt lượng do các vật  [ ... ]  ra luôn bằng tổng nhiệt lượng do các vật  [ ... ]  vào. Nếu tính cả nhiệt lượng hao phí truyền ra môi trường ngoài thì: Q<sub>to</sub>àn phần = Q<sub>ích</sub> +  [ ... ] . Hiệu suất của quá trình luôn  [ ... ]  100%.\"</i>","opts":["tỏa — thu","không đổi","lớn hơn — A<sub>ích</sub>","thu — tỏa"],"ans":0,"exp":"<b>Phương trình cân bằng nhiệt và hao phí:</b><br><div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub> = Q<sub>thu</sub></span></div>Khi có hao phí: <span class='math-sym'>Q<sub>cung</sub> cấp = Q<sub>ích</sub> + Q<sub>hao</sub> phí</span>, do đó <span class='math-sym'>H = Q<sub>ích</sub> / Q<sub>cung</sub> cấp < 100%</span>.","svgGraph":null},{"q":"Dùng một ấm điện có hiệu suất nhiệt H = 80% để đun m = 2,0 kg nước từ 25°C đến khi sôi ở 100°C. Biết c<sub>nước</sub> = 4200 J/(kg·K) và giá tiền điện là 2500 đồng/kWh. Số tiền điện phải trả cho một lần đun này xấp xỉ là:","opts":["547 đồng","438 đồng","685 đồng","820 đồng"],"ans":0,"exp":"• Nhiệt lượng có ích làm sôi nước:<div class='formula-box'><span class='math-sym'>Q<sub>ích</sub> = m · c · (100 - 25) = 2 × 4200 × 75 = 630.000 J</span></div>• Điện năng tiêu thụ thực tế của ấm:<div class='formula-box'><span class='math-sym'>A = <div class='fraction'><span class='numerator'>Q<sub>ích</sub></span><span class='denominator'>H</span></div> = <div class='fraction'><span class='numerator'>630000</span><span class='denominator'>0,8</span></div> = 787.500 J</span></div>• Đổi sang số điện (kWh):<div class='formula-box'><span class='math-sym'>A = <div class='fraction'><span class='numerator'>787500</span><span class='denominator'>3,6 × 10⁶</span></div> ≈ 0,21875 kWh</span></div>• Tiền điện: <span class='math-sym'>0,21875 × 2500 ≈ 546,875 đồng ≈ 547 đồng</span>.","svgGraph":null},{"q":"Thả m₁ = 0,1 kg nước đá ở 0°C vào m₂ = 0,4 kg nước ở 40°C đựng trong bình cách nhiệt. Bỏ qua trao đổi nhiệt với bình. Cho c<sub>nước</sub> = 4200 J/(kg·K), λ = 3,34 × 10⁵ J/kg. Nhiệt độ cân bằng t của hệ sau khi đá tan hết là:","opts":["16,1°C","20,0°C","12,5°C","24,2°C"],"ans":0,"exp":"• Nhiệt lượng cần để làm nóng chảy hoàn toàn 0,1 kg đá:<div class='formula-box'><span class='math-sym'>Q<sub>tan</sub> = m₁ · λ = 0,1 × 3,34 × 10⁵ = 33.400 J</span></div>• Nhiệt lượng nước tỏa ra khi hạ từ 40°C về 0°C:<div class='formula-box'><span class='math-sym'>Q<sub>tỏa</sub><sub>max</sub> = 0,4 × 4200 × 40 = 67.200 J > 33.400 J</span></div>⟹ Đá tan hoàn toàn và nhiệt độ cân bằng <span class='math-sym'>t > 0°C</span>.<br>• Phương trình cân bằng nhiệt:<div class='formula-box'><span class='math-sym'>m₁ · λ + m₁ · c · (t - 0) = m₂ · c · (40 - t)</span></div>⇔ <span class='math-sym'>33400 + 0,1 × 4200 · t = 0,4 × 4200 · (40 - t)</span><br>⇔ <span class='math-sym'>33400 + 420t = 67200 - 1680t ⟹ 2100t = 33800 ⟹ t ≈ 16,095°C ≈ 16,1°C</span>.","svgGraph":null},{"q":"Hình vẽ dưới đây biểu diễn đường đun nóng liên tục một khối chất tinh khiết khối lượng m = 1,0 kg bằng nguồn nhiệt công suất không đổi P = 1000 W. Giai đoạn nóng chảy diễn ra trong khoảng thời gian Δt₁ = 200 s; giai đoạn hoá hơi sôi diễn ra trong khoảng thời gian Δt₂ = 1200 s. Tỉ số giữa nhiệt hoá hơi riêng và nhiệt nóng chảy riêng (<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span>) của chất này là:","opts":["<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = 6","<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = 3","<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">6</span></span>","<span class=\"fraction\"><span class=\"numerator\">L</span><span class=\"denominator\">λ</span></span> = 12"],"ans":0,"exp":"• Nhiệt nóng chảy riêng: <span class='math-sym'>λ = (P · Δt₁) / m</span>.<br>• Nhiệt hoá hơi riêng: <span class='math-sym'>L = (P · Δt₂) / m</span>.<br>• Lập tỉ số:<div class='formula-box'><span class='math-sym'><div class='fraction'><span class='numerator'>L</span><span class='denominator'>λ</span></div> = <div class='fraction'><span class='numerator'>Δt₂</span><span class='denominator'>Δt₁</span></div> = <div class='fraction'><span class='numerator'>1200</span><span class='denominator'>200</span></div> = 6</span></div>Nhiệt hoá hơi riêng của chất lớn gấp 6 lần nhiệt nóng chảy riêng.","svgGraph":"<svg viewBox=\"0 0 480 260\" width=\"100%\" height=\"auto\" style=\"display:block;\">\n  <defs>\n    <marker id=\"arrow7\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n    </marker>\n  </defs>\n  <!-- Luoi mo -->\n  <line x1=\"50\" y1=\"170\" x2=\"440\" y2=\"170\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"50\" y1=\"90\" x2=\"440\" y2=\"90\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"90\" y1=\"220\" x2=\"90\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"160\" y1=\"220\" x2=\"160\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"220\" y1=\"220\" x2=\"220\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  <line x1=\"410\" y1=\"220\" x2=\"410\" y2=\"40\" stroke=\"rgba(255,255,255,0.08)\" stroke-dasharray=\"4\"/>\n  \n  <!-- Truc toa do -->\n  <line x1=\"50\" y1=\"220\" x2=\"460\" y2=\"220\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arrow7)\"/>\n  <line x1=\"50\" y1=\"220\" x2=\"50\" y2=\"25\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arrow7)\"/>\n  \n  <text x=\"462\" y=\"224\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">t (s)</text>\n  <text x=\"22\" y=\"26\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"700\">T (°C)</text>\n  <text x=\"38\" y=\"235\" fill=\"#94a3b8\" font-size=\"13\">O</text>\n  \n  <!-- Moc gia tri -->\n  <text x=\"18\" y=\"174\" fill=\"#cbd5e1\" font-size=\"12\">T₁</text>\n  <text x=\"18\" y=\"94\" fill=\"#cbd5e1\" font-size=\"12\">T₂</text>\n  <text x=\"82\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">100</text>\n  <text x=\"150\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">300</text>\n  <text x=\"210\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">500</text>\n  <text x=\"398\" y=\"236\" fill=\"#cbd5e1\" font-size=\"11\">1700</text>\n\n  <!-- Duong dun nong lien tuc -->\n  <!-- Ran tang nhiet: 0 -> 100s -->\n  <line x1=\"50\" y1=\"210\" x2=\"90\" y2=\"170\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n  <!-- Nong chay: 100 -> 300s (Dt1 = 200s) -->\n  <line x1=\"90\" y1=\"170\" x2=\"160\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"4\" />\n  <circle cx=\"90\" cy=\"170\" r=\"4\" fill=\"#f43f5e\" />\n  <circle cx=\"160\" cy=\"170\" r=\"4\" fill=\"#f43f5e\" />\n  <!-- Long tang nhiet: 300 -> 500s -->\n  <line x1=\"160\" y1=\"170\" x2=\"220\" y2=\"90\" stroke=\"#06b6d4\" stroke-width=\"3\" />\n  <!-- Hoa hoi: 500 -> 1700s (Dt2 = 1200s) -->\n  <line x1=\"220\" y1=\"90\" x2=\"410\" y2=\"90\" stroke=\"#eab308\" stroke-width=\"4\" />\n  <circle cx=\"220\" cy=\"90\" r=\"4\" fill=\"#eab308\" />\n  <circle cx=\"410\" cy=\"90\" r=\"4\" fill=\"#eab308\" />\n  <!-- Hoi tang nhiet tiep -->\n  <line x1=\"410\" y1=\"90\" x2=\"445\" y2=\"50\" stroke=\"#10b981\" stroke-width=\"3\" />\n\n  <!-- Chu thich -->\n  <text x=\"96\" y=\"158\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">Δt₁ = 200 s (Nóng chảy)</text>\n  <text x=\"240\" y=\"78\" fill=\"#eab308\" font-size=\"11\" font-weight=\"700\">Δt₂ = 1200 s (Hoá hơi sôi)</text>\n</svg>"},{"q":"Khi tiến hành các phép đo thực nghiệm nhiệt học trong chương trình Vật Lí 12, hãy kiểm tra tính Đúng/Sai của các nhận định về sai số: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Chỉ cần đo một lần duy nhất là có thể kết luận chắc chắn giá trị chính xác tuyệt đối của đại lượng nhiệt học.","Bình nhiệt lượng kế có vỏ xốp cách nhiệt dày nhằm giảm thiểu tối đa sai số do trao đổi nhiệt với không khí bên ngoài.","Nếu trong công thức tính toán ta bỏ qua nhiệt lượng do que khuấy và nhiệt kế hấp thụ thì kết quả nhiệt dung riêng đo được sẽ lớn hơn giá trị thực tế.","Độ chia nhỏ nhất của nhiệt kế kỹ thuật số càng nhỏ thì sai số dụng cụ càng giảm."],"ans":0,"exp":"• <b>Ý a [Đúng]:</b> Vỏ xốp cách nhiệt hạn chế mất mát nhiệt qua đối lưu và dẫn nhiệt.<br>• <b>Ý b [Đúng]:</b> Vì <span class='math-sym'>P · t = Q<sub>nước</sub>ước + Q<sub>d</sub>ụng cụ</span>. Bỏ qua nhiệt lượng dụng cụ khiến phần nhiệt gán cho nước bị đội lên ⟹ <span class='math-sym'>c<sub>t</sub>ính > c<sub>th</sub>ực</span>.<br>• <b>Ý c [Sai]:</b> Cần đo lặp lại ít nhất 3 đến 5 lần và tính giá trị trung bình để loại trừ sai số ngẫu nhiên.<br>• <b>Ý d [Đúng]:</b> Sai số dụng cụ thường lấy bằng một nửa hoặc một độ chia nhỏ nhất.","svgGraph":null},{"q":"Một bếp gas công nghiệp sử dụng khí hoá lỏng LPG có năng suất tỏa nhiệt q = 46 × 10⁶ J/kg. Hiệu suất của bếp là H = 60%. Cần đốt cháy bao nhiêu gam gas LPG để đun sôi 5,0 kg nước từ 20°C và làm hoá hơi hoàn toàn 1,0 kg nước trong số đó? Cho c<sub>nước</sub> = 4200 J/(kg·K), L = 2,26 × 10⁶ J/kg.","opts":["143 gam","86 gam","238 gam","172 gam"],"ans":0,"exp":"• Nhiệt lượng làm tăng 5 kg nước từ 20°C lên 100°C:<div class='formula-box'><span class='math-sym'>Q₁ = 5 × 4200 × (100 - 20) = 1.680.000 J</span></div>• Nhiệt lượng làm hoá hơi 1 kg nước sôi:<div class='formula-box'><span class='math-sym'>Q₂ = 1 × 2,26 × 10⁶ = 2.260.000 J</span></div>• Tổng nhiệt lượng có ích: <span class='math-sym'>Q<sub>ích</sub> = 1.680.000 + 2.260.000 = 3.940.000 J</span>.<br>• Nhiệt lượng toàn phần khí gas cần tỏa ra:<div class='formula-box'><span class='math-sym'>Q<sub>tp</sub> = <div class='fraction'><span class='numerator'>Q<sub>ích</sub></span><span class='denominator'>H</span></div> = <div class='fraction'><span class='numerator'>3940000</span><span class='denominator'>0,6</span></div> ≈ 6.566.667 J</span></div>• Khối lượng gas cần đốt cháy:<div class='formula-box'><span class='math-sym'>m<sub>gas</sub> = <div class='fraction'><span class='numerator'>Q<sub>tp</sub></span><span class='denominator'>q</span></div> = <div class='fraction'><span class='numerator'>6566667</span><span class='denominator'>46 × 10⁶</span></div> ≈ 0,14275 kg ≈ 143 gam</span></div>","svgGraph":null}],"8":[{"q":"Theo nội dung của thuyết động học phân tử chất khí, nhận định nào sau đây là <b>không chính xác</b>?","opts":["Chất khí được cấu tạo từ các phân tử có kích thước rất nhỏ so với khoảng cách giữa chúng.","Các phân tử khí luôn chuyển động hỗn loạn không ngừng; nhiệt độ càng cao thì chuyển động càng nhanh.","Khi chuyển động hỗn loạn, các phân tử khí va chạm vào nhau và va chạm vào thành bình gây nên áp suất.","Lực tương tác hút và đẩy giữa các phân tử khí luôn có độ lớn cực đại ở mọi khoảng cách."],"ans":3,"exp":"• <b>Theo thuyết động học phân tử:</b> Giữa các phân tử có lực hút và lực đẩy phân tử, nhưng khi khoảng cách giữa các phân tử rất lớn (như ở thể khí), lực tương tác phân tử là <b>rất yếu (có thể bỏ qua)</b>.<br>• Do đó nhận định D cho rằng lực tương tác luôn có độ lớn cực đại là hoàn toàn sai.","svgGraph":null},{"q":"Khái niệm <b>khí lí tưởng</b> trong vật lí được định nghĩa dựa trên những giả thuyết đơn giản hoá nào sau đây?","opts":["Các phân tử khí được coi là các chất điểm và chỉ tương tác với nhau khi va chạm đàn hồi.","Chất khí không có khối lượng và không gây ra áp suất lên thành bình chứa.","Các phân tử khí luôn đứng yên ở các vị trí cân bằng cố định trong không gian.","Lực hút giữa các phân tử khí luôn lớn hơn lực đẩy ở mọi nhiệt độ."],"ans":0,"exp":"• <b>Mô hình khí lí tưởng:</b><br>1. Thể tích của bản thân các phân tử khí không đáng kể so với thể tích bình chứa (coi phân tử là <i>chất điểm</i>).<br>2. Các phân tử khí chỉ tương tác với nhau khi <i>va chạm</i> (coi là va chạm đàn hồi).","svgGraph":null},{"q":"Nguyên nhân trực tiếp dẫn tới <b>chuyển động Brown</b> của các hạt khói bụi hoặc hạt phấn hoa lơ lửng trong không khí là do:","opts":["Sự va chạm không cân bằng, ngẫu nhiên từ mọi phía của vô số các phân tử không khí chuyển động nhiệt vào hạt bụi.","Trọng lực của Trái Đất thay đổi liên tục theo thời gian tác dụng lên hạt bụi.","Lực từ trường của Trái Đất làm hạt bụi chuyển động theo đường xoắn ốc.","Sự bốc hơi liên tục của các chất lỏng bám trên bề mặt hạt bụi."],"ans":0,"exp":"• <b>Giải thích hiện tượng Brown:</b> Vì hạt bụi có kích thước rất nhỏ, trong từng khoảnh khắc ngắn, số phân tử khí va chạm vào hạt từ các phía là không bằng nhau.<br>• Hợp lực va chạm không cân bằng đã đẩy hạt bụi chuyển động dích dắc hỗn loạn ngẫu nhiên.","svgGraph":null},{"q":"Xét các đặc điểm của mô hình khí lí tưởng và so sánh với khí thực. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Ở cùng điều kiện nhiệt độ và áp suất, mật độ phân tử của khí lí tưởng luôn gấp đôi mật độ phân tử khí thực.","Khí thực ở điều kiện nhiệt độ cao và áp suất thấp tuân theo rất gần đúng các quy luật của khí lí tưởng.","Trong mô hình khí lí tưởng, các phân tử khí chuyển động nhiệt hỗn loạn về mọi phương hướng với xác suất như nhau.","Khi nhiệt độ chất khí hạ xuống cực thấp hoặc áp suất tăng cực lớn, khí thực có thể ngưng tụ thành thể lỏng còn khí lí tưởng theo định nghĩa thì không bao giờ ngưng tụ."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Ở áp suất thấp (phân tử ở xa nhau) và nhiệt độ cao (động năng lớn so với thế năng tương tác), khí thực coi gần đúng là khí lí tưởng.<br>• <b>Ý b: ĐÚNG.</b> Chuyển động nhiệt là đẳng hướng trong không gian.<br>• <b>Ý c: SAI.</b> Mật độ phân tử phụ thuộc vào p và T theo phương trình trạng thái, không có chuyện luôn gấp đôi.<br>• <b>Ý d: ĐÚNG.</b> Khí lí tưởng bỏ qua lực hút phân tử nên không bao giờ ngưng tụ thành chất lỏng.","svgGraph":null},{"q":"Hãy ghép nối từng thuật ngữ vật lí ở Cột A với bản chất hoặc đặc trưng tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Chuyển động nhiệt ➔ Gây ra do vô số va chạm đàn hồi của các phân tử khí lên mỗi đơn vị diện tích thành bình.","Chuyển động nhiệt ➔ Chuyển động hỗn loạn không ngừng của các hạt bụi/phấn hoa dưới tác dụng va chạm của phân tử môi trường.","Chất điểm (trong khí lí tưởng) ➔ Gây ra do vô số va chạm đàn hồi của các phân tử khí lên mỗi đơn vị diện tích thành bình.","Áp suất chất khí ➔ Chuyển động hỗn loạn không ngừng của các hạt bụi/phấn hoa dưới tác dụng va chạm của phân tử môi trường."],"ans":0,"exp":"• 1 ghép với C (Chuyển động nhiệt là chuyển động hỗn loạn phụ thuộc nhiệt độ).<br>• 2 ghép với D (Chất điểm mô tả kích thước phân tử rất nhỏ so với dung tích bình).<br>• 3 ghép với A (Áp suất khí là xung lượng va chạm lên một đơn vị diện tích thành bình).<br>• 4 ghép với B (Chuyển động Brown của hạt vi mô lơ lửng).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Áp suất của chất khí tác dụng lên thành bình chứa là kết quả của vô số va chạm [0] của các phân tử khí lên thành bình. Khi nhiệt độ của khối khí càng [1], các phân tử khí chuyển động càng nhanh, tần số và xung lượng va chạm càng mạnh, dẫn tới áp suất chất khí tác dụng lên thành bình càng [2].\"</i>","opts":["đàn hồi — cao","không đổi","thấp — nhỏ","cao — đàn hồi"],"ans":0,"exp":"• <b>Nguyên lí tạo áp suất:</b> Các va chạm được xem là <i>đàn hồi</i>. Khi nhiệt độ càng <i>cao</i>, tốc độ phân tử càng lớn thì áp suất tác dụng lên thành bình càng <i>lớn</i>.","svgGraph":null},{"q":"Một bình kín dung tích không đổi chứa một lượng khí lí tưởng ở nhiệt độ không đổi. Nếu bơm thêm khí vào bình sao cho mật độ phân tử khí tăng gấp 3 lần thì áp suất của khí trong bình sẽ:","opts":["Tăng gấp 3 lần.","Giảm đi 3 lần.","Không đổi vì thể tích bình và nhiệt độ không đổi.","Tăng gấp 9 lần."],"ans":0,"exp":"• <b>Công thức áp suất theo mật độ phân tử:</b> <span class=\"math-sym\">p</span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub><span class=\"math-sym\">E</span><sub>d</sub>.<br>• Vì nhiệt độ <span class=\"math-sym\">T</span> không đổi nên động năng trung bình không đổi. Mật độ phân tử <span class=\"math-sym\">n</span><sub>0</sub> tăng 3 lần thì áp suất <span class=\"math-sym\">p</span> tăng 3 lần.","svgGraph":null},{"q":"Khoảng cách trung bình giữa các phân tử của chất khí ở điều kiện nhiệt độ và áp suất tiêu chuẩn thường có độ lớn vào khoảng:","opts":["Lớn hơn kích thước của chính phân tử khoảng vài chục lần.","Xấp xỉ bằng đường kính của phân tử.","Nhỏ hơn đường kính của phân tử.","Bằng hàng triệu lần kích thước bình chứa."],"ans":0,"exp":"• Ở điều kiện tiêu chuẩn, đường kính phân tử cỡ <span class=\"math-sym\">10</span><sup>-10</sup> m (0,1 nm), trong khi khoảng cách trung bình giữa các phân tử khí cỡ vài nm (gấp khoảng 20 - 50 lần kích thước phân tử).","svgGraph":null},{"q":"Quan sát hình vẽ mô phỏng chuyển động Brown và tương tác va chạm của các phân tử khí vào hạt lơ lửng và thành bình chứa. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Đường zic-zac màu vàng mô tả chính xác quỹ đạo chuyển động thực tế liên tục trong từng khoảng thời gian vô cùng bé của hạt khói.","Nguyên nhân hạt khói đổi hướng chuyển động liên tục là do tại mỗi thời điểm lực va chạm tổng hợp từ các phân tử khí xung quanh là khác không.","Các va chạm của phân tử khí vào thành bình chứa làm xuất hiện áp suất chất khí lên thành bình.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a: SAI.</b> Đường gấp khúc chỉ nối các vị trí quan sát được sau các khoảng thời gian gián đoạn nhất định, không phải quỹ đạo thực tế liên tục trong từng khoảnh khắc siêu vi mô.<br>• <b>Ý b: ĐÚNG.</b> Sự bất đối xứng của các cú va chạm ngẫu nhiên tạo ra hợp lực đẩy hạt đổi hướng liên tục.<br>• <b>Ý c: SAI.</b> Hạt càng lớn thì số va chạm từ mọi phía trung hòa lẫn nhau, chuyển động Brown càng khó quan sát (hạt bụi lớn sẽ đứng yên hoặc rơi xuống do trọng lực).<br>• <b>Ý d: ĐÚNG.</b> Áp suất chính là lực nén trung bình trên một đơn vị diện tích thành bình.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"particleGrad\" cx=\"40%\" cy=\"40%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\"/>\n    </radialGradient>\n    <radialGradient id=\"smokeGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#fbbf24\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </radialGradient>\n    <marker id=\"arrowB\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"28\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">SƠ ĐỒ CHUYỂN ĐỘNG BROWN &amp; VA CHẠM PHÂN TỬ KHÍ</text>\n  \n  <!-- Bình chứa -->\n  <rect x=\"40\" y=\"45\" width=\"460\" height=\"215\" rx=\"8\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2.5\" stroke-dasharray=\"6,4\"/>\n  <text x=\"50\" y=\"65\" fill=\"#94a3b8\" font-size=\"12\">Thành bình chứa khí</text>\n  \n  <!-- Quỹ đạo zic-zac hạt khói -->\n  <polyline points=\"100,160 150,110 220,180 300,120 370,210 420,140\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/>\n  <circle cx=\"100\" cy=\"160\" r=\"5\" fill=\"#f59e0b\"/>\n  <circle cx=\"150\" cy=\"110\" r=\"5\" fill=\"#f59e0b\"/>\n  <circle cx=\"220\" cy=\"180\" r=\"5\" fill=\"#f59e0b\"/>\n  <circle cx=\"300\" cy=\"120\" r=\"5\" fill=\"#f59e0b\"/>\n  <circle cx=\"370\" cy=\"210\" r=\"5\" fill=\"#f59e0b\"/>\n  <!-- Hạt khói hiện tại -->\n  <circle cx=\"420\" cy=\"140\" r=\"16\" fill=\"url(#smokeGrad)\" stroke=\"#fef08a\" stroke-width=\"2\"/>\n  <text x=\"420\" y=\"144\" fill=\"#0f172a\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">Hạt khói</text>\n  \n  <!-- Các phân tử khí va chạm -->\n  <!-- Va chạm hạt khói -->\n  <line x1=\"470\" y1=\"110\" x2=\"438\" y2=\"132\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrowB)\"/>\n  <circle cx=\"475\" cy=\"105\" r=\"7\" fill=\"url(#particleGrad)\"/>\n  \n  <line x1=\"390\" y1=\"90\" x2=\"410\" y2=\"124\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrowB)\"/>\n  <circle cx=\"385\" cy=\"85\" r=\"7\" fill=\"url(#particleGrad)\"/>\n\n  <line x1=\"450\" y1=\"190\" x2=\"430\" y2=\"155\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrowB)\"/>\n  <circle cx=\"455\" cy=\"195\" r=\"7\" fill=\"url(#particleGrad)\"/>\n\n  <!-- Các phân tử khác bay hỗn loạn -->\n  <circle cx=\"120\" cy=\"80\" r=\"7\" fill=\"url(#particleGrad)\"/>\n  <line x1=\"120\" y1=\"80\" x2=\"145\" y2=\"70\" stroke=\"#38bdf8\" stroke-width=\"1.8\" marker-end=\"url(#arrowB)\"/>\n\n  <circle cx=\"180\" cy=\"220\" r=\"7\" fill=\"url(#particleGrad)\"/>\n  <line x1=\"180\" y1=\"220\" x2=\"195\" y2=\"245\" stroke=\"#38bdf8\" stroke-width=\"1.8\" marker-end=\"url(#arrowB)\"/>\n\n  <!-- Phân tử đập vào thành bình -->\n  <circle cx=\"70\" cy=\"190\" r=\"7\" fill=\"url(#particleGrad)\"/>\n  <line x1=\"70\" y1=\"190\" x2=\"44\" y2=\"190\" stroke=\"#f43f5e\" stroke-width=\"2\" marker-end=\"url(#arrowB)\"/>\n  <text x=\"80\" y=\"240\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Va chạm đàn hồi gây áp suất p lên thành bình</text>\n</svg>"},{"q":"Khi mở nắp một lọ nước hoa ở một góc trong phòng học kín gió, chỉ sau một khoảng thời gian ngắn, các bạn học sinh ngồi ở góc đối diện đều ngửi thấy mùi thơm. Hiện tượng này được giải thích chủ yếu là do:","opts":["Các phân tử nước hoa chuyển động hỗn loạn không ngừng và khuếch tán, xen lẫn vào khoảng trống giữa các phân tử không khí.","Không khí trong phòng có lực hút tĩnh điện kéo các phân tử nước hoa lan tỏa khắp phòng.","Các phân tử nước hoa chỉ chuyển động theo một hướng xác định từ nơi có nồng độ cao đến nơi có nồng độ thấp.","Trọng lực của Trái Đất hút các phân tử nước hoa rơi xuống sàn và lan truyền phẳng dọc theo mặt đất."],"ans":0,"exp":"• <b>Hiện tượng khuếch tán:</b> Theo mô hình động học phân tử chất khí, các phân tử nước hoa sau khi bay hơi sẽ chuyển động nhiệt hỗn loạn không ngừng về mọi phía, liên tục va chạm với các phân tử không khí và tự động lan tỏa xen kẽ vào các khoảng trống giữa các phân tử khí trong phòng.<br>• Quá trình này diễn ra hoàn toàn tự phát mà không cần có gió hay lực hút bên ngoài.","svgGraph":null}],"9":[{"q":"Quá trình biến đổi trạng thái của một lượng khí xác định trong đó <b>nhiệt độ được giữ không đổi</b> được gọi là:","opts":["Quá trình đẳng nhiệt.","Quá trình đẳng áp.","Quá trình đẳng tích.","Quá trình đoạn nhiệt."],"ans":0,"exp":"• <b>Định nghĩa:</b> Quá trình biến đổi trạng thái trong đó nhiệt độ <span class=\"math-sym\">T</span> không đổi gọi là quá trình đẳng nhiệt.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Graph 1: p-V -->\n  <g transform=\"translate(30, 20)\">\n    <line x1=\"20\" y1=\"160\" x2=\"180\" y2=\"160\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"180,160 172,156 172,164\" fill=\"#94a3b8\"/>\n    <text x=\"185\" y=\"164\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">V</text>\n    <line x1=\"20\" y1=\"160\" x2=\"20\" y2=\"10\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"20,10 16,18 24,18\" fill=\"#94a3b8\"/>\n    <text x=\"15\" y=\"8\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">p</text>\n    <text x=\"10\" y=\"172\" fill=\"#94a3b8\" font-size=\"11\">O</text>\n    <!-- Hyperbola T2 > T1 -->\n    <path d=\"M 35,40 Q 55,90 160,135\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"132\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">T₂</text>\n    <path d=\"M 30,70 Q 45,115 150,150\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <text x=\"155\" y=\"148\" fill=\"#06b6d4\" font-size=\"11\" font-weight=\"700\">T₁</text>\n    <text x=\"95\" y=\"182\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\">Đồ thị p - V (Đường cong Hyperbol)</text>\n  </g>\n  <!-- Graph 2: p - 1/V -->\n  <g transform=\"translate(240, 20)\">\n    <line x1=\"20\" y1=\"160\" x2=\"180\" y2=\"160\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"180,160 172,156 172,164\" fill=\"#94a3b8\"/>\n    <text x=\"185\" y=\"164\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">1/V</text>\n    <line x1=\"20\" y1=\"160\" x2=\"20\" y2=\"10\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <polygon points=\"20,10 16,18 24,18\" fill=\"#94a3b8\"/>\n    <text x=\"15\" y=\"8\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\">p</text>\n    <text x=\"10\" y=\"172\" fill=\"#94a3b8\" font-size=\"11\">O</text>\n    <!-- Straight line through O -->\n    <line x1=\"20\" y1=\"160\" x2=\"160\" y2=\"45\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"45\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">T₂</text>\n    <line x1=\"20\" y1=\"160\" x2=\"160\" y2=\"85\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"85\" fill=\"#06b6d4\" font-size=\"11\" font-weight=\"700\">T₁</text>\n    <text x=\"95\" y=\"182\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\">Đồ thị p theo 1/V (Đoạn thẳng)</text>\n  </g>\n</svg>"},{"q":"Biểu thức toán học nào sau đây mô tả đúng <b>Định luật Boyle</b> đối với một lượng khí lí tưởng xác định ở nhiệt độ không đổi?","opts":["p · V = hằng số.","<span class=\"fraction\"><span class=\"numerator\">p</span><span class=\"denominator\">V</span></span> = hằng số.","<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = hằng số.","<span class=\"fraction\"><span class=\"numerator\">p</span><span class=\"denominator\">T</span></span> = hằng số."],"ans":0,"exp":"• <b>Định luật Boyle:</b> Ở nhiệt độ không đổi, tích của áp suất <span class=\"math-sym\">p</span> và thể tích <span class=\"math-sym\">V</span> của một khối lượng khí xác định là một hằng số: <span class=\"math-sym\">p · V</span> = const.","svgGraph":null},{"q":"Một khối khí lí tưởng có thể tích ban đầu là 8,0 lít ở áp suất 1,5 bar. Nếu nén đẳng nhiệt khối khí này đến khi áp suất đạt 4,0 bar thì thể tích của khối khí khi đó là:","opts":["3,0 lít.","2,5 lít.","4,5 lít.","6,0 lít."],"ans":0,"exp":"• <b>Áp dụng định luật Boyle:</b> <span class=\"math-sym\">p</span><sub>1</sub><span class=\"math-sym\">V</span><sub>1</sub> = <span class=\"math-sym\">p</span><sub>2</sub><span class=\"math-sym\">V</span><sub>2</sub>.<br>• <span class=\"math-sym\">V</span><sub>2</sub> = <span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">p₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,5 × 8,0</span><span class=\"denominator\">4,0</span></span> = <b>3,0 lít</b>.","svgGraph":null},{"q":"Xét một lượng khí lí tưởng nhất định thực hiện quá trình biến đổi đẳng nhiệt. Mỗi phát biểu sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trong hệ tọa độ (p, <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">V</span></span>), đường đẳng nhiệt là một đường thẳng song song với trục hoành.","Khi thể tích khối khí giảm đi 4 lần thì áp suất của khí tăng lên 4 lần.","Đường đẳng nhiệt trong hệ tọa độ (p, V) là một nhánh của đường cong hypebol.","Đường đẳng nhiệt ứng với nhiệt độ cao hơn luôn nằm ở vị trí cao hơn đường đẳng nhiệt ứng với nhiệt độ thấp hơn trên giản đồ (p, V)."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Vì <span class=\"math-sym\">p</span> tỉ lệ nghịch với <span class=\"math-sym\">V</span>.<br>• <b>Ý b: ĐÚNG.</b> Phương trình <span class=\"math-sym\">p</span> = const/<span class=\"math-sym\">V</span> có dạng hàm số <span class=\"math-sym\">y = <span class=\"fraction\"><span class=\"numerator\">a</span><span class=\"denominator\">x</span></span></span> (đường hypebol).<br>• <b>Ý c: SAI.</b> Vì <span class=\"math-sym\">p = const · (<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">V</span></span>)</span> nên trong hệ <span class=\"math-sym\">(p, <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">V</span></span>)</span> nó là đoạn thẳng kéo dài đi qua gốc tọa độ O.<br>• <b>Ý d: ĐÚNG.</b> Ở cùng thể tích <span class=\"math-sym\">V</span>, nhiệt độ cao hơn thì áp suất lớn hơn nên đồ thị nằm trên.","svgGraph":null},{"q":"Hãy ghép dạng đồ thị ở Cột A với hệ tọa độ tương ứng của quá trình đẳng nhiệt ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Đường hypebol ➔ Giản đồ (p, T) trong quá trình đẳng nhiệt.","Đường hypebol ➔ Giản đồ (p, V) trong quá trình đẳng nhiệt.","Đoạn thẳng kéo dài đi qua gốc tọa độ O ➔ Giản đồ (p, T) trong quá trình đẳng nhiệt.","Đoạn thẳng vuông góc với trục nhiệt độ T ➔ Giản đồ (p, V) trong quá trình đẳng nhiệt."],"ans":0,"exp":"• 1 ghép với B (Hyperbol trên hệ p - V).<br>• 2 ghép với C (Tỉ lệ bậc nhất trên hệ p - <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">V</span></span>).<br>• 3 ghép với A (Đường thẳng đứng T = const trên hệ p - T).<br>• 4 ghép với D (Đường nằm ngang T = const trên hệ T - V).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong quá trình [0] của một lượng khí xác định, áp suất của khối khí [1] với thể tích của nó. Tích của áp suất và thể tích là một đại lượng [2].\"</i>","opts":["đẳng nhiệt — tỉ lệ nghịch","không đổi","tỉ lệ thuận — tăng dần","tỉ lệ nghịch — đẳng nhiệt"],"ans":0,"exp":"• <b>Phát biểu định luật Boyle:</b> Ở nhiệt độ không đổi (quá trình đẳng nhiệt), áp suất tỉ lệ nghịch với thể tích; tích <span class=\"math-sym\">p · V</span> không đổi.","svgGraph":null},{"q":"Một bọt khí nổi lên từ đáy một hồ nước sâu 10 m lên tới mặt nước. Coi nhiệt độ của nước là như nhau ở mọi độ sâu và áp suất khí quyển là 1,0 · 10⁵ Pa. Lấy g = 9,8 m/s² và khối lượng riêng của nước là 1000 kg/m³. Thể tích của bọt khí khi lên tới mặt nước so với ở đáy hồ sẽ:","opts":["Tăng gần gấp 2 lần.","Giảm đi một nửa.","Không đổi.","Tăng gần gấp 4 lần."],"ans":0,"exp":"• Áp suất ở đáy hồ: <span class=\"math-sym\">p</span><sub>1</sub> = <span class=\"math-sym\">p</span><sub>0</sub> + <span class=\"math-sym\">ρgh</span> = 10⁵ + 1000 × 9,8 × 10 = 1,98 · 10⁵ Pa ≈ 2<span class=\"math-sym\">p</span><sub>0</sub>.<br>• Khi lên mặt nước, áp suất chỉ còn <span class=\"math-sym\">p</span><sub>2</sub> = <span class=\"math-sym\">p</span><sub>0</sub> = 1,0 · 10⁵ Pa.<br>• Vì nhiệt độ không đổi: <span class=\"math-sym\">V</span><sub>2</sub> = <span class=\"math-sym\">V</span><sub>1</sub> · (<span class=\"math-sym\">p</span><sub>1</sub>/<span class=\"math-sym\">p</span><sub>2</sub>) ≈ 2<span class=\"math-sym\">V</span><sub>1</sub> (thể tích bọt khí tăng xấp xỉ gấp đôi).","svgGraph":null},{"q":"Trong động tác hít vào của con người, cơ hoành hạ xuống và các cơ liên sườn co lại làm thể tích lồng ngực (phổi) tăng lên. Dựa vào định luật Boyle (coi nhiệt độ cơ thể không đổi), hãy giải thích tại sao không khí từ môi trường ngoài lại tràn vào phổi?","opts":["Thể tích phổi tăng làm áp suất khí trong phổi giảm xuống thấp hơn áp suất khí quyển, khiến không khí ngoài tràn vào.","Thể tích phổi tăng làm áp suất khí trong phổi tăng mạnh, tạo lực hút kéo không khí bên ngoài vào.","Nhiệt độ trong phổi tăng đột ngột làm không khí bên ngoài bị hút vào để cân bằng nhiệt độ.","Thể tích phổi tăng làm tăng khối lượng riêng của chất khí trong phổi tạo chênh lệch trọng lực."],"ans":0,"exp":"• <b>Cơ chế hô hấp theo Định luật Boyle:</b> Quá trình hô hấp diễn ra ở nhiệt độ cơ thể không đổi (T = const). Khi hít vào, cơ hoành hạ xuống và các cơ liên sườn co lại làm tăng thể tích lồng ngực (V tăng). Theo định luật Boyle, áp suất khí trong phổi giảm xuống thấp hơn áp suất khí quyển (p < p<sub>kh</sub>í quyển), khiến không khí tự động tràn vào phổi.<br>• Khi thở ra, cơ hoành nâng lên làm giảm thể tích lồng ngực (V giảm), áp suất trong phổi tăng cao hơn bên ngoài (p > p<sub>kh</sub>í quyển), đẩy khí CO₂ ra ngoài.","svgGraph":null},{"q":"Cho đồ thị đường đẳng nhiệt của cùng một lượng khí lí tưởng ở hai nhiệt độ T₁ và T₂ như hình vẽ. Nhận định nào sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu giữ nguyên áp suất p, khi chuyển từ nhiệt độ T₁ sang T₂ thể tích của khối khí sẽ bị giảm đi.","Nhiệt độ tuyệt đối của chất khí ở trạng thái 2 lớn hơn trạng thái 1 (T₂ > T₁).","Trên đồ thị (p, <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">V</span></span>), hệ số góc của đường thẳng ứng với T₂ lớn hơn đường thẳng ứng với T₁.","Cả 3 nhận định trên đều đúng."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Kẻ một đường thẳng <span class=\"math-sym\">V = hằng số</span> cắt 2 đường tại <span class=\"math-sym\">p</span><sub>2</sub> > <span class=\"math-sym\">p</span><sub>1</sub> ⇒ <span class=\"math-sym\">T</span><sub>2</sub> > <span class=\"math-sym\">T</span><sub>1</sub>.<br>• <b>Ý b: ĐÚNG.</b> <span class=\"math-sym\">p = (nRT) · (<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">V</span></span>)</span>, hệ số góc tỉ lệ thuận với <span class=\"math-sym\">T</span> nên đường <span class=\"math-sym\">T</span><sub>2</sub> dốc hơn.<br>• <b>Ý c: SAI.</b> Cùng áp suất <span class=\"math-sym\">p</span>, nhiệt độ cao hơn thì thể tích <span class=\"math-sym\">V</span> phải lớn hơn.<br>• <b>Ý d: SAI.</b> Định luật chỉ nghiệm đúng ở áp suất thấp đến trung bình.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr9\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐỒ THỊ ĐƯỜNG ĐẲNG NHIỆT (ĐỊNH LUẬT BOYLE)</text>\n  \n  <!-- Trục tọa độ đồ thị 1: p - V -->\n  <g transform=\"translate(60, 40)\">\n    <text x=\"70\" y=\"10\" fill=\"#cbd5e1\" font-size=\"12\" font-weight=\"bold\">Hệ tọa độ (p, V)</text>\n    <line x1=\"20\" y1=\"190\" x2=\"190\" y2=\"190\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr9)\"/>\n    <line x1=\"20\" y1=\"190\" x2=\"20\" y2=\"20\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr9)\"/>\n    <text x=\"185\" y=\"208\" fill=\"#94a3b8\" font-size=\"12\">V</text>\n    <text x=\"6\" y=\"24\" fill=\"#94a3b8\" font-size=\"12\">p</text>\n    <text x=\"10\" y=\"205\" fill=\"#94a3b8\" font-size=\"11\">O</text>\n    \n    <!-- Hyperbol T1 -->\n    <path d=\"M 30,170 Q 55,70 170,45\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <text x=\"175\" y=\"48\" fill=\"#06b6d4\" font-size=\"12\" font-weight=\"bold\">T₁</text>\n    \n    <!-- Hyperbol T2 -->\n    <path d=\"M 45,180 Q 80,95 180,75\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <text x=\"185\" y=\"78\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">T₂</text>\n    \n    <text x=\"90\" y=\"220\" fill=\"#38bdf8\" font-size=\"12\" text-anchor=\"middle\">Đường cong hypebol</text>\n  </g>\n\n  <!-- Trục tọa độ đồ thị 2: p - 1/V -->\n  <g transform=\"translate(320, 40)\">\n    <text x=\"70\" y=\"10\" fill=\"#cbd5e1\" font-size=\"12\" font-weight=\"bold\">Hệ tọa độ (p, 1/V)</text>\n    <line x1=\"20\" y1=\"190\" x2=\"180\" y2=\"190\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr9)\"/>\n    <line x1=\"20\" y1=\"190\" x2=\"20\" y2=\"20\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr9)\"/>\n    <text x=\"175\" y=\"208\" fill=\"#94a3b8\" font-size=\"12\">1/V</text>\n    <text x=\"6\" y=\"24\" fill=\"#94a3b8\" font-size=\"12\">p</text>\n    <text x=\"10\" y=\"205\" fill=\"#94a3b8\" font-size=\"11\">O</text>\n    \n    <!-- Đường thẳng qua gốc O -->\n    <line x1=\"20\" y1=\"190\" x2=\"40\" y2=\"170\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"40\" y1=\"170\" x2=\"160\" y2=\"50\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"55\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">T₂</text>\n\n    <line x1=\"20\" y1=\"190\" x2=\"40\" y2=\"178\" stroke=\"#06b6d4\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"40\" y1=\"178\" x2=\"160\" y2=\"105\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <text x=\"165\" y=\"110\" fill=\"#06b6d4\" font-size=\"12\" font-weight=\"bold\">T₁</text>\n\n    <text x=\"85\" y=\"220\" fill=\"#38bdf8\" font-size=\"12\" text-anchor=\"middle\">Đoạn thẳng hướng về gốc O</text>\n  </g>\n</svg>"},{"q":"Tại sao khi nén khí trong thí nghiệm kiểm chứng định luật Boyle, ta phải dịch chuyển pit-tông một cách thật chậm rãi?","opts":["Để nhiệt lượng sinh ra do ma sát và nén khí kịp truyền ra môi trường, đảm bảo nhiệt độ của khối khí không đổi.","Để tránh làm vỡ áp kế đo áp suất gắn trên xilanh.","Để các phân tử khí có đủ thời gian biến mất khỏi xilanh.","Để thể tích khí luôn giữ cố định không đổi trong quá trình nén."],"ans":0,"exp":"• <b>Kỹ năng thực hành:</b> Khi nén nhanh, công cơ học biến thành nội năng làm chất khí nóng lên (<span class=\"math-sym\">T</span> tăng, quá trình đoạn nhiệt).<br>• Do đó phải nén <b>rất chậm</b> để chất khí kịp trao đổi nhiệt với môi trường, giữ nhiệt độ <span class=\"math-sym\">T</span> ổn định.","svgGraph":null}],"10":[{"q":"Quá trình biến đổi trạng thái của một lượng khí xác định trong đó <b>áp suất được giữ không đổi</b> được gọi là:","opts":["Quá trình đẳng áp.","Quá trình đẳng nhiệt.","Quá trình đẳng tích.","Quá trình đoạn nhiệt."],"ans":0,"exp":"• <b>Định nghĩa:</b> Quá trình biến đổi trạng thái khi áp suất <span class=\"math-sym\">p</span> không đổi gọi là quá trình đẳng áp.","svgGraph":null},{"q":"Hệ thức nào sau đây mô tả đúng mối quan hệ giữa thể tích V và nhiệt độ tuyệt đối T trong <b>Định luật Charles</b>?","opts":["<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = hằng số (hay <span class=\"fraction\"><span class=\"numerator\">V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">V₂</span><span class=\"denominator\">T₂</span></span>).","V · T = hằng số.","<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">t</span></span> = hằng số (với t là nhiệt độ Celsius).","p · V = hằng số."],"ans":0,"exp":"• <b>Định luật Charles:</b> Trong quá trình đẳng áp của một lượng khí xác định, thể tích tỉ lệ thuận với nhiệt độ tuyệt đối: <span class=\"math-sym\">V / T</span> = const.","svgGraph":null},{"q":"Một khối khí lí tưởng có thể tích 4,5 lít ở nhiệt độ 27°C. Khi nung nóng đẳng áp khối khí đó đến nhiệt độ 127°C thì thể tích của khối khí sẽ là:","opts":["6,0 lít.","5,5 lít.","7,5 lít.","9,0 lít."],"ans":0,"exp":"• <b>Đổi sang thang Kelvin:</b><br>• <span class=\"math-sym\">T</span><sub>1</sub> = 27 + 273 = 300 K.<br>• <span class=\"math-sym\">T</span><sub>2</sub> = 127 + 273 = 400 K.<br>• <span class=\"math-sym\">V</span><sub>2</sub> = <span class=\"math-sym\">V</span><sub>1</sub> · <span class=\"fraction\"><span class=\"numerator\">T₂</span><span class=\"denominator\">T₁</span></span> = 4,5 × <span class=\"fraction\"><span class=\"numerator\">400</span><span class=\"denominator\">300</span></span> = <b>6,0 lít</b>.","svgGraph":null},{"q":"Khi nghiên cứu về quá trình đẳng áp và thang nhiệt độ tuyệt đối Kelvin, mỗi khẳng định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Thể tích của một lượng khí xác định tỉ lệ thuận với nhiệt độ theo thang Celsius t (°C).","Độ không tuyệt đối (0 K hay -273,15°C) là giới hạn nhiệt độ thấp nhất mà vật chất có thể tiến tới.","Trên đồ thị (V, T), đường đẳng áp là đoạn thẳng có đường kéo dài đi qua gốc tọa độ O (0 K).","Đối với hai đường đẳng áp của cùng một khối khí, đường nào có góc nghiêng lớn hơn so với trục nhiệt độ T sẽ ứng với áp suất nhỏ hơn."],"ans":0,"exp":"• <b>Ý a: SAI.</b> Thể tích tỉ lệ thuận với nhiệt độ tuyệt đối <span class=\"math-sym\">T</span> (Kelvin), không phải nhiệt độ Celsius <span class=\"math-sym\">t</span>.<br>• <b>Ý b: ĐÚNG.</b> 0 K là nhiệt độ mà mọi chuyển động nhiệt phân tử lí thuyết dừng lại.<br>• <b>Ý c: ĐÚNG.</b> Đồ thị có dạng <span class=\"math-sym\">V = (const) · T</span>.<br>• <b>Ý d: ĐÚNG.</b> Hệ số góc <span class=\"math-sym\">k = <span class=\"fraction\"><span class=\"numerator\">nR</span><span class=\"denominator\">p</span></span></span>. Áp suất <span class=\"math-sym\">p</span> càng nhỏ thì hệ số góc <span class=\"math-sym\">k</span> càng lớn (đường dốc hơn).","svgGraph":null},{"q":"Hãy ghép các thông số/công thức ở Cột A với ý nghĩa vật lí chuẩn xác ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["V₁ / T₁ = V₂ / T₂ ➔ Đường đẳng áp cắt trục hoành tại điểm nhiệt độ không tuyệt đối.","V₁ / T₁ = V₂ / T₂ ➔ Độ không tuyệt đối, tại đó thể tích khí lí tưởng tiến dần về 0.","T = t + 273,15 ➔ Đường đẳng áp cắt trục hoành tại điểm nhiệt độ không tuyệt đối.","0 K (-273,15°C) ➔ Độ không tuyệt đối, tại đó thể tích khí lí tưởng tiến dần về 0."],"ans":0,"exp":"• 1 ghép với D (Định luật Charles).<br>• 2 ghép với C (Công thức đổi nhiệt độ sang Kelvin).<br>• 3 ghép với B (Ý nghĩa của độ không tuyệt đối).<br>• 4 ghép với A (Đặc điểm đường đẳng áp cắt trục hoành tại -273,15°C).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong quá trình đẳng áp của một khối lượng khí xác định, thể tích của chất khí tỉ lệ thuận với [0]. Khi nhiệt độ tăng, các phân tử khí chuyển động nhanh hơn; để giữ cho [1] không đổi, chất khí buộc phải [2] để giảm mật độ va chạm trên mỗi đơn vị diện tích.\"</i>","opts":["nhiệt độ tuyệt đối — áp suất","không đổi","co lại — khối lượng riêng","áp suất — nhiệt độ tuyệt đối"],"ans":0,"exp":"• <b>Bản chất vi mô:</b> Để áp suất giữ nguyên khi tốc độ phân tử tăng, thể tích phải <i>giãn nở</i> tương ứng.","svgGraph":null},{"q":"Một quả bóng bay chứa khí hidro để ngoài trời nắng to bị căng phồng lên và có thể bị nổ. Hiện tượng này được giải thích chủ yếu bằng:","opts":["Khi nhiệt độ tăng, khí trong bóng giãn nở làm tăng thể tích và áp suất lên màng bóng theo định luật Charles.","Màng cao su của bóng bay bị co lại khi gặp nhiệt độ cao.","Áp suất khí quyển bên ngoài quả bóng tăng đột ngột.","Khí hidro phản ứng hóa học tự cháy với màng cao su."],"ans":0,"exp":"• Khi nhiệt độ ngoài trời tăng cao, khí bên trong nhận nhiệt và dãn nở đẳng áp hoặc tăng áp suất tác dụng lên thành cao su, vượt quá giới hạn đàn hồi gây nổ.","svgGraph":null},{"q":"Một quả bóng bàn vô tình bị giẫm bẹp một phần nhưng vỏ bóng chưa bị rách thủng. Khi nhúng quả bóng đó vào trong một cốc nước sôi, vỏ bóng phồng trở lại như cũ. Hiện tượng này được giải thích dựa trên cơ sở vật lí nào sau đây?","opts":["Nhiệt độ không khí bên trong bóng tăng lên làm khối khí dãn nở đẳng áp, tăng thể tích đẩy vỏ bóng phồng lại.","Nước nóng thấm qua lớp vỏ nhựa làm tăng lượng phân tử khí chứa bên trong quả bóng bàn.","Nhiệt độ cao làm vỏ bóng bàn bằng chất dẻo co rút mạnh ép không khí dồn vào tâm quả bóng.","Áp suất của nước nóng bên ngoài ép đều vào vỏ bóng từ mọi phía làm phục hồi hình cầu ban đầu."],"ans":0,"exp":"• <b>Ứng dụng Định luật Charles:</b> Khi nhúng bóng vào nước sôi, áp suất khí bên trong coi như xấp xỉ áp suất khí quyển (p ≈ const). Khi nhiệt độ tăng từ T₁ lên T₂, theo định luật Charles: <span class=\"fraction\"><span class=\"numerator\">V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">V₂</span><span class=\"denominator\">T₂</span></span> nên thể tích khí tăng tỉ lệ thuận, khí nở ra tạo áp lực đẩy vỏ bóng phồng căng trở lại như cũ.<br>• Lưu ý: Phương pháp này chỉ áp dụng thành công khi vỏ bóng bàn chưa bị thủng hoặc rách nứt.","svgGraph":null},{"q":"Dựa vào đồ thị đường đẳng áp hình bên, đánh giá tính Đúng/Sai của các nhận định vật lí sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tại mốc 0°C trên đồ thị (V, t), thể tích của khối khí đã giảm về bằng 0.","Trên đồ thị (V, T), đường p₁ nằm trên đường p₂ nên áp suất p₁ nhỏ hơn áp suất p₂ (p₁ < p₂).","Nếu hạ nhiệt độ về 0 K thì về mặt lí thuyết thể tích của khí lí tưởng tiến về giá trị bằng 0.","Giao điểm của đường kéo dài các đường đẳng áp với trục hoành t (°C) luôn là điểm -273,15°C với mọi chất khí lí tưởng."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Kẻ đường thẳng đứng <span class=\"math-sym\">T = hằng số</span>: <span class=\"math-sym\">V</span><sub>1</sub> > <span class=\"math-sym\">V</span><sub>2</sub> ⇒ <span class=\"math-sym\">p</span><sub>1</sub> < <span class=\"math-sym\">p</span><sub>2</sub>.<br>• <b>Ý b: ĐÚNG.</b> Đây là hệ quả suy ra từ định luật Charles đối với chất khí lí tưởng.<br>• <b>Ý c: SAI.</b> Tại 0°C = 273,15 K thì thể tích khí vẫn có giá trị hữu hạn <span class=\"math-sym\">V</span><sub>0</sub> > 0.<br>• <b>Ý d: ĐÚNG.</b> Mọi đường đẳng áp đều có đường kéo dài hội tụ tại điểm <span class=\"math-sym\">t</span> = -273,15°C.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr10\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐỒ THỊ ĐƯỜNG ĐẲNG ÁP (ĐỊNH LUẬT CHARLES)</text>\n  \n  <!-- Giản đồ (V, T) Kelvin -->\n  <g transform=\"translate(60, 40)\">\n    <text x=\"60\" y=\"10\" fill=\"#cbd5e1\" font-size=\"12\" font-weight=\"bold\">Hệ tọa độ (V, T) Kelvin</text>\n    <line x1=\"20\" y1=\"190\" x2=\"190\" y2=\"190\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr10)\"/>\n    <line x1=\"20\" y1=\"190\" x2=\"20\" y2=\"20\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr10)\"/>\n    <text x=\"185\" y=\"208\" fill=\"#94a3b8\" font-size=\"12\">T (K)</text>\n    <text x=\"6\" y=\"24\" fill=\"#94a3b8\" font-size=\"12\">V</text>\n    <text x=\"10\" y=\"205\" fill=\"#94a3b8\" font-size=\"11\">0 K</text>\n    \n    <!-- Đường p1 (nét đứt kéo dài qua O) -->\n    <line x1=\"20\" y1=\"190\" x2=\"55\" y2=\"155\" stroke=\"#10b981\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"55\" y1=\"155\" x2=\"175\" y2=\"35\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n    <text x=\"180\" y=\"40\" fill=\"#10b981\" font-size=\"12\" font-weight=\"bold\">p₁</text>\n\n    <!-- Đường đẳng áp p2 -->\n    <line x1=\"20\" y1=\"190\" x2=\"55\" y2=\"170\" stroke=\"#f59e0b\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"55\" y1=\"170\" x2=\"175\" y2=\"90\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n    <text x=\"180\" y=\"95\" fill=\"#f59e0b\" font-size=\"12\" font-weight=\"bold\">p₂</text>\n\n    <text x=\"90\" y=\"220\" fill=\"#38bdf8\" font-size=\"12\" text-anchor=\"middle\">Đoạn thẳng hướng về gốc 0 K</text>\n  </g>\n\n  <!-- Giản đồ (V, t) Celsius -->\n  <g transform=\"translate(310, 40)\">\n    <text x=\"60\" y=\"10\" fill=\"#cbd5e1\" font-size=\"12\" font-weight=\"bold\">Hệ tọa độ (V, t) Celsius</text>\n    <line x1=\"10\" y1=\"190\" x2=\"200\" y2=\"190\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr10)\"/>\n    <line x1=\"80\" y1=\"190\" x2=\"80\" y2=\"20\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr10)\"/>\n    <text x=\"195\" y=\"208\" fill=\"#94a3b8\" font-size=\"12\">t (°C)</text>\n    <text x=\"65\" y=\"24\" fill=\"#94a3b8\" font-size=\"12\">V</text>\n    <text x=\"75\" y=\"205\" fill=\"#94a3b8\" font-size=\"11\">0°C</text>\n    \n    <!-- Cắt trục hoành tại -273.15 -->\n    <line x1=\"20\" y1=\"190\" x2=\"80\" y2=\"135\" stroke=\"#10b981\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"80\" y1=\"135\" x2=\"185\" y2=\"40\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n    <circle cx=\"20\" cy=\"190\" r=\"3.5\" fill=\"#f43f5e\"/>\n    <text x=\"2\" y=\"208\" fill=\"#f43f5e\" font-size=\"10\" font-weight=\"bold\">-273,15°C</text>\n\n    <text x=\"100\" y=\"220\" fill=\"#38bdf8\" font-size=\"12\" text-anchor=\"middle\">Cắt trục hoành tại -273,15°C</text>\n  </g>\n</svg>"},{"q":"Khinh khí cầu du lịch có thể bay lơ lửng và nâng giỏ chở người lên không trung nhờ đầu đốt gas đặt dưới đáy quả khí cầu. Nguyên lí vật lí chủ yếu của hoạt động này là gì?","opts":["Đốt nóng làm không khí trong khí cầu dãn nở, khối lượng riêng giảm nhỏ hơn không khí lạnh xung quanh, tạo lực nâng Ác-si-mét.","Ngọn lửa đốt tạo ra dòng khí phản lực phụt thẳng xuống mặt đất đẩy khinh khí cầu bay lên như tên lửa.","Khí nóng bên trong khí cầu biến đổi hóa học thành khí hydrogen có khối lượng siêu nhẹ.","Đầu đốt gas tích điện dương cho khí cầu tạo lực đẩy tĩnh điện với bề mặt Trái Đất."],"ans":0,"exp":"• <b>Nguyên lí bay của khinh khí cầu:</b> Quá trình đốt nóng không khí bên trong khoang mở ở đáy diễn ra ở áp suất khí quyển coi như không đổi (p = const).<br>• Theo định luật Charles, khi đốt nóng, không khí trong khí cầu nở ra. Vì khối lượng riêng ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> nên khối lượng riêng của không khí nóng nhỏ hơn không khí lạnh bên ngoài (ρ<sub>n</sub>óng < ρ_lạnh).<br>• Theo định luật Archimedes, lực đẩy Archimedes F<sub>A</sub> = ρ_lạnh · V · g lớn hơn tổng trọng lực của khí cầu và khoang tải, giúp khinh khí cầu bay lên.","svgGraph":null}],"11":[{"q":"Phương trình trạng thái của một lượng khí lí tưởng xác định (phương trình Clapeyron) được viết dưới dạng nào sau đây?","opts":["<span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · V₂</span><span class=\"denominator\">T₂</span></span> = hằng số.","p₁ · V₁ · T₁ = p₂ · V₂ · T₂.","<span class=\"fraction\"><span class=\"numerator\">p₁ · T₁</span><span class=\"denominator\">V₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · T₂</span><span class=\"denominator\">V₂</span></span>.","<span class=\"fraction\"><span class=\"numerator\">p₁</span><span class=\"denominator\">V₁ · T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂</span><span class=\"denominator\">V₂ · T₂</span></span>."],"ans":0,"exp":"• <b>Phương trình Clapeyron:</b> Đối với một khối lượng khí xác định: <span class=\"fraction\"><span class=\"numerator\">p · V</span><span class=\"denominator\">T</span></span> = const, hay <span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · V₂</span><span class=\"denominator\">T₂</span></span>.","svgGraph":null},{"q":"Phương trình Clapeyron – Mendeleev biểu diễn mối quan hệ giữa áp suất p, thể tích V, nhiệt độ tuyệt đối T và số mol n của khí lí tưởng là:","opts":["p · V = n · R · T (với R = 8,31 J/(mol·K)).","p · V = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">M</span></span> · k · T.","p · T = n · R · V.","<span class=\"fraction\"><span class=\"numerator\">p · V</span><span class=\"denominator\">T</span></span> = n · k."],"ans":0,"exp":"• <b>Phương trình Clapeyron - Mendeleev:</b> <span class=\"math-sym\">p · V</span> = <span class=\"math-sym\">n · R · T</span> = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">M</span></span><span class=\"math-sym\">R · T</span>.<br>• Trong đó <span class=\"math-sym\">R ≈ 8,31</span> J/(mol·K) là hằng số khí lí tưởng.","svgGraph":null},{"q":"Trong cấp cứu y tế, một bình thép chuyên dụng có dung tích 10 lít chứa khí oxygen (O₂) ở nhiệt độ 27°C và áp suất cao 150 atm. Coi oxygen là khí lí tưởng (M = 32 g/mol, R = 0,0821 atm·L/(mol·K)), khối lượng khí oxygen chứa trong bình là:","opts":["Khoảng 1,95 kg.","Khoảng 3,90 kg.","Khoảng 0,98 kg.","Khoảng 5,85 kg."],"ans":0,"exp":"• <b>Áp dụng phương trình Clapeyron - Mendeleev:</b><br>p · V = n · R · T = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">M</span></span> · R · T ⟹ m = <span class=\"fraction\"><span class=\"numerator\">p · V · M</span><span class=\"denominator\">R · T</span></span>.<br>• Với p = 150 atm, V = 10 L, T = 27 + 273 = 300 K, M = 32 g/mol:<br>m = <span class=\"fraction\"><span class=\"numerator\">150 · 10 · 32</span><span class=\"denominator\">0,0821 · 300</span></span> ≈ 1949 g ≈ 1,95 kg.","svgGraph":null},{"q":"Xét các trường hợp riêng và hệ quả của phương trình trạng thái khí lí tưởng. Mỗi khẳng định sau là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Ở cùng điều kiện nhiệt độ và áp suất, các chất khí khác nhau có cùng thể tích sẽ chứa số phân tử khí hoàn toàn khác nhau.","Khi nhiệt độ T không đổi, phương trình trạng thái suy biến về định luật Boyle (p · V = const).","Khi áp suất p không đổi, phương trình trạng thái suy biến về định luật Charles (<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = const).","Khối lượng riêng ρ của một chất khí lí tưởng tỉ lệ thuận với áp suất p và tỉ lệ nghịch với nhiệt độ tuyệt đối T."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Định luật Boyle là trường hợp đẳng nhiệt.<br>• <b>Ý b: ĐÚNG.</b> Định luật Charles là trường hợp đẳng áp.<br>• <b>Ý c: ĐÚNG.</b> <span class=\"math-sym\">ρ</span> = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> = <span class=\"fraction\"><span class=\"numerator\">pM</span><span class=\"denominator\">RT</span></span>.<br>• <b>Ý d: SAI.</b> Theo định luật Avogadro, cùng p, V, T thì số mol và số phân tử là <b>như nhau</b>.","svgGraph":null},{"q":"Hãy ghép các công thức ở Cột A với tên gọi quy chuẩn ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["p<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = hằng số ➔ Quá trình đẳng tích (Định luật Gay-Lussac/Sác-lơ).","p<span class=\"fraction\"><span class=\"numerator\">V</span><span class=\"denominator\">T</span></span> = hằng số ➔ Phương trình Clapeyron - Mendeleev.","pV = (m/M)RT ➔ Quá trình đẳng tích (Định luật Gay-Lussac/Sác-lơ).","p₁ / T₁ = p₂ / T₂ ➔ Phương trình Clapeyron - Mendeleev."],"ans":0,"exp":"• 1 ghép với D (Phương trình trạng thái).<br>• 2 ghép với B (Phương trình Clapeyron - Mendeleev).<br>• 3 ghép với A (Quá trình đẳng tích).<br>• 4 ghép với C (Khối lượng riêng của khí).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trạng thái của một lượng khí xác định được đặc trưng bởi ba thông số trạng thái: [0], thể tích và [1]. Mối liên hệ đồng thời giữa cả ba thông số này được xác định thông qua [2] của khí lí tưởng.\"</i>","opts":["áp suất — nhiệt độ tuyệt đối","không đổi","năng lượng — vận tốc","nhiệt độ tuyệt đối — áp suất"],"ans":0,"exp":"• Ba thông số trạng thái cơ bản là <b>áp suất (p)</b>, <b>thể tích (V)</b> và <b>nhiệt độ tuyệt đối (T)</b>. Mối liên hệ được gọi là <b>phương trình trạng thái</b>.","svgGraph":null},{"q":"Nồi áp suất là một thiết bị gia dụng giúp ninh nhừ xương và nấu chín thức ăn rất nhanh chóng. Cơ chế vật lí chủ yếu giúp nồi áp suất rút ngắn thời gian nấu nướng là gì?","opts":["Van kín giữ thể tích không đổi; khi nhiệt độ tăng, áp suất tăng cao làm nhiệt độ sôi của nước tăng vượt quá 100°C.","Nắp kín giữ nhiệt giúp thức ăn hấp thụ 100% nhiệt lượng mà không bị tỏa ra môi trường xung quanh.","Áp suất hơi rất cao tác dụng lực cơ học trực tiếp bẻ gãy cấu trúc liên kết sợi của thực phẩm.","Các phân tử hơi nước va chạm với vận tốc ánh sáng làm phân rã các tế bào thực phẩm nhanh hơn."],"ans":0,"exp":"• <b>Nguyên lí nồi áp suất:</b> Khi nấu trong nồi áp suất đậy kín có gioăng cao su, thể tích không đổi (V ≈ const). Nước sôi hóa hơi làm áp suất trong nồi tăng vọt lên khoảng 1,5 - 2 atm.<br>• Nhiệt độ sôi của chất lỏng phụ thuộc thuận vào áp suất mặt thoáng: Áp suất càng cao thì nhiệt độ sôi của nước càng tăng (lên tới 115 - 120°C). Nước sôi ở nhiệt độ cao truyền nhiệt nhanh gấp nhiều lần, giúp thức ăn chín nhừ nhanh chóng và tiết kiệm tới 70% thời gian cũng như năng lượng đun nấu.","svgGraph":null},{"q":"Trước khi lên đường cao tốc vào buổi sáng se lạnh (20°C), bác tài xế đo áp suất lốp xe là 2,2 bar. Sau khi chạy tốc độ cao liên tục vào giữa trưa nắng, nhiệt độ không khí trong lốp xe tăng lên đến 60°C. Coi thể tích lốp xe dãn nở không đáng kể. Áp suất khí trong lốp lúc này là:","opts":["2,50 bar.","2,85 bar.","2,35 bar.","3,10 bar."],"ans":0,"exp":"• Coi thể tích không đổi (đẳng tích): <span class=\"math-sym\">T</span><sub>1</sub> = 20 + 273 = 293 K; <span class=\"math-sym\">T</span><sub>2</sub> = 60 + 273 = 333 K.<br>• <span class=\"math-sym\">p</span><sub>2</sub> = <span class=\"math-sym\">p</span><sub>1</sub> · (<span class=\"math-sym\">T</span><sub>2</sub>/<span class=\"math-sym\">T</span><sub>1</sub>) = 2,2 × (<span class=\"fraction\"><span class=\"numerator\">333</span><span class=\"denominator\">293</span></span>) ≈ <b>2,50 bar</b>.","svgGraph":null},{"q":"Xét chu trình biến đổi từ trạng thái (1) sang (2) rồi sang (3) của một lượng khí lí tưởng trên giản đồ (p, V) như hình vẽ. Nhận định nào sau đây là Đúng hay Sai?<br>Xác định tính Đúng/Sai của nhận định: <i>\"Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là quá trình dãn nở đẳng nhiệt.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Đoạn (1)-(2) là nhánh cong hyperbol đẳng nhiệt.<br>• <b>Ý b: ĐÚNG.</b> Vì ở trạng thái (3) cùng thể tích <span class=\"math-sym\">V</span><sub>2</sub> nhưng áp suất <span class=\"math-sym\">p</span><sub>2</sub> > <span class=\"math-sym\">p</span><sub>1</sub> nên <span class=\"math-sym\">T</span><sub>3</sub> > <span class=\"math-sym\">T</span><sub>2</sub>.<br>• <b>Ý c: ĐÚNG.</b> Đoạn (2)-(3) vuông góc với trục V nên <span class=\"math-sym\">V = hằng số</span> (đẳng tích).<br>• <b>Ý d: ĐÚNG.</b> Thể tích tăng từ <span class=\"math-sym\">V</span><sub>1</sub> lên <span class=\"math-sym\">V</span><sub>2</sub> làm áp suất giảm từ <span class=\"math-sym\">p</span><sub>2</sub> xuống <span class=\"math-sym\">p</span><sub>1</sub>.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr11\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\"/>\n    </marker>\n    <marker id=\"arrowProcess\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#f59e0b\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">CHU TRÌNH BIẾN ĐỔI TRẠNG THÁI KHÍ LÍ TƯỞNG (p - V)</text>\n\n  <!-- Trục tọa độ p - V -->\n  <line x1=\"60\" y1=\"230\" x2=\"490\" y2=\"230\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr11)\"/>\n  <line x1=\"60\" y1=\"230\" x2=\"60\" y2=\"35\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr11)\"/>\n  <text x=\"480\" y=\"250\" fill=\"#94a3b8\" font-size=\"13\">V (m³)</text>\n  <text x=\"35\" y=\"45\" fill=\"#94a3b8\" font-size=\"13\">p (Pa)</text>\n  <text x=\"45\" y=\"245\" fill=\"#94a3b8\" font-size=\"12\">O</text>\n\n  <!-- Tọa độ các trạng thái -->\n  <!-- Trạng thái 1: (V1=140, p1=70) -->\n  <!-- Trạng thái 2: (V2=340, p2=160) -->\n  <!-- Trạng thái 3: (V3=340, p3=70) -->\n\n  <!-- Các đường gióng -->\n  <line x1=\"60\" y1=\"70\" x2=\"140\" y2=\"70\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"60\" y1=\"160\" x2=\"340\" y2=\"160\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"140\" y1=\"230\" x2=\"140\" y2=\"70\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"340\" y1=\"230\" x2=\"340\" y2=\"70\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n\n  <text x=\"25\" y=\"75\" fill=\"#94a3b8\" font-size=\"12\">p₂</text>\n  <text x=\"25\" y=\"165\" fill=\"#94a3b8\" font-size=\"12\">p₁</text>\n  <text x=\"135\" y=\"248\" fill=\"#94a3b8\" font-size=\"12\">V₁</text>\n  <text x=\"335\" y=\"248\" fill=\"#94a3b8\" font-size=\"12\">V₂</text>\n\n  <!-- Quá trình 1 -> 2: dãn nở đẳng nhiệt T1 -->\n  <path d=\"M 140,70 Q 210,130 340,160\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3\"/>\n  <!-- Mũi tên chỉ chiều 1 -> 2 -->\n  <path d=\"M 230,123 L 236,127\" stroke=\"#06b6d4\" stroke-width=\"3\" marker-end=\"url(#arrowProcess)\"/>\n  <text x=\"210\" y=\"105\" fill=\"#06b6d4\" font-size=\"12\" font-weight=\"bold\">(1) → (2): Đẳng nhiệt T</text>\n\n  <!-- Quá trình 2 -> 3: làm nguội đẳng tích V2 -->\n  <line x1=\"340\" y1=\"160\" x2=\"340\" y2=\"70\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n  <path d=\"M 340,120 L 340,105\" stroke=\"#f43f5e\" stroke-width=\"3\" marker-end=\"url(#arrowProcess)\"/>\n  <text x=\"350\" y=\"120\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">(2) → (3): Đẳng tích V₂</text>\n\n  <!-- Điểm nút trạng thái -->\n  <circle cx=\"140\" cy=\"70\" r=\"6\" fill=\"#38bdf8\"/>\n  <text x=\"148\" y=\"65\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">(1) [p₂, V₁, T₁]</text>\n\n  <circle cx=\"340\" cy=\"160\" r=\"6\" fill=\"#38bdf8\"/>\n  <text x=\"350\" y=\"170\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">(2) [p₁, V₂, T₁]</text>\n\n  <circle cx=\"340\" cy=\"70\" r=\"6\" fill=\"#fbbf24\"/>\n  <text x=\"350\" y=\"65\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">(3) [p₂, V₂, T₃]</text>\n</svg>"},{"q":"Khối lượng riêng của không khí ở điều kiện tiêu chuẩn (0°C và 1,013 · 10⁵ Pa) là 1,29 kg/m³. Ở nhiệt độ 100°C và áp suất 2,026 · 10⁵ Pa, khối lượng riêng của không khí xấp xỉ bằng:","opts":["1,89 kg/m³.","2,58 kg/m³.","1,45 kg/m³.","0,95 kg/m³."],"ans":0,"exp":"• Áp dụng công thức: <span class=\"math-sym\">ρ</span> = <span class=\"fraction\"><span class=\"numerator\">pM</span><span class=\"denominator\">RT</span></span> ⇒ <span class=\"fraction\"><span class=\"numerator\">ρ₂</span><span class=\"denominator\">ρ₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂</span><span class=\"denominator\">p₁</span></span> · <span class=\"fraction\"><span class=\"numerator\">T₁</span><span class=\"denominator\">T₂</span></span>.<br>• <span class=\"math-sym\">ρ</span><sub>2</sub> = 1,29 × (2,<span class=\"fraction\"><span class=\"numerator\">026</span><span class=\"denominator\">1</span></span>,013) × (<span class=\"fraction\"><span class=\"numerator\">273</span><span class=\"denominator\">373</span></span>) = 1,29 × 2 × 0,732 ≈ <b>1,89 kg/m³</b>.","svgGraph":null}],"12":[{"q":"Biểu thức nào sau đây thể hiện mối liên hệ giữa áp suất p của khí lí tưởng với mật độ phân tử n₀ và động năng tịnh tiến trung bình Ed của phân tử?","opts":["p = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span> · n₀ · Ed.","p = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span> · n₀ · Ed.","p = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · n₀ · Ed.","p = n₀ · k · Ed."],"ans":0,"exp":"• <b>Hệ thức cơ bản:</b> <span class=\"math-sym\">p</span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub><span class=\"math-sym\">m</span><span class=\"math-sym\">v²</span> = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub>(<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span><span class=\"math-sym\">m</span><span class=\"math-sym\">v²</span>) = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">3</span></span><span class=\"math-sym\">n</span><sub>0</sub><span class=\"math-sym\">E</span><sub>d</sub>.","svgGraph":null},{"q":"Động năng tịnh tiến trung bình của phân tử khí lí tưởng tỉ lệ thuận với nhiệt độ tuyệt đối T theo hệ thức:","opts":["Ed = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · k · T (với k là hằng số Boltzmann).","Ed = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · k · T.","Ed = 3 · k · T.","Ed = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · R · T."],"ans":0,"exp":"• <b>Mối quan hệ giữa động năng và nhiệt độ:</b> <span class=\"math-sym\">E</span><sub>d</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span><span class=\"math-sym\">kT</span>.<br>• Trong đó <span class=\"math-sym\">k ≈ 1,38 · 10⁻²³</span> J/K là hằng số Boltzmann.","svgGraph":null},{"q":"Hằng số Boltzmann k liên hệ với hằng số khí lí tưởng R và số Avogadro NA theo biểu thức nào?","opts":["k = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">N<sub>A</sub></span></span>.","k = R · N<sub>A</sub>.","k = <span class=\"fraction\"><span class=\"numerator\">N<sub>A</sub></span><span class=\"denominator\">R</span></span>.","k = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">2N<sub>A</sub></span></span>."],"ans":0,"exp":"• <b>Định nghĩa hằng số Boltzmann:</b> <span class=\"math-sym\">k</span> = <span class=\"fraction\"><span class=\"numerator\">R</span><span class=\"denominator\">N<sub>A</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">8,31</span><span class=\"denominator\">6,022 · 10²³</span></span> ≈ 1,38 · 10⁻²³ J/K.","svgGraph":null},{"q":"Khi xem xét về động năng phân tử và tốc độ chuyển động nhiệt của phân tử khí, mỗi nhận định sau là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Ở cùng một nhiệt độ, phân tử khí có khối lượng mol lớn hơn sẽ có tốc độ căn quân phương lớn hơn.","Động năng tịnh tiến trung bình của các phân tử chỉ phụ thuộc vào nhiệt độ tuyệt đối T, không phụ thuộc vào bản chất chất khí.","Khi nhiệt độ tuyệt đối của khối khí tăng lên gấp 4 lần thì tốc độ căn quân phương của phân tử tăng gấp 2 lần.","Tại nhiệt độ phòng (khoảng 300 K), tốc độ chuyển động nhiệt của phân tử không khí có độ lớn khoảng vài trăm mét trên giây."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> <span class=\"math-sym\">E</span><sub>d</sub> = 1,5<span class=\"math-sym\">kT</span> chỉ phụ thuộc nhiệt độ <span class=\"math-sym\">T</span>.<br>• <b>Ý b: SAI.</b> Vì <span class=\"math-sym\">v</span><sub>cqp</sub> = <span class=\"fraction\"><span class=\"numerator\">3RT</span><span class=\"denominator\">M</span></span><sup><span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span></sup>, khối lượng mol <span class=\"math-sym\">M</span> càng lớn thì tốc độ càng <b>nhỏ</b>.<br>• <b>Ý c: ĐÚNG.</b> Tốc độ tỉ lệ với căn bậc hai của nhiệt độ tuyệt đối: <span class=\"math-sym\">v ∝ √T</span>. Khi T tăng 4 lần thì v tăng √4 = 2 lần.<br>• <b>Ý d: ĐÚNG.</b> Tốc độ căn quân phương của khí N₂ ở 300 K cỡ 500 m/s.","svgGraph":null},{"q":"Hãy ghép các đại lượng vật lí ở Cột A với biểu thức tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Động năng tịnh tiến trung bình Ed ➔ √(<span class=\"fraction\"><span class=\"numerator\">3RT</span><span class=\"denominator\">M</span></span>) hay √(<span class=\"fraction\"><span class=\"numerator\">3kT</span><span class=\"denominator\">m</span></span>)","Động năng tịnh tiến trung bình Ed ➔ <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · k · T","Tốc độ căn quân phương vcqp ➔ √(<span class=\"fraction\"><span class=\"numerator\">3RT</span><span class=\"denominator\">M</span></span>) hay √(<span class=\"fraction\"><span class=\"numerator\">3kT</span><span class=\"denominator\">m</span></span>)","Áp suất khí p theo mật độ n₀ ➔ <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · k · T"],"ans":0,"exp":"• 1 ghép với B (Động năng phân tử).<br>• 2 ghép với A (Tốc độ căn quân phương).<br>• 3 ghép với D (Áp suất theo động năng).<br>• 4 ghép với C (Hằng số Boltzmann).","svgGraph":null},{"q":"Dựa vào mô hình động học phân tử chất khí, hãy giải thích tại sao khi giữ thể tích bình chứa không đổi, nếu ta tăng nhiệt độ của khối khí thì áp suất khí tác dụng lên thành bình lại tăng lên?","opts":["Nhiệt độ tăng làm tốc độ và động năng phân tử tăng, phân tử va chạm vào thành bình thường xuyên hơn và mạnh hơn.","Nhiệt độ tăng làm số lượng phân tử khí bên trong bình tự sinh thêm nhiều hơn làm tăng mật độ.","Nhiệt độ tăng làm kích thước của từng phân tử khí nở to ra chiếm nhiều không gian thể tích hơn.","Nhiệt độ tăng làm lực hút tĩnh điện giữa phân tử khí với thành bình tăng lên đột ngột."],"ans":0,"exp":"• <b>Giải thích vi mô về áp suất:</b> Áp suất chất khí tác dụng lên thành bình là kết quả của vô số va chạm của các phân tử khí vào thành bình trong mỗi giây.<br>• Khi nhiệt độ tăng, các phân tử chuyển động nhanh hơn, va chạm vào thành bình thường xuyên hơn và mạnh hơn làm tăng áp suất.<br>• Công thức p = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span> · n₀ · m · v² cho thấy áp suất tỉ lệ với mật độ phân tử n₀ và động năng trung bình của phân tử.","svgGraph":null},{"q":"Động năng tịnh tiến trung bình của một phân tử khí ở nhiệt độ 27°C xấp xỉ bằng bao nhiêu? Lấy k = 1,38 · 10⁻²³ J/K.","opts":["6,21 · 10⁻²¹ J.","4,14 · 10⁻²¹ J.","8,28 · 10⁻²¹ J.","5,58 · 10⁻²¹ J."],"ans":0,"exp":"• <span class=\"math-sym\">T</span> = 27 + 273 = 300 K.<br>• <span class=\"math-sym\">E</span><sub>d</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span><span class=\"math-sym\">kT</span> = 1,5 × 1,38 · 10⁻²³ × 300 = <b>6,21 · 10⁻²¹ J</b>.","svgGraph":null},{"q":"Bầu khí quyển Trái Đất giữ lại được các khí như oxygen (O₂) và nitrogen (N₂), nhưng hầu như không giữ được các khí nhẹ như hydrogen (H₂) và helium (He). Nguyên nhân vật lí cơ bản là do:","opts":["Ở cùng nhiệt độ, phân tử H₂ và He có khối lượng nhỏ nên tốc độ căn quân phương rất lớn, dễ vượt tốc độ vũ trụ cấp I để thoát ly.","Khí H₂ và He bị từ trường Trái Đất tạo lực từ đẩy ngược ra ngoài không gian liên hành tinh.","Tầng ôzôn phản xạ hoàn toàn và chỉ cho phép khí nặng đi qua vào khí quyển.","Lực hấp dẫn của Trái Đất chỉ tác dụng lên các chất khí có khối lượng phân tử lớn hơn 20 g/mol."],"ans":0,"exp":"• <b>Tốc độ căn quân phương:</b> v<sub>rms</sub> = √(<span class=\"fraction\"><span class=\"numerator\">3RT</span><span class=\"denominator\">M</span></span>). Phân tử khí hydro (H₂, khối lượng mol M = 2 g/mol) có khối lượng phân tử nhẹ hơn rất nhiều so với oxy (O₂, M = 32 g/mol) và nitơ (N₂, M = 28 g/mol).<br>• Ở cùng nhiệt độ, tốc độ chuyển động nhiệt của phân tử hydro rất lớn (cỡ 1,9 km/s), lớn hơn tốc độ thoát ly của Trái Đất đối với các phân tử ở tầng cao khí quyển. Trải qua hàng tỉ năm, hầu hết các phân tử hydro nhẹ đã bay thoát khỏi trường hấp dẫn của Trái Đất vào không gian vũ trụ.","svgGraph":null},{"q":"Quan sát đường cong phân bố tốc độ phân tử Maxwell - Boltzmann ở hai nhiệt độ T₁ và T₂ như đồ thị hình bên. Nhận định nào sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Ở nhiệt độ cao hơn T₂, số lượng phân tử có tốc độ rất nhỏ lại chiếm tỉ lệ áp đảo.","Nhiệt độ tuyệt đối T₂ lớn hơn nhiệt độ tuyệt đối T₁ (T₂ > T₁).","Tốc độ có xác suất lớn nhất ở nhiệt độ T₂ lớn hơn so với ở nhiệt độ T₁ (v₂ > v₁).","Diện tích giới hạn bởi mỗi đường cong phân bố và trục hoành là bằng nhau (đều bằng 1)."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Đỉnh của T₂ dịch sang phải ⇒ nhiệt độ T₂ cao hơn.<br>• <b>Ý b: ĐÚNG.</b> Tọa độ đỉnh tương ứng tốc độ xác suất lớn nhất tăng từ <span class=\"math-sym\">v</span><sub>1</sub> lên <span class=\"math-sym\">v</span><sub>2</sub>.<br>• <b>Ý c: ĐÚNG.</b> Tổng xác suất trên toàn dải tốc độ luôn bằng 100% (tích phân bằng 1).<br>• <b>Ý d: SAI.</b> Khi nhiệt độ cao, phân tử chuyển dịch sang dải tốc độ cao, số phân tử tốc độ chậm giảm đi.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr12\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐƯỜNG CONG PHÂN BỐ TỐC ĐỘ MAXWELL - BOLTZMANN</text>\n  \n  <line x1=\"50\" y1=\"230\" x2=\"490\" y2=\"230\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr12)\"/>\n  <line x1=\"50\" y1=\"230\" x2=\"50\" y2=\"35\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr12)\"/>\n  <text x=\"475\" y=\"250\" fill=\"#94a3b8\" font-size=\"13\">Tốc độ v (m/s)</text>\n  <text x=\"20\" y=\"45\" fill=\"#94a3b8\" font-size=\"13\">f(v)</text>\n  <text x=\"35\" y=\"245\" fill=\"#94a3b8\" font-size=\"12\">O</text>\n\n  <!-- Đường T1: thấp hơn về tốc độ, đỉnh cao hơn -->\n  <path d=\"M 50,230 C 80,180 120,60 160,60 C 200,60 250,190 340,225 C 380,228 440,230 470,230\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3\"/>\n  \n  <!-- Đường T2 -->\n  <path d=\"M 50,230 C 90,210 160,110 230,110 C 300,110 360,170 420,215 C 450,225 470,230 480,230\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n\n  <!-- Điểm đỉnh T1 -->\n  <line x1=\"160\" y1=\"60\" x2=\"160\" y2=\"230\" stroke=\"#06b6d4\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n  <circle cx=\"160\" cy=\"60\" r=\"5\" fill=\"#06b6d4\"/>\n  <text x=\"160\" y=\"50\" fill=\"#06b6d4\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Đỉnh T₁ (v xác suất lớn nhất)</text>\n  <text x=\"150\" y=\"248\" fill=\"#06b6d4\" font-size=\"12\" font-weight=\"bold\">v₁</text>\n\n  <!-- Điểm đỉnh T2 -->\n  <line x1=\"230\" y1=\"110\" x2=\"230\" y2=\"230\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n  <circle cx=\"230\" cy=\"110\" r=\"5\" fill=\"#f43f5e\"/>\n  <text x=\"250\" y=\"100\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Đỉnh T₂</text>\n  <text x=\"225\" y=\"248\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">v₂</text>\n\n  <!-- Chú thích -->\n  <rect x=\"330\" y=\"45\" width=\"180\" height=\"60\" rx=\"8\" fill=\"rgba(30,41,59,0.8)\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <text x=\"340\" y=\"65\" fill=\"#06b6d4\" font-size=\"11\" font-weight=\"bold\">— Ở T₁: Nhiệt độ thấp</text>\n  <text x=\"340\" y=\"85\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">— Ở T₂: Đỉnh dịch sang phải</text>\n</svg>"},{"q":"Theo mô hình động học phân tử chất khí và nhiệt động lực học cổ điển, 'Độ không tuyệt đối' (0 K, ứng với -273,15°C) có ý nghĩa vật lí sâu sắc là gì?","opts":["Nhiệt độ lí thuyết mà tại đó động năng tịnh tiến trung bình của các phân tử khí bằng 0, mọi chuyển động nhiệt đều ngừng lại.","Nhiệt độ mà tại đó tất cả các chất khí thực đều chuyển thành chất khí lí tưởng hoàn hảo.","Nhiệt độ mà tại đó khối lượng của chất khí tăng lên đến giá trị vô cùng lớn.","Nhiệt độ mà tại đó nước tinh khiết bắt đầu đóng băng ở áp suất tiêu chuẩn 1 atm."],"ans":0,"exp":"• <b>Ý nghĩa của 0 K:</b> Từ công thức E<sub>d</sub> = <span class=\"fraction\"><span class=\"numerator\">3</span><span class=\"denominator\">2</span></span> · k · T, khi nhiệt độ tuyệt đối T → 0 K, động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử tiệm cận tới 0. Khi đó, về mặt lí thuyết cổ điển, mọi chuyển động nhiệt của phân tử đều dừng lại.<br>• Theo nguyên lí thứ ba của nhiệt động lực học (Định luật Nernst), không thể bằng bất kì quá trình hữu hạn nào làm hạ nhiệt độ của một hệ vật chất xuống đúng 0 K (Độ không tuyệt đối chỉ là giới hạn lí thuyết).","svgGraph":null}],"13":[{"q":"Trong một chu trình biến đổi khép kín (chu trình kín) của chất khí lí tưởng, sau khi đi hết một vòng kín và trở về trạng thái ban đầu thì biến thiên nội năng ΔU của khối khí bằng:","opts":["Bằng 0.","Luôn có giá trị dương.","Luôn có giá trị âm.","Bằng tổng công sinh ra trong chu trình."],"ans":0,"exp":"• <b>Nội năng là hàm của trạng thái:</b> Vì trạng thái cuối trùng với trạng thái đầu (<span class=\"math-sym\">T</span><sub>cuối</sub> = <span class=\"math-sym\">T</span><sub>đầu</sub>) nên biến thiên nội năng: <b>ΔU = 0</b>.","svgGraph":null},{"q":"Theo ý nghĩa hình học, công toàn phần A' mà khối khí sinh ra trong một chu trình kín thuận chiều kim đồng hồ trên hệ tọa độ (p, V) được xác định bằng:","opts":["Diện tích của hình phẳng được bao quanh bởi chu trình đó trên giản đồ (p, V).","Chu vi của đường cong chu trình kín.","Độ dài trục hoành của chu trình.","Tích của áp suất lớn nhất và thể tích lớn nhất của chu trình."],"ans":0,"exp":"• <b>Ý nghĩa hình học của công:</b> Công <span class=\"math-sym\">A'</span> mà khí sinh ra trong chu trình bằng diện tích hình giới hạn bởi chu trình trên giản đồ <span class=\"math-sym\">(p, V)</span>.","svgGraph":null},{"q":"Hai bình kín dung tích V₁ = 2,0 lít và V₂ = 3,0 lít chứa cùng một loại khí ở cùng nhiệt độ, áp suất ban đầu lần lượt là p₁ = 1,0 atm và p₂ = 2,0 atm. Nối hai bình bằng một ống nhỏ có khóa, mở khóa để hai bình thông nhau và giữ nhiệt độ không đổi. Áp suất của hỗn hợp khí khi cân bằng là:","opts":["1,6 atm.","1,5 atm.","1,8 atm.","1,4 atm."],"ans":0,"exp":"• Bảo toàn số mol khí (nhiệt độ T không đổi): <span class=\"math-sym\">pV</span><sub>chung</sub> = <span class=\"math-sym\">p</span><sub>1</sub><span class=\"math-sym\">V</span><sub>1</sub> + <span class=\"math-sym\">p</span><sub>2</sub><span class=\"math-sym\">V</span><sub>2</sub>.<br>• <span class=\"math-sym\">p</span> = <span class=\"fraction\"><span class=\"numerator\">p₁V₁ + p₂V₂</span><span class=\"denominator\">V₁ + V₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">1,0 × 2,0 + 2,0 × 3,0</span><span class=\"denominator\">2,0 + 3,0</span></span> = <span class=\"fraction\"><span class=\"numerator\">8,0</span><span class=\"denominator\">5,0</span></span> = <b>1,6 atm</b>.","svgGraph":null},{"q":"Xét các đặc tính nhiệt động lực học của chu trình chất khí khép kín. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hiệu suất cực đại của một động cơ nhiệt hoạt động theo chu trình Carnot chỉ phụ thuộc vào bản chất của chất khí sử dụng làm tác nhân.","Trong toàn bộ một chu trình kín, nhiệt lượng Q mà chất khí nhận được bằng công A' mà chất khí sinh ra (Q = A').","Nếu chu trình biến đổi theo chiều thuận chiều kim đồng hồ trên hệ (p, V) thì công sinh ra A' > 0 (chu trình động cơ nhiệt).","Nếu chu trình biến đổi theo chiều ngược chiều kim đồng hồ trên hệ (p, V) thì công nhận vào A > 0 (chu trình máy làm lạnh)."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Vì <span class=\"math-sym\">ΔU = 0 ⇒ Q + A = 0 ⇒ Q = -A = A'</span>.<br>• <b>Ý b: ĐÚNG.</b> Công dãn nở ở áp suất cao lớn hơn công nén ở áp suất thấp nên <span class=\"math-sym\">A' > 0</span>.<br>• <b>Ý c: ĐÚNG.</b> Chu trình ngược chiều kim đồng hồ tiêu tốn công cơ học để bơm nhiệt.<br>• <b>Ý d: SAI.</b> Hiệu suất Carnot <span class=\"math-sym\">η = 1 - T₂/T₁</span> chỉ phụ thuộc nhiệt độ nguồn nóng <span class=\"math-sym\">T₁</span> và nguồn lạnh <span class=\"math-sym\">T₂</span>, không phụ thuộc vào chất khí.","svgGraph":null},{"q":"Hãy ghép các biểu thức tính toán nhiệt động lực học ở Cột A với nội hàm tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["A' = p · ΔV ➔ Nhiệt lượng nhận bằng công sinh ra trong toàn bộ chu trình kín.","A' = p · ΔV ➔ Áp suất cân bằng của hệ hai bình khí thông nhau ở cùng nhiệt độ.","ΔU = 0 ➔ Nhiệt lượng nhận bằng công sinh ra trong toàn bộ chu trình kín.","p = <span class=\"fraction\"><span class=\"numerator\">p₁V₁ + p₂V₂</span><span class=\"denominator\">V₁ + V₂</span></span> ➔ Áp suất cân bằng của hệ hai bình khí thông nhau ở cùng nhiệt độ."],"ans":0,"exp":"• 1 ghép với C (Công đẳng áp).<br>• 2 ghép với D (Biến thiên nội năng chu trình kín).<br>• 3 ghép với B (Áp suất bình thông nhau).<br>• 4 ghép với A (Cân bằng năng lượng chu trình kín).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong quá trình dãn nở, chất khí [0] công cho môi trường ngoài. Ngược lại, khi bị nén ép bởi ngoại lực, chất khí [1] công từ môi trường. Trong một chu trình kín sinh công hữu ích (động cơ nhiệt), công sinh ra trong giai đoạn dãn nở phải [2] công tiêu tốn trong giai đoạn nén lại.\"</i>","opts":["sinh ra — nhận","không đổi","nhỏ hơn — tiêu tán","nhận — sinh ra"],"ans":0,"exp":"• Khí nở ra: <b>sinh công</b>. Khí bị nén: <b>nhận công</b>. Để có công có ích <span class=\"math-sym\">A' > 0</span> thì công sinh ra phải <b>lớn hơn</b> công nhận vào.","svgGraph":null},{"q":"Một quả bóng thám không đo khí tượng chứa khí heli được thả từ mặt đất (p₁ = 1,0 atm, T₁ = 300 K) bay lên cao vào tầng bình lưu. Khi lên tới độ cao trên 30 km, quả bóng bị nổ tung. Nguyên nhân chính là do:","opts":["Càng lên cao áp suất khí quyển ngoài càng giảm mạnh, làm thể tích quả bóng dãn nở vượt giới hạn đàn hồi của vỏ bóng.","Càng lên cao nhiệt độ khí quyển tăng lên hàng nghìn độ C làm khí heli bên trong bốc cháy.","Gió trên tầng cao thổi với vận tốc siêu thanh cọ xát làm rách thủng màng cao su của vỏ bóng.","Lực hấp dẫn của Trái Đất ở độ cao 30 km triệt tiêu hoàn toàn làm vỏ bóng tự phát nổ."],"ans":0,"exp":"• <b>Giải thích theo Phương trình trạng thái:</b> Áp dụng <span class=\"fraction\"><span class=\"numerator\">p₁ · V₁</span><span class=\"denominator\">T₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">p₂ · V₂</span><span class=\"denominator\">T₂</span></span>. Thể tích lốp xe coi như gần như không đổi (V ≈ const).<br>• Khi xe chạy đường dài với tốc độ cao, ma sát giữa lốp xe với mặt đường và lực cản sinh nhiệt lớn làm nhiệt độ không khí trong lốp tăng vọt (T tăng). Do thể tích không đổi, áp suất khí nén trong lốp tăng tỉ lệ thuận với nhiệt độ (p tăng). Nếu lốp đã cũ hoặc bị bơm quá căng từ trước, áp suất vượt quá giới hạn chịu lực của vỏ lốp sẽ dẫn tới nổ lốp rất nguy hiểm.","svgGraph":null},{"q":"Người ta dùng bơm tay có thể tích mỗi lần bơm là 100 cm³ để bơm không khí ở áp suất khí quyển 1,0 · 10⁵ Pa vào một quả bóng rổ có thể tích 2,5 lít (coi không đổi). Trước khi bơm, bóng chứa không khí ở áp suất khí quyển. Bỏ qua ma sát và coi nhiệt độ không đổi. Để áp suất khí trong bóng đạt 2,4 · 10⁵ Pa thì số lần bơm tối thiểu là:","opts":["35 lần.","25 lần.","30 lần.","40 lần."],"ans":0,"exp":"• Thể tích khí ban đầu: <span class=\"math-sym\">V</span><sub>1</sub> = <span class=\"math-sym\">V</span><sub>bóng</sub> + <span class=\"math-sym\">n · V</span><sub>bơm</sub> = 2500 + <span class=\"math-sym\">n</span> × 100 (cm³), ở áp suất <span class=\"math-sym\">p</span><sub>1</sub> = 1,0 · 10⁵ Pa.<br>• Sau khi bơm: khí chứa trong bóng thể tích <span class=\"math-sym\">V</span><sub>2</sub> = 2500 cm³ ở áp suất <span class=\"math-sym\">p</span><sub>2</sub> = 2,4 · 10⁵ Pa.<br>• Định luật Boyle: <span class=\"math-sym\">p</span><sub>1</sub><span class=\"math-sym\">V</span><sub>1</sub> = <span class=\"math-sym\">p</span><sub>2</sub><span class=\"math-sym\">V</span><sub>2</sub> ⇒ 1,0 × (2500 + 100<span class=\"math-sym\">n</span>) = 2,4 × 2500 = 6000.<br>• 100<span class=\"math-sym\">n</span> = 3500 ⇒ <span class=\"math-sym\">n</span> = <b>35 lần</b>.","svgGraph":null},{"q":"Xét chu trình biến đổi chữ nhật (1)-(2)-(3)-(4)-(1) của một khối khí lí tưởng trên giản đồ (p, V) như hình vẽ. Cho 1 bar = 10⁵ Pa và 1 lít = 10⁻³ m³. Đánh giá tính Đúng/Sai của các mệnh đề sau:<br>Xác định tính Đúng/Sai của nhận định: <i>\"Quá trình (1) → (2) là quá trình dãn nở đẳng áp ở áp suất 3,0 bar.\"</i>","opts":["Đúng.","Sai.","Chỉ đúng trong một số trường hợp đặc biệt.","Chưa đủ dữ kiện để kết luận."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Đoạn (1)-(2) nằm ngang ở mức <span class=\"math-sym\">p</span> = 3,0 bar và thể tích tăng từ 2,0 lít lên 6,0 lít.<br>• <b>Ý b: ĐÚNG.</b> Nhiệt độ <span class=\"math-sym\">T ∝ p · V</span>. Tích <span class=\"math-sym\">p · V</span> lớn nhất tại điểm (2): <span class=\"math-sym\">p · V</span> = 3,0 × 6,0 = 18 bar·L.<br>• <b>Ý c: ĐÚNG.</b> Công bằng diện tích hình chữ nhật: <span class=\"math-sym\">A'</span> = Δ<span class=\"math-sym\">p</span> × Δ<span class=\"math-sym\">V</span> = (3,0 - 1,0) · 10⁵ Pa × (6,0 - 2,0) · 10⁻³ m³ = 2 · 10⁵ × 4 · 10⁻³ = <b>800 J</b>.<br>• <b>Ý d: ĐÚNG.</b> Cùng thể tích 2,0 lít, áp suất tại (4) là 1,0 bar nhỏ hơn áp suất tại (1) là 3,0 bar nên <span class=\"math-sym\">T</span><sub>4</sub> < <span class=\"math-sym\">T</span><sub>1</sub>.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr13\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\"/>\n    </marker>\n    <marker id=\"arrLoop\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#10b981\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">CHU TRÌNH NHIỆT KHÉP KÍN TRÊN GIẢN ĐỒ (p - V)</text>\n\n  <!-- Hệ trục p - V -->\n  <line x1=\"60\" y1=\"230\" x2=\"490\" y2=\"230\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr13)\"/>\n  <line x1=\"60\" y1=\"230\" x2=\"60\" y2=\"35\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr13)\"/>\n  <text x=\"475\" y=\"250\" fill=\"#94a3b8\" font-size=\"13\">V (lít)</text>\n  <text x=\"30\" y=\"45\" fill=\"#94a3b8\" font-size=\"13\">p (bar)</text>\n  <text x=\"45\" y=\"245\" fill=\"#94a3b8\" font-size=\"12\">O</text>\n\n  <!-- Chu trình chữ nhật: 1(V1=140, p2=70) -> 2(V2=360, p2=70) -> 3(V2=360, p1=170) -> 4(V1=140, p1=170) -> 1 -->\n  <!-- Vùng diện tích công A' -->\n  <polygon points=\"140,70 360,70 360,170 140,170\" fill=\"rgba(16,185,129,0.18)\" stroke=\"none\"/>\n\n  <!-- Các cạnh chu trình -->\n  <!-- 1 -> 2: dãn nở đẳng áp p2 -->\n  <line x1=\"140\" y1=\"70\" x2=\"360\" y2=\"70\" stroke=\"#10b981\" stroke-width=\"3\"/>\n  <line x1=\"240\" y1=\"70\" x2=\"255\" y2=\"70\" stroke=\"#10b981\" stroke-width=\"3\" marker-end=\"url(#arrLoop)\"/>\n\n  <!-- 2 -> 3: giảm áp đẳng tích V2 -->\n  <line x1=\"360\" y1=\"70\" x2=\"360\" y2=\"170\" stroke=\"#10b981\" stroke-width=\"3\"/>\n  <line x1=\"360\" y1=\"110\" x2=\"360\" y2=\"125\" stroke=\"#10b981\" stroke-width=\"3\" marker-end=\"url(#arrLoop)\"/>\n\n  <!-- 3 -> 4: nén đẳng áp p1 -->\n  <line x1=\"360\" y1=\"170\" x2=\"140\" y2=\"170\" stroke=\"#10b981\" stroke-width=\"3\"/>\n  <line x1=\"260\" y1=\"170\" x2=\"245\" y2=\"170\" stroke=\"#10b981\" stroke-width=\"3\" marker-end=\"url(#arrLoop)\"/>\n\n  <!-- 4 -> 1: tăng áp đẳng tích V1 -->\n  <line x1=\"140\" y1=\"170\" x2=\"140\" y2=\"70\" stroke=\"#10b981\" stroke-width=\"3\"/>\n  <line x1=\"140\" y1=\"130\" x2=\"140\" y2=\"115\" stroke=\"#10b981\" stroke-width=\"3\" marker-end=\"url(#arrLoop)\"/>\n\n  <!-- Gióng tọa độ -->\n  <line x1=\"60\" y1=\"70\" x2=\"140\" y2=\"70\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"60\" y1=\"170\" x2=\"140\" y2=\"170\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"140\" y1=\"230\" x2=\"140\" y2=\"170\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"360\" y1=\"230\" x2=\"360\" y2=\"170\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n\n  <!-- Giá trị trục số -->\n  <text x=\"35\" y=\"75\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">3,0</text>\n  <text x=\"35\" y=\"175\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">1,0</text>\n  <text x=\"135\" y=\"248\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">2,0</text>\n  <text x=\"355\" y=\"248\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\">6,0</text>\n\n  <!-- Đỉnh -->\n  <circle cx=\"140\" cy=\"70\" r=\"5\" fill=\"#f59e0b\"/>\n  <text x=\"125\" y=\"60\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"bold\">(1)</text>\n\n  <circle cx=\"360\" cy=\"70\" r=\"5\" fill=\"#f59e0b\"/>\n  <text x=\"368\" y=\"60\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"bold\">(2)</text>\n\n  <circle cx=\"360\" cy=\"170\" r=\"5\" fill=\"#f59e0b\"/>\n  <text x=\"368\" y=\"185\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"bold\">(3)</text>\n\n  <circle cx=\"140\" cy=\"170\" r=\"5\" fill=\"#f59e0b\"/>\n  <text x=\"125\" y=\"185\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"bold\">(4)</text>\n\n  <!-- Chữ công A' -->\n  <text x=\"250\" y=\"125\" fill=\"#10b981\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">Công A' = S(1234)</text>\n</svg>"},{"q":"Một xilanh nằm ngang kín hai đầu, bên trong có một pit-tông cách nhiệt chia xilanh thành hai ngăn bằng nhau, mỗi ngăn có thể tích 3,0 lít chứa khí ở áp suất 1,0 atm và 27°C. Đun nóng một ngăn lên đến 127°C và giữ nguyên ngăn kia ở 27°C. Pit-tông dịch chuyển sang phía ngăn lạnh cho đến khi áp suất hai bên bằng nhau. Thể tích ngăn nóng lúc này là:","opts":["3,43 lít.","3,60 lít.","3,25 lít.","3,75 lít."],"ans":0,"exp":"• Tổng thể tích hai ngăn không đổi: <span class=\"math-sym\">V</span><sub>nóng</sub> + <span class=\"math-sym\">V</span><sub>lạnh</sub> = 6,0 lít.<br>• Khi cân bằng: áp suất hai ngăn bằng nhau <span class=\"math-sym\">p</span><sub>nóng</sub> = <span class=\"math-sym\">p</span><sub>lạnh</sub>.<br>• Số mol mỗi ngăn không đổi: <span class=\"math-sym\">n</span><sub>1</sub> = <span class=\"math-sym\">n</span><sub>2</sub> ⇒ <span class=\"fraction\"><span class=\"numerator\">V<sub>n</sub>óng</span><span class=\"denominator\">T<sub>n</sub>óng</span></span> = <span class=\"fraction\"><span class=\"numerator\">V<sub>l</sub>ạnh</span><span class=\"denominator\">T<sub>l</sub>ạnh</span></span>.<br>• <span class=\"fraction\"><span class=\"numerator\">V<sub>n</sub>óng</span><span class=\"denominator\">400</span></span> = <span class=\"fraction\"><span class=\"numerator\">6,0 - V<sub>n</sub>óng</span><span class=\"denominator\">300</span></span> ⇒ 3<span class=\"math-sym\">V</span><sub>nóng</sub> = 24 - 4<span class=\"math-sym\">V</span><sub>nóng</sub> ⇒ 7<span class=\"math-sym\">V</span><sub>nóng</sub> = 24 ⇒ <span class=\"math-sym\">V</span><sub>nóng</sub> ≈ <b>3,43 lít</b>.","svgGraph":null}],"14":[{"q":"Từ trường là một dạng vật chất đặc biệt tồn tại trong không gian xung quanh:","opts":["Nam châm, các hạt mang điện chuyển động hoặc dòng điện.","Chỉ xung quanh các điện tích đứng yên.","Chỉ xung quanh các khối kim loại có nhiệt độ rất cao.","Chỉ xung quanh lõi sắt non được nối đất."],"ans":0,"exp":"• <b>Bản chất từ trường:</b> Từ trường là môi trường vật chất tồn tại xung quanh nam châm, xung quanh dòng điện (các điện tích chuyển động) và tác dụng lực từ lên các nam châm hoặc dòng điện khác đặt trong nó.","svgGraph":null},{"q":"Quy ước về chiều của đường sức từ ở bên ngoài thanh nam châm thẳng là:","opts":["Đi ra từ cực Bắc (N) và đi vào cực Nam (S).","Đi ra từ cực Nam (S) và đi vào cực Bắc (N).","Đồng quy về tâm của thanh nam châm.","Phát xuất từ cả hai cực và phân kì ra vô cực."],"ans":0,"exp":"• <b>Quy ước chiều đường sức từ:</b> Ở bên ngoài nam châm, đường sức từ đi ra từ cực Bắc (North) và đi vào cực Nam (South) (khẩu quyết: <i>Ra Bắc vào Nam</i>).","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Bar magnet in center -->\n  <rect x=\"170\" y=\"85\" width=\"60\" height=\"40\" fill=\"#ef4444\" stroke=\"#f87171\" stroke-width=\"1.5\" rx=\"4\"/>\n  <text x=\"200\" y=\"110\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"16\" font-weight=\"800\">N</text>\n  <rect x=\"230\" y=\"85\" width=\"60\" height=\"40\" fill=\"#3b82f6\" stroke=\"#60a5fa\" stroke-width=\"1.5\" rx=\"4\"/>\n  <text x=\"260\" y=\"110\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"16\" font-weight=\"800\">S</text>\n  <!-- Field lines loops -->\n  <!-- Outer top -->\n  <path d=\"M 190,85 C 190,15 270,15 270,85\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"5,2\"/>\n  <polygon points=\"230,23 238,20 238,26\" fill=\"#38bdf8\"/>\n  <!-- Middle top -->\n  <path d=\"M 200,85 C 200,45 260,45 260,85\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"230,48 238,45 238,51\" fill=\"#38bdf8\"/>\n  <!-- Outer bottom -->\n  <path d=\"M 190,125 C 190,195 270,195 270,125\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"5,2\"/>\n  <polygon points=\"230,187 238,184 238,190\" fill=\"#38bdf8\"/>\n  <!-- Middle bottom -->\n  <path d=\"M 200,125 C 200,165 260,165 260,125\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"230,162 238,159 238,165\" fill=\"#38bdf8\"/>\n  <!-- Out from N -->\n  <path d=\"M 170,105 L 80,105\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"110,105 118,101 118,109\" fill=\"#38bdf8\"/>\n  <!-- Into S -->\n  <path d=\"M 290,105 L 380,105\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <polygon points=\"350,105 342,101 342,109\" fill=\"#38bdf8\"/>\n  <!-- Rule caption -->\n  <text x=\"230\" y=\"202\" fill=\"#34d399\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">Quy ước: Vào cực Nam (S) - Ra cực Bắc (N)</text>\n</svg>"},{"q":"Đặc điểm nào sau đây là <b>đặc trưng phân biệt cơ bản</b> giữa đường sức từ của từ trường và đường sức điện của điện trường tĩnh?","opts":["Đường sức từ luôn là những đường cong khép kín hoặc vô hạn ở hai đầu.","Đường sức từ luôn xuất phát từ điện tích dương và kết thúc ở điện tích âm.","Các đường sức từ có thể cắt nhau tại những điểm có từ trường rất mạnh.","Nơi nào từ trường càng mạnh thì các đường sức từ vẽ càng thưa."],"ans":0,"exp":"• <b>Tính chất xoáy của từ trường:</b> Đường sức từ là những <b>đường cong khép kín</b> (từ trường là trường xoáy, không có điện tích từ riêng rẽ), khác với điện trường tĩnh có đường sức xuất phát từ điện tích dương và kết thúc ở điện tích âm.","svgGraph":null},{"q":"Xét về bản chất của từ trường và các đường sức từ, mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Kim la bàn luôn chỉ chính xác 100% về cực Bắc địa lí của Trái Đất ở mọi nơi.","Qua mỗi điểm trong không gian chỉ vẽ được duy nhất một đường sức từ.","Nơi nào từ trường mạnh hơn thì các đường sức từ ở đó được vẽ mau hơn (dày hơn).","Từ trường đều là từ trường mà vectơ cảm ứng từ có hướng và độ lớn như nhau tại mọi điểm."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Các đường sức từ không bao giờ cắt nhau.<br>• <b>Ý b: ĐÚNG.</b> Mật độ đường sức biểu diễn độ mạnh yếu của từ trường.<br>• <b>Ý c: ĐÚNG.</b> Định nghĩa từ trường đều (ví dụ trong lòng nam châm chữ U hoặc trong ống dây dài mang dòng điện).<br>• <b>Ý d: SAI.</b> Trục từ trường Trái Đất lệch một góc so với trục quay địa lí (góc từ thiên), cực Bắc từ của Trái Đất thực chất nằm gần cực Nam địa lí.","svgGraph":null},{"q":"Hãy ghép nguồn sinh ra từ trường ở Cột A với dạng hình học đặc trưng của đường sức từ ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Dòng điện thẳng dài vô hạn ➔ Gần như là các đường thẳng song song cách đều nhau (từ trường đều).","Dòng điện thẳng dài vô hạn ➔ Các đường tròn đồng tâm nằm trên mặt phẳng vuông góc với dòng điện.","Trong lòng ống dây hình trụ dài mang dòng điện ➔ Gần như là các đường thẳng song song cách đều nhau (từ trường đều).","Dòng điện tròn ➔ Các đường tròn đồng tâm nằm trên mặt phẳng vuông góc với dòng điện."],"ans":0,"exp":"• 1 ghép với B (Dòng điện thẳng: đường tròn đồng tâm).<br>• 2 ghép với C (Trong lòng ống dây: từ trường đều dọc trục).<br>• 3 ghép với D (Dòng điện tròn: qua tâm là đường thẳng).<br>• 4 ghép với A (Giữa hai cực nam châm chữ U là từ trường đều).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trái Đất hoạt động như một thanh nam châm khổng lồ. Cực từ nằm ở bán cầu Bắc của Trái Đất thực chất có từ tính là [0], do đó nó [1] cực Bắc của kim la bàn chỉ về hướng Bắc địa lí. Vùng không gian xung quanh Trái Đất chịu tác dụng của từ trường này được gọi là [2], có vai trò chắn các hạt tích điện nguy hiểm từ gió Mặt Trời.\"</i>","opts":["cực Nam từ — hút","không đổi","đẩy — khí quyển","hút — cực Nam từ"],"ans":0,"exp":"• Vì hai cực khác tên hút nhau, cực Bắc của la bàn hướng về phía Bắc vì ở đó có <b>cực Nam từ</b> của Trái Đất. Vùng bao quanh gọi là <b>từ quyển</b>.","svgGraph":null},{"q":"Tương tác nào sau đây <b>không phải</b> là tương tác từ?","opts":["Tương tác hút nhau giữa hai quả cầu tích điện trái dấu đứng yên.","Tương tác giữa hai thanh nam châm đặt gần nhau.","Tương tác giữa một dây dẫn mang dòng điện và một kim nam châm.","Tương tác đẩy nhau giữa hai dòng điện thẳng song song ngược chiều."],"ans":0,"exp":"• Hai điện tích đứng yên tương tác với nhau bằng <b>lực tĩnh điện (lực Coulomb)</b>, không phải lực từ.","svgGraph":null},{"q":"Để phát hiện sự tồn tại của từ trường tại một vị trí trong phòng thí nghiệm, dụng cụ thực nghiệm đơn giản và hiệu quả nhất là dùng:","opts":["Một kim nam châm nhỏ có thể quay tự do quanh trục thẳng đứng (nam châm thử).","Một thanh kim loại bằng nhôm không nhiễm điện.","Một chiếc nhiệt kế rượu.","Một quả cầu tích điện đứng yên."],"ans":0,"exp":"• Nam châm thử sẽ bị lệch khỏi hướng Bắc - Nam địa lí khi đưa vào vùng có từ trường lạ.","svgGraph":null},{"q":"Quan sát hình vẽ mô tả phổ đường sức từ của thanh nam châm thẳng. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu bẻ đôi thanh nam châm này ra làm hai nửa thì ta sẽ thu được một nửa chỉ mang cực Bắc và một nửa chỉ mang cực Nam.","Ở bên ngoài thanh nam châm, đường sức từ đi ra từ cực N (màu đỏ) và đi vào cực S (màu xanh).","Kim nam châm thử đặt tại một điểm bất kì trên đường sức từ sẽ có trục định hướng tiếp tuyến với đường sức từ tại điểm đó.","Mật độ các đường sức từ ở gần hai cực của nam châm là dày nhất, chứng tỏ từ trường tại hai cực là mạnh nhất."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Quy ước ra Bắc (N) vào Nam (S).<br>• <b>Ý b: ĐÚNG.</b> Trục kim nam châm thử luôn trùng với tiếp tuyến đường sức từ.<br>• <b>Ý c: ĐÚNG.</b> Hai đầu cực là nơi tập trung từ trường mạnh nhất.<br>• <b>Ý d: SAI.</b> Không tồn tại đơn cực từ; khi bẻ đôi mỗi mẩu sẽ tự hình thành đủ hai cực Bắc - Nam mới.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrMag\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">PHỔ ĐƯỜNG SỨC TỪ CỦA THANH NAM CHÂM THẲNG</text>\n\n  <!-- Thanh nam châm thẳng ở giữa -->\n  <g transform=\"translate(180, 115)\">\n    <!-- Cực Nam (S) -->\n    <rect x=\"0\" y=\"0\" width=\"90\" height=\"50\" fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"1.5\" rx=\"4\"/>\n    <text x=\"45\" y=\"32\" fill=\"#ffffff\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\">S (Nam)</text>\n    <!-- Cực Bắc (N) -->\n    <rect x=\"90\" y=\"0\" width=\"90\" height=\"50\" fill=\"#dc2626\" stroke=\"#f87171\" stroke-width=\"1.5\" rx=\"4\"/>\n    <text x=\"135\" y=\"32\" fill=\"#ffffff\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\">N (Bắc)</text>\n  </g>\n\n  <!-- Đường sức từ vòng trên -->\n  <path d=\"M 360,130 C 460,70 440,35 270,35 C 100,35 80,70 180,130\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <path d=\"M 330,50 L 320,48\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrMag)\"/>\n  <path d=\"M 220,45 L 210,48\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrMag)\"/>\n\n  <path d=\"M 360,140 C 510,50 490,10 270,10 C 50,10 30,50 180,140\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"6,3\"/>\n\n  <!-- Đường sức từ vòng dưới -->\n  <path d=\"M 360,150 C 460,210 440,245 270,245 C 100,245 80,210 180,150\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <path d=\"M 320,232 L 330,230\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrMag)\"/>\n  <path d=\"M 210,232 L 220,230\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrMag)\"/>\n\n  <!-- Kim nam châm thử ở phía trên -->\n  <g transform=\"translate(250, 25)\">\n    <polygon points=\"0,10 20,5 40,10 20,15\" fill=\"#64748b\"/>\n    <polygon points=\"20,5 40,10 20,15\" fill=\"#dc2626\"/>\n    <polygon points=\"0,10 20,5 20,15\" fill=\"#0284c7\"/>\n    <circle cx=\"20\" cy=\"10\" r=\"2.5\" fill=\"#f8fafc\"/>\n  </g>\n  <text x=\"270\" y=\"65\" fill=\"#94a3b8\" font-size=\"11\" text-anchor=\"middle\">Kim nam châm thử định hướng theo tiếp tuyến đường sức</text>\n\n  <!-- Chú thích quy tắc -->\n  <text x=\"270\" y=\"270\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Quy tắc chiều đường sức từ: \"Ra Bắc (N) – Vào Nam (S)\"</text>\n</svg>"},{"q":"Hai dây dẫn thẳng song song mang dòng điện cùng chiều đặt gần nhau sẽ:","opts":["Hút nhau.","Đẩy nhau.","Không tương tác.","Vừa hút vừa đẩy tuần hoàn."],"ans":0,"exp":"• <b>Quy tắc tương tác dòng điện:</b> Hai dòng điện song song <b>cùng chiều thì hút nhau</b>, <b>ngược chiều thì đẩy nhau</b>.","svgGraph":null}],"15":[{"q":"Độ lớn của lực từ tác dụng lên một đoạn dây dẫn thẳng có chiều dài L mang dòng điện không đổi I đặt trong từ trường đều B được tính bằng công thức:","opts":["F = I · B · L · sinα (với α là góc giữa dây dẫn và vectơ B).","F = I · B · L · cosα.","F = <span class=\"fraction\"><span class=\"numerator\">I · B</span><span class=\"denominator\">L · sinα</span></span>.","F = <span class=\"fraction\"><span class=\"numerator\">B · L</span><span class=\"denominator\">I · cosα</span></span>."],"ans":0,"exp":"• <b>Định luật Ampère:</b> <span class=\"math-sym\">F = I · B · L · sin α</span>. Lực từ đạt cực đại khi dây dẫn vuông góc với đường sức từ (α = 90°).","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"handG\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\"><stop offset=\"0%\" stop-color=\"#4f46e5\"/><stop offset=\"100%\" stop-color=\"#06b6d4\"/></linearGradient>\n  </defs>\n  <!-- Vector F (Thumb, up) -->\n  <g transform=\"translate(180, 25)\">\n    <line x1=\"50\" y1=\"120\" x2=\"50\" y2=\"20\" stroke=\"#f43f5e\" stroke-width=\"4\"/>\n    <polygon points=\"50,10 42,28 58,28\" fill=\"#f43f5e\"/>\n    <text x=\"65\" y=\"25\" fill=\"#f43f5e\" font-size=\"16\" font-weight=\"800\">F (Lực từ)</text>\n    <!-- Vector I (4 fingers, right) -->\n    <line x1=\"50\" y1=\"120\" x2=\"160\" y2=\"120\" stroke=\"#10b981\" stroke-width=\"4\"/>\n    <polygon points=\"170,120 152,112 152,128\" fill=\"#10b981\"/>\n    <text x=\"175\" y=\"125\" fill=\"#10b981\" font-size=\"16\" font-weight=\"800\">I (Dòng điện)</text>\n    <!-- Vector B (Field into palm, perspective dots) -->\n    <circle cx=\"50\" cy=\"120\" r=\"10\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <line x1=\"43\" y1=\"113\" x2=\"57\" y2=\"127\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <line x1=\"57\" y1=\"113\" x2=\"43\" y2=\"127\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <text x=\"35\" y=\"150\" fill=\"#38bdf8\" font-size=\"15\" font-weight=\"800\">B (Cảm ứng từ đi vào lòng bàn tay ⊗)</text>\n  </g>\n  <rect x=\"25\" y=\"30\" width=\"135\" height=\"145\" rx=\"12\" fill=\"rgba(79,70,229,0.15)\" stroke=\"#818cf8\" stroke-width=\"1.5\"/>\n  <text x=\"92\" y=\"55\" fill=\"#818cf8\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">QUY TẮC</text>\n  <text x=\"92\" y=\"73\" fill=\"#818cf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">BÀN TAY TRÁI</text>\n  <text x=\"92\" y=\"105\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">• Lòng tay hứng B</text>\n  <text x=\"92\" y=\"125\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">• 4 ngón chỉ chiều I</text>\n  <text x=\"92\" y=\"145\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">• Ngón cái 90° chỉ F</text>\n</svg>"},{"q":"Đơn vị đo của cảm ứng từ B trong hệ đơn vị chuẩn SI là:","opts":["Tesla (T).","Weber (Wb).","Henry (H).","Volt (V)."],"ans":0,"exp":"• Đơn vị của cảm ứng từ là <b>Tesla (ký hiệu: T)</b>. 1 T = 1 N / (A·m).","svgGraph":null},{"q":"Một đoạn dây dẫn thẳng dài 0,2 m mang dòng điện 5,0 A đặt trong từ trường đều có cảm ứng từ B = 0,4 T. Dây dẫn vuông góc với các đường sức từ. Lực từ tác dụng lên đoạn dây dẫn có độ lớn là:","opts":["0,40 N.","0,20 N.","0,80 N.","0,04 N."],"ans":0,"exp":"• Vì dây vuông góc với từ trường nên sinα = sin 90° = 1.<br>• <span class=\"math-sym\">F = I · B · L</span> = 5,0 × 0,4 × 0,2 = <b>0,40 N</b>.","svgGraph":null},{"q":"Xét quy tắc bàn tay trái và đặc tính của lực từ tác dụng lên dòng điện. Mỗi khẳng định sau là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu đoạn dây dẫn đặt song song với các đường cảm ứng từ thì lực từ tác dụng lên nó đạt giá trị cực đại.","Quy tắc bàn tay trái: Đặt bàn tay trái sao cho lòng bàn tay hứng các đường sức từ, chiều từ cổ tay đến các ngón tay chỉ chiều dòng điện thì ngón tay cái choãi ra 90° chỉ chiều của lực từ.","Lực từ tác dụng lên đoạn dòng điện luôn vuông góc đồng thời với cả đoạn dây dẫn và vectơ cảm ứng từ B.","Khi đổi chiều đồng thời cả dòng điện I và cảm ứng từ B thì chiều của lực từ tác dụng lên dây dẫn không bị thay đổi."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Nội dung chuẩn quy tắc bàn tay trái.<br>• <b>Ý b: ĐÚNG.</b> Vectơ <span class=\"math-sym\">F ⊥ (I, B)</span>.<br>• <b>Ý c: SAI.</b> Khi song song thì <span class=\"math-sym\">α = 0° ⇒ sin α = 0 ⇒ F = 0</span> (lực từ bằng 0).<br>• <b>Ý d: ĐÚNG.</b> Đổi dấu hai lần thì tích có hướng giữ nguyên chiều.","svgGraph":null},{"q":"Hãy ghép ngón tay/bộ phận của bàn tay trái ở Cột A với đại lượng tương ứng trong quy tắc bàn tay trái ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Ngón tay cái choãi ra 90° ➔ Hướng theo chiều của dòng điện I.","Ngón tay cái choãi ra 90° ➔ Hứng các đường sức từ (hướng ngược chiều vectơ B).","Chiều từ cổ tay đến ngón tay giữa ➔ Hướng theo chiều của dòng điện I.","Lòng bàn tay ➔ Hứng các đường sức từ (hướng ngược chiều vectơ B)."],"ans":0,"exp":"• 1 ghép với C (Ngón cái chỉ lực từ F).<br>• 2 ghép với A (Ngón giữa theo dòng điện I).<br>• 3 ghép với B (Lòng bàn tay hứng B).<br>• 4 ghép với D (Góc choãi 90°).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Vectơ cảm ứng từ B tại một điểm đặc trưng cho từ trường về mặt [0] lực. Vectơ B có phương trùng với [1] của đường sức từ tại điểm đó và có chiều trùng với chiều của từ trường (từ cực [2] sang cực Bắc của kim nam châm thử cân bằng tại đó).\"</i>","opts":["tác dụng — tiếp tuyến","không đổi","sinh công — Bắc","tiếp tuyến — tác dụng"],"ans":0,"exp":"• B đặc trưng cho tác dụng lực, có phương tiếp tuyến với đường sức từ, chiều từ Nam sang Bắc của nam châm thử.","svgGraph":null},{"q":"Trong đời sống hằng ngày, thiết bị nào sau đây hoạt động dựa trên ứng dụng trực tiếp của lực từ tác dụng lên khung dây dẫn có dòng điện đặt trong từ trường?","opts":["Động cơ điện một chiều trong quạt máy, máy bơm nước và xe đạp điện.","Bình thủy điện giữ nhiệt dùng trong sinh hoạt gia đình.","Ấm đun nước siêu tốc bằng điện trở may-so đốt nóng.","Bóng đèn sợi đốt halogen dùng để chiếu sáng trong nhà."],"ans":0,"exp":"• <b>Ứng dụng của lực từ:</b> Động cơ điện (motor) hoạt động dựa trên tác dụng của lực từ lên các đoạn dây dẫn của khung dây mang dòng điện đặt trong từ trường.<br>• Cặp lực từ tác dụng lên hai cạnh đối diện của khung dây tạo thành một ngẫu lực từ, làm khung dây quay liên tục quanh trục của nó, chuyển hóa điện năng thành cơ năng phục vụ đời sống.","svgGraph":null},{"q":"Nguyên lí phát ra âm thanh của một chiếc loa điện động (loa thùng, tai nghe thông thường) dựa trên hiện tượng vật lí nào sau đây?","opts":["Lực từ tác dụng lên cuộn dây mang dòng âm tần đặt trong từ trường của nam châm, làm cuộn dây và màng loa dao động.","Hiện tượng quang điện giải phóng các hạt electron tự do làm rung chuyển các phân tử không khí.","Lực ma sát cơ học giữa cuộn dây và lõi thép tạo ra âm thanh truyền qua màng loa.","Sự dãn nở vì nhiệt tuần hoàn của màng loa khi có dòng điện chạy qua điện trở."],"ans":0,"exp":"• <b>Nguyên lí loa điện động:</b> Loa điện động gồm một nam châm vĩnh cửu tạo từ trường hướng tâm và một cuộn dây (cuộn âm thanh) gắn liền với màng loa đặt trong khe từ trường.<br>• Khi dòng điện xoay chiều mang tín hiệu âm tần chạy qua cuộn dây, từ trường tác dụng lực từ F<sub>t</sub>ừ lên cuộn dây làm nó dao động dọc theo trục theo phương vuông góc với đường sức từ.<br>• Cuộn dây kéo theo màng loa dao động, nén và dãn các lớp không khí xung quanh, tái tạo sóng âm truyền đến tai người nghe.","svgGraph":null},{"q":"Quan sát hình vẽ mô tả đoạn dây dẫn mang dòng điện trong từ trường đều và quy tắc bàn tay trái. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu xoay đoạn dây dẫn sao cho nó song song với phương thẳng đứng của cảm ứng từ B thì lực từ đạt cực đại.","Theo hình vẽ, dòng điện I chạy từ trái sang phải và cảm ứng từ B hướng thẳng đứng từ trên xuống dưới.","Lực từ F tác dụng lên đoạn dây dẫn hướng thẳng đứng từ dưới lên trên.","Nếu đồng thời tăng cường độ dòng điện lên 2 lần và giảm cảm ứng từ đi 2 lần thì độ lớn của lực từ không đổi."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Trục dây nằm ngang, chiều dòng điện sang phải, mũi tên B hướng xuống.<br>• <b>Ý b: ĐÚNG.</b> Đặt tay trái hứng B (lòng bàn tay ngửa lên), 4 ngón sang phải thì ngón cái chỉ lên trên.<br>• <b>Ý c: ĐÚNG.</b> <span class=\"math-sym\">F = (2I) · <span class=\"fraction\"><span class=\"numerator\">B</span><span class=\"denominator\">2</span></span> · L = I · B · L</span> (không đổi).<br>• <b>Ý d: SAI.</b> Khi song song thì <span class=\"math-sym\">α = 0 ⇒ F = 0</span>.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrF\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#f43f5e\"/>\n    </marker>\n    <marker id=\"arrB\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#06b6d4\"/>\n    </marker>\n    <marker id=\"arrI\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#fbbf24\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">QUY TẮC BÀN TAY TRÁI XÁC ĐỊNH LỰC TỪ</text>\n\n  <!-- Đoạn dây dẫn nằm ngang -->\n  <line x1=\"120\" y1=\"180\" x2=\"420\" y2=\"180\" stroke=\"#f59e0b\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n  <line x1=\"240\" y1=\"180\" x2=\"300\" y2=\"180\" stroke=\"#fbbf24\" stroke-width=\"4\" marker-end=\"url(#arrI)\"/>\n  <text x=\"320\" y=\"200\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">Dòng điện I</text>\n\n  <!-- Các vectơ cảm ứng từ B vuông góc đâm xuống -->\n  <g stroke=\"#06b6d4\" stroke-width=\"2.5\">\n    <line x1=\"170\" y1=\"90\" x2=\"170\" y2=\"160\" marker-end=\"url(#arrB)\"/>\n    <line x1=\"270\" y1=\"90\" x2=\"270\" y2=\"160\" marker-end=\"url(#arrB)\"/>\n    <line x1=\"370\" y1=\"90\" x2=\"370\" y2=\"160\" marker-end=\"url(#arrB)\"/>\n  </g>\n  <text x=\"285\" y=\"110\" fill=\"#06b6d4\" font-size=\"14\" font-weight=\"bold\">Từ trường B</text>\n\n  <!-- Vectơ lực từ F hướng ra ngoài (góc chiếu 3D hướng chéo lên) -->\n  <line x1=\"270\" y1=\"180\" x2=\"270\" y2=\"70\" stroke=\"#f43f5e\" stroke-width=\"3.5\" marker-end=\"url(#arrF)\"/>\n  <text x=\"285\" y=\"75\" fill=\"#f43f5e\" font-size=\"16\" font-weight=\"bold\">Lực từ F = I·B·L·sinα</text>\n\n  <!-- Hộp mô tả bàn tay trái -->\n  <rect x=\"60\" y=\"215\" width=\"420\" height=\"50\" rx=\"8\" fill=\"rgba(30,41,59,0.85)\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <text x=\"70\" y=\"235\" fill=\"#cbd5e1\" font-size=\"11\">• <b>Lòng bàn tay:</b> Hứng các đường sức từ B.</text>\n  <text x=\"70\" y=\"252\" fill=\"#cbd5e1\" font-size=\"11\">• <b>Chiều cổ tay đến ngón giữa:</b> Hướng theo dòng điện I.</text>\n  <text x=\"280\" y=\"252\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">• <b>Ngón cái choãi 90°:</b> Chỉ chiều lực từ F.</text>\n</svg>"},{"q":"Tàu đệm từ trường (Maglev) có thể di chuyển với vận tốc cực cao (trên 500 km/h) mà vẫn rất êm ái. Đặc điểm vật lí cốt lõi giúp tàu đạt được vận tốc này là:","opts":["Lực từ giữa nam châm siêu dẫn nâng thân tàu lơ lửng trên đường ray, triệt tiêu hoàn toàn ma sát lăn cơ học.","Tàu được trang bị động cơ phản lực đốt cháy nhiên liệu hạt nhân ở đuôi tàu.","Đường ray của tàu được bọc kín và hút chân không tuyệt đối làm giảm lực cản không khí về 0.","Trọng lực của Trái Đất tác dụng lên đoàn tàu bị triệt tiêu hoàn toàn khi tàu đạt tốc độ cao."],"ans":0,"exp":"• <b>Ứng dụng của lực từ trong tàu đệm từ Maglev:</b> Hệ thống nam châm điện siêu dẫn đặt trên thân tàu và đường ray tạo ra lực từ cực mạnh cùng dấu để đẩy tàu nâng bổng lên cách mặt ray khoảng 10 - 15 mm.<br>• Nhờ không có sự tiếp xúc cơ học trực tiếp giữa bánh xe và ray, lực ma sát lăn bị triệt tiêu hoàn toàn, chỉ còn lực cản của không khí.<br>• Điều này giúp tàu Maglev vận hành êm ái, giảm thiểu tiếng ồn và đạt tốc độ siêu cao vượt trội (từ 400 đến trên 600 km/h) mà các đoàn tàu bánh sắt truyền thống khó đạt được.","svgGraph":null}],"16":[{"q":"Từ thông Φ xuyên qua diện tích S của một khung dây phẳng đặt trong từ trường đều B được xác định bởi công thức:","opts":["Φ = B · S · cosα (với α là góc giữa vectơ cảm ứng từ B và vectơ pháp tuyến n của khung dây).","Φ = B · S · sinα.","Φ = <span class=\"fraction\"><span class=\"numerator\">B</span><span class=\"denominator\">S · cosα</span></span>.","Φ = I · B · S."],"ans":0,"exp":"• <b>Định nghĩa từ thông:</b> <span class=\"math-sym\">Φ = B · S · cos α</span>.<br>• Trong đó <span class=\"math-sym\">α = (n, B)</span>. Từ thông có đơn vị là <b>Weber (Wb)</b>.","svgGraph":null},{"q":"Điều kiện cần và đủ để xuất hiện dòng điện cảm ứng trong một mạch kín là:","opts":["Từ thông qua diện tích giới hạn bởi mạch kín phải biến thiên theo thời gian.","Mạch kín phải được đặt trong một từ trường có độ lớn cực đại không đổi.","Khung dây phải được làm bằng chất liệu siêu dẫn.","Từ trường gửi qua mạch kín phải có các đường sức từ hoàn toàn song song."],"ans":0,"exp":"• <b>Hiện tượng cảm ứng điện từ:</b> Dòng điện cảm ứng chỉ xuất hiện trong mạch kín <b>khi và chỉ khi từ thông qua mạch biến thiên</b> theo thời gian.","svgGraph":null},{"q":"Theo <b>Định luật Lenz</b>, dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho:","opts":["Từ trường do nó sinh ra có tác dụng chống lại sự biến thiên của từ thông ban đầu gửi qua mạch kín.","Làm cho từ thông qua mạch luôn luôn tăng lên cực đại.","Làm cho khung dây quay theo chiều kim đồng hồ trong mọi trường hợp.","Từ trường cảm ứng luôn luôn cùng chiều với từ trường ban đầu."],"ans":0,"exp":"• <b>Định luật Lenz:</b> Thể hiện tính bảo toàn năng lượng và chống lại nguyên nhân sinh ra nó: Nếu từ thông ban đầu tăng thì từ trường cảm ứng sẽ ngược chiều để chống tăng; nếu từ thông giảm thì từ trường cảm ứng sẽ cùng chiều để chống giảm.","svgGraph":null},{"q":"Xét các quy tắc và định luật về hiện tượng cảm ứng điện từ. Mỗi nhận định sau là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Từ thông qua mặt phẳng khung dây đạt giá trị cực đại khi mặt phẳng khung đặt song song với các đường sức từ.","Độ lớn của suất điện động cảm ứng trong mạch kín tỉ lệ với tốc độ biến thiên của từ thông qua mạch đó (ec = -<span class=\"fraction\"><span class=\"numerator\">ΔΦ</span><span class=\"denominator\">Δt</span></span>).","Khi đưa cực Bắc của thanh nam châm lại gần một vòng nhôm kín thì vòng nhôm sẽ bị đẩy ra xa.","Hiện tượng tự cảm là một trường hợp đặc biệt của hiện tượng cảm ứng điện từ xảy ra trong chính mạch có dòng điện biến thiên."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Định luật Faraday về suất điện động cảm ứng.<br>• <b>Ý b: SAI.</b> Khi mặt phẳng khung song song với B thì pháp tuyến n vuông góc với B ⇒ α = 90° ⇒ cosα = 0 ⇒ Φ = 0 (từ thông bằng 0, không phải cực đại).<br>• <b>Ý c: ĐÚNG.</b> Theo định luật Lenz, khi nam châm lại gần (từ thông tăng), vòng nhôm xuất hiện dòng điện tạo từ trường ngược chiều đẩy nam châm (chống lại sự lại gần).<br>• <b>Ý d: ĐÚNG.</b> Đây là bản chất của hiện tượng tự cảm.","svgGraph":null},{"q":"Hãy ghép các đại lượng/định luật ở Cột A với đơn vị hoặc nội hàm tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Từ thông Φ ➔ Đơn vị là Weber trên giây (Wb/s) hay Volt (V).","Từ thông Φ ➔ Đơn vị đo là Weber (Wb) trong hệ SI.","Suất điện động cảm ứng ec ➔ Đơn vị là Weber trên giây (Wb/s) hay Volt (V).","Định luật Lenz ➔ Đơn vị đo là Weber (Wb) trong hệ SI."],"ans":0,"exp":"• 1 ghép với B (Từ thông đơn vị Wb).<br>• 2 ghép với D (Suất điện động đơn vị V).<br>• 3 ghép với C (Định luật Lenz xác định chiều).<br>• 4 ghép với A (Tốc độ biến thiên Wb/s).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Độ lớn của suất điện động cảm ứng xuất hiện trong một mạch kín tỉ lệ thuận với [0] của từ thông gửi qua diện tích giới hạn bởi mạch đó. Dấu trừ trong biểu thức của định luật Faraday thể hiện sự phù hợp với [1], phản ánh tính chất [2] nguyên nhân sinh ra nó.\"</i>","opts":["tốc độ biến thiên — định luật Lenz","không đổi","hỗ trợ — định luật Ohm","định luật Lenz — tốc độ biến thiên"],"ans":0,"exp":"• Biểu thức <span class=\"math-sym\">e</span><sub>c</sub> = <span class=\"fraction\"><span class=\"numerator\">-ΔΦ</span><span class=\"denominator\">Δt</span></span>. Dấu trừ thể hiện <b>định luật Lenz</b> chống lại sự biến thiên.","svgGraph":null},{"q":"Một khung dây phẳng có diện tích 20 cm² gồm 100 vòng dây đặt trong từ trường đều có vectơ B vuông góc với mặt phẳng khung. Trong khoảng thời gian 0,02 s, cảm ứng từ giảm đều từ 0,5 T về 0,1 T. Độ lớn của suất điện động cảm ứng xuất hiện trong khung dây là:","opts":["4,0 V.","2,0 V.","8,0 V.","0,4 V."],"ans":0,"exp":"• Vectơ B vuông góc mặt phẳng khung ⇒ cos 0° = 1.<br>• <span class=\"math-sym\">|e</span><sub>c</sub><span class=\"math-sym\">| = N · S ·</span> <span class=\"fraction\"><span class=\"numerator\">|ΔB|</span><span class=\"denominator\">Δt</span></span> = 100 × 20 · 10⁻⁴ × <span class=\"fraction\"><span class=\"numerator\">0,5 - 0,1</span><span class=\"denominator\">0,02</span></span> = 0,2 × 20 = <b>4,0 V</b>.","svgGraph":null},{"q":"Trong hệ thống giao thông hiện đại, phanh điện từ sử dụng dòng điện Fu-cô (Foucault) được trang bị phổ biến trên các đoàn tàu cao tốc (như Shinkansen, TGV). Ưu điểm nổi bật của loại phanh này so với phanh ma sát cơ học là:","opts":["Quá trình hãm phanh êm ái ở tốc độ cao, không mòn đĩa phanh và không phát sinh tia lửa hay bụi ma sát độc hại.","Phanh điện từ có thể dừng đoàn tàu tức thì chỉ trong 0,01 giây mà hoàn toàn không gây gia tốc quán tính.","Phanh điện từ tự động tăng công suất phát điện của động cơ kéo đoàn tàu trong khi hãm.","Phanh điện từ vận hành mà không cần bất kì từ trường nào tác dụng lên đĩa kim loại dẫn điện."],"ans":0,"exp":"• <b>Ứng dụng dòng điện Fu-cô:</b> Khi phanh điện từ hoạt động, một từ trường mạnh được đặt xuyên qua đĩa kim loại gắn với trục bánh xe (hoặc ray dẫn).<br>• Sự quay của đĩa kim loại trong từ trường làm từ thông biến thiên, sinh ra dòng điện xoay tròn Foucault bên trong khối kim loại. Theo định luật Lenz, lực từ tác dụng lên các dòng điện này luôn chống lại nguyên nhân sinh ra nó (chống lại chuyển động quay), tạo ra mômen hãm xe dừng lại mà không hề có sự cọ xát mài mòn cơ học.","svgGraph":null},{"q":"Quan sát đồ thị từ thông Φ(t) và suất điện động cảm ứng ec(t) như hình bên. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Khi từ thông đạt giá trị cực đại Φ₀ ở thời điểm t₁ thì suất điện động cảm ứng cũng đạt giá trị cực đại.","Trong khoảng thời gian từ 0 đến t₁, từ thông tăng đều theo hàm bậc nhất nên suất điện động cảm ứng ec có giá trị âm không đổi.","Trong khoảng thời gian từ t₁ đến t₂, từ thông giữ nguyên không đổi nên suất điện động cảm ứng ec bằng 0.","Nếu thời gian tăng từ thông từ 0 đến t₁ bị rút ngắn một nửa thì độ lớn suất điện động cảm ứng sẽ tăng gấp đôi."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Đạo hàm bậc nhất của hàm tuyến tính là hằng số, có dấu trừ theo định luật Faraday.<br>• <b>Ý b: ĐÚNG.</b> <span class=\"math-sym\">ΔΦ = 0 ⇒ e</span><sub>c</sub> = 0.<br>• <b>Ý c: ĐÚNG.</b> Tốc độ biến thiên tăng gấp đôi thì độ lớn <span class=\"math-sym\">e</span><sub>c</sub> tăng gấp đôi.<br>• <b>Ý d: SAI.</b> Tại <span class=\"math-sym\">t</span><sub>1</sub> từ thông đạt cực đại và không đổi nên đạo hàm bằng 0, suất điện động bằng 0.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr16\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐỒ THỊ TỪ THÔNG Φ(t) &amp; SUẤT ĐIỆN ĐỘNG CẢM ỨNG ec(t)</text>\n\n  <!-- Đồ thị 1: Phi(t) -->\n  <g transform=\"translate(40, 40)\">\n    <line x1=\"20\" y1=\"90\" x2=\"210\" y2=\"90\" stroke=\"#94a3b8\" stroke-width=\"1.5\" marker-end=\"url(#arr16)\"/>\n    <line x1=\"20\" y1=\"90\" x2=\"20\" y2=\"15\" stroke=\"#94a3b8\" stroke-width=\"1.5\" marker-end=\"url(#arr16)\"/>\n    <text x=\"200\" y=\"105\" fill=\"#94a3b8\" font-size=\"11\">t (s)</text>\n    <text x=\"5\" y=\"20\" fill=\"#38bdf8\" font-size=\"11\">Φ (Wb)</text>\n\n    <!-- Đường Phi tăng tuyến tính rồi đi ngang -->\n    <line x1=\"20\" y1=\"90\" x2=\"100\" y2=\"30\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n    <line x1=\"100\" y1=\"30\" x2=\"190\" y2=\"30\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n\n    <line x1=\"100\" y1=\"30\" x2=\"100\" y2=\"90\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n    <text x=\"15\" y=\"102\" fill=\"#94a3b8\" font-size=\"10\">0</text>\n    <text x=\"95\" y=\"102\" fill=\"#94a3b8\" font-size=\"10\">t₁</text>\n    <text x=\"185\" y=\"102\" fill=\"#94a3b8\" font-size=\"10\">t₂</text>\n    <text x=\"2\" y=\"35\" fill=\"#38bdf8\" font-size=\"10\">Φ₀</text>\n\n    <text x=\"105\" y=\"125\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Từ thông tăng rồi không đổi</text>\n  </g>\n\n  <!-- Đồ thị 2: ec(t) -->\n  <g transform=\"translate(290, 40)\">\n    <line x1=\"20\" y1=\"60\" x2=\"210\" y2=\"60\" stroke=\"#94a3b8\" stroke-width=\"1.5\" marker-end=\"url(#arr16)\"/>\n    <line x1=\"20\" y1=\"100\" x2=\"20\" y2=\"15\" stroke=\"#94a3b8\" stroke-width=\"1.5\" marker-end=\"url(#arr16)\"/>\n    <text x=\"200\" y=\"75\" fill=\"#94a3b8\" font-size=\"11\">t (s)</text>\n    <text x=\"5\" y=\"20\" fill=\"#f43f5e\" font-size=\"11\">ec (V)</text>\n\n    <!-- Giai đoạn 1: ec âm không đổi; Giai đoạn 2: ec = 0 -->\n    <line x1=\"20\" y1=\"85\" x2=\"100\" y2=\"85\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n    <line x1=\"100\" y1=\"85\" x2=\"100\" y2=\"60\" stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n    <line x1=\"100\" y1=\"60\" x2=\"190\" y2=\"60\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n\n    <text x=\"95\" y=\"55\" fill=\"#94a3b8\" font-size=\"10\">t₁</text>\n    <text x=\"185\" y=\"55\" fill=\"#94a3b8\" font-size=\"10\">t₂</text>\n    <text x=\"2\" y=\"90\" fill=\"#f43f5e\" font-size=\"10\">-E₀</text>\n\n    <text x=\"105\" y=\"125\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">ec = -ΔΦ/Δt (xung bậc thang)</text>\n  </g>\n\n  <!-- Kết luận định luật Lenz -->\n  <rect x=\"50\" y=\"200\" width=\"440\" height=\"58\" rx=\"8\" fill=\"rgba(30,41,59,0.85)\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"222\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\">• Định luật Lenz:</text>\n  <text x=\"165\" y=\"222\" fill=\"#cbd5e1\" font-size=\"12\">Dòng điện cảm ứng có chiều sao cho từ trường do nó sinh ra</text>\n  <text x=\"65\" y=\"242\" fill=\"#cbd5e1\" font-size=\"12\">có tác dụng <b>chống lại sự biến thiên của từ thông</b> ban đầu gửi qua mạch.</text>\n</svg>"},{"q":"Khi đưa một thanh nam châm dịch chuyển ra xa một cuộn dây dẫn kín, dòng điện cảm ứng xuất hiện trong cuộn dây sẽ có chiều sinh ra từ trường nhằm mục đích:","opts":["Hút thanh nam châm lại gần cuộn dây (chống lại sự dịch chuyển ra xa).","Đẩy thanh nam châm ra xa nhanh hơn nữa.","Triệt tiêu hoàn toàn từ trường của chính thanh nam châm.","Làm nóng cuộn dây đến khi nóng chảy."],"ans":0,"exp":"• <b>Theo định luật Lenz:</b> Dòng điện cảm ứng luôn sinh ra lực từ chống lại chuyển động tương đối. Khi nam châm ra xa, nó sẽ hút lại để ngăn cản sự chuyển động ra xa đó.","svgGraph":null}],"17":[{"q":"Nguyên tắc hoạt động của máy phát điện xoay chiều một pha dựa trên hiện tượng vật lí nào?","opts":["Hiện tượng cảm ứng điện từ.","Hiện tượng tự cảm.","Hiện tượng tỏa nhiệt Joule - Lenz.","Hiện tượng quang điện ngoài."],"ans":0,"exp":"• <b>Nguyên tắc:</b> Máy phát điện xoay chiều hoạt động dựa trên <b>hiện tượng cảm ứng điện từ</b>: khi từ thông qua cuộn dây biến thiên tuần hoàn (do roto quay), trong cuộn dây xuất hiện suất điện động xoay chiều.","svgGraph":null},{"q":"Mối quan hệ giữa giá trị hiệu dụng U và giá trị cực đại (biên độ) U₀ của điện áp xoay chiều hình sin là:","opts":["U = <span class=\"fraction\"><span class=\"numerator\">U₀</span><span class=\"denominator\">√2</span></span>.","U = U₀ · √2.","U = 2 · U₀.","U = <span class=\"fraction\"><span class=\"numerator\">U₀</span><span class=\"denominator\">2</span></span>."],"ans":0,"exp":"• <b>Giá trị hiệu dụng:</b> <span class=\"math-sym\">U</span> = <span class=\"fraction\"><span class=\"numerator\">U₀</span><span class=\"denominator\">√2</span></span> ≈ 0,707 <span class=\"math-sym\">U</span><sub>0</sub>.","svgGraph":null},{"q":"Điện áp xoay chiều của mạng điện sinh hoạt dân dụng tại Việt Nam có giá trị hiệu dụng 220 V và tần số 50 Hz. Giá trị cực đại của điện áp này xấp xỉ bằng:","opts":["311 V.","220 V.","440 V.","155 V."],"ans":0,"exp":"• <span class=\"math-sym\">U</span><sub>0</sub> = <span class=\"math-sym\">U · √2</span> = 220 × 1,414 ≈ <b>311 V</b>.","svgGraph":null},{"q":"Xét cấu tạo và hoạt động của máy phát điện xoay chiều. Mỗi phát biểu sau là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Các đồng hồ đo điện đa năng hiện số (VOM) khi đo dòng điện xoay chiều sẽ chỉ giá trị cực đại của dòng điện.","Máy phát điện xoay chiều gồm hai bộ phận chính là phần cảm (tạo ra từ trường) và phần ứng (tạo ra suất điện động cảm ứng).","Bộ phận đứng yên được gọi là stato, bộ phận quay quanh trục được gọi là roto.","Tần số của dòng điện xoay chiều do máy phát có p cặp cực và roto quay với tốc độ n (vòng/s) sinh ra là f = n · p."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Phần cảm tạo từ trường, phần ứng sinh dòng điện.<br>• <b>Ý b: ĐÚNG.</b> Định nghĩa stato (tĩnh) và roto (quay).<br>• <b>Ý c: ĐÚNG.</b> Công thức chuẩn: <span class=\"math-sym\">f = n · p</span> (với n tính bằng vòng/giây).<br>• <b>Ý d: SAI.</b> Các dụng cụ đo vôn kế, ampe kế nhiệt luôn chỉ <b>giá trị hiệu dụng</b>.","svgGraph":null},{"q":"Hãy ghép các thông số/khái niệm ở Cột A với bản chất ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Phần cảm ➔ Bộ phận chứa các cuộn dây sinh ra suất điện động cảm ứng.","Phần cảm ➔ Công thức tính tần số dòng điện xoay chiều (n: vòng/s, p: số cặp cực).","Phần ứng ➔ Bộ phận chứa các cuộn dây sinh ra suất điện động cảm ứng.","f = n · p ➔ Công thức tính tần số dòng điện xoay chiều (n: vòng/s, p: số cặp cực)."],"ans":0,"exp":"• 1 ghép với D (Phần cảm tạo từ trường).<br>• 2 ghép với A (Phần ứng tạo suất điện động).<br>• 3 ghép với B (Công thức tần số f = np).<br>• 4 ghép với C (Định nghĩa giá trị hiệu dụng qua tác dụng nhiệt).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Giá trị hiệu dụng của dòng điện xoay chiều có giá trị bằng cường độ của một dòng điện [0] mà khi đi qua cùng một điện trở trong cùng một khoảng thời gian sẽ tỏa ra một nhiệt lượng [1]. Để tính công suất nhiệt trung bình, ta sử dụng biểu thức P = [2].\"</i>","opts":["không đổi — hoàn toàn bằng nhau","không đổi","lớn gấp đôi — R · I₀²","hoàn toàn bằng nhau — không đổi"],"ans":0,"exp":"• Định nghĩa giá trị hiệu dụng dựa vào <b>tác dụng nhiệt tương đương</b> với dòng điện không đổi: <span class=\"math-sym\">P = R · I²</span> (với I là cường độ hiệu dụng).","svgGraph":null},{"q":"Một máy phát điện xoay chiều một pha có roto gồm 4 cặp cực (p = 4). Để máy phát ra dòng điện có tần số chuẩn 50 Hz thì roto phải quay với tốc độ là:","opts":["750 vòng/phút (12,5 vòng/s).","1500 vòng/phút.","3000 vòng/phút.","600 vòng/phút."],"ans":0,"exp":"• <span class=\"math-sym\">f = n · p</span> ⇒ <span class=\"math-sym\">n = <span class=\"fraction\"><span class=\"numerator\">f</span><span class=\"denominator\">p</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">50</span><span class=\"denominator\">4</span></span> = 12,5 vòng/s.<br>• Tính theo vòng/phút: <span class=\"math-sym\">N</span> = 12,5 × 60 = <b>750 vòng/phút</b>.","svgGraph":null},{"q":"Đinamô (dynamo) gắn ở bánh xe đạp dùng để thắp sáng bóng đèn khi đạp xe vào ban đêm. Hoạt động của đinamô xe đạp dựa trên nguyên tắc vật lí nào sau đây?","opts":["Bánh xe quay làm nam châm quay theo trước cuộn dây cố định, làm từ thông qua cuộn dây biến thiên tạo suất điện động cảm ứng.","Bánh xe cọ xát với núm xoay sinh ra hiện tượng nhiễm điện do ma sát truyền điện vào bóng đèn.","Pin hóa học tích hợp bên trong đinamô tự động phát điện khi phát hiện xe chuyển động.","Nhiệt lượng sinh ra do ma sát ở vành bánh xe được chuyển hóa trực tiếp thành quang năng phát sáng."],"ans":0,"exp":"• <b>Cấu tạo và hoạt động của đinamô xe đạp:</b> Đinamô xe đạp là một máy phát điện xoay chiều cỡ nhỏ. Phần cảm là nam châm vĩnh cửu gắn với núm xoay tì vào lốp xe; phần ứng là cuộn dây quấn quanh lõi sắt non cố định trên khung xe.<br>• Khi bánh xe quay, nam châm quay theo làm từ thông Φ(t) qua cuộn dây biến thiên tuần hoàn: Φ(t) = B · S · cos(ωt).<br>• Theo định luật Faraday, trong cuộn dây xuất hiện suất điện động cảm ứng xoay chiều e<sub>c</sub> = -dΦ/dt = ω · B · S · sin(ωt), cung cấp dòng điện làm sáng đèn xe đạp khi đi trong đêm tối.","svgGraph":null},{"q":"Quan sát đồ thị biến thiên điều hòa của điện áp xoay chiều u(t) hình bên. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Giá trị hiệu dụng U biểu diễn trên đồ thị luôn lớn hơn giá trị cực đại U₀.","Tại thời điểm t = 0, điện áp đạt giá trị cực đại tức thời u = +U₀.","Khoảng thời gian ngắn nhất giữa hai lần liên tiếp điện áp tức thời đạt giá trị cực đại +U₀ chính là một chu kỳ T của dòng điện.","Trong một chu kỳ T, dòng điện xoay chiều đổi chiều chuyển động đúng 2 lần."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Đồ thị bắt đầu từ đỉnh <span class=\"math-sym\">u(0) = +U₀</span>.<br>• <b>Ý b: ĐÚNG.</b> Định nghĩa chu kỳ T.<br>• <b>Ý c: SAI.</b> <span class=\"math-sym\">U = U₀ / √2 ≈ 0,707 U₀ < U₀</span>.<br>• <b>Ý d: ĐÚNG.</b> Đổi chiều tại các thời điểm qua vị trí cân bằng (u = 0).","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr17\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐỒ THỊ DAO ĐỘNG HÌNH SIN CỦA ĐIỆN ÁP XOAY CHIỀU</text>\n\n  <!-- Hệ trục u(t) -->\n  <line x1=\"50\" y1=\"140\" x2=\"490\" y2=\"140\" stroke=\"#94a3b8\" stroke-width=\"1.8\" marker-end=\"url(#arr17)\"/>\n  <line x1=\"70\" y1=\"240\" x2=\"70\" y2=\"40\" stroke=\"#94a3b8\" stroke-width=\"1.8\" marker-end=\"url(#arr17)\"/>\n  <text x=\"475\" y=\"160\" fill=\"#94a3b8\" font-size=\"12\">Thời gian t (s)</text>\n  <text x=\"25\" y=\"45\" fill=\"#38bdf8\" font-size=\"13\">u (V)</text>\n  <text x=\"55\" y=\"155\" fill=\"#94a3b8\" font-size=\"12\">O</text>\n\n  <!-- Đường sóng sin u = U0 cos(wt) -->\n  <path d=\"M 70,70 C 120,70 120,210 170,210 C 220,210 220,70 270,70 C 320,70 320,210 370,210 C 420,210 420,70 470,70\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n\n  <!-- Gióng biên độ U0 và -U0 -->\n  <line x1=\"70\" y1=\"70\" x2=\"470\" y2=\"70\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n  <line x1=\"70\" y1=\"210\" x2=\"470\" y2=\"210\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n  <text x=\"35\" y=\"75\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">+U₀</text>\n  <text x=\"35\" y=\"215\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">-U₀</text>\n\n  <!-- Mức hiệu dụng U = U0 / sqrt(2) -->\n  <line x1=\"70\" y1=\"90\" x2=\"470\" y2=\"90\" stroke=\"#f59e0b\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n  <text x=\"20\" y=\"95\" fill=\"#f59e0b\" font-size=\"11\">U = U₀/√2</text>\n\n  <!-- Đánh dấu chu kỳ T -->\n  <line x1=\"270\" y1=\"70\" x2=\"270\" y2=\"140\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"265\" y=\"158\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">T</text>\n\n  <line x1=\"470\" y1=\"70\" x2=\"470\" y2=\"140\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"460\" y=\"158\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">2T</text>\n\n  <text x=\"270\" y=\"260\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Điện áp tức thời: u = U₀·cos(ωt + φ) • Giá trị hiệu dụng: U = U₀ / √2</text>\n</svg>"},{"q":"Trong hệ thống truyền tải điện lưới quốc gia và các nhà máy công nghiệp, người ta sử dụng phổ biến dòng điện xoay chiều ba pha thay vì dòng một pha chủ yếu là vì:","opts":["Tiết kiệm dây dẫn khi truyền tải điện năng đi xa và dễ dàng tạo ra từ trường quay để vận hành động cơ không đồng bộ 3 pha.","Dòng điện xoay chiều 3 pha có điện áp thấp hơn nên hoàn toàn không gây nguy hiểm điện giật cho con người.","Dòng điện 3 pha không bị tiêu hao năng lượng do tỏa nhiệt Joule trên đường dây truyền tải.","Dòng 3 pha chỉ truyền tải điện theo một chiều duy nhất mà không đổi chiều như dòng 1 pha."],"ans":0,"exp":"• <b>Ưu điểm vượt trội của dòng xoay chiều 3 pha:</b><br>1. <i>Tiết kiệm dây dẫn:</i> Truyền tải điện năng bằng dòng 3 pha tiết kiệm dây dẫn đáng kể so với dòng 1 pha có cùng công suất.<br>2. <i>Tạo từ trường quay:</i> Dòng điện xoay chiều 3 pha chạy vào ba cuộn dây đặt lệch nhau 120° trên stato sẽ tạo ra từ trường quay đồng bộ cực kì mạnh mẽ và ổn định, làm quay rôto của động cơ không đồng bộ 3 pha (loại động cơ chiếm trên 85% tổng công suất động cơ điện trong công nghiệp).","svgGraph":null}],"18":[{"q":"Dòng điện Foucault (dòng điện xoáy) là:","opts":["Dòng điện cảm ứng xuất hiện trong khối vật dẫn kim loại khi khối vật dẫn đó đặt trong từ trường biến thiên hoặc chuyển động cắt đường sức từ.","Dòng điện xoay chiều một pha trong lưới điện quốc gia.","Dòng chuyển dời của các hạt mang điện trong chất bán dẫn tinh khiết.","Dòng điện một chiều phát ra từ các tấm pin Mặt Trời."],"ans":0,"exp":"• <b>Định nghĩa dòng Foucault:</b> Là dòng điện cảm ứng khép kín sinh ra trong <b>khối vật dẫn kim loại</b> khi có sự biến thiên từ thông, gây ra tác dụng nhiệt mạnh hoặc lực cản từ.","svgGraph":null},{"q":"Để giảm thiểu tác hại của dòng điện Foucault làm nóng và gây hao phí năng lượng trong lõi thép của máy biến áp và động cơ điện, người ta thường:","opts":["Ghép lõi thép từ nhiều lá thép kĩ thuật mỏng có phủ sơn cách điện xếp khép kín song song với đường sức từ.","Đúc lõi thép thành một khối kim loại dày nguyên khối bằng đồng nguyên chất.","Tăng cường độ dòng điện đi qua các cuộn dây lên mức tối đa.","Hút chân không hoàn toàn bên trong vỏ máy."],"ans":0,"exp":"• Khi chia lõi thép thành các lá mỏng cách điện, mạch dòng điện xoáy bị chia nhỏ và điện trở tăng lên rất lớn, làm dòng Foucault giảm xuống tối thiểu, giảm hao phí do tỏa nhiệt.","svgGraph":null},{"q":"Một máy biến áp lí tưởng có số vòng dây cuộn sơ cấp là N₁ = 2200 vòng và cuộn thứ cấp là N₂ = 110 vòng. Khi đặt vào hai đầu cuộn sơ cấp điện áp xoay chiều có giá trị hiệu dụng U₁ = 220 V thì điện áp hiệu dụng ở hai đầu cuộn thứ cấp để hở là:","opts":["11 V.","22 V.","44 V.","110 V."],"ans":0,"exp":"• Áp dụng hệ thức biến áp: <span class=\"fraction\"><span class=\"numerator\">U₂</span><span class=\"denominator\">U₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">N₂</span><span class=\"denominator\">N₁</span></span>.<br>• <span class=\"math-sym\">U</span><sub>2</sub> = <span class=\"math-sym\">U</span><sub>1</sub> · <span class=\"fraction\"><span class=\"numerator\">N₂</span><span class=\"denominator\">N₁</span></span> = 220 × <span class=\"fraction\"><span class=\"numerator\">110</span><span class=\"denominator\">2200</span></span> = <b>11 V</b>.","svgGraph":null},{"q":"Xét các đặc điểm và ứng dụng của máy biến áp và dòng điện Foucault. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Máy biến áp có thể dùng để biến đổi điện áp của dòng điện một chiều không đổi phát ra từ acquy.","Máy biến áp là thiết bị có khả năng biến đổi điện áp của dòng điện xoay chiều mà không làm thay đổi tần số của dòng điện.","Nếu số vòng dây cuộn thứ cấp lớn hơn cuộn sơ cấp (N₂ > N₁) thì máy biến áp là máy tăng áp (U₂ > U₁).","Bếp từ hoạt động dựa trên tác dụng nhiệt của dòng điện Foucault chạy trong đáy nồi bằng kim loại có từ tính."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Định nghĩa máy biến áp; tần số f luôn không đổi.<br>• <b>Ý b: ĐÚNG.</b> <span class=\"math-sym\">U₂/U₁ = N₂/N₁ > 1 ⇒ U₂ > U₁</span>.<br>• <b>Ý c: SAI.</b> Dòng một chiều không đổi có từ thông không đổi (ΔΦ = 0), không gây cảm ứng điện từ nên máy biến áp không hoạt động được.<br>• <b>Ý d: ĐÚNG.</b> Từ trường biến thiên tần số cao tạo dòng Foucault sinh nhiệt trực tiếp tại đáy nồi.","svgGraph":null},{"q":"Hãy ghép thiết bị/ứng dụng ở Cột A với nguyên lí hoạt động tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Bếp từ (bếp điện cảm ứng) ➔ Tác dụng cản trở chuyển động (lực hãm từ) của dòng Foucault trong đĩa kim loại.","Bếp từ (bếp điện cảm ứng) ➔ Biến đổi điện áp xoay chiều dựa trên cảm ứng điện từ qua lõi thép chung.","Phanh điện từ trên tàu cao tốc ➔ Tác dụng cản trở chuyển động (lực hãm từ) của dòng Foucault trong đĩa kim loại.","Máy biến áp ➔ Biến đổi điện áp xoay chiều dựa trên cảm ứng điện từ qua lõi thép chung."],"ans":0,"exp":"• 1 ghép với C (Bếp từ sinh nhiệt qua Foucault).<br>• 2 ghép với A (Phanh điện từ dùng lực hãm Foucault).<br>• 3 ghép với B (Máy biến áp dùng cảm ứng điện từ).<br>• 4 ghép với D (Công tơ điện dùng đĩa nhôm Foucault).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Trong quá trình truyền tải điện năng đi xa, công suất hao phí do tỏa nhiệt trên đường dây tỉ lệ nghịch với [0] của điện áp truyền tải. Do đó, để giảm hao phí truyền tải đi 100 lần, trước khi truyền đi ta cần dùng máy [1] để nâng điện áp lên [2] lần.\"</i>","opts":["bình phương — tăng áp","không đổi","hạ áp — 100","tăng áp — bình phương"],"ans":0,"exp":"• Công thức hao phí: Δ<span class=\"math-sym\">P = P²R / (U² cos²φ)</span>. Hao phí tỉ lệ nghịch với <b>bình phương</b> điện áp. Để giảm 100 lần, ta dùng máy <b>tăng áp</b> tăng điện áp lên <b>10</b> lần.","svgGraph":null},{"q":"Một máy biến áp lí tưởng có tỉ số số vòng dây <span class=\"fraction\"><span class=\"numerator\">N₁</span><span class=\"denominator\">N₂</span></span> = 5. Cuộn thứ cấp được nối với một bóng đèn sợi đốt tiêu thụ công suất 44 W ở điện áp 22 V. Cường độ dòng điện hiệu dụng chạy trong cuộn sơ cấp là:","opts":["0,4 A.","2,0 A.","10 A.","0,08 A."],"ans":0,"exp":"• Cường độ dòng thứ cấp: <span class=\"math-sym\">I</span><sub>2</sub> = <span class=\"math-sym\">P / U</span><sub>2</sub> = <span class=\"fraction\"><span class=\"numerator\">44</span><span class=\"denominator\">22</span></span> = 2 A.<br>• Biến áp lí tưởng: <span class=\"fraction\"><span class=\"numerator\">I₁</span><span class=\"denominator\">I₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">N₂</span><span class=\"denominator\">N₁</span></span> = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">5</span></span>.<br>• <span class=\"math-sym\">I</span><sub>1</sub> = <span class=\"math-sym\">I</span><sub>2</sub> / 5 = <span class=\"fraction\"><span class=\"numerator\">2</span><span class=\"denominator\">5</span></span> = <b>0,4 A</b>.","svgGraph":null},{"q":"Người ta cần truyền tải một công suất điện 1,0 MW từ nhà máy thủy điện đến nơi tiêu thụ bằng đường dây có điện trở tổng cộng R = 20 Ω. Nếu điện áp ở đầu đường dây truyền tải là 50 kV và hệ số công suất cosφ = 1 thì công suất hao phí do tỏa nhiệt trên đường dây là:","opts":["8,0 kW.","4,0 kW.","16 kW.","2,0 kW."],"ans":0,"exp":"• Δ<span class=\"math-sym\">P</span> = <span class=\"fraction\"><span class=\"numerator\">P² · R</span><span class=\"denominator\">U²</span></span> = <span class=\"fraction\"><span class=\"numerator\">(1,0 · 10⁶)² × 20</span><span class=\"denominator\">(50 · 10³)²</span></span> = <span class=\"fraction\"><span class=\"numerator\">2 · 10¹³</span><span class=\"denominator\">2,5 · 10⁹</span></span> = 8000 W = <b>8,0 kW</b>.","svgGraph":null},{"q":"Quan sát sơ đồ cấu tạo và hoạt động của máy biến áp hình bên. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Theo hình vẽ, số vòng dây cuộn thứ cấp N₂ nhiều hơn cuộn sơ cấp N₁ nên đây là máy hạ áp.","Từ thông do dòng điện xoay chiều trong cuộn sơ cấp sinh ra hầu như khép kín hoàn toàn bên trong lõi thép dẫn từ.","Hệ thức <span class=\"fraction\"><span class=\"numerator\">U₁</span><span class=\"denominator\">U₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">N₁</span><span class=\"denominator\">N₂</span></span> nghiệm đúng chính xác khi máy biến áp hoạt động ở chế độ lí tưởng (không có hao phí từ tản và nhiệt tỏa).","Ở máy biến áp lí tưởng, nếu điện áp thứ cấp tăng lên k lần thì cường độ dòng điện thứ cấp sẽ giảm đi k lần so với sơ cấp."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Lõi thép khép kín tập trung dẫn đường sức từ.<br>• <b>Ý b: SAI.</b> <span class=\"math-sym\">N₂ > N₁ ⇒ U₂ > U₁</span> (đây là máy <b>tăng áp</b>).<br>• <b>Ý c: ĐÚNG.</b> Công thức máy biến áp lí tưởng.<br>• <b>Ý d: ĐÚNG.</b> Do bảo toàn công suất <span class=\"math-sym\">P₁ = P₂ ⇒ U₁ · I₁ = U₂ · I₂</span>.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">SƠ ĐỒ NGUYÊN LÍ MÁY BIẾN ÁP (LÕI THÉP KHÉP KÍN)</text>\n\n  <!-- Lõi thép biến áp khép kín -->\n  <rect x=\"130\" y=\"55\" width=\"280\" height=\"150\" rx=\"10\" fill=\"#334155\" stroke=\"#94a3b8\" stroke-width=\"2.5\"/>\n  <!-- Cửa sổ lõi thép -->\n  <rect x=\"200\" y=\"90\" width=\"140\" height=\"80\" rx=\"4\" fill=\"#0f172a\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n  <!-- Cuộn sơ cấp N1 bên trái -->\n  <g fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"4\">\n    <ellipse cx=\"165\" cy=\"95\" rx=\"20\" ry=\"8\"/>\n    <ellipse cx=\"165\" cy=\"110\" rx=\"20\" ry=\"8\"/>\n    <ellipse cx=\"165\" cy=\"125\" rx=\"20\" ry=\"8\"/>\n    <ellipse cx=\"165\" cy=\"140\" rx=\"20\" ry=\"8\"/>\n    <ellipse cx=\"165\" cy=\"155\" rx=\"20\" ry=\"8\"/>\n  </g>\n  <!-- Dây vào sơ cấp -->\n  <line x1=\"80\" y1=\"95\" x2=\"145\" y2=\"95\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n  <line x1=\"80\" y1=\"155\" x2=\"145\" y2=\"155\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n  <circle cx=\"75\" cy=\"95\" r=\"4\" fill=\"#f59e0b\"/>\n  <circle cx=\"75\" cy=\"155\" r=\"4\" fill=\"#f59e0b\"/>\n  <text x=\"50\" y=\"130\" fill=\"#f59e0b\" font-size=\"12\" font-weight=\"bold\">U₁, N₁</text>\n  <text x=\"135\" y=\"180\" fill=\"#f59e0b\" font-size=\"11\" font-weight=\"bold\">Cuộn sơ cấp</text>\n\n  <!-- Cuộn thứ cấp N2 bên phải -->\n  <g fill=\"none\" stroke=\"#10b981\" stroke-width=\"4\">\n    <ellipse cx=\"375\" cy=\"85\" rx=\"20\" ry=\"7\"/>\n    <ellipse cx=\"375\" cy=\"98\" rx=\"20\" ry=\"7\"/>\n    <ellipse cx=\"375\" cy=\"111\" rx=\"20\" ry=\"7\"/>\n    <ellipse cx=\"375\" cy=\"124\" rx=\"20\" ry=\"7\"/>\n    <ellipse cx=\"375\" cy=\"137\" rx=\"20\" ry=\"7\"/>\n    <ellipse cx=\"375\" cy=\"150\" rx=\"20\" ry=\"7\"/>\n    <ellipse cx=\"375\" cy=\"163\" rx=\"20\" ry=\"7\"/>\n  </g>\n  <!-- Dây ra thứ cấp -->\n  <line x1=\"395\" y1=\"85\" x2=\"460\" y2=\"85\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n  <line x1=\"395\" y1=\"163\" x2=\"460\" y2=\"163\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n  <circle cx=\"465\" cy=\"85\" r=\"4\" fill=\"#10b981\"/>\n  <circle cx=\"465\" cy=\"163\" r=\"4\" fill=\"#10b981\"/>\n  <text x=\"480\" y=\"130\" fill=\"#10b981\" font-size=\"12\" font-weight=\"bold\">U₂, N₂</text>\n  <text x=\"350\" y=\"180\" fill=\"#10b981\" font-size=\"11\" font-weight=\"bold\">Cuộn thứ cấp</text>\n\n  <!-- Từ thông khép kín trong lõi -->\n  <rect x=\"180\" y=\"75\" width=\"180\" height=\"110\" rx=\"6\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"5,4\"/>\n  <text x=\"270\" y=\"132\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Từ thông Φ(t)</text>\n\n  <!-- Công thức máy biến áp -->\n  <rect x=\"70\" y=\"215\" width=\"400\" height=\"50\" rx=\"8\" fill=\"rgba(30,41,59,0.85)\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <text x=\"270\" y=\"245\" fill=\"#facc15\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">Hệ thức biến áp lí tưởng: U₁ / U₂ = N₁ / N₂ = I₂ / I₁</text>\n</svg>"},{"q":"Tại sao các thiết bị phanh điện từ trên xe tải lớn hoặc tàu hỏa chạy đệm từ trường lại không bao giờ bị mòn cơ học như phanh má phanh ma sát truyền thống?","opts":["Vì lực hãm sinh ra hoàn toàn do tương tác từ trường giữa dòng điện Foucault cảm ứng và nam châm mà không cần hai bề mặt tiếp xúc cọ xát trực tiếp.","Vì nhiệt độ làm bốc hơi toàn bộ bề mặt kim loại trước khi chạm vào nhau.","Vì nam châm đẩy xe bay lên không trung.","Vì dòng Foucault làm nguội dầu bôi trơn thành chất siêu rắn."],"ans":0,"exp":"• <b>Ưu điểm vượt trội của phanh điện từ:</b> Lực hãm là lực tương tác từ trường tác dụng từ xa lên dòng xoáy Foucault, không có tiếp xúc cọ xát cơ học nên <b>không bị mòn đĩa phanh và không phát sinh bụi bẩn</b>.","svgGraph":null}],"19":[{"q":"Theo luận điểm nổi tiếng của James Clerk Maxwell, mối quan hệ mật thiết giữa điện trường và từ trường biến thiên là:","opts":["Một từ trường biến thiên theo thời gian sinh ra một điện trường xoáy, và ngược lại một điện trường biến thiên theo thời gian sinh ra một từ trường.","Điện trường biến thiên chỉ sinh ra các hạt electron tự do.","Từ trường biến thiên chỉ xuất hiện khi có dây dẫn kim loại dẫn điện.","Điện trường và từ trường tồn tại hoàn toàn độc lập, không bao giờ có thể tương hỗ sinh ra nhau."],"ans":0,"exp":"• <b>Thuyết điện từ trường Maxwell:</b> Điện trường biến thiên và từ trường biến thiên là hai mặt thống nhất của một thực thể vật lí duy nhất gọi là <b>điện từ trường</b>.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Axis v (Propagating axis x) -->\n  <line x1=\"40\" y1=\"105\" x2=\"420\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n  <polygon points=\"425,105 413,99 413,111\" fill=\"#94a3b8\"/>\n  <text x=\"430\" y=\"110\" fill=\"#94a3b8\" font-size=\"13\" font-weight=\"800\">v</text>\n  <!-- E wave (Vertical, Red/Pink) -->\n  <path d=\"M 60,105 Q 110,25 160,105 Q 210,185 260,105 Q 310,25 360,105\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n  <text x=\"110\" y=\"30\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"800\">E (Điện trường)</text>\n  <!-- E vectors -->\n  <line x1=\"110\" y1=\"105\" x2=\"110\" y2=\"35\" stroke=\"#f43f5e\" stroke-width=\"1.5\"/><polygon points=\"110,30 106,40 114,40\" fill=\"#f43f5e\"/>\n  <line x1=\"210\" y1=\"105\" x2=\"210\" y2=\"175\" stroke=\"#f43f5e\" stroke-width=\"1.5\"/><polygon points=\"210,180 206,170 214,170\" fill=\"#f43f5e\"/>\n  <!-- B wave (Horizontal perspective, Cyan/Blue) -->\n  <path d=\"M 60,105 Q 110,145 160,105 Q 210,65 260,105 Q 310,145 360,105\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.5\" stroke-dasharray=\"4,2\"/>\n  <text x=\"210\" y=\"55\" fill=\"#06b6d4\" font-size=\"14\" font-weight=\"800\">B (Từ trường)</text>\n  <!-- Caption -->\n  <text x=\"230\" y=\"198\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">Sóng điện từ là sóng ngang: E ⊥ B ⊥ v và cùng pha dao động</text>\n</svg>"},{"q":"Sóng điện từ là:","opts":["Điện từ trường lan truyền trong không gian dưới dạng sóng.","Sóng cơ học lan truyền nhờ sự dao động của các phân tử môi trường.","Chỉ là dòng các hạt proton chuyển động trong chân không.","Dòng các hạt neutron thoát ra từ lò phản ứng hạt nhân."],"ans":0,"exp":"• <b>Định nghĩa sóng điện từ:</b> Là sự lan truyền của điện từ trường trong không gian theo thời gian.","svgGraph":null},{"q":"Đặc điểm nào sau đây là <b>đúng</b> khi nói về sóng điện từ?","opts":["Sóng điện từ là sóng ngang, lan truyền được trong chân không với tốc độ bằng tốc độ ánh sáng c ≈ 3 · 10⁸ m/s.","Sóng điện từ là sóng dọc, không thể lan truyền trong môi trường chân không.","Vectơ cường độ điện trường E và vectơ cảm ứng từ B luôn dao động vuông pha với nhau.","Tốc độ truyền sóng điện từ trong môi trường điện môi luôn lớn hơn tốc độ truyền trong chân không."],"ans":0,"exp":"• <b>Đặc điểm sóng điện từ:</b> Là sóng ngang (<span class=\"math-sym\">E ⊥ B ⊥ v</span>), truyền được trong chân không với tốc độ cực đại <span class=\"math-sym\">c ≈ 3 · 10⁸</span> m/s. Tại mỗi điểm, <span class=\"math-sym\">E</span> và <span class=\"math-sym\">B</span> luôn <b>dao động đồng pha</b>.","svgGraph":null},{"q":"Xét tính chất và thang sóng điện từ. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Sóng điện từ không có các tính chất phản xạ, khúc xạ và giao thoa như sóng ánh sáng.","Sóng điện từ mang năng lượng tỉ lệ với lũy thừa bậc 4 của tần số sóng.","Tại mỗi điểm trên phương truyền sóng, vectơ cường độ điện trường E và vectơ cảm ứng từ B luôn biến thiên cùng tần số và cùng pha với nhau.","Sắp xếp theo thứ tự bước sóng giảm dần: Sóng vô tuyến → Tia hồng ngoại → Ánh sáng nhìn thấy → Tia tử ngoại → Tia X → Tia gamma."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Năng lượng bức xạ <span class=\"math-sym\">W ∝ f⁴</span>.<br>• <b>Ý b: ĐÚNG.</b> <span class=\"math-sym\">E</span> và <span class=\"math-sym\">B</span> luôn đồng pha (đạt cực đại cùng lúc, triệt tiêu cùng lúc).<br>• <b>Ý c: ĐÚNG.</b> Đây là thứ tự chuẩn của thang sóng điện từ theo bước sóng giảm dần (tần số tăng dần).<br>• <b>Ý d: SAI.</b> Bản thân ánh sáng chính là sóng điện từ nên có đầy đủ phản xạ, khúc xạ, giao thoa, nhiễu xạ.","svgGraph":null},{"q":"Hãy ghép các vùng sóng trong thang sóng điện từ ở Cột A với ứng dụng thực tiễn điển hình ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Sóng vô tuyến (Radio) ➔ Tiệt trùng thực phẩm, dụng cụ y tế và phát hiện vết nứt bề mặt kim loại.","Sóng vô tuyến (Radio) ➔ Chiếu điện, chụp X-quang chẩn đoán hình ảnh xương trong y tế.","Tia hồng ngoại ➔ Tiệt trùng thực phẩm, dụng cụ y tế và phát hiện vết nứt bề mặt kim loại.","Tia tử ngoại (UV) ➔ Chiếu điện, chụp X-quang chẩn đoán hình ảnh xương trong y tế."],"ans":0,"exp":"• 1 ghép với C (Sóng vô tuyến: viễn thông, wifi).<br>• 2 ghép với D (Tia hồng ngoại: remote, camera nhiệt).<br>• 3 ghép với A (Tia UV: tiệt trùng, diệt khuẩn).<br>• 4 ghép với B (Tia X: chụp X-quang y tế).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Sóng điện từ là [0] vì các vectơ cường độ điện trường E và cảm ứng từ B luôn vuông góc với phương truyền sóng. Ba vectơ E, B và vận tốc truyền sóng v tạo thành một [1]. Khi lan truyền qua mặt phân cách giữa hai môi trường, sóng điện từ tuân theo các quy luật [2] và khúc xạ tương tự như ánh sáng.\"</i>","opts":["sóng ngang — tam diện thuận","không đổi","tam diện nghịch — nhiệt động","tam diện thuận — sóng ngang"],"ans":0,"exp":"• Sóng điện từ là <b>sóng ngang</b>; ba vectơ <span class=\"math-sym\">(E, B, v)</span> lập thành một <b>tam diện thuận</b>; có đầy đủ tính chất <b>phản xạ</b>, khúc xạ.","svgGraph":null},{"q":"Một sóng điện từ truyền hình phát sóng với tần số f = 100 MHz trong chân không. Biết tốc độ ánh sáng c = 3 · 10⁸ m/s. Bước sóng của sóng điện từ này là:","opts":["3,0 m.","0,3 m.","30 m.","300 m."],"ans":0,"exp":"• <span class=\"math-sym\">λ = <span class=\"fraction\"><span class=\"numerator\">c</span><span class=\"denominator\">f</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">3 · 10⁸</span><span class=\"denominator\">100 · 10⁶</span></span> = <b>3,0 m</b>.","svgGraph":null},{"q":"Lò vi sóng là thiết bị làm nóng và nấu chín thức ăn rất nhanh chóng trong gia đình. Cơ chế vật lí chủ yếu giúp lò vi sóng làm nóng thực phẩm là gì?","opts":["Dùng sóng điện từ tần số khoảng 2,45 GHz làm các phân tử nước phân cực trong thực phẩm dao động mạnh, chuyển năng lượng thành nhiệt.","Dùng dòng điện Fu-cô chạy trực tiếp qua thực phẩm để nung nóng tương tự nguyên lí bếp từ.","Chiếu chùm tia tử ngoại (UV) năng lượng cao làm biến tính nhiệt các protein trong thức ăn.","Dùng nhiệt lượng tỏa ra từ thanh đốt điện trở may-so hồng ngoại gắn trên nóc lò."],"ans":0,"exp":"• <b>Cơ chế vật lí của lò vi sóng:</b> Nước là phân tử phân cực (có cực âm và cực dương). Sóng vi sóng phát ra có tần số 2,45 GHz làm điện trường dao động đảo chiều 2,45 tỉ lần mỗi giây.<br>• Dưới tác dụng của điện trường xoay chiều này, các phân tử nước trong thức ăn liên tục quay đổi hướng với tần số cực cao, cọ xát mãnh liệt vào nhau sinh ra nhiệt lượng lớn từ sâu bên trong khối thức ăn.<br>• Nhờ vậy, thức ăn được làm nóng cực nhanh và chín đều từ trong ra ngoài, tiết kiệm năng lượng hơn nhiều so với việc truyền nhiệt bề mặt của bếp gas hay lò nướng thông thường.","svgGraph":null},{"q":"Quan sát mô hình không gian 3D của sóng điện từ lan truyền dọc theo trục z như hình vẽ. Đánh giá tính Đúng/Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu che chắn bằng một lồng lưới kim loại khép kín (lồng Faraday) thì sóng điện từ vẫn có thể tự do xuyên qua như truyền trong không khí.","Vectơ cường độ điện trường E dao động trong mặt phẳng thẳng đứng xOz.","Vectơ cảm ứng từ B dao động trong mặt phẳng nằm ngang yOz.","Khoảng cách giữa hai điểm gần nhau nhất trên trục truyền sóng z mà dao động tại đó cùng pha chính là một bước sóng λ."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Dao động theo phương trục x vuông góc phương truyền sóng z.<br>• <b>Ý b: ĐÚNG.</b> Dao động theo phương trục y vuông góc cả x và z.<br>• <b>Ý c: ĐÚNG.</b> Định nghĩa bước sóng.<br>• <b>Ý d: SAI.</b> Lồng kim loại dẫn điện (lồng Faraday) chắn hoàn toàn sóng điện từ (nguyên lí khi đi thang máy sóng điện thoại bị mất).","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr19\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n    <marker id=\"arrWave\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">MÔ HÌNH KHÔNG GIAN 3D CỦA SÓNG ĐIỆN TỪ (E ⊥ B ⊥ v)</text>\n\n  <!-- Trục tọa độ 3D -->\n  <!-- Trục truyền sóng z (nằm ngang sang phải) -->\n  <line x1=\"60\" y1=\"150\" x2=\"490\" y2=\"150\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr19)\"/>\n  <text x=\"475\" y=\"170\" fill=\"#94a3b8\" font-size=\"13\">Trục z (v)</text>\n  \n  <!-- Trục x (điện trường E thẳng đứng) -->\n  <line x1=\"80\" y1=\"230\" x2=\"80\" y2=\"50\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr19)\"/>\n  <text x=\"65\" y=\"60\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">E</text>\n\n  <!-- Trục y (từ trường B chéo góc) -->\n  <line x1=\"120\" y1=\"180\" x2=\"40\" y2=\"120\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr19)\"/>\n  <text x=\"35\" y=\"115\" fill=\"#06b6d4\" font-size=\"13\" font-weight=\"bold\">B</text>\n\n  <!-- Dao động điện trường E (mặt phẳng đứng - màu đỏ/hồng) -->\n  <path d=\"M 80,150 C 130,70 150,70 200,150 C 250,230 270,230 320,150 C 370,70 390,70 440,150\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n  <!-- Các mũi tên E dựng đứng -->\n  <line x1=\"140\" y1=\"150\" x2=\"140\" y2=\"90\" stroke=\"#f43f5e\" stroke-width=\"1.8\" marker-end=\"url(#arrWave)\"/>\n  <line x1=\"260\" y1=\"150\" x2=\"260\" y2=\"210\" stroke=\"#f43f5e\" stroke-width=\"1.8\" marker-end=\"url(#arrWave)\"/>\n  <line x1=\"380\" y1=\"150\" x2=\"380\" y2=\"90\" stroke=\"#f43f5e\" stroke-width=\"1.8\" marker-end=\"url(#arrWave)\"/>\n\n  <!-- Dao động từ trường B (mặt phẳng nằm ngang/nghiêng - màu lục/lam) -->\n  <path d=\"M 80,150 C 120,175 160,175 200,150 C 240,125 280,125 320,150 C 360,175 400,175 440,150\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n  <!-- Các mũi tên B nằm xiên ngang -->\n  <line x1=\"140\" y1=\"150\" x2=\"160\" y2=\"168\" stroke=\"#06b6d4\" stroke-width=\"1.8\" marker-end=\"url(#arrWave)\"/>\n  <line x1=\"260\" y1=\"150\" x2=\"240\" y2=\"132\" stroke=\"#06b6d4\" stroke-width=\"1.8\" marker-end=\"url(#arrWave)\"/>\n  <line x1=\"380\" y1=\"150\" x2=\"400\" y2=\"168\" stroke=\"#06b6d4\" stroke-width=\"1.8\" marker-end=\"url(#arrWave)\"/>\n\n  <!-- Bước sóng lambda -->\n  <line x1=\"80\" y1=\"40\" x2=\"320\" y2=\"40\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <line x1=\"80\" y1=\"35\" x2=\"80\" y2=\"45\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <line x1=\"320\" y1=\"35\" x2=\"320\" y2=\"45\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"36\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Bước sóng λ = c / f</text>\n\n  <!-- Chú thích -->\n  <text x=\"270\" y=\"260\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Sóng ngang: Vectơ E ⊥ Vectơ B ⊥ Phương truyền sóng v (Tốc độ ánh sáng c ≈ 3·10⁸ m/s)</text>\n</svg>"},{"q":"Sóng wifi gia đình thường hoạt động ở hai dải tần số 2,4 GHz và 5 GHz. Các sóng này thuộc loại bức xạ nào trong thang sóng điện từ?","opts":["Sóng vô tuyến cực ngắn (vi sóng - microwaves).","Bức xạ tia hồng ngoại (infrared).","Bức xạ tia tử ngoại (ultraviolet).","Bức xạ tia X (X-rays)."],"ans":0,"exp":"• <b>Phân loại sóng vô tuyến:</b> Bước sóng của wifi ở tần số f = 2,4 GHz là λ = <span class=\"fraction\"><span class=\"numerator\">c</span><span class=\"denominator\">f</span></span> = <span class=\"fraction\"><span class=\"numerator\">3 · 10⁸</span><span class=\"denominator\">2,4 · 10⁹</span></span> ≈ 0,125 m = 12,5 cm.<br>• Bước sóng này nằm trong dải từ 1 mm đến 1 m, thuộc vùng sóng vi ba (vi sóng) của sóng vô tuyến cực ngắn. Sóng cực ngắn mang lượng thông tin rất lớn, truyền thẳng tốt, thích hợp cho truyền dẫn mạng không dây wifi, thông tin vệ tinh và mạng di động 4G/5G.","svgGraph":null}],"20":[{"q":"Một thanh kim loại chiều dài L chuyển động với vận tốc không đổi v vuông góc với các đường sức từ của một từ trường đều có cảm ứng từ B. Độ lớn của suất điện động cảm ứng xuất hiện giữa hai đầu thanh là:","opts":["ec = B · L · v.","ec = <span class=\"fraction\"><span class=\"numerator\">B · v</span><span class=\"denominator\">L</span></span>.","ec = <span class=\"fraction\"><span class=\"numerator\">B · L</span><span class=\"denominator\">v</span></span>.","ec = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">2</span></span> · B · v² · L."],"ans":0,"exp":"• <b>Suất điện động chuyển động:</b> Khi đoạn dây cắt đường sức từ với góc vuông: <span class=\"math-sym\">e</span><sub>c</sub> = <span class=\"math-sym\">B · v · L</span>.","svgGraph":null},{"q":"Một thanh dẫn điện dài 0,5 m chuyển động đều với tốc độ 4,0 m/s trong mặt phẳng vuông góc với từ trường đều B = 0,25 T. Suất điện động cảm ứng xuất hiện giữa hai đầu thanh là:","opts":["0,50 V.","0,25 V.","1,00 V.","0,125 V."],"ans":0,"exp":"• <span class=\"math-sym\">e</span><sub>c</sub> = <span class=\"math-sym\">B · v · L</span> = 0,25 × 4,0 × 0,5 = <b>0,50 V</b>.","svgGraph":null},{"q":"Một khung dây phẳng tròn bán kính r = 10 cm gồm 50 vòng dây quay đều quanh một đường kính nằm trong từ trường đều B = 0,1 T với tốc độ góc ω = 100 rad/s. Trục quay vuông góc với vectơ B. Suất điện động cực đại sinh ra trong khung dây là:","opts":["15,7 V (5π V).","31,4 V (10π V).","7,85 V.","5,0 V."],"ans":0,"exp":"• Diện tích một vòng: <span class=\"math-sym\">S = πr²</span> = π × 0,1² = 0,01π m².<br>• <span class=\"math-sym\">E</span><sub>0</sub> = <span class=\"math-sym\">ω · N · B · S</span> = 100 × 50 × 0,1 × (0,01π) = 5π ≈ <b>15,7 V</b>.","svgGraph":null},{"q":"Xét bài toán thanh kim loại trượt trên hai thanh ray kim loại song song không ma sát nối với điện trở R trong từ trường đều thẳng đứng. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu tăng điện trở R của mạch lên 2 lần thì độ lớn suất điện động cảm ứng giữa hai đầu thanh cũng tăng lên 2 lần.","Dòng điện cảm ứng xuất hiện trong mạch chạy qua thanh kim loại làm xuất hiện lực từ cản trở chuyển động của thanh (chống lại nguyên nhân sinh ra nó).","Để thanh chuyển động thẳng đều với vận tốc không đổi v, ngoại lực kéo thanh phải có độ lớn bằng đúng độ lớn của lực từ cản trở.","Toàn bộ công cơ học do ngoại lực sinh ra để duy trì chuyển động thẳng đều của thanh được chuyển hóa thành nhiệt lượng tỏa ra trên điện trở R."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Lực từ có tác dụng hãm chuyển động theo định luật Lenz.<br>• <b>Ý b: ĐÚNG.</b> Chuyển động thẳng đều thì hợp lực bằng 0 ⇒ <span class=\"math-sym\">F</span><sub>kéo</sub> = <span class=\"math-sym\">F</span><sub>từ</sub>.<br>• <b>Ý c: ĐÚNG.</b> Định luật bảo toàn năng lượng: công cơ học chuyển hoá hoàn toàn thành điện năng rồi toả nhiệt trên R.<br>• <b>Ý d: SAI.</b> Suất điện động <span class=\"math-sym\">e</span><sub>c</sub> = <span class=\"math-sym\">B · v · L</span> hoàn toàn độc lập với điện trở <span class=\"math-sym\">R</span>.","svgGraph":null},{"q":"Hãy ghép các bài toán/hiện tượng từ trường ở Cột A với công thức giải tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Đoạn dây mang dòng điện cân bằng trong từ trường ➔ ΔP = <span class=\"fraction\"><span class=\"numerator\">P² · R</span><span class=\"denominator\">U² · cos²φ</span></span>","Đoạn dây mang dòng điện cân bằng trong từ trường ➔ E₀ = ω · N · B · S","Thanh ray trượt sinh suất điện động ➔ ΔP = <span class=\"fraction\"><span class=\"numerator\">P² · R</span><span class=\"denominator\">U² · cos²φ</span></span>","Công suất hao phí truyền tải điện năng ➔ E₀ = ω · N · B · S"],"ans":0,"exp":"• 1 ghép với C (Lực từ cân bằng trọng lực).<br>• 2 ghép với D (Suất điện động chuyển động).<br>• 3 ghép với A (Hao phí truyền tải điện).<br>• 4 ghép với B (Suất điện động xoay chiều cực đại).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Khi thanh kim loại trượt đều trên ray trong từ trường, công của ngoại lực kéo thanh trong khoảng thời gian Δt bằng [0] do dòng điện cảm ứng sinh ra trong mạch. Hiện tượng này là một minh chứng thực nghiệm sắc bén khẳng định [1] được nghiệm đúng hoàn toàn trong [2].\"</i>","opts":["nhiệt lượng tỏa ra — định luật bảo toàn năng lượng","không đổi","định luật vạn vật hấp dẫn — sự biến thiên entropy","định luật bảo toàn năng lượng — nhiệt lượng tỏa ra"],"ans":0,"exp":"• Công ngoại lực bằng <b>nhiệt lượng tỏa ra</b>, minh chứng sự bảo toàn năng lượng trong <b>hiện tượng cảm ứng điện từ</b>.","svgGraph":null},{"q":"Một thanh kim loại MN dài 20 cm, khối lượng 40 g đặt trên hai thanh ray nằm ngang nhẵn trong từ trường đều thẳng đứng B = 0,5 T. Nối hai ray với nguồn điện không đổi. Để thanh chuyển động sang phải với gia tốc a = 2,5 m/s² thì cường độ dòng điện chạy qua thanh MN phải là:","opts":["1,0 A.","2,0 A.","0,5 A.","4,0 A."],"ans":0,"exp":"• Lực từ gây gia tốc cho thanh: <span class=\"math-sym\">F = m · a</span> = 0,04 × 2,5 = 0,1 N.<br>• Mà <span class=\"math-sym\">F = I · B · L</span> ⇒ <span class=\"math-sym\">I = F / (B · L)</span> = 0,1 / (0,5 × 0,2) = <b>1,0 A</b>.","svgGraph":null},{"q":"Tại một trạm phát điện, người ta muốn giảm công suất hao phí do tỏa nhiệt trên đường dây truyền tải đi 64 lần mà vẫn giữ nguyên công suất truyền đi và hệ số công suất. Cần phải điều chỉnh tỉ số điện áp ở máy biến áp tăng áp như thế nào?","opts":["Tăng điện áp trước khi truyền tải lên 8 lần.","Tăng điện áp trước khi truyền tải lên 64 lần.","Giảm điện áp trước khi truyền tải đi 8 lần.","Tăng điện áp trước khi truyền tải lên 16 lần."],"ans":0,"exp":"• Vì hao phí tỉ lệ nghịch với <span class=\"math-sym\">U²</span>: <span class=\"fraction\"><span class=\"numerator\">ΔP₁</span><span class=\"denominator\">ΔP₂</span></span> = <span class=\"fraction\"><span class=\"numerator\">U₂²</span><span class=\"denominator\">U₁²</span></span> = 64 ⇒ <span class=\"fraction\"><span class=\"numerator\">U₂</span><span class=\"denominator\">U₁</span></span> = √64 = <b>8 lần</b>.","svgGraph":null},{"q":"Xét sơ đồ thí nghiệm thanh kim loại MN trượt trên hai thanh ray trong từ trường đều như hình vẽ. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu đổi chiều của từ trường B hướng thẳng đứng từ dưới lên trên và vẫn kéo thanh sang phải thì chiều dòng điện cảm ứng không đổi.","Khi thanh MN trượt sang phải với vận tốc v, diện tích mạch kín tăng làm từ thông qua mạch tăng lên.","Theo định luật Lenz, dòng điện cảm ứng Ic có chiều chạy từ N lên M qua thanh MN để sinh ra từ trường cảm ứng ngược chiều chống lại sự tăng của từ thông.","Độ lớn lực từ cản trở chuyển động của thanh được tính bằng công thức F<sub>t</sub>ừ = <span class=\"fraction\"><span class=\"numerator\">B² · L² · v</span><span class=\"denominator\">R</span></span>."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Diện tích mạch tăng ⇒ từ thông tăng.<br>• <b>Ý b: ĐÚNG.</b> Từ trường cảm ứng phải hướng ra ngoài (chống tăng) ⇒ dòng điện chạy từ N lên M.<br>• <b>Ý c: ĐÚNG.</b> <span class=\"math-sym\">F</span><sub>từ</sub> = <span class=\"math-sym\">I</span><sub>c</sub><span class=\"math-sym\">BL</span> = (<span class=\"math-sym\">e</span><sub>c</sub>/<span class=\"math-sym\">R</span>)<span class=\"math-sym\">BL</span> = (<span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">B · v · L</span><span class=\"denominator\">R</span></span></span>)<span class=\"math-sym\">BL</span> = <span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">B² · L² · v</span><span class=\"denominator\">R</span></span></span>.<br>• <b>Ý d: SAI.</b> Khi đảo chiều B thì chiều dòng cảm ứng sẽ đảo chiều ngược lại (từ M xuống N).","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr20\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\"/>\n    </marker>\n    <marker id=\"arrVel\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#10b981\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">BÀI TOÁN THANH KIM LOẠI TRƯỢT TRÊN RAY TRONG TỪ TRƯỜNG</text>\n\n  <!-- Hai thanh ray song song -->\n  <line x1=\"80\" y1=\"90\" x2=\"460\" y2=\"90\" stroke=\"#94a3b8\" stroke-width=\"4\"/>\n  <line x1=\"80\" y1=\"200\" x2=\"460\" y2=\"200\" stroke=\"#94a3b8\" stroke-width=\"4\"/>\n\n  <!-- Điện trở R nối giữa 2 ray bên trái -->\n  <line x1=\"80\" y1=\"90\" x2=\"80\" y2=\"120\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n  <rect x=\"70\" y=\"120\" width=\"20\" height=\"50\" fill=\"#334155\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n  <text x=\"50\" y=\"150\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"bold\">R</text>\n  <line x1=\"80\" y1=\"170\" x2=\"80\" y2=\"200\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n\n  <!-- Kí hiệu từ trường B đâm vuông góc vào mặt phẳng (dấu nhân x) -->\n  <g fill=\"#06b6d4\" font-size=\"16\" font-family=\"monospace\" font-weight=\"bold\">\n    <text x=\"130\" y=\"130\">⊗</text> <text x=\"130\" y=\"175\">⊗</text>\n    <text x=\"180\" y=\"130\">⊗</text> <text x=\"180\" y=\"175\">⊗</text>\n    <text x=\"230\" y=\"130\">⊗</text> <text x=\"230\" y=\"175\">⊗</text>\n    <text x=\"350\" y=\"130\">⊗</text> <text x=\"350\" y=\"175\">⊗</text>\n    <text x=\"410\" y=\"130\">⊗</text> <text x=\"410\" y=\"175\">⊗</text>\n  </g>\n  <text x=\"230\" y=\"70\" fill=\"#06b6d4\" font-size=\"13\" font-weight=\"bold\">Từ trường đều B (hướng vào)</text>\n\n  <!-- Thanh kim loại MN nằm ngang di chuyển -->\n  <rect x=\"280\" y=\"80\" width=\"16\" height=\"130\" rx=\"4\" fill=\"#fbbf24\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n  <text x=\"282\" y=\"75\" fill=\"#f8fafc\" font-size=\"13\" font-weight=\"bold\">M</text>\n  <text x=\"282\" y=\"225\" fill=\"#f8fafc\" font-size=\"13\" font-weight=\"bold\">N</text>\n\n  <!-- Vận tốc v kéo sang phải -->\n  <line x1=\"296\" y1=\"145\" x2=\"360\" y2=\"145\" stroke=\"#10b981\" stroke-width=\"3\" marker-end=\"url(#arrVel)\"/>\n  <text x=\"340\" y=\"135\" fill=\"#10b981\" font-size=\"13\" font-weight=\"bold\">v</text>\n\n  <!-- Chiều dòng điện I cảm ứng từ N lên M -->\n  <line x1=\"288\" y1=\"170\" x2=\"288\" y2=\"120\" stroke=\"#f43f5e\" stroke-width=\"2.5\" marker-end=\"url(#arr20)\"/>\n  <text x=\"260\" y=\"145\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">I<tspan baseline-shift=\"sub\" font-size=\"70%\">c</tspan></text>\n\n  <!-- Chú thích công thức -->\n  <text x=\"270\" y=\"260\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Suất điện động cảm ứng: |ec| = B·v·L • Lực cản từ: F<tspan baseline-shift=\"sub\" font-size=\"70%\">từ</tspan> = I<tspan baseline-shift=\"sub\" font-size=\"70%\">c</tspan>·B·L</text>\n</svg>"},{"q":"Một máy biến áp có số vòng cuộn sơ cấp là 1000 vòng, cuộn thứ cấp là 200 vòng. Cuộn sơ cấp mắc vào điện áp xoay chiều hiệu dụng 220 V. Mạch thứ cấp tiêu thụ dòng điện hiệu dụng 5 A. Hiệu suất của máy biến áp đạt 90%. Cường độ dòng điện hiệu dụng ở cuộn sơ cấp là:","opts":["1,11 A.","1,00 A.","0,90 A.","1,25 A."],"ans":0,"exp":"• Điện áp thứ cấp: <span class=\"math-sym\">U</span><sub>2</sub> = <span class=\"math-sym\">U</span><sub>1</sub> × (<span class=\"fraction\"><span class=\"numerator\">200</span><span class=\"denominator\">1000</span></span>) = 44 V.<br>• Công suất thứ cấp: <span class=\"math-sym\">P</span><sub>2</sub> = <span class=\"math-sym\">U</span><sub>2</sub> · <span class=\"math-sym\">I</span><sub>2</sub> = 44 × 5 = 220 W.<br>• Hiệu suất: <span class=\"math-sym\">H = P₂ / P₁</span> = 0,90 ⇒ <span class=\"math-sym\">P</span><sub>1</sub> = <span class=\"fraction\"><span class=\"numerator\">220</span><span class=\"denominator\">0</span></span>,90 ≈ 244,4 W.<br>• Cường độ dòng sơ cấp: <span class=\"math-sym\">I</span><sub>1</sub> = <span class=\"math-sym\">P</span><sub>1</sub> / <span class=\"math-sym\">U</span><sub>1</sub> = 244,<span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">220</span></span> ≈ <b>1,11 A</b>.","svgGraph":null}],"21":[{"q":"Hạt nhân nguyên tử được cấu tạo từ các hạt cơ bản nào sau đây?","opts":["Các proton mang điện tích dương và các neutron không mang điện (gọi chung là nucleon).","Các electron mang điện tích âm và các proton mang điện tích dương.","Chỉ gồm các hạt neutron liên kết lại với nhau.","Các hạt electron chuyển động với tốc độ ánh sáng xung quanh tâm."],"ans":0,"exp":"• <b>Cấu tạo hạt nhân:</b> Hạt nhân nguyên tử được tạo thành từ <b>proton (mang điện tích +e)</b> và <b>neutron (không mang điện)</b>, gọi chung là các <b>nucleon</b>.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"pGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#fb7185\"/><stop offset=\"100%\" stop-color=\"#e11d48\"/></radialGradient>\n    <radialGradient id=\"nGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#60a5fa\"/><stop offset=\"100%\" stop-color=\"#2563eb\"/></radialGradient>\n    <radialGradient id=\"eGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#fef08a\"/><stop offset=\"100%\" stop-color=\"#eab308\"/></radialGradient>\n  </defs>\n  <!-- Electron orbits -->\n  <ellipse cx=\"230\" cy=\"105\" rx=\"160\" ry=\"50\" fill=\"none\" stroke=\"rgba(255,255,255,0.15)\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n  <ellipse cx=\"230\" cy=\"105\" rx=\"90\" ry=\"75\" fill=\"none\" stroke=\"rgba(255,255,255,0.15)\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" transform=\"rotate(45 230 105)\"/>\n  <!-- Electrons -->\n  <circle cx=\"70\" cy=\"105\" r=\"5\" fill=\"url(#eGrad)\"><animate attributeName=\"opacity\" values=\"0.6;1;0.6\" dur=\"2s\" repeatCount=\"indefinite\"/></circle>\n  <circle cx=\"390\" cy=\"105\" r=\"5\" fill=\"url(#eGrad)\"/>\n  <!-- Nucleus Glow Container -->\n  <circle cx=\"230\" cy=\"105\" r=\"45\" fill=\"rgba(147,51,234,0.15)\" stroke=\"#a855f7\" stroke-width=\"1.5\"/>\n  <!-- Nucleons cluster -->\n  <g>\n    <!-- Protons -->\n    <circle cx=\"220\" cy=\"95\" r=\"10\" fill=\"url(#pGrad)\"/><text x=\"220\" y=\"98\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">+</text>\n    <circle cx=\"238\" cy=\"115\" r=\"10\" fill=\"url(#pGrad)\"/><text x=\"238\" y=\"118\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">+</text>\n    <circle cx=\"215\" cy=\"118\" r=\"10\" fill=\"url(#pGrad)\"/><text x=\"215\" y=\"121\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" text-anchor=\"middle\">+</text>\n    <!-- Neutrons -->\n    <circle cx=\"238\" cy=\"92\" r=\"10\" fill=\"url(#nGrad)\"/><text x=\"238\" y=\"95\" fill=\"#fff\" font-size=\"9\" font-weight=\"800\" text-anchor=\"middle\">n</text>\n    <circle cx=\"222\" cy=\"110\" r=\"10\" fill=\"url(#nGrad)\"/><text x=\"222\" y=\"113\" fill=\"#fff\" font-size=\"9\" font-weight=\"800\" text-anchor=\"middle\">n</text>\n    <circle cx=\"245\" cy=\"108\" r=\"10\" fill=\"url(#nGrad)\"/><text x=\"245\" y=\"111\" fill=\"#fff\" font-size=\"9\" font-weight=\"800\" text-anchor=\"middle\">n</text>\n  </g>\n  <!-- Legend -->\n  <rect x=\"25\" y=\"20\" width=\"130\" height=\"75\" rx=\"8\" fill=\"rgba(15,23,42,0.85)\" stroke=\"rgba(255,255,255,0.12)\"/>\n  <circle cx=\"45\" cy=\"40\" r=\"7\" fill=\"url(#pGrad)\"/><text x=\"60\" y=\"44\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"700\">Proton (Z, +e)</text>\n  <circle cx=\"45\" cy=\"60\" r=\"7\" fill=\"url(#nGrad)\"/><text x=\"60\" y=\"64\" fill=\"#60a5fa\" font-size=\"11\" font-weight=\"700\">Neutron (N, 0)</text>\n  <circle cx=\"45\" cy=\"80\" r=\"5\" fill=\"url(#eGrad)\"/><text x=\"60\" y=\"84\" fill=\"#fde047\" font-size=\"11\" font-weight=\"700\">Electron (-e)</text>\n  <!-- Caption -->\n  <text x=\"230\" y=\"198\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">Mô hình cấu tạo hạt nhân (Số khối A = Z + N)</text>\n</svg>"},{"q":"Hạt nhân nguyên tử nhôm có ký hiệu là ²⁷₁₃Al. Số lượng proton, neutron và số khối A của hạt nhân này lần lượt là:","opts":["13 proton, 14 neutron và số khối A = 27.","13 proton, 27 neutron và số khối A = 14.","14 proton, 13 neutron và số khối A = 27.","27 proton, 13 neutron và số khối A = 14."],"ans":0,"exp":"• Kí hiệu <span class=\"math-sym\"><sup>A</sup><sub>Z</sub>X</span>:<br>• Số proton: <span class=\"math-sym\">Z</span> = 13.<br>• Số khối: <span class=\"math-sym\">A</span> = 27.<br>• Số neutron: <span class=\"math-sym\">N = A - Z</span> = 27 - 13 = 14.","svgGraph":null},{"q":"Các nguyên tử được gọi là <b>đồng vị</b> của nhau khi hạt nhân của chúng có:","opts":["Cùng số proton Z nhưng khác số neutron N (dẫn tới số khối A khác nhau).","Cùng số neutron N nhưng khác số proton Z.","Cùng số khối A nhưng khác số proton Z.","Cùng khối lượng nhưng tính chất hóa học hoàn toàn khác nhau."],"ans":0,"exp":"• <b>Định nghĩa đồng vị:</b> Các nguyên tử có <b>cùng số proton Z</b> (cùng vị trí trong bảng tuần hoàn hóa học) nhưng có <b>số neutron N khác nhau</b>.","svgGraph":null},{"q":"Xét các đặc trưng kích thước và năng lượng của hạt nhân nguyên tử. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Đơn vị khối lượng nguyên tử u được định nghĩa bằng đúng khối lượng của một nguyên tử cacbon ¹²₆C tự do.","Bán kính của hạt nhân nguyên tử tỉ lệ thuận với căn bậc ba của số khối A (R ≈ 1,2 · 10⁻¹⁵ · A^(<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span>) m).","Kích thước của hạt nhân nguyên tử nhỏ hơn kích thước của toàn bộ nguyên tử khoảng 10.000 đến 100.000 lần.","Theo hệ thức Einstein, một vật có khối lượng nghỉ m luôn mang một năng lượng nghỉ tương ứng là E = m · c²."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Công thức bán kính hạt nhân thực nghiệm.<br>• <b>Ý b: ĐÚNG.</b> Hạt nhân cỡ <span class=\"math-sym\">10⁻¹⁵</span> m, nguyên tử cỡ <span class=\"math-sym\">10⁻¹⁰</span> m.<br>• <b>Ý c: SAI.</b> 1 u bằng <b><span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">12</span></span></b> khối lượng nguyên tử cacbon ¹²₆C.<br>• <b>Ý d: ĐÚNG.</b> Hệ thức tương đương khối lượng - năng lượng của Einstein.","svgGraph":null},{"q":"Hãy ghép các đại lượng ở Cột A với giá trị xấp xỉ chuẩn mực ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Khối lượng của 1 đơn vị u tính theo kg ➔ 1,602 · 10⁻¹⁹ C","Khối lượng của 1 đơn vị u tính theo kg ➔ 1,66055 · 10⁻²⁷ kg","Năng lượng tương đương của 1 u tính theo MeV ➔ 1,602 · 10⁻¹⁹ C","Điện tích nguyên tố e ➔ 1,66055 · 10⁻²⁷ kg"],"ans":0,"exp":"• 1 ghép với B (1 u theo kg).<br>• 2 ghép với C (1 u theo MeV).<br>• 3 ghép với A (Điện tích e).<br>• 4 ghép với D (Khối lượng proton theo u).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Số lượng [0] trong hạt nhân quyết định điện tích của hạt nhân và vị trí của nguyên tố trong bảng hệ thống tuần hoàn hóa học. Tổng số proton và [1] được gọi là số khối A. Hầu hết khối lượng của toàn bộ nguyên tử tập trung ở [2] do khối lượng các electron ở lớp vỏ là không đáng kể.\"</i>","opts":["proton — neutron","không đổi","mạng tinh thể — quang phổ","neutron — proton"],"ans":0,"exp":"• Số <b>proton</b> quyết định số hiệu nguyên tử Z; tổng proton và <b>neutron</b> là số khối A; khối lượng nguyên tử tập trung chủ yếu ở <b>hạt nhân</b>.","svgGraph":null},{"q":"Kĩ thuật chụp cắt lớp phát xạ positron (PET scan) là một công nghệ chẩn đoán y tế tiên tiến giúp phát hiện sớm các tế bào ung thư. Kĩ thuật này sử dụng loại chất nào đưa vào cơ thể bệnh nhân?","opts":["Dược chất phóng xạ chứa đồng vị phóng xạ phát hạt positron (tia β⁺, như ¹⁸₉F).","Nam châm vĩnh cửu siêu nhỏ gắn định vị vào tế bào hồng cầu.","Khối lượng kim loại chì ²⁰⁶₈₂Pb có khả năng cản tia bức xạ ngoài.","Khí hiếm phóng xạ radon hít trực tiếp qua đường hô hấp."],"ans":0,"exp":"• <b>Ứng dụng y học hạt nhân (PET Scan):</b> Bệnh nhân được tiêm một lượng nhỏ dược chất chứa đồng vị phát hạt positron β⁺ (như ¹⁸₉F gắn vào glucose).<br>• Tế bào ung thư phát triển mạnh tiêu thụ nhiều glucose sẽ tập trung nhiều đồng vị này. Hạt positron phát ra khi phân rã gặp ngay electron trong mô sẽ xảy ra hiện tượng hủy cặp (e⁺ + e⁻ → 2γ), tạo ra 2 photon tia gamma bay ngược chiều nhau (180°). Hệ thống máy dò PET ghi lại các tia gamma này để dựng hình ảnh 3D vị trí khối u với độ chính xác cao.","svgGraph":null},{"q":"Bán kính hạt nhân nguyên tử có kích thước cực nhỏ (cỡ 10⁻¹⁵ m) nhưng lại tập trung tới hơn 99,9% khối lượng của toàn bộ nguyên tử. Mật độ khối lượng của vật chất hạt nhân xấp xỉ khoảng bao nhiêu?","opts":["Khoảng 10¹⁷ kg/m³ (một giọt vật chất hạt nhân thể tích 1 cm³ có khối lượng lên tới hàng trăm triệu tấn).","Khoảng 1000 kg/m³ tương đương với khối lượng riêng của nước nguyên chất.","Khoảng 10⁴ kg/m³ tương đương với khối lượng riêng của kim loại chì và vàng.","Khoảng 10⁻¹⁷ kg/m³ vì các hạt vi mô có khối lượng vô cùng nhỏ bé."],"ans":0,"exp":"• <b>Mật độ khối lượng hạt nhân:</b> Thể tích hạt nhân V = <span class=\"fraction\"><span class=\"numerator\">4</span><span class=\"denominator\">3</span></span> · π · R³ ≈ 7,2 · 10⁻⁴⁵ · A m³.<br>• Khối lượng hạt nhân m ≈ A · 1,66 · 10⁻²⁷ kg.<br>• Mật độ khối lượng ρ = <span class=\"fraction\"><span class=\"numerator\">m</span><span class=\"denominator\">V</span></span> ≈ <span class=\"fraction\"><span class=\"numerator\">1,66 · 10⁻²⁷</span><span class=\"denominator\">7,2 · 10⁻⁴⁵</span></span> ≈ 2,3 · 10¹⁷ kg/m³.<br>• Con số khổng lồ này cho thấy vật chất hạt nhân đặc khít một cách phi thường (tương đương mật độ vật chất bên trong các ngôi sao neutron trong vũ trụ).","svgGraph":null},{"q":"Dựa vào sơ đồ mô hình cấu trúc hạt nhân nguyên tử hình bên. Đánh giá tính Đúng/Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Lực hạt nhân có bản chất là lực hấp dẫn giữa các nucleon.","Các proton (p⁺) tích điện dương nằm rất gần nhau trong hạt nhân chịu lực đẩy tĩnh điện Coulomb rất mạnh.","Để hạt nhân tồn tại bền vững, giữa các nucleon phải có lực hút hạt nhân (lực tương tác mạnh) thắng được lực đẩy tĩnh điện.","Lực hạt nhân là lực tương tác có bán kính tác dụng rất ngắn, chỉ có tác dụng trong phạm vi kích thước hạt nhân (khoảng 10⁻¹⁵ m)."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Ở khoảng cách cực ngắn, lực đẩy Coulomb giữa các proton là cực kì lớn.<br>• <b>Ý b: ĐÚNG.</b> Lực hạt nhân là lực liên kết giữ các nucleon lại với nhau.<br>• <b>Ý c: SAI.</b> Lực hạt nhân là <b>lực tương tác mạnh</b>, hoàn toàn không phải lực hấp dẫn hay lực điện từ.<br>• <b>Ý d: ĐÚNG.</b> Ngoài phạm vi <span class=\"math-sym\">10⁻¹⁵</span> m, lực hạt nhân giảm nhanh chóng về 0.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"protGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#f87171\"/>\n      <stop offset=\"100%\" stop-color=\"#b91c1c\"/>\n    </radialGradient>\n    <radialGradient id=\"neutGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"100%\" stop-color=\"#475569\"/>\n    </radialGradient>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">MÔ HÌNH CẤU TRÚC HẠT NHÂN NGUYÊN TỬ (PROTON &amp; NEUTRON)</text>\n\n  <!-- Vùng hạt nhân trung tâm -->\n  <circle cx=\"210\" cy=\"140\" r=\"75\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"6,4\"/>\n  <text x=\"210\" y=\"55\" fill=\"#38bdf8\" font-size=\"11\" text-anchor=\"middle\">Bán kính R ≈ 1,2·10⁻¹⁵·A^(1/3) m</text>\n\n  <!-- Các nucleon -->\n  <!-- Hàng sau -->\n  <circle cx=\"185\" cy=\"115\" r=\"16\" fill=\"url(#neutGrad)\"/>\n  <text x=\"185\" y=\"120\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <circle cx=\"235\" cy=\"115\" r=\"16\" fill=\"url(#protGrad)\"/>\n  <text x=\"235\" y=\"120\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">p⁺</text>\n\n  <circle cx=\"210\" cy=\"95\" r=\"16\" fill=\"url(#neutGrad)\"/>\n  <text x=\"210\" y=\"100\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <!-- Hàng giữa -->\n  <circle cx=\"165\" cy=\"145\" r=\"16\" fill=\"url(#protGrad)\"/>\n  <text x=\"165\" y=\"150\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">p⁺</text>\n\n  <circle cx=\"210\" cy=\"140\" r=\"17\" fill=\"url(#neutGrad)\"/>\n  <text x=\"210\" y=\"145\" fill=\"#f8fafc\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <circle cx=\"255\" cy=\"145\" r=\"16\" fill=\"url(#protGrad)\"/>\n  <text x=\"255\" y=\"150\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">p⁺</text>\n\n  <!-- Hàng trước -->\n  <circle cx=\"185\" cy=\"165\" r=\"16\" fill=\"url(#neutGrad)\"/>\n  <text x=\"185\" y=\"170\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <circle cx=\"235\" cy=\"165\" r=\"16\" fill=\"url(#protGrad)\"/>\n  <text x=\"235\" y=\"170\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">p⁺</text>\n\n  <!-- Bảng ký hiệu hạt nhân bên phải -->\n  <g transform=\"translate(330, 70)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"140\" rx=\"10\" fill=\"rgba(30,41,59,0.9)\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <text x=\"90\" y=\"30\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">KÍ HIỆU HẠT NHÂN</text>\n    <text x=\"90\" y=\"80\" fill=\"#38bdf8\" font-size=\"34\" font-weight=\"800\" text-anchor=\"middle\">X</text>\n    <text x=\"55\" y=\"65\" fill=\"#f43f5e\" font-size=\"18\" font-weight=\"bold\">A</text>\n    <text x=\"55\" y=\"95\" fill=\"#10b981\" font-size=\"18\" font-weight=\"bold\">Z</text>\n    <text x=\"15\" y=\"115\" fill=\"#cbd5e1\" font-size=\"10\">• A = Z + N (Số khối)</text>\n    <text x=\"15\" y=\"130\" fill=\"#cbd5e1\" font-size=\"10\">• Z: Số proton (Điện tích)</text>\n  </g>\n\n  <!-- Chú thích chân -->\n  <text x=\"270\" y=\"255\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Đơn vị khối lượng nguyên tử: 1 u ≈ 1,66055·10⁻²⁷ kg ≈ 931,5 MeV/c²</text>\n</svg>"},{"q":"Trong tự nhiên, nguyên tố carbon có các đồng vị bền là ¹²₆C, ¹³₆C và đồng vị phóng xạ ¹⁴₆C (chu kì bán rã 5730 năm). Khẳng định nào sau đây là đúng khi nói về các đồng vị này?","opts":["Chúng có cùng tính chất hóa học vì cùng có 6 electron lớp vỏ, nhưng khác nhau về độ bền vững hạt nhân.","Chúng có tính chất hóa học hoàn toàn khác nhau vì số lượng neutron quyết định khả năng liên kết phân tử.","Cả ba đồng vị đều tự phát phân rã phóng xạ với cùng tốc độ và chu kì bán rã.","Đồng vị ¹⁴₆C có 8 proton và 6 neutron nằm trong hạt nhân nguyên tử."],"ans":0,"exp":"• <b>Đặc điểm của đồng vị:</b> Các đồng vị của cùng một nguyên tố có cùng số hiệu nguyên tử Z = 6 (cùng số proton và cùng số electron lớp ngoài), do đó chúng có cấu hình electron giống hệt nhau và thể hiện các tính chất hóa học hoàn toàn như nhau.<br>• Tuy nhiên, vì có số neutron N khác nhau (N<sub>C12</sub> = 6, N<sub>C13</sub> = 7, N<sub>C14</sub> = 8) nên khối lượng và độ bền vững hạt nhân của chúng khác nhau: ¹²C, ¹³C bền vững vĩnh cửu, trong khi ¹⁴C không bền và phân rã phóng xạ β⁻.","svgGraph":null}],"22":[{"q":"Độ hụt khối Δm của hạt nhân nguyên tử <sup>A</sup><sub>Z</sub>X được xác định bởi công thức nào sau đây?","opts":["Δm = [Z · mp + (A - Z) · mn] - mX.","Δm = mX - [Z · mp + (A - Z) · mn].","Δm = A · mp - mX.","Δm = Z · mp + A · mn."],"ans":0,"exp":"• <b>Định nghĩa độ hụt khối:</b> Khối lượng của hạt nhân luôn nhỏ hơn tổng khối lượng của các nucleon tự do tạo nên nó: <span class=\"math-sym\">Δm = [Z · m<sub>p</sub> + (A - Z) · m<sub>n</sub>] - m<sub>X</sub> > 0</span>.","svgGraph":null},{"q":"Đại lượng vật lí nào sau đây đặc trưng trực tiếp cho <b>mức độ bền vững</b> của hạt nhân nguyên tử?","opts":["Năng lượng liên kết riêng (E<sub>lkr</sub> = <span class=\"fraction\"><span class=\"numerator\">E<sub>lk</sub></span><span class=\"denominator\">A</span></span>).","Năng lượng liên kết toàn phần (Elk).","Độ hụt khối của hạt nhân (Δm).","Số lượng neutron trong hạt nhân."],"ans":0,"exp":"• <b>Quy tắc bền vững:</b> Năng lượng liên kết toàn phần tỉ lệ với số nucleon, nhưng <b>năng lượng liên kết riêng (<span class=\"math-sym\">E</span><sub>lkr</sub> = <span class=\"math-sym\">E</span><sub>lk</sub> / <span class=\"math-sym\">A</span>)</b> mới là đại lượng đặc trưng cho độ bền vững của hạt nhân (càng lớn thì hạt nhân càng bền).","svgGraph":null},{"q":"Nguồn gốc năng lượng khổng lồ giúp Mặt Trời và các vì sao trong vũ trụ tỏa sáng và bức xạ nhiệt liên tục hàng tỉ năm qua đến từ loại phản ứng nào sau đây?","opts":["Phản ứng nhiệt hạch (tổng hợp các hạt nhân hydro nhẹ thành hạt nhân heli ở nhiệt độ và áp suất cực cao).","Phản ứng phân hạch dây chuyền của các đồng vị urani và thori bên trong lòng Mặt Trời.","Quá trình phân rã phóng xạ tự nhiên của các quặng khoáng chất kim loại nặng ở tâm Mặt Trời.","Phản ứng oxy hóa cháy của khí hydro và carbon dưới áp suất khí quyển Mặt Trời."],"ans":0,"exp":"• <b>Năng lượng Mặt Trời từ Phản ứng nhiệt hạch:</b> Ở vùng tâm của Mặt Trời có nhiệt độ khoảng 15 triệu Kelvin và áp suất hàng trăm tỉ atm.<br>• Dưới điều kiện siêu nhiệt này, các hạt nhân hydro (¹₁H) có động năng cực lớn vượt qua lực đẩy Coulomb tĩnh điện, kết hợp với nhau trong chuỗi phản ứng nhiệt hạch tạo thành hạt nhân heli (⁴₂He) và giải phóng nguồn năng lượng bức xạ khổng lồ khoảng 26,7 MeV cho mỗi hạt heli tạo thành.","svgGraph":null},{"q":"Xét các định luật bảo toàn trong phản ứng hạt nhân. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Trong phản ứng hạt nhân luôn luôn bảo toàn tổng khối lượng nghỉ của các hạt.","Trong mọi phản ứng hạt nhân luôn có sự bảo toàn điện tích (Z) và bảo toàn số khối (A).","Định luật bảo toàn động lượng toàn phần luôn được nghiệm đúng trong phản ứng hạt nhân.","Nếu tổng khối lượng nghỉ của các hạt trước phản ứng lớn hơn tổng khối lượng nghỉ của các hạt sau phản ứng thì phản ứng đó là phản ứng tỏa năng lượng."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Bảo toàn số nucleon A và điện tích Z.<br>• <b>Ý b: SAI.</b> Không có định luật bảo toàn khối lượng nghỉ trong hạt nhân (khối lượng nghỉ chuyển thành động năng hoặc năng lượng photon).<br>• <b>Ý c: ĐÚNG.</b> Bảo toàn động lượng là định luật phổ quát.<br>• <b>Ý d: ĐÚNG.</b> <span class=\"math-sym\">ΔE = (m</span><sub>trước</sub> - <span class=\"math-sym\">m</span><sub>sau</sub>)<span class=\"math-sym\">c² > 0</span> (tỏa năng lượng).","svgGraph":null},{"q":"Hãy ghép khái niệm ở Cột A với biểu thức tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Năng lượng liên kết Elk ➔ <span class=\"fraction\"><span class=\"numerator\">Δm · c²</span><span class=\"denominator\">A</span></span>","Năng lượng liên kết Elk ➔ (mtrước - msau) · c²","Năng lượng liên kết riêng Elkr ➔ <span class=\"fraction\"><span class=\"numerator\">Δm · c²</span><span class=\"denominator\">A</span></span>","Năng lượng tỏa ra của phản ứng hạt nhân ➔ (mtrước - msau) · c²"],"ans":0,"exp":"• 1 ghép với D (Năng lượng liên kết toàn phần).<br>• 2 ghép với A (Năng lượng liên kết riêng).<br>• 3 ghép với B (Năng lượng tỏa phản ứng).<br>• 4 ghép với C (Độ hụt khối).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Lực hạt nhân là lực tương tác [0] liên kết các nucleon trong hạt nhân. Trong một phản ứng hạt nhân tỏa năng lượng, tổng độ hụt khối của các hạt nhân sinh ra sau phản ứng [1] tổng độ hụt khối của các hạt nhân trước phản ứng, đồng thời các hạt nhân sản phẩm có xu hướng [2] hơn.\"</i>","opts":["mạnh — lớn hơn","không đổi","nhỏ hơn — kém bền","lớn hơn — mạnh"],"ans":0,"exp":"• Lực hạt nhân là tương tác <b>mạnh</b>. Khi tỏa năng lượng, độ hụt khối sau <b>lớn hơn</b> độ hụt khối trước và sản phẩm sinh ra <b>bền vững</b> hơn.","svgGraph":null},{"q":"Cho khối lượng hạt nhân ⁴₂He là 4,0015 u; mp = 1,00728 u; mn = 1,00866 u. Lấy 1 u = 931,5 MeV/c². Năng lượng liên kết riêng của hạt nhân ⁴₂He là:","opts":["7,07 MeV/nucleon.","28,3 MeV/nucleon.","14,1 MeV/nucleon.","3,53 MeV/nucleon."],"ans":0,"exp":"• Độ hụt khối: <span class=\"math-sym\">Δm</span> = 2 × 1,00728 + 2 × 1,00866 - 4,0015 = 0,03038 u.<br>• Năng lượng liên kết: <span class=\"math-sym\">E</span><sub>lk</sub> = 0,03038 × 931,5 ≈ 28,30 MeV.<br>• Năng lượng liên kết riêng: <span class=\"math-sym\">E</span><sub>lkr</sub> = 28,<span class=\"fraction\"><span class=\"numerator\">30</span><span class=\"denominator\">4</span></span> ≈ <b>7,07 MeV/nucleon</b>.","svgGraph":null},{"q":"Trên đường cong năng lượng liên kết riêng theo số khối A, các hạt nhân có số khối trong khoảng 50 < A < 70 (đặc biệt là sắt ⁵⁶₂₆Fe) có năng lượng liên kết riêng đạt cực đại (khoảng 8,8 MeV/nucleon). Ý nghĩa vật lí của đặc điểm này là gì?","opts":["Hạt nhân ⁵⁶₂₆Fe bền vững nhất trong tự nhiên, khó bị phá vỡ nhất, là 'điểm dừng' của quá trình nhiệt hạch trong các ngôi sao già.","Hạt nhân ⁵⁶₂₆Fe kém bền vững nhất và rất dễ dàng tự phát nổ phân hạch ở điều kiện thường.","Hạt nhân sắt có khả năng tự phát nổ nhiệt hạch để sinh ra các nguyên tố nhẹ hơn như hydro.","Năng lượng liên kết của toàn bộ hạt nhân sắt nhỏ hơn năng lượng liên kết của một hạt proton đơn lẻ."],"ans":0,"exp":"• <b>Độ bền vững của hạt nhân:</b> Năng lượng liên kết riêng E<sub>lkr</sub> = <span class=\"fraction\"><span class=\"numerator\">E<sub>lk</sub></span><span class=\"denominator\">A</span></span> đặc trưng cho mức độ bền vững của hạt nhân: E<sub>lkr</sub> càng lớn thì hạt nhân càng bền chặt.<br>• Với giá trị cực đại ≈ 8,8 MeV/nucleon, hạt nhân sắt ⁵⁶₂₆Fe là một trong những hạt nhân bền vững nhất trong vũ trụ. Các phản ứng nhiệt hạch trong lõi các ngôi sao chỉ có thể sinh năng lượng đến khi tạo ra sắt thì dừng lại; để tạo ra các nguyên tố nặng hơn sắt cần năng lượng từ các vụ nổ siêu tân tinh (supernova).","svgGraph":null},{"q":"Quan sát đường cong năng lượng liên kết riêng Elkr theo số khối A hình bên. Đánh giá tính Đúng/Sai của các nhận định sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Năng lượng liên kết của hạt nhân ²³⁸U nhỏ hơn năng lượng liên kết của hạt nhân ⁵⁶Fe.","Các hạt nhân ở hai đầu đồ thị (rất nhẹ như H và rất nặng như U) đều có năng lượng liên kết riêng nhỏ hơn các hạt nhân ở vùng giữa.","Hạt nhân sắt ⁵⁶₂₆Fe ở vị trí đỉnh cao nhất của đồ thị nên là một trong những hạt nhân bền vững nhất trong tự nhiên.","Quá trình phân hạch hạt nhân urani ²³⁸U và nhiệt hạch hạt nhân hiđrô đều tạo ra các hạt nhân mới có năng lượng liên kết riêng lớn hơn nên đều tỏa năng lượng."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Đồ thị hình chuông lệch, hai đầu thấp hơn đỉnh giữa.<br>• <b>Ý b: ĐÚNG.</b> Fe-56 có <span class=\"math-sym\">E</span><sub>lkr</sub> cực đại ≈ 8,8 MeV/nu.<br>• <b>Ý c: ĐÚNG.</b> Cả hai phản ứng đều chuyển dịch về phía vùng hạt nhân bền hơn nên đều toả năng lượng cực lớn.<br>• <b>Ý d: SAI.</b> Năng lượng liên kết toàn phần <span class=\"math-sym\">E</span><sub>lk</sub> = <span class=\"math-sym\">A · E</span><sub>lkr</sub>. U-238 có <span class=\"math-sym\">E</span><sub>lk</sub> ≈ 238 × 7,6 ≈ 1800 MeV lớn hơn nhiều so với Fe-56 (<span class=\"math-sym\">E</span><sub>lk</sub> ≈ 56 × 8,8 ≈ 490 MeV).","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr22\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐƯỜNG CONG NĂNG LƯỢNG LIÊN KẾT RIÊNG THEO SỐ KHỐI A</text>\n\n  <!-- Hệ trục Elkr theo A -->\n  <line x1=\"50\" y1=\"230\" x2=\"490\" y2=\"230\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr22)\"/>\n  <line x1=\"50\" y1=\"230\" x2=\"50\" y2=\"35\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr22)\"/>\n  <text x=\"475\" y=\"250\" fill=\"#94a3b8\" font-size=\"13\">Số khối A</text>\n  <text x=\"15\" y=\"45\" fill=\"#38bdf8\" font-size=\"12\">Elkr (MeV/nu)</text>\n  <text x=\"35\" y=\"245\" fill=\"#94a3b8\" font-size=\"12\">0</text>\n\n  <!-- Vùng hạt nhân bền vững nhất quanh Fe (A = 50 - 70) -->\n  <rect x=\"140\" y=\"50\" width=\"80\" height=\"180\" fill=\"rgba(16,185,129,0.15)\" stroke=\"none\"/>\n  <text x=\"180\" y=\"70\" fill=\"#10b981\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Vùng bền vững nhất</text>\n\n  <!-- Đường cong Elkr -->\n  <!-- Bắt đầu từ dơteri (A=2) ~ 1.1 MeV, lên He (A=4) ~ 7.1 MeV, đạt đỉnh Fe (A=56) ~ 8.8 MeV, giảm dần tới U (A=238) ~ 7.6 MeV -->\n  <path d=\"M 55,215 Q 70,100 80,105 Q 100,120 130,65 Q 180,55 240,65 Q 350,90 470,95\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n\n  <!-- Điểm Fe-56 đỉnh cực đại -->\n  <circle cx=\"180\" cy=\"55\" r=\"5\" fill=\"#f43f5e\"/>\n  <line x1=\"180\" y1=\"55\" x2=\"180\" y2=\"230\" stroke=\"#f43f5e\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n  <text x=\"180\" y=\"45\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">⁵⁶₂₆Fe (~8,8 MeV)</text>\n  <text x=\"175\" y=\"248\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">56</text>\n\n  <!-- Điểm U-238 -->\n  <circle cx=\"470\" cy=\"95\" r=\"5\" fill=\"#fbbf24\"/>\n  <line x1=\"470\" y1=\"95\" x2=\"470\" y2=\"230\" stroke=\"#fbbf24\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\"/>\n  <text x=\"470\" y=\"85\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">²³⁸U (~7,6 MeV)</text>\n  <text x=\"460\" y=\"248\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">238</text>\n\n  <!-- Điểm He-4 -->\n  <circle cx=\"80\" cy=\"105\" r=\"4.5\" fill=\"#38bdf8\"/>\n  <text x=\"80\" y=\"95\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">⁴He</text>\n  <text x=\"75\" y=\"248\" fill=\"#94a3b8\" font-size=\"11\">4</text>\n\n  <!-- Ghi chú phân hạch & nhiệt hạch -->\n  <text x=\"90\" y=\"160\" fill=\"#06b6d4\" font-size=\"11\" font-weight=\"bold\">← Nhiệt hạch (tổng hợp hạt nhẹ)</text>\n  <text x=\"310\" y=\"140\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">Phân hạch (vỡ hạt nặng) →</text>\n</svg>"},{"q":"Vũ khí hạt nhân bao gồm bom nguyên tử (bom A) và bom nhiệt hạch (bom H hay bom khinh khí). Sự khác biệt cốt lõi về nguyên lí giải phóng năng lượng giữa hai loại vũ khí này là gì?","opts":["Bom A dựa trên phân hạch dây chuyền hạt nhân nặng (²³⁵U), bom H dựa trên nhiệt hạch hạt nhân hydro được kích hoạt bởi bom A.","Bom nguyên tử không phát ra phóng xạ nguy hiểm, còn bom nhiệt hạch chỉ phát ra sóng âm thanh xung kích.","Bom nhiệt hạch chỉ dùng thuốc nổ hóa học TNT thông thường nén khí để tạo ra áp suất cao.","Bom nguyên tử giải phóng năng lượng lớn hơn bom nhiệt hạch hàng nghìn lần với cùng khối lượng."],"ans":0,"exp":"• <b>Cơ chế của bom hạt nhân:</b><br>1. <i>Bom nguyên tử (Bom A):</i> Dựa trên phản ứng phân hạch dây chuyền không điều khiển của các hạt nhân nặng (²³⁵U hoặc ²³⁹Pu) khi đạt khối lượng tới hạn.<br>2. <i>Bom nhiệt hạch (Bom H):</i> Dựa trên phản ứng tổng hợp hạt nhân các đồng vị hydro (²₁H + ³₁H → ⁴₂He + ¹₀n). Để đạt nhiệt độ hàng chục triệu độ kích hoạt phản ứng nhiệt hạch, người ta phải dùng một quả bom phân hạch (bom A) làm ngòi nổ. Bom H có sức tàn phá lớn gấp hàng trăm đến hàng nghìn lần bom A.","svgGraph":null}],"23":[{"q":"Hiện tượng phóng xạ là quá trình biến đổi hạt nhân có đặc điểm bản chất nào sau đây?","opts":["Quá trình tự phát của một hạt nhân không bền vững tự phân rã, giải phóng các tia bức xạ và biến đổi thành hạt nhân khác.","Hiện tượng hạt nhân bị kích thích phát quang khi bị chiếu ánh sáng tử ngoại.","Quá trình hai hạt nhân nhẹ va chạm kết hợp thành hạt nhân nặng hơn ở nhiệt độ cao.","Hiện tượng bắn phá hạt nhân bằng chùm electron năng lượng cao trong máy gia tốc."],"ans":0,"exp":"• <b>Bản chất hiện tượng phóng xạ:</b> Là quá trình <b>tự phát và ngẫu nhiên</b> từ bên trong hạt nhân, hoàn toàn không phụ thuộc vào các điều kiện môi trường bên ngoài như nhiệt độ, áp suất hay liên kết hóa học.","svgGraph":"<svg viewBox=\"0 0 460 210\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Radioactive source Lead box -->\n  <rect x=\"30\" y=\"80\" width=\"50\" height=\"50\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"2\" rx=\"4\"/>\n  <rect x=\"65\" y=\"100\" width=\"20\" height=\"10\" fill=\"#0f172a\"/>\n  <circle cx=\"50\" cy=\"105\" r=\"8\" fill=\"#f59e0b\"/>\n  <text x=\"55\" y=\"145\" fill=\"#cbd5e1\" font-size=\"10\" text-anchor=\"middle\">Nguồn phóng xạ</text>\n  <!-- Capacitor plates -->\n  <!-- Positive plate (top) -->\n  <rect x=\"130\" y=\"25\" width=\"200\" height=\"12\" fill=\"#ef4444\" rx=\"3\"/>\n  <text x=\"230\" y=\"20\" fill=\"#ef4444\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">BẢN CỰC DƯƠNG (+)</text>\n  <!-- Negative plate (bottom) -->\n  <rect x=\"130\" y=\"165\" width=\"200\" height=\"12\" fill=\"#3b82f6\" rx=\"3\"/>\n  <text x=\"230\" y=\"192\" fill=\"#3b82f6\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">BẢN CỰC ÂM (-)</text>\n  <!-- Radiation rays -->\n  <!-- Beta- (curves towards positive plate) -->\n  <path d=\"M 80,105 Q 160,105 240,45\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n  <polygon points=\"245,42 233,43 238,51\" fill=\"#f59e0b\"/>\n  <text x=\"255\" y=\"45\" fill=\"#f59e0b\" font-size=\"13\" font-weight=\"800\">Tia β⁻ (lệch nhiều về +)</text>\n  <!-- Gamma (straight line, not deflected) -->\n  <line x1=\"80\" y1=\"105\" x2=\"360\" y2=\"105\" stroke=\"#10b981\" stroke-width=\"2.5\" stroke-dasharray=\"5,2\"/>\n  <polygon points=\"368,105 356,99 356,111\" fill=\"#10b981\"/>\n  <text x=\"375\" y=\"109\" fill=\"#10b981\" font-size=\"13\" font-weight=\"800\">Tia γ (không lệch)</text>\n  <!-- Alpha (curves gently towards negative plate) -->\n  <path d=\"M 80,105 Q 180,105 260,155\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3\"/>\n  <polygon points=\"266,159 254,153 259,161\" fill=\"#06b6d4\"/>\n  <text x=\"275\" y=\"163\" fill=\"#06b6d4\" font-size=\"13\" font-weight=\"800\">Tia α (lệch ít về -)</text>\n</svg>"},{"q":"Tia phóng xạ nào sau đây có bản chất là sóng điện từ có bước sóng cực ngắn (mang năng lượng photon rất cao và có khả năng đâm xuyên mạnh nhất)?","opts":["Tia gamma (γ).","Tia alpha (α).","Tia bêta trừ (β⁻).","Tia bêta cộng (β⁺)."],"ans":0,"exp":"• <b>Tia gamma (γ)</b> là sóng điện từ có bước sóng cực ngắn (dưới 10⁻¹¹ m), không mang điện tích, đâm xuyên cực kì mạnh (có thể xuyên qua lớp chì dày hàng chục cm).","svgGraph":null},{"q":"Chu kỳ bán rã T của một chất phóng xạ là khoảng thời gian để:","opts":["Một nửa số lượng hạt nhân của chất phóng xạ đó bị phân rã biến đổi thành chất khác.","Toàn bộ khối lượng chất phóng xạ bị tiêu hủy hoàn toàn.","Độ phóng xạ của chất tăng lên gấp đôi.","Khối lượng chất phóng xạ giảm đi <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span>."],"ans":0,"exp":"• <b>Định nghĩa chu kỳ bán rã T:</b> Là khoảng thời gian mà sau đó số hạt nhân phóng xạ (hoặc độ phóng xạ) giảm đi <b>một nửa (còn lại 50%)</b>.","svgGraph":null},{"q":"Xét các tia phóng xạ và định luật phân rã phóng xạ. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Tia bêta trừ (β⁻) là dòng các electron (⁰₋₁e) phóng ra từ lớp vỏ electron của nguyên tử.","Tia alpha (α) thực chất là dòng các hạt nhân heli ⁴₂He, có khả năng ion hóa chất khí rất mạnh nhưng khả năng đâm xuyên kém (bị chặn bởi tờ giấy dày).","Hằng số phóng xạ λ liên hệ với chu kỳ bán rã T theo công thức λ = <span class=\"fraction\"><span class=\"numerator\">ln 2</span><span class=\"denominator\">T</span></span> ≈ <span class=\"fraction\"><span class=\"numerator\">0,693</span><span class=\"denominator\">T</span></span>.","Phương pháp định tuổi bằng đồng vị phóng xạ cacbon ¹⁴₆C (chu kỳ bán rã khoảng 5730 năm) được ứng dụng rộng rãi trong khảo cổ học để xác định niên đại cổ vật hữu cơ."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Bản chất tia alpha.<br>• <b>Ý b: SAI.</b> Tia β⁻ phóng ra <b>từ bên trong hạt nhân</b> do quá trình biến đổi neutron thành proton (<span class=\"math-sym\">n → p + e⁻ + ν_e</span>), không phải từ lớp vỏ electron.<br>• <b>Ý c: ĐÚNG.</b> Công thức <span class=\"math-sym\">λ = <span class=\"fraction\"><span class=\"numerator\">ln 2</span><span class=\"denominator\">T</span></span></span>.<br>• <b>Ý d: ĐÚNG.</b> Ứng dụng định tuổi bằng C-14 trong khảo cổ.","svgGraph":null},{"q":"Hãy ghép các tia phóng xạ ở Cột A với bản chất vật lí chuẩn xác ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Tia alpha (α) ➔ Sóng điện từ có bước sóng cực ngắn mang năng lượng rất cao.","Tia alpha (α) ➔ Dòng các hạt pozitron (electron dương ⁰₁e).","Tia bêta trừ (β⁻) ➔ Sóng điện từ có bước sóng cực ngắn mang năng lượng rất cao.","Tia bêta cộng (β⁺) ➔ Dòng các hạt pozitron (electron dương ⁰₁e)."],"ans":0,"exp":"• 1 ghép với C (Tia α là hạt nhân He).<br>• 2 ghép với D (Tia β⁻ là hạt electron).<br>• 3 ghép với B (Tia β⁺ là hạt pozitron).<br>• 4 ghép với A (Tia γ là photon sóng điện từ).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Số hạt nhân phóng xạ còn lại sau thời gian t tuân theo định luật hàm mũ N(t) = N₀ · 2<sup>-<span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup>. Sau thời gian bằng [0] chu kỳ bán rã thì khối lượng chất phóng xạ còn lại đúng bằng <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">8</span></span> khối lượng ban đầu. Độ phóng xạ H đặc trưng cho số phân rã trong 1 giây, có đơn vị SI là [1] (1 phân rã/giây) hoặc đơn vị truyền thống [2].\"</i>","opts":["3 — Becquerel (Bq)","không đổi","Tesla — Weber","Becquerel (Bq) — 3"],"ans":0,"exp":"• Sau <span class=\"math-sym\">t = 3T</span> thì <span class=\"math-sym\">N = N₀ / 2³ = N₀ / 8</span>. Đơn vị độ phóng xạ là <b>Bq</b> (SI) hoặc <b>Ci</b> (1 Ci = 3,7 · 10¹⁰ Bq).","svgGraph":null},{"q":"Một chất phóng xạ có chu kỳ bán rã là 14 ngày. Ban đầu có 80 mg chất đó. Khối lượng chất phóng xạ còn lại sau 42 ngày là:","opts":["10 mg.","20 mg.","40 mg.","5 mg."],"ans":0,"exp":"• Số chu kỳ bán rã đã trôi qua: <span class=\"math-sym\">k = <span class=\"fraction\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">42</span><span class=\"denominator\">14</span></span> = 3 chu kỳ.<br>• Khối lượng còn lại: <span class=\"math-sym\">m = <span class=\"fraction\"><span class=\"numerator\">m₀</span><span class=\"denominator\">2³</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">80</span><span class=\"denominator\">8</span></span> = <b>10 mg</b>.","svgGraph":null},{"q":"Hạt nhân poloni ²¹⁰₈₄Po phóng xạ alpha và biến đổi thành hạt nhân chì Pb bền vững theo phương trình: ²¹⁰₈₄Po → ⁴₂He + <sup>A</sup><sub>Z</sub>Pb. Kí hiệu của hạt nhân chì sinh ra là:","opts":["²⁰⁶₈₂Pb.","²⁰⁸₈₂Pb.","²¹⁴₈₆Pb.","²⁰⁶₈₀Pb."],"ans":0,"exp":"• Bảo toàn số khối: <span class=\"math-sym\">A</span> = 210 - 4 = 206.<br>• Bảo toàn điện tích: <span class=\"math-sym\">Z</span> = 84 - 2 = 82.<br>• Hạt nhân tạo thành là <b>²⁰⁶₈₂Pb</b>.","svgGraph":null},{"q":"Quan sát đồ thị hàm mũ phân rã phóng xạ N(t) theo chu kỳ bán rã T hình bên. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu tăng nhiệt độ của mẫu phóng xạ lên 1000°C thì chu kỳ bán rã T sẽ bị rút ngắn đi một nửa.","Tại thời điểm t = T, số hạt nhân mẹ chưa bị phân rã chiếm 50% số hạt ban đầu N₀.","Tại thời điểm t = 2T, số hạt nhân con mới sinh ra chiếm 75% tổng số hạt ban đầu.","Đồ thị phân rã tiệm cận tới trục hoành, chứng tỏ về mặt lí thuyết sau thời gian vô cùng lớn chất phóng xạ mới phân rã hết hoàn toàn."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Sau 1 chu kỳ còn 50% hạt mẹ.<br>• <b>Ý b: ĐÚNG.</b> Sau 2 chu kỳ còn 25% hạt mẹ ⇒ đã phân rã tạo thành 75% hạt con.<br>• <b>Ý c: ĐÚNG.</b> Hàm <span class=\"math-sym\">e^(-λt)</span> tiệm cận 0 khi <span class=\"math-sym\">t → ∞</span>.<br>• <b>Ý d: SAI.</b> Phóng xạ là hiện tượng tự phát từ bên trong hạt nhân, hoàn toàn không phụ thuộc nhiệt độ hay áp suất.","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr23\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐỒ THỊ ĐỊNH LUẬT PHÂN RÃ PHÓNG XẠ N(t) = N₀ · 2^(-t/T)</text>\n\n  <!-- Hệ trục N theo t -->\n  <line x1=\"60\" y1=\"230\" x2=\"490\" y2=\"230\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr23)\"/>\n  <line x1=\"60\" y1=\"230\" x2=\"60\" y2=\"35\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr23)\"/>\n  <text x=\"475\" y=\"250\" fill=\"#94a3b8\" font-size=\"13\">Thời gian t</text>\n  <text x=\"25\" y=\"45\" fill=\"#38bdf8\" font-size=\"12\">Số hạt N(t)</text>\n  <text x=\"45\" y=\"245\" fill=\"#94a3b8\" font-size=\"12\">0</text>\n\n  <!-- Đường cong hàm mũ phân rã N(t) -->\n  <!-- t=0: N=N0(200); t=T: N=N0/2(100); t=2T: N=N0/4(50); t=3T: N=N0/8(25); t=4T: N=N0/16(12.5) -->\n  <path d=\"M 60,60 C 120,110 160,145 200,145 C 240,145 280,185 300,185 C 340,185 370,210 400,210 C 430,210 460,220 480,222\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n\n  <!-- Mốc t = 0 -->\n  <text x=\"35\" y=\"65\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">N₀</text>\n\n  <!-- Mốc t = T (145 px từ trục hoành = 230 - 85) -->\n  <line x1=\"60\" y1=\"145\" x2=\"160\" y2=\"145\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"160\" y1=\"145\" x2=\"160\" y2=\"230\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <circle cx=\"160\" cy=\"145\" r=\"5\" fill=\"#f43f5e\"/>\n  <text x=\"20\" y=\"150\" fill=\"#cbd5e1\" font-size=\"12\">N₀/2</text>\n  <text x=\"155\" y=\"248\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">T</text>\n\n  <!-- Mốc t = 2T -->\n  <line x1=\"60\" y1=\"188\" x2=\"260\" y2=\"188\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"260\" y1=\"188\" x2=\"260\" y2=\"230\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <circle cx=\"260\" cy=\"188\" r=\"5\" fill=\"#f43f5e\"/>\n  <text x=\"20\" y=\"192\" fill=\"#cbd5e1\" font-size=\"12\">N₀/4</text>\n  <text x=\"250\" y=\"248\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">2T</text>\n\n  <!-- Mốc t = 3T -->\n  <line x1=\"60\" y1=\"210\" x2=\"360\" y2=\"210\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"360\" y1=\"210\" x2=\"360\" y2=\"230\" stroke=\"#475569\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n  <circle cx=\"360\" cy=\"210\" r=\"5\" fill=\"#f43f5e\"/>\n  <text x=\"20\" y=\"214\" fill=\"#cbd5e1\" font-size=\"12\">N₀/8</text>\n  <text x=\"350\" y=\"248\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">3T</text>\n\n  <!-- Hộp chú thích chu kỳ bán rã -->\n  <rect x=\"270\" y=\"55\" width=\"220\" height=\"70\" rx=\"8\" fill=\"rgba(30,41,59,0.9)\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <text x=\"280\" y=\"78\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">• Chu kỳ bán rã T = ln 2 / λ</text>\n  <text x=\"280\" y=\"98\" fill=\"#cbd5e1\" font-size=\"11\">Cứ sau mỗi chu kỳ T, số hạt nhân</text>\n  <text x=\"280\" y=\"114\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">mẹ giảm đi một nửa (còn lại 50%).</text>\n</svg>"},{"q":"Một mẫu gỗ cổ khai quật từ một di chỉ khảo cổ học có độ phóng xạ của đồng vị ¹⁴₆C bằng 25% độ phóng xạ của mẫu gỗ tươi cùng loại cùng khối lượng. Biết chu kỳ bán rã của ¹⁴C là 5730 năm. Tuổi của mẫu gỗ cổ đó là:","opts":["11460 năm.","5730 năm.","17190 năm.","22920 năm."],"ans":0,"exp":"• <span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">H(t)</span><span class=\"denominator\">H₀</span></span></span> = 25% = <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">4</span></span> = <span class=\"math-sym\">2⁻² ⇒ t / T</span> = 2.<br>• Tuổi mẫu gỗ: <span class=\"math-sym\">t = 2T</span> = 2 × 5730 = <b>11460 năm</b>.","svgGraph":null}],"24":[{"q":"Phản ứng phân hạch hạt nhân là quá trình:","opts":["Một hạt nhân nặng hấp thụ một neutron chậm rồi vỡ thành hai hạt nhân nhẹ hơn và giải phóng thêm các neutron thứ cấp kèm năng lượng lớn.","Hai hạt nhân nhẹ kết hợp lại với nhau thành hạt nhân nặng hơn ở nhiệt độ hàng trăm triệu độ.","Hạt nhân tự phát phóng ra các tia alpha để trở nên bền vững hơn.","Hạt nhân hấp thụ photon gamma để biến đổi điện tích."],"ans":0,"exp":"• <b>Định nghĩa phản ứng phân hạch:</b> Là phản ứng trong đó một <b>hạt nhân rất nặng</b> (như ²³⁵U, ²³⁹Pu) hấp thụ một neutron nhiệt (chậm), kích hoạt vỡ thành 2 mảnh nhẹ hơn và kèm theo 2 đến 3 neutron mới.","svgGraph":null},{"q":"Để duy trì phản ứng phân hạch dây chuyền tự kiểm soát được và ổn định trong lò phản ứng của nhà máy điện hạt nhân, hệ số nhân neutron k phải được duy trì ở giá trị:","opts":["k = 1 (trạng thái tới hạn).","k > 1 (trạng thái trên tới hạn).","k < 1 (trạng thái dưới tới hạn).","k = 0."],"ans":0,"exp":"• <b>Các chế độ phản ứng dây chuyền:</b><br>• <span class=\"math-sym\">k = 1</span>: Số neutron sinh ra trung bình bằng số neutron tiêu hao, phản ứng diễn ra <b>ổn định và kiểm soát được</b> trong lò phản ứng điện hạt nhân.<br>• <span class=\"math-sym\">k > 1</span>: Bùng nổ mãnh liệt (bom nguyên tử).<br>• <span class=\"math-sym\">k < 1</span>: Phản ứng tự tắt.","svgGraph":null},{"q":"Phản ứng nhiệt hạch là phản ứng tổng hợp hai hạt nhân rất nhẹ thành hạt nhân nặng hơn. Điều kiện cốt lõi để phản ứng nhiệt hạch có thể xảy ra trong thực tế là:","opts":["Nhiệt độ phải cực kì cao (hàng chục đến hàng trăm triệu độ) để các hạt nhân có động năng đủ lớn thắng được lực đẩy tĩnh điện Coulomb.","Nhiệt độ phải hạ xuống gần độ không tuyệt đối 0 K.","Phải có từ trường ngoài cực mạnh hướng dọc trục lò phản ứng.","Phải dùng tia laser công suất thấp chiếu liên tục nhiều năm."],"ans":0,"exp":"• Để hai hạt nhân tích điện dương thắng được lực đẩy tĩnh điện và tiến vào khoảng cách <span class=\"math-sym\">10⁻¹⁵</span> m (tầm tác dụng của lực hạt nhân), chúng cần động năng nhiệt cực lớn, tương ứng nhiệt độ <b>hàng trăm triệu Kelvin</b>.","svgGraph":null},{"q":"Xét ưu điểm và an toàn năng lượng hạt nhân. Mỗi nhận định sau đây là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Năng lượng tỏa ra từ Mặt Trời và các ngôi sao trong vũ trụ có nguồn gốc chủ yếu từ các phản ứng phân hạch dây chuyền của urani.","Năng lượng nhiệt hạch là nguồn năng lượng sạch, nguồn nhiên liệu hiđrô gần như vô tận trong nước biển và không tạo ra chất thải phóng xạ nguy hại lâu dài.","Trong lò phản ứng hạt nhân, các thanh điều khiển làm bằng chất hấp thụ neutron mạnh (như Bo hoặc Cadimi) được dùng để điều chỉnh hệ số k.","Chất làm chậm (như nước nặng D₂O hoặc than chì) trong lò phản ứng có tác dụng giảm tốc độ của neutron nhanh thành neutron nhiệt."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Nhiệt hạch là nguồn năng lượng tương lai sạch và dồi dào.<br>• <b>Ý b: ĐÚNG.</b> Thanh Bo / Cd hấp thụ neutron để kiểm soát tốc độ phản ứng.<br>• <b>Ý c: SAI.</b> Năng lượng Mặt Trời có nguồn gốc từ <b>phản ứng nhiệt hạch</b> (tổng hợp hiđrô thành heli), không phải phân hạch urani.<br>• <b>Ý d: ĐÚNG.</b> Neutron nhiệt dễ bị hấp thụ bởi ²³⁵U hơn neutron nhanh.","svgGraph":null},{"q":"Hãy ghép thuật ngữ/bộ phận ở Cột A với chức năng tương ứng trong công nghệ hạt nhân ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Chất làm chậm (nước nặng, than chì) ➔ Hấp thụ các neutron dư thừa để khống chế hệ số nhân neutron k = 1.","Chất làm chậm (nước nặng, than chì) ➔ Làm giảm động năng của neutron nhanh thành neutron nhiệt dễ gây phân hạch.","Thanh điều khiển (Bo, Cadimi) ➔ Hấp thụ các neutron dư thừa để khống chế hệ số nhân neutron k = 1.","Vỏ bọc an toàn bê tông cốt thép ➔ Làm giảm động năng của neutron nhanh thành neutron nhiệt dễ gây phân hạch."],"ans":0,"exp":"• 1 ghép với B (Chất làm chậm giảm tốc neutron).<br>• 2 ghép với A (Thanh điều khiển hấp thụ neutron).<br>• 3 ghép với C (Vỏ bê tông chắn bức xạ).<br>• 4 ghép với D (Chất tải nhiệt truyền nhiệt quay tuabin).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Mỗi phân hạch hạt nhân ²³⁵U tỏa ra năng lượng khổng lồ khoảng [0] MeV. Khối lượng nhiên liệu tối thiểu để phản ứng phân hạch dây chuyền có thể duy trì tự phát được gọi là [1]. Nếu khối lượng nhỏ hơn mức này thì phần lớn neutron sẽ [2] ra ngoài không gian trước khi kịp gây phân hạch tiếp theo.\"</i>","opts":["200 — khối lượng tới hạn","không đổi","khối lượng nghỉ — hấp thụ","khối lượng tới hạn — 200"],"ans":0,"exp":"• Mỗi phân hạch toả ~<b>200</b> MeV. Khối lượng tối thiểu là <b>khối lượng tới hạn</b>, nếu nhỏ hơn neutron sẽ <b>thoát</b> ra ngoài.","svgGraph":null},{"q":"Biết mỗi phân hạch hạt nhân ²³⁵U tỏa ra năng lượng trung bình là 200 MeV. Cho số Avogadro NA = 6,022 · 10²³ mol⁻¹ và 1 eV = 1,6 · 10⁻¹⁹ J. Năng lượng tỏa ra khi phân hạch hoàn toàn 1,0 kg ²³⁵U xấp xỉ bằng:","opts":["8,2 · 10¹³ J (tương đương đốt cháy hàng ngàn tấn than đá).","2,5 · 10⁸ J.","5,1 · 10¹⁰ J.","1,6 · 10¹⁵ J."],"ans":0,"exp":"• Số hạt nhân trong 1 kg: <span class=\"math-sym\">N</span> = (<span class=\"fraction\"><span class=\"numerator\">1000</span><span class=\"denominator\">235</span></span>) × 6,022 · 10²³ ≈ 2,56 · 10²⁴ hạt.<br>• Năng lượng tỏa ra: <span class=\"math-sym\">E</span> = 2,56 · 10²⁴ × 200 × 10⁶ × 1,6 · 10⁻¹⁹ ≈ <b>8,2 · 10¹³ J</b>.","svgGraph":null},{"q":"Ưu thế vượt trội lớn nhất của việc phát triển điện hạt nhân so với các nhà máy nhiệt điện đốt nhiên liệu hóa thạch truyền thống (than đá, dầu khí) là:","opts":["Mật độ năng lượng cực kì cao và không phát thải khí nhà kính (CO₂) gây biến đổi khí hậu trong quá trình vận hành.","Chi phí xây dựng ban đầu của nhà máy điện hạt nhân rẻ hơn rất nhiều.","Không bao giờ sinh ra chất thải sau quá trình sản xuất điện.","Có thể xây dựng ở bất kì vị trí nào mà không cần nguồn nước làm mát."],"ans":0,"exp":"• <b>Ưu điểm cốt lõi của điện hạt nhân:</b> Năng lượng hạt nhân có mật độ năng lượng siêu đậm đặc, vận hành liên tục ổn định (công suất nền) và <b>không phát thải khí CO₂ hay SO₂</b> gây ô nhiễm không khí.","svgGraph":null},{"q":"Quan sát sơ đồ chuỗi phản ứng phân hạch dây chuyền hình bên. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Hai hạt nhân sản phẩm phân hạch (như Ba và Kr) là các hạt nhân hoàn toàn bền vững và không có tính phóng xạ.","Neutron kích hoạt ban đầu phải là neutron chậm để hạt nhân ²³⁵U dễ hấp thụ.","Mỗi lần phân hạch giải phóng trung bình 2 đến 3 neutron mới.","Nếu không có biện pháp hấp thụ bớt neutron thì số lượng phân hạch sẽ tăng theo cấp số nhân dẫn đến vụ nổ hạt nhân."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Cần neutron chậm (nhiệt).<br>• <b>Ý b: ĐÚNG.</b> Số neutron trung bình sinh ra là 2,5 hạt.<br>• <b>Ý c: ĐÚNG.</b> Đây là nguyên lí của bom nguyên tử (<span class=\"math-sym\">k > 1</span>).<br>• <b>Ý d: SAI.</b> Các mảnh phân hạch thường thừa neutron và là các đồng vị phóng xạ phát ra tia beta và gamma (chất thải phóng xạ).","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <radialGradient id=\"u235\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </radialGradient>\n    <radialGradient id=\"fissionProd\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#06b6d4\"/>\n      <stop offset=\"100%\" stop-color=\"#0e7490\"/>\n    </radialGradient>\n    <radialGradient id=\"neutronG\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#e2e8f0\"/>\n      <stop offset=\"100%\" stop-color=\"#64748b\"/>\n    </radialGradient>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">SƠ ĐỒ PHẢN ỨNG PHÂN HẠCH DÂY CHUYỀN (URANI ²³⁵U)</text>\n\n  <!-- Neutron ban đầu bắn vào -->\n  <circle cx=\"45\" cy=\"140\" r=\"8\" fill=\"url(#neutronG)\"/>\n  <text x=\"45\" y=\"144\" fill=\"#0f172a\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n  <line x1=\"55\" y1=\"140\" x2=\"105\" y2=\"140\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n\n  <!-- Hạt nhân U-235 thế hệ 1 -->\n  <circle cx=\"135\" cy=\"140\" r=\"26\" fill=\"url(#u235)\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n  <text x=\"135\" y=\"145\" fill=\"#f8fafc\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">²³⁵U</text>\n\n  <!-- Hai mảnh phân hạch thế hệ 1 -->\n  <line x1=\"155\" y1=\"125\" x2=\"210\" y2=\"90\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <circle cx=\"230\" cy=\"80\" r=\"18\" fill=\"url(#fissionProd)\"/>\n  <text x=\"230\" y=\"85\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Ba</text>\n\n  <line x1=\"155\" y1=\"155\" x2=\"210\" y2=\"190\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  <circle cx=\"230\" cy=\"200\" r=\"18\" fill=\"url(#fissionProd)\"/>\n  <text x=\"230\" y=\"205\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Kr</text>\n\n  <!-- 3 neutron thứ cấp phóng ra -->\n  <line x1=\"160\" y1=\"135\" x2=\"310\" y2=\"115\" stroke=\"#facc15\" stroke-width=\"1.8\" stroke-dasharray=\"4,2\"/>\n  <circle cx=\"315\" cy=\"115\" r=\"7\" fill=\"url(#neutronG)\"/>\n  <text x=\"315\" y=\"118\" fill=\"#0f172a\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <line x1=\"160\" y1=\"140\" x2=\"310\" y2=\"140\" stroke=\"#facc15\" stroke-width=\"1.8\" stroke-dasharray=\"4,2\"/>\n  <circle cx=\"315\" cy=\"140\" r=\"7\" fill=\"url(#neutronG)\"/>\n  <text x=\"315\" y=\"143\" fill=\"#0f172a\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <line x1=\"160\" y1=\"145\" x2=\"310\" y2=\"165\" stroke=\"#facc15\" stroke-width=\"1.8\" stroke-dasharray=\"4,2\"/>\n  <circle cx=\"315\" cy=\"165\" r=\"7\" fill=\"url(#neutronG)\"/>\n  <text x=\"315\" y=\"168\" fill=\"#0f172a\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">n</text>\n\n  <!-- Hạt nhân U-235 thế hệ 2 tiếp tục bị kích hoạt -->\n  <circle cx=\"410\" cy=\"100\" r=\"22\" fill=\"url(#u235)\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <text x=\"410\" y=\"104\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">²³⁵U</text>\n\n  <circle cx=\"410\" cy=\"180\" r=\"22\" fill=\"url(#u235)\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <text x=\"410\" y=\"184\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">²³⁵U</text>\n\n  <!-- Chú thích chân -->\n  <rect x=\"70\" y=\"235\" width=\"400\" height=\"35\" rx=\"6\" fill=\"rgba(30,41,59,0.85)\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <text x=\"270\" y=\"257\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Hệ số nhân neutron: k = 1 (Lò phản ứng hạt nhân) • k &gt; 1 (Vụ nổ hạt nhân)</text>\n</svg>"},{"q":"Đồng vị phóng xạ Co-60 (Coban-60) được ứng dụng rộng rãi trong y tế chủ yếu để:","opts":["Xạ trị tiêu diệt tế bào ung thư bằng chùm tia gamma.","Chụp ảnh cắt lớp phổi bằng sóng siêu âm.","Làm nguồn phát quang cho đèn tín hiệu giao thông.","Khử trùng nguồn nước sinh hoạt bằng nhiệt độ cao."],"ans":0,"exp":"• Đồng vị <b>⁶⁰₂₇Co</b> phát ra tia gamma năng lượng cao dùng trong máy xạ trị điều trị ung thư.","svgGraph":null}],"25":[{"q":"Tỉ số giữa số hạt nhân con tạo thành N<sub>con</sub> và số hạt nhân mẹ còn lại N<sub>m</sub>ẹ tại thời điểm t trong một phân rã phóng xạ tuân theo hệ thức:","opts":["<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 2<sup><span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup> - 1.","<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 2<sup>-<span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup>.","<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 1 - 2<sup>-<span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup>.","<span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>mẹ</sub></span></span> = 2<sup><span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup> + 1."],"ans":0,"exp":"• Số hạt con tạo thành bằng số hạt mẹ đã phân rã: <span class=\"math-sym\">N</span><sub>con</sub> = <span class=\"math-sym\">ΔN = N</span><sub>0</sub>(1 - <span class=\"math-sym\">2⁻ᵗ/ᵀ</span>).<br>• Số hạt mẹ còn lại: <span class=\"math-sym\">N</span><sub>mẹ</sub> = <span class=\"math-sym\">N</span><sub>0</sub> · <span class=\"math-sym\">2⁻ᵗ/ᵀ</span>.<br>• Tỉ số: <span class=\"fraction\"><span class=\"numerator\">N<sub>con</sub></span><span class=\"denominator\">N<sub>m</sub>ẹ</span></span> = <span class=\"fraction\"><span class=\"numerator\">1 - 2⁻ᵗ/ᵀ</span><span class=\"denominator\">2⁻ᵗ/ᵀ</span></span> = <b>2ᵗ/ᵀ - 1</b>.","svgGraph":null},{"q":"Tại thời điểm t = 2T (sau 2 chu kỳ bán rã), tỉ số giữa số hạt nhân con tạo thành và số hạt nhân mẹ còn lại là:","opts":["3.","2.","4.","<span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">3</span></span>."],"ans":0,"exp":"• Áp dụng công thức: <span class=\"math-sym\">N</span><sub>con</sub> / <span class=\"math-sym\">N</span><sub>mẹ</sub> = <span class=\"math-sym\">2² - 1 = 4 - 1</span> = <b>3</b> (số hạt con gấp 3 lần số hạt mẹ).","svgGraph":null},{"q":"Phương pháp 'nguyên tử đánh dấu' (radioactive tracer) ứng dụng phổ biến trong y tế chẩn đoán và khảo sát nông nghiệp dựa trên nguyên lí vật lí nào sau đây?","opts":["Đưa lượng nhỏ đồng vị phóng xạ vào hệ thống và dùng thiết bị dò bức xạ theo dõi đường đi và sự tích tụ của nguyên tố đó.","Chiếu chùm tia gamma cường độ mạnh để biến đổi toàn bộ cấu trúc di truyền của sinh vật.","Kích thích phản ứng nhiệt hạch mini bên trong các cơ quan nội tạng để tiêu diệt mầm bệnh.","Đo vận tốc truyền sóng ánh sáng khả kiến qua tế bào sinh học để xác định nồng độ khoáng chất."],"ans":0,"exp":"• <b>Kĩ thuật nguyên tử đánh dấu:</b> Đồng vị phóng xạ có tính chất hóa học giống hệt đồng vị bền của cùng nguyên tố nên tham gia vào các quá trình sinh hóa tự nhiên của cơ thể hoặc hệ thống ống dẫn.<br>• Trong quá trình di chuyển, chúng liên tục phát ra tia bức xạ (như tia γ). Thiết bị dò bức xạ bên ngoài có thể theo dõi chính xác dòng chảy của máu, phát hiện các vị trí tắc mạch, đánh giá chức năng tuyến giáp (dùng ¹³¹I), hoặc phát hiện các điểm rò rỉ ngầm dưới lòng đất.","svgGraph":null},{"q":"Xét các bài toán cân bằng và bảo toàn trong phản ứng hạt nhân. Mỗi khẳng định sau là Đúng hay Sai? Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Nếu một hạt nhân mẹ đứng yên phóng xạ tạo thành hai hạt mới thì hai hạt sinh ra sẽ chuyển động cùng chiều với cùng độ lớn động lượng.","Trong phản ứng hạt nhân tỏa năng lượng, tổng động năng của các hạt sinh ra sau phản ứng luôn lớn hơn tổng động năng của các hạt ban đầu trước phản ứng.","Trong phản ứng hạt nhân thu năng lượng, tổng khối lượng nghỉ của các hạt sau phản ứng lớn hơn tổng khối lượng nghỉ trước phản ứng.","Định luật phóng xạ là định luật mang tính thống kê, chỉ nghiệm đúng khi xét số lượng rất lớn các nguyên tử hạt nhân."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Năng lượng tỏa ra chuyển thành động năng hạt sản phẩm: <span class=\"math-sym\">K</span><sub>sau</sub> - <span class=\"math-sym\">K</span><sub>trước</sub> = Δ<span class=\"math-sym\">E > 0</span>.<br>• <b>Ý b: SAI.</b> Vì ban đầu đứng yên nên <span class=\"math-sym\">p<sub>m</sub>ẹ = 0 ⇒ p₁ + p₂ = 0 ⇒ p₁ = -p₂</span> (hai hạt phải chuyển động <b>ngược chiều nhau</b>).<br>• <b>Ý c: ĐÚNG.</b> Thu năng lượng thì khối lượng nghỉ tăng lên: <span class=\"math-sym\">m</span><sub>sau</sub> > <span class=\"math-sym\">m</span><sub>trước</sub>.<br>• <b>Ý d: ĐÚNG.</b> Bản chất ngẫu nhiên thống kê.","svgGraph":null},{"q":"Hãy ghép dạng bài toán hạt nhân ở Cột A với phương trình cơ sở tương ứng ở Cột B:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT VẬT LÍ</b>?","opts":["Năng lượng phản ứng hạt nhân theo độ hụt khối ➔ p₁ = -p₂ (véc-tơ động lượng đối nhau)","Năng lượng phản ứng hạt nhân theo độ hụt khối ➔ A₁ + A₂ = A₃ + A₄","Tỉ số hạt con và hạt mẹ ➔ p₁ = -p₂ (véc-tơ động lượng đối nhau)","Bảo toàn động lượng khi hạt nhân mẹ đứng yên ➔ A₁ + A₂ = A₃ + A₄"],"ans":0,"exp":"• 1 ghép với C (Năng lượng theo độ hụt khối sau - trước).<br>• 2 ghép với D (Tỉ số con / mẹ).<br>• 3 ghép với A (Bảo toàn động lượng đứng yên).<br>• 4 ghép với B (Bảo toàn số khối A).","svgGraph":null},{"q":"Chọn cụm từ thích hợp nhất để hoàn thiện nhận định vật lí sau:<br><i>\"Một hạt nhân mẹ ban đầu đứng yên phóng xạ hạt alpha. Theo định luật bảo toàn động lượng, hạt nhân con và hạt alpha sẽ bay ra theo hai hướng [0]. Tỉ số động năng của hạt alpha so với hạt nhân con [1] với tỉ số khối lượng của chúng, do đó hạt alpha nhẹ hơn sẽ nhận phần lớn [2] của phản ứng.\"</i>","opts":["ngược chiều nhau — tỉ lệ nghịch","không đổi","tỉ lệ thuận — khối lượng","tỉ lệ nghịch — ngược chiều nhau"],"ans":0,"exp":"• Hai hạt bay <b>ngược chiều nhau</b>; động lượng bằng nhau <span class=\"math-sym\">p_α = p<sub>c</sub> ⇒ K = p² / 2m</span> tỉ lệ <b>nghịch</b> với khối lượng; hạt α nhẹ hơn chiếm hầu hết <b>động năng</b>.","svgGraph":null},{"q":"Một hạt nhân ²¹⁰₈₄Po đứng yên phân rã alpha thành hạt nhân chì ²⁰⁶₈₂Pb. Cho khối lượng các hạt xấp xỉ bằng số khối: m_α = 4 u; m<sub>Pb</sub> = 206 u. Phản ứng tỏa ra năng lượng ΔE = 5,4 MeV. Động năng của hạt alpha sinh ra là:","opts":["5,3 MeV.","5,1 MeV.","4,8 MeV.","2,7 MeV."],"ans":0,"exp":"• Bảo toàn động lượng: <span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">K_α</span><span class=\"denominator\">K<sub>Pb</sub></span></span> = <span class=\"fraction\"><span class=\"numerator\">m<sub>Pb</sub></span><span class=\"denominator\">m_α</span></span></span> = <span class=\"fraction\"><span class=\"numerator\">206</span><span class=\"denominator\">4</span></span> = 51,5.<br>• <span class=\"math-sym\">K_α = ΔE</span> × <span class=\"fraction\"><span class=\"numerator\">m<sub>Pb</sub></span><span class=\"denominator\">m<sub>Pb</sub> + m_α</span></span> = 5,4 × (<span class=\"fraction\"><span class=\"numerator\">206</span><span class=\"denominator\">210</span></span>) ≈ <b>5,3 MeV</b>.","svgGraph":null},{"q":"Các nhà địa chất và thiên văn học xác định tuổi của các mẫu đất đá trên Mặt Trăng do tàu Apollo mang về là khoảng 4,5 tỉ năm dựa trên phương pháp định tuổi bằng tỉ số phóng xạ nào?","opts":["Tỉ số giữa số hạt chì con ²⁰⁶₈₂Pb tạo thành và số hạt urani mẹ ²³⁸₉₂U còn lại trong mẫu đá.","Tỉ số giữa đồng vị carbon phóng xạ ¹⁴₆C và đồng vị carbon bền ¹²₆C.","Tỉ số giữa lượng khí heli và lượng khí hydrogen thoát ra khi nung chảy mẫu đá.","Tỉ số giữa khối lượng của mẫu đá so với khối lượng toàn bộ vỏ Mặt Trăng."],"ans":0,"exp":"• <b>Định tuổi địa chất U - Pb:</b> Chuỗi phân rã của đồng vị ²³⁸₉₂U chuyển hóa thành đồng vị bền ²⁰⁶₈₂Pb có chu kì bán rã rất lớn T ≈ 4,47 · 10⁹ năm (xấp xỉ tuổi của Trái Đất và hệ Mặt Trời).<br>• Tỉ số số hạt: <span class=\"fraction\"><span class=\"numerator\">N<sub>Pb</sub></span><span class=\"denominator\">N<sub>U</sub></span></span> = 2<sup><span class=\"fraction\" style=\"font-size:0.75em;\"><span class=\"numerator\">t</span><span class=\"denominator\">T</span></span></sup> - 1. Bằng cách đo tỉ số này trong các tinh thể zircon của mẫu đá, các nhà khoa học tính chính xác tuổi t của đá Mặt Trăng là khoảng 4,5 tỉ năm (trong khi phương pháp ¹⁴C chỉ đo được cổ vật dưới 50.000 năm do T<sub>C14</sub> ≈ 5730 năm).","svgGraph":null},{"q":"Quan sát đồ thị biến thiên của số hạt mẹ N(t) và số hạt con N<sub>con</sub>(t) theo thời gian hình bên. Đánh giá tính Đúng/Sai của các mệnh đề sau: Trong các nhận định sau, nhận định nào là <b>SAI</b>?","opts":["Độ dốc của đường tăng trưởng số hạt con ngày càng tăng dần theo thời gian.","Tại thời điểm t = T (giao điểm của hai đường cong), số hạt nhân mẹ còn lại đúng bằng số hạt nhân con tạo thành.","Tổng số hạt nhân mẹ còn lại và số hạt nhân con tạo thành ở bất kì thời điểm nào luôn bằng số hạt nhân mẹ ban đầu N₀.","Sau thời gian t = 3T, số hạt con tạo thành chiếm 87,5% tổng số hạt ban đầu."],"ans":0,"exp":"• <b>Ý a: ĐÚNG.</b> Tại t = T thì <span class=\"math-sym\">N<sub>m</sub>ẹ = N<sub>con</sub> = N₀/2</span>.<br>• <b>Ý b: ĐÚNG.</b> Định luật bảo toàn: mỗi hạt mẹ phân rã sinh ra 1 hạt con ⇒ <span class=\"math-sym\">N<sub>m</sub>ẹ(t) + N<sub>con</sub>(t) = N₀</span>.<br>• <b>Ý c: ĐÚNG.</b> Sau 3T hạt mẹ còn <span class=\"fraction\"><span class=\"numerator\">1</span><span class=\"denominator\">8</span></span> = 12,5% ⇒ hạt con chiếm 87,5%.<br>• <b>Ý d: SAI.</b> Số hạt mẹ giảm dần nên tốc độ sinh hạt con (<span class=\"math-sym\"><span class=\"fraction\"><span class=\"numerator\">dN</span><span class=\"denominator\">dt</span></span></span>) giảm dần theo thời gian (đường cong thoải dần).","svgGraph":"<svg viewBox=\"0 0 540 280\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arr25\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\"/>\n    </marker>\n  </defs>\n  <rect width=\"540\" height=\"280\" rx=\"14\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"270\" y=\"26\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">ĐỒ THỊ SỰ BIẾN THIÊN SỐ HẠT MẸ N(t) &amp; SỐ HẠT CON Ncon(t)</text>\n\n  <!-- Trục tọa độ -->\n  <line x1=\"60\" y1=\"230\" x2=\"490\" y2=\"230\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr25)\"/>\n  <line x1=\"60\" y1=\"230\" x2=\"60\" y2=\"35\" stroke=\"#94a3b8\" stroke-width=\"2\" marker-end=\"url(#arr25)\"/>\n  <text x=\"475\" y=\"250\" fill=\"#94a3b8\" font-size=\"13\">Thời gian t</text>\n  <text x=\"25\" y=\"45\" fill=\"#38bdf8\" font-size=\"12\">Số hạt</text>\n  <text x=\"45\" y=\"245\" fill=\"#94a3b8\" font-size=\"12\">0</text>\n\n  <!-- Mốc N0 -->\n  <line x1=\"60\" y1=\"60\" x2=\"470\" y2=\"60\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n  <text x=\"35\" y=\"65\" fill=\"#38bdf8\" font-size=\"13\" font-weight=\"bold\">N₀</text>\n\n  <!-- Mốc N0/2 -->\n  <line x1=\"60\" y1=\"145\" x2=\"470\" y2=\"145\" stroke=\"#475569\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n  <text x=\"20\" y=\"150\" fill=\"#cbd5e1\" font-size=\"12\">N₀/2</text>\n\n  <!-- Đường hạt mẹ N(t) màu đỏ: giảm dần -->\n  <path d=\"M 60,60 C 130,110 180,145 220,145 C 270,145 320,190 380,210 C 420,218 450,225 470,226\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"3\"/>\n  <text x=\"410\" y=\"200\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">Hạt mẹ N(t)</text>\n\n  <!-- Đường hạt con N<tspan baseline-shift=\"sub\" font-size=\"70%\">con</tspan>(t) màu xanh: tăng dần -->\n  <path d=\"M 60,230 C 130,180 180,145 220,145 C 270,145 320,100 380,80 C 420,72 450,65 470,64\" fill=\"none\" stroke=\"#10b981\" stroke-width=\"3\"/>\n  <text x=\"410\" y=\"95\" fill=\"#10b981\" font-size=\"12\" font-weight=\"bold\">Hạt con Ncon(t)</text>\n\n  <!-- Điểm giao nhau tại t = T: N<tspan baseline-shift=\"sub\" font-size=\"70%\">me</tspan> = N<tspan baseline-shift=\"sub\" font-size=\"70%\">con</tspan> = N0 / 2 -->\n  <circle cx=\"220\" cy=\"145\" r=\"6\" fill=\"#fbbf24\"/>\n  <line x1=\"220\" y1=\"145\" x2=\"220\" y2=\"230\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n  <text x=\"215\" y=\"248\" fill=\"#fbbf24\" font-size=\"13\" font-weight=\"bold\">t = T</text>\n\n  <!-- Chú thích công thức -->\n  <text x=\"270\" y=\"268\" fill=\"#facc15\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\">Tại t = T: N<tspan baseline-shift=\"sub\" font-size=\"70%\">con</tspan> = N<tspan baseline-shift=\"sub\" font-size=\"70%\">mẹ</tspan> = N₀/2 • Tỉ số N<tspan baseline-shift=\"sub\" font-size=\"70%\">con</tspan> / N<tspan baseline-shift=\"sub\" font-size=\"70%\">mẹ</tspan> = 2^(t/T) - 1</text>\n</svg>"},{"q":"Trong dây chuyền sản xuất tự động các lá màng nhôm mỏng hoặc giấy công nghiệp, người ta đặt nguồn phát tia phóng xạ β ở một bên tấm màng và đầu dò bức xạ ở bên đối diện. Thiết bị này dùng để:","opts":["Tự động kiểm soát và điều chỉnh độ dày của màng thông qua mức độ suy giảm của chùm tia β khi đâm xuyên qua màng.","Khử trùng và tiệt trùng bề mặt tấm màng để chống nấm mốc và vi khuẩn bám dính.","Đốt nóng làm khô nhanh màng nhôm và giấy trong quá trình cán tốc độ cao.","Tích điện âm cho màng kim loại để các lớp màng tự động dính chặt vào nhau."],"ans":0,"exp":"• <b>Thiết bị đo độ dày bức xạ:</b> Tia β (các electron năng lượng cao) có khả năng đâm xuyên qua các màng vật chất mỏng và bị hấp thụ một phần.<br>• Độ suy giảm cường độ của chùm tia β phụ thuộc chặt chẽ vào độ dày của lớp vật liệu. Nếu màng bị dày hơn tiêu chuẩn, lượng tia β tới đầu dò giảm ⇒ hệ thống tự động điều khiển trục cán ép chặt lại. Ngược lại, nếu màng mỏng hơn, lượng tia tới tăng ⇒ nới lỏng trục cán. Thiết bị hoạt động liên tục không tiếp xúc và tự động hóa 100%.","svgGraph":null}]}};
if (typeof module !== "undefined") module.exports = ARENA_QUESTIONS;
